(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("polybius-3-e", [{"sp": "HDR", "t": "Ἱστορίαι (Εʹ–Ηʹ)"}, {"sp": "HDR", "t": "Βιβλίον Εʹ", "st": "5"}, {"sp": "N", "t": "τὸ μὲν οὖν κατὰ τὴν Ἀράτου τοῦ νεωτέρου στρατηγίαν ἔτος ἐτύγχανε διεληλυθὸς περὶ τὴν τῆς Πλειάδος ἐπιτολήν· οὕτως γὰρ ἦγε τοὺς χρόνους τότε τὸ τῶν Ἀχαιῶν ἔθνος. διόπερ οὗτος μὲν ἀπετίθετο τὴν ἀρχήν, Ἐπήρατος δὲ παρελάμβανε τὴν τῶν Ἀχαιῶν ἡγεμονίαν· Αἰτωλῶν δὲ Δωρίμαχος ἐστρατήγει. κατὰ δὲ τοὺς αὐτοὺς καιροὺς ἀρχομένης τῆς θερείας Ἀννίβας μὲν ἐκφανῶς ἤδη τὸν πρὸς Ῥωμαίους πόλεμον ἀνειληφώς, ὁρμήσας ἐκ Καινῆς πόλεως καὶ διαβὰς τὸν Ἴβηρα ποταμὸν ἐνήρχετο τῆς ἐπιβολῆς καὶ πορείας τῆς εἰς Ἰταλίαν· Ῥωμαῖοι δὲ Τεβέριον μὲν Σεμπρώνιον εἰς Λιβύην μετὰ δυνάμεως, Πόπλιον δὲ Κορνήλιον εἰς Ἰβηρίαν ἐξαπέστελλον· Ἀντίοχος δὲ καὶ Πτολεμαῖος, ἀπεγνωκότες τὰς πρεσβείας καὶ τὸ λόγῳ διεξάγειν τὴν ὑπὲρ Κοίλης Συρίας ἀμφισβήτησιν, ἐνήρχοντο πολεμεῖν ἀλλήλοις. ὁ δὲ βασιλεὺς Φίλιππος, ἐνδεὴς ὢν σίτου καὶ χρημάτων εἰς τὰς δυνάμεις, συνῆγε τοὺς Ἀχαιοὺς διὰ τῶν ἀρχόντων εἰς ἐκκλησίαν. ἁθροισθέντος δὲ τοῦ πλήθους εἰς Αἴγιον κατὰ τοὺς νόμους, ὁρῶν τοὺς μὲν περὶ Ἄρατον ἐθελοκακοῦντας διὰ τὴν περὶ τὰς ἀρχαιρεσίας γεγενημένην εἰς αὐτοὺς τῶν περὶ τὸν Ἀπελλῆν κακοπραγμοσύνην, τὸν δ’ Ἐπήρατον ἄπρακτον ὄντα τῇ φύσει καὶ καταγινωσκόμενον ὑπὸ πάντων, συλλογισάμενος ἐκ τῶν προειρημένων τὴν ἄγνοιαν τῶν περὶ τὸν Ἀπελλῆν καὶ Λεόντιον, ἔκρινεν αὖθις ἀντέχεσθαι τῶν περὶ τὸν Ἄρατον. πείσας οὖν τοὺς ἄρχοντας μεταγαγεῖν τὴν ἐκκλησίαν εἰς Σικυῶνα, λαβὼν τόν τε πρεσβύτερον καὶ τὸν νεώτερον Ἄρατον εἰς τὰς χεῖρας, καὶ πάντων τῶν γεγονότων ἀναθεὶς τὴν αἰτίαν ἐπὶ τὸν Ἀπελλῆν, παρεκάλει μένειν αὐτοὺς ἐπὶ τῆς ἐξ ἀρχῆς αἱρέσεως. τῶν δὲ συγκαταθεμένων ἑτοίμως, εἰσελθὼν εἰς τοὺς Ἀχαιοὺς καὶ χρησάμενος συνεργοῖς τοῖς προειρημένοις, πάντα κατέπραξε τὰ πρὸς τὴν ἐπιβολήν. πεντήκοντα μὲν γὰρ ἔδοξε τάλαντα τοῖς Ἀχαιοῖς εἰς τὴν πρώτην ἀναζυγὴν αὐτῷ δοῦσι παραχρῆμα τριμήνου μισθοδοτῆσαι τὴν δύναμιν καὶ σίτου προσθεῖναι μυριάδας· τὸ δὲ λοιπόν, ἕως ἂν παρὼν ἐν Πελοποννήσῳ συμπολεμῇ, τάλαντα λαμβάνειν ἑκάστου μηνὸς παρὰ τῶν Ἀχαιῶν ἑπτακαίδεκα.", "st": "5.1"}, {"sp": "N", "t": "δοξάντων δὲ τούτων, οἱ μὲν Ἀχαιοὶ διελύθησαν ἐπὶ τὰς πόλεις· τῷ δὲ βασιλεῖ βουλευομένῳ μετὰ τῶν φίλων, ἐπειδὴ συνῆλθον αἱ δυνάμεις ἐκ τῆς παραχειμασίας, ἔδοξε χρῆσθαι κατὰ θάλατταν τῷ πολέμῳ. οὕτως γὰρ ἐπέπειστο μόνως αὐτὸς μὲν δυνήσεσθαι ταχέως πανταχόθεν ἐπιφαίνεσθαι τοῖς πολεμίοις, τοὺς δ’ ὑπεναντίους ἥκιστ’ ἂν δύνασθαι παραβοηθεῖν ἀλλήλοις, ἅτε διεσπασμένους μὲν ταῖς χώραις, δεδιότας δ’ ἑκάστους περὶ σφῶν διὰ τὴν ἀδηλότητα καὶ τὸ τάχος τῆς κατὰ θάλατταν παρουσίας τῶν πολεμίων· πρὸς γὰρ Αἰτωλοὺς καὶ Λακεδαιμονίους ἔτι δ’ Ἠλείους ὁ πόλεμος ἦν αὐτῷ. κριθέντων δὲ τούτων, ἥθροιζε τάς τε τῶν Ἀχαιῶν νῆας καὶ τὰς σφετέρας εἰς τὸ Λέχαιον, καὶ συνεχεῖς ποιούμενος ἀναπείρας ἐγύμναζε τοὺς φαλαγγίτας καὶ συνείθιζε ταῖς εἰρεσίαις, προθύμως αὐτῷ πρὸς τὸ παραγγελλόμενον συνυπακουόντων τῶν Μακεδόνων· πρός τε γὰρ τοὺς ἐν γῇ κινδύνους ἐκ παρατάξεως γενναιότατοι πρός τε τὰς κατὰ θάλατταν ἐκ τοῦ καιροῦ χρείας ἑτοιμότατοι, λειτουργοί γε μὴν περὶ τὰς ταφρείας καὶ χαρακοποιίας καὶ πᾶσαν τὴν τοιαύτην ταλαιπωρίαν φιλοπονώτατοί τινες, οἵους Ἡσίοδος παρεισάγει τοὺς Αἰακίδας, πολέμῳ κεχαρηότας ἠΰτε δαιτί. ὁ μὲν οὖν βασιλεὺς καὶ τὸ τῶν Μακεδόνων πλῆθος ἐν τῷ Κορίνθῳ διέτριβε, περὶ τὴν κατὰ θάλατταν ἄσκησιν καὶ παρασκευὴν γινόμενος· ὁ δ’ Ἀπελλῆς, οὔτ’ ἐπικρατεῖν τοῦ Φιλίππου δυνάμενος οὔτε φέρειν τὴν ἐλάττωσιν παρορώμενος, ποιεῖται συνωμοσίαν πρὸς τοὺς περὶ Λεόντιον καὶ Μεγαλέαν, ὥστ’ ἐκείνους μὲν συμπαρόντας ἐπ’ αὐτῶν τῶν καιρῶν ἐθελοκακεῖν καὶ λυμαίνεσθαι τὰς τοῦ βασιλέως χρείας, αὐτὸς δὲ χωρισθεὶς εἰς Χαλκίδα φροντίζειν ἵνα μηδαμόθεν αὐτῷ χορηγία παραγίνηται πρὸς τὰς ἐπιβολάς. οὗτος μὲν οὖν τοιαῦτα συνθέμενος καὶ κακοτροπευσάμενος πρὸς τοὺς προειρημένους ἀπῆρεν εἰς τὴν Χαλκίδα; σκήψεις τινὰς εὐλόγους πρὸς τὸν βασιλέα πορισάμενος· κἀκεῖ διατρίβων οὕτως βεβαίως ἐτήρει τὰ κατὰ τοὺς ὅρκους, πάντων αὐτῷ πειθαρχούντων κατὰ τὴν προγεγενημένην πίστιν, ὥστε τὸ τελευταῖον ἀναγκασθῆναι τὸν βασιλέα δι’ ἀπορίαν ἐνέχυρα τιθέντα τῶν πρὸς τὴν χρείαν ἀργυρωμάτων ἀπὸ τούτων ποιεῖσθαι τὴν διαγωγήν. ἡθροισμένων δὲ τῶν πλοίων, καὶ τῶν Μακεδόνων ἤδη ταῖς εἰρεσίαις κατηρτισμένων, σιτομετρήσας καὶ μισθοδοτήσας ὁ βασιλεὺς τὴν δύναμιν ἀνήχθη, καὶ κατῆρε δευτεραῖος εἰς Πάτρας, ἔχων Μακεδόνας μὲν ἑξακισχιλίους, μισθοφόρους δὲ χιλίους καὶ διακοσίους.", "st": "5.2"}, {"sp": "N", "t": "κατὰ δὲ τοὺς αὐτοὺς καιροὺς Δωρίμαχος ὁ τῶν Αἰτωλῶν στρατηγὸς Ἀγέλαον καὶ Σκόπαν ἐξαπέστειλε τοῖς Ἠλείοις μετὰ Νεοκρήτων πεντακοσίων· οἱ δ’ Ἠλεῖοι δεδιότες μὴ τὴν Κυλλήνην ὁ Φίλιππος ἐπιβάληται πολιορκεῖν, στρατιώτας τε μισθοφόρους συνήθροιζον καὶ τοὺς πολιτικοὺς ἡτοίμαζον, ὠχυροῦντο δὲ καὶ τὴν Κυλλήνην ἐπιμελῶς. εἰς ἃ βλέπων ὁ Φίλιππος, τούς τε τῶν Ἀχαιῶν μισθοφόρους καὶ τῶν παρ’ αὑτῷ Κρητῶν καὶ τῶν Γαλατικῶν ἱππέων τινάς, σὺν δὲ τούτοις τῶν ἐξ Ἀχαΐας ἐπιλέκτων εἰς δισχιλίους πεζοὺς ἁθροίσας, ἐν τῇ τῶν Δυμαίων πόλει κατέλειπεν, ἅμα μὲν ἐφεδρείας ἔχοντας, ἅμα δὲ προφυλακῆς τάξιν πρὸς τὸν ἀπὸ τῆς Ἠλείας φόβον. αὐτὸς δ’, ἔτι πρότερον γεγραφὼς τοῖς Μεσσηνίοις καὶ τοῖς Ἠπειρώταις, ἔτι δὲ τοῖς Ἀκαρνᾶσι καὶ Σκερδιλαΐδᾳ, πληροῦν ἑκάστοις τὰ παρ’ αὑτοῖς πλοῖα καὶ συναντᾶν εἰς Κεφαλληνίαν, ἀναχθεὶς ἐκ τῶν Πατρῶν κατὰ τὴν σύνταξιν ἔπλει, καὶ προσέσχε τῆς Κεφαλληνίας κατὰ Πρόννους. ὁρῶν δὲ τό τε πολισμάτιον [τοὺς Πρόννους] δυσπολιόρκητον ὂν καὶ τὴν χώραν στενήν, παρέπλει τῷ στόλῳ, καὶ καθωρμίσθη πρὸς τὴν τῶν Παλαιῶν πόλιν. συνιδὼν δὲ ταύτην τὴν χώραν γέμουσαν σίτου καὶ δυναμένην τρέφειν στρατόπεδον, τὴν μὲν δύναμιν ἐκβιβάσας προσεστρατοπέδευσε τῇ πόλει, τὰς δὲ ναῦς συνορμίσας τάφρῳ καὶ χάρακι περιέλαβε, τοὺς δὲ Μακεδόνας ἐφῆκε σιτολογεῖν. αὐτὸς δὲ περιῄει τὴν πόλιν, ἐπισκοπῶν πῶς δυνατὸν εἴη προσάγειν ἔργα τῷ τείχει καὶ μηχανάς, βουλόμενος ἅμα μὲν προσδέξασθαι τοὺς συμμάχους, ἅμα δὲ τὴν πόλιν ἐξελεῖν, ἵνα πρῶτον μὲν Αἰτωλῶν παρέληται τὴν ἀναγκαιοτάτην ὑπηρεσίαν — ταῖς γὰρ τῶν Κεφαλλήνων ναυσὶ χρώμενοι τάς τ’ εἰς Πελοπόννησον ἐποιοῦντο διαβάσεις καὶ τὰς Ἠπειρωτῶν ἔτι δ’ Ἀκαρνάνων ἐπόρθουν παραλίας — δεύτερον δ’ ἵνα παρασκευάσῃ μὲν αὑτῷ, παρασκευάσῃ δὲ τοῖς συμμάχοις ὁρμητήριον εὐφυὲς κατὰ τῆς τῶν πολεμίων χώρας. ἡ γὰρ Κεφαλληνία κεῖται μὲν κατὰ τὸν Κορινθιακὸν κόλπον ὡς εἰς τὸ Σικελικὸν ἀνατείνουσα πέλαγος, ἐπίκειται δὲ τῆς μὲν Πελοποννήσου τοῖς πρὸς ἄρκτον καὶ πρὸς ἑσπέραν μέρεσι κεκλιμένοις καὶ μάλιστα τῇ τῶν Ἠλείων χώρᾳ, τῆς δ’ Ἠπείρου καὶ τῆς Αἰτωλίας ἔτι δὲ τῆς Ἀκαρνανίας τοῖς πρὸς μεσημβρίαν καὶ πρὸς τὰς δύσεις μέρεσιν ἐστραμμένοις.", "st": "5.3"}, {"sp": "N", "t": "διὸ καὶ πρός τε τὴν συναγωγὴν τῶν συμμάχων εὐφυῶς ἐχούσης καὶ κατὰ τῆς τῶν πολεμίων καὶ πρὸ τῆς τῶν φίλων χώρας εὐκαίρως κειμένης, ἔσπευδε χειρωσάμενος ὑφ’ αὑτὸν ποιήσασθαι τὴν νῆσον. συνθεωρῶν δὲ τὰ μὲν ἄλλα πάντα μέρη τῆς πόλεως τὰ μὲν θαλάττῃ, τὰ δὲ κρημνοῖς περιεχόμενα, βραχὺν δέ τινα τόπον ἐπίπεδον αὐτῆς ὑπάρχοντα, τὸ πρὸς τὴν Ζάκυνθον ἐστραμμένον, τῇδε διενοεῖτο προσάγειν ἔργα καὶ τῇδε τὴν ὅλην συνίστασθαι πολιορκίαν. ὁ μὲν οὖν βασιλεὺς περὶ ταῦτα καὶ πρὸς τούτοις ἦν. κατὰ δὲ τὸν καιρὸν τοῦτον πεντεκαίδεκα μὲν ἧκον λέμβοι παρὰ Σκερδιλαΐδου — τοὺς γὰρ πλείστους ἐκωλύθη πέμψαι διὰ τὰς γενομένας ἐπιβουλὰς καὶ ταραχὰς περὶ τοὺς κατὰ τὴν Ἰλλυρίδα πολιδυνάστας — ἧκον δὲ καὶ παρ’ Ἠπειρωτῶν καὶ παρ’ Ἀκαρνάνων ἔτι δὲ Μεσσηνίων οἱ διαταχθέντες σύμμαχοι· τῆς γὰρ τῶν Φιαλέων πόλεως ἐξαιρεθείσης ἀπροφασίστως τὸ λοιπὸν ἤδη μετεῖχον Μεσσήνιοι τοῦ πολέμου. τῶν δὲ πρὸς τὴν πολιορκίαν ἡτοιμασμένων, διαθεὶς τὰ βέλη καὶ τοὺς πετροβόλους κατὰ τοὺς ἁρμόζοντας τόπους πρὸς τὸ κωλύειν τοὺς ἀμυνομένους, παρακαλέσας τοὺς Μακεδόνας ὁ βασιλεὺς προσῆγε τὰς μηχανὰς τοῖς τείχεσι καὶ διὰ τούτων τοῖς ὀρύγμασιν ἐνεχείρει. ταχὺ δὲ τοῦ τείχους ἐπὶ δύο πλέθρα κρεμασθέντος διὰ τὴν ἐν τοῖς ἔργοις προθυμίαν τῶν Μακεδόνων, ἐγγίσας τοῖς τείχεσιν ὁ βασιλεὺς παρῄνει τοῖς ἐν τῇ πόλει τίθεσθαι πρὸς αὑτὸν τὴν εἰρήνην. τῶν δὲ παρακουόντων, ἐμβαλὼν πῦρ τοῖς ἐρείσμασιν ὁμοῦ πᾶν τὸ διεστυλωμένον κατέβαλε τεῖχος. οὗ γενομένου, πρώτους ἐφῆκε τοὺς πελταστὰς τοὺς ὑπὸ Λεόντιον ταττομένους, σπειρηδὸν τάξας καὶ παραγγείλας βιάζεσθαι διὰ τοῦ πτώματος. οἱ δὲ περὶ τὸν Λεόντιον, τηροῦντες τὰ πρὸς τὸν Ἀπελλῆν συγκείμενα, τρὶς ἑξῆς τοὺς νεανίσκους ὑπερβάντας τὸ πτῶμα διέτρεψαν τοῦ μὴ τελεσιουργῆσαι τὴν κατάληψιν τῆς πόλεως· καὶ προδιεφθαρκότες μὲν τοὺς ἐπιφανεστάτους τῶν κατὰ μέρος ἡγεμόνων, ἐθελοκακοῦντες δὲ καὶ παρ’ ἕκαστον ἀποδειλιῶντες αὐτοί, τέλος ἐξέπεσον ἐκ τῆς πόλεως πολλὰς πληγὰς λαβόντες, καίπερ εὐχερῶς δυνάμενοι κρατῆσαι τῶν πολεμίων. ὁ δὲ βασιλεύς, ὁρῶν ἀποδειλιῶντας μὲν τοὺς ἡγεμόνας, τραυματίας δὲ καὶ πλείους γεγονότας τῶν Μακεδόνων, τῆς μὲν πολιορκίας ἀπέστη, περὶ δὲ τῶν ἑξῆς ἐβουλεύετο μετὰ τῶν φίλων.", "st": "5.4"}, {"sp": "N", "t": "κατὰ δὲ τοὺς αὐτοὺς καιροὺς Λυκοῦργος μὲν εἰς τὴν Μεσσηνίαν ἐξεστρατεύκει, Δωρίμαχος δὲ τοὺς ἡμίσεις ἔχων Αἰτωλῶν εἰς Θετταλίαν ἐπεποίητο τὴν ὁρμήν, ἀμφότεροι πεπεισμένοι τὸν Φίλιππον ἀποσπάσειν τῆς τῶν Παλαιέων πολιορκίας. ὑπὲρ ὧν ἧκον πρέσβεις πρὸς τὸν βασιλέα παρά τ’ Ἀκαρνάνων καὶ παρὰ Μεσσηνίων, οἱ μὲν παρὰ τῶν Ἀκαρνάνων παρακαλοῦντες αὐτὸν ἐμβαλεῖν εἰς τὴν τῶν Αἰτωλῶν χώραν καὶ τόν τε Δωρίμαχον ἀποστῆσαι τῆς εἰς τὴν Μακεδονίαν ὁρμῆς καὶ τὴν χώραν τῶν Αἰτωλῶν ἐπελθεῖν καὶ πορθῆσαι πᾶσαν ἀδεῶς, οἱ δὲ παρὰ τῶν Μεσσηνίων δεόμενοι σφίσι βοηθεῖν καὶ διδάσκοντες ὅτι τῶν ἐτησίων ἤδη στάσιν ἐχόντων δυνατόν ἐστι τὴν παρακομιδὴν ἐκ τῆς Κεφαλληνίας εἰς τὴν Μεσσηνίαν ἐν ἡμέρᾳ ποιήσασθαι μιᾷ· διόπερ οἱ περὶ Γόργον τὸν Μεσσήνιον αἰφνίδιον καὶ πραγματικὴν ἐσομένην συνίστασαν τὴν ἐπὶ τὸν Λυκοῦργον ἐπίθεσιν. οἱ δὲ περὶ τὸν Λεόντιον, τηροῦντες τὴν αὑτῶν ὑπόθεσιν, συνήργουν τοῖς περὶ τὸν Γόργον ἐκτενῶς, θεωροῦντες ὅτι συμβήσεται τὴν θερείαν εἰς τέλος ἄπρακτον γενέσθαι τῷ Φιλίππῳ. πλεῦσαι μὲν γὰρ εἰς τὴν Μεσσηνίαν ῥᾴδιον ἦν, ἀναπλεῦσαι δ’ ἐκεῖθεν τῶν ἐτησίων ἐπεχόντων ἀδύνατον· ἐξ οὗ δῆλον ἦν ὡς ὁ μὲν Φίλιππος ἐν τῇ Μεσσηνίᾳ μετὰ τῆς δυνάμεως συγκλεισθεὶς ἀναγκασθήσεται τὸ λοιπὸν μέρος τοῦ θέρους ἄπρακτος μένειν, οἱ δ’ Αἰτωλοὶ τὴν Θετταλίαν καὶ τὴν Ἤπειρον ἐπιπορευόμενοι κατασύρουσι καὶ πορθοῦσι πᾶσαν ἀδεῶς. οὗτοι μὲν οὖν λυμεωνευόμενοι ταῦτα καὶ τοιαῦτα συνεβούλευον. οἱ δὲ περὶ τὸν Ἄρατον συμπαρόντες τῆς ἐναντίας προέστασαν γνώμης. δεῖν γὰρ ἔφασαν εἰς τὴν Αἰτωλίαν ποιεῖσθαι τὸν πλοῦν καὶ τούτων ἔχεσθαι τῶν πραγμάτων· ἐξεστρατευκότων γὰρ τῶν Αἰτωλῶν μετὰ Δωριμάχου κάλλιστον εἶναι καιρὸν ἐπελθεῖν καὶ πορθῆσαι τὴν Αἰτωλίαν. ὁ δὲ βασιλεύς, τὰ μὲν ἀπιστῶν ἤδη τοῖς περὶ τὸν Λεόντιον ἐκ τῆς περὶ τὴν πολιορκίαν ἐθελοκακήσεως, συναισθανόμενος δὲ καὶ ἐκ τοῦ περὶ τὸν πλοῦν αὐτῶν διαβουλίου τὴν κακοπραγμοσύνην, ἔκρινε χρῆσθαι τοῖς πράγμασι κατὰ τὴν Ἀράτου γνώμην. διόπερ Ἐπηράτῳ μὲν ἔγραψε τῷ τῶν Ἀχαιῶν στρατηγῷ βοηθεῖν τοῖς Μεσσηνίοις, ἀναλαβόντι τοὺς Ἀχαιούς, αὐτὸς δ’ ἀναχθεὶς ἐκ τῆς Κεφαλληνίας παρῆν δευτεραῖος εἰς Λευκάδα μετὰ τοῦ στόλου νυκτός. εὐτρεπισάμενος δὲ τὰ περὶ τὸν Διόρυκτον, καὶ ταύτῃ διακομίσας τὰς ναῦς, ἐποιεῖτο τὸν ἀπόπλουν κατὰ τὸν Ἀμβρακικὸν καλούμενον κόλπον. ὁ δὲ προειρημένος κόλπος ἐπὶ πολὺ προτείνων ἐκ τοῦ Σικελικοῦ πελάγους εἰς τοὺς μεσογαίους ἀνήκει τόπους τῆς Αἰτωλίας, καθάπερ καὶ πρότερον ἡμῖν εἴρηται. διανύσας δὲ καὶ καθορμισθεὶς βραχὺ πρὸ ἡμέρας πρὸς τῇ καλουμένῃ Λιμναίᾳ, τοῖς μὲν στρατιώταις ἀριστοποιεῖσθαι παρήγγειλε καὶ τὸ πολὺ τῆς ἀποσκευῆς ἀποθεμένους εὐζώνους σφᾶς παρασκευάζειν πρὸς ἀναζυγήν, αὐτὸς δὲ τοὺς ὁδηγοὺς ἁθροίσας τά τε περὶ τοὺς τόπους καὶ τὰς παρακειμένας πόλεις ἐπυνθάνετο καὶ διηρεύνα.", "st": "5.5"}, {"sp": "N", "t": "κατὰ δὲ τὸν καιρὸν τοῦτον ἧκεν ἔχων Ἀριστόφαντος ὁ στρατηγὸς πανδημεὶ τοὺς Ἀκαρνᾶνας· πολλὰ γὰρ καὶ δεινὰ πεπονθότες ἐν τοῖς ἀνώτερον χρόνοις ὑπ’ Αἰτωλῶν ἐκθύμως εἶχον πρὸς τὸ κατὰ πάντα τρόπον ἀμύνασθαι καὶ βλάψαι τοὺς Αἰτωλούς. διόπερ ἀσμένως ἐπιλαβόμενοι τότε τῆς Μακεδόνων ἐπαρκείας, ἧκον ἐν τοῖς ὅπλοις, οὐ μόνον ὅσοις ὁ νόμος ἐπέταττε στρατεύειν, ἀλλὰ καὶ τῶν πρεσβυτέρων τινές. οὐκ ἐλάττω δὲ τούτων ὁρμὴν εἶχον Ἠπειρῶται διὰ τὰς παραπλησίους αἰτίας· διὰ δὲ τὸ μέγεθος τῆς χώρας καὶ διὰ τὸ τῆς παρουσίας αἰφνίδιον τῆς τοῦ Φιλίππου καθυστέρουν τῇ συναγωγῇ τῶν καιρῶν. τῶν δ’ Αἰτωλῶν τοὺς μὲν ἡμίσεις ἔχων Δωρίμαχος ἐπεποίητο τὴν ἔξοδον, καθάπερ εἶπον, τοὺς δ’ ἡμίσεις ἀπολελοίπει, νομίζων ἀξιόχρεων πρὸς τὰ παράδοξα ταύτην τὴν ἐφεδρείαν ὑπάρχειν τῶν τε πόλεων καὶ τῆς χώρας. ὁ δὲ βασιλεὺς ἀπολιπὼν φυλακὴν ἱκανὴν τῆς ἀποσκευῆς, τότε μὲν ἀναζεύξας ἐκ τῆς Λιμναίας δείλης καὶ προελθὼν ὡς ἑξήκοντα στάδια κατεστρατοπέδευσε. δειπνοποιησάμενος δὲ καὶ βραχὺ διαναπαύσας τὴν δύναμιν αὖθις ὥρμα, καὶ συνεχῶς νυκτοπορήσας ἧκε πρὸς τὸν Ἀχελῷον ποταμὸν ἄρτι τῆς ἡμέρας ἐπιφαινούσης, μεταξὺ Κωνώπης καὶ Στράτου, σπεύδων ἄφνω καὶ παραδόξως ἐπὶ τὸν ἐν τοῖς Θέρμοις τόπον ἐπιβαλεῖν.", "st": "5.6"}, {"sp": "N", "t": "οἱ δὲ περὶ τὸν Λεόντιον κατὰ δύο τρόπους ὁρῶντες τὸν μὲν Φίλιππον καθιξόμενον τῆς προθέσεως, τοὺς δ’ Αἰτωλοὺς ἀδυνατήσοντας τοῖς παροῦσι, καθ’ ἕνα μὲν ᾗ ταχεῖα καὶ παράδοξος ἡ τῶν Μακεδόνων ἐγεγόνει παρουσία, καθ’ ἕτερον δ’ ᾗ πρός γε τὸν ἐν τοῖς Θέρμοις τόπον οὐδέποτ’ ἂν ὑπολαβόντες Αἰτωλοὶ τολμῆσαι τὸν Φίλιππον οὕτω προχείρως αὑτὸν δοῦναι διὰ τὰς ὀχυρότητας τῶν τόπων ἔμελλον ἀπρονόητοι καὶ παντελῶς ἀπαράσκευοι ληφθήσεσθαι πρὸς τὸ συμβαῖνον· εἰς ἃ βλέποντες, καὶ τηροῦντες τὴν ἑαυτῶν πρόθεσιν, ᾤοντο δεῖν τὸν Φίλιππον περὶ τὸν Ἀχελῷον στρατοπεδεύσαντα προσαναπαῦσαι τὴν δύναμιν ἐκ τῆς νυκτοπορίας, σπουδάζοντες βραχεῖάν γε τοῖς Αἰτωλοῖς ἀναστροφὴν δοῦναι πρὸς τὴν βοήθειαν. οἱ δὲ περὶ τὸν Ἄρατον, θεωροῦντες τὸν μὲν καιρὸν ὀξὺν ὄντα τῆς ἐπιβολῆς, τοὺς δὲ περὶ τὸν Λεόντιον προδήλως ἐμποδίζοντας, διεμαρτύροντο τὸν Φίλιππον μὴ παριέναι τὸν καιρὸν μηδὲ καταμέλλειν. οἷς καὶ πεισθεὶς ὁ βασιλεύς, καὶ προσκόπτων ἤδη τοῖς περὶ τὸν Λεόντιον, ἐποιεῖτο τὴν πορείαν κατὰ τὸ συνεχές. διαβὰς δὲ τὸν Ἀχελῷον ποταμὸν προῆγε συντόνως ὡς ἐπὶ τὸν Θέρμον· ἅμα δὲ προάγων ἐδῄου καὶ κατέφθειρε τὴν χώραν. παρῄει δ’ ἐκ μὲν εὐωνύμων ἀπολιπὼν Στράτον, Ἀγρίνιον, Θεστιεῖς, ἐκ δὲ δεξιῶν Κωνώπην, Λυσιμάχειαν, Τριχώνιον, Φύταιον. ἀφικόμενος δὲ πρὸς πόλιν τὴν καλουμένην Μέταπαν, ἣ κεῖται μὲν ἐπ’ αὐτῆς τῆς Τριχωνίδος λίμνης καὶ τῶν παρὰ ταύτην στενῶν, ἀπέχει δὲ σχεδὸν ἑξήκοντα στάδια τοῦ προσαγορευομένου Θέρμου, ταύτην μὲν ἐκλιπόντων τῶν Αἰτωλῶν εἰσαγαγὼν πεντακοσίους στρατιώτας κατεῖχε, βουλόμενος ἐφεδρείᾳ χρήσασθαι πρός τε τὴν εἴσοδον καὶ τὴν ἔξοδον τὴν ἐκ τῶν στενῶν — ἔστι γὰρ πᾶς ὁ παρὰ τὴν λίμνην τόπος ὀρεινὸς καὶ τραχύς, συνηγμένος ταῖς ὕλαις· διὸ καὶ παντελῶς στενὴν καὶ δυσδίοδον ἔχει τὴν πάροδον — μετὰ δὲ ταῦτα τοὺς μὲν μισθοφόρους προθέμενος πάσης τῆς πορείας, ἐπὶ δὲ τούτοις τοὺς Ἰλλυριούς, ἑξῆς δὲ τοὺς πελταστὰς καὶ φαλαγγίτας ἔχων προῆγε διὰ τῶν στενῶν, ἀπουραγούντων μὲν αὐτῷ τῶν Κρητῶν, δεξιῶν δὲ παρὰ πλάγια τῶν Θρᾳκῶν καὶ ψιλῶν ἀντιπαραπορευομένων ταῖς χώραις. τὴν μὲν γὰρ ἐκ τῶν εὐωνύμων ἐπιφάνειαν τῆς πορείας ἠσφάλισθ’ ἡ λίμνη σχεδὸν ἐπὶ τριάκοντα στάδια.", "st": "5.7"}, {"sp": "N", "t": "ἀνύσας δὲ τοὺς προειρημένους τόπους, καὶ παραγενόμενος πρὸς τὴν καλουμένην κώμην Παμφίαν, ὁμοίως καὶ ταύτην ἀσφαλισάμενος φρουρᾷ προέβαινε πρὸς τὸν Θέρμον, ὁδὸν οὐ μόνον προσάντη καὶ τραχεῖαν διαφερόντως, ἀλλὰ καὶ κρημνοὺς ἐξ ἑκατέρου τοῦ μέρους ἔχουσαν βαθεῖς, ὥστε καὶ λίαν ἐπισφαλῆ καὶ στενὴν τὴν πάροδον εἶναι κατ’ ἐνίους τόπους, τῆς πάσης ἀναβάσεως οὔσης σχεδὸν ἐπὶ τριάκοντα στάδια. διανύσας δὲ καὶ ταύτην ἐν βραχεῖ χρόνῳ διὰ τὸ τοὺς Μακεδόνας ἐνεργὸν ποιεῖσθαι τὴν πορείαν, ἧκε πολλῆς ὥρας ἐπὶ τὸν Θέρμον, καὶ καταστρατοπεδεύσας ἐφῆκε τὴν δύναμιν τάς τε περιοικίδας κώμας πορθεῖν καὶ τὸ τῶν Θερμίων πεδίον ἐπιτρέχειν, ὁμοίως δὲ καὶ τὰς οἰκίας τὰς ἐν αὐτῷ τῷ Θέρμῳ διαρπάζειν, οὔσας πλήρεις οὐ μόνον σίτου καὶ τῆς τοιαύτης χορηγίας, ἀλλὰ καὶ κατασκευῆς διαφερούσης τῶν παρ’ Αἰτωλῶν. καθ’ ἕκαστον γὰρ ἔτος ἀγοράς τε καὶ πανηγύρεις ἐπιφανεστάτας, ἔτι δὲ καὶ τὰς τῶν ἀρχαιρεσίων καταστάσεις ἐν τούτῳ τῷ τόπῳ συντελούντων, ἕκαστοι πρὸς τὰς ὑποδοχὰς καὶ τὰς εἰς ταῦτα παρασκευὰς τὰ πολυτελέστατα τῶν ἐν τοῖς βίοις ὑπαρχόντων εἰς τοῦτον ἀπετίθεντο τὸν τόπον. χωρὶς δὲ τῆς χρείας καὶ τὴν ἀσφάλειαν ἤλπιζον ἐνταυθοῖ βεβαιοτάτην αὑτοῖς ὑπάρχειν, διὰ τὸ μήτε πολέμιον τετολμηκέναι μηδένα πώποτε εἰς τοὺς τόπους τούτους ἐμβαλεῖν, εἶναί τε τῇ φύσει τοιούτους ὥστε τῆς συμπάσης Αἰτωλίας οἷον ἀκροπόλεως ἔχειν τάξιν. διότιπερ εἰρηνευομένης ἐκ παλαιοῦ τῆς χώρας πλήρεις ἦσαν ἀγαθῶν πολλῶν αἵ τε περὶ τὸ ἱερὸν οἰκίαι καὶ πάντες οἱ πέριξ τόποι. ἐκείνην μὲν οὖν τὴν νύκτα παντοδαπῆς γέμοντες ὠφελείας αὐτοῦ κατηυλίσθησαν· τῇ δ’ ἐπαύριον τῆς μὲν κατασκευῆς τὰ πολυτελέστατα καὶ τὰ δυνατὰ κομίζεσθαι διέλεγον, τὰ δὲ λοιπὰ σωρεύοντες πρὸ τῶν σκηνῶν ἐνεπίμπρασαν. ὁμοίως δὲ καὶ τῶν ὅπλων τῶν ἐν ταῖς στοαῖς ἀνακειμένων τὰ μὲν πολυτελῆ καθαιροῦντες ἀπεκόμιζον, τινὰ δ’ ὑπήλλαττον, τὰ δὲ λοιπὰ συναθροίσαντες πῦρ ἐνέβαλον. ἦν δὲ ταῦτα πλείω τῶν μυρίων καὶ πεντακισχιλίων.", "st": "5.8"}, {"sp": "N", "t": "καὶ ἕως μὲν τούτου πάντα κατὰ τοὺς τοῦ πολέμου· νόμους καλῶς καὶ δικαίως ἐπράττετο· τὰ δὲ μετὰ ταῦτα πῶς χρὴ λέγειν οὐκ οἶδα. λαβόντες γὰρ ἔννοιαν τῶν ἐν Δίῳ καὶ Δωδώνῃ πεπραγμένων τοῖς Αἰτωλοῖς, τάς τε στοὰς ἐνεπίμπρασαν καὶ τὰ λοιπὰ τῶν ἀναθημάτων διέφθειρον, ὄντα πολυτελῆ ταῖς κατασκευαῖς καὶ πολλῆς ἐπιμελείας ἔνια τετευχότα καὶ δαπάνης. οὐ μόνον δὲ τῷ πυρὶ κατελυμήναντο τὰς ὀροφάς, ἀλλὰ καὶ κατέσκαψαν εἰς ἔδαφος. ἀνέτρεψαν δὲ καὶ τοὺς ἀνδριάντας, ὄντας οὐκ ἐλάττους δισχιλίων· πολλοὺς δὲ καὶ διέφθειραν, πλὴν ὅσοι θεῶν ἐπιγραφὰς ἢ τύπους εἶχον· τῶν δὲ τοιούτων ἀπέσχοντο. κατέγραφον δ’ εἰς τοὺς τοίχους καὶ τὸν περιφερόμενον στίχον, ἤδη τότε τῆς ἐπιδεξιότητος τῆς Σάμου φυομένης, ὃς ἦν υἱὸς μὲν Χρυσογόνου, σύντροφος δὲ τοῦ βασιλέως. ὁ δὲ στίχος ἦν ὁρᾷς τὸ δῖον οὗ βέλος διέπτατο; καὶ μεγίστη δὴ καὶ παράστασις ἐπὶ τούτοις εἶχε τόν τε βασιλέα καὶ τοὺς περὶ αὐτὸν φίλους, ὡς δικαίως ταῦτα πράττοντας καὶ καθηκόντως, ἀμυνομένους τοῖς ὁμοίοις τὴν τῶν Αἰτωλῶν περὶ τὸ Δῖον ἀσέβειαν. ἐμοὶ δὲ τἀναντία δοκεῖ τούτων. εἰ δ’ ὀρθὸς ὁ λόγος, σκοπεῖν ἐν μέσῳ πάρεστι, χρωμένους οὐχ ἑτέροις τισίν, ἀλλὰ τοῖς ἐξ αὐτῆς τῆς οἰκίας ταύτης παραδείγμασιν. Ἀντίγονος ἐκ παρατάξεως νικήσας μάχῃ Κλεομένην τὸν βασιλέα τῶν Λακεδαιμονίων ἐγκρατὴς ἐγένετο καὶ τῆς Σπάρτης, αὐτός τ’ ὢν κύριος ὃ βούλοιτο χρῆσθαι καὶ τῇ πόλει καὶ τοῖς ἐμπολιτευομένοις, τοσοῦτον ἀπεῖχε τοῦ κακῶς ποιεῖν τοὺς γεγονότας ὑποχειρίους ὡς ἐκ τῶν ἐναντίων ἀποδοὺς τὸ πάτριον πολίτευμα καὶ τὴν ἐλευθερίαν, καὶ τῶν μεγίστων ἀγαθῶν αἴτιος γενόμενος καὶ κοινῇ καὶ κατ’ ἰδίαν Λακεδαιμονίοις, οὕτως εἰς τὴν οἰκείαν ἀπηλλάγη. τοιγαροῦν οὐ μόνον ἐκρίθη παρ’ αὐτὸν τὸν καιρὸν εὐεργέτης, ἀλλὰ καὶ μεταλλάξας σωτήρ, οὐδὲ παρὰ μόνοις Λακεδαιμονίοις, ἀλλὰ παρὰ πᾶσι τοῖς Ἕλλησιν ἀθανάτου τέτευχε τιμῆς καὶ δόξης ἐπὶ τοῖς προειρημένοις.", "st": "5.9"}, {"sp": "N", "t": "καὶ μὴν ὁ πρῶτος αὐτῶν αὐξήσας τὴν βασιλείαν καὶ γενόμενος ἀρχηγὸς τοῦ προσχήματος τῆς οἰκίας, Φίλιππος νικήσας Ἀθηναίους τὴν ἐν Χαιρωνείᾳ μάχην, οὐ τοσοῦτον ἤνυσε διὰ τῶν ὅπλων ὅσον διὰ τῆς ἐπιεικείας καὶ φιλανθρωπίας τῶν τρόπων. τῷ μὲν γὰρ πολέμῳ καὶ τοῖς ὅπλοις αὐτῶν μόνων περιεγένετο καὶ κύριος κατέστη τῶν ἀντιταξαμένων, τῇ δ’ εὐγνωμοσύνῃ καὶ μετριότητι πάντας Ἀθηναίους ἅμα καὶ τὴν πόλιν αὐτῶν ἔσχεν ὑποχείριον, οὐκ ἐπιμετρῶν τῷ θυμῷ τοῖς πραττομένοις, ἀλλὰ μέχρι τούτου πολεμῶν καὶ φιλονεικῶν, ἕως τοῦ λαβεῖν ἀφορμὰς πρὸς ἀπόδειξιν τῆς αὑτοῦ πρᾳότητος καὶ καλοκἀγαθίας. τοιγαροῦν χωρὶς λύτρων ἀποστείλας τοὺς αἰχμαλώτους καὶ κηδεύσας Ἀθηναίων τοὺς τετελευτηκότας, ἔτι δὲ συνθεὶς Ἀντιπάτρῳ τὰ τούτων ὀστᾶ καὶ τῶν ἀπαλλαττομένων τοὺς πλείστους ἀμφιέσας, μικρᾷ δαπάνῃ διὰ τὴν ἀγχίνοιαν τὴν μεγίστην πρᾶξιν κατειργάσατο· τὸ γὰρ Ἀθηναίων φρόνημα καταπληξάμενος τῇ μεγαλοψυχίᾳ πρὸς πᾶν ἑτοίμους αὐτοὺς ἔσχε συναγωνιστὰς ἀντὶ πολεμίων. τί δ’ Ἀλέξανδρος; ἐκεῖνος γὰρ ἐπὶ τοσοῦτον ἐξοργισθεὶς Θηβαίοις ὥστε τοὺς μὲν οἰκήτορας ἐξανδραποδίσασθαι, τὴν δὲ πόλιν εἰς ἔδαφος κατασκάψαι, τῆς γε πρὸς τοὺς θεοὺς εὐσεβείας οὐκ ὠλιγώρησε περὶ τὴν κατάληψιν τῆς πόλεως, ἀλλὰ πλείστην ἐποιήσατο πρόνοιαν ὑπὲρ τοῦ μηδ’ ἀκούσιον ἁμάρτημα γενέσθαι περὶ τὰ ἱερὰ καὶ καθόλου τὰ τεμένη. καὶ μὴν ὅτε διαβὰς εἰς τὴν Ἀσίαν μετεπορεύετο τὴν Περσῶν ἀσέβειαν εἰς τοὺς Ἕλληνας, παρὰ μὲν τῶν ἀνθρώπων ἐπειράθη λαβεῖν δίκην ἀξίαν τῶν σφίσι πεπραγμένων, τῶν δὲ τοῖς θεοῖς καταπεφημισμένων πάντων ἀπέσχετο, καίπερ τῶν Περσῶν μάλιστα περὶ τοῦτο τὸ μέρος ἐξαμαρτόντων ἐν τοῖς κατὰ τὴν Ἑλλάδα τόποις. ταῦτ’ οὖν ἐχρῆν καὶ τότε Φίλιππον ἐν νῷ λαμβάνοντα συνεχῶς μὴ οὕτως τῆς ἀρχῆς ὡς τῆς προαιρέσεως καὶ τῆς μεγαλοψυχίας διάδοχον αὑτὸν ἀναδεικνύναι καὶ κληρονόμον τῶν προειρημένων ἀνδρῶν. ὁ δ’ ἵνα μὲν καὶ συγγενὴς Ἀλεξάνδρου καὶ Φιλίππου φαίνηται μεγάλην ἐποιεῖτο παρ’ ὅλον τὸν βίον σπουδήν, ἵνα δὲ ζηλωτὴς οὐδὲ τὸν ἐλάχιστον ἔσχε λόγον. τοιγαροῦν τἀναντία τοῖς προειρημένοις ἀνδράσιν ἐπιτηδεύων τῆς ἐναντίας ἔτυχε παρὰ πᾶσι δόξης, προβαίνων κατὰ τὴν ἡλικίαν.", "st": "5.10"}, {"sp": "N", "t": "ὧν ἦν ἓν καὶ τὸ τότε πραχθέν. τοῖς γὰρ Αἰτωλῶν ἀσεβήμασι συνεξαμαρτάνων διὰ τὸν θυμὸν καὶ κακῷ κακὸν ἰώμενος οὐδὲν ᾤετο ποιεῖν ἄτοπον. καὶ Σκόπᾳ μὲν καὶ Δωριμάχῳ παρ’ ἕκαστον εἰς ἀσέλγειαν καὶ παρανομίαν ὠνείδιζε, τὴν ἐν Δωδώνῃ καὶ Δίῳ προφερόμενος ἀσέβειαν εἰς τὸ θεῖον· αὐτὸς δὲ παραπλήσια ποιῶν οὐκ ᾤετο τῆς ὁμοίας ἐκείνοις τεύξεσθαι δόξης παρὰ τοῖς ἀκούσασι. τὸ μὲν γὰρ παραιρεῖσθαι τῶν πολεμίων καὶ καταφθείρειν φρούρια, λιμένας, πόλεις, ἄνδρας, ναῦς, καρπούς, τἄλλα τὰ τούτοις παραπλήσια, δι’ ὧν τοὺς μὲν ὑπεναντίους ἀσθενεστέρους ἄν τις ποιήσαι, τὰ δὲ σφέτερα πράγματα καὶ τὰς ἐπιβολὰς δυναμικωτέρας, ταῦτα μὲν ἀναγκάζουσιν οἱ τοῦ πολέμου νόμοι καὶ τὰ τούτου δίκαια δρᾶν· τὸ δὲ μήτε τοῖς ἰδίοις πράγμασιν ἐπικουρίαν μέλλοντα μηδ’ ἡντινοῦν παρασκευάζειν μήτε τοῖς ἐχθροῖς ἐλάττωσιν πρός γε τὸν ἐνεστῶτα πόλεμον ἐκ περιττοῦ καὶ ναούς, ἅμα δὲ τούτοις ἀνδριάντας καὶ πᾶσαν δὴ τὴν τοιαύτην κατασκευὴν λυμαίνεσθαι, πῶς οὐκ ἂν εἴποι τις εἶναι τρόπου καὶ θυμοῦ λυττῶντος ἔργον; οὐ γὰρ ἐπ’ ἀπωλείᾳ δεῖ καὶ ἀφανισμῷ τοῖς ἀγνοήσασι πολεμεῖν τοὺς ἀγαθοὺς ἄνδρας, ἀλλ’ ἐπὶ διορθώσει καὶ μεταθέσει τῶν ἡμαρτημένων, οὐδὲ συναναιρεῖν τὰ μηδὲν ἀδικοῦντα τοῖς ἠδικηκόσιν, ἀλλὰ συσσῴζειν μᾶλλον καὶ συνεξαιρεῖσθαι τοῖς ἀναιτίοις τοὺς δοκοῦντας ἀδικεῖν. τυράννου μὲν γὰρ ἔργον ἐστὶ τὸ κακῶς ποιοῦντα τῷ φόβῳ δεσπόζειν ἀκουσίων, μισούμενον καὶ μισοῦντα τοὺς ὑποταττομένους· βασιλέως δὲ τὸ πάντας εὖ ποιοῦντα, διὰ τὴν εὐεργεσίαν καὶ φιλανθρωπίαν ἀγαπώμενον, ἑκόντων ἡγεῖσθαι καὶ προστατεῖν. μάλιστα δ’ ἄν τις καταμάθοι τὴν ἁμαρτίαν τὴν τότε Φιλίππου, λαβὼν πρὸ ὀφθαλμῶν τίνα διάληψιν εἰκὸς ἦν Αἰτωλοὺς ἔχειν, εἰ τἀναντία τοῖς εἰρημένοις ἔπραξε καὶ μήτε τὰς στοὰς μήτε τοὺς ἀνδριάντας διέφθειρε μήτ’ ἄλλο μηδὲν ᾐκίσατο τῶν ἀναθημάτων. ἐγὼ μὲν γὰρ οἶμαι τὴν βελτίστην ἂν καὶ φιλανθρωποτάτην, συνειδότας μὲν αὑτοῖς τὰ περὶ Δῖον καὶ Δωδώνην πεπραγμένα, σαφῶς δὲ γινώσκοντας ὅθ’ ὁ Φίλιππος τότε καὶ πρᾶξαι κύριος ἦν ὃ βουληθείη, καὶ πράξας τὰ δεινότατα δικαίως ἂν ἐδόκει τοῦτο πεποιηκέναι τό γε κατ’ ἐκείνους μέρος· διὰ δὲ τὴν αὑτοῦ πρᾳότητα καὶ μεγαλοψυχίαν οὐδὲν εἵλετο τῶν ὁμοίων ἐκείνοις ἐπιτηδεύειν.", "st": "5.11"}, {"sp": "N", "t": "δῆλον γὰρ ἐκ τούτων ὡς εἰκὸς ἦν αὑτῶν μὲν καταγινώσκειν, τὸν δὲ Φίλιππον ἀποδέχεσθαι καὶ θαυμάζειν, ὡς βασιλικῶς καὶ μεγαλοψύχως αὐτοῦ· χρωμένου τῇ τε πρὸς τὸ θεῖον εὐσεβείᾳ καὶ τῇ πρὸς αὐτοὺς ὀργῇ. καὶ μὴν τό γε νικῆσαι τοὺς πολεμίους καλοκἀγαθίᾳ καὶ τοῖς δικαίοις οὐκ ἐλάττω, μείζω δὲ παρέχεται χρείαν τῶν ἐν τοῖς ὅπλοις κατορθωμάτων. οἷς μὲν γὰρ δι’ ἀνάγκην, οἷς δὲ κατὰ προαίρεσιν εἴκουσιν οἱ λειφθέντες· καὶ τὰ μὲν μετὰ μεγάλων ἐλαττωμάτων ποιεῖται τὴν διόρθωσιν, τὰ δὲ χωρὶς βλάβης πρὸς τὸ βέλτιον μετατίθησι τοὺς ἁμαρτάνοντας. τὸ δὲ μέγιστον, ἐν οἷς μὲν τὸ πλεῖστόν ἐστι τῆς πράξεως τῶν ὑποταττομένων, ἐν οἷς δ’ αὐτοτελὴς ἡ νίκη γίνεται τῶν ἡγουμένων. ἴσως μὲν οὖν οὐκ ἄν τις αὐτῷ Φιλίππῳ τῶν τότε γενομένων πᾶσαν ἐπιφέροι τὴν αἰτίαν διὰ τὴν ἡλικίαν, τὸ πλεῖον δὲ τοῖς συνοῦσι καὶ συμπράττουσι τῶν φίλων, ὧν ἦν Ἄρατος καὶ Δημήτριος ὁ Φάριος. ὑπὲρ ὧν οὐ δυσχερὲς ἀποφήνασθαι καὶ μὴ παρόντα τότε ποτέρου τὴν τοιαύτην εἰκὸς εἶναι συμβουλίαν. χωρὶς γὰρ τῆς κατὰ τὸν ὅλον βίον προαιρέσεως, ἐν ᾗ περὶ μὲν Ἄρατον οὐδὲν ἂν εὑρεθείη προπετὲς οὐδ’ ἄκριτον, περὶ δὲ Δημήτριον τἀναντία, καὶ δεῖγμα τῆς προαιρέσεως ἑκατέρων ἐν οἷς συνεβουλεύσαντο Φιλίππῳ παραπλησίως ὁμολογούμενον ἔχομεν· ὑπὲρ οὗ λαβόντες τὸν οἰκεῖον καιρὸν ποιησόμεθα τὴν ἁρμόζουσαν μνήμην.", "st": "5.12"}, {"sp": "N", "t": "ὁ δὲ Φίλιππος — ἀπὸ γὰρ τούτων παρεξέβην — ὅσα δυνατὸν ἦν ἄγειν καὶ φέρειν ἀναλαβὼν ἐκ τοῦ Θέρμου προῆγε, ποιούμενος τὴν αὐτὴν ἐπάνοδον ᾗ καὶ παρεγένετο, προβαλόμενος μὲν τὴν λείαν εἰς τοὔμπροσθεν καὶ τὰ βαρέα τῶν ὅπλων, ἐπὶ δὲ τῆς οὐραγίας ἀπολιπὼν τοὺς Ἀκαρνᾶνας καὶ τοὺς μισθοφόρους, σπεύδων ὡς τάχιστα διανύσαι τὰς δυσχωρίας διὰ τὸ προσδοκᾶν τοὺς Αἰτωλοὺς ἐξάψεσθαι τῆς οὐραγίας, πιστεύοντας ταῖς ὀχυρότησι τῶν τόπων. ὃ καὶ συνέβη γενέσθαι παρὰ πόδας. οἱ γὰρ Αἰτωλοὶ προσβεβοηθηκότες καὶ συνηθροισμένοι σχεδὸν εἰς τρισχιλίους, ἕως μὲν ὁ Φίλιππος ἦν ἐπὶ τῶν μετεώρων, οὐκ ἤγγιζον, ἀλλ’ ἔμενον ἔν τισι τόποις ἀδήλοις, Ἀλεξάνδρου τοῦ Τριχωνέως προεστῶτος αὐτῶν· ἅμα δὲ τῷ κινῆσαι τὴν οὐραγίαν ἐπέβαλον εὐθέως εἰς τὸν Θέρμον καὶ προσέκειντο τοῖς ἐσχάτοις. γινομένης δὲ ταραχῆς περὶ τὴν οὐραγίαν, ἔτι μᾶλλον ἐκθύμως οἱ παρὰ τῶν Αἰτωλῶν ἐπέκειντο καὶ προσέφερον τὰς χεῖρας, πιστεύοντες τοῖς τόποις. ὁ δὲ Φίλιππος, προειδὼς τὸ μέλλον, ὑπό τινα λόφον ὑπεστάλκει τοὺς Ἰλλυριοὺς ἐν τῇ καταβάσει καὶ τῶν πελταστῶν τοὺς ἐπιτηδειοτάτους. ὧν διαναστάντων ἐπὶ τοὺς ἐπικειμένους καὶ προπεπτωκότας τῶν ὑπεναντίων, τοὺς μὲν λοιποὺς τῶν Αἰτωλῶν ἀνοδίᾳ καὶ προτροπάδην συνέβη φυγεῖν, ἑκατὸν δὲ καὶ τριάκοντα πεσεῖν, ἁλῶναι δ’ οὐ πολὺ τούτων ἐλάττους. γενομένου δὲ τοῦ προτερήματος τούτου, ταχέως οἱ περὶ τὴν οὐραγίαν, ἐμπρήσαντες τὸ Πάμφιον καὶ μετ’ ἀσφαλείας διελθόντες τὰ στενά, συνέμιξαν τοῖς Μακεδόσιν· ὁ γὰρ Φίλιππος ἐστρατοπεδευκὼς περὶ τὴν Μέταπαν ἐνταυθοῖ προσανεδέχετο τοὺς ἀπὸ τῆς οὐραγίας. εἰς δὲ τὴν ὑστεραίαν κατασκάψας τὴν Μέταπαν προῆγε, καὶ παρενέβαλε περὶ τὴν καλουμένην πόλιν Ἄκρας. τῇ δ’ ἑξῆς ἅμα προάγων ἐπόρθει τὴν χώραν, καὶ καταστρατοπεδεύσας περὶ Κωνώπην ἐπέμεινε τὴν ἐχομένην ἡμέραν. τῇ δ’ ἐπιούσῃ πάλιν ἀναζεύξας ἐποιεῖτο τὴν πορείαν παρὰ τὸν Ἀχελῷον ἕως ἐπὶ τὸν Στράτον. διαβὰς δὲ τὸν ποταμὸν ἐπέστησε τὴν δύναμιν ἐκτὸς βέλους, ἀποπειρώμενος τῶν ἔνδον·", "st": "5.13"}, {"sp": "N", "t": "ἐπυνθάνετο γὰρ εἰς τὸν Στράτον συνδεδραμηκέναι τῶν Αἰτωλῶν πεζοὺς μὲν εἰς τρισχιλίους, ἱππεῖς δὲ περὶ τετρακοσίους, Κρῆτας δ’ εἰς πεντακοσίους. οὐδενὸς δ’ ἐπεξιέναι τολμῶντος, αὖτις ἀρξάμενος ἐκίνει τοὺς πρώτους, ποιούμενος τὴν πορείαν ὡς ἐπὶ τὴν Λιμναίαν καὶ τὰς ναῦς. ἅμα δὲ τῷ τὴν οὐραγίαν παραλλάξαι τὴν πόλιν τὸ μὲν πρῶτον ὀλίγοι τῶν Αἰτωλικῶν ἱππέων ἐξελθόντες κατεπείραζον τῶν ἐσχάτων· ἐπεὶ δὲ τό τε τῶν Κρητῶν πλῆθος ἐκ τῆς πόλεως καί τινες τῶν Αἰτωλικῶν συνῆψαν τοῖς αὑτῶν ἱππεῦσι, γινομένης ὁλοσχερεστέρας συμπλοκῆς, ἠναγκάσθησαν ἐκ μεταβολῆς οἱ περὶ τὴν οὐραγίαν κινδυνεύειν. τὸ μὲν οὖν πρῶτον ἀμφοτέρων ἐφάμιλλος ἦν ὁ κίνδυνος· προσβοηθησάντων δὲ τοῖς παρὰ τοῦ Φιλίππου μισθοφόροις τῶν Ἰλλυριῶν, ἐνέκλιναν καὶ σποράδην ἔφευγον οἱ τῶν Αἰτωλῶν ἱππεῖς καὶ μισθοφόροι. καὶ τὸ μὲν πολὺ μέρος αὐτῶν ἕως εἰς τὰς πύλας καὶ πρὸς τὰ τείχη συνεδίωξαν οἱ παρὰ τοῦ βασιλέως, κατέβαλον δ’ εἰς ἑκατόν. ἀπὸ δὲ ταύτης τῆς χρείας λοιπὸν οἱ μὲν ἐκ τῆς πόλεως τὴν ἡσυχίαν ἦγον, οἱ δ’ ἀπὸ τῆς οὐραγίας ἀσφαλῶς συνῆψαν πρὸς τὸ στρατόπεδον καὶ τὰς ναῦς. ὁ δὲ Φίλιππος καταστρατοπεδεύσας ἐν ὥρᾳ τοῖς θεοῖς ἔθυεν εὐχαριστήρια τῆς γεγενημένης αὐτῷ περὶ τὴν ἐπιβολὴν εὐροίας, ἅμα δὲ καὶ τοὺς ἡγεμόνας ἐκάλει, βουλόμενος ἑστιᾶσαι πάντας. ἐδόκει γὰρ εἰς τόπους αὑτὸν δεδωκέναι παραβόλους καὶ τοιούτους, εἰς οὓς οὐδεὶς ἐτόλμησε πρότερον στρατοπέδῳ παρεμβαλεῖν. ὁ δ’ οὐ μόνον ἐνέβαλε μετὰ τῆς δυνάμεως, ἀλλὰ καὶ πᾶν ὃ προέθετο συντελεσάμενος ἀσφαλῶς ἐποιήσατο τὴν ἐπάνοδον. δι’ ἃ περιχαρὴς ὢν οὗτος μὲν ἐγίνετο περὶ τὴν τῶν ἡγεμόνων ὑποδοχήν· οἱ δὲ περὶ τὸν Μεγαλέαν καὶ Λεόντιον δυσχερῶς ἔφερον τὴν γεγενημένην ἐπιτυχίαν τοῦ βασιλέως, ὡς ἂν διατεταγμένοι μὲν πρὸς τὸν Ἀπελλῆν πάσαις ἐμποδιεῖν ταῖς ἐπιβολαῖς αὐτοῦ, μὴ δυνάμενοι δὲ τοῦτο ποιεῖν, ἀλλὰ τῶν πραγμάτων αὐτοῖς κατὰ τοὐναντίον προχωρούντων, διεσφαλμένοι προφανῶς. ἀλλ’ ἧκόν γε πρὸς τὸ δεῖπνον.", "st": "5.14"}, {"sp": "N", "t": "ἦσαν μὲν οὖν εὐθέως ἐν ὑπονοίᾳ τῷ τε βασιλεῖ καὶ τοῖς ἄλλοις οὐχ ὁμοίως τοῖς λοιποῖς χαίροντες ἐπὶ τοῖς γεγονόσι· προβαίνοντος δὲ τοῦ πότου, κἄπειτα γενομένης ἀκαιρίας καὶ πολυποσίας, ἀναγκασθέντες συμπεριφέρεσθαι, ταχέως ἐξεθεάτρισαν αὑτούς. λυθείσης γὰρ τῆς συνουσίας ὑπό τε τῆς μέθης καὶ τῆς ἀλογιστίας ἐλαυνόμενοι, περιῄεσαν ζητοῦντες τὸν Ἄρατον. συμμίξαντες δὲ κατὰ τὴν ἐπάνοδον αὐτῷ, τὸ μὲν πρῶτον ἐλοιδόρουν, μετὰ δὲ βάλλειν ἐνεχείρησαν τοῖς λίθοις. προσβοηθούντων δὲ πλειόνων ἀμφοτέροις θόρυβος ἦν καὶ κίνημα κατὰ τὴν παρεμβολήν. ὁ δὲ βασιλεὺς ἀκούων τῆς κραυγῆς, ἐξαπέστειλε τοὺς ἐπιγνωσομένους καὶ διαλύσοντας τὴν ταραχήν. ὁ μὲν οὖν Ἄρατος, παραγενομένων τούτων, εἰπὼν τὰ γεγονότα καὶ μάρτυρας παρασχόμενος τοὺς συμπαρόντας, ἀπηλλάττετο ταύτης τῆς ἀδικίας ἐπὶ τὴν αὑτοῦ σκηνήν, ὁ δὲ Λεόντιος ἀλόγως πως κατὰ τὸν θόρυβον ἀπέρρευσε. τὸν δὲ Μεγαλέαν καὶ Κρίνωνα μεταπεμψάμενος ὁ βασιλεύς, ἐπεὶ συνῆκε τὸ γεγονός, ἐπετίμα πικρῶς. οἱ δ’ οὐχ οἷον ὑπέμειναν, ἀλλ’ ἐπεμέτρησαν, φάσκοντες οὐδὲ λήξειν τῆς προθέσεως, ἕως ἂν τὸν μισθὸν ἐπιθῶσι τοῖς περὶ τὸν Ἄρατον. ὁ δὲ βασιλεύς, ὀργισθεὶς ἐπὶ τῷ ῥηθέντι, παραχρῆμα πρὸς εἴκοσι τάλαντα κατεγγυήσας ἐκέλευσεν αὐτοὺς εἰς φυλακὴν ἀπαγαγεῖν.", "st": "5.15"}, {"sp": "N", "t": "τῇ δ’ ἐπαύριον ἀνακαλεσάμενος τὸν Ἄρατον παρεκάλει θαρρεῖν, ὅτι ποιήσεται τὴν ἐνδεχομένην ἐπιστροφὴν τοῦ πράγματος. ὁ δὲ Λεόντιος, συνεὶς τὰ περὶ τὸν Μεγαλέαν, ἧκε πρὸς τὴν σκηνὴν μετά τινων πελταστῶν, πεπεισμένος καταπλήξεσθαι διὰ τὴν ἡλικίαν καὶ ταχέως εἰς μετάνοιαν ἄξειν τὸν βασιλέα. συντυχὼν δ’ αὐτῷ, προσεπυνθάνετο τίς ἐτόλμησεν ἐπιβαλεῖν τὰς χεῖρας Μεγαλέᾳ καὶ τίς εἰς τὴν φυλακὴν ἀπαγαγεῖν. τοῦ δὲ βασιλέως ὑποστατικῶς αὐτοῦ φήσαντος συντεταχέναι, καταπλαγεὶς ὁ Λεόντιος καί τι προσανοιμώξας, ἀπῄει τεθυμωμένος. ὁ δὲ βασιλεύς, ἀναχθεὶς παντὶ τῷ στόλῳ καὶ διάρας τὸν κόλπον, ὡς θᾶττον εἰς τὴν Λευκάδα καθωρμίσθη, τοῖς μὲν ἐπὶ τῆς τῶν λαφύρων οἰκονομίας τεταγμένοις περὶ ταῦτα συνέταξε γινομένοις μὴ καθυστερεῖν, αὐτὸς δὲ συναγαγὼν τοὺς φίλους ἀπέδωκε κρίσιν τοῖς περὶ τὸν Μεγαλέαν. τοῦ δ’ Ἀράτου κατηγορήσαντος ἀνέκαθεν τὰ πεπραγμένα τοῖς περὶ τὸν Λεόντιον, καὶ διελθόντος τὴν γενομένην ὑπ’ αὐτῶν ἐν Ἄργει σφαγήν, ἣν ἐποιήσαντο μετὰ τὸν Ἀντιγόνου χωρισμόν, καὶ τὰς πρὸς Ἀπελλῆν συνθήκας, ἔτι δὲ τὸν περὶ τοὺς Παλαιεῖς ἐμποδισμόν, καὶ πάντα ταῦτα μετ’ ἀποδείξεως ἐνδεικνυμένου καὶ μαρτύρων, οὐ δυνάμενοι πρὸς οὐδὲν ἀντιλέγειν οἱ περὶ τὸν Μεγαλέαν κατεκρίθησαν ὁμοθυμαδὸν ὑπὸ τῶν φίλων. καὶ Κρίνων μὲν ἔμεινεν ἐν τῇ φυλακῇ, τὸν δὲ Μεγαλέαν Λεόντιος ἀνεδέξατο τῶν χρημάτων. ἡ μὲν οὖν Ἀπελλοῦ καὶ τῶν περὶ τὸν Λεόντιον πρᾶξις ἐν τούτοις ἦν, παλίντροπον λαμβάνουσα τὴν προκοπὴν ταῖς ἐξ ἀρχῆς αὐτῶν ἐλπίσιν. ἔδοξαν μὲν γὰρ καταπληξάμενοι τὸν Ἄρατον καὶ μονώσαντες τὸν Φίλιππον ποιήσειν ὅ τι ἂν αὐτοῖς δοκῇ συμφέρειν, ἀπέβη δὲ τούτων τἀναντία.", "st": "5.16"}, {"sp": "N", "t": "κατὰ δὲ τοὺς προειρημένους καιροὺς Λυκοῦργος ἐκ μὲν τῆς Μεσσηνίας οὐδὲν ἄξιον λόγου πράξας ἐπανῆλθε· μετὰ δὲ ταῦτα πάλιν ὁρμήσας ἐκ Λακεδαίμονος κατελάβετο τὴν τῶν Τεγεατῶν πόλιν. τῶν δὲ σωμάτων ἀποχωρησάντων εἰς τὴν ἄκραν, ἐπεβάλετο πολιορκεῖν ταύτην. οὐδαμῶς δὲ δυνάμενος ἀνύειν οὐδὲν αὖτις ἀνεχώρησεν εἰς τὴν Σπάρτην. οἱ δ’ ἐκ τῆς Ἤλιδος καταδραμόντες τὴν Δυμαίαν καὶ τοὺς βοηθήσαντας τῶν ἱππέων εἰς ἐνέδραν ἐπαγαγόμενοι ῥᾳδίως ἐτρέψαντο, καὶ τῶν μὲν Γαλατικῶν οὐκ ὀλίγους κατέβαλον, τῶν δὲ πολιτικῶν αἰχμαλώτους ἔλαβον Πολυμήδη τε τὸν Αἰγιέα καὶ Δυμαίους Ἀγησίπολιν καὶ Διοκλέα. Δωρίμαχος δὲ τὴν μὲν πρώτην ἔξοδον ἐποιήσατο μετὰ τῶν Αἰτωλῶν, πεπεισμένος, καθάπερ ἐπάνω προεῖπον, αὑτὸν μὲν ἀσφαλῶς κατασύρειν τὴν Θετταλίαν, τὸν δὲ Φίλιππον ἀναστήσειν ἀπὸ τῆς περὶ τοὺς Παλαιεῖς πολιορκίας· εὑρὼν δὲ τοὺς περὶ τὸν Χρυσόγονον καὶ Πετραῖον ἑτοίμους ἐν Θετταλίᾳ πρὸς τὸ διακινδυνεύειν, εἰς μὲν τὸ πεδίον οὐκ ἐθάρρει καταβαίνειν, ἐν δὲ ταῖς παρωρείαις προσανέχων διῆγε. προσπεσούσης δ’ αὐτῷ τῆς τῶν Μακεδόνων εἰς τὴν Αἰτωλίαν εἰσβολῆς, ἀφέμενος τῶν κατὰ Θετταλίαν ἐβοήθει τούτοις κατὰ σπουδήν. καταλαβὼν δ’ ἀπηλλαγμένους ἐκ τῆς Αἰτωλίας τοὺς Μακεδόνας οὗτος μὲν ὑπελείπετο καὶ καθυστέρει πάντων· ὁ δὲ βασιλεὺς ἀναχθεὶς ἐκ τῆς Λευκάδος, καὶ πορθήσας ἐν παράπλῳ τὴν τῶν Οἰανθέων χώραν, κατῆρε μετὰ τοῦ στόλου παντὸς εἰς Κόρινθον. ὁρμίσας δὲ τὰς νῆας ἐν τῷ Λεχαίῳ τήν τε δύναμιν ἐξεβίβαζε καὶ τοὺς γραμματοφόρους διαπέστελλε πρὸς τὰς ἐν Πελοποννήσῳ συμμαχίδας πόλεις, δηλῶν τὴν ἡμέραν, ἐν ᾗ δεήσει πάντας μετὰ τῶν ὅπλων κοιταίους ἐν τῇ τῶν Τεγεατῶν γίνεσθαι πόλει.", "st": "5.17"}, {"sp": "N", "t": "ταῦτα δὲ διαπραξάμενος, καὶ μείνας οὐδένα χρόνον ἐν τῇ Κορίνθῳ, παρήγγειλε τοῖς Μακεδόσιν ἀναζυγήν. ποιησάμενος δὲ τὴν πορείαν δι’ Ἄργους ἧκε δευτεραῖος εἰς Τεγέαν. προσαναλαβὼν δὲ τοὺς ἡθροισμένους τῶν Ἀχαιῶν προῆγε διὰ τῆς ὀρεινῆς, σπουδάζων λαθεῖν τοὺς Λακεδαιμονίους ἐμβαλὼν εἰς τὴν χώραν. περιελθὼν δὲ ταῖς ἐρημίαις, τεταρταῖος ἐπέβαλε τοῖς καταντικρὺ τῆς πόλεως λόφοις, καὶ παρῄει δεξιὸν ἔχων τὸ Μενελάιον ἐπ’ αὐτὰς τὰς Ἀμύκλας. οἱ δὲ Λακεδαιμόνιοι, θεωροῦντες ἐκ τῆς πόλεως παράγουσαν τὴν δύναμιν, ἐκπλαγεῖς ἐγένοντο καὶ περίφοβοι, θαυμάζοντες τὸ συμβαῖνον. ἀκμὴν γὰρ ἦσαν μετέωροι ταῖς διανοίαις ἐκ τῶν προσπιπτόντων ὑπὲρ τοῦ Φιλίππου περὶ τὴν καταφθορὰν τοῦ Θέρμου καὶ καθόλου ταῖς ἐν Αἰτωλίᾳ πράξεσι, καί τις ἐνεπεπτώκει θροῦς παρ’ αὐτοῖς ὑπὲρ τοῦ τὸν Λυκοῦργον ἐκπέμπειν βοηθήσοντα τοῖς Αἰτωλοῖς. ὑπὲρ δὲ τοῦ τὸ δεινὸν ἥξειν ἐπὶ σφᾶς οὕτως ὀξέως ἐκ τηλικούτου διαστήματος οὐδὲ διενοεῖτο παράπαν αὐτῶν οὐδείς, ἅτε καὶ τῆς ἡλικίας ἐχούσης ἀκμὴν εὐκαταφρόνητόν τι τῆς τοῦ βασιλέως. διὸ καὶ παρὰ δόξαν αὐτοῖς τῶν πραγμάτων συγκυρούντων εἰκότως ἦσαν ἐκπλαγεῖς. ὁ γὰρ Φίλιππος τολμηρότερον καὶ πρακτικώτερον ἢ κατὰ τὴν ἡλικίαν χρώμενος ταῖς ἐπιβολαῖς εἰς ἀπορίαν καὶ δυσχρηστίαν ἅπαντας ἦγε τοὺς πολεμίους. ἀναχθεὶς γὰρ ἐκ μέσης Αἰτωλίας, καθάπερ ἐπάνω προεῖπον, καὶ διανύσας ἐν νυκτὶ τὸν Ἀμβρακικὸν κόλπον, εἰς Λευκάδα κατῆρε. δύο δὲ μείνας ἡμέρας ἐνταῦθα, τῇ τρίτῃ ποιησάμενος ὑπὸ τὴν ἑωθινὴν τὸν ἀνάπλουν, δευτεραῖος πορθήσας ἅμα τὴν τῶν Αἰτωλῶν παραλίαν ἐν Λεχαίῳ καθωρμίσθη. μετὰ δὲ ταῦτα κατὰ τὸ συνεχὲς ποιούμενος τὰς πορείας ἑβδομαῖος ἐπέβαλε τοῖς ὑπὲρ τὴν πόλιν κειμένοις παρὰ τὸ Μενελάιον λόφοις, ὥστε τοὺς πλείστους ὁρῶντας τὸ γεγονὸς μὴ πιστεύειν τοῖς συμβαίνουσιν. οἱ μὲν οὖν Λακεδαιμόνιοι, περιδεεῖς γεγονότες διὰ τὸ παράδοξον, ἠπόρουν καὶ δυσχρήστως διέκειντο πρὸς τὸ παρόν.", "st": "5.18"}, {"sp": "N", "t": "ὁ δὲ Φίλιππος τῇ μὲν πρώτῃ κατεστρατοπέδευσε περὶ τὰς Ἀμύκλας. αἱ δ’ Ἀμύκλαι καλούμεναι τόπος ἐστὶ τῆς Λακωνικῆς χώρας καλλιδενδρότατος καὶ καλλικαρπότατος, ἀπέχει δὲ τῆς Λακεδαίμονος ὡς εἴκοσι σταδίους. ὑπάρχει δὲ καὶ τέμενος Ἀπόλλωνος ἐν αὐτῷ σχεδὸν ἐπιφανέστατον τῶν κατὰ τὴν Λακωνικὴν ἱερῶν. κεῖται δὲ τῆς πόλεως ἐν τοῖς πρὸς θάλατταν κεκλιμένοις μέρεσι. τῇ δ’ ἐπιούσῃ πορθῶν ἅμα τὴν χώραν εἰς τὸν Πύρρου καλούμενον κατέβη χάρακα. δύο δὲ τὰς ἑξῆς ἡμέρας ἐπιδραμὼν καὶ δῃώσας τοὺς σύνεγγυς τόπους, κατεστρατοπέδευσε περὶ τὸ Κάρνιον, ὅθεν ὁρμήσας ἦγε πρὸς Ἀσίνην· καὶ ποιησάμενος προσβολάς, οὐδέν γε τῶν προύργου περαίνων, ἀνέζευξε, καὶ τὸ λοιπὸν ἐπιπορευόμενος ἔφθειρε τὴν χώραν πᾶσαν τὴν ἐπὶ τὸ Κρητικὸν πέλαγος τετραμμένην ἕως Ταινάρου. μεταβαλόμενος δ’ αὖτις ἐποιεῖτο τὴν πορείαν παρὰ τὸν ναύσταθμον τῶν Λακεδαιμονίων, ὃ καλεῖται μὲν Γύθιον, ἔχει δ’ ἀσφαλῆ λιμένα, τῆς δὲ πόλεως ἀπέχει περὶ διακόσια καὶ τριάκοντα στάδια. τοῦτο δ’ ἀπολιπὼν κατὰ πορείαν δεξιὸν κατεστρατοπέδευσε περὶ τὴν Ἑλείαν, ἥτις ἐστὶν ὡς πρὸς μέρος θεωρουμένη πλείστη καὶ καλλίστη χώρα τῆς Λακωνικῆς. ὅθεν ἀφιεὶς τὰς προνομὰς αὐτόν τε τὸν τόπον τοῦτον πάντα κατεπυρπόλει καὶ διέφθειρε τοὺς ἐν αὐτῷ καρπούς, ἀφικνεῖτο δὲ ταῖς προνομαῖς καὶ πρὸς Ἀκρίας καὶ Λεύκας, ἔτι δὲ καὶ τὴν τῶν Βοιῶν χώραν.", "st": "5.19"}, {"sp": "N", "t": "οἱ δὲ Μεσσήνιοι, κομισάμενοι τὰ γράμματα τὰ παρὰ τοῦ Φιλππίου τὰ περὶ τῆς στρατείας, τῇ μὲν ὁρμῇ τῶν ἄλλων οὐκ ἐλείποντο συμμάχων, ἀλλὰ τὴν ἔξοδον ἐποιήσαντο μετὰ σπουδῆς καὶ τοὺς ἀκμαιοτάτους ἄνδρας ἐξέπεμψαν, πεζοὺς μὲν δισχιλίους, ἱππεῖς δὲ διακοσίους. τῷ δὲ μήκει τῆς ὁδοῦ καθυστερήσαντες τῆς εἰς τὴν Τεγέαν παρουσίας τοῦ Φιλίππου, τὸ μὲν πρῶτον ἠπόρουν τί δέον εἴη ποιεῖν· ἀγωνιῶντες δὲ μὴ δόξαιεν ἐθελοκακεῖν διὰ τὰς προγεγενημένας περὶ αὐτοὺς ὑποψίας, ὥρμησαν διὰ τῆς Ἀργείας εἰς τὴν Λακωνικήν, βουλόμενοι συνάψαι τοῖς περὶ τὸν Φίλιππον. παραγενόμενοι δὲ πρὸς Γλυμπεῖς χωρίον, ὃ κεῖται περὶ τοὺς ὅρους τῆς Ἀργείας καὶ Λακωνικῆς, πρὸς τοῦτο κατεστρατοπέδευσαν ἀπείρως ἅμα καὶ ῥᾳθύμως· οὔτε γὰρ τάφρον οὔτε χάρακα τῇ παρεμβολῇ περιέβαλον οὔτε τόπον εὐφυῆ περιέβλεψαν, ἀλλὰ τῇ τῶν κατοικούντων τὸ χωρίον εὐνοίᾳ πιστεύοντες ἀκάκως πρὸ τοῦ τείχους αὐτοῦ παρενέβαλον. ὁ δὲ Λυκοῦργος, προσαγγελθείσης αὐτῷ τῆς τῶν Μεσσηνίων παρουσίας, ἀναλαβὼν τοὺς μισθοφόρους καί τινας τῶν Λακεδαιμονίων προῆγε, καὶ συνάψας τοῖς τόποις ὑπὸ τὴν ἑωθινὴν ἐπέθετο τῇ στρατοπεδείᾳ τολμηρῶς. οἱ δὲ Μεσσήνιοι, τἄλλα πάντα κακῶς βουλευσάμενοι, καὶ μάλιστα προελθεῖν ἐκ τῆς Τεγέας, μὴ κατὰ τὸ πλῆθος ἀξιόχρεως ὑπάρχοντες μήτε πιστεύοντες ἐμπείροις, παρ’ αὐτόν γε τὸν κίνδυνον κατὰ τὴν ἐπίθεσιν ὅμως τὸ δυνατὸν ἐκ τῶν πραγμάτων ἔλαβον πρὸς τὴν ἑαυτῶν σωτηρίαν· ἅμα γὰρ τῷ συνιδεῖν ἐπιφαινομένους τοὺς πολεμίους ἀφέμενοι πάντων σπουδῇ πρὸς τὸ χωρίον προσέφυγον. διόπερ Λυκοῦργος τῶν μὲν ἵππων ἐγκρατὴς ἐγένετο τῶν πλείστων καὶ τῆς ἀποσκευῆς, τῶν δ’ ἀνδρῶν ζωγρίᾳ μὲν οὐδενὸς ἐκυρίευσε, τῶν δ’ ἱππέων ὀκτὼ μόνον ἀπέκτεινε. Μεσσήνιοι μὲν οὖν τοιαύτῃ περιπετείᾳ χρησάμενοι πάλιν δι’ Ἄργους εἰς τὴν οἰκείαν ἀνεκομίσθησαν. ὁ δὲ Λυκοῦργος μετεωρισθεὶς ἐπὶ τῷ γεγονότι, παραγενόμενος εἰς τὴν Λακεδαίμονα περὶ παρασκευὴν ἐγίνετο καὶ συνήδρευε μετὰ τῶν φίλων, ὡς οὐκ ἐάσων τὸν Φίλιππον ἐπανελθεῖν ἐκ τῆς χώρας ἄνευ κινδύνου καὶ συμπλοκῆς. ὁ δὲ βασιλεὺς ἐκ τῆς Ἑλείας ἀναζεύξας προῆγε, πορθῶν ἅμα τὴν χώραν, καὶ τεταρταῖος αὖθις εἰς τὰς Ἀμύκλας κατῆρε παντὶ τῷ στρατεύματι περὶ μέσον ἡμέρας.", "st": "5.20"}, {"sp": "N", "t": "Λυκοῦργος δὲ διαταξάμενος περὶ τοῦ μέλλοντος κινδύνου τοῖς ἡγεμόσι καὶ τοῖς φίλοις, αὐτὸς μὲν ἐξελθὼν ἐκ τῆς πόλεως κατελάβετο τοὺς περὶ τὸ Μενελάιον τόπους, ἔχων τοὺς πάντας οὐκ ἐλάττους δισχιλίων, τοῖς δ’ ἐν τῇ πόλει συνέθετο προσέχειν τὸν νοῦν, ἵν’ ὅταν αὐτοῖς αἴρῃ τὸ σύνθημα, σπουδῇ κατὰ πλείους τόπους ἐξαγαγόντες πρὸ τῆς πόλεως τὴν δύναμιν ἐκτάττωσι, βλέπουσαν ἐπὶ τὸν Εὐρώταν, καθ’ ὃν ἐλάχιστον τόπον ἀπέχει τῆς πόλεως ὁ ποταμός. τὰ μὲν οὖν περὶ τὸν Λυκοῦργον καὶ τοὺς Λακεδαιμονίους ἐν τούτοις ἦν. ἵνα δὲ μὴ τῶν τόπων ἀγνοουμένων ἀνυπότακτα καὶ κωφὰ γίνηται τὰ λεγόμενα, συνυποδεικτέον ἂν εἴη τὴν φύσιν καὶ τάξιν αὐτῶν, ὃ δὴ καὶ παρ’ ὅλην τὴν πραγματείαν πειρώμεθα ποιεῖν, συνάπτοντες καὶ συνοικειοῦντες ἀεὶ τοὺς ἀγνοουμένους τῶν τόπων τοῖς γνωριζομένοις καὶ παραδιδομένοις. ἐπεὶ γὰρ τῶν κατὰ πόλεμον κινδύνων τοὺς πλείους καὶ κατὰ γῆν καὶ κατὰ θάλατταν σφάλλουσιν αἱ τῶν τόπων διαφοραί, βουλόμεθα δὲ πάντες οὐχ οὕτως τὸ γεγονὸς ὡς τὸ πῶς ἐγένετο γινώσκειν, οὐ παρολιγωρητέον τῆς τῶν τόπων ὑπογραφῆς ἐν οὐδ’ ὁποίᾳ μὲν τῶν πράξεων, ἥκιστα δ’ ἐν ταῖς πολεμικαῖς, οὐδ’ ὀκνητέον ποτὲ μὲν λιμέσι καὶ πελάγεσι καὶ νήσοις συγχρῆσθαι σημείοις, ποτὲ δὲ πάλιν ἱεροῖς, ὄρεσι, χώραις ἐπωνύμοις, τὸ δὲ τελευταῖον ταῖς ἐκ τοῦ περιέχοντος διαφοραῖς, ἐπειδὴ κοινόταται πᾶσιν ἀνθρώποις εἰσὶν αὗται· μόνως γὰρ οὕτως δυνατὸν εἰς ἔννοιαν ἀγαγεῖν τῶν ἀγνοουμένων τοὺς ἀκούοντας, καθάπερ καὶ πρότερον εἰρήκαμεν. ἔστι δ’ ἡ τῶν τόπων φύσις τοιαύτη [ὑπὲρ ὧν νῦν δὴ ὁ λόγος].", "st": "5.21"}, {"sp": "N", "t": "τῆς γὰρ Σπάρτης τῷ μὲν καθόλου σχήματι περιφεροῦς ὑπαρχούσης καὶ κειμένης ἐν τόποις ἐπιπέδοις, κατὰ μέρος δὲ περιεχούσης ἐν αὑτῇ διαφόρους ἀνωμάλους καὶ βουνώδεις τόπους, τοῦ δὲ ποταμοῦ παραρρέοντος ἐκ τῶν πρὸς ἀνατολὰς αὐτῆς μερῶν, ὃς καλεῖται μὲν Εὐρώτας, γίνεται δὲ τὸν πλείω χρόνον ἄβατος διὰ τὸ μέγεθος, συμβαίνει τοὺς βουνοὺς ἐφ’ ὧν τὸ Μενελάιόν ἐστι πέραν μὲν εἶναι τοῦ ποταμοῦ, κεῖσθαι δὲ τῆς πόλεως κατὰ χειμερινὰς ἀνατολάς, ὄντας τραχεῖς καὶ δυσβάτους καὶ διαφερόντως ὑψηλούς, ἐπικεῖσθαι δὲ τῷ πρὸς τὴν πόλιν τοῦ ποταμοῦ διαστήματι κυρίως, δι’ οὗ φέρεται μὲν ὁ προειρημένος ποταμὸς παρ’ αὐτὴν τὴν τοῦ λόφου ῥίζαν, ἔστι δ’ οὐ πλεῖον τὸ πᾶν διάστημα τριῶν ἡμισταδίων· δι’ οὗ τὴν ἀνακομιδὴν ἔδει ποιεῖσθαι κατ’ ἀνάγκην τὸν Φίλιππον, ἐκ μὲν εὐωνύμων ἔχοντα τὴν πόλιν καὶ τοὺς Λακεδαιμονίους ἑτοίμους καὶ παρατεταγμένους, ἐκ δὲ δεξιῶν τόν τε ποταμὸν καὶ τοὺς περὶ τὸν Λυκοῦργον ἐπὶ τῶν λόφων ἐφεστῶτας. ἐμεμηχάνηντο δέ τι πρὸς τοῖς ὑπάρχουσι καὶ τοιοῦτον οἱ Λακεδαιμόνιοι· φράξαντες γὰρ τὸν ποταμὸν ἄνωθεν ἐπὶ τὸν μεταξὺ τόπον τῆς πόλεως καὶ τῶν βουνῶν ἐφῆκαν, οὗ διαβρόχου γενηθέντος, οὐχ οἷον τοὺς ἵππους, ἀλλ’ οὐδ’ ἂν τοὺς πεζοὺς δυνατὸν ἦν ἐμβαίνειν. διόπερ ἀπελείπετο παρ’ αὐτὴν τὴν παρώρειαν ὑπὸ τοὺς λόφους τὴν δύναμιν ἄγοντας δυσπαραβοηθήτους καὶ μακροὺς αὑτοὺς ἐν πορείᾳ παραδιδόναι τοῖς πολεμίοις. εἰς ἃ βλέπων ὁ Φίλιππος, καὶ βουλευσάμενος μετὰ τῶν φίλων, ἀναγκαιότατον ἔκρινε τῶν παρόντων τὸ τρέψασθαι πρώτους τοὺς περὶ τὸν Λυκοῦργον ἀπὸ τῶν κατὰ τὸ Μενελάιον τόπων. ἀναλαβὼν οὖν τούς τε μισθοφόρους καὶ τοὺς πελταστάς, ἐπὶ δὲ τούτοις καὶ τοὺς Ἰλλυριούς, προῆγε διαβὰς τὸν ποταμὸν ὡς ἐπὶ τοὺς λόφους. ὁ δὲ Λυκοῦργος, συνθεωρῶν τὴν ἐπίνοιαν τοῦ Φιλίππου, τοὺς μὲν μεθ’ ἑαυτοῦ στρατιώτας ἡτοίμαζε καὶ παρεκάλει πρὸς τὸν κίνδυνον, τοῖς δ’ ἐν τῇ πόλει τὸ σημεῖον ἀνέφηνεν. οὗ γενομένου παραυτίκα τοὺς πολιτικούς, οἷς ἐπιμελὲς ἦν, ἐξῆγον κατὰ τὸ συντεταγμένον πρὸ τοῦ τείχους, ποιοῦντες ἐπὶ τοῦ δεξιοῦ κέρατος τοὺς ἱππεῖς.", "st": "5.22"}, {"sp": "N", "t": "ὁ δὲ Φίλιππος ἐγγίσας τοῖς περὶ τὸν Λυκοῦργον τὸ μὲν πρῶτον αὐτοὺς ἐφῆκε τοὺς μισθοφόρους, ἐξ οὗ καὶ συνέβη τὰς ἀρχὰς ἐπικυδεστέρως ἀγωνίζεσθαι τοὺς παρὰ τῶν Λακεδαιμονίων, ἅτε καὶ τοῦ καθοπλισμοῦ καὶ τῶν τόπων αὐτοῖς οὐ μικρὰ συμβαλλομένων. ἐπεὶ δὲ τοὺς μὲν πελταστὰς ὁ Φίλιππος ὑπέβαλε τοῖς ἀγωνιζομένοις, ἐφεδρείας ἔχοντας τάξιν, τοῖς δ’ Ἰλλυριοῖς ὑπεράρας ἐκ πλαγίων ἐποιεῖτο τὴν ἔφοδον, τότε συνέβη τοὺς μὲν παρὰ τοῦ Φιλίππου μισθοφόρους ἐπαρθέντας τῇ τῶν Ἰλλυριῶν καὶ πελταστῶν ἐφεδρείᾳ πολλαπλασίως ἐπιρρωσθῆναι πρὸς τὸν κίνδυνον, τοὺς δὲ παρὰ τοῦ Λυκούργου, καταπλαγέντας τὴν τῶν βαρέων ὅπλων ἔφοδον, ἐγκλίναντας φυγεῖν. ἔπεσον μὲν οὖν αὐτῶν εἰς ἑκατόν, ἑάλωσαν δὲ μικρῷ πλείους· οἱ δὲ λοιποὶ διέφυγον εἰς τὴν πόλιν. ὁ δὲ Λυκοῦργος αὐτὸς ταῖς ἀνοδίαις ὁρμήσας νύκτωρ μετ’ ὀλίγων ἐποιήσατο τὴν εἰς πόλιν πάροδον. Φίλιππος δὲ τοὺς μὲν λόφους τοῖς Ἰλλυριοῖς κατελάβετο, τοὺς δ’ εὐζώνους ἔχων καὶ πελταστὰς ἐπανῄει πρὸς τὴν δύναμιν. Ἄρατος δὲ κατὰ τὸν καιρὸν τοῦτον, ἄγων ἐκ τῶν Ἀμυκλῶν τὴν φάλαγγα, σύνεγγυς ἦν ἤδη τῆς πόλεως. ὁ μὲν οὖν βασιλεὺς διαβὰς τὸν ποταμὸν ἐφήδρευε τοῖς εὐζώνοις καὶ πελτασταῖς, ἔτι δὲ τοῖς ἱππεῦσιν, ἕως τὰ βαρέα τῶν ὅπλων ὑπ’ αὐτοὺς τοὺς βουνοὺς ἀσφαλῶς διῄει τὰς δυσχωρίας. τῶν δ’ ἐκ τῆς πόλεως ἐπιβαλομένων ἐγχειρεῖν τοῖς ἐφεδρεύουσι τῶν ἱππέων, καὶ γενομένης συμπλοκῆς ὁλοσχερεστέρας, καὶ τῶν πελταστῶν εὐψύχως ἀγωνισαμένων, καὶ περὶ τοῦτον τὸν καιρὸν ὁ Φίλιππος ὁμολογούμενον προτέρημα ποιήσας, καὶ συνδιώξας τοὺς τῶν Λακεδαιμονίων ἱππεῖς εἰς τὰς πύλας, μετὰ ταῦτα διαβὰς ἀσφαλῶς τὸν Εὐρώταν ἀπουράγει τοῖς αὑτοῦ φαλαγγίταις", "st": "5.23"}, {"sp": "N", "t": "ἤδη δὲ τῆς ὥρας συναγούσης, ἀπαναγκαζόμενος αὐτοῦ στρατοπεδεύειν, περὶ τὴν ἐκ τῶν στενῶν ἔξοδον ἐχρήσατο στρατοπεδείᾳ, κατὰ σύμπτωμα τῶν ἡγεμόνων περιβαλομένων τοιοῦτον τόπον οἷον οὐκ ἂν ἄλλον τις εὕροι βουλόμενος εἰς τὴν χώραν τῆς Λακωνικῆς παρ’ αὐτὴν τὴν πόλιν ποιεῖσθαι τὴν εἰσβολήν. ἔστι γὰρ ἐπὶ τῆς ἀρχῆς τῶν προειρημένων στενῶν, ὅταν ἀπὸ τῆς Τεγέας ἢ καθόλου τῆς μεσογαίου παραγινόμενος ἐγγίζῃ τις τῇ Λακεδαίμονι, τόπος ἀπέχων μὲν τῆς πόλεως δύο μάλιστα σταδίους, ἐπ’ αὐτοῦ δὲ κείμενος τοῦ ποταμοῦ. τούτου δὲ συμβαίνει τὴν μὲν ἐπὶ τὴν πόλιν καὶ τὸν ποταμὸν βλέπουσαν πλευρὰν περιέχεσθαι πᾶσαν ἀπορρῶγι μεγάλῃ καὶ παντελῶς ἀπροσίτῳ· τὸ δ’ ἐπὶ τοῖς κρημνοῖς τούτοις χωρίον ἐπίπεδόν ἐστι καὶ γεῶδες καὶ κάθυγρον, ἅμα δὲ καὶ πρὸς τὰς εἰσαγωγὰς καὶ τὰς ἐξαγωγὰς τῶν δυνάμεων εὐφυῶς κείμενον, ὥστε τὸν στρατοπεδεύσαντα ἐν αὐτῷ καὶ κατασχόντα τὸν ὑπερκείμενον λόφον δοκεῖν μὲν ἐν ἀσφαλεῖ στρατοπεδεύειν διὰ τὴν παράθεσιν τῆς πόλεως, στρατοπεδεύειν δ’ ἐν καλλίστῳ, κρατοῦντα τῆς εἰσόδου καὶ τῆς διόδου τῶν στενῶν. πλὴν ὅ γε Φίλιππος, καταστρατοπεδεύσας ἐν τούτῳ μετ’ ἀσφαλείας, τῇ κατὰ πόδας ἡμέρᾳ τὴν μὲν ἀποσκευὴν προαπέστειλε, τὴν δὲ δύναμιν ἐξέταξεν ἐν τοῖς ἐπιπέδοις εὐσύνοπτον τοῖς ἐκ τῆς πόλεως. χρόνον μὲν οὖν τινα βραχὺν ἔμεινε, μετὰ δὲ ταῦτα κλίνας ἐπὶ κέρας ἦγε ποιούμενος τὴν πορείαν ὡς ἐπὶ Τεγέαν. συνάψας δὲ τοῖς τόποις ἐν οἷς Ἀντίγονος καὶ Κλεομένης συνεστήσαντο τὸν κίνδυνον, αὐτοῦ κατεστρατοπέδευσε. τῇ δ’ ἑξῆς θεασάμενος τοὺς τόπους καὶ θύσας τοῖς θεοῖς ἐφ’ ἑκατέρου τῶν λόφων, ὧν ὁ μὲν Ὄλυμπος, ὁ δ’ Εὔας καλεῖται, μετὰ ταῦτα προῆγε, στερροποιησάμενος τὴν οὐραγίαν. ἀφικόμενος δ’ εἰς Τεγέαν καὶ λαφυροπωλήσας πᾶσαν τὴν λείαν, καὶ μετὰ ταῦτα ποιησάμενος δι’ Ἄργους τὴν πορείαν, ἧκε μετὰ τῆς δυνάμεως εἰς Κόρινθον. παρόντων δὲ πρεσβευτῶν παρά τε Ῥοδίων καὶ Χίων περὶ διαλύσεως τοῦ πολέμου, χρηματίσας τούτοις καὶ συνυποκριθεὶς καὶ φήσας ἕτοιμος εἶναι διαλύεσθαι καὶ νῦν καὶ πάλαι πρὸς Αἰτωλούς, τούτους μὲν ἐξέπεμπε, διαλέγεσθαι κελεύσας καὶ τοῖς Αἰτωλοῖς περὶ τῆς διαλύσεως, αὐτὸς δὲ καταβὰς εἰς τὸ Λέχαιον ἐγίνετο περὶ πλοῦν, ἔχων τινὰς πράξεις ὁλοσχερεστέρας ἐν τοῖς περὶ Φωκίδα τόποις.", "st": "5.24"}, {"sp": "N", "t": "κατὰ δὲ τὸν καιρὸν τοῦτον οἱ περὶ τὸν Λεόντιον καὶ Μεγαλέαν καὶ Πτολεμαῖον, ἔτι πεπεισμένοι καταπλήξεσθαι τὸν Φίλιππον καὶ λύειν τῷ τοιούτῳ τρόπῳ τὰς προγεγενημένας ἁμαρτίας, ἐνέβαλον λόγους εἴς τε τοὺς πελταστὰς καὶ τοὺς ἐκ τοῦ λεγομένου παρὰ τοῖς Μακεδόσιν ἀγήματος, ὅτι κινδυνεύουσι μὲν ὑπὲρ πάντων, γίνεται δ’ αὐτοῖς οὐδὲν τῶν δικαίων οὐδὲ κομίζονται τελείας τὰς ὠφελείας τὰς γινομένας αὐτοῖς ἐκ τῶν ἐθισμῶν. δι’ ὧν παρώξυναν τοὺς νεανίσκους συστραφέντας ἐγχειρῆσαι διαρπάζειν μὲν τὰς τῶν ἐπιφανεστάτων φίλων καταλύσεις, ἐκβάλλειν δὲ τὰς θύρας καὶ κατακόπτειν τὸν κέραμον τῆς τοῦ βασιλέως αὐλῆς. τούτων δὲ συμβαινόντων, καὶ τῆς πόλεως ὅλης ἐν θορύβῳ καὶ ταραχῇ καθεστώσης, ἀκούσας ὁ Φίλιππος, ἧκε μετὰ σπουδῆς ἐκ τοῦ Λεχαίου θέων εἰς τὴν πόλιν. καὶ συναγαγὼν εἰς τὸ θέατρον τοὺς Μακεδόνας τὰ μὲν παρεκάλει, τὰ δ’ ἐπέπληττε πᾶσιν ἐπὶ τοῖς πεπραγμένοις. θορύβου δ’ ὄντος καὶ πολλῆς ἀκρισίας, καὶ τῶν μὲν οἰομένων δεῖν ἄγειν καὶ καταλεύειν τοὺς αἰτίους, τῶν δὲ διαλύεσθαι καὶ μηδενὶ μνησικακεῖν, τότε μὲν ὑποκριθεὶς ὡς πεπεισμένος καὶ παρακαλέσας πάντας ἐπανῆλθε, σαφῶς μὲν εἰδὼς τοὺς ἀρχηγοὺς τῆς κινήσεως γεγονότας, οὐ προσποιηθεὶς δὲ διὰ τὸν καιρόν.", "st": "5.25"}, {"sp": "N", "t": "μετὰ δὲ τὴν ταραχὴν ταύτην αἱ μὲν ἐν τῇ Φωκίδι προφανεῖσαι πράξεις ἐμποδισμούς τινας ἔσχον· οἱ δὲ περὶ τὸν Λεόντιον, ἀπεγνωκότες τὰς ἐν αὑτοῖς ἐλπίδας διὰ τὸ μηδὲν σφίσι προχωρεῖν τῶν ἐπινοουμένων, κατέφευγον ἐπὶ τὸν Ἀπελλῆν καὶ διαπεμπόμενοι συνεχῶς ἐκάλουν αὐτὸν ἐκ τῆς Χαλκίδος, ἀπολογιζόμενοι τὴν περὶ σφᾶς ἀπορίαν καὶ δυσχρηστίαν ἐκ τῆς πρὸς τὸν βασιλέα διαφορᾶς. συνέβαινε δὲ τὸν Ἀπελλῆν πεποιῆσθαι τὴν ἐν τῇ Χαλκίδι διατριβὴν ἐξουσιαστικώτερον τοῦ καθήκοντος αὐτῷ· τὸν μὲν γὰρ βασιλέα, νέον ἔτι καὶ τὸ πλεῖον ὑφ’ αὑτὸν ὄντα καὶ μηδενὸς κύριον ἀπεδείκνυε, τὸν δὲ τῶν πραγμάτων χειρισμὸν καὶ τὴν τῶν ὅλων ἐξουσίαν εἰς αὑτὸν ἐπανῆγε. διόπερ οἵ τ’ ἀπὸ Μακεδονίας καὶ Θετταλίας ἐπιστάται καὶ χειρισταὶ τὴν ἀναφορὰν ἐποιοῦντο πρὸς ἐκεῖνον, αἵ τε κατὰ τὴν Ἑλλάδα πόλεις ἐν τοῖς ψηφίσμασι καὶ τιμαῖς καὶ δωρεαῖς ἐπὶ βραχὺ μὲν ἐμνημόνευον τοῦ βασιλέως, τὸ δ’ ὅλον αὐτοῖς ἦν καὶ τὸ πᾶν Ἀπελλῆς. ἐφ’ οἷς Φίλιππος πυνθανόμενος πάλαι μὲν ἐσχετλίαζε καὶ δυσχερῶς ἔφερε τὸ γινόμενον, ἅτε καὶ παρὰ πλευρὰν ὄντος Ἀράτου καὶ πραγματικῶς ἐξεργαζομένου τὴν ὑπόθεσιν· ἀλλ’ ἐκαρτέρει καὶ πᾶσιν ἄδηλος ἦν ἐπὶ τί φέρεται καὶ ἐπὶ ποίας ὑπάρχει γνώμης. ὁ δ’ Ἀπελλῆς, ἀγνοῶν τὰ καθ’ αὑτόν, πεπεισμένος δ’, ἐὰν εἰς ὄψιν ἔλθῃ τῷ Φιλίππῳ, πάντα κατὰ τὴν ἑαυτοῦ γνώμην διοικήσειν, ὥρμησε τοῖς περὶ τὸν Λεόντιον ἐπικουρήσων ἐκ τῆς Χαλκίδος. παραγενομένου δ’ εἰς τὴν Κόρινθον αὐτοῦ, μεγάλην σπουδὴν ἐποιοῦντο καὶ παρώξυνον τοὺς νέους εἰς τὴν ἀπάντησιν οἱ περὶ τὸν Λεόντιον καὶ Πτολεμαῖον καὶ Μεγαλέαν, ὄντες ἡγεμόνες τῶν τε πελταστῶν καὶ τῶν ἄλλων τῶν ἐπιφανεστάτων συστημάτων. γενομένης δὲ τῆς εἰσόδου τραγικῆς διὰ τὸ πλῆθος τῶν ἀπαντησάντων ἡγεμόνων καὶ στρατιωτῶν, ἧκε πρὸς τὴν αὐλὴν ὁ προειρημένος εὐθέως ἐκ πορείας. βουλομένου δ’ αὐτοῦ κατὰ τὴν προγεγενημένην συνήθειαν εἰσιέναι, παρακατέσχε τις τῶν ῥαβδούχων κατὰ τὸ συντεταγμένον, φήσας οὐκ εὐκαίρως ἔχειν τὸν βασιλέα. ξενισθεὶς δὲ καὶ διαπορήσας ἐπὶ πολὺν χρόνον διὰ τὸ παράδοξον ὁ μὲν Ἀπελλῆς ἐπανῆγε διατετραμμένος, οἱ δὲ λοιποὶ παραχρῆμα πάντες ἀπέρρεον ἀπ’ αὐτοῦ προφανῶς, ὥστε τὸ τελευταῖον μόνον μετὰ τῶν ἰδίων παίδων εἰσελθεῖν εἰς τὴν αὑτοῦ κατάλυσιν. βραχεῖς γὰρ δὴ πάνυ καιροὶ πάντας μὲν ἀνθρώπους ὡς ἐπίπαν ὑψοῦσι καὶ πάλιν ταπεινοῦσι, μάλιστα δὲ τοὺς ἐν ταῖς βασιλείαις. ὄντως γάρ εἰσιν οὗτοι παραπλήσιοι ταῖς ἐπὶ τῶν ἀβακίων ψήφοις· ἐκεῖναί τε γὰρ κατὰ τὴν τοῦ ψηφίζοντος βούλησιν ἄρτι χαλκοῦν καὶ παραυτίκα τάλαντον ἰσχύουσιν, οἵ τε περὶ τὰς αὐλὰς κατὰ τὸ τοῦ βασιλέως νεῦμα μακάριοι καὶ παρὰ πόδας ἐλεεινοὶ γίνονται. ὁ δὲ Μεγαλέας, ὁρῶν παρὰ δόξαν ἐκβαίνουσαν αὑτοῖς τὴν ἐπικουρίαν τὴν κατὰ τὸν Ἀπελλῆν, φόβου πλήρης ἦν καὶ περὶ δρασμὸν ἐγένετο. ὁ δ’ Ἀπελλῆς ἐπὶ μὲν τὰς συνουσίας καὶ τοιαῦτα τῶν τιμῶν παρελαμβάνετο, τῶν δὲ διαβουλίων καὶ τῆς μεθ’ ἡμέραν συμπεριφορᾶς οὐ μετεῖχε. ταῖς δ’ ἑξῆς ἡμέραις ὁ βασιλεὺς ἐπὶ τὰς κατὰ τὴν Φωκίδα πράξεις πάλιν ἐκ τοῦ Λεχαίου ποιούμενος τὸν πλοῦν ἐπεσπάσατο τὸν Ἀπελλῆν. διαπεσούσης δ’ αὐτῷ τῆς ἐπιβολῆς, οὗτος μὲν αὖτις ἐξ", "st": "5.26"}, {"sp": "N", "t": "Ἐλατείας ἀνέστρεφε, κατὰ δὲ τὸν καιρὸν τοῦτον ὁ Μεγαλέας εἰς τὰς Ἀθήνας ἀπεχώρησε, καταλιπὼν τὸν Λεόντιον ἐν ἐγγύῃ τῶν εἴκοσι ταλάντων. τῶν δ’ ἐν ταῖς Ἀθήναις στρατηγῶν οὐ προσδεξαμένων αὐτόν, μετῆλθε πάλιν εἰς τὰς Θήβας. ὁ δὲ βασιλεὺς ἀναχθεὶς ἐκ τῶν κατὰ Κίρραν τόπων κατέπλευσε μετὰ τῶν ὑπασπιστῶν εἰς τὸν τῶν Σικυωνίων λιμένα, κἀκεῖθεν ἀναβὰς εἰς τὴν πόλιν τοὺς μὲν ἄρχοντας παρῃτήσατο, παρὰ δ’ Ἄρατον καταλύσας μετὰ τούτου τὴν πᾶσαν ἐποιεῖτο διαγωγήν, τῷ δ’ Ἀπελλῇ συνέταξε πλεῖν εἰς Κόρινθον. προσπεσόντων δὲ τῶν κατὰ τὸν Μεγαλέαν αὐτῷ, τοὺς μὲν πελταστάς, ὧν ἡγεῖτο Λεόντιος, εἰς τὴν Τριφυλίαν ἐξαπέστειλε μετὰ Ταυρίωνος, ὥς τινος χρείας κατεπειγούσης, τούτων δ’ ἀφορμησάντων, ἀπαγαγεῖν ἐκέλευσε τὸν Λεόντιον πρὸς τὴν ἀναδοχήν. συνέντες δ’ οἱ πελτασταὶ τὸ γεγονός, διαπεμψαμένου τινὰ πρὸς αὐτοὺς τοῦ Λεοντίου, πρεσβευτὰς ἐξαπέστειλαν πρὸς τὸν βασιλέα, παρακαλοῦντες, εἰ μὲν πρὸς ἄλλο τι πεποίηται τὴν ἀπαγωγὴν τοῦ Λεοντίου, μὴ χωρὶς αὑτῶν ποιήσασθαι τὴν ὑπὲρ τῶν ἐγκαλουμένων κρίσιν, εἰ δὲ μή, ὅτι νομιοῦσι μεγαλείως παρολιγωρεῖσθαι καὶ καταγινώσκεσθαι πάντες — εἶχον γὰρ ἀεὶ τὴν τοιαύτην ἰσηγορίαν Μακεδόνες πρὸς τοὺς βασιλεῖς — εἰ δὲ πρὸς τὴν ἐγγύην τοῦ Μεγαλέου, διότι τὰ χρήματα κατὰ κοινὸν εἰσενέγκαντες ἐκτίσουσιν αὐτοί. τὸν μὲν οὖν Λεόντιον ὁ βασιλεὺς παροξυνθεὶς θᾶττον ἢ προέθετο διὰ τὴν τῶν πελταστῶν φιλοτιμίαν ἐπανείλετο.", "st": "5.27"}, {"sp": "N", "t": "οἱ δὲ παρὰ τῶν Ῥοδίων καὶ Χίων πρέσβεις ἐπανῆκον ἐκ τῆς Αἰτωλίας, ἀνοχάς τε πεποιημένοι τριακονθημέρους, καὶ πρὸς τὰς διαλύσεις ἑτοίμους φάσκοντες εἶναι τοὺς Αἰτωλούς, καὶ τεταγμένοι ῥητὴν ἡμέραν, εἰς ἣν ἠξίουν τὸν Φίλιππον ἀπαντῆσαι πρὸς τὸ Ῥίον, ὑπισχνούμενοι πάντα ποιήσειν τοὺς Αἰτωλοὺς ἐφ’ ᾧ συνθέσθαι τὴν εἰρήνην. ὁ δὲ Φίλιππος, δεξάμενος τὰς ἀνοχάς, τοῖς μὲν συμμάχοις ἔγραψε, διασαφῶν πέμπειν εἰς Πάτρας τοὺς συνεδρεύσοντας καὶ βουλευσομένους ὑπὲρ τῆς πρὸς Αἰτωλοὺς διαλύσεως, αὐτὸς δ’ ἐκ τοῦ Λεχαίου κατέπλευσε δευτεραῖος εἰς τὰς Πάτρας. κατὰ δὲ τὸν καιρὸν τοῦτον ἐπιστολαί τινες ἀνεπέμφθησαν πρὸς αὐτὸν ἐκ τῶν κατὰ τὴν Φωκίδα τόπων, παρὰ τοῦ Μεγαλέα διαπεμπόμεναι πρὸς τοὺς Αἰτωλούς, ἐν αἷς ἦν παράκλησίς τε τῶν Αἰτωλῶν θαρρεῖν καὶ μένειν ἐν τῷ πολέμῳ, διότι τὰ κατὰ τὸν Φίλιππον ἔξω τελέως ἐστὶ διὰ τὴν ἀχορηγησίαν· πρὸς δὲ τούτοις κατηγορίαι τινὲς τοῦ βασιλέως καὶ λοιδορίαι φιλαπεχθεῖς ἦσαν. ἀναγνοὺς δὲ ταύτας, καὶ νομίσας πάντων τῶν κακῶν ἀρχηγὸν εἶναι τὸν Ἀπελλῆν, τοῦτον μὲν εὐθέως φυλακὴν περιστήσας ἐξαπέστειλε μετὰ σπουδῆς εἰς τὸν Κόρινθον, ἅμα δὲ καὶ τὸν υἱὸν αὐτοῦ καὶ τὸν ἐρώμενον, ἐπὶ δὲ τὸν Μεγαλέαν εἰς τὰς Θήβας Ἀλέξανδρον ἔπεμψε, προστάξας ἄγειν αὐτὸν ἐπὶ τὰς ἀρχὰς πρὸς τὴν ἐγγύην. τοῦ δ’ Ἀλεξάνδρου τὸ προσταχθὲν ποιήσαντος, οὐχ ὑπέμεινε τὴν πρᾶξιν ὁ Μεγαλέας, ἀλλ’ αὑτῷ προσήνεγκε τὰς χεῖρας. περὶ δὲ τὰς αὐτὰς ἡμέρας συνέβη καὶ τὸν Ἀπελλῆν μεταλλάξαι τὸν βίον, ἅμα δὲ καὶ τὸν υἱὸν καὶ τὸν ἐρώμενον. οὗτοι μὲν οὖν τῆς ἁρμοζούσης τυχόντες καταστροφῆς ἐξέλιπον τὸν βίον, καὶ μάλιστα διὰ τὴν εἰς Ἄρατον γενομένην ἐξ αὐτῶν ἀσέλγειαν·", "st": "5.28"}, {"sp": "N", "t": "οἱ δ’ Αἰτωλοὶ τὰ μὲν ἔσπευδον ποιήσασθαι τὴν εἰρήνην, πιεζόμενοι τῷ πολέμῳ, καὶ παρὰ δόξαν αὐτοῖς προχωρούντων τῶν πραγμάτων — ἐλπίσαντες γὰρ ὡς παιδίῳ νηπίῳ χρήσασθαι τῷ Φιλίππῳ διά τε τὴν ἡλικίαν καὶ τὴν ἀπειρίαν, τὸν μὲν Φίλιππον εὗρον τέλειον ἄνδρα καὶ κατὰ τὰς ἐπιβολὰς καὶ κατὰ τὰς πράξεις, αὐτοὶ δ’ ἐφάνησαν εὐκαταφρόνητοι καὶ παιδαριώδεις ἔν τε τοῖς κατὰ μέρος καὶ τοῖς καθόλου πράγμασιν — ἅμα δὲ προσπιπτούσης αὐτοῖς τῆς τε περὶ τοὺς πελταστὰς γενομένης ταραχῆς καὶ τῆς τῶν περὶ τὸν Ἀπελλῆν καὶ Λεόντιον ἀπωλείας ἐλπίσαντες μέγα τι καὶ δυσχερὲς κίνημα περὶ τὴν αὐλὴν εἶναι, παρεῖλκον ὑπερτιθέμενοι τὴν ἐπὶ τὸ Ῥίον ταχθεῖσαν ἡμέραν. ὁ δὲ Φίλιππος, ἀσμένως ἐπιλαβόμενος τῆς προφάσεως ταύτης διὰ τὸ θαρρεῖν ἐπὶ τῷ πολέμῳ, καὶ προδιειληφὼς ἀποτρίβεσθαι τὰς διαλύσεις, τότε παρακαλέσας τοὺς ἀπηντηκότας τῶν συμμάχων οὐ τὰ πρὸς διαλύσεις πράττειν, ἀλλὰ τὰ πρὸς τὸν πόλεμον, ἀναχθεὶς αὖτις ἀπέπλευσεν εἰς τὸν Κόρινθον. καὶ τοὺς μὲν Μακεδόνας διὰ Θετταλίας ἀπέλυσε πάντας εἰς τὴν οἰκείαν παραχειμάσοντας, αὐτὸς δ’ ἀναχθεὶς ἐκ Κεγχρεῶν, καὶ παρὰ τὴν Ἀττικὴν κομισθεὶς δι’ Εὐρίπου, κατέπλευσεν εἰς Δημητριάδα· κἀκεῖ Πτολεμαῖον, ὃς ἦν ἔτι λοιπὸς τῆς τῶν περὶ τὸν Λεόντιον ἑταιρείας, κρίνας ἐν τοῖς Μακεδόσιν ἀπέκτεινε. κατὰ δὲ τοὺς καιροὺς τούτους Ἀννίβας μὲν εἰς Ἰταλίαν ἐμβεβληκὼς ἀντεστρατοπέδευε ταῖς τῶν Ῥωμαίων δυνάμεσι περὶ τὸν Πάδον καλούμενον ποταμόν, Ἀντίοχος δὲ τὰ πλεῖστα μέρη Κοίλης Συρίας κατεστραμμένος αὖτις εἰς παραχειμασίαν ἀνέλυσε, Λυκοῦργος δ’ ὁ βασιλεὺς τῶν Λακεδαιμονίων εἰς Αἰτωλίαν ἔφυγε, καταπλαγεὶς τοὺς ἐφόρους. οἱ γὰρ ἔφοροι, προσπεσούσης αὐτοῖς ψευδοῦς διαβολῆς, ὡς μέλλοντος αὐτοῦ νεωτερίζειν, ἁθροίσαντες τοὺς νέους νυκτὸς ἦλθον ἐπὶ τὴν οἰκίαν· ὁ δὲ προαισθόμενος ἐξεχώρησε μετὰ τῶν ἰδίων οἰκετῶν.", "st": "5.29"}, {"sp": "N", "t": "τοῦ δὲ χειμῶνος ἐπιγενομένου, καὶ Φιλίππου μὲν τοῦ βασιλέως εἰς Μακεδονίαν ἀπηλλαγμένου, τοῦ δ’ Ἐπηράτου τοῦ στρατηγοῦ τῶν Ἀχαιῶν καταπεφρονημένου μὲν ὑπὸ τῶν πολιτικῶν νεανίσκων, κατεγνωσμένου δὲ τελέως ὑπὸ τῶν μισθοφόρων, οὔτ’ ἐπειθάρχει τοῖς παραγγελλομένοις οὐδεὶς οὔτ’ ἦν ἕτοιμον οὐδὲν πρὸς τὴν τῆς χώρας βοήθειαν. εἰς ἃ βλέψας Πυρρίας ὁ παρὰ τῶν Αἰτωλῶν ἀπεσταλμένος στρατηγὸς τοῖς Ἠλείοις, ἔχων Αἰτωλῶν εἰς χιλίους καὶ τριακοσίους καὶ τοὺς τῶν Ἠλείων μισθοφόρους, ἅμα δὲ τούτοις πολιτικοὺς πεζοὺς μὲν εἰς χιλίους, ἱππεῖς δὲ διακοσίους, ὥστ’ εἶναι τοὺς πάντας εἰς τρισχιλίους, οὐ μόνον τὴν τῶν Δυμαίων καὶ Φαραιέων συνεχῶς ἐπόρθει χώραν, ἀλλὰ καὶ τὴν τῶν Πατρέων. τὸ δὲ τελευταῖον ἐπὶ τὸ Παναχαϊκὸν ὄρος καλούμενον ἐπιστρατοπεδεύσας, τὸ κείμενον ὑπὲρ τῆς τῶν Πατρέων πόλεως, ἐδῄου πᾶσαν τὴν ἐπὶ τὸ Ῥίον καὶ τὴν ἐπ’ Αἴγιον κεκλιμένην χώραν. λοιπὸν αἱ μὲν πόλεις κακοπαθοῦσαι καὶ μὴ τυγχάνουσαι βοηθείας δυσχερῶς πως εἶχον πρὸς τὰς εἰσφοράς, οἱ δὲ στρατιῶται, τῶν ὀψωνίων παρελκομένων καὶ καθυστερούντων, τὸ παραπλήσιον ἐποίουν περὶ τὰς βοηθείας· ἐξ ἀμφοῖν δὲ τῆς τοιαύτης ἀνταποδόσεως γινομένης, ἐπὶ τὸ χεῖρον προύβαινε τὰ πράγματα καὶ τέλος διελύθη τὸ ξενικόν. πάντα δὲ ταῦτα συνέβαινε γίνεσθαι διὰ τὴν τοῦ προεστῶτος ἀδυναμίαν. ἐν τοιαύτῃ δ’ ὄντων διαθέσει τῶν κατὰ τοὺς Ἀχαιούς, καὶ τῶν χρόνων ἤδη καθηκόντων, Ἐπήρατος μὲν ἀπετίθετο τὴν ἀρχήν, οἱ δ’ Ἀχαιοὶ τῆς θερείας ἐναρχομένης στρατηγὸν αὑτῶν Ἄρατον κατέστησαν τὸν πρεσβύτερον. καὶ τὰ μὲν κατὰ τὴν Εὐρώπην ἐν τούτοις ἦν. ἡμεῖς δ’ ἐπειδὴ κατά τε τὴν τῶν χρόνων διαίρεσιν καὶ κατὰ τὴν τῶν πράξεων περιγραφὴν ἁρμόζοντα τόπον εἰλήφαμεν, μεταβάντες ἐπὶ τὰς κατὰ τὴν Ἀσίαν πράξεις τὰς κατὰ τὴν αὐτὴν ὀλυμπιάδα τοῖς προειρημένοις ἐπιτελεσθείσας αὖτις ὑπὲρ ἐκείνων ποιησόμεθα", "st": "5.30"}, {"sp": "N", "t": "τὴν ἐξήγησιν, καὶ πρῶτον ἐπιχειρήσομεν δηλοῦν κατὰ τὴν ἐξ ἀρχῆς πρόθεσιν τὸν ὑπὲρ Κοίλης Συρίας Ἀντιόχῳ καὶ Πτολεμαίῳ συστάντα πόλεμον, σαφῶς μὲν γινώσκοντες ὅτι κατὰ τὸν καιρὸν τοῦτον, εἰς ὃν ἐλήξαμεν τῶν Ἑλληνικῶν, ὅσον οὔπω κρίνεσθαι συνέβαινε καὶ πέρας λαμβάνειν αὐτόν, αἱρούμενοι δὲ τὴν τοιαύτην ἐπίστασιν καὶ διαίρεσιν τῆς ἐνεστώσης διηγήσεως. τοῦ μὲν γὰρ μὴ τῆς τῶν κατὰ μέρος καιρῶν ἀκριβείας διαμαρτάνειν τοὺς ἀκούοντας ἱκανὴν τοῖς φιλομαθοῦσι πεπείσμεθα παρασκευάζειν ἐμπειρίαν ἐκ τοῦ τὰς ἑκάστων ἀρχὰς καὶ συντελείας παρυπομιμνήσκειν, καθ’ ὁποίους ἐγίνοντο καιροὺς τῆς ὑποκειμένης ὀλυμπιάδος καὶ τῶν Ἑλληνικῶν πράξεων· τὸ δ’ εὐπαρακολούθητον καὶ σαφῆ γίνεσθαι τὴν διήγησιν οὐδὲν ἀναγκαιότερον ἐπὶ ταύτης τῆς ὀλυμπιάδος ἡγούμεθ’ εἶναι τοῦ μὴ συμπλέκειν ἀλλήλαις τὰς πράξεις, ἀλλὰ χωρίζειν καὶ διαιρεῖν αὐτὰς καθ’ ὅσον ἐστὶ δυνατόν, μέχρις ἂν ἐπὶ τὰς ἑξῆς ὀλυμπιάδας ἐλθόντες κατ’ ἔτος ἀρξώμεθα γράφειν τὰς κατάλληλα γενομένας πράξεις. ἐπεὶ γὰρ οὐ τινά, τὰ δὲ παρὰ πᾶσι γεγονότα γράφειν προῃρήμεθα, καὶ σχεδὸν ὡς εἰπεῖν μεγίστῃ τῶν προγεγονότων ἐπιβολῇ κεχρήμεθα τῆς ἱστορίας, καθάπερ καὶ πρότερόν που δεδηλώκαμεν, δέον ἂν εἴη μεγίστην ἡμᾶς ποιεῖσθαι πρόνοιαν καὶ τοῦ χειρισμοῦ καὶ τῆς οἰκονομίας, ἵνα καὶ κατὰ μέρος καὶ καθόλου σαφὲς τὸ σύνταγμα γίνηται τῆς πραγματείας. διὸ καὶ νῦν βραχὺ προσαναδραμόντες περὶ τῆς Ἀντιόχου καὶ Πτολεμαίου βασιλείας πειρασόμεθα λαμβάνειν ἀρχὰς ὁμολογουμένας καὶ γνωριζομένας περὶ τῶν λέγεσθαι μελλόντων, ὅπερ ἐστὶ πάντων ἀναγκαιότατον.", "st": "5.31"}, {"sp": "N", "t": "οἱ μὲν γὰρ ἀρχαῖοι τὴν ἀρχὴν ἥμισυ τοῦ παντὸς εἶναι φάσκοντες μεγίστην παρῄνουν ποιεῖσθαι σπουδὴν ἐν ἑκάστοις ὑπὲρ τοῦ καλῶς ἄρξασθαι· δοκοῦντες δὴ λέγειν ὑπερβολικῶς ἐλλιπέστερόν μοι φαίνονται τῆς ἀληθείας εἰρηκέναι. θαρρῶν γὰρ ἄν τις εἴπειεν οὐχ ἥμισυ τὴν ἀρχὴν εἶναι τοῦ παντός, ἀλλὰ καὶ πρὸς τὸ τέλος διατείνειν. πῶς γὰρ ἄρξασθαί τινος καλῶς οἷόν τε μὴ προπεριλαβόντα τῷ νῷ τὴν συντέλειαν τῆς ἐπιβολῆς μηδὲ γινώσκοντα ποῦ καὶ πρὸς τί καὶ τίνος χάριν ἐπιβάλλεται τοῦτο ποιεῖν; πῶς δὲ πάλιν οἷόν τε συγκεφαλαιώσασθαι πράγματα δεόντως μὴ συναναφέροντα τὴν ἀρχὴν πόθεν ἢ πῶς ἢ διὰ τί πρὸς τὰς ἐνεστώσας ἀφῖκται πράξεις; διόπερ οὐχ ἕως τοῦ μέσου νομίζοντας διατείνειν τὰς ἀρχάς, ἀλλ’ ἕως τοῦ τέλους, πλείστην περὶ ταύτας ποιητέον σπουδὴν καὶ τοὺς λέγοντας καὶ τοὺς ἀκούοντας περὶ τῶν ὅλων. ὃ δὴ καὶ νῦν ἡμεῖς πειρασόμεθα ποιεῖν.", "st": "5.32"}, {"sp": "N", "t": "καίτοι γ’ οὐκ ἀγνοῶ διότι καὶ πλείους ἕτεροι τῶν συγγραφέων τὴν αὐτὴν ἐμοὶ προεῖνται φωνήν, φάσκοντες τὰ καθόλου γράφειν καὶ μεγίστην τῶν προγεγονότων ἐπιβεβλῆσθαι πραγματείαν· περὶ ὧν ἐγώ, παραιτησάμενος Ἔφορον τὸν πρῶτον καὶ μόνον ἐπιβεβλημένον τὰ καθόλου γράφειν, τὸ μὲν πλείω λέγειν ἢ μνημονεύειν τινὸς τῶν ἄλλων ἐπ’ ὀνόματος παρήσω, μέχρι δὲ τούτου μνησθήσομαι, διότι τῶν καθ’ ἡμᾶς τινες γραφόντων ἱστορίαν ἐν τρισὶν ἢ τέτταρσιν ἐξηγησάμενοι σελίσιν ἡμῖν τὸν Ῥωμαίων καὶ Καρχηδονίων πόλεμον φασὶ τὰ καθόλου γράφειν. καίτοι διότι πλεῖσται μὲν καὶ μέγισται τότε περί τε τὴν Ἰβηρίαν καὶ Λιβύην, ἔτι δὲ τὴν Σικελίαν καὶ Ἰταλίαν ἐπετελέσθησαν πράξεις, ἐπιφανέστατος δὲ καὶ πολυχρονιώτατος ὁ κατ’ Ἀννίβαν πόλεμος γέγονε πλὴν τοῦ περὶ Σικελίαν, πάντες δ’ ἠναγκάσθημεν πρὸς αὐτὸν ἀποβλέπειν διὰ τὸ μέγεθος, δεδιότες τὴν συντέλειαν τῶν ἀποβησομένων, τίς οὕτως ἐστὶν ἀδαὴς ὃς οὐκ οἶδεν; ἀλλ’ ἔνιοι τῶν πραγματευομένων οὐδ’ ἐφ’ ὅσον οἱ τὰ κατὰ καιροὺς ἐν ταῖς χρονογραφίαις ὑπομνηματιζόμενοι πολιτικῶς εἰς τοὺς τοίχους, οὐδ’ ἐπὶ τοσοῦτο μνησθέντες, πάσας φασὶ τὰς κατὰ τὴν Ἑλλάδα καὶ βάρβαρον περιειληφέναι πράξεις. τοῦτο δ’ ἐστὶν αἴτιον, ὅτι τὸ μὲν τῷ λόγῳ τῶν μεγίστων ἔργων ἀντιποιήσασθαι τελείως ἐστὶ ῥᾴδιον, τὸ δὲ τοῖς πράγμασιν ἐφικέσθαι τινὸς τῶν καλῶν οὐκ εὐμαρές. διὸ καὶ τὸ μὲν ἐν μέσῳ κεῖται καὶ πᾶσι κοινὸν ὡς ἔπος εἰπεῖν τοῖς μόνον τολμᾶν δυναμένοις ὑπάρχει, τὸ δὲ καὶ λίαν ἐστὶ σπάνιον καὶ σπανίοις συνεξέδραμε κατὰ τὸν βίον. ταῦτα μὲν οὖν προήχθην εἰπεῖν χάριν τῆς ἀλαζονείας τῶν ὑπερηφανούντων ἑαυτοὺς καὶ τὰς ἰδίας πραγματείας· ἐπὶ δὲ τὴν ἀρχὴν ἐπάνειμι τῆς ἐμαυτοῦ προθέσεως.", "st": "5.33"}, {"sp": "N", "t": "ὡς γὰρ θᾶττον Πτολεμαῖος ὁ κληθεὶς Φιλοπάτωρ, μεταλλάξαντος τοῦ πατρός, ἐπανελόμενος τὸν ἀδελφὸν Μάγαν καὶ τοὺς τούτῳ συνεργοῦντας παρέλαβε τὴν τῆς Αἰγύπτου δυναστείαν, νομίσας τῶν μὲν οἰκείων φόβων ἀπολελύσθαι δι’ αὑτοῦ καὶ διὰ τῆς προειρημένης πράξεως, τῶν δ’ ἐκτὸς κινδύνων ἀπηλλάχθαι διὰ τὴν τύχην, Ἀντιγόνου μὲν καὶ Σελεύκου μετηλλαχότων, Ἀντιόχου δὲ καὶ Φιλίππου τῶν διαδεδεγμένων τὰς ἀρχὰς παντάπασι νέων καὶ μόνον οὐ παίδων ὑπαρχόντων, καταπιστεύσας διὰ ταῦτα τοῖς παροῦσι καιροῖς, πανηγυρικώτερον διῆγε τὰ κατὰ τὴν ἀρχήν, ἀνεπίστατον μὲν καὶ δυσέντευκτον αὑτὸν παρασκευάζων τοῖς περὶ τὴν αὐλὴν καὶ τοῖς ἄλλοις τοῖς τὰ κατὰ τὴν Αἴγυπτον χειρίζουσιν, ὀλίγωρον δὲ καὶ ῥᾴθυμον ὑποδεικνύων τοῖς ἐπὶ τῶν ἔξω πραγμάτων διατεταγμένοις, ὑπὲρ ὧν οἱ πρότερον οὐκ ἐλάττω, μείζω δ’ ἐποιοῦντο σπουδὴν ἢ περὶ τῆς κατ’ αὐτὴν τὴν Αἴγυπτον δυναστείας. τοιγαροῦν ἐπέκειντο μὲν τοῖς τῆς Συρίας βασιλεῦσι καὶ κατὰ γῆν καὶ κατὰ θάλατταν, Κοίλης Συρίας καὶ Κύπρου κυριεύοντες· παρέκειντο δὲ τοῖς κατὰ τὴν Ἀσίαν δυνάσταις, ὁμοίως δὲ καὶ ταῖς νήσοις, δεσπόζοντες τῶν ἐπιφανεστάτων πόλεων καὶ τόπων καὶ λιμένων κατὰ πᾶσαν τὴν παραλίαν ἀπὸ Παμφυλίας ἕως Ἑλλησπόντου καὶ τῶν κατὰ Λυσιμάχειαν τόπων· ἐφήδρευον δὲ τοῖς ἐν τῇ Θρᾴκῃ καὶ τοῖς ἐν Μακεδονίᾳ πράγμασι, τῶν κατ’ Αἶνον καὶ Μαρώνειαν καὶ πορρώτερον ἔτι πόλεων κυριεύοντες. καὶ τῷ τοιούτῳ τρόπῳ μακρὰν ἐκτετακότες τὰς χεῖρας, καὶ προβεβλημένοι πρὸ αὑτῶν ἐκ πολλοῦ τὰς δυναστείας, οὐδέποτε περὶ τῆς κατ’ Αἴγυπτον ἠγωνίων ἀρχῆς. διὸ καὶ τὴν σπουδὴν εἰκότως μεγάλην ἐποιοῦντο περὶ τῶν ἔξω πραγμάτων. ὁ δὲ προειρημένος βασιλεὺς ὀλιγώρως ἕκαστα τούτων χειρίζων διὰ τοὺς ἀπρεπεῖς ἔρωτας καὶ τὰς ἀλόγους καὶ συνεχεῖς μέθας, εἰκότως ἐν πάνυ βραχεῖ χρόνῳ καὶ τῆς ψυχῆς ἅμα καὶ τῆς ἀρχῆς ἐπιβούλους εὗρε καὶ πλείους, ὧν ἐγένετο πρῶτος Κλεομένης ὁ Σπαρτιάτης.", "st": "5.34"}, {"sp": "N", "t": "οὗτος γάρ, ἕως μὲν ὁ προσαγορευόμενος Εὐεργέτης ἔζη, πρὸς ὃν ἐποιήσατο τὴν κοινωνίαν τῶν πραγμάτων καὶ τὰς πίστεις, ἦγε τὴν ἡσυχίαν, πεπεισμένος ἀεὶ δι’ ἐκείνου τεύξεσθαι τῆς καθηκούσης ἐπικουρίας εἰς τὸ τὴν πατρῴαν ἀνακτήσασθαι βασιλείαν· ἐπεὶ δ’ ἐκεῖνος μὲν μετήλλαξε, προῄει δ’ ὁ χρόνος, οἱ δὲ κατὰ τὴν Ἑλλάδα καιροὶ μόνον οὐκ ἐπ’ ὀνόματος ἐκάλουν τὸν Κλεομένην, μετηλλαχότος μὲν Ἀντιγόνου, πολεμουμένων δὲ τῶν Ἀχαιῶν, κοινωνούντων δὲ τῶν Λακεδαιμονίων Αἰτωλοῖς τῆς πρὸς Ἀχαιοὺς καὶ Μακεδόνας ἀπεχθείας κατὰ τὴν ἐξ ἀρχῆς ἐπιβολὴν καὶ πρόθεσιν τὴν Κλεομένους, τότε δὴ καὶ μᾶλλον ἠναγκάζετο σπεύδειν καὶ φιλοτιμεῖσθαι περὶ τῆς ἐξ Ἀλεξανδρείας ἀπαλλαγῆς. διόπερ τὸ μὲν πρῶτον ἐντεύξεις ἐποιεῖτο, παρακαλῶν μετὰ χορηγίας τῆς καθηκούσης καὶ δυνάμεως αὐτὸν ἐκπέμψαι, μετὰ δὲ ταῦτα παρακουόμενος ἠξίου μετὰ δεήσεως μόνον αὐτὸν ἀπολῦσαι μετὰ τῶν ἰδίων οἰκετῶν· τοὺς γὰρ καιροὺς ἱκανὰς ὑποδεικνύειν ἀφορμὰς αὐτῷ πρὸς τὸ καθικέσθαι τῆς πατρῴας ἀρχῆς. ὁ μὲν οὖν βασιλεύς, οὔτ’ ἐφιστάνων [ἐν] οὐδενὶ τῶν τοιούτων οὔτε προνοούμενος τοῦ μέλλοντος διὰ τὰς προειρημένας αἰτίας, εὐήθως καὶ ἀλόγως ἀεὶ παρήκουε τοῦ Κλεομένους. οἱ δὲ περὶ τὸν Σωσίβιον — οὗτος γὰρ μάλιστα τότε προεστάτει τῶν πραγμάτων — συνεδρεύσαντες τοιαύτας τινὰς ἐποιήσαντο περὶ αὐτοῦ διαλήψεις. μετὰ μὲν γὰρ στόλου καὶ χορηγίας ἐκπέμπειν αὐτὸν οὐκ ἔκρινον, καταφρονοῦντες τῶν ἔξω πραγμάτων διὰ τὸ μετηλλαχέναι τὸν Ἀντίγονον καὶ νομίζειν μάταιον αὑτοῖς ἔσεσθαι τὴν εἰς ταῦτα δαπάνην. πρὸς δὲ τούτοις ἠγωνίων μή ποτε μετηλλαχότος μὲν Ἀντιγόνου, τῶν δὲ λοιπῶν μηδενὸς ὑπάρχοντος ἀντιπάλου, ταχέως ἀκονιτὶ τὰ κατὰ τὴν Ἑλλάδα ποιησάμενος ὑφ’ αὑτὸν βαρὺς καὶ φοβερὸς αὐτὸς ὁ Κλεομένης ἀνταγωνιστὴς σφίσι γένηται, τεθεαμένος μὲν ὑπ’ αὐγὰς αὐτῶν τὰ πράγματα, κατεγνωκὼς δὲ τοῦ βασιλέως, θεωρῶν δὲ πολλὰ τὰ παρακρεμάμενα μέρη καὶ μακρὰν ἀπεσπασμένα τῆς βασιλείας καὶ πολλὰς ἀφορμὰς ἔχοντα πρὸς πραγμάτων λόγον· καὶ γὰρ ναῦς ἐν τοῖς κατὰ Σάμον ἦσαν τόποις οὐκ ὀλίγαι καὶ στρατιωτῶν πλῆθος ἐν τοῖς κατ’ Ἔφεσον. διὰ ταῦτα μὲν οὖν τὴν ἐπιβολήν, ὥστ’ ἐκπέμπειν αὐτὸν μετὰ χορηγίας, ἀπεδοκίμασαν διὰ τὰς προειρημένας αἰτίας· τό γε μὴν ὀλιγωρήσαντας ἄνδρα τοιοῦτον ἐξαποστεῖλαι, πρόδηλον ἐχθρὸν καὶ πολέμιον, οὐδαμῶς ἡγοῦντο σφίσι συμφέρειν. λοιπὸν ἦν ἄκοντα κατέχειν. τοῦτο δ’ αὐτόθεν καὶ χωρὶς λόγου πάντες μὲν ἀπεδοκίμαζον, οὐκ ἀσφαλὲς νομίζοντες εἶναι λέοντι καὶ προβάτοις ὁμοῦ ποιεῖσθαι τὴν ἔπαυλιν· μάλιστα δὲ τοῦτο τὸ μέρος ὁ Σωσίβιος ὑφεωρᾶτο διά τινα τοιαύτην αἰτίαν.", "st": "5.35"}, {"sp": "N", "t": "καθ’ ὃν γὰρ καιρὸν ἐγίνοντο περὶ τὴν ἀναίρεσιν τοῦ Μάγα καὶ τῆς Βερενίκης, ἀγωνιῶντες μὴ διασφαλῶσι τῆς ἐπιβολῆς, καὶ μάλιστα διὰ τὴν Βερενίκης τόλμαν, ἠναγκάζοντο πάντας αἰκάλλειν τοὺς περὶ τὴν αὐλὴν καὶ πᾶσιν ὑπογράφειν ἐλπίδας, ἐὰν κατὰ λόγον αὐτοῖς χωρήσῃ τὰ πράγματα. τότε δὴ κατανοῶν ὁ Σωσίβιος τὸν Κλεομένην δεόμενον μὲν τῆς ἐκ τῶν βασιλέων ἐπικουρίας, ἔχοντα δὲ γνώμην καὶ πραγμάτων ἀληθινὴν ἔννοιαν, ὑπογράφων αὐτῷ μεγάλας ἐλπίδας ἅμα συμμετέδωκε τῆς ἐπιβολῆς. θεωρῶν δ’ αὐτὸν ὁ Κλεομένης ἐξεπτοημένον καὶ μάλιστα δεδιότα τοὺς ξένους καὶ μισθοφόρους, θαρρεῖν παρεκάλει· τοὺς γὰρ μισθοφόρους βλάψειν μὲν αὐτὸν οὐδέν, ὠφελήσειν δ’ ὑπισχνεῖτο. μᾶλλον δ’ αὐτοῦ θαυμάσαντος τὴν ἐπαγγελίαν \"οὐχ ὁρᾷς\" ἔφη \"διότι σχεδὸν εἰς τρισχιλίους εἰσὶν ἀπὸ Πελοποννήσου ξένοι καὶ Κρῆτες εἰς χιλίους, οἷς ἐὰν νεύσωμεν ἡμεῖς μόνον, ἑτοίμως ὑπουργήσουσι πάντες; τούτων δὲ συστραφέντων, τίνας ἀγωνιᾷς; ἢ δῆλον\" ἔφη \"τοὺς ἀπὸ Συρίας καὶ Καρίας στρατιώτας;\" τότε μὲν οὖν ἡδέως ὁ Σωσίβιος ἀκούσας ταῦτα διπλασίως ἐπερρώσθη πρὸς τὴν κατὰ τῆς Βερενίκης πρᾶξιν· μετὰ δὲ ταῦτα θεωρῶν τὴν τοῦ βασιλέως ῥᾳθυμίαν, ἀεὶ τὸν λόγον ἀνενεοῦτο, καὶ πρὸ ὀφθαλμῶν τήν τε τοῦ Κλεομένους τόλμαν ἐλάμβανε καὶ τὴν τῶν ξένων πρὸς αὐτὸν εὔνοιαν. διὸ καὶ τότε μάλιστα παρέστησε τῷ τε βασιλεῖ καὶ τοῖς φίλοις ὁρμὴν οὗτος εἰς τὸ προκαταλαβέσθαι καὶ συγκλεῖσαι τὸν Κλεομένην. πρὸς δὲ τὴν ἐπίνοιαν ταύτην ἐχρήσατο συνεργήματι τοιούτῳ τινί.", "st": "5.36"}, {"sp": "N", "t": "Νικαγόρας τις ἦν Μεσσήνιος· οὗτος ὑπῆρχε πατρικὸς ξένος Ἀρχιδάμου τοῦ Λακεδαιμονίων βασιλέως. τὸν μὲν οὖν πρὸ τοῦ χρόνον βραχεῖά τις ἦν τοῖς προειρημένοις ἐπιπλοκὴ πρὸς ἀλλήλους· καθ’ ὃν δὲ καιρὸν Ἀρχίδαμος ἐκ τῆς Σπάρτης ἔφυγε δείσας τὸν Κλεομένην, καὶ παρεγένετ’ εἰς Μεσσηνίαν, οὐ μόνον οἰκίᾳ καὶ τοῖς ἄλλοις ἀναγκαίοις ὁ Νικαγόρας αὐτὸν ἐδέξατο προθύμως, ἀλλὰ καὶ κατὰ τὴν ἑξῆς συμπεριφορὰν ἐγένετό τις αὐτοῖς ὁλοσχερὴς εὔνοια καὶ συνήθεια πρὸς ἀλλήλους. διὸ καὶ μετὰ ταῦτα, τοῦ Κλεομένους ὑποδείξαντος ἐλπίδα καθόδου καὶ διαλύσεως πρὸς τὸν Ἀρχίδαμον, ἔδωκεν αὑτὸν ὁ Νικαγόρας εἰς τὰς διαποστολὰς καὶ τὰς ὑπὲρ τῶν πίστεων συνθήκας. ὧν κυρωθέντων ὁ μὲν Ἀρχίδαμος εἰς τὴν Σπάρτην κατῄει, πιστεύσας ταῖς διὰ τοῦ Νικαγόρου γεγενημέναις συνθήκαις, ὁ δὲ Κλεομένης ἀπαντήσας τὸν μὲν Ἀρχίδαμον ἐπανείλετο, τοῦ δὲ Νικαγόρου καὶ τῶν ἄλλων τῶν συνόντων ἐφείσατο. πρὸς μὲν οὖν τοὺς ἐκτὸς ὁ Νικαγόρας ὑπεκρίνετο χάριν ὀφείλειν τῷ Κλεομένει διὰ τὴν αὑτοῦ σωτηρίαν, ἐν αὑτῷ γε μὴν βαρέως ἔφερε τὸ συμβεβηκός, δοκῶν αἴτιος γεγονέναι τῷ βασιλεῖ τῆς ἀπωλείας. οὗτος ὁ Νικαγόρας ἵππους ἄγων κατέπλευσε βραχεῖ χρόνῳ πρότερον εἰς τὴν Ἀλεξάνδρειαν. ἀποβαίνων δ’ ἐκ τῆς νεὼς καταλαμβάνει τόν τε Κλεομένην καὶ τὸν Παντέα καὶ μετ’ αὐτῶν Ἱππίταν ἐν τῷ λιμένι παρὰ τὴν κρηπῖδα περιπατοῦντας. ἰδὼν δ’ ὁ Κλεομένης αὐτὸν καὶ συμμίξας, ἠσπάζετο φιλοφρόνως, καὶ προσεπύθετο τί παρείη. τοῦ δ’ εἰπόντος ὅτι παραγέγονεν ἵππους ἄγων \"ἐβουλόμην ἄν σε\" ἔφη \"καὶ λίαν ἀντὶ τῶν ἵππων κιναίδους ἄγειν καὶ σαμβύκας· τούτων γὰρ ὁ νῦν βασιλεὺς κατεπείγεται. \" τότε γοῦν ἐπιγελάσας ὁ Νικαγόρας ἐσιώπησε, μετὰ δέ τινας ἡμέρας ἐπὶ πλεῖον ἐλθὼν εἰς τὰς χεῖρας τῷ Σωσιβίῳ διὰ τοὺς ἵππους εἶπε κατὰ τοῦ Κλεομένους τὸν ἄρτι ῥηθέντα λόγον, θεωρῶν δὲ τὸν Σωσίβιον ἡδέως ἀκούοντα, πᾶσαν ἐξέθετο τὴν προϋπάρχουσαν ἑαυτῷ πρὸς τὸν Κλεομένην διαφοράν.", "st": "5.37"}, {"sp": "N", "t": "ὃν ὁ Σωσίβιος ἐπιγνοὺς ἀλλοτρίως πρὸς τὸν Κλεομένην διακείμενον, τὰ μὲν παραχρῆμα δούς, ἃ δ’ εἰς τὸ μέλλον ἐπαγγειλάμενος, συνέπεισε γράψαντα κατὰ τοῦ Κλεομένους ἐπιστολὴν ἀπολιπεῖν ἐσφραγισμένην, ἵν’ ἐπειδὰν ὁ Νικαγόρας ἐκπλεύσῃ μετ’ ὀλίγας ἡμέρας, ὁ παῖς ἀνενέγκῃ τὴν ἐπιστολὴν πρὸς αὐτὸν ὡς ὑπὸ τοῦ Νικαγόρου πεμφθεῖσαν. συνεργήσαντος δὲ τοῦ Νικαγόρου τὰ προειρημένα καὶ τῆς ἐπιστολῆς ἀνενεχθείσης ὑπὸ τοῦ παιδὸς πρὸς τὸν Σωσίβιον μετὰ τὸν ἔκπλουν τοῦ Νικαγόρου, παρὰ πόδας ἅμα τὸν οἰκέτην καὶ τὴν ἐπιστολὴν ἧκεν ἔχων πρὸς τὸν βασιλέα. τοῦ μὲν παιδὸς φάσκοντος Νικαγόραν ἀπολιπεῖν τὴν ἐπιστολήν, ἐντειλάμενον ἀποδοῦναι Σωσιβίῳ, τῆς δ’ ἐπιστολῆς διασαφούσης ὅτι μέλλει Κλεομένης, ἐὰν μὴ ποιῶνται τὴν ἐξαποστολὴν αὐτοῦ μετὰ τῆς ἁρμοζούσης παρασκευῆς καὶ χορηγίας, ἐπανίστασθαι τοῖς τοῦ βασιλέως πράγμασιν, εὐθέως ὁ Σωσίβιος λαβόμενος τῆς ἀφορμῆς ταύτης παρώξυνε τὸν βασιλέα καὶ τοὺς ἄλλους φίλους πρὸς τὸ μὴ μέλλειν, ἀλλὰ φυλάξασθαι καὶ συγκλεῖσαι τὸν Κλεομένην. γενομένου δὲ τούτου, καί τινος ἀποδοθείσης οἰκίας αὐτῷ παμμεγέθους, ἐποιεῖτο τὴν διατριβὴν ἐν ταύτῃ παραφυλαττόμενος, τούτῳ διαφέρων τῶν ἄλλων τῶν ὑπηγμένων εἰς τὰς φυλακάς, τῷ ποιεῖσθαι τὴν δίαιταν ἐν μείζονι δεσμωτηρίῳ. εἰς ἃ βλέπων ὁ Κλεομένης, καὶ μοχθηρὰς ἐλπίδας ἔχων ὑπὲρ τοῦ μέλλοντος, παντὸς πράγματος ἔκρινε πεῖραν λαμβάνειν, οὐχ οὕτως πεπεισμένος κατακρατήσειν τῆς προθέσεως — οὐδὲν γὰρ εἶχε τῶν εὐλόγων πρὸς τὴν ἐπιβολήν — τὸ δὲ πλεῖον εὐθανατῆσαι σπουδάζων καὶ μηδὲν ἀνάξιον ὑπομεῖναι τῆς περὶ αὐτὸν προγεγενημένης τόλμης, ἅμα δὲ καὶ λαμβάνων ἐν νῷ τὸ τοιοῦτον, ὥς γ’ ἐμοὶ δοκεῖ, καὶ προτιθέμενος, ὅπερ εἴωθε συμβαίνειν πρὸς τοὺς μεγαλόφρονας τῶν ἀνδρῶν, μὴ μὰν ἀσπουδεί γε καὶ ἀκλειῶς ἀπολοίμην, ἀλλὰ μέγα ῥέξας τι καὶ ἐσσομένοισι πυθέσθαι.", "st": "5.38"}, {"sp": "N", "t": "παρατηρήσας οὖν ἔξοδον τοῦ βασιλέως εἰς Κάνωβον, διέδωκε τοῖς φυλάττουσιν αὑτὸν φήμην ὡς ἀφίεσθαι μέλλων ὑπὸ τοῦ βασιλέως, καὶ διὰ ταύτην τὴν αἰτίαν αὐτός τε τοὺς αὑτοῦ θεράποντας εἱστία καὶ τοῖς φυλάττουσιν ἱερεῖα καὶ στεφάνους, ἅμα δὲ τούτοις οἶνον ἐξαπέστειλε. τῶν δὲ χρωμένων τούτοις ἀνυπονοήτως καὶ καταμεθυσθέντων, παραλαβὼν τοὺς συνόντας φίλους καὶ τοὺς περὶ αὑτὸν παῖδας περὶ μέσον ἡμέρας λαθὼν τοὺς φύλακας ἐξῆλθε μετ’ ἐγχειριδίων. προάγοντες δὲ καὶ συντυχόντες κατὰ τὴν πλατεῖαν Πτολεμαίῳ τῷ τότ’ ἐπὶ τῆς πόλεως ἀπολελειμμένῳ, καταπληξάμενοι τῷ παραβόλῳ τοὺς συνόντας αὐτῷ, τοῦτον μὲν κατασπάσαντες ἀπὸ τοῦ τεθρίππου παρέκλεισαν, τὰ δὲ πλήθη παρεκάλουν ἐπὶ τὴν ἐλευθερίαν. οὐδενὸς δὲ προσέχοντος αὐτοῖς οὐδὲ συνεξισταμένου διὰ τὸ παράδοξον τῆς ἐπιβολῆς, ἐπιστρέψαντες ὥρμησαν πρὸς τὴν ἄκραν, ὡς ἀνασπάσοντες ταύτης τὰς πυλίδας καὶ συγχρησόμενοι τοῖς εἰς τὴν φυλακὴν ἀπηγμένοις τῶν ἀνδρῶν. ἀποσφαλέντες δὲ καὶ ταύτης τῆς ἐπιβολῆς διὰ τὸ τοὺς ἐφεστῶτας προαισθομένους τὸ μέλλον ἀσφαλίσασθαι τὴν πύλην, προσήνεγκαν αὑτοῖς τὰς χεῖρας εὐψύχως πάνυ καὶ Λακωνικῶς. Κλεομένης μὲν οὖν οὕτω μετήλλαξε τὸν βίον, ἀνὴρ γενόμενος καὶ πρὸς τὰς ὁμιλίας ἐπιδέξιος καὶ πρὸς πραγμάτων οἰκονομίαν εὐφυὴς καὶ συλλήβδην ἡγεμονικὸς καὶ βασιλικὸς τῇ φύσει.", "st": "5.39"}, {"sp": "N", "t": "μετὰ δὲ τοῦτον οὐ πολὺ κατόπιν Θεόδοτος ὁ τεταγμένος ἐπὶ Κοίλης Συρίας, ὢν τὸ γένος Αἰτωλός, τὰ μὲν καταφρονήσας τοῦ βασιλέως διὰ τὴν ἀσέλγειαν τοῦ βίου καὶ τῆς ὅλης αἱρέσεως, τὰ δὲ διαπιστήσας τοῖς περὶ τὴν αὐλὴν διὰ τὸ μικροῖς ἔμπροσθεν χρόνοις ἀξιολόγους παρασχόμενος χρείας τῷ βασιλεῖ περί τε τἄλλα καὶ περὶ τὴν πρώτην ἐπιβολὴν Ἀντιόχου τοῖς κατὰ Κοίλην Συρίαν πράγμασι, μὴ οἷον ἐπὶ τούτοις τυχεῖν τινος χάριτος, ἀλλὰ τοὐναντίον ἀνακληθεὶς εἰς τὴν Ἀλεξάνδρειαν παρ’ ὀλίγον κινδυνεῦσαι τῷ βίῳ, διὰ ταύτας τὰς αἰτίας ἐπεβάλετο τότε λαλεῖν Ἀντιόχῳ καὶ τὰς κατὰ Κοίλην Συρίαν πόλεις ἐγχειρίζειν. τοῦ δ’ ἀσμένως δεξαμένου τὴν ἐλπίδα, ταχεῖαν ἐλάμβανε τὸ πρᾶγμα τὴν οἰκονομίαν. ἵνα δὲ καὶ περὶ ταύτης τῆς οἰκίας τὸ παραπλήσιον ποιήσωμεν, ἀναδραμόντες ἐπὶ τὴν παράληψιν τῆς Ἀντιόχου δυναστείας ἀπὸ τούτων τῶν καιρῶν ποιησόμεθα κεφαλαιώδη τὴν ἔφοδον ἐπὶ τὴν ἀρχὴν τοῦ μέλλοντος λέγεσθαι πολέμου. Ἀντίοχος γὰρ ἦν μὲν υἱὸς νεώτερος Σελεύκου τοῦ Καλλινίκου προσαγορευθέντος, μεταλλάξαντος δὲ τοῦ πατρὸς καὶ διαδεξαμένου τἀδελφοῦ Σελεύκου τὴν βασιλείαν διὰ τὴν ἡλικίαν, τὸ μὲν πρῶτον τοῖς ἄνω τόποις μεθιστάμενος ἐποιεῖτο τὴν διατριβήν, ἐπεὶ δὲ Σέλευκος μετὰ δυνάμεως ὑπερβαλὼν τὸν Ταῦρον ἐδολοφονήθη, καθάπερ καὶ πρότερον εἰρήκαμεν, μεταλαβὼν τὴν ἀρχὴν αὐτὸς ἐβασίλευσε, διαπιστεύων τὴν μὲν ἐπὶ τάδε τοῦ Ταύρου δυναστείαν Ἀχαιῷ, τὰ δ’ ἄνω μέρη τῆς βασιλείας ἐγκεχειρικὼς Μόλωνι καὶ τἀδελφῷ τῷ Μόλωνος Ἀλεξάνδρῳ, Μόλωνος μὲν Μηδίας ὑπάρχοντος σατράπου, τἀδελφοῦ δὲ τῆς Περσίδος.", "st": "5.40"}, {"sp": "N", "t": "οἳ καταφρονήσαντες μὲν αὐτοῦ διὰ τὴν ἡλικίαν, ἐλπίσαντες δὲ τὸν Ἀχαιὸν ἔσεσθαι κοινωνὸν σφίσι τῆς ἐπιβολῆς, μάλιστα δὲ φοβούμενοι τὴν ὠμότητα καὶ κακοπραγμοσύνην τὴν Ἑρμείου τοῦ τότε προεστῶτος τῶν ὅλων πραγμάτων, ἀφίστασθαι καὶ διαστρέφειν ἐνεχείρησαν τὰς ἄνω σατραπείας. ὁ δ’ Ἑρμείας ἦν μὲν ἀπὸ Καρίας, ἐπέστη δ’ ἐπὶ τὰ πράγματα, Σελεύκου τἀδελφοῦ ταύτην αὐτῷ τὴν πίστιν ἐγχειρίσαντος, καθ’ οὓς καιροὺς ἐποιεῖτο τὴν ἐπὶ τὸν ἄτταλον στρατείαν. τυχὼν δὲ ταύτης τῆς ἐξουσίας πᾶσι μὲν ἐφθόνει τοῖς ἐν ὑπεροχαῖς οὖσι τῶν περὶ τὴν αὐλήν, φύσει δ’ ὠμὸς ὢν τῶν μὲν τὰς ἀγνοίας ἐπὶ τὸ χεῖρον ἐκδεχόμενος ἐκόλαζε, τοῖς δὲ χειροποιήτους καὶ ψευδεῖς ἐπιφέρων αἰτίας ἀπαραίτητος ἦν καὶ πικρὸς δικαστής. μάλιστα δ’ ἔσπευδε καὶ περὶ παντὸς ἐποιεῖτο βουλόμενος ἐπανελέσθαι τὸν ἀποκομίσαντα τὰς δυνάμεις τὰς Σελεύκῳ συνεξελθούσας Ἐπιγένην, διὰ τὸ θεωρεῖν τὸν ἄνδρα καὶ λέγειν καὶ πράττειν δυνάμενον καὶ μεγάλης ἀποδοχῆς ἀξιούμενον παρὰ ταῖς δυνάμεσιν. ὢν δὲ ταύτης τῆς προθέσεως ἐπεῖχε, βουλόμενος ἀεί τινος ὁρμῆς ἐπιλαβέσθαι καὶ προφάσεως κατὰ τοῦ προειρημένου. ἁθροισθέντος δὲ τοῦ συνεδρίου περὶ τῆς τοῦ Μόλωνος ἀποστάσεως, καὶ κελεύσαντος τοῦ βασιλέως λέγειν ἕκαστον τὸ φαινόμενον περὶ τοῦ πῶς δεῖ χρῆσθαι τοῖς κατὰ τοὺς ἀποστάτας πράγμασι, καὶ πρώτου συμβουλεύοντος Ἐπιγένους διότι δεῖ μὴ μέλλειν, ἀλλ’ ἐκ χειρὸς ἔχεσθαι τῶν προκειμένων, καὶ πρῶτον καὶ μάλιστα τὸν βασιλέα συνάπτειν τοῖς τόποις καὶ παρ’ αὐτοὺς εἶναι τοὺς καιρούς· οὕτως γὰρ ἢ τὸ παράπαν οὐδὲ τολμήσειν ἀλλοτριοπραγεῖν τοὺς περὶ τὸν Μόλωνα, τοῦ βασιλέως παρόντος καὶ τοῖς πολλοῖς ἐν ὄψει γενομένου μετὰ συμμέτρου δυνάμεως, ἢ κἂν ὅλως τολμήσωσι καὶ μείνωσιν ἐπὶ τῆς προθέσεως, ταχέως αὐτοὺς συναρπασθέντας ὑπὸ τῶν ὄχλων ὑποχειρίους παραδοθήσεσθαι τῷ βασιλεῖ·", "st": "5.41"}, {"sp": "N", "t": "ταῦτα λέγοντος ἔτι τοῦ προειρημένου διοργισθεὶς Ἑρμείας πολὺν ἔφησεν αὐτὸν χρόνον ἐπίβουλον ὄντα καὶ προδότην τῆς βασιλείας διαλεληθέναι, νῦν δὲ καλῶς ποιοῦντα φανερὸν ἐκ τῆς συμβουλῆς γεγονέναι, σπουδάζοντα μετ’ ὀλίγων ἐγχειρίσαι τὸ τοῦ βασιλέως σῶμα τοῖς ἀποστάταις. τότε μὲν οὖν οἷον ὑποθύψας τὴν διαβολὴν παρῆκε τὸν Ἐπιγένην, πικρίαν ἄκαιρον μᾶλλον ἢ δυσμένειαν ἐπιφήνας· αὐτὸς δὲ κατὰ τὴν αὑτοῦ γνώμην τὴν μὲν ἐπὶ τὸν Μόλωνα στρατείαν, κατάφοβος ὢν τὸν κίνδυνον, ἐξέκλινε διὰ τὴν ἀπειρίαν τῶν πολεμικῶν, ἐπὶ δὲ τὸν Πτολεμαῖον ἐσπούδαζε στρατεύειν, ἀσφαλῆ τοῦτον εἶναι πεπεισμένος τὸν πόλεμον διὰ τὴν τοῦ προειρημένου βασιλέως ῥᾳθυμίαν. τότε μὲν οὖν καταπληξάμενος τοὺς ἐν τῷ συνεδρίῳ πάντας ἐπὶ μὲν τὸν Μόλωνα στρατηγοὺς ἐξέπεμψε μετὰ δυνάμεως Ξένωνα καὶ Θεόδοτον τὸν ἡμιόλιον, τὸν δ’ Ἀντίοχον παρώξυνε συνεχῶς, οἰόμενος δεῖν ἐπιβάλλειν τὰς χεῖρας τοῖς κατὰ Κοίλην Συρίαν πράγμασι, μόνως οὕτως ὑπολαμβάνων, εἰ πανταχόθεν τῷ νεανίσκῳ περισταίη πόλεμος, οὔτε τῶν πρότερον ἡμαρτημένων ὑφέξειν δίκας οὔτε τῆς παρούσης ἐξουσίας κωλυθήσεσθαι διὰ τὰς χρείας καὶ τοὺς ἀεὶ περιισταμένους ἀγῶνας τῷ βασιλεῖ καὶ κινδύνους. διὸ καὶ τὸ τελευταῖον ἐπιστολὴν πλάσας ὡς παρ’ Ἀχαιοῦ διαπεσταλμένην προσήνεγκε τῷ βασιλεῖ, διασαφοῦσαν ὅτι Πτολεμαῖος αὐτὸν παρακαλεῖ πραγμάτων ἀντιποιήσασθαι καί φησι καὶ ναυσὶ καὶ χρήμασι χορηγήσειν πρὸς πάσας τὰς ἐπιβολάς, ἐὰν ἀναλάβῃ διάδημα καὶ φανερὸς γένηται πᾶσιν ἀντιποιούμενος τῆς ἀρχῆς, ἣν τοῖς πράγμασιν ἔχειν αὐτὸν καὶ νῦν, τῆς δ’ ἐπιγραφῆς αὑτῷ φθονοῦντα τὸν ὑπὸ τῆς τύχης διδόμενον ἀποτρίβεσθαι στέφανον. ὁ μὲν οὖν βασιλεὺς πιστεύσας τοῖς γραφομένοις ἕτοιμος ἦν καὶ μετέωρος στρατεύειν ἐπὶ Κοίλην Συρίαν.", "st": "5.42"}, {"sp": "N", "t": "ὄντος δ’ αὐτοῦ κατὰ τοὺς καιροὺς τούτους περὶ Σελεύκειαν τὴν ἐπὶ τοῦ Ζεύγματος, παρῆν Διόγνητος ὁ ναύαρχος ἐκ Καππαδοκίας τῆς περὶ τὸν Εὔξεινον, ἄγων Λαοδίκην τὴν Μιθριδάτου τοῦ βασιλέως θυγατέρα, παρθένον οὖσαν, γυναῖκα τῷ βασιλεῖ κατωνομασμένην. ὁ δὲ Μιθριδάτης εὔχετο μὲν ἀπόγονος εἶναι τῶν ἑπτὰ Περσῶν ἑνὸς τῶν ἐπανελομένων τὸν μάγον, διατετηρήκει δὲ τὴν δυναστείαν ἀπὸ προγόνων τὴν ἐξ ἀρχῆς αὐτοῖς διαδοθεῖσαν ὑπὸ Δαρείου παρὰ τὸν Εὔξεινον πόντον. Ἀντίοχος δὲ προσδεξάμενος τὴν παρθένον μετὰ τῆς ἁρμοζούσης ἀπαντήσεως καὶ προστασίας εὐθέως ἐπετέλει τοὺς γάμους, μεγαλοπρεπῶς καὶ βασιλικῶς χρώμενος ταῖς παρασκευαῖς. μετὰ δὲ τὴν συντέλειαν τῶν γάμων καταβὰς εἰς Ἀντιόχειαν, βασίλισσαν ἀποδείξας τὴν Λαοδίκην, λοιπὸν ἐγίνετο περὶ τὴν τοῦ πολέμου παρασκευήν. κατὰ δὲ τοὺς καιροὺς τούτους Μόλων, ἑτοίμους παρεσκευακὼς πρὸς πᾶν τοὺς ἐκ τῆς ἰδίας σατραπείας ὄχλους διά τε τὰς ἐλπίδας τὰς ἐκ τῶν ὠφελειῶν καὶ τοὺς φόβους, οὓς ἐνειργάσατο τοῖς ἡγεμόσιν ἀνατατικὰς καὶ ψευδεῖς εἰσφέρων ἐπιστολὰς παρὰ τοῦ βασιλέως, ἕτοιμον δὲ συναγωνιστὴν ἔχων τὸν ἀδελφὸν Ἀλέξανδρον, ἠσφαλισμένος δὲ καὶ τὰ κατὰ τὰς παρακειμένας σατραπείας διὰ τῆς τῶν προεστώτων εὐνοίας καὶ δωροδοκίας, ἐξεστράτευσε μετὰ μεγάλης δυνάμεως ἐπὶ τοὺς τοῦ βασιλέως στρατηγούς. οἱ δὲ περὶ τὸν Ξένωνα καὶ Θεόδοτον καταπλαγέντες τὴν ἔφοδον ἀνεχώρησαν εἰς τὰς πόλεις. ὁ δὲ Μόλων κύριος γενόμενος τῆς Ἀπολλωνιάτιδος χώρας εὐπορεῖτο ταῖς χορηγίαις ὑπερβαλλόντως. ἦν δὲ φοβερὸς μὲν καὶ πρὸ τοῦ διὰ τὸ μέγεθος τῆς δυναστείας.", "st": "5.43"}, {"sp": "N", "t": "τά τε γὰρ ἱπποφόρβια πάντα τὰ βασιλικὰ Μήδοις ἐγκεχείρισται, σίτου τε καὶ θρεμμάτων πλῆθος ἀναρίθμητον παρ’ αὐτοῖς ἐστι. περί γε μὴν τῆς ὀχυρότητος καὶ τοῦ μεγέθους τῆς χώρας οὐδ’ ἂν εἰπεῖν δύναιτ’ ἀξίως οὐδείς. ἡ γὰρ Μηδία κεῖται μὲν περὶ μέσην τὴν Ἀσίαν, διαφέρει δὲ καὶ κατὰ τὸ μέγεθος καὶ κατὰ τὴν εἰς ὕψος ἀνάτασιν πάντων τῶν κατὰ τὴν Ἀσίαν τόπων, ὡς πρὸς μέρος θεωρουμένη. καὶ μὴν ἐπίκειται τοῖς ἀλκιμωτάτοις καὶ μεγίστοις ἔθνεσι. πρόκειται γὰρ αὐτῆς παρὰ μὲν τὴν ἕω καὶ τὰ πρὸς ἀνατολὰς μέρη τὰ κατὰ τὴν ἔρημον πεδία τὴν μεταξὺ κειμένην τῆς Περσίδος καὶ τῆς Παρθυαίας· ἐπίκειται δὲ καὶ κρατεῖ τῶν καλουμένων Κασπίων πυλῶν, συνάπτει δὲ τοῖς Ταπύρων ὄρεσιν, ἃ δὴ τῆς Ὑρκανίας θαλάττης οὐ πολὺ διέστηκε. τοῖς δὲ πρὸς μεσημβρίαν κλίμασι καθήκει πρός τε τὴν Μεσοποταμίαν καὶ τὴν Ἀπολλωνιᾶτιν χώραν, παράκειται δὲ τῇ Περσίδι, προβεβλημένη τὸ Ζάγρον ὄρος, ὃ τὴν μὲν ἀνάβασιν ἔχει πρὸς ἑκατὸν στάδια, διαφορὰς δὲ καὶ συγκλείσεις πλείους ἔχον ἐν αὑτῷ διέζευκται κοιλάσι, κατὰ δέ τινας τόπους αὐλῶσιν, οὓς κατοικοῦσι Κοσσαῖοι καὶ Κορβρῆναι καὶ Κάρχοι καὶ πλείω γένη βαρβάρων ἕτερα, διαφέρειν δοκοῦντα πρὸς τὰς πολεμικὰς χρείας. τοῖς δὲ πρὸς τὰς δύσεις μέρεσι κειμένοις συνάπτει τοῖς Σατραπείοις καλουμένοις· τούτοις δὲ συμβαίνει μὴ πολὺ διεστάναι τῶν ἐθνῶν τῶν ἐπὶ τὸν Εὔξεινον καθηκόντων πόντον. τὰ δ’ ἐπὶ τὰς ἄρκτους αὐτῆς τετραμμένα μέρη περιέχεται μὲν Ἐλυμαίοις καὶ τοῖς Ἀνιαράκαις, ἔτι δὲ Καδουσίοις καὶ Ματιανοῖς, ὑπέρκειται δὲ τῶν συναπτόντων πρὸς τὴν Μαιῶτιν τοῦ Πόντου μερῶν. αὐτὴ δ’ ἡ Μηδία διέζευκται πλείοσιν ὄρεσιν ἀπὸ τῆς ἠοῦς ἕως πρὸς τὰς δύσεις, ὧν μεταξὺ κεῖται πεδία πληθύοντα πόλεσι καὶ κώμαις.", "st": "5.44"}, {"sp": "N", "t": "κυριεύων δὲ ταύτης τῆς χώρας, βασιλικὴν ἐχούσης περίστασιν, καὶ πάλαι μὲν φοβερὸς ἦν, ὡς πρότερον εἶπα, διὰ τὴν ὑπεροχὴν τῆς δυναστείας· τότε δὲ καὶ τῶν τοῦ βασιλέως στρατηγῶν δοκούντων παρακεχωρηκέναι τῶν ὑπαίθρων αὐτῷ καὶ τῶν ἰδίων δυνάμεων ἐπηρμένων ταῖς ὁρμαῖς διὰ τὸ κατὰ λόγον σφίσι προχωρεῖν τὰς πρώτας ἐλπίδας, τελέως ἐδόκει φοβερὸς εἶναι καὶ ἀνυπόστατος πᾶσι τοῖς τὴν Ἀσίαν κατοικοῦσι. διὸ τὸ μὲν πρῶτον ἐπεβάλετο διαβὰς τὸν Τίγριν πολιορκεῖν τὴν Σελεύκειαν· κωλυθείσης δὲ τῆς διαβάσεως ὑπὸ Ζεύξιδος διὰ τὸ καταλαβέσθαι τὰ ποτάμια πλοῖα, τοῦτον τὸν τρόπον ἀναχωρήσας εἰς τὴν ἐν τῇ Κτησιφῶντι λεγομένῃ στρατοπεδείαν παρεσκεύαζε ταῖς δυνάμεσι τὰ πρὸς τὴν παραχειμασίαν. ὁ δὲ βασιλεὺς ἀκούσας τήν τε τοῦ Μόλωνος ἔφοδον καὶ τὴν τῶν ἰδίων στρατηγῶν ἀναχώρησιν αὐτὸς μὲν ἦν ἕτοιμος πάλιν ἐπὶ τὸν Μόλωνα στρατεύειν, ἀποστὰς τῆς ἐπὶ τὸν Πτολεμαῖον ὁρμῆς, καὶ μὴ προΐεσθαι τοὺς καιρούς· Ἑρμείας δέ, τηρῶν τὴν ἐξ ἀρχῆς πρόθεσιν ἐπὶ μὲν τὸν Μόλωνα Ξενοίταν τὸν Ἀχαιὸν ἐξέπεμψε στρατηγὸν αὐτοκράτορα μετὰ δυνάμεως, φήσας δεῖν πρὸς μὲν τοὺς ἀποστάτας στρατηγοῖς πολεμεῖν, πρὸς δὲ τοὺς βασιλεῖς αὐτὸν ποιεῖσθαι τὸν βασιλέα καὶ τὰς ἐπιβολὰς καὶ τοὺς ὑπὲρ τῶν ὅλων ἀγῶνας, αὐτὸς δὲ διὰ τὴν ἡλικίαν ὑποχείριον ἔχων τὸν νεανίσκον προῆγε, καὶ συνήθροιζε τὰς δυνάμεις εἰς Ἀπάμειαν· ἐντεῦθεν δ’ ἀναζεύξας ἧκε πρὸς τὴν Λαοδίκειαν. ἀφ’ ἧς ποιησάμενος τὴν ὁρμὴν ὁ βασιλεὺς μετὰ πάσης τῆς στρατιᾶς, καὶ διελθὼν τὴν ἔρημον, ἐνέβαλεν εἰς τὸν αὐλῶνα τὸν προσαγορευόμενον Μαρσύαν, ὃς κεῖται μὲν μεταξὺ τῆς κατὰ τὸν Λίβανον καὶ τὸν Ἀντιλίβανον παρωρείας, συνάγεται δ’ εἰς στενὸν ὑπὸ τῶν προειρημένων ὀρῶν. συμβαίνει δὲ καὶ τοῦτον αὐτὸν τὸν τόπον, ᾗ στενώτατός ἐστι, διείργεσθαι τενάγεσι καὶ λίμναις, ἐξ ὧν ὁ μυρεψικὸς κείρεται κάλαμος.", "st": "5.45"}, {"sp": "N", "t": "ἐπίκειται δὲ τοῖς στενοῖς ἐκ μὲν θατέρου μέρους Βρόχοι προσαγορευόμενόν τι χωρίον, ἐκ δὲ θατέρου Γέρρα, στενὴν ἀπολείποντα πάροδον. ποιησάμενος δὲ διὰ τοῦ προειρημένου τὴν πορείαν αὐλῶνος ἐπὶ πλείους ἡμέρας, καὶ προσαγαγόμενος τὰς παρακειμένας πόλεις, παρῆν πρὸς τὰ Γέρρα. καταλαβὼν δὲ τὸν Θεόδοτον τὸν Αἰτωλὸν προκατειληφότα τὰ Γέρρα καὶ τοὺς Βρόχους, τὰ δὲ παρὰ τὴν λίμνην στενὰ διωχυρωμένον τάφροις καὶ χάραξι καὶ διειληφότα φυλακαῖς εὐκαίροις, τὸ μὲν πρῶτον ἐπεβάλετο βιάζεσθαι, πλείω δὲ πάσχων ἢ ποιῶν κακὰ διὰ τὴν ὀχυρότητα τῶν τόπων καὶ διὰ τὸ μένειν ἔτι τὸν Θεόδοτον ἀκέραιον, ἀπέστη τῆς ἐπιβολῆς. διὸ καὶ τοιαύτης οὔσης τῆς περὶ τοὺς τόπους δυσχρηστίας, προσπεσόντος αὐτῷ Ξενοίταν ἐπταικέναι τοῖς ὅλοις καὶ τὸν Μόλωνα πάντων τῶν ἄνω τόπων ἐπικρατεῖν, ἀφέμενος τούτων ὥρμησε τοῖς οἰκείοις πράγμασι βοηθήσων. ὁ γὰρ Ξενοίτας ὁ στρατηγὸς ἀποσταλεὶς αὐτοκράτωρ, καθάπερ ἐπάνω προεῖπα, καὶ μείζονος ἐξουσίας ἢ κατὰ τὴν προσδοκίαν τυχών, ὑπεροπτικώτερον μὲν ἐχρῆτο τοῖς αὑτοῦ φίλοις, θρασύτερον δὲ ταῖς πρὸς τοὺς ἐχθροὺς ἐπιβολαῖς. οὐ μὴν ἀλλὰ καταζεύξας εἰς τὴν Σελεύκειαν, καὶ μεταπεμψάμενος Διογένην τὸν τῆς Σουσιανῆς ἔπαρχον καὶ Πυθιάδην τὸν τῆς Ἐρυθρᾶς θαλάττης, ἐξῆγε τὰς δυνάμεις, καὶ λαβὼν πρόβλημα τὸν Τίγριν ποταμὸν ἀντεστρατοπέδευσε τοῖς πολεμίοις. πλειόνων δὲ διακολυμβώντων πρὸς αὐτὸν ἀπὸ τῆς τοῦ Μόλωνος στρατοπεδείας, καὶ δηλούντων ὡς ἐὰν διαβῇ τὸν ποταμόν, ἅπαν ἀπονεύσει πρὸς αὐτὸν τὸ τοῦ Μόλωνος στρατόπεδον — τῷ μὲν γὰρ Μόλωνι φθονεῖν, τῷ δὲ βασιλεῖ τὸ πλῆθος εὔνουν ὑπάρχειν διαφερόντως — ἐπαρθεὶς τούτοις ὁ Ξενοίτας ἐπεβάλετο διαβαίνειν τὸν Τίγριν. ὑποδείξας δὲ διότι μέλλει ζευγνύναι τὸν ποταμὸν κατά τινα νησίζοντα τόπον, τῶν μὲν πρὸς τοῦτο τὸ μέρος ἐπιτηδείων οὐδὲν ἡτοίμαζε, διὸ καὶ συνέβη καταφρονῆσαι τοὺς περὶ τὸν Μόλωνα τῆς ὑποδεικνυμένης ἐπιβολῆς, τὰ δὲ πλοῖα συνήθροιζε καὶ κατήρτιζε καὶ πολλὴν ἐπιμέλειαν ἐποιεῖτο περὶ τούτων. ἐπιλέξας δ’ ἐκ παντὸς τοῦ στρατεύματος τοὺς εὐρωστοτάτους ἱππεῖς καὶ πεζούς, ἐπὶ τῆς παρεμβολῆς ἀπολιπὼν Ζεῦξιν καὶ Πυθιάδην παρῆλθε νυκτὸς ὡς ὀγδοήκοντα σταδίους ὑποκάτω τῆς τοῦ Μόλωνος στρατοπεδείας, καὶ διακομίσας τοῖς πλοίοις τὴν δύναμιν ἀσφαλῶς νυκτὸς ἔτι κατεστρατοπέδευσε, λαβὼν εὐφυῆ τόπον, ᾧ συνέβαινε κατὰ μὲν τὸ πλεῖστον ὑπὸ τοῦ ποταμοῦ περιέχεσθαι, τὸ δὲ λοιπὸν ἕλεσιν ἠσφαλίσθαι καὶ τέλμασιν.", "st": "5.46"}, {"sp": "N", "t": "ὁ δὲ Μόλων συνεὶς τὸ γεγονὸς ἐξαπέστειλε τοὺς ἱππεῖς, ὡς κωλύσων τοὺς ἐπιδιαβαίνοντας ῥᾳδίως καὶ συντρίψων τοὺς ἤδη διαβεβηκότας· οἳ καὶ συνεγγίσαντες τοῖς περὶ τὸν Ξενοίταν διὰ τὴν ἄγνοιαν τῶν τόπων οὐ προσεδέοντο τῶν πολεμίων, αὐτοὶ δ’ ὑφ’ αὑτῶν βαπτιζόμενοι καὶ καταδύνοντες ἐν τοῖς τέλμασιν ἄχρηστοι μὲν ἦσαν ἅπαντες, πολλοὶ δὲ καὶ διεφθάρησαν αὐτῶν. ὁ δὲ Ξενοίτας, πεπεισμένος, ἐὰν πλησιάσῃ, μεταβαλεῖσθαι τὰς τοῦ Μόλωνος πρὸς αὐτὸν δυνάμεις, προελθὼν παρὰ τὸν ποταμὸν καὶ συνεγγίσας παρεστρατοπέδευσε τοῖς ὑπεναντίοις. κατὰ δὲ τὸν καιρὸν τοῦτον ὁ Μόλων, εἴτε καὶ στρατηγήματος χάριν εἴτε καὶ διαπιστήσας ταῖς δυνάμεσι, μή τι συμβῇ τῶν ὑπὸ τοῦ Ξενοίτου προσδοκωμένων, ἀπολιπὼν ἐν τῷ χάρακι τὴν ἀποσκευὴν ἀνέζευξε νυκτός, καὶ προῆγε σύντονον ποιούμενος τὴν πορείαν ὡς ἐπὶ Μηδίας. ὁ δὲ Ξενοίτας, ὑπολαβὼν πεφευγέναι τὸν Μόλωνα καταπεπληγμένον τὴν ἔφοδον αὐτοῦ καὶ διαπιστοῦντα ταῖς ἰδίαις αὑτοῦ δυνάμεσι, τὸ μὲν πρῶτον ἐπιστρατοπεδεύσας κατελάβετο τὴν τῶν πολεμίων παρεμβολήν, καὶ διεπεραίου πρὸς αὑτὸν τοὺς ἰδίους ἱππεῖς καὶ τὰς τούτων ἀποσκευὰς ἐκ τῆς Ζεύξιδος παρεμβολῆς· μετὰ δὲ ταῦτα συναθροίσας παρεκάλει τοὺς πολλοὺς θαρρεῖν καὶ καλὰς ἐλπίδας ἔχειν ὑπὲρ τῶν ὅλων, ὡς πεφευγότος τοῦ Μόλωνος. ταῦτα δ’ εἰπὼν ἐπιμελεῖσθαι παρήγγειλε καὶ θεραπεύειν αὑτοὺς ἅπασιν, ὡς ἐκ ποδὸς ἀκολουθήσων πρωῒ τοῖς ὑπεναντίοις.", "st": "5.47"}, {"sp": "N", "t": "οἱ δὲ πολλοὶ κατατεθαρρηκότες καὶ παντοδαπῆς ἐπειλημμένοι χορηγίας, ὥρμησαν πρὸς ἀπόλαυσιν καὶ μέθην καὶ τὴν ταῖς τοιαύταις ὁρμαῖς παρεπομένην ῥᾳθυμίαν. ὁ δὲ Μόλων διανύσας ἱκανόν τινα τόπον καὶ δειπνοποιησάμενος παρῆν ἐξ ὑποστροφῆς, καὶ καταλαβὼν ἐρριμμένους καὶ μεθύοντας πάντας, προσέβαλε τῷ χάρακι τῶν πολεμίων ὑπὸ τὴν ἑωθινήν. οἱ δὲ περὶ τὸν Ξενοίταν ἐκπλαγέντες ἐπὶ τοῖς συμβαίνουσι διὰ τὸ παράδοξον, ἀδυνατοῦντες δὲ τοὺς πολλοὺς ἐγείρειν διὰ τὴν κατέχουσαν αὐτοὺς μέθην, αὐτοὶ μὲν ἀλόγως ὁρμήσαντες εἰς τοὺς πολεμίους διεφθάρησαν, τῶν δὲ κοιμωμένων οἱ μὲν πλείους ἐν αὐταῖς ταῖς στιβάσι κατεκόπησαν, οἱ δὲ λοιποὶ ῥιπτοῦντες ἑαυτοὺς εἰς τὸν ποταμὸν ἐπειρῶντο διαβαίνειν πρὸς τὴν ἀντίπερα στρατοπεδείαν· οὐ μὴν ἀλλ’ οἱ πλείους καὶ τούτων ἀπώλλυντο. καθόλου δὲ ποικίλη τις ἦν ἀκρισία περὶ τὰ στρατόπεδα καὶ κυδοιμός· πάντες γὰρ ἐκπλαγεῖς καὶ περιδεεῖς ἦσαν, ἅμα δὲ καὶ τῆς ἀντίπερα παρεμβολῆς ὑπὸ τὴν ὄψιν οὔσης ἐν πάνυ βραχεῖ διαστήματι, τῆς μὲν τοῦ ποταμοῦ βίας καὶ δυσχρηστίας ἐξελανθάνοντο διὰ τὴν ἐπιθυμίαν τὴν πρὸς τὸ σῴζεσθαι, κατὰ δὲ τὴν παράστασιν καὶ τὴν ὁρμὴν τὴν πρὸς τὴν σωτηρίαν ἐρρίπτουν ἑαυτοὺς εἰς τὸν ποταμόν, ἐνίεσαν δὲ καὶ τὰ ὑποζύγια σὺν ταῖς ἀποσκευαῖς, ὡς τοῦ ποταμοῦ κατά τινα πρόνοιαν αὐτοῖς συνεργήσοντος καὶ διακομιοῦντος ἀσφαλῶς πρὸς τὴν ἀντίπερα κειμένην στρατοπεδείαν. ἐξ ὧν συνέβαινε τραγικὴν καὶ παρηλλαγμένην φαίνεσθαι τοῦ ῥεύματος τὴν φαντασίαν, ὡς ἂν ὁμοῦ τοῖς νηχομένοις φερομένων ἵππων, ὑποζυγίων, ὅπλων, νεκρῶν, ἀποσκευῆς παντοδαπῆς. Μόλων δὲ κυριεύσας τῆς τοῦ Ξενοίτου παρεμβολῆς, καὶ μετὰ ταῦτα διαβὰς τὸν ποταμὸν ἀσφαλῶς, ἅτε μηδενὸς κωλύοντος διὰ τὸ φυγεῖν τὴν ἔφοδον αὐτοῦ καὶ τοὺς περὶ τὸν Ζεῦξιν, ἐγκρατὴς γίνεται καὶ τῆς τούτου στρατοπεδείας. συντελεσάμενος δὲ τὰ προειρημένα παρῆν μετὰ τοῦ στρατοπέδου πρὸς τὴν Σελεύκειαν. παραλαβὼν δὲ καὶ ταύτην ἐξ ἐφόδου διὰ τὸ πεφευγέναι τοὺς περὶ τὸν Ζεῦξιν, ἅμα δὲ τούτοις τὸν Διομέδοντα τὸν ἐπιστάτην τῆς Σελευκείας, λοιπὸν ἤδη προάγων ἀκονιτὶ κατεστρέφετο τὰς ἄνω σατραπείας. γενόμενος δὲ κύριος τῆς τε Βαβυλωνίας καὶ τῆς περὶ τὴν Ἐρυθρὰν θάλατταν ἧκε πρὸς Σοῦσα. τὴν μὲν οὖν πόλιν ἐξ ἐφόδου καὶ ταύτην κατέσχε, τῇ δ’ ἄκρᾳ προσβολὰς ποιούμενος οὐδὲν ἤνυε τῷ φθάσαι Διογένην τὸν στρατηγὸν εἰς αὐτὴν παρεισπεσόντα. διὸ καὶ ταύτης μὲν τῆς ἐπιβολῆς ἀπέστη, καταλιπὼν δὲ τοὺς πολιορκήσοντας κατὰ τάχος ἀνέζευξε, καὶ κατῆρε μετὰ τῆς δυνάμεως πάλιν εἰς Σελεύκειαν τὴν ἐπὶ τῷ Τίγριδι. πολλὴν δὲ ποιησάμενος ἐπιμέλειαν ἐνταῦθα τοῦ στρατοπέδου καὶ παρακαλέσας τὸ πλῆθος ὥρμησε πρὸς τὰς ἑξῆς πράξεις, καὶ τὴν μὲν Παραποταμίαν μέχρι πόλεως Εὐρώπου κατέσχε, τὴν δὲ Μεσοποταμίαν ἕως Δούρων. Ἀντίοχος δέ, τούτων αὐτῷ προσπεσόντων, ὡς ἐπάνω προεῖπον, ἀπογνοὺς τὰς κατὰ Κοίλην Συρίαν ἐλπίδας ὥρμησε πρὸς ταύτας τὰς ἐπιβολάς.", "st": "5.48"}, {"sp": "N", "t": "ἐν ᾧ καιρῷ πάλιν ἁθροισθέντος τοῦ συνεδρίου, καὶ κελεύσαντος λέγειν τοῦ βασιλέως ὑπὲρ τοῦ πῶς δεῖ χρῆσθαι ταῖς ἐπὶ τὸν Μόλωνα παρασκευαῖς, αὖτις Ἐπιγένους καταρξαμένου καὶ λέγοντος περὶ τῶν ἐνεστώτων, ὡς ἔδει μὲν πάλαι μὴ μέλλειν κατὰ τὴν αὑτοῦ συμβουλίαν πρὸ τοῦ τηλικαῦτα προτερήματα λαβεῖν τοὺς ἐχθρούς, οὐ μὴν ἀλλὰ καὶ νῦν ἔτι φάσκοντος δεῖν ἔχεσθαι τῶν πραγμάτων, πάλιν Ἑρμείας ἀκρίτως καὶ προπετῶς ἐξοργισθεὶς ἤρξατο λοιδορεῖν τὸν εἰρημένον. ἅμα δὲ φορτικῶς μὲν αὑτὸν ἐγκωμιάζων, ἀστόχους δὲ καὶ ψευδεῖς ποιούμενος κατηγορίας Ἐπιγένους, μαρτυρόμενος δὲ τὸν βασιλέα μὴ παριδεῖν οὕτως ἀλόγως μηδ’ ἀποστῆναι τῶν περὶ Κοίλης Συρίας ἐλπίδων, προσέκοπτε μὲν τοῖς πολλοῖς, ἐλύπει δὲ καὶ τὸν Ἀντίοχον, μόλις δὲ κατέπαυσε τὴν ἁψιμαχίαν, πολλὴν ποιησαμένου τοῦ βασιλέως σπουδὴν εἰς τὸ διαλύειν αὐτούς. δόξαντος δὲ τοῖς πολλοῖς Ἐπιγένους ἀναγκαιότερα καὶ συμφορώτερα λέγειν, ἐκυρώθη τὸ διαβούλιον στρατεύειν ἐπὶ τὸν Μόλωνα καὶ τούτων ἔχεσθαι τῶν πράξεων. ταχὺ δὲ συνυποκριθεὶς καὶ μεταπεσὼν Ἑρμείας, καὶ φήσας δεῖν ἅπαντας τὸ κριθὲν ἀπροφασίστως συμπράττειν, οὗτος αὐτὸς ἕτοιμος ἦν καὶ πολὺς πρὸς ταῖς παρασκευαῖς.", "st": "5.49"}, {"sp": "N", "t": "ἁθροισθεισῶν δὲ τῶν δυνάμεων εἰς Ἀπάμειαν, καί τινος ἐγγενομένης στάσεως τοῖς πολλοῖς ὑπὲρ τῶν προσοφειλομένων ὀψωνίων, λαβὼν ἐπτοημένον τὸν βασιλέα καὶ δεδιότα τὸ γεγονὸς κίνημα διὰ τὸν καιρόν, ἐπηγγείλατο διαλύσειν πᾶσι τὰς σιταρχίας, ἐὰν αὐτῷ συγχωρήσῃ μὴ στρατεύειν μετ’ αὐτῶν τὸν Ἐπιγένην· οὐ γὰρ οἷόν τ’ εἶναι τῶν κατὰ λόγον οὐδὲν πράττεσθαι κατὰ τὴν στρατείαν τηλικαύτης ἐν αὐτοῖς ὀργῆς καὶ στάσεως ἐγγεγενημένης. ὁ δὲ βασιλεὺς δυσχερῶς μὲν ἤκουσε καὶ περὶ παντὸς ἐποιεῖτο σπουδάζων διὰ τὴν ἐμπειρίαν τῶν πολεμικῶν συστρατεύειν αὑτῷ τὸν Ἐπιγένην, περιεχόμενος δὲ καὶ προκατειλημμένος οἰκονομίαις καὶ φυλακαῖς καὶ θεραπείαις ὑπὸ τῆς Ἑρμείου κακοηθείας οὐκ ἦν αὑτοῦ κύριος· διὸ καὶ τοῖς παροῦσιν εἴκων συνεχώρησε τοῖς ἀξιουμένοις. τοῦ δ’ Ἐπιγένους κατὰ τὸ προσταχθὲν ἀναχωρήσαντος εἰς ἱμάτιον …, οἱ μὲν οὖν ἐν τῷ συνεδρίῳ κατεπλάγησαν τὸν φθόνον, αἱ δὲ δυνάμεις τυχοῦσαι τῶν ἀξιουμένων ἐκ μεταβολῆς εὐνοϊκῶς διέκειντο πρὸς τὸν αἴτιον τῆς τῶν ὀψωνίων διορθώσεως πλὴν τῶν Κυρρηστῶν· οὗτοι δ’ ἐστασίασαν καὶ σχεδὸν εἰς ἑξακισχιλίους ὄντες τὸν ἀριθμὸν ἀπέστησαν, καὶ πολλὰς δή τινας ἀηδίας ἐπὶ χρόνον ἱκανὸν παρέσχον· τέλος δὲ μάχῃ κρατηθέντες ὑπό τινος τῶν τοῦ βασιλέως στρατηγῶν οἱ μὲν πλεῖστοι διεφθάρησαν, οἱ δὲ περιλειφθέντες παρέδοσαν ἑαυτοὺς εἰς τὴν τοῦ βασιλέως πίστιν. ὁ δ’ Ἑρμείας τοὺς μὲν φίλους διὰ τὸν φόβον, τὰς δὲ δυνάμεις διὰ τὴν εὐχρηστίαν ὑφ’ ἑαυτὸν πεποιημένος, ἀναζεύξας προῆγε μετὰ τοῦ βασιλέως. περὶ δὲ τὸν Ἐπιγένην πρᾶξιν συνεστήσατο τοιαύτην, λαβὼν συνεργὸν τὸν ἀκροφύλακα τῆς Ἀπαμείας Ἄλεξιν. γράψας ὡς παρὰ Μόλωνος ἀπεσταλμένην ἐπιστολὴν πρὸς τὸν Ἐπιγένην πείθει τινὰ τῶν ἐκείνου παίδων ἐλπίσι μεγάλαις ψυχαγωγήσας εἰσενέγκαντα πρὸς τὸν Ἐπιγένην καταμῖξαι τὴν ἐπιστολὴν τοῖς ἐκείνου γράμμασιν. οὗ γενομένου παρῆν εὐθέως Ἄλεξις, καὶ διηρώτα τὸν Ἐπιγένην μή τινας ἐπιστολὰς κεκόμισται παρὰ τοῦ Μόλωνος. τοῦ δ’ ἀπειπομένου πικρῶς ἐρευνᾶν ᾔτει. ταχὺ δὲ παρεισελθὼν εὗρε τὴν ἐπιστολήν, ᾗ χρησάμενος ἀφορμῇ παραχρῆμα τὸν Ἐπιγένην ἀπέκτεινεν. οὗ συμβάντος ὁ μὲν βασιλεὺς ἐπείσθη δικαίως ἀπολωλέναι τὸν Ἐπιγένην, οἱ δὲ περὶ τὴν αὐλὴν ὑπώπτευον μὲν τὸ γεγονός, ἦγον δὲ τὴν ἡσυχίαν διὰ τὸν φόβον.", "st": "5.50"}, {"sp": "N", "t": "Ἀντίοχος δὲ παραγενόμενος ἐπὶ τὸν Εὐφράτην καὶ προσαναλαβὼν τὴν δύναμιν αὖτις ἐξώρμα, καὶ διανύσας εἰς Ἀντιόχειαν τὴν ἐν Μυγδονίᾳ περὶ τροπὰς χειμερινὰς ἐπέμεινε, θέλων ἀποδέξασθαι τὴν ἐπιφορὰν καὶ τὴν ἀκμὴν τοῦ χειμῶνος. μείνας δὲ περὶ τετταράκονθ’ ἡμέρας προῆγεν εἰς Λίββαν. ἀποδοθέντος δ’ ἐκεῖσε διαβουλίου ποίᾳ δεῖ προάγειν ἐπὶ τὸν Μόλωνα καὶ πῶς πόθεν κεχρῆσθαι ταῖς εἰς τὰς πορείας χορηγίαις — ἐτύγχανε γὰρ ὁ Μόλων ἐν τοῖς περὶ Βαβυλῶνα τόποις ὑπάρχων — Ἑρμείᾳ μὲν ἐδόκει παρὰ τὸν Τίγριν ποιεῖσθαι τὴν πορείαν, προβαλλομένους τοῦτόν τε καὶ τὸν Λύκον ποταμὸν καὶ τὸν Κάπρον, Ζεῦξις δὲ λαμβάνων πρὸ ὀφθαλμῶν τὴν ἀπώλειαν τὴν Ἐπιγένους τὰ μὲν ἠγωνία λέγειν τὸ φαινόμενον, τὰ δὲ προδήλου τῆς ἀγνοίας οὔσης τῆς κατὰ τὸν Ἑρμείαν μόλις ἐθάρρησε συμβουλεύειν ὅτι διαβατέον εἴη τὸν Τίγριν, ἀπολογιζόμενος τήν τε λοιπὴν δυσχέρειαν τῆς παρὰ τὸν ποταμὸν πορείας καὶ διότι δέοι διανύσαντας ἱκανοὺς τόπους, μετὰ ταῦτα διελθόντας ὁδὸν ἔρημον ἡμερῶν ἕξ, παραγενέσθαι πρὸς τὴν Βασιλικὴν διώρυχα καλουμένην· ἧς προκαταληφθείσης ὑπὸ τῶν πολεμίων ἀδύνατον μὲν γενέσθαι τὴν διάβασιν αὐτῆς, ἐπισφαλῆ δὲ προφανῶς τὴν διὰ τῆς ἐρήμου πάλιν ἀποχώρησιν, καὶ μάλιστα διὰ τὴν ἐσομένην ἔνδειαν τῶν ἐπιτηδείων. ἐκ δὲ τοῦ διαβῆναι τὸν Τίγριν πρόδηλον μὲν ἀπεδείκνυε τὴν μετάνοιαν καὶ πρόσκλισιν τῷ βασιλεῖ τῶν κατὰ τὴν Ἀπολλωνιᾶτιν χώραν ὄχλων διὰ τὸ καὶ νῦν αὐτοὺς μὴ κατὰ προαίρεσιν, ἀνάγκῃ δὲ καὶ φόβῳ ποιεῖν Μόλωνι τὸ προσταττόμενον, πρόδηλον δὲ τὴν δαψίλειαν τῶν ἐπιτηδείων τοῖς στρατοπέδοις διὰ τὴν ἀρετὴν τῆς χώρας. τὸ δὲ μέγιστον, ἀπέφαινε διακλεισθησόμενον τὸν Μόλωνα τῆς εἰς τὴν Μηδίαν ἐπανόδου καὶ τῆς ἐξ ἐκείνων τῶν τόπων ἐπαρκείας, ἐξ ὧν ἀναγκασθήσεσθαι διακινδυνεύειν αὐτόν, ἢ μὴ θέλοντος τοῦτο ποιεῖν ἐκείνου μεταβαλέσθαι τὰς δυνάμεις ταχέως πρὸς τὰς τοῦ βασιλέως ἐλπίδας.", "st": "5.51"}, {"sp": "N", "t": "κριθείσης δὲ τῆς τοῦ Ζεύξιδος γνώμης, παραυτίκα διελόντες τὴν δύναμιν εἰς τρία μέρη κατὰ τριττοὺς τόπους τοῦ ποταμοῦ διεπεραίουν τὸ πλῆθος καὶ τὰς ἀποσκευάς. μετὰ δὲ ταῦτα ποιησάμενοι τὴν πορείαν ὡς ἐπὶ Δούρων ταύτης μὲν τῆς πόλεως ἔλυσαν ἐξ ἐφόδου τὴν πολιορκίαν — ἐτύγχανε γὰρ ὑπό τινος τῶν τοῦ Μόλωνος ἡγεμόνων πολιορκουμένη — χρησάμενοι δὲ κατὰ τὸ συνεχὲς ἐντεῦθεν ταῖς ἀναζυγαῖς ὀγδοαῖοι τὸ καλούμενον Ὀρεικὸν ὑπερέβαλον καὶ κατῆραν εἰς Ἀπολλωνίαν. Μόλων δὲ κατὰ τοὺς αὐτοὺς καιροὺς πυθόμενος τὴν τοῦ βασιλέως παρουσίαν, καὶ διαπιστῶν τοῖς περὶ τὴν Σουσιανὴν καὶ Βαβυλωνίαν ὄχλοις διὰ τὸ προσφάτως καὶ παραδόξως αὐτῶν ἐγκρατὴς γεγονέναι, φοβούμενος δὲ καὶ τῆς εἰς Μηδίαν ἐπανόδου μὴ διακλεισθῇ, διέγνω ζευγνύειν τὸν Τίγριν καὶ διαβιβάζειν τὰς δυνάμεις, σπεύδων, εἰ δύναιτο, προκαταλαβέσθαι τὴν τραχεῖαν τῆς Ἀπολλωνιάτιδος διὰ τὸ πιστεύειν τῷ πλήθει τῶν σφενδονητῶν τῶν προσαγορευομένων Κυρτίων. πράξας δὲ τὸ κριθὲν ταχεῖαν ἐποιεῖτο καὶ σύντονον τὴν πορείαν. ἅμα δὲ τοῦ τε Μόλωνος συνάπτοντος τοῖς προειρημένοις τόποις καὶ τοῦ βασιλέως ἐκ τῆς Ἀπολλωνίας ὁρμήσαντος μετὰ πάσης δυνάμεως, συνέβη τοὺς ὑπ’ ἀμφοτέρων προαποσταλέντας εὐζώνους ἅμα συμπεσεῖν ἐπί τινας ὑπερβολάς· οἳ τὸ μὲν πρῶτον συνεπλέκοντο καὶ κατεπείραζον ἀλλήλων, ἐν δὲ τῷ συνάψαι τὰς παρ’ ἀμφοῖν δυνάμεις ἀπέστησαν. καὶ τότε μὲν ἀναχωρήσαντες εἰς τὰς ἰδίας παρεμβολὰς ἐστρατοπέδευσαν τετταράκοντα σταδίους ἀπ’ ἀλλήλων διεστῶτες· τῆς δὲ νυκτὸς ἐπιγενομένης συλλογισάμενος ὁ Μόλων ὡς ἐπισφαλὴς γίνεται καὶ δύσχρηστος τοῖς ἀποστάταις πρὸς τοὺς βασιλεῖς ὁ μεθ’ ἡμέραν καὶ κατὰ πρόσωπον κίνδυνος, ἐπεβάλετο νυκτὸς ἐγχειρεῖν τοῖς περὶ τὸν Ἀντίοχον. ἐπιλέξας δὲ τοὺς ἐπιτηδειοτάτους καὶ τοὺς ἀκμαιοτάτους ἐκ παντὸς τοῦ στρατοπέδου περιῄει κατά τινας τόπους, θέλων ἐξ ὑπερδεξίου ποιήσασθαι τὴν ἐπίθεσιν. γνοὺς δὲ κατὰ τὴν πορείαν δέκα νεανίσκους ἁθρόους ἀποκεχωρηκότας πρὸς τὸν Ἀντίοχον, ταύτης μὲν τῆς ἐπινοίας ἀπέστη, ταχὺ δ’ ἐκ μεταβολῆς ποιησάμενος τὴν ἀποχώρησιν καὶ παραγενόμενος εἰς τὸν ἑαυτοῦ χάρακα περὶ τὴν ἑωθινήν, πᾶν τὸ στρατόπεδον ἐνέπλησε θορύβου καὶ ταραχῆς· δείσαντες γὰρ ἐκ τῶν ὕπνων οἱ κατὰ τὸν χάρακα διὰ τὴν τῶν προσιόντων ἔφοδον μικροῦ δεῖν ἐξέπεσον ἐκ τῆς παρεμβολῆς. Μόλων μὲν οὖν, καθ’ ὅσον ἐδύνατο, κατεπράϋνε τὴν γεγενημένην ἐν αὐτοῖς ταραχήν·", "st": "5.52"}, {"sp": "N", "t": "ὁ δὲ βασιλεὺς ἕτοιμος ὢν πρὸς τὸν κίνδυνον ἅμα τῷ φωτὶ τὴν δύναμιν ἐκίνει πᾶσαν ἐκ τοῦ χάρακος. ἐπὶ μὲν οὖν τοῦ δεξιοῦ κέρως ἔταξε πρώτους τοὺς ξυστοφόρους ἱππεῖς, ἐπιστήσας Ἄρδυν, κεκριμένον ἄνδρα περὶ τὰς πολεμικὰς πράξεις· τούτοις δὲ παρέθηκε τοὺς συμμαχικοὺς Κρῆτας, ὧν εἴχοντο Γαλάται Ῥιγόσαγες· παρὰ δὲ τούτους ἔθηκε τοὺς ἀπὸ τῆς Ἑλλάδος ξένους καὶ μισθοφόρους, οἷς ἑπόμενον παρενέβαλε τὸ τῆς φάλαγγος σύστημα. τὸ δ’ εὐώνυμον κέρας ἀπέδωκε τοῖς Ἑταίροις προσαγορευομένοις, οὖσιν ἱππεῦσι. τὰ δὲ θηρία πρὸ τῆς δυνάμεως ἐν διαστήμασι κατέστησε, δέκα τὸν ἀριθμὸν ὄντα. τὰ δ’ ἐπιτάγματα τῶν πεζῶν καὶ τῶν ἱππέων ἐπὶ τὰ κέρατα μερίσας κυκλοῦν παρήγγειλε τοὺς πολεμίους, ἐπειδὰν συμβάλωσι. μετὰ δὲ ταῦτα παρεκάλει τὰς δυνάμεις ἐπιπορευόμενος διὰ βραχέων τὰ πρέποντα τοῖς καιροῖς. καὶ τὸ μὲν εὐώνυμον κέρας Ἑρμείᾳ καὶ Ζεύξιδι παρέδωκε, τὸ δὲ δεξιὸν αὐτὸς εἶχε. Μόλων δὲ δύσχρηστον μὲν ἐποιήσατο τὴν ἐξαγωγήν, ταραχώδη δὲ καὶ τὴν ἔκταξιν διὰ τὴν ἐν τῇ νυκτὶ προγεγενημένην ἀλογίαν· οὐ μὴν ἀλλὰ τοὺς μὲν ἱππεῖς ἐφ’ ἑκάτερον ἐμερίσατο κέρας, στοχαζόμενος τῆς τῶν ὑπεναντίων παρατάξεως, τοὺς δὲ θυρεαφόρους καὶ Γαλάτας καὶ καθόλου τὰ βαρέα τῶν ὅπλων εἰς τὸν μεταξὺ τόπον ἔθηκε τῶν ἱππέων. ἔτι δὲ τοὺς τοξότας καὶ σφενδονήτας καὶ συλλήβδην τὸ τοιοῦτο γένος ἐκτὸς τῶν ἱππέων παρ’ ἑκάτερα παρενέβαλε, τὰ δὲ δρεπανηφόρα τῶν ἁρμάτων προεβάλετο τῆς δυνάμεως ἐν διαστάσει. καὶ τὸ μὲν εὐώνυμον κέρας Νεολάῳ παρέδωκε τἀδελφῷ, τὸ δὲ δεξιὸν αὐτὸς εἶχε.", "st": "5.53"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα ποιησαμένων τῶν δυνάμεων τὴν ἐπαγωγήν, τὸ μὲν δεξιὸν κέρας τοῦ Μόλωνος διετήρησε τὴν πίστιν καὶ συνέβαλε τοῖς περὶ τὸν Ζεῦξιν ἐρρωμένως, τὸ δ’ εὐώνυμον ἅμα τῷ συνιὸν εἰς ὄψιν ἐλθεῖν τῷ βασιλεῖ μετεβάλετο πρὸς τοὺς πολεμίους· οὗ γενομένου συνέβη τοὺς μὲν περὶ τὸν Μόλωνα διατραπῆναι, τοὺς δὲ τοῦ βασιλέως ἐπιρρωσθῆναι διπλασίως. ὁ δὲ Μόλων συννοήσας τὸ γεγονὸς καὶ πανταχόθεν ἤδη κυκλούμενος, λαβὼν πρὸ ὀφθαλμῶν τὰς ἐσομένας περὶ αὑτὸν αἰκίας, ἐὰν ὑποχείριος γένηται καὶ ζωγρίᾳ ληφθῇ, προσήνεγκε τὰς χεῖρας ἑαυτῷ. παραπλησίως δὲ καὶ πάντες οἱ κοινωνήσαντες τῆς ἐπιβολῆς, φυγόντες εἰς τοὺς οἰκείους ἕκαστοι τόπους, τὴν αὐτὴν ἐποιήσαντο τοῦ βίου καταστροφήν. ὁ δὲ Νεόλαος, ἀποφυγὼν ἐκ τῆς μάχης καὶ παραγενόμενος εἰς τὴν Περσίδα πρὸς Ἀλέξανδρον τὸν τοῦ Μόλωνος ἀδελφόν, τὴν μὲν μητέρα καὶ τὰ τοῦ Μόλωνος τέκνα κατέσφαξε, μετὰ δὲ τὸν τούτων θάνατον ἐπικατέσφαξεν αὑτόν, πείσας τὸ παραπλήσιον ποιῆσαι καὶ τὸν Ἀλέξανδρον. ὁ δὲ βασιλεὺς διαρπάσας τὴν παρεμβολὴν τῶν πολεμίων, τὸ μὲν σῶμα τοῦ Μόλωνος ἀνασταυρῶσαι προσέταξε κατὰ τὸν ἐπιφανέστατον τόπον τῆς Μηδίας. ὃ καὶ παραχρῆμα συνετέλεσαν οἱ πρὸς τούτοις τεταγμένοι· διακομίσαντες γὰρ εἰς τὴν Καλλωνῖτιν πρὸς αὐταῖς ἀνεσταύρωσαν ταῖς εἰς τὸν Ζάγρον ἀναβολαῖς· μετὰ ταῦτα δὲ ταῖς δυνάμεσιν ἐπιτιμήσας διὰ πλειόνων καὶ δοὺς δεξιὰν συνέστησε τοὺς ἀποκομιοῦντας αὐτοὺς εἰς Μηδίαν καὶ καταστησομένους τὰ κατὰ τὴν χώραν. αὐτὸς δὲ καταβὰς εἰς Σελεύκειαν καθίστατο τὰ κατὰ τὰς πέριξ σατραπείας, ἡμέρως χρώμενος πᾶσι καὶ νουνεχῶς. Ἑρμείας δὲ τηρῶν τὴν αὑτοῦ προαίρεσιν ἐπέφερε μὲν αἰτίας τοῖς ἐν τῇ Σελευκείᾳ καὶ χιλίοις ἐζημίου ταλάντοις τὴν πόλιν, ἐφυγάδευε δὲ τοὺς καλουμένους Ἀδειγάνας, ἀκρωτηριάζων δὲ καὶ φονεύων καὶ στρεβλῶν πολλοὺς διέφθειρε τῶν Σελευκέων. ἃ μόλις βασιλεύς, τὰ μὲν πείθων τὸν Ἑρμείαν, ἃ δὲ καὶ κατὰ τὴν αὑτοῦ γνώμην χειρίζων, τέλος ἐπράϋνε καὶ κατέστησε τὴν πόλιν, ἑκατὸν καὶ πεντήκοντα τάλαντα μόνον ἐπιτίμιον αὐτοὺς πραξάμενος τῆς ἀγνοίας. ταῦτα δὲ διοικήσας Διογένην μὲν στρατηγὸν ἀπέλιπε Μηδίας, Ἀπολλόδωρον δὲ τῆς Σουσιανῆς· Τύχωνα δὲ τὸν ἀρχιγραμματέα τῆς δυνάμεως στρατηγὸν ἐπὶ τοὺς κατὰ τὴν Ἐρυθρὰν θάλατταν τόπους ἐξαπέστειλε. τὰ μὲν οὖν κατὰ τὴν Μόλωνος ἀπόστασιν καὶ τὸ διὰ ταῦτα γενόμενον κίνημα περὶ τὰς ἄνω σατραπείας τοιαύτης ἔτυχε διορθώσεως καὶ καταστάσεως.", "st": "5.54"}, {"sp": "N", "t": "ὁ δὲ βασιλεὺς ἐπαρθεὶς τῷ γεγονότι προτερήματι, καὶ βουλόμενος ἀναταθῆναι καὶ καταπλήξασθαι τοὺς ὑπερκειμένους ταῖς ἑαυτοῦ σατραπείαις καὶ συνοροῦντας δυνάστας τῶν βαρβάρων, ἵνα μήτε συγχορηγεῖν μήτε συμπολεμεῖν τολμῶσι τοῖς ἀποστάταις αὐτοῦ γινομένοις, ἐπεβάλετο στρατεύειν ἐπ’ αὐτούς, καὶ πρῶτον ἐπὶ τὸν Ἀρταβαζάνην, ὃς ἐδόκει βαρύτατος εἶναι καὶ πρακτικώτατος τῶν δυναστῶν, δεσπόζειν δὲ καὶ τῶν Σατραπείων καλουμένων καὶ τῶν τούτοις συντερμονούντων ἐθνῶν. Ἑρμείας δὲ κατὰ τοὺς καιροὺς τούτους ἐδεδίει μὲν τὴν εἰς τοὺς ἄνω τόπους στρατείαν διὰ τὸν κίνδυνον, ὠρέγετο δὲ κατὰ τὴν ἐξ ἀρχῆς πρόθεσιν τῆς ἐπὶ τὸν Πτολεμαῖον στρατείας· οὐ μὴν ἀλλὰ προσπεσόντος υἱὸν γεγονέναι τῷ βασιλεῖ, νομίσας καὶ παθεῖν ἄν τι τὸν Ἀντίοχον ἐν τοῖς ἄνω τόποις ὑπὸ τῶν βαρβάρων καὶ παραδοῦναι καιροὺς αὑτῷ πρὸς ἐπαναίρεσιν, συγκατέθετο τῇ στρατείᾳ, πεπεισμένος, ἐὰν ἐπανέληται τὸν Ἀντίοχον, ἐπιτροπεύων τοῦ παιδίου κύριος ἔσεσθαι τῆς ἀρχῆς αὐτός. κριθέντων δὲ τούτων ὑπερβαλόντες τὸν Ζάγρον ἐνέβαλον εἰς τὴν Ἀρταβαζάνου χώραν, ἣ παράκειται μὲν τῇ Μηδίᾳ, διειργούσης αὐτὴν τῆς ἀνὰ μέσον κειμένης ὀρεινῆς, ὑπέρκειται δ’ αὐτῆς τινὰ μέρη τοῦ Πόντου κατὰ τοὺς ὑπὲρ τὸν Φᾶσιν τόπους, συνάπτει δὲ πρὸς τὴν Ὑρκανίαν θάλατταν, ἔχει δὲ πλῆθος ἀνδρῶν ἀλκίμων καὶ μᾶλλον ἱππέων, αὐτάρκης δὲ καὶ ταῖς λοιπαῖς ἐστι ταῖς πρὸς τὸν πόλεμον παρασκευαῖς. ταύτην δὲ συμβαίνει τὴν ἀρχὴν ἀπὸ Περσῶν ἔτι διατηρεῖσθαι, παροραθείσης αὐτῆς ἐν τοῖς κατ’ Ἀλέξανδρον καιροῖς. ὁ δ’ Ἀρταβαζάνης, καταπλαγεὶς τὴν ἔφοδον τοῦ βασιλέως, καὶ μάλιστα διὰ τὴν ἡλικίαν, τελέως γὰρ ἤδη γηραιὸς ἦν, εἴξας τοῖς παροῦσιν ἐποιήσατο συνθήκας εὐδοκουμένας Ἀντιόχῳ.", "st": "5.55"}, {"sp": "N", "t": "τούτων δὲ κυρωθέντων Ἀπολλοφάνης ὁ ἰατρός, ἀγαπώμενος ὑπὸ τοῦ βασιλέως διαφερόντως, θεωρῶν τὸν Ἑρμείαν οὐκέτι φέροντα κατὰ σχῆμα τὴν ἐξουσίαν, ἠγωνία μὲν καὶ περὶ τοῦ βασιλέως, τὸ δὲ πλεῖον ὑπώπτευε καὶ κατάφοβος ἦν ὑπὲρ τῶν καθ’ αὑτόν. διὸ λαβὼν καιρὸν προσφέρει τῷ βασιλεῖ λόγον, παρακαλῶν μὴ ῥᾳθυμεῖν μηδ’ ἀνυπονόητον εἶναι τῆς Ἑρμείου τόλμης, μηδ’ ἕως τούτου περιμεῖναι μέχρις ἂν οὗ τοῖς ὁμοίοις τἀδελφῷ παλαίῃ συμπτώμασιν. ἀπέχειν δ’ οὐ μακρὰν αὐτὸν ἔφη τοῦ κινδύνου· διὸ προσέχειν ἠξίου καὶ βοηθεῖν κατὰ σπουδὴν αὑτῷ τε καὶ τοῖς φίλοις. τοῦ δ’ Ἀντιόχου πρὸς αὐτὸν ἀνθομολογησαμένου διότι καὶ δυσαρεστεῖ καὶ φοβεῖται τὸν Ἑρμείαν, ἐκείνῳ δὲ μεγάλην χάριν ἔχειν φήσαντος ἐπὶ τῷ κηδεμονικῶς τετολμηκέναι περὶ τούτων εἰπεῖν πρὸς αὐτόν, ὁ μὲν Ἀπολλοφάνης εὐθαρσὴς ἐγένετο τῷ δοκεῖν μὴ διεψεῦσθαι τῆς αἱρέσεως καὶ διαλήψεως τῆς τοῦ βασιλέως, ὁ δ’ Ἀντίοχος ἠξίου τὸν Ἀπολλοφάνην συνεπιλαβέσθαι μὴ μόνον τοῖς λόγοις, ἀλλὰ καὶ τοῖς ἔργοις τῆς αὑτοῦ τε καὶ τῶν φίλων σωτηρίας. τοῦ δὲ πρὸς πᾶν ἑτοίμως ἔχειν φήσαντος, συμφρονήσαντες μετὰ ταῦτα καὶ προβαλόμενοι σκῆψιν ὡς σκοτωμάτων τινῶν ἐπιπεπτωκότων τῷ βασιλεῖ, τὴν μὲν θεραπείαν ἀπέλυσαν ἐπί τινας ἡμέρας καὶ τοὺς εἰθισμένους παρευτακτεῖν, πρὸς δὲ τοὺς φίλους ἔλαβον ἐξουσίαν οἷς βούλοιντο κατ’ ἰδίαν χρηματίζειν διὰ τὴν τῆς ἐπισκέψεως πρόφασιν. ἐν ᾧ καιρῷ κατασκευασάμενοι τοὺς ἐπιτηδείους πρὸς τὴν πρᾶξιν, πάντων ἑτοίμως αὐτοῖς συνυπακουόντων διὰ τὸ πρὸς τὸν Ἑρμείαν μῖσος, ἐγίνοντο πρὸς τὸ συντελεῖν τὴν ἐπιβολήν. φασκόντων δὲ δεῖν τῶν ἰατρῶν ἅμα τῷ φωτὶ ποιεῖσθαι τοὺς περιπάτους ὑπὸ τὸ ψῦχος τὸν Ἀντίοχον, ὁ μὲν Ἑρμείας ἧκε πρὸς τὸν ταχθέντα καιρόν, ἅμα δὲ τούτῳ καὶ τῶν φίλων οἱ συνειδότες τὴν πρᾶξιν, οἱ δὲ λοιποὶ καθυστέρουν διὰ τὸ πολὺ παρηλλάχθαι τὴν ἔξοδον τοῦ βασιλέως πρὸς τὸν εἰθισμένον καιρόν. διόπερ ἀποσπάσαντες αὐτὸν ἀπὸ τῆς στρατοπεδείας εἴς τινα τόπον ἔρημον, κἄπειτα μικρὸν ἀπονεύσαντος τοῦ βασιλέως ὡς ἐπί τι τῶν ἀναγκαίων, ἐξεκέντησαν. Ἑρμείας μὲν οὖν τούτῳ τῷ τρόπῳ μετήλλαξε τὸν βίον, οὐδεμίαν ὑποσχὼν τιμωρίαν ἀξίαν τῶν αὑτῷ πεπραγμένων· ὁ δὲ βασιλεὺς ἀπολυθεὶς φόβου καὶ δυσχρηστίας πολλῆς ἐπανῆγε ποιούμενος τὴν πορείαν ὡς ἐπ’ οἴκου, πάντων τῶν κατὰ τὴν χώραν ἀποδεχομένων τάς τε πράξεις αὐτοῦ καὶ τὰς ἐπιβολάς, καὶ μάλιστα κατὰ τὴν δίοδον ἐπισημαινομένων τὴν Ἑρμείου μετάστασιν. ἐν ᾧ καιρῷ καὶ κατὰ τὴν Ἀπάμειαν αἱ μὲν γυναῖκες τὴν γυναῖκα τὴν Ἑρμείου κατέλευσαν, οἱ δὲ παῖδες τοὺς υἱεῖς.", "st": "5.56"}, {"sp": "N", "t": "Ἀντίοχος δὲ παραγενόμενος εἰς τὴν οἰκείαν, καὶ διαφεὶς τὰς δυνάμεις εἰς παραχειμασίαν, διεπέμπετο πρὸς τὸν Ἀχαιόν, ἐγκαλῶν καὶ διαμαρτυρόμενος πρῶτον μὲν ἐπὶ τῷ τετολμηκέναι διάδημα περιθέσθαι καὶ βασιλέα χρηματίζειν, δεύτερον δὲ προλέγων ὡς οὐ λανθάνει κοινοπραγῶν Πτολεμαίῳ καὶ καθόλου πλείω τοῦ δέοντος κινούμενος. ὁ γὰρ Ἀχαιός, καθ’ οὓς καιροὺς ἐπὶ τὸν Ἀρταβαζάνην ὁ βασιλεὺς ἐστράτευε, πεισθεὶς καὶ παθεῖν ἄν τι τὸν Ἀντίοχον, καὶ μὴ παθόντος ἐλπίσας διὰ τὸ μῆκος τῆς ἀποστάσεως φθάσειν ἐμβαλὼν εἰς Συρίαν καὶ συνεργοῖς χρησάμενος Κυρρησταῖς τοῖς ἀποστάταις γεγονόσι τοῦ βασιλέως ταχέως ἂν κρατῆσαι τῶν κατὰ τὴν βασιλείαν πραγμάτων, ὥρμησε μετὰ πάσης τῆς δυνάμεως ἐκ Λυδίας. παραγενόμενος δ’ εἰς Λαοδίκειαν τὴν ἐν Φρυγίᾳ διάδημά τε περιέθετο καὶ βασιλεὺς τότε πρῶτον ἐτόλμησε χρηματίζειν καὶ γράφειν πρὸς τὰς πόλεις; Γαρσυήριδος αὐτὸν τοῦ φυγάδος εἰς τοῦτο τὸ μέρος μάλιστα προτρεψαμένου. προάγοντος δὲ κατὰ τὸ συνεχὲς αὐτοῦ, καὶ σχεδὸν ἤδη περὶ Λυκαονίαν ὄντος, αἱ δυνάμεις ἐστασίασαν, δυσαρεστούμεναι τῷ δοκεῖν γίνεσθαι τὴν στρατείαν ἐπὶ τὸν κατὰ φύσιν αὐτῶν ἐξ ἀρχῆς ὑπάρχοντα βασιλέα. διόπερ Ἀχαιὸς συνεὶς τὴν ἐν αὐτοῖς διατροπὴν τῆς μὲν προκειμένης ἐπιβολῆς ἀπέστη, βουλόμενος δὲ πεισθῆναι τὰς δυνάμεις ὡς οὐδ’ ἐξ ἀρχῆς ἐπεβάλετο στρατεύειν εἰς Συρίαν, ἐπιστρέψας πορθεῖ τὴν Πισιδικήν, καὶ πολλὰς ὠφελείας παρασκευάσας τῷ στρατοπέδῳ, πάντας εὔνους αὑτῷ καὶ πεπιστευκότας ἔχων ἐπανῆλθε πάλιν εἰς τὴν οἰκείαν.", "st": "5.57"}, {"sp": "N", "t": "ὁ δὲ βασιλεὺς σαφῶς ἕκαστα τούτων ἐπεγνωκώς, πρὸς μὲν τὸν Ἀχαιὸν διεπέμπετο συνεχῶς ἀνατεινόμενος, καθάπερ ἐπάνω προεῖπον, πρὸς δὲ ταῖς ἐπὶ τὸν Πτολεμαῖον παρασκευαῖς ὅλος καὶ πᾶς ἦν. διὸ καὶ συναθροίσας εἰς Ἀπάμειαν τὰς δυνάμεις ὑπὸ τὴν ἐαρινὴν ὥραν, ἀνέδωκε τοῖς φίλοις διαβούλιον πῶς χρηστέον ἐστὶ ταῖς εἰς Κοίλην Συρίαν εἰσβολαῖς. πολλῶν δ’ εἰς τοῦτο τὸ μέρος ῥηθέντων καὶ περὶ τῶν τόπων καὶ περὶ παρασκευῆς καὶ περὶ τῆς κατὰ τὴν ναυτικὴν δύναμιν συνεργείας, Ἀπολλοφάνης, ὑπὲρ οὗ καὶ πρότερον εἴπαμεν, τὸ γένος ὢν Σελευκεύς, ἐπέτεμε πάσας τὰς προειρημένας γνώμας· ἔφη γὰρ εὔηθες εἶναι τὸ Κοίλης μὲν Συρίας ἐπιθυμεῖν καὶ στρατεύειν ἐπὶ ταύτην, Σελεύκειαν δὲ περιορᾶν ὑπὸ Πτολεμαίου κρατουμένην, ἀρχηγέτιν οὖσαν καὶ σχεδὸν ὡς εἰπεῖν ἑστίαν ὑπάρχουσαν τῆς αὑτῶν δυναστείας. ἣν χωρὶς τῆς αἰσχύνης, ἣν περιποιεῖ νῦν τῇ βασιλείᾳ φρουρουμένη διὰ τῶν ἐν Αἰγύπτῳ βασιλέων, καὶ πρὸς πραγμάτων λόγον μεγίστας ἔχειν καὶ καλλίστας ἀφορμάς. κρατουμένην μὲν γὰρ ὑπὸ τῶν ἐχθρῶν μέγιστον ἐμπόδιον εἶναι πρὸς πάσας αὐτοῖς τὰς ἐπιβολάς· οὗ γὰρ ἂν ἐπινοήσωσιν ἀεὶ προβαίνειν, οὐκ ἐλάττονος δεῖσθαι προνοίας καὶ φυλακῆς αὐτοῖς τοὺς οἰκείους τόπους διὰ τὸν ἀπὸ ταύτης φόβον τῆς ἐπὶ τοὺς πολεμίους παρασκευῆς. κρατηθεῖσάν γε μὴν οὐ μόνον ἔφη δύνασθαι βεβαίως τηρεῖν τὴν οἰκείαν, ἀλλὰ καὶ πρὸς τὰς ἄλλας ἐπινοίας καὶ προθέσεις καὶ κατὰ γῆν καὶ κατὰ θάλατταν μεγάλα δύνασθαι συνεργεῖν διὰ τὴν εὐκαιρίαν τοῦ τόπου. πεισθέντων δὲ πάντων τοῖς λεγομένοις, ἔδοξε ταύτην πρώτην ἐξαιρεῖν τὴν πόλιν· συνέβαινε γὰρ Σελεύκειαν ἔτι τότε κατέχεσθαι φρουραῖς ὑπὸ τῶν ἐξ Αἰγύπτου βασιλέων ἐκ τῶν κατὰ τὸν Εὐεργέτην ἐπικληθέντα Πτολεμαῖον καιρῶν, ἐν οἷς ἐκεῖνος διὰ τὰ Βερενίκης συμπτώματα καὶ τὴν ὑπὲρ ἐκείνης ὀργὴν στρατεύσας εἰς τοὺς κατὰ Συρίαν τόπους ἐγκρατὴς ἐγένετο ταύτης τῆς πόλεως.", "st": "5.58"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ Ἀντίοχος κριθέντων τούτων Διογνήτῳ μὲν τῷ ναυάρχῳ παρήγγειλε πλεῖν ὡς ἐπὶ τῆς Σελευκείας, αὐτὸς δ’ ἐκ τῆς Ἀπαμείας ὁρμήσας μετὰ τῆς στρατιᾶς, καὶ περὶ πέντε σταδίους ἀποσχὼν τῆς πόλεως, προσεστρατοπέδευσε κατὰ τὸν ἱππόδρομον. Θεόδοτον δὲ τὸν ἡμιόλιον ἐξαπέστειλε μετὰ τῆς ἁρμοζούσης δυνάμεως ἐπὶ τοὺς κατὰ Κοίλην Συρίαν τόπους, καταληψόμενον τὰ στενὰ καὶ προκαθησόμενον ἅμα τῶν αὑτοῦ πραγμάτων. τὴν δὲ τῆς Σελευκείας θέσιν καὶ τὴν τῶν πέριξ τόπων ἰδιότητα τοιαύτην ἔχειν τὴν φύσιν συμβαίνει. κειμένης γὰρ αὐτῆς ἐπὶ θαλάττῃ μεταξὺ Κιλικίας καὶ Φοινίκης, ὄρος ἐπίκειται παμμέγεθες, ὃ καλοῦσι Κορυφαῖον· ᾧ πρὸς μὲν τὴν ἀφ’ ἑσπέρας πλευρὰν προσκλύζει τὸ καταλῆγον τοῦ πελάγους τοῦ μεταξὺ κειμένου Κύπρου καὶ Φοινίκης, τοῖς δ’ ἀπὸ τῆς ἠοῦς μέρεσιν ὑπέρκειται τῆς Ἀντιοχέων καὶ Σελευκέων χώρας. ἐν δὲ τοῖς πρὸς μεσημβρίαν αὐτοῦ κλίμασι τὴν Σελεύκειαν συμβαίνει κεῖσθαι, διεζευγμένην φάραγγι κοίλῃ καὶ δυσβάτῳ, καθήκουσαν μὲν καὶ περικλωμένην ὡς ἐπὶ θάλατταν, κατὰ δὲ τὰ πλεῖστα μέρη κρημνοῖς καὶ πέτραις ἀπορρῶξι περιεχομένην. ὑπὸ δὲ τὴν ἐπὶ θάλατταν αὐτῆς νεύουσαν πλευρὰν ἐν τοῖς ἐπιπέδοις τά τ’ ἐμπόρια καὶ τὸ προάστειον κεῖται, διαφερόντως τετειχισμένον. παραπλησίως δὲ καὶ τὸ σύμπαν τῆς πόλεως κύτος τείχεσι πολυτελέσιν ἠσφάλισται, κεκόσμηται δὲ καὶ ναοῖς καὶ ταῖς τῶν οἰκοδομημάτων κατασκευαῖς ἐκπρεπῶς. πρόσβασιν δὲ μίαν ἔχει κατὰ τὴν ἀπὸ θαλάττης πλευρὰν κλιμακωτὴν καὶ χειροποίητον, ἐγκλίμασι καὶ σκαιώμασι πυκνοῖς καὶ συνεχέσι διειλημμένην. ὁ δὲ καλούμενος Ὀρόντης ποταμὸς οὐ μακρὰν αὐτῆς ποιεῖται τὰς ἐκβολάς, ὃς τὴν ἀρχὴν τοῦ ῥεύματος λαμβάνων ἀπὸ τῶν κατὰ τὸν Λίβανον καὶ τὸν Ἀντιλίβανον τόπων, καὶ διανύσας τὸ καλούμενον Ἀμύκης πεδίον, ἐπ’ αὐτὴν ἱκνεῖται τὴν Ἀντιόχειαν, δι’ ἧς φερόμενος καὶ πάσας ὑποδεχόμενος τὰς ἀνθρωπείας λύμας διὰ τὸ πλῆθος τοῦ ῥεύματος, τέλος οὐ μακρὰν τῆς Σελευκείας ποιεῖται τὴν ἐκβολὴν εἰς τὸ προειρημένον πέλαγος.", "st": "5.59"}, {"sp": "N", "t": "Ἀντίοχος δὲ τὸ μὲν πρῶτον διεπέμπετο πρὸς τοὺς ἐπιστάτας τῆς πόλεως, προτείνων χρήματα καὶ πλῆθος ἐλπίδων, ἐφ’ ᾧ παραλαβεῖν ἄνευ κινδύνου τὴν Σελεύκειαν· ἀδυνατῶν δὲ πείθειν τοὺς ἐπὶ τῶν ὅλων ἐφεστῶτας ἔφθειρέ τινας τῶν κατὰ μέρος ἡγεμόνων, οἷς πιστεύσας ἡτοίμαζε τὴν δύναμιν, ὡς κατὰ μὲν τὸν ἀπὸ θαλάττης τόπον τοῖς ἀπὸ τοῦ ναυτικοῦ ποιησόμενος τὰς προσβολάς, κατὰ δὲ τὸν ἀπὸ τῆς ἠπείρου τοῖς ἐκ τοῦ στρατοπέδου. διελὼν οὖν εἰς τρία μέρη τὴν δύναμιν, καὶ παρακαλέσας τὰ πρέποντα τῷ καιρῷ, καὶ δωρεὰς μεγάλας καὶ στεφάνους ἐπ’ ἀνδραγαθίᾳ καὶ τοῖς ἰδιώταις καὶ τοῖς ἡγεμόσι προκηρύξας, Ζεύξιδι μὲν καὶ τοῖς μετ’ αὐτοῦ παρέδωκε τοὺς κατὰ τὴν ἐπ’ Ἀντιόχειαν φέρουσαν πύλην τόπους, Ἑρμογένει δὲ τοὺς κατὰ τὸ Διοσκούριον, Ἄρδυϊ δὲ καὶ Διογνήτῳ τὰς κατὰ τὸ νεώριον καὶ τὸ προάστειον ἐπέτρεψε προσβολάς, διὰ τὸ πρὸς τοὺς ἔνδοθεν αὐτῷ τοιαύτας τινὰς γεγονέναι συνθήκας ὡς ἐὰν κρατήσῃ τοῦ προαστείου μετὰ βίας, οὕτως ἐγχειρισθησομένης αὐτῷ καὶ τῆς πόλεως. ἀποδοθέντος δὲ τοῦ συνθήματος πάντες ἅμα καὶ πανταχόθεν ἐνεργὸν ἐποιοῦντο καὶ βίαιον τὴν προσβολήν· τολμηρότατα μέντοι προσέβαλον οἱ περὶ τὸν Ἄρδυν καὶ Διόγνητον, διὰ τὸ τοὺς μὲν ἄλλους τόπους, εἰ μὴ τετραποδητὶ τρόπον τινὰ προσπλεκόμενοι βιάζοιντο, τήν γε διὰ τῶν κλιμάκων προσβολὴν μὴ προσίεσθαι παράπαν, τὰ δὲ νεώρια καὶ τὸ προάστειον ἐπιδέχεσθαι τὴν προσφορὰν καὶ στάσιν καὶ πρόσθεσιν τῶν κλιμάκων ἀσφαλῶς. διὸ τῶν μὲν ἀπὸ τοῦ ναυτικοῦ τοῖς νεωρίοις, τῶν δὲ περὶ τὸν Ἄρδυν τοῖς προαστείοις προσηρεικότων τὰς κλίμακας καὶ βιαζομένων εὐρώστως, τῶν δ’ ἐκ τῆς πόλεως οὐ δυναμένων τούτοις βοηθεῖν, διὰ τὸ κατὰ πάντα τόπον περιεστάναι τὸ δεινόν, ταχέως συνέβη τὸ προάστειον ὑποχείριον γενέσθαι τοῖς περὶ τὸν Ἄρδυν. οὗ κρατηθέντος εὐθέως οἱ διεφθαρμένοι τῶν κατὰ μέρος ἡγεμόνων, προστρέχοντες πρὸς τὸν Λεόντιον τὸν ἐπὶ τῶν ὅλων, ἐκπέμπειν ᾤοντο δεῖν καὶ τίθεσθαι τὰ πρὸς Ἀντίοχον πρὶν ἢ κατὰ κράτος ἁλῶναι τὴν πόλιν. ὁ δὲ Λεόντιος, ἀγνοῶν μὲν τὴν διαφθορὰν τῶν ἡγεμόνων, καταπεπληγμένος δὲ τὴν διατροπὴν αὐτῶν, ἐξέπεμψε τοὺς θησομένους τὰς πίστεις ὑπὲρ τῆς τῶν ἐν τῇ πόλει πάντων ἀσφαλείας πρὸς τὸν Ἀντίοχον.", "st": "5.60"}, {"sp": "N", "t": "ὁ δὲ βασιλεὺς δεξάμενος τὴν ἔντευξιν συνεχώρησε δώσειν τοῖς ἐλευθέροις τὴν ἀσφάλειαν· οὗτοι δ’ ἦσαν εἰς ἑξακισχιλίους. παραλαβὼν δὲ τὴν πόλιν οὐ μόνον ἐφείσατο τῶν ἐλευθέρων, ἀλλὰ καὶ τοὺς πεφευγότας τῶν Σελευκέων καταγαγὼν τήν τε πολιτείαν αὐτοῖς ἀπέδωκε καὶ τὰς οὐσίας· ἠσφαλίσατο δὲ φυλακαῖς τόν τε λιμένα καὶ τὴν ἄκραν. ἔτι δὲ περὶ ταῦτα διατρίβοντος αὐτοῦ, προσπεσόντων παρὰ Θεοδότου γραμμάτων, ἐν οἷς αὐτὸν ἐκάλει κατὰ σπουδὴν ἐγχειρίζων τὰ κατὰ Κοίλην Συρίαν, πολλῆς ἀπορίας ἦν καὶ δυσχρηστίας πλήρης ὑπὲρ τοῦ τί πρακτέον καὶ πῶς χρηστέον ἐστὶ τοῖς προσαγγελλομένοις. ὁ δὲ Θεόδοτος, ὢν τὸ γένος Αἰτωλὸς καὶ μεγάλας παρεσχημένος τῇ Πτολεμαίου βασιλείᾳ χρείας, καθάπερ ἐπάνω προεῖπον, ἐπὶ δὲ τούτοις οὐχ οἷον χάριτος ἠξιωμένος, ἀλλὰ καὶ τῷ βίῳ κεκινδυνευκὼς καθ’ οὓς καιροὺς Ἀντίοχος ἐποιεῖτο τὴν ἐπὶ Μόλωνα στρατείαν, τότε κατεγνωκὼς τοῦ βασιλέως καὶ διηπιστηκὼς τοῖς περὶ τὴν αὐλήν, καταλαβόμενος διὰ μὲν αὑτοῦ Πτολεμαΐδα, διὰ δὲ Παναιτώλου Τύρον, ἐκάλει τὸν Ἀντίοχον μετὰ σπουδῆς. ὁ δὲ βασιλεὺς καὶ τὰς ἐπὶ τὸν Ἀχαιὸν ἐπιβολὰς ὑπερθέμενος καὶ τἄλλα πάντα πάρεργα ποιησάμενος ἀνέζευξε μετὰ τῆς δυνάμεως, ποιούμενος τὴν πορείαν ᾗ καὶ πρόσθεν. διελθὼν δὲ τὸν ἐπικαλούμενον αὐλῶνα Μαρσύαν, κατεστρατοπέδευσε περὶ τὰ στενὰ τὰ κατὰ Γέρρα πρὸς τῇ μεταξὺ κειμένῃ λίμνῃ. πυνθανόμενος δὲ Νικόλαον τὸν παρὰ Πτολεμαίου στρατηγὸν προσκαθῆσθαι τῇ Πτολεμαΐδι πολιορκοῦντα τὸν Θεόδοτον, τὰ μὲν βαρέα τῶν ὅπλων ἀπέλειπε, προστάξας τοῖς ἡγουμένοις πολιορκεῖν τοὺς Βρόχους, τὸ κείμενον ἐπὶ τῆς λίμνης καὶ τῆς παρόδου χωρίον, αὐτὸς δὲ τοὺς εὐζώνους ἀναλαβὼν προῆγε, βουλόμενος λῦσαι τὴν πολιορκίαν. ὁ δὲ Νικόλαος πρότερον ἤδη πεπυσμένος τὴν τοῦ βασιλέως παρουσίαν, αὐτὸς μὲν ἀνεχώρησε, τοὺς δὲ περὶ Λαγόραν τὸν Κρῆτα καὶ Δορυμένην τὸν Αἰτωλὸν ἐξαπέστειλε προκαταληψομένους τὰ στενὰ τὰ περὶ Βηρυτόν· οἷς προσβαλὼν ὁ βασιλεὺς ἐξ ἐφόδου καὶ τρεψάμενος ἐπεστρατοπέδευσε τοῖς στενοῖς.", "st": "5.61"}, {"sp": "N", "t": "προσδεξάμενος δὲ καὶ τὴν λοιπὴν δύναμιν ἐνταῦθα, καὶ παρακαλέσας τὰ πρέποντα ταῖς προκειμέναις ἐπιβολαῖς, μετὰ ταῦτα προήγαγε μετὰ πάσης τῆς δυνάμεως, εὐθαρσὴς καὶ μετέωρος ὢν πρὸς τὰς ὑπογραφομένας ἐλπίδας. ἀπαντησάντων δὲ τῶν περὶ τὸν Θεόδοτον καὶ Παναίτωλον αὐτῷ καὶ τῶν ἅμα τούτοις φίλων, ἀποδεξάμενος τούτους φιλανθρώπως παρέλαβε τήν τε Τύρον καὶ Πτολεμαΐδα καὶ τὰς ἐν ταύταις παρασκευάς, ἐν αἷς ἦν καὶ πλοῖα τετταράκοντα· τούτων κατάφρακτα μὲν εἴκοσι διαφέροντα ταῖς κατασκευαῖς, ἐν οἷς οὐδὲν ἔλαττον ἦν τετρήρους, τὰ δὲ λοιπὰ τριήρεις καὶ δίκροτα καὶ κέλητες. ταῦτα μὲν οὖν Διογνήτῳ παρέδωκε τῷ ναυάρχῳ· προσπεσόντος δ’ αὐτῷ τὸν μὲν Πτολεμαῖον εἰς Μέμφιν ἐξεληλυθέναι, τὰς δὲ δυνάμεις ἡθροῖσθαι πάσας εἰς Πηλούσιον καὶ τάς τε διώρυχας ἀναστομοῦν καὶ τὰ πότιμα τῶν ὑδάτων ἐμφράττειν, τῆς μὲν ἐπὶ τὸ Πηλούσιον ἐπιβολῆς ἀπέστη, τὰς δὲ πόλεις ἐπιπορευόμενος ἐπειρᾶτο τὰς μὲν βίᾳ, τὰς δὲ πειθοῖ, πρὸς αὑτὸν ἐπάγεσθαι. τῶν δὲ πόλεων αἱ μὲν ἐλαφραὶ καταπεπληγμέναι τὴν ἔφοδον αὐτοῦ προσετίθεντο· αἱ δὲ πιστεύουσαι ταῖς παρασκευαῖς καὶ ταῖς ὀχυρότησι τῶν τόπων ὑπέμενον· ἃς ἠναγκάζετο προσκαθεζόμενος πολιορκεῖν καὶ κατατρίβειν τοὺς χρόνους. οἱ δὲ περὶ τὸν Πτολεμαῖον τοῦ μὲν ἐκ χειρὸς βοηθεῖν τοῖς σφετέροις πράγμασιν, ὅπερ ἦν καθῆκον, οὕτως παρεσπονδημένοι προφανῶς, οὐδ’ ἐπιβολὴν εἶχον διὰ τὴν ἀδυναμίαν· ἐπὶ τοσοῦτον γὰρ αὐτοῖς ὠλιγώρητο πάντα τὰ κατὰ τὰς πολεμικὰς παρασκευάς.", "st": "5.62"}, {"sp": "N", "t": "λοιπὸν δὲ συνεδρεύσαντες οἱ περὶ τὸν Ἀγαθοκλέα καὶ Σωσίβιον, οἱ τότε προεστῶτες τῆς βασιλείας, ἐκ τῶν ἐνδεχομένων τὸ δυνατὸν ἔλαβον πρὸς τὸ παρόν. ἐβουλεύσαντο γὰρ γίνεσθαι μὲν περὶ τὴν τοῦ πολέμου παρασκευήν, ἐν δὲ τῷ μεταξὺ διαπρεσβευόμενοι κατεκλύειν τὸν Ἀντίοχον, συνεργοῦντες κατὰ τὴν ἔμφασιν τῇ προϋπαρχούσῃ περὶ αὐτὸν ὑπὲρ τοῦ Πτολεμαίου διαλήψει· αὕτη δ’ ἦν ὡς πολεμεῖν μὲν οὐκ ἂν τολμήσαντος, διὰ λόγου δὲ καὶ τῶν φίλων διδάξοντος καὶ πείσοντος αὐτὸν ἀποστῆναι τῶν κατὰ Κοίλην Συρίαν τόπων. κριθέντων δὲ τούτων οἱ περὶ τὸν Ἀγαθοκλέα καὶ Σωσίβιον ἐπὶ τοῦτο τὸ μέρος ταχθέντες ἐξέπεμπον ἐπιμελῶς τὰς πρεσβείας πρὸς τὸν Ἀντίοχον. ἅμα δὲ διαπεμψάμενοι πρός τε Ῥοδίους καὶ Βυζαντίους καὶ Κυζικηνούς, σὺν δὲ τούτοις Αἰτωλούς, ἐπεσπάσαντο πρεσβείας ἐπὶ τὰς διαλύσεις. αἳ καὶ παραγενόμεναι μεγάλας αὐτοῖς ἔδοσαν ἀφορμάς, διαπρεσβευόμεναι πρὸς ἀμφοτέρους τοὺς βασιλεῖς, εἰς τὸ λαβεῖν ἀναστροφὴν καὶ χρόνον πρὸς τὰς τοῦ πολέμου παρασκευάς. ταύταις τε δὴ κατὰ τὸ συνεχὲς ἐχρημάτιζον ἐν τῇ Μέμφει προκαθήμενοι, παραπλησίως δὲ καὶ τὰς παρὰ τῶν περὶ τὸν Ἀντίοχον ἀπεδέχοντο, φιλανθρώπως ποιούμενοι τὰς ἀπαντήσεις. ἀνεκαλοῦντο δὲ καὶ συνήθροιζον εἰς τὴν Ἀλεξάνδρειαν τοὺς μισθοφόρους τοὺς ἐν ταῖς ἔξω πόλεσιν ὑπ’ αὐτῶν μισθοδοτουμένους. ἐξαπέστελλον δὲ καὶ ξενολόγους καὶ παρεσκεύαζον τοῖς προϋπάρχουσι καὶ τοῖς παραγινομένοις τὰς σιταρχίας. ὡσαύτως δὲ καὶ περὶ τὴν λοιπὴν ἐγίνοντο παρασκευήν, ἀνὰ μέρος καὶ συνεχῶς διατρέχοντες εἰς τὴν Ἀλεξάνδρειαν, ἵνα μηδὲν ἐλλίπῃ τῶν χορηγιῶν πρὸς τὰς προκειμένας ἐπιβολάς. τὴν δὲ περὶ τὰ ὅπλα κατασκευὴν καὶ τὴν τῶν ἀνδρῶν ἐκλογὴν καὶ διαίρεσιν Ἐχεκράτει τῷ Θετταλῷ καὶ Φοξίδᾳ τῷ Μελιταιεῖ παρέδοσαν, ἅμα δὲ τούτοις Εὐρυλόχῳ τῷ Μάγνητι καὶ Σωκράτει τῷ Βοιωτίῳ· σὺν οἷς ἦν καὶ Κνωπίας Ἀλλαριώτης. εὐκαιρότατα γὰρ δὴ τούτων ἐπελάβοντο τῶν ἀνδρῶν, οἵτινες ἔτι Δημητρίῳ καὶ Ἀντιγόνῳ συστρατευόμενοι κατὰ ποσὸν ἔννοιαν εἶχον τῆς ἀληθείας καὶ καθόλου τῆς ἐν τοῖς ὑπαίθροις χρείας. οὗτοι δὲ παραλαβόντες τὸ πλῆθος ἐνδεχομένως ἐχείριζον καὶ στρατιωτικῶς.", "st": "5.63"}, {"sp": "N", "t": "πρῶτον μὲν γὰρ κατὰ γένη καὶ καθ’ ἡλικίαν διελόντες ἀνέδοσαν ἑκάστοις τοὺς ἐπιτηδείους καθοπλισμούς, ὀλιγωρήσαντες τῶν πρότερον αὐτοῖς ὑπαρχόντων· μετὰ δὲ ταῦτα συνέταξαν οἰκείως πρὸς τὴν παροῦσαν χρείαν, λύσαντες τὰ συστήματα καὶ τὰς ἐκ τῶν πρότερον ὀψωνιασμῶν καταγραφάς· ἑξῆς δὲ τούτοις ἐγύμναζον, συνήθεις ἑκάστους ποιοῦντες οὐ μόνον τοῖς παραγγέλμασιν, ἀλλὰ καὶ ταῖς οἰκείαις τῶν καθοπλισμῶν κινήσεσιν. ἐποιοῦντο δὲ καὶ συναγωγὰς ἐπὶ τῶν ὅπλων καὶ παρακλήσεις, ἐν αἷς μεγίστην παρείχοντο χρείαν Ἀνδρόμαχος Ἀσπένδιος καὶ Πολυκράτης Ἀργεῖος, προσφάτως μὲν ἐκ τῆς Ἑλλάδος διαβεβηκότες, συνήθεις δ’ ἀκμὴν ὄντες ταῖς Ἑλληνικαῖς ὁρμαῖς καὶ ταῖς ἑκάστων ἐπινοίαις, πρὸς δὲ τούτοις ἐπιφανεῖς ὑπάρχοντες ταῖς τε πατρίσι καὶ τοῖς βίοις, Πολυκράτης δὲ καὶ μᾶλλον διά τε τὴν τῆς οἰκίας ἀρχαιότητα καὶ διὰ τὴν Μνασιάδου τοῦ πατρὸς δόξαν ἐκ τῆς ἀθλήσεως. οἳ καὶ κατ’ ἰδίαν καὶ κοινῇ παρακαλοῦντες ὁρμὴν καὶ προθυμίαν ἐνειργάσαντο τοῖς ἀνθρώποις πρὸς τὸν μέλλοντα κίνδυνον.", "st": "5.64"}, {"sp": "N", "t": "εἶχον δὲ καὶ τὰς ἡγεμονίας ἕκαστοι τῶν προειρημένων ἀνδρῶν οἰκείας ταῖς ἰδίαις ἐμπειρίαις. Εὐρύλοχος μὲν γὰρ ὁ Μάγνης ἡγεῖτο σχεδὸν ἀνδρῶν τρισχιλίων τοῦ καλουμένου παρὰ τοῖς βασιλεῦσιν ἀγήματος, Σωκράτης δ’ ὁ Βοιώτιος πελταστὰς ὑφ’ αὑτὸν εἶχε δισχιλίους. ὁ δ’ Ἀχαιὸς Φοξίδας καὶ Πτολεμαῖος ὁ Θρασέου, σὺν δὲ τούτοις Ἀνδρόμαχος [ὁ] Ἀσπένδιος, συνεγύμναζον μὲν ἐπὶ ταὐτὸ τὴν φάλαγγα καὶ τοὺς μισθοφόρους Ἕλληνας, ἡγοῦντο δὲ τῆς μὲν φάλαγγος Ἀνδρόμαχος καὶ Πτολεμαῖος, τῶν δὲ μισθοφόρων Φοξίδας, οὔσης τῆς μὲν φάλαγγος εἰς δισμυρίους καὶ πεντακισχιλίους, τῶν δὲ μισθοφόρων εἰς ὀκτακισχιλίους. τοὺς δ’ ἱππεῖς τοὺς μὲν περὶ τὴν αὐλήν, ὄντας εἰς ἑπτακοσίους, Πολυκράτης παρεσκεύαζε καὶ τοὺς ἀπὸ Λιβύης, ἔτι δὲ καὶ τοὺς ἐγχωρίους· καὶ τούτων αὐτὸς ἡγεῖτο πάντων, περὶ τρισχιλίους ὄντων τὸν ἀριθμόν. τούς γε μὴν ἀπὸ τῆς Ἑλλάδος καὶ πᾶν τὸ τῶν μισθοφόρων ἱππέων πλῆθος Ἐχεκράτης ὁ Θετταλὸς διαφερόντως ἀσκήσας, ὄντας εἰς δισχιλίους, μεγίστην ἐπ’ αὐτοῦ τοῦ κινδύνου παρέσχετο χρείαν. οὐδενὸς δ’ ἧττον ἔσπευδε περὶ τοὺς ὑφ’ αὑτὸν ταττομένους Κνωπίας Ἀλλαριώτης, ἔχων τοὺς μὲν πάντας Κρῆτας εἰς τρισχιλίους, αὐτῶν δὲ τούτων χιλίους Νεόκρητας, ἐφ’ ὧν ἐτετάχει Φίλωνα τὸν Κνώσιον. καθώπλισαν δὲ καὶ Λίβυας τρισχιλίους εἰς τὸν Μακεδονικὸν τρόπον, ἐφ’ ὧν ἦν Ἀμμώνιος ὁ Βαρκαῖος. τὸ δὲ τῶν Αἰγυπτίων πλῆθος ἦν μὲν εἰς δισμυρίους φαλαγγίτας, ὑπετάττετο δὲ Σωσιβίῳ. συνήχθη δὲ καὶ Θρᾳκῶν καὶ Γαλατῶν πλῆθος, ἐκ μὲν τῶν κατοίκων καὶ τῶν ἐπιγόνων εἰς τετρακισχιλίους, οἱ δὲ προσφάτως ἐπισυναχθέντες ἦσαν εἰς δισχιλίους, ὧν ἡγεῖτο Διονύσιος ὁ Θρᾷξ. ἡ μὲν οὖν Πτολεμαίῳ παρασκευαζομένη δύναμις τῷ τε πλήθει καὶ ταῖς διαφοραῖς τοσαύτη καὶ τοιαύτη τις ἦν.", "st": "5.65"}, {"sp": "N", "t": "Ἀντίοχος δὲ συνεσταμένος πολιορκίαν περὶ τὴν καλουμένην πόλιν Δῶρα, καὶ περαίνειν οὐδὲν δυνάμενος διά τε τὴν ὀχυρότητα τοῦ τόπου καὶ τὰς τῶν περὶ τὸν Νικόλαον παραβοηθείας, συνάπτοντος ἤδη τοῦ χειμῶνος, συνεχώρησε ταῖς παρὰ τοῦ Πτολεμαίου πρεσβείαις ἀνοχάς τε ποιήσασθαι τετραμήνους καὶ περὶ τῶν ὅλων εἰς πάντα συγκαταβήσεσθαι τὰ φιλάνθρωπα. ταῦτα δ’ ἔπραττε πλεῖστον μὲν ἀπέχων τῆς ἀληθείας, σπεύδων δὲ μὴ πολὺν χρόνον ἀποσπᾶσθαι τῶν οἰκείων τόπων, ἀλλ’ ἐν τῇ Σελευκείᾳ ποιήσασθαι τὴν τῶν δυνάμεων παραχειμασίαν διὰ τὸ προφανῶς τὸν Ἀχαιὸν ἐπιβουλεύειν μὲν τοῖς σφετέροις πράγμασι, συνεργεῖν δὲ τοῖς περὶ τὸν Πτολεμαῖον ὁμολογουμένως. τούτων δὲ συγχωρηθέντων Ἀντίοχος τοὺς μὲν πρεσβευτὰς ἐξέπεμψε, παραγγείλας διασαφεῖν αὐτῷ τὴν ταχίστην τὰ δόξαντα τοῖς περὶ τὸν Πτολεμαῖον καὶ συνάπτειν εἰς Σελεύκειαν· ἀπολιπὼν δὲ φυλακὰς τὰς ἁρμοζούσας ἐν τοῖς τόποις, καὶ παραδοὺς Θεοδότῳ τὴν τῶν ὅλων ἐπιμέλειαν, ἐπανῆλθε· καὶ παραγενόμενος εἰς τὴν Σελεύκειαν διαφῆκε τὰς δυνάμεις εἰς παραχειμασίαν. καὶ τὸ λοιπὸν ἤδη τοῦ μὲν γυμνάζειν τοὺς ὄχλους ὠλιγώρει, πεπεισμένος οὐ προσδεήσεσθαι τὰ πράγματα μάχης διὰ τὸ τινῶν μὲν μερῶν Κοίλης Συρίας καὶ Φοινίκης ἤδη κυριεύειν, τοὺς δὲ λοιποὺς ἐλπίζειν ἐξ ἑκόντων καὶ διὰ λόγου παραλήψεσθαι, μὴ τολμώντων τὸ παράπαν τῶν περὶ τὸν Πτολεμαῖον εἰς τὸν περὶ τῶν ὅλων συγκαταβαίνειν κίνδυνον. ταύτην δὲ συνέβαινε τὴν διάληψιν καὶ τοὺς πρεσβευτὰς ἔχειν διὰ τὸ τὰς ἐντεύξεις αὐτοῖς τὸν Σωσίβιον ἐν τῇ Μέμφει προκαθήμενον φιλανθρώπους ποιεῖσθαι, τῶν δὲ κατὰ τὴν Ἀλεξάνδρειαν παρασκευῶν μηδέποτε τοὺς διαπεμπομένους πρὸς τὸν Ἀντίοχον ἐᾶν αὐτόπτας γενέσθαι.", "st": "5.66"}, {"sp": "N", "t": "πλὴν καὶ τότε τῶν πρέσβεων ἀφικομένων οἱ μὲν περὶ τὸν Σωσίβιον ἕτοιμοι πρὸς πᾶν, ὁ δ’ Ἀντίοχος μεγίστην ἐποιεῖτο σπουδὴν εἰς τὸ καθάπαξ καὶ τοῖς ὅπλοις καὶ τοῖς δικαίοις ἐπὶ τῶν ἐντεύξεων καταπεριεῖναι τῶν ἐκ τῆς Ἀλεξανδρείας. ᾗ καὶ παραγενομένων τῶν πρεσβευτῶν εἰς τὴν Σελεύκειαν, καὶ συγκαταβαινόντων εἰς τοὺς κατὰ μέρος ὑπὲρ τῆς διαλύσεως λόγους κατὰ τὰς ὑπὸ τῶν περὶ τὸν Σωσίβιον ἐντολάς, ὁ μὲν βασιλεὺς τὸ μὲν ἄρτι γεγονὸς ἀτύχημα καὶ προφανὲς ἀδίκημα περὶ τῆς ἐνεστώσης καταλήψεως τῶν περὶ Κοίλην Συρίαν τόπων οὐ δεινὸν ἐνόμιζε κατὰ τὰς δικαιολογίας, τὸ δὲ πλεῖστον οὐδ’ ἐν ἀδικήματι, κατηριθμεῖτο τὴν πρᾶξιν, ὡς καθηκόντων αὐτῷ τινων ἀντιπεποιημένος, τὴν δὲ πρώτην Ἀντιγόνου τοῦ Μονοφθάλμου κατάληψιν καὶ τὴν Σελεύκου δυναστείαν τῶν τόπων τούτων ἐκείνας ἔφη κυριωτάτας εἶναι καὶ δικαιοτάτας κτήσεις, καθ’ ἃς αὐτοῖς, οὐ Πτολεμαίῳ, καθήκειν τὰ κατὰ Κοίλην Συρίαν· καὶ γὰρ Πτολεμαῖον διαπολεμῆσαι πρὸς Ἀντίγονον οὐχ αὑτῷ, Σελεύκῳ δὲ συγκατασκευάζοντα τὴν ἀρχὴν τῶν τόπων τούτων. μάλιστα δὲ τὸ κοινὸν ἐπιέζει πάντων τῶν βασιλέων συγχώρημα, καθ’ οὓς καιροὺς Ἀντίγονον νικήσαντες, καὶ βουλευόμενοι κατὰ προαίρεσιν ὁμόσε πάντες, Κάσσανδρος, Λυσίμαχος, Σέλευκος, ἔκριναν Σελεύκου τὴν ὅλην Συρίαν ὑπάρχειν. οἱ δὲ παρὰ τοῦ Πτολεμαίου τἀναντία τούτων ἐπειρῶντο συνιστάνειν· τό τε γὰρ παρὸν ηὖξον ἀδίκημα καὶ δεινὸν ἐποίουν τὸ γεγονός, εἰς παρασπόνδημα τὴν Θεοδότου προδοσίαν καὶ τὴν ἔφοδον ἀνάγοντες τὴν Ἀντιόχου, προεφέροντο δὲ καὶ τὰς ἐπὶ Πτολεμαίου τοῦ Λάγου κτήσεις, φάσκοντες ἐπὶ τούτῳ συμπολεμῆσαι Σελεύκῳ Πτολεμαῖον, ἐφ’ ᾧ τὴν μὲν ὅλης τῆς Ἀσίας ἀρχὴν Σελεύκῳ περιθεῖναι, τὰ δὲ κατὰ Κοίλην Συρίαν αὑτῷ κατακτήσασθαι καὶ Φοινίκην. ἐλέγετο μὲν οὖν ταῦτα καὶ παραπλήσια τούτοις πλεονάκις ὑπ’ ἀμφοτέρων κατὰ τὰς διαπρεσβείας καὶ τὰς ἐντεύξεις, ἐπετελεῖτο δὲ τὸ παράπαν οὐδέν, ἅτε τῆς δικαιολογίας γινομένης διὰ τῶν κοινῶν φίλων, μεταξὺ δὲ μηδενὸς ὑπάρχοντος τοῦ δυνησομένου παρακατασχεῖν καὶ κωλῦσαι τὴν τοῦ δοκοῦντος ἀδικεῖν ὁρμήν. μάλιστα δὲ παρεῖχε δυσχρηστίαν ἀμφοτέροις τὰ περὶ τὸν Ἀχαιόν· Πτολεμαῖος μὲν γὰρ ἐσπούδαζε περιλαβεῖν ταῖς συνθήκαις αὐτόν, Ἀντίοχος δὲ καθάπαξ οὐδὲ λόγον ἠνείχετο περὶ τούτων, δεινὸν ἡγούμενος τὸ καὶ τολμᾶν τὸν Πτολεμαῖον περιστέλλειν τοὺς ἀποστάτας καὶ μνήμην ποιεῖσθαι περί τινος τῶν τοιούτων.", "st": "5.67"}, {"sp": "N", "t": "διόπερ ἐπεὶ πρεσβεύοντες μὲν ἅλις εἶχον ἀμφότεροι, πέρας δ’ οὐδὲν ἐγίνετο περὶ τὰς συνθήκας, συνῆπτε δὲ τὰ τῆς ἐαρινῆς ὥρας, Ἀντίοχος μὲν συνῆγε τὰς δυνάμεις, ὡς εἰσβαλῶν καὶ κατὰ γῆν καὶ κατὰ θάλατταν καὶ καταστρεψόμενος τὰ καταλειπόμενα μέρη τῶν ἐν Κοίλῃ Συρίᾳ πραγμάτων, οἱ δὲ περὶ τὸν Πτολεμαῖον ὁλοσχερέστερον ἐπιτρέψαντες τῷ Νικολάῳ χορηγίας τε παρεῖχον εἰς τοὺς κατὰ Γάζαν τόπους δαψιλεῖς καὶ δυνάμεις ἐξέπεμπον πεζικὰς καὶ ναυτικάς. ὧν προσγενομένων εὐθαρσῶς ὁ Νικόλαος εἰς τὸν πόλεμον ἐνέβαινε, πρὸς πᾶν τὸ παραγγελλόμενον ἑτοίμως αὐτῷ συνεργοῦντος Περιγένους τοῦ ναυάρχου· τοῦτον γὰρ ἐπὶ τῶν ναυτικῶν δυνάμεων ἐξαπέστειλαν οἱ περὶ τὸν Πτολεμαῖον, ἔχοντα καταφράκτους μὲν ναῦς τριάκοντα, φορτηγοὺς δὲ πλείους τῶν τετρακοσίων. Νικόλαος δὲ τὸ μὲν γένος ὑπῆρχεν Αἰτωλός, τριβὴν δὲ καὶ τόλμαν ἐν τοῖς πολεμικοῖς οὐδενὸς εἶχεν ἐλάττω τῶν παρὰ Πτολεμαίῳ στρατευομένων. προκαταλαβόμενος δὲ μέρει μέν τινι τὰ κατὰ Πλάτανον στενά, τῇ δὲ λοιπῇ δυνάμει, μεθ’ ἧς αὐτὸς ἦν, τὰ περὶ Πορφυρεῶνα πόλιν, ταύτῃ παρεφύλαττε τὴν εἰσβολὴν τοῦ βασιλέως, ὁμοῦ συνορμούσης αὐτῷ καὶ τῆς ναυτικῆς δυνάμεως. Ἀντίοχος δὲ παρελθὼν εἰς Μάραθον, καὶ παραγενομένων πρὸς αὐτὸν Ἀραδίων ὑπὲρ συμμαχίας, οὐ μόνον προσεδέξατο τὴν συμμαχίαν, ἀλλὰ καὶ τὴν διαφορὰν τὴν προϋπάρχουσαν αὐτοῖς πρὸς ἀλλήλους κατέπαυσε, διαλύσας τοὺς ἐν τῇ νήσῳ πρὸς τοὺς τὴν ἤπειρον κατοικοῦντας τῶν Ἀραδίων. μετὰ δὲ ταῦτα ποιησάμενος τὴν εἰσβολὴν κατὰ τὸ καλούμενον Θεοῦ πρόσωπον ἧκε πρὸς Βηρυτόν, Βότρυν μὲν ἐν τῇ παρόδῳ καταλαβόμενος, Τριήρη δὲ καὶ Κάλαμον ἐμπρήσας. ἐντεῦθεν δὲ Νίκαρχον μὲν καὶ Θεόδοτον προαπέστειλε, συντάξας προκαταλαβέσθαι τὰς δυσχωρίας περὶ τὸν Λύκον καλούμενον ποταμόν· αὐτὸς δὲ τὴν δύναμιν ἀναλαβὼν προῆλθε καὶ κατεστρατοπέδευσε περὶ τὸν Δαμούραν ποταμόν, συμπαραπλέοντος ἅμα καὶ Διογνήτου τοῦ ναυάρχου. παραλαβὼν δὲ πάλιν ἐντεῦθεν τούς τε περὶ τὸν Θεόδοτον καὶ Νίκαρχον τοὺς ἐκ τῆς δυνάμεως εὐζώνους, ὥρμησε κατασκεψόμενος τὰς προκατεχομένας ὑπὸ τῶν περὶ τὸν Νικόλαον δυσχωρίας. συνθεωρήσας δὲ τὰς τῶν τόπων ἰδιότητας, τότε μὲν ἀνεχώρησε πρὸς τὴν παρεμβολήν, κατὰ δὲ τὴν ἐπιοῦσαν ἡμέραν, καταλιπὼν αὐτοῦ τὰ βαρέα τῶν ὅπλων καὶ Νίκαρχον ἐπὶ τούτων, προῆγε μετὰ τῆς λοιπῆς δυνάμεως ἐπὶ τὴν προκειμένην χρείαν.", "st": "5.68"}, {"sp": "N", "t": "τῆς δὲ κατὰ τὸν Λίβανον παρωρείας κατὰ τοὺς τόπους τούτους συγκλειούσης τὴν παραλίαν εἰς στενὸν καὶ βραχὺν τόπον, συμβαίνει καὶ τοῦτον αὐτὸν ῥάχει δυσβάτῳ καὶ τραχείᾳ διεζῶσθαι, στενὴν δὲ καὶ δυσχερῆ παρ’ αὐτὴν τὴν θάλατταν ἀπολειπούσῃ πάροδον. ἐφ’ ᾗ τότε Νικόλαος παρεμβεβληκώς, καὶ τοὺς μὲν τῷ τῶν ἀνδρῶν πλήθει προκατειληφὼς τόπους, τοὺς δὲ ταῖς χειροποιήτοις κατασκευαῖς διησφαλισμένος, ῥᾳδίως ἐπέπειστο κωλύσειν τῆς εἰσόδου τὸν Ἀντίοχον. ὁ δὲ βασιλεὺς διελὼν εἰς τρία μέρη τὴν δύναμιν τὸ μὲν ἓν Θεοδότῳ παρέδωκε, προστάξας συμπλέκεσθαι καὶ βιάζεσθαι παρ’ αὐτὴν τὴν παρώρειαν τοῦ Λιβάνου, τὸ δ’ ἕτερον Μενεδήμῳ, διὰ πλειόνων ἐντειλάμενος κατὰ μέσην πειράζειν τὴν ῥάχιν· τὸ δὲ τρίτον πρὸς θάλατταν ἀπένειμε, Διοκλέα τὸν στρατηγὸν τῆς Παραποταμίας ἡγεμόνα συστήσας. αὐτὸς δὲ μετὰ τῆς θεραπείας εἶχε τὸν μέσον τόπον, πάντα βουλόμενος ἐποπτεύειν καὶ παντὶ τῷ δεομένῳ παραβοηθεῖν. ἅμα δὲ τούτοις ἐξηρτυμένοι παρενέβαλον εἰς ναυμαχίαν οἱ περὶ τὸν Διόγνητον καὶ Περιγένην, συνάπτοντες κατὰ τὸ δυνατὸν τῇ γῇ καὶ πειρώμενοι ποιεῖν ὡς ἂν εἰ μίαν ἐπιφάνειαν τῆς πεζομαχίας καὶ ναυμαχίας. πάντων δὲ ποιησαμένων ἀφ’ ἑνὸς σημείου καὶ παραγγέλματος ἑνὸς τὰς προσβολάς, ἡ μὲν ναυμαχία πάρισον εἶχε τὸν κίνδυνον διὰ τὸ καὶ τῷ πλήθει καὶ ταῖς παρασκευαῖς παραπλήσιον εἶναι τὸ παρ’ ἀμφοῖν ναυτικόν, τῶν δὲ πεζῶν τὸ μὲν πρῶτον ἐπεκράτουν οἱ τοῦ Νικολάου, συγχρώμενοι ταῖς τῶν τόπων ὀχυρότησι, ταχὺ δὲ τῶν περὶ τὸν Θεόδοτον ἐκβιασαμένων τοὺς ἐπὶ τῇ παρωρείᾳ, κἄπειτα ποιουμένων ἐξ ὑπερδεξίου τὴν ἔφοδον, τραπέντες οἱ περὶ τὸν Νικόλαον ἔφευγον προτροπάδην ἅπαντες. κατὰ δὲ τὴν φυγὴν ἔπεσον μὲν αὐτῶν εἰς δισχιλίους, ζωγρίᾳ δ’ ἑάλωσαν οὐκ ἐλάττους τούτων· οἱ δὲ λοιποὶ πάντες ἀπεχώρησαν ἐπὶ Σιδῶνος. ὁ δὲ Περιγένης, ἐπικυδέστερος ὢν ταῖς ἐλπίσι κατὰ τὴν ναυμαχίαν, συνθεωρήσας τὸ κατὰ τοὺς πεζοὺς ἐλάττωμα καὶ διατραπείς, ἀσφαλῶς ἐποιήσατο τὴν ἀποχώρησιν εἰς τοὺς αὐτοὺς τόπους.", "st": "5.69"}, {"sp": "N", "t": "Ἀντίοχος δὲ τὴν δύναμιν ἀναλαβὼν ἧκε καὶ κατεστρατοπέδευσε πρὸς τῇ Σιδῶνι. τὸ μὲν οὖν καταπειράζειν τῆς πόλεως ἀπέγνω διὰ τὴν προϋπάρχουσαν αὐτόθι δαψίλειαν τῆς χορηγίας καὶ τὸ πλῆθος τῶν ἐνοικούντων καὶ συμπεφευγότων ἀνδρῶν· ἀναλαβὼν δὲ τὴν δύναμιν αὐτὸς μὲν ἐποιεῖτο τὴν πορείαν ὡς ἐπὶ Φιλοτερίας, Διογνήτῳ δὲ συνέταξε τῷ ναυάρχῳ πάλιν ἔχοντι τὰς ναῦς ἀποπλεῖν εἰς Τύρον. ἡ δὲ Φιλοτερία κεῖται παρ’ αὐτὴν τὴν λίμνην, εἰς ἣν ὁ καλούμενος Ἰορδάνης ποταμὸς εἰσβάλλων ἐξίησι πάλιν εἰς τὰ πεδία τὰ περὶ τὴν Σκυθῶν πόλιν προσαγορευομένην. γενόμενος δὲ καθ’ ὁμολογίαν ἐγκρατὴς ἀμφοτέρων τῶν προειρημένων πόλεων, εὐθαρσῶς ἔσχε πρὸς τὰς μελλούσας ἐπιβολὰς διὰ τὸ τὴν ὑποτεταγμένην χώραν ταῖς πόλεσι ταύταις ῥᾳδίως δύνασθαι παντὶ τῷ στρατοπέδῳ χορηγεῖν καὶ δαψιλῆ παρασκευάζειν τὰ κατεπείγοντα πρὸς τὴν χρείαν. ἀσφαλισάμενος δὲ φρουραῖς ταύτας ὑπερέβαλε τὴν ὀρεινὴν καὶ παρῆν ἐπ’ Ἀταβύριον, ὃ κεῖται μὲν ἐπὶ λόφου μαστοειδοῦς, τὴν δὲ πρόσβασιν ἔχει πλεῖον ἢ πεντεκαίδεκα σταδίων. χρησάμενος δὲ κατὰ τὸν καιρὸν τοῦτον ἐνέδρᾳ καὶ στρατηγήματι κατέσχε τὴν πόλιν· προκαλεσάμενος γὰρ εἰς ἀκροβολισμὸν τοὺς ἀπὸ τῆς πόλεως καὶ συγκαταβιβάσας ἐπὶ πολὺ τοὺς προκινδυνεύοντας, κἄπειτα πάλιν ἐκ μεταβολῆς τῶν φευγόντων καὶ διαναστάσεως τῶν ἐγκαθημένων συμβαλών, πολλοὺς μὲν αὐτῶν ἀπέκτεινε, τέλος δ’ ἐπακολουθήσας καὶ προκαταπληξάμενος ἐξ ἐφόδου παρέλαβε καὶ ταύτην τὴν πόλιν. κατὰ δὲ τὸν καιρὸν τοῦτον Κεραίας, εἷς τῶν· ὑπὸ Πτολεμαῖον ταττομένων ὑπάρχων, ἀπέστη πρὸς αὐτόν· ᾧ χρησάμενος μεγαλοπρεπῶς πολλοὺς ἐμετεώρισε τῶν παρὰ τοῖς ἐναντίοις ἡγεμόνων· Ἱππόλοχος γοῦν ὁ Θετταλὸς οὐ μετὰ πολὺ τετρακοσίους ἱππεῖς ἧκεν ἔχων πρὸς αὐτὸν τῶν ὑπὸ Πτολεμαῖον ταττομένων. ἀσφαλισάμενος δὲ καὶ τὸ Ἀταβύριον ἀνέζευξε, καὶ προάγων παρέλαβε Πέλλαν καὶ Καμοῦν καὶ Γεφροῦν.", "st": "5.70"}, {"sp": "N", "t": "τοιαύτης δὲ γενομένης τῆς εὐροίας, οἱ τὴν παρακειμένην Ἀραβίαν κατοικοῦντες, παρακαλέσαντες σφᾶς αὐτούς, ὁμοθυμαδὸν αὐτῷ προσέθεντο πάντες. προσλαβὼν δὲ καὶ τὴν παρὰ τούτων ἐλπίδα καὶ χορηγίαν προῆγε, καὶ κατασχὼν εἰς τὴν Γαλᾶτιν γίνεται Ἀβίλων καὶ τῶν εἰς αὐτὰ παραβεβοηθηκότων, ὧν ἡγεῖτο Νικίας, ἀναγκαῖος ὢν καὶ συγγενὴς Μεννέου. καταλειπομένων δ’ ἔτι τῶν Γαδάρων, ἃ δοκεῖ τῶν κατ’ ἐκείνους τοὺς τόπους ὀχυρότητι διαφέρειν, προσστρατοπεδεύσας αὐτοῖς καὶ συστησάμενος ἔργα ταχέως κατεπλήξατο καὶ παρέλαβε τὴν πόλιν. μετὰ δὲ ταῦτα πυνθανόμενος εἰς τὰ Ῥαββατάμανα τῆς Ἀραβίας καὶ πλείους ἡθροισμένους τῶν πολεμίων πορθεῖν καὶ κατατρέχειν τὴν τῶν προσκεχωρηκότων Ἀράβων αὐτῷ χώραν, πάντ’ ἐν ἐλάττονι θέμενος ὥρμησε καὶ προσεστρατοπέδευσε τοῖς βουνοῖς, ἐφ’ ὧν κεῖσθαι συμβαίνει τὴν πόλιν. περιελθὼν δὲ καὶ συνθεασάμενος τὸν λόφον κατὰ δύο τόπους μόνον ἔχοντα πρόσοδον, ταύτῃ προσέβαινε καὶ κατὰ τούτους συνίστατο τοὺς τόπους τὰς τῶν μηχανημάτων κατασκευάς. ἀποδοὺς δὲ τὴν ἐπιμέλειαν τῶν ἔργων τῶν μὲν Νικάρχῳ, τῶν δὲ Θεοδότῳ, τὸ λοιπὸν αὐτὸς ἤδη κοινὸν αὑτὸν παρεσκεύαζε κατὰ τὴν ἐπιμέλειαν καὶ τὴν ἐπίσκεψιν τῆς ἑκατέρου περὶ ταῦτα φιλοτιμίας. πολλὴν δὲ ποιουμένων σπουδὴν τῶν περὶ τὸν Θεόδοτον καὶ Νίκαρχον, καὶ συνεχῶς ἁμιλλωμένων πρὸς ἀλλήλους περὶ τοῦ πότερος αὐτῶν φθάσει καταβαλὼν τὸ προκείμενον τῶν ἔργων τεῖχος, ταχέως συνέβη καὶ παρὰ τὴν προσδοκίαν ἑκάτερον πεσεῖν τὸ μέρος. οὗ συμβάντος ἐποιοῦντο καὶ νύκτωρ μὲν καὶ μεθ’ ἡμέραν προσβολὰς καὶ πᾶσαν προσέφερον βίαν, οὐδένα παραλείποντες καιρόν. συνεχῶς δὲ καταπειράζοντες τῆς πόλεως οὐ μὴν ἤνυον τῆς ἐπιβολῆς οὐδὲν διὰ τὸ πλῆθος τῶν εἰς τὴν πόλιν συνδεδραμηκότων ἀνδρῶν, ἕως οὗ τῶν αἰχμαλώτων τινὸς ὑποδείξαντος τὸν ὑπόνομον, δι’ οὗ κατέβαινον ἐπὶ τὴν ὑδρείαν οἱ πολιορκούμενοι, τοῦτον ἀναρρήξαντες ἐνέφραξαν ὕλῃ καὶ λίθοις καὶ παντὶ τῷ τοιούτῳ γένει. τότε δὲ συνείξαντες οἱ κατὰ τὴν πόλιν διὰ τὴν ἀνυδρίαν παρέδοσαν αὑτούς. οὗ γενομένου κυριεύσας τῶν Ῥαββαταμάνων ἐπὶ μὲν τούτων ἀπέλιπε Νίκαρχον μετὰ φυλακῆς τῆς ἁρμοζούσης· Ἱππόλοχον δὲ καὶ Κεραίαν τοὺς ἀποστάντας μετὰ πεζῶν πεντακισχιλίων ἐξαποστείλας ἐπὶ τοὺς κατὰ Σαμάρειαν τόπους, καὶ συντάξας προκαθῆσθαι καὶ πᾶσι τὴν ἀσφάλειαν προκατασκευάζειν τοῖς ὑπ’ αὐτὸν ταττομένοις, ἀνέζευξε μετὰ τῆς δυνάμεως ὡς ἐπὶ Πτολεμαΐδος, ἐκεῖ ποιεῖσθαι διεγνωκὼς τὴν παραχειμασίαν.", "st": "5.71"}, {"sp": "N", "t": "κατὰ δὲ τὴν αὐτὴν θερείαν Πεδνηλισσεῖς, πολιορκούμενοι καὶ κινδυνεύοντες ὑπὸ Σελγέων, διεπέμψαντο περὶ βοηθείας πρὸς Ἀχαιόν. τοῦ δ’ ἀσμένως ὑπακούσαντος, οὗτοι μὲν εὐθαρσῶς ὑπέμενον τὴν πολιορκίαν, προσανέχοντες ταῖς ἐλπίσι τῆς βοηθείας, ὁ δ’ Ἀχαιός, προχειρισάμενος Γαρσύηριν μετὰ πεζῶν ἑξακισχιλίων, ἱππέων δὲ πεντακοσίων, ἐξαπέστειλε σπουδῇ παραβοηθήσοντα τοῖς Πεδνηλισσεῦσιν. οἱ δὲ Σελγεῖς, συνέντες τὴν παρουσίαν τῆς βοηθείας, προκατελάβοντο τὰ στενὰ τὰ περὶ τὴν καλουμένην Κλίμακα τῷ πλείονι μέρει τῆς ἑαυτῶν δυνάμεως, καὶ τὴν μὲν εἰσβολὴν τὴν ἐπὶ Σάπορδα κατεῖχον, τὰς δὲ διόδους καὶ προσβάσεις πάσας ἔφθειρον. ὁ δὲ Γαρσύηρις, ἐμβαλὼν εἰς τὴν Μιλυάδα καὶ καταστρατοπεδεύσας περὶ τὴν καλουμένην Κρητῶν πόλιν, ἐπεὶ συνῄσθετο προκατεχομένων τῶν τόπων ἀδύνατον οὖσαν τὴν εἰς τοὔμπροσθεν πορείαν, ἐπινοεῖ τινα δόλον τοιοῦτον. ἀναζεύξας ἦγε πάλιν εἰς τοὐπίσω τὴν πορείαν, ὡς ἀπεγνωκὼς τὴν βοήθειαν διὰ τὸ προκατέχεσθαι τοὺς τόπους. οἱ δὲ Σελγεῖς προχείρως πιστεύσαντες, ὡς ἀπεγνωκότος βοηθεῖν Γαρσυήριδος, οἱ μὲν εἰς τὸ στρατόπεδον ἀπεχώρησαν, οἱ δ’ εἰς τὴν πόλιν διὰ τὸ κατεπείγειν τὴν τοῦ σίτου κομιδήν. ὁ δὲ Γαρσύηρις, ἐξ ἐπιστροφῆς ἐνεργὸν ποιησάμενος τὴν πορείαν, ἧκε πρὸς τὰς ὑπερβολάς. καταλαβὼν δ’ ἐρήμους, ταύτας μὲν ἠσφαλίσατο φυλακαῖς, Φάϋλλον ἐπὶ πάντων ἐπιστήσας, αὐτὸς δὲ μετὰ τῆς στρατιᾶς εἰς Πέργην κατάρας ἐντεῦθεν ἐποιεῖτο τὰς διαπρεσβείας πρός τε τοὺς ἄλλους τοὺς τὴν Πισιδικὴν κατοικοῦντας καὶ πρὸς τὴν Παμφυλίαν, ὑποδεικνύων μὲν τὸ τῶν Σελγέων βάρος, παρακαλῶν δὲ πάντας πρὸς τὴν Ἀχαιοῦ συμμαχίαν καὶ πρὸς τὴν βοήθειαν τοῖς Πεδνηλισσεῦσιν.", "st": "5.72"}, {"sp": "N", "t": "οἱ δὲ Σελγεῖς κατὰ τὸν καιρὸν τοῦτον, στρατηγὸν ἐξαποστείλαντες μετὰ δυνάμεως, ἤλπισαν καταπληξάμενοι ταῖς τῶν τόπων ἐμπειρίαις ἐκβαλεῖν τὸν Φάϋλλον ἐκ τῶν ὀχυρωμάτων. οὐ καθικόμενοι δὲ τῆς προθέσεως, ἀλλὰ πολλοὺς ἀποβαλόντες τῶν στρατιωτῶν ἐν ταῖς προσβολαῖς, ταύτης μὲν τῆς ἐλπίδος ἀπέστησαν, τῇ δὲ πολιορκίᾳ καὶ τοῖς ἔργοις οὐχ ἧττον, ἀλλὰ μᾶλλον ἢ πρὸ τοῦ προσεκαρτέρουν. τοῖς δὲ περὶ Γαρσύηριν Ἐτεννεῖς μὲν οἱ τῆς Πισιδικῆς τὴν ὑπὲρ Σίδης ὀρεινὴν κατοικοῦντες, ὀκτακισχιλίους ὁπλίτας ἔπεμψαν, Ἀσπένδιοι δὲ τοὺς ἡμίσεις· Σιδῆται δὲ τὰ μὲν στοχαζόμενοι τῆς πρὸς Ἀντίοχον εὐνοίας, τὸ δὲ πλεῖον διὰ τὸ πρὸς Ἀσπενδίους μῖσος, οὐ μετέσχον τῆς βοηθείας. ὁ δὲ Γαρσύηρις ἀναλαβὼν τάς τε τῶν βεβοηθηκότων καὶ τὰς ἰδίας δυνάμεις ἧκε πρὸς τὴν Πεδνηλισσόν, πεπεισμένος ἐξ ἐφόδου λύσειν τὴν πολιορκίαν· οὐ καταπληττομένων δὲ τῶν Σελγέων, λαβὼν σύμμετρον ἀπόστημα κατεστρατοπέδευσε. τῶν δὲ Πεδνηλισσέων πιεζομένων ὑπὸ τῆς ἐνδείας, ὁ Γαρσύηρις σπεύδων ποιεῖν τὰ δυνατά, δισχιλίους ἑτοιμάσας ἄνδρας καὶ δοὺς ἑκάστῳ μέδιμνον πυρῶν, νυκτὸς εἰς τὴν Πεδνηλισσὸν εἰσέπεμπε. τῶν δὲ Σελγέων συνέντων τὸ γινόμενον καὶ παραβοηθησάντων, συνέβη τῶν μὲν ἀνδρῶν τῶν εἰσφερόντων κατακοπῆναι τοὺς πλείστους, τοῦ δὲ σίτου παντὸς κυριεῦσαι τοὺς Σελγεῖς. οἷς ἐπαρθέντες ἐνεχείρησαν οὐ μόνον τὴν πόλιν, ἀλλὰ καὶ τοὺς περὶ τὸν Γαρσύηριν πολιορκεῖν· ἔχουσι γὰρ δή τι τολμηρὸν ἀεὶ καὶ παράβολον ἐν τοῖς πολεμίοις οἱ Σελγεῖς. δι’ ἃ καὶ τότε καταλιπόντες φυλακὴν τὴν ἀναγκαίαν τοῦ χάρακος, τοῖς λοιποῖς περιστάντες κατὰ πλείους τόπους ἅμα προσέβαλον εὐθαρσῶς τῇ τῶν ὑπεναντίων παρεμβολῇ. πανταχόθεν δὲ τοῦ κινδύνου παραδόξως περιεστῶτος, κατὰ δέ τινας τόπους καὶ τοῦ χάρακος ἤδη διασπωμένου, θεωρῶν ὁ Γαρσύηρις τὸ συμβαῖνον καὶ μοχθηρὰς ἐλπίδας ἔχων ὑπὲρ τῶν ὅλων, ἐξέπεμψε τοὺς ἱππεῖς κατά τινα τόπον ἀφυλακτούμενον· οὓς νομίσαντες οἱ Σελγεῖς καταπεπληγμένους καὶ δεδιότας τὸ μέλλον ἀποχωρήσειν οὐ προσέσχον, ἀλλ’ ἁπλῶς ὠλιγώρησαν. οἱ δὲ περιιππεύσαντες καὶ γενόμενοι κατὰ νώτου τοῖς πολεμίοις ἐνέβαλον, καὶ προσέφερον τὰς χεῖρας ἐρρωμένως. οὗ συμβαίνοντος ἀναθαρρήσαντες οἱ τοῦ Γαρσυήριδος πεζοί, καίπερ ἤδη τετραμμένοι, πάλιν ἐκ μεταβολῆς ἠμύνοντο τοὺς εἰσπίπτοντας· ἐξ οὗ περιεχόμενοι πανταχόθεν οἱ Σελγεῖς τέλος εἰς φυγὴν ὥρμησαν. ἅμα δὲ τούτοις οἱ Πεδνηλισσεῖς ἐπιθέμενοι τοὺς ἐν τῷ χάρακι καταλειφθέντας ἐξέβαλον. γενομένης δὲ τῆς φυγῆς ἐπὶ πολὺν τόπον, ἔπεσον μὲν οὐκ ἐλάττους μυρίων, τῶν δὲ λοιπῶν οἱ μὲν σύμμαχοι πάντες εἰς τὴν οἰκείαν, οἱ δὲ Σελγεῖς διὰ τῆς ὀρεινῆς εἰς τὴν αὑτῶν πατρίδα κατέφυγον.", "st": "5.73"}, {"sp": "N", "t": "ὁ δὲ Γαρσύηρις ἀναζεύξας ἐκ ποδὸς εἵπετο τοῖς φεύγουσι, σπεύδων διελθεῖν τὰς δυσχωρίας καὶ συνεγγίσαι τῇ πόλει πρὶν ἢ στῆναι καὶ βουλεύσασθαί τι τοὺς πεφευγότας ὑπὲρ τῆς αὑτοῦ παρουσίας. οὗτος μὲν οὖν ἧκε μετὰ τῆς δυνάμεως πρὸς τὴν πόλιν· οἱ δὲ Σελγεῖς δυσελπιστοῦντες μὲν ἐπὶ τοῖς συμμάχοις διὰ τὴν κοινὴν περιπέτειαν, ἐκπεπληγμένοι δὲ ταῖς ψυχαῖς διὰ τὸ γεγονὸς ἀτύχημα, περίφοβοι τελέως ἦσαν καὶ περὶ σφῶν αὐτῶν καὶ περὶ τῆς πατρίδος. διὸ συνελθόντες εἰς ἐκκλησίαν ἐβουλεύσαντο πρεσβευτὴν ἐκπέμπειν ἕνα τῶν πολιτῶν Λόγβασιν, ὃς ἐγεγόνει μὲν ἐπὶ πολὺ συνήθης καὶ ξένος Ἀντιόχου τοῦ μεταλλάξαντος τὸν βίον ἐπὶ Θρᾴκης, δοθείσης δ’ ἐν παρακαταθήκῃ καὶ Λαοδίκης αὐτῷ τῆς Ἀχαιοῦ γενομένης γυναικός, ἐτετρόφει ταύτην ὡς θυγατέρα καὶ διαφερόντως ἐπεφιλοστοργήκει τὴν παρθένον. δι’ ἃ νομίζοντες οἱ Σελγεῖς εὐφυέστατον ἔχειν πρεσβευτὴν πρὸς τὰ περιεστῶτα τοῦτον ἐξαπέστειλαν· ὃς ποιησάμενος ἰδίᾳ τὴν ἔντευξιν πρὸς Γαρσύηριν, τοσοῦτο κατὰ τὴν προαίρεσιν ἀπέσχε τοῦ βοηθεῖν τῇ πατρίδι κατὰ τὸ δέον ὥστε τἀναντία παρεκάλει τὸν Γαρσύηριν σπουδῇ πέμπειν ἐπὶ τὸν Ἀχαιόν, ἀναδεχόμενος ἐγχειριεῖν αὐτοῖς τὴν πόλιν. ὁ μὲν οὖν Γαρσύηρις, δεξάμενος ἑτοίμως τὴν ἐλπίδα, πρὸς μὲν τὸν Ἀχαιὸν ἐξέπεμψε τοὺς ἐπισπασομένους καὶ διασαφήσοντας περὶ τῶν ἐνεστώτων, πρὸς δὲ τοὺς Σελγεῖς ἀνοχὰς ποιησάμενος εἷλκε τὸν χρόνον τῶν συνθηκῶν, αἰὲν ὑπὲρ τῶν κατὰ μέρος ἀντιλογίας καὶ σκήψεις εἰσφερόμενος χάριν τοῦ προσδέξασθαι μὲν τὸν Ἀχαιόν, δοῦναι δ’ ἀναστροφὴν τῷ Λογβάσει πρὸς τὰς ἐντεύξεις καὶ παρασκευὰς τῆς ἐπιβολῆς.", "st": "5.74"}, {"sp": "N", "t": "κατὰ δὲ τὸν καιρὸν τοῦτον πλεονάκις συμπορευομένων πρὸς ἀλλήλους εἰς σύλλογον, ἐγίνετό τις συνήθεια τῶν ἐκ τοῦ στρατοπέδου, παρεισιόντων πρὸς τὰς σιταρχίας εἰς τὴν πόλιν. ὃ δὴ καὶ πολλοῖς καὶ πολλάκις ἤδη παραίτιον γέγονε τῆς ἀπωλείας. καί μοι δοκεῖ πάντων τῶν ζῴων εὐπαραλογιστότατον ὑπάρχειν ἄνθρωπος, δοκοῦν εἶναι πανουργότατον. πόσαι μὲν γὰρ παρεμβολαὶ καὶ φρούρια, πόσαι δὲ καὶ πηλίκαι πόλεις τούτῳ τῷ τρόπῳ παρεσπόνδηνται; καὶ τούτων οὕτω συνεχῶς καὶ προφανῶς πολλοῖς ἤδη συμβεβηκότων οὐκ οἶδ’ ὅπως καινοί τινες αἰεὶ καὶ νέοι πρὸς τὰς τοιαύτας ἀπάτας πεφύκαμεν. τούτου δ’ αἴτιόν ἐστιν ὅτι τὰς τῶν πρότερον ἐπταικότων ἐν ἑκάστοις περιπετείας οὐ ποιούμεθα προχείρους, ἀλλὰ σίτου μὲν καὶ χρημάτων πλῆθος, ἔτι δὲ τειχῶν καὶ βελῶν κατασκευάς, μετὰ πολλῆς ταλαιπωρίας καὶ δαπάνης ἑτοιμαζόμεθα πρὸς τὰ παράδοξα τῶν συμβαινόντων, ὃ δ’ ἐστὶ ῥᾷστον μὲν τῶν ὄντων, μεγίστας δὲ παρέχεται χρείας ἐν τοῖς ἐπισφαλέσι καιροῖς, τούτου πάντες κατολιγωροῦμεν, καὶ ταῦτα δυνάμενοι μετ’ εὐσχήμονος ἀναπαύσεως ἅμα καὶ διαγωγῆς ἐκ τῆς ἱστορίας καὶ πολυπραγμοσύνης περιποιεῖσθαι τὴν τοιαύτην ἐμπειρίαν. πλὴν ὁ μὲν Ἀχαιὸς ἧκε πρὸς τὸν καιρόν, οἱ δὲ Σελγεῖς συμμίξαντες αὐτῷ μεγάλας ἔσχον ἐλπίδας ὡς ὁλοσχεροῦς τινος τευξόμενοι φιλανθρωπίας. ὁ δὲ Λόγβασις ἐν τούτῳ τῷ καιρῷ κατὰ βραχὺ συνηθροικὼς εἰς τὴν ἰδίαν οἰκίαν τῶν ἐκ τοῦ στρατοπέδου παρεισιόντων στρατιωτῶν, συνεβούλευε τοῖς πολίταις μὴ παρεῖναι τὸν καιρόν, ἀλλὰ πράττειν βλέποντας εἰς τὴν ὑποδεικνυμένην φιλανθρωπίαν ὑπ’ Ἀχαιοῦ, καὶ τέλος ἐπιθεῖναι ταῖς συνθήκαις πανδημεὶ βουλευσαμένους ὑπὲρ τῶν ἐνεστώτων. ταχὺ δὲ συναθροισθείσης τῆς ἐκκλησίας, οὗτοι μὲν ἐβουλεύοντο, καλέσαντες καὶ τοὺς ἀπὸ τῶν φυλακείων ἅπαντας, ὡς τέλος ἐπιθήσοντας τοῖς προκειμένοις·", "st": "5.75"}, {"sp": "N", "t": "ὁ δὲ Λόγβασις ἀποδοὺς τὸ σύνθημα τοῦ καιροῦ τοῖς ὑπεναντίοις ἡτοίμαζε τοὺς ἡθροισμένους κατὰ τὴν οἰκίαν, διεσκευάζετο δὲ καὶ καθωπλίζετο μετὰ τῶν υἱῶν αὐτὸς ἅμα πρὸς τὸν κίνδυνον. τῶν δὲ πολεμίων ὁ μὲν Ἀχαιὸς τοὺς [μὲν] ἡμίσεις ἔχων προέβαινε πρὸς αὐτὴν τὴν πόλιν, ὁ δὲ Γαρσύηρις τοὺς ὑπολειπομένους ἀναλαβὼν προῆγεν ὡς ἐπὶ τὸ Κεσβέδιον καλούμενον. τοῦτο δ’ ἐστὶ μὲν Διὸς ἱερόν, κεῖται δ’ εὐφυῶς κατὰ τῆς πόλεως· ἄκρας γὰρ λαμβάνει διάθεσιν. συνθεασαμένου δέ τινος κατὰ τύχην αἰπόλου τὸ συμβαῖνον καὶ προσαγγείλαντος πρὸς τὴν ἐκκλησίαν, οἱ μὲν ἐπὶ τὸ Κεσβέδιον ὥρμων μετὰ σπουδῆς, οἱ δ’ ἐπὶ τὰ φυλακεῖα, τὸ δὲ πλῆθος ὑπὸ τὸν θυμὸν ἐπὶ τὴν οἰκίαν τοῦ Λογβάσιος. καταφανοῦς δὲ τῆς πράξεως γενομένης, οἱ μὲν αὐτῶν ἐπὶ τὸ τέγος ἀναβάντες, οἱ δὲ ταῖς αὐλείοις βιασάμενοι, τόν τε Λόγβασιν καὶ τοὺς υἱούς, ἅμα δὲ καὶ τοὺς ἄλλους πάντας αὐτοῦ κατεφόνευσαν. μετὰ δὲ ταῦτα κηρύξαντες τοῖς δούλοις ἐλευθερίαν καὶ διελόντες σφᾶς αὐτοὺς ἐβοήθουν ἐπὶ τοὺς εὐκαίρους τῶν τόπων. ὁ μὲν οὖν Γαρσύηρις ἰδὼν προκατεχόμενον τὸ Κεσβέδιον ἀπέστη τῆς προθέσεως· τοῦ δ’ Ἀχαιοῦ βιαζομένου πρὸς αὐτὰς τὰς πύλας ἐξελθόντες οἱ Σελγεῖς ἑπτακοσίους μὲν κατέβαλον τῶν Μυσῶν, τοὺς δὲ λοιποὺς ἀπέστησαν τῆς ὁρμῆς. μετὰ δὲ ταύτην τὴν πρᾶξιν ὁ μὲν Ἀχαιὸς καὶ Γαρσύηρις ἀνεχώρησαν εἰς τὴν αὑτῶν παρεμβολήν, οἱ δὲ Σελγεῖς, δεδιότες μὲν τὰς ἐν αὑτοῖς στάσεις, δεδιότες δὲ καὶ τὴν τῶν πολεμίων ἐπιστρατοπεδείαν, ἐξέπεμψαν μεθ’ ἱκετηριῶν τοὺς πρεσβυτέρους, καὶ σπονδὰς ποιησάμενοι διελύσαντο τὸν πόλεμον ἐπὶ τούτοις, ἐφ’ ᾧ παραχρῆμα μὲν δοῦναι τετρακόσια τάλαντα καὶ τοὺς τῶν Πεδνηλισσέων αἰχμαλώτους, μετὰ δέ τινα χρόνον ἕτερα προσθεῖναι τριακόσια. Σελγεῖς μὲν οὖν διὰ τὴν Λογβάσιος ἀσέβειαν τῇ πατρίδι κινδυνεύσαντες, διὰ τὴν σφετέραν εὐτολμίαν τήν τε πατρίδα διετήρησαν καὶ τὴν ἐλευθερίαν οὐ κατῄσχυναν καὶ τὴν ὑπάρχουσαν αὐτοῖς πρὸς Λακεδαιμονίους συγγένειαν·", "st": "5.76"}, {"sp": "N", "t": "Ἀχαιὸς δὲ ποιησάμενος ὑφ’ ἑαυτὸν τὴν Μιλυάδα καὶ τὰ πλεῖστα μέρη τῆς Παμφυλίας ἀνέζευξε, καὶ παραγενόμενος εἰς Σάρδεις ἐπολέμει μὲν Ἀττάλῳ συνεχῶς, ἀνετείνετο δὲ Προυσίᾳ, πᾶσι δ’ ἦν φοβερὸς καὶ βαρὺς τοῖς ἐπὶ τάδε τοῦ Ταύρου κατοικοῦσι. κατὰ δὲ τὸν καιρόν, καθ’ ὃν Ἀχαιὸς ἐποιεῖτο τὴν ἐπὶ τοὺς Σελγεῖς στρατείαν, Ἄτταλος ἔχων τοὺς Αἰγοσάγας Γαλάτας ἐπεπορεύετο τὰς κατὰ τὴν Αἰολίδα πόλεις καὶ τὰς συνεχεῖς ταύταις, ὅσαι πρότερον Ἀχαιῷ προσεκεχωρήκεισαν διὰ τὸν φόβον· ὧν αἱ μὲν πλείους ἐθελοντὴν αὐτῷ προσέθεντο καὶ μετὰ χάριτος, ὀλίγαι δέ τινες τῆς βίας προσεδεήθησαν. ἦσαν δ’ αἱ τότε μεταθέμεναι πρὸς αὐτὸν πρῶτον μὲν Κύμη καὶ Σμύρνα καὶ Φώκαια· μετὰ δὲ ταύτας Αἰγαιεῖς καὶ Τημνῖται προσεχώρησαν, καταπλαγέντες τὴν ἔφοδον· ἧκον δὲ καὶ παρὰ Τηίων καὶ Κολοφωνίων πρέσβεις ἐγχειρίζοντες σφᾶς αὐτοὺς καὶ τὰς πόλεις. προσδεξάμενος δὲ καὶ τούτους ἐπὶ ταῖς συνθήκαις αἷς καὶ τὸ πρότερον, καὶ λαβὼν ὁμήρους, ἐχρημάτισε τοῖς παρὰ τῶν Σμυρναίων πρεσβευταῖς φιλανθρώπως διὰ τὸ μάλιστα τούτους τετηρηκέναι τὴν πρὸς αὐτὸν πίστιν. προελθὼν δὲ κατὰ τὸ συνεχὲς καὶ διαβὰς τὸν Λύκον ποταμὸν προῆγεν ἐπὶ τὰς τῶν Μυσῶν κατοικίας, ἀπὸ δὲ τούτων γενόμενος ἧκε πρὸς Καρσέας. καταπληξάμενος δὲ τούτους, ὁμοίως δὲ καὶ τοὺς τὰ Δίδυμα τείχη φυλάττοντας, παρέλαβε καὶ ταῦτα τὰ χωρία, Θεμιστοκλέους αὐτὰ παραδόντος, ὃς ἐτύγχανε στρατηγὸς ὑπ’ Ἀχαιοῦ καταλελειμμένος τῶν τόπων τούτων. ὁρμήσας δ’ ἐντεῦθεν καὶ κατασύρας τὸ Ἀπίας πεδίον ὑπερέβαλε τὸ καλούμενον ὄρος Πελεκᾶντα καὶ κατέζευξε περὶ τὸν Μέγιστον ποταμόν.", "st": "5.77"}, {"sp": "N", "t": "οὗ γενομένης ἐκλείψεως σελήνης, πάλαι δυσχερῶς φέροντες οἱ Γαλάται τὰς ἐν ταῖς πορείαις κακοπαθείας, ἅτε ποιούμενοι τὴν στρατείαν μετὰ γυναικῶν καὶ τέκνων, ἑπομένων αὐτοῖς τούτων ἐν ταῖς ἁμάξαις, τότε σημειωσάμενοι τὸ γεγονὸς οὐκ ἂν ἔφασαν ἔτι προελθεῖν εἰς τὸ πρόσθεν. ὁ δὲ βασιλεὺς Ἄτταλος, χρείαν μὲν ἐξ αὐτῶν οὐδεμίαν ὁλοσχερῆ κομιζόμενος, θεωρῶν δ’ ἀποσπωμένους ἐν ταῖς πορείαις καὶ καθ’ αὑτοὺς στρατοπεδεύοντας καὶ τὸ ὅλον ἀπειθοῦντας καὶ πεφρονηματισμένους, εἰς ἀμηχανίαν ἐνέπιπτεν οὐ τὴν τυχοῦσαν· ἅμα μὲν γὰρ ἠγωνία μὴ πρὸς τὸν Ἀχαιὸν ἀπονεύσαντες συνεπίθωνται τοῖς αὑτοῦ πράγμασιν, ἅμα δ’ ὑφεωρᾶτο τὴν ἐξακολουθοῦσαν αὐτῷ φήμην, ἐὰν περιστήσας τοὺς στρατιώτας διαφθείρῃ πάντας τοὺς δοκοῦντας διὰ τῆς ἰδίας πίστεως πεποιῆσθαι τὴν εἰς τὴν Ἀσίαν διάβασιν. διὸ τῆς προειρημένης ἀφορμῆς λαβόμενος ἐπηγγείλατο κατὰ μὲν τὸ παρὸν ἀποκαταστήσειν αὐτοὺς πρὸς τὴν διάβασιν καὶ τόπον δώσειν εὐφυῆ πρὸς κατοικίαν, μετὰ δὲ ταῦτα συμπράξειν εἰς ὁπόσ’ ἂν αὐτὸν παρακαλῶσι τῶν δυνατῶν καὶ καλῶς ἐχόντων. Ἄτταλος μὲν οὖν, ἀποκαταστήσας τοὺς Αἰγοσάγας εἰς τὸν Ἑλλήσποντον καὶ χρηματίσας φιλανθρώπως Λαμψακηνοῖς, Ἀλεξανδρεῦσιν, Ἰλιεῦσι, διὰ τὸ τετηρηκέναι τούτους τὴν πρὸς αὐτὸν πίστιν, ἀνεχώρησε μετὰ τῆς δυνάμεως εἰς Πέργαμον·", "st": "5.78"}, {"sp": "N", "t": "Ἀντίοχος δὲ καὶ Πτολεμαῖος, τῆς ἐαρινῆς ὥρας ἐνισταμένης, ἑτοίμας ἔχοντες τὰς παρασκευὰς ἐγίνοντο πρὸς τῷ διὰ μάχης κρίνειν τὴν ἔφοδον. οἱ μὲν οὖν περὶ τὸν Πτολεμαῖον ὥρμησαν ἐκ τῆς Ἀλεξανδρείας, ἔχοντες πεζῶν μὲν εἰς ἑπτὰ μυριάδας, ἱππεῖς δὲ πεντακισχιλίους, ἐλέφαντας ἑβδομήκοντα τρεῖς· Ἀντίοχος δὲ γνοὺς τὴν ἔφοδον αὐτῶν συνῆγε τὰς δυνάμεις. ἦσαν δ’ αὗται Δάαι μὲν καὶ Καρμάνιοι καὶ Κίλικες εἰς τὸν τῶν εὐζώνων τρόπον καθωπλισμένοι περὶ πεντακισχιλίους· τούτων δ’ ἅμα τὴν ἐπιμέλειαν εἶχε καὶ τὴν ἡγεμονίαν Βύττακος ὁ Μακεδών. ὑπὸ δὲ Θεόδοτον τὸν Αἰτωλὸν τὸν ποιησάμενον τὴν προδοσίαν ἦσαν ἐκ πάσης ἐκλελεγμένοι τῆς βασιλείας, καθωπλισμένοι δ’ εἰς τὸν Μακεδονικὸν τρόπον, ἄνδρες μύριοι· τούτων οἱ πλείονες ἀργυράσπιδες. τὸ δὲ τῆς φάλαγγος πλῆθος ἦν εἰς δυσμυρίους, ἧς ἡγεῖτο Νίκαρχος καὶ Θεόδοτος ὁ καλούμενος ἡμιόλιος. πρὸς δὲ τούτοις Ἀγριᾶνες καὶ Πέρσαι τοξόται καὶ σφενδονῆται δισχίλιοι. μετὰ δὲ τούτων χίλιοι Θρᾷκες, ὧν ἡγεῖτο Μενέδημος Ἀλαβανδεύς. ὑπῆρχον δὲ καὶ Μήδων καὶ Κισσίων καὶ Καδουσίων καὶ Καρμανῶν οἱ πάντες εἰς πεντακισχιλίους, οἷς ἀκούειν Ἀσπασιανοῦ προσετέτακτο τοῦ Μήδου. Ἄραβες δὲ καί τινες τῶν τούτοις προσχώρων ἦσαν μὲν εἰς μυρίους, ὑπετάττοντο δὲ Ζαβδιβήλῳ. τῶν δ’ ἀπὸ τῆς Ἑλλάδος μισθοφόρων ἡγεῖτο μὲν Ἱππόλοχος Θετταλός, ὑπῆρχον δὲ τὸν ἀριθμὸν εἰς πεντακισχιλίους. Κρῆτας δὲ χιλίους μὲν καὶ πεντακοσίους εἶχε τοὺς μετ’ Εὐρυλόχου, χιλίους δὲ Νεόκρητας τοὺς ὑπὸ Ζέλυν τὸν Γορτύνιον ταττομένους· οἷς ἅμα συνῆσαν ἀκοντισταὶ Λυδοὶ πεντακόσιοι καὶ Κάρδακες οἱ μετὰ Λυσιμάχου τοῦ Γαλάτου χίλιοι. τῶν δ’ ἱππέων ἦν τὸ πᾶν πλῆθος εἰς ἑξακισχιλίους· εἶχε δὲ τῶν μὲν τετρακισχιλίων τὴν ἡγεμονίαν Ἀντίπατρος ὁ τοῦ βασιλέως ἀδελφιδοῦς, ἐπὶ δὲ τῶν λοιπῶν ἐτέτακτο Θεμίσων. καὶ τῆς μὲν Ἀντιόχου δυνάμεως τὸ πλῆθος ἦν πεζοὶ μὲν ἑξακισμύριοι καὶ δισχίλιοι, σὺν δὲ τούτοις ἱππεῖς ἑξακισχίλιοι, θηρία δὲ δυσὶ πλείω τῶν ἑκατόν.", "st": "5.79"}, {"sp": "N", "t": "Πτολεμαῖος δὲ ποιησάμενος τὴν πορείαν ἐπὶ Πηλουσίου, τὸ μὲν πρῶτον ἐν ταύτῃ τῇ πόλει κατέζευξε, προσαναλαβὼν δὲ τοὺς ἐφελκομένους καὶ σιτομετρήσας τὴν δύναμιν ἐκίνει, καὶ προῆγε ποιούμενος τὴν πορείαν παρὰ τὸ Κάσιον καὶ τὰ Βάραθρα καλούμενα διὰ τῆς ἀνύδρου. διανύσας δ’ ἐπὶ τὸ προκείμενον πεμπταῖος, κατεστρατοπέδευσε πεντήκοντα σταδίους ἀποσχὼν Ῥαφίας, ἣ κεῖται μετὰ Ῥινοκόλουρα πρώτη τῶν κατὰ Κοίλην Συρίαν πόλεων ὡς πρὸς τὴν Αἴγυπτον. κατὰ δὲ τοὺς αὐτοὺς καιροὺς Ἀντίοχος ἧκε τὴν δύναμιν ἔχων, παραγενόμενος δ’ εἰς Γάζαν καὶ προσαναλαβὼν ἐνταῦθα τὴν δύναμιν αὖθις προῄει βάδην. καὶ παραλλάξας τὴν προειρημένην πόλιν κατεστρατοπέδευσε νυκτός, ἀποσχὼν τῶν ὑπεναντίων ὡς δέκα σταδίους. τὸ μὲν οὖν πρῶτον ἐν τούτῳ τῷ διαστήματι γεγονότες ἀντεστρατοπέδευον ἀλλήλοις· μετὰ δέ τινας ἡμέρας Ἀντίοχος, ἅμα τόπον βουλόμενος εὐφυέστερον μεταλαβεῖν καὶ ταῖς δυνάμεσιν ἐμποιῆσαι θάρσος, προσεστρατοπέδευσε τοῖς περὶ τὸν Πτολεμαῖον, ὥστε μὴ πλεῖον τῶν πέντε σταδίων τοὺς χάρακας ἀπέχειν ἀλλήλων. ἐν ᾧ καιρῷ περί τε τὰς ὑδρείας καὶ προνομὰς ἐγίνοντο συμπλοκαὶ πλείους, ὁμοίως δὲ καὶ μεταξὺ τῶν στρατοπέδων ἀκροβολισμοὶ συνίσταντο, ποτὲ μὲν ἱππέων, ποτὲ δὲ καὶ πεζῶν.", "st": "5.80"}, {"sp": "N", "t": "κατὰ δὲ τὸν καιρὸν τοῦτον Θεόδοτος Αἰτωλικῇ μέν, οὐκ ἀνάνδρῳ δ’ ἐπεβάλετο τόλμῃ καὶ πράξει. συνειδὼς γὰρ ἐκ τῆς προγεγενημένης συμβιώσεως τὴν τοῦ βασιλέως αἵρεσιν καὶ δίαιταν ποία τις ἦν, εἰσπορεύεται τρίτος γενόμενος ὑπὸ τὴν ἑωθινὴν εἰς τὸν τῶν πολεμίων χάρακα. κατὰ μὲν οὖν τὴν ὄψιν ἄγνωστος ἦν διὰ τὸ σκότος, κατὰ δὲ τὴν ἐσθῆτα καὶ τὴν ἄλλην περικοπὴν ἀνεπισήμαντος διὰ τὸ ποικίλην εἶναι κἀκείνων τὴν δύναμιν. ἐστοχασμένος δ’ ἐν ταῖς πρότερον ἡμέραις τῆς τοῦ βασιλέως σκηνῆς διὰ τὸ παντελῶς σύνεγγυς γίνεσθαι τοὺς ἀκροβολισμούς, ὥρμησε θρασέως ἐπ’ αὐτήν, καὶ τοὺς μὲν πρώτους πάντας διελθὼν ἔλαθε, παραπεσὼν δ’ εἰς τὴν σκηνήν, ἐν ᾗ χρηματίζειν εἰώθει καὶ δειπνεῖν ὁ βασιλεύς, πάντα τόπον ἐρευνήσας τοῦ μὲν βασιλέως ἀπέτυχε διὰ τὸ τὸν μὲν Πτολεμαῖον ἐκτὸς τῆς ἐπιφανοῦς καὶ χρηματιστικῆς σκηνῆς ποιεῖσθαι τὴν ἀνάπαυσιν, δύο δέ τινας τῶν αὐτοῦ κοιμωμένων τραυματίσας, καὶ τὸν ἰατρὸν τοῦ βασιλέως Ἀνδρέαν ἀποκτείνας, ἀνεχώρησε μετ’ ἀσφαλείας εἰς τὴν ἑαυτοῦ παρεμβολήν, βραχέα θορυβηθεὶς ἤδη περὶ τὴν τοῦ χάρακος ἔκπτωσιν, τῇ μὲν τόλμῃ συντετελεκὼς τὴν πρόθεσιν, τῇ δὲ προνοίᾳ διεσφαλμένος διὰ τὸ μὴ καλῶς ἐξητακέναι ποῦ τὴν ἀνάπαυσιν ὁ Πτολεμαῖος εἰώθει ποιεῖσθαι.", "st": "5.81"}, {"sp": "N", "t": "οἱ δὲ βασιλεῖς πένθ’ ἡμέρας ἀντιστρατοπεδεύσαντες ἀλλήλοις, ἔγνωσαν ἀμφότεροι διὰ μάχης κρίνειν τὰ πράγματα. καταρχομένων δὲ τῶν περὶ τὸν Πτολεμαῖον κινεῖν τὴν δύναμιν ἐκ τοῦ χάρακος, εὐθέως οἱ περὶ τὸν Ἀντίοχον ἀντεξῆγον. καὶ τὰς μὲν φάλαγγας ἀμφότεροι καὶ τοὺς ἐπιλέκτους τοὺς εἰς τὸν Μακεδονικὸν τρόπον καθωπλισμένους κατὰ πρόσωπον ἀλλήλων ἔταξαν, τὰ δὲ κέρατα Πτολεμαίῳ μὲν ἑκάτερα τουτονὶ συνίστατο τὸν τρόπον. Πολυκράτης μὲν εἶχε μετὰ τῶν ὑφ’ ἑαυτὸν ἱππέων τὸ λαιὸν κέρας· τούτου δὲ καὶ τῆς φάλαγγος μεταξὺ Κρῆτες ἦσαν παρ’ αὐτοὺς τοὺς ἱππεῖς, ἑξῆς δὲ τούτοις τὸ βασιλικὸν ἄγημα, μετὰ δὲ τούτους οἱ μετὰ Σωκράτους πελτασταί, συνάπτοντες τοῖς Λίβυσι τοῖς εἰς τὸν Μακεδονικὸν τρόπον καθωπλισμένοις. ἐπὶ δὲ τοῦ δεξιοῦ κέρως Ἐχεκράτης ἦν ὁ Θετταλός, ἔχων τοὺς ὑφ’ αὑτὸν ἱππεῖς· παρὰ δὲ τοῦτον ἐκ τῶν εὐωνύμων. ἵσταντο Γαλάται καὶ Θρᾷκες· ἑξῆς δὲ τούτοις Φοξίδας εἶχε τοὺς ἀπὸ τῆς Ἑλλάδος μισθοφόρους, συνάπτοντας τοῖς τῶν Αἰγυπτίων φαλαγγίταις. τῶν δὲ θηρίων τὰ μὲν τετταράκοντα κατὰ τὸ λαιὸν ἦν, ἐφ’ οὗ Πτολεμαῖος αὐτὸς ἔμελλε ποιεῖσθαι τὸν κίνδυνον, τὰ δὲ τριάκοντα καὶ τρία πρὸ τοῦ δεξιοῦ κέρατος ἐτέτακτο κατ’ αὐτοὺς τοὺς μισθοφόρους ἱππεῖς. Ἀντίοχος δὲ τοὺς μὲν ἑξήκοντα τῶν ἐλεφάντων, ἐφ’ ὧν ἦν Φίλιππος ὁ σύντροφος αὐτοῦ, πρὸ τοῦ δεξιοῦ κέρατος προέστησε, καθ’ ὃ ποιεῖσθαι τὸν κίνδυνον αὐτὸς ἔμελλε πρὸς τοὺς περὶ τὸν Πτολεμαῖον· τούτων δὲ κατόπιν δισχιλίους μὲν ἱππεῖς τοὺς ὑπ’ Ἀντίπατρον ταττομένους ἐπέστησε, δισχιλίους δ’ ἐν ἐπικαμπίῳ παρενέβαλε. παρὰ δὲ τοὺς ἱππεῖς ἐν μετώπῳ τοὺς Κρῆτας ἔστησε· τούτοις δ’ ἑξῆς ἔταξε τοὺς ἀπὸ τῆς Ἑλλάδος μισθοφόρους· μετὰ δὲ τούτων καὶ τῶν εἰς τὸν Μακεδονικὸν τρόπον καθωπλισμένων τοὺς μετὰ Βυττάκου τοῦ Μακεδόνος ὄντας πεντακισχιλίους παρενέβαλε. τῆς δ’ εὐωνύμου τάξεως ἐπ’ αὐτὸ μὲν τὸ κέρας ἔθηκε δισχιλίους ἱππεῖς, ὧν ἡγεῖτο Θεμίσων, παρὰ δὲ τούτους Κάρδακας καὶ Λυδοὺς ἀκοντιστάς, ἑξῆς δὲ τούτοις τοὺς ὑπὸ Μενέδημον εὐζώνους, ὄντας εἰς τρισχιλίους, μετὰ δὲ τούτους Κισσίους καὶ Μήδους καὶ Καρμανίους, παρὰ δὲ τούτους Ἄραβας ἅμα τοῖς προσχώροις, συνάπτοντας τῇ φάλαγγι. τὰ δὲ κατάλοιπα τῶν θηρίων τοῦ λαιοῦ κέρατος προεβάλετο, τῶν βασιλικῶν τινα γεγονότα παίδων ἐπιστήσας Μυΐσκον.", "st": "5.82"}, {"sp": "N", "t": "τοῦτον δὲ τὸν τρόπον τῶν δυνάμεων ἐκτεταγμένων ἐπιπαρῄεσαν οἱ βασιλεῖς ἀμφότεροι κατὰ πρόσωπον τὰς αὑτῶν τάξεις παρακαλοῦντες ἅμα τοῖς ἡγεμόσι καὶ φίλοις. μεγίστας δ’ ἐν τοῖς φαλαγγίταις ἐλπίδας ἔχοντες ἀμφότεροι πλείστην καὶ σπουδὴν καὶ παράκλησιν ἐποιοῦντο περὶ ταύτας τὰς τάξεις, Πτολεμαίῳ μὲν Ἀνδρομάχου καὶ Σωσιβίου καὶ τῆς ἀδελφῆς Ἀρσινόης, τῷ δὲ Θεοδότου καὶ Νικάρχου συμπαρακαλούντων διὰ τὸ παρ’ ἑκατέρῳ τούτους ἔχειν τὰς τῶν φαλαγγιτῶν ἡγεμονίας. ἦν δὲ παραπλήσιος ὁ νοῦς τῶν ὑφ’ ἑκατέρου παρακαλουμένων. ἴδιον μὲν γὰρ ἔργον ἐπιφανὲς καὶ κατηξιωμένον προφέρεσθαι τοῖς παρακαλουμένοις οὐδέτερος αὐτῶν εἶχε διὰ τὸ προσφάτως παρειληφέναι τὰς ἀρχάς, τῆς δὲ τῶν προγόνων δόξης καὶ τῶν ἐκείνοις πεπραγμένων ἀναμιμνήσκοντες φρόνημα καὶ θάρσος τοῖς φαλαγγίταις ἐπειρῶντο παριστάναι. μάλιστα δὲ τὰς ἐξ αὑτῶν εἰς τὸ μέλλον ἐλπίδας ἐπιδεικνύντες, καὶ κατ’ ἰδίαν τοὺς ἡγουμένους καὶ κοινῇ πάντας τοὺς ἀγωνίζεσθαι μέλλοντας ἠξίουν καὶ παρεκάλουν ἀνδρωδῶς καὶ γενναίως χρήσασθαι τῷ παρόντι κινδύνῳ. ταῦτα δὲ καὶ τούτοις παραπλήσια λέγοντες, τὰ μὲν δι’ αὑτῶν, τὰ δὲ καὶ διὰ τῶν ἑρμηνέων, παρίππευον.", "st": "5.83"}, {"sp": "N", "t": "ἐπεὶ δὲ παριὼν ἧκε μετὰ τῆς ἀδελφῆς Πτολεμαῖος μὲν ἐπὶ τὸ πάσης τῆς σφετέρας παρατάξεως εὐώνυμον, Ἀντίοχος δὲ μετὰ τῆς βασιλικῆς ἴλης ἐπὶ τὸ δεξιόν, σημήναντες τὸ πολεμικὸν συνέβαλον πρῶτον τοῖς θηρίοις. ὀλίγα μὲν οὖν τινα τῶν παρὰ Πτολεμαίου συνήρεισε τοῖς ἐναντίοις· ἐφ’ ὧν ἐποίουν ἀγῶνα καλὸν οἱ πυργομαχοῦντες, ἐκ χειρὸς ταῖς σαρίσαις διαδορατιζόμενοι καὶ τύπτοντες ἀλλήλους, ἔτι δὲ καλλίω τὰ θηρία, βιαιομαχοῦντα καὶ συμπίπτοντα κατὰ πρόσωπον αὑτοῖς. ἔστι γὰρ ἡ τῶν ζῴων μάχη τοιαύτη τις. συμπλέξαντα καὶ παρεμβαλόντα τοὺς ὀδόντας εἰς ἀλλήλους ὠθεῖ τῇ βίᾳ, διερειδόμενα περὶ τῆς χώρας, ἕως ἂν κατακρατῆσαν τῇ δυνάμει θάτερον παρώσῃ τὴν θατέρου προνομήν· ὅταν δ’ ἅπαξ ἐγκλῖναν πλάγιον λάβῃ, τιτρώσκει τοῖς ὀδοῦσι, καθάπερ οἱ ταῦροι τοῖς κέρασι. τὰ δὲ πλεῖστα τῶν τοῦ Πτολεμαίου θηρίων ἀπεδειλία τὴν μάχην, ὅπερ ἔθος ἐστὶ ποιεῖν τοῖς Λιβυκοῖς ἐλέφασι· τὴν γὰρ ὀσμὴν καὶ φωνὴν οὐ μένουσιν, ἀλλὰ καὶ καταπεπληγμένοι τὸ μέγεθος καὶ τὴν δύναμιν, ὥς γ’ ἐμοὶ δοκεῖ, φεύγουσιν εὐθέως ἐξ ἀποστήματος τοὺς Ἰνδικοὺς ἐλέφαντας· ὃ καὶ τότε συνέβη γενέσθαι. τούτων δὲ διαταραχθέντων καὶ πρὸς τὰς αὑτῶν τάξεις συνωθουμένων, τὸ μὲν ἄγημα τὸ τοῦ Πτολεμαίου πιεζόμενον ὑπὸ τῶν θηρίων ἐνέκλινε, τοῖς δὲ περὶ τὸν Πολυκράτην καὶ τοῖς ὑπὸ τοῦτον ἱππεῦσι διατεταγμένοις οἱ περὶ τὸν Ἀντίοχον ὑπὲρ τὰ θηρία περικερῶντες καὶ προσπίπτοντες ἐνέβαλον. ἅμα δὲ τούτοις, τῶν ἐλεφάντων ἐντός, οἱ περὶ τὴν φάλαγγα τῶν Ἑλλήνων μισθοφόροι προσπεσόντες τοὺς τοῦ Πτολεμαίου πελταστὰς ἐξέωσαν, προσυγκεχυκότων ἤδη καὶ τὰς τούτων τάξεις τῶν θηρίων. τὸ μὲν οὖν εὐώνυμον τοῦ Πτολεμαίου τοῦτον τὸν", "st": "5.84"}, {"sp": "N", "t": "τρόπον πιεζόμενον ἐνέκλινε πᾶν, Ἐχεκράτης δ’ ὁ τὸ δεξιὸν ἔχων κέρας τὸ μὲν πρῶτον ἐκαραδόκει τὴν τῶν προειρημένων κεράτων σύμπτωσιν, ἐπεὶ δὲ τὸν μὲν κονιορτὸν ἑώρα κατὰ τῶν ἰδίων φερόμενον, τὰ δὲ παρ’ αὑτοῖς θηρία τὸ παράπαν οὐδὲ προσιέναι τολμῶντα τοῖς ὑπεναντίοις, τῷ μὲν Φοξίδᾳ παρήγγειλε τοὺς ἀπὸ τῆς Ἑλλάδος ἔχοντι μισθοφόρους συμβαλεῖν τοῖς κατὰ πρόσωπον ἀντιτεταγμένοις, αὐτὸς δ’ ἐξαγαγὼν κατὰ κέρας τοὺς ἱππεῖς καὶ τοὺς ὑπὸ τὰ θηρία τεταγμένους τῆς μὲν ἐφόδου τῶν θηρίων ἐκτὸς ἐγεγόνει, τοὺς δὲ τῶν πολεμίων ἱππεῖς, οὓς μὲν ὑπεραίρων, οἷς δὲ κατὰ κέρας ἐμβάλλων, ταχέως ἐτρέψατο. τὸ δὲ παραπλήσιον ὅ τε Φοξίδας καὶ πάντες οἱ περὶ αὐτὸν ἐποίησαν· προσπεσόντες γὰρ τοῖς Ἄραψι καὶ τοῖς Μήδοις ἠνάγκασαν ἀποστραφέντας φεύγειν προτροπάδην. τὸ μὲν οὖν δεξιὸν τῶν περὶ τὸν Ἀντίοχον ἐνίκα, τὸ δ’ εὐώνυμον ἡττᾶτο τὸν προειρημένον τρόπον. αἱ δὲ φάλαγγες, ἀμφοτέρων τῶν κεράτων αὐταῖς ἐψιλωμένων, ἔμενον ἀκέραιοι κατὰ μέσον τὸ πεδίον, ἀμφηρίστους ἔχουσαι τὰς ὑπὲρ τοῦ μέλλοντος ἐλπίδας. κατὰ δὲ τὸν καιρὸν τοῦτον Ἀντίοχος μὲν ἐνηγωνίζετο τῷ κατὰ τὸ δεξιὸν κέρας προτερήματι, Πτολεμαῖος δὲ τὴν ἀποχώρησιν ὑπὸ τὴν φάλαγγα πεποιημένος, τότε προελθὼν εἰς μέσον καὶ φανεὶς ταῖς δυνάμεσι τοὺς μὲν ὑπεναντίους κατεπλήξατο, τοῖς δὲ παρ’ αὑτοῦ μεγάλην ὁρμὴν ἐνειργάσατο καὶ προθυμίαν. διὸ καὶ καταβαλόντες παραχρῆμα τὰς σαρίσας οἱ περὶ τὸν Ἀνδρόμαχον καὶ Σωσίβιον ἐπῆγον. οἱ μὲν οὖν ἐπίλεκτοι τῶν Συριακῶν βραχύν τινα χρόνον ἀντέστησαν, οἵ τε μετὰ τοῦ Νικάρχου ταχέως ἐγκλίναντες ὑπεχώρουν· ὁ δ’ Ἀντίοχος, ὡς ἂν ἄπειρος καὶ νέος, ὑπολαμβάνων ἐκ τοῦ καθ’ ἑαυτὸν μέρους καὶ τὰ λοιπὰ παραπλησίως αὑτῷ πάντα νικᾶν, ἐπέκειτο τοῖς φεύγουσιν. ὀψὲ δέ ποτε τῶν πρεσβυτέρων τινὸς ἐπιστήσαντος αὐτόν, καὶ δείξαντος φερόμενον τὸν κονιορτὸν ἀπὸ τῆς φάλαγγος ἐπὶ τὴν ἑαυτῶν παρεμβολήν, τότε συννοήσας τὸ γινόμενον ἀνατρέχειν ἐπειρᾶτο μετὰ τῆς βασιλικῆς ἴλης ἐπὶ τὸν τῆς παρατάξεως τόπον. καταλαβὼν δὲ τοὺς παρ’ αὑτοῦ πάντας πεφευγότας, οὕτως ἐποιεῖτο τὴν ἀποχώρησιν εἰς τὴν Ῥαφίαν, τὸ μὲν καθ’ αὑτὸν μέρος πεπεισμένος νικᾶν, διὰ δὲ τὴν τῶν ἄλλων ἀγεννίαν καὶ δειλίαν ἐσφάλθαι νομίζων τοῖς ὅλοις.", "st": "5.85"}, {"sp": "N", "t": "Πτολεμαῖος δὲ διὰ μὲν τῆς φάλαγγος τὰ ὅλα διακρίνας, διὰ δὲ τῶν ἀπὸ τοῦ δεξιοῦ κέρατος ἱππέων καὶ μισθοφόρων πολλοὺς ἀποκτείνας κατὰ τὸ δίωγμα τῶν ὑπεναντίων, τότε μὲν ἀναχωρήσας ἐπὶ τῆς ὑπαρχούσης ηὐλίσθη παρεμβολῆς. τῇ δ’ ἐπαύριον τοὺς μὲν ἰδίους νεκροὺς ἀνελόμενος καὶ θάψας, τοὺς δὲ τῶν ἐναντίων σκυλεύσας, ἀνέζευξε καὶ προῆγε πρὸς τὴν Ῥαφίαν. ὁ δ’ Ἀντίοχος ἐκ τῆς φυγῆς ἐβούλετο μὲν εὐθέως ἔξω στρατοπεδεύειν, συναθροίσας τοὺς ἐν τοῖς συστήμασι πεφευγότας, τῶν δὲ πλείστων εἰς τὴν πόλιν πεποιημένων τὴν ἀποχώρησιν ἠναγκάσθη καὶ αὐτὸς εἰσελθεῖν. οὗτος μὲν οὖν ὑπὸ τὴν ἑωθινὴν ἐξαγαγὼν τὸ σῳζόμενον μέρος τῆς δυνάμεως διέτεινε πρὸς Γάζαν, κἀκεῖ καταστρατοπεδεύσας καὶ διαπεμψάμενος περὶ τῆς τῶν νεκρῶν ἀναιρέσεως, ἐκήδευσε τοὺς τεθνεῶτας ὑποσπόνδους. ἦσαν δ’ οἱ τετελευτηκότες τῶν παρ’ Ἀντιόχου πεζοὶ μὲν οὐ πολὺ λείποντες μυρίων, ἱππεῖς δὲ πλείους τριακοσίων· ζωγρίᾳ δ’ ἑάλωσαν ὑπὲρ τοὺς τετρακισχιλίους. ἐλέφαντες δὲ τρεῖς μὲν παραχρῆμα, δύο δ’ ἐκ τῶν τραυμάτων ἀπέθανον. τῶν δὲ παρὰ Πτολεμαίου πεζοὶ μὲν εἰς χιλίους καὶ πεντακοσίους ἐτελεύτησαν, ἱππεῖς δ’ εἰς ἑπτακοσίους· τῶν δ’ ἐλεφάντων ἑκκαίδεκα μὲν ἀπέθανον, ᾑρέθησαν δ’ αὐτῶν οἱ πλείους. ἡ μὲν οὖν πρὸς Ῥαφίαν μάχη γενομένη τοῖς βασιλεῦσι περὶ Κοίλης Συρίας τοῦτον ἀπετελέσθη τὸν τρόπον· μετὰ δὲ τὴν τῶν νεκρῶν ἀναίρεσιν Ἀντίοχος μὲν ἐποιεῖτο τὴν ἀποχώρησιν εἰς τὴν οἰκείαν μετὰ τῆς δυνάμεως, Πτολεμαῖος δὲ τήν τε Ῥαφίαν καὶ τὰς ἄλλας πόλεις ἐξ ἐφόδου παρελάμβανε, πάντων τῶν πολιτευμάτων ἁμιλλωμένων ὑπὲρ τοῦ φθάσαι τοὺς πέλας περὶ τὴν ἀποκατάστασιν καὶ μετάθεσιν τὴν πρὸς αὐτόν. ἴσως μὲν οὖν εἰώθασι πάντες περὶ τοὺς τοιούτους καιροὺς ἁρμόζεσθαί πως ἀεὶ πρὸς τὸ παρόν· μάλιστα δὲ τὸ κατ’ ἐκείνους τοὺς τόπους γένος τῶν ἀνθρώπων εὐφυὲς καὶ πρόχειρον πρὸς τὰς ἐκ τοῦ καιροῦ χάριτας. τότε δὲ καὶ τῆς εὐνοίας προκαθηγουμένης πρὸς τοὺς ἀπὸ τῆς Ἀλεξανδρείας βασιλεῖς εἰκότως τοῦτο συνέβαινε γίνεσθαι· τῇ γὰρ οἰκίᾳ ταύτῃ μᾶλλον ἀεί πως οἱ κατὰ Κοίλην Συρίαν ὄχλοι προσκλίνουσι. διόπερ οὐκ ἀπέλειπον ὑπερβολὴν ἀρεσκείας, στεφάνοις καὶ θυσίαις καὶ βωμοῖς καὶ παντὶ τῷ τοιούτῳ τρόπῳ τιμῶντες τὸν Πτολεμαῖον.", "st": "5.86"}, {"sp": "N", "t": "Ἀντίοχος δὲ παραγενόμενος εἰς τὴν ἐπώνυμον αὑτοῦ πόλιν εὐθέως ἐξέπεμψε τοὺς περὶ τὸν Ἀντίπατρον τὸν ἀδελφιδοῦν καὶ Θεόδοτον τὸν ἡμιόλιον πρεσβευτὰς πρὸς τὸν Πτολεμαῖον ὑπὲρ εἰρήνης καὶ διαλύσεως, ἀγωνιῶν τὴν τῶν ὑπεναντίων ἔφοδον· ἠπίστει μὲν γὰρ τοῖς ὄχλοις διὰ τὸ γεγονὸς ἐλάττωμα περὶ αὐτόν, ἐφοβεῖτο δὲ τὸν Ἀχαιὸν μὴ συνεπίθηται τοῖς καιροῖς. Πτολεμαῖος δὲ τούτων οὐδὲν συλλογιζόμενος, ἀλλ’ ἀσμενίζων ἐπὶ τῷ γεγονότι προτερήματι διὰ τὸ παράδοξον καὶ συλλήβδην ἐπὶ τῷ Κοίλην Συρίαν ἐκτῆσθαι παραδόξως, οὐκ ἀλλότριος ἦν τῆς ἡσυχίας, ἀλλ’ ὑπὲρ τὸ δέον οἰκεῖος, ἑλκόμενος ὑπὸ τῆς συνήθους ἐν τῷ βίῳ ῥᾳθυμίας καὶ καχεξίας. πλὴν παραγενομένων τῶν περὶ τὸν Ἀντίπατρον, βραχέα προσαναταθεὶς καὶ καταμεμψάμενος ἐπὶ τοῖς πεπραγμένοις τὸν Ἀντίοχον, συνεχώρησε σπονδὰς ἐνιαυσίους. καὶ τούτοις μὲν ἐπικυρώσοντα τὰς διαλύσεις συνεξαπέστειλε Σωσίβιον, αὐτὸς δὲ διατρίψας ἐπὶ τρεῖς μῆνας ἐν τοῖς κατὰ Συρίαν καὶ Φοινίκην τόποις καὶ καταστησάμενος τὰς πόλεις, μετὰ ταῦτα καταλιπὼν τὸν Ἀνδρόμαχον τὸν Ἀσπένδιον στρατηγὸν ἐπὶ πάντων τῶν προειρημένων τόπων ἀνέζευξε μετὰ τῆς ἀδελφῆς καὶ τῶν φίλων ἐπ’ Ἀλεξανδρείας, παράδοξον τοῖς ἐν τῇ βασιλείᾳ πρὸς τὴν τοῦ λοιποῦ βίου προαίρεσιν τέλος ἐπιτεθεικὼς τῷ πολέμῳ. Ἀντίοχος δὲ τὰ περὶ τὰς σπονδὰς ἀσφαλισάμενος πρὸς τὸν Σωσίβιον, ἐγίνετο κατὰ τὴν ἐξ ἀρχῆς πρόθεσιν περὶ τὴν ἐπὶ τὸν Ἀχαιὸν παρασκευήν. τὰ μὲν οὖν κατὰ τὴν Ἀσίαν ἐν τούτοις ἦν.", "st": "5.87"}, {"sp": "N", "t": "Ῥόδιοι δὲ κατὰ τοὺς προειρημένους καιροὺς ἐπειλημμένοι τῆς ἀφορμῆς τῆς κατὰ τὸν σεισμὸν τὸν γενόμενον παρ’ αὐτοῖς βραχεῖ χρόνῳ πρότερον, ἐν ᾧ συνέβη τόν τε κολοσσὸν τὸν μέγαν πεσεῖν καὶ τὰ πλεῖστα τῶν τειχῶν καὶ τῶν νεωρίων, οὕτως ἐχείριζον νουνεχῶς καὶ πραγματικῶς τὸ γεγονὸς ὡς μὴ βλάβης, διορθώσεως δὲ μᾶλλον, αὐτοῖς αἴτιον γενέσθαι τὸ σύμπτωμα. τοσοῦτον ἄγνοια καὶ ῥᾳθυμία διαφέρει παρ’ ἀνθρώποις ἐπιμελείας καὶ φρονήσεως περί τε τοὺς κατ’ ἰδίαν βίους καὶ τὰς κοινὰς πολιτείας, ὥστε τοῖς μὲν καὶ τὰς ἐπιτυχίας βλάβην ἐπιφέρειν, τοῖς δὲ καὶ τὰς περιπετείας ἐπανορθώσεως γίνεσθαι παραιτίας. οἱ γοῦν Ῥόδιοι τότε παρὰ τὸν χειρισμὸν τὸ μὲν σύμπτωμα ποιοῦντες μέγα καὶ δεινόν, αὐτοὶ δὲ σεμνῶς καὶ προστατικῶς κατὰ τὰς πρεσβείας χρώμενοι ταῖς ἐντεύξεσι καὶ ταῖς κατὰ μέρος ὁμιλίαις, εἰς τοῦτ’ ἤγαγον τὰς πόλεις, καὶ μάλιστα τοὺς βασιλεῖς, ὥστε μὴ μόνον λαμβάνειν δωρεὰς ὑπερβαλλούσας, ἀλλὰ καὶ χάριν προσοφείλειν αὐτοῖς τοὺς διδόντας. Ἱέρων γὰρ καὶ Γέλων οὐ μόνον ἔδωκαν ἑβδομήκοντα καὶ πέντ’ ἀργυρίου τάλαντα πρὸς τὴν εἰς τὸ ἔλαιον τοῖς ἐν τῷ γυμνασίῳ χορηγίαν, τὰ μὲν παραχρῆμα, τὰ δ’ ἐν χρόνῳ βραχεῖ παντελῶς, ἀλλὰ καὶ λέβητας ἀργυροῦς καὶ βάσεις τούτων καί τινας ὑδρίας ἀνέθεσαν, πρὸς δὲ τούτοις εἰς τὰς θυσίας δέκα τάλαντα καὶ τὴν ἐπαύξησιν τῶν πολιτῶν ἄλλα δέκα, χάριν τοῦ τὴν πᾶσαν εἰς ἑκατὸν τάλαντα γενέσθαι δωρεάν. καὶ μὴν ἀτέλειαν τοῖς πρὸς αὐτοὺς πλοϊζομένοις ἔδοσαν καὶ πεντήκοντα καταπέλτας τριπήχεις. καὶ τελευταῖον τοσαῦτα δόντες, ὡς προσοφείλοντες χάριν, ἔστησαν ἀνδριάντας ἐν τῷ τῶν Ῥοδίων δείγματι, στεφανούμενον τὸν δῆμον τῶν Ῥοδίων ὑπὸ τοῦ δήμου τοῦ Συρακοσίων.", "st": "5.88"}, {"sp": "N", "t": "ἐπηγγείλατο δὲ καὶ Πτολεμαῖος αὐτοῖς ἀργυρίου τάλαντα τριακόσια καὶ σίτου μυριάδας ἀρταβῶν ἑκατόν, ξύλα δὲ ναυπηγήσιμα δέκα πεντήρων καὶ δέκα τριήρων, πευκίνων τετραγώνων πήχεις ἐμμέτρους τετρακισμυρίους, καὶ χαλκοῦ νομίσματος τάλαντα χίλια, στυππίου τρισχίλι’, ὀθονίων ἱστοὺς τρισχιλίους, εἰς τὴν τοῦ κολοσσοῦ κατασκευὴν τάλαντα τρισχίλι’, οἰκοδόμους ἑκατόν, ὑπουργοὺς τριακοσίους καὶ πεντήκοντα, καὶ τούτοις καθ’ ἕκαστον ἔτος εἰς ὀψώνιον τάλαντα δεκατέτταρα, πρὸς δὲ τούτοις εἰς τοὺς ἀγῶνας καὶ τὰς θυσίας ἀρτάβας σίτου μυρίας δισχιλίας, καὶ μὴν εἰς σιτομετρίαν δέκα τριήρων ἀρτάβας δισμυρίας. καὶ τούτων ἔδωκε τὰ μὲν πλεῖστα παραχρῆμα, τοῦ δ’ ἀργυρίου παντὸς τὸ τρίτον μέρος. παραπλησίως Ἀντίγονος ξύλ’ ἀφ’ ἑκκαιδεκαπήχους ἕως ὀκταπήχους εἰς σφηκίσκων λόγον μύρια, στρωτῆρας ἑπταπήχεις πεντακισχιλίους, σιδήρου τάλαντα τρισχίλια, πίττης τάλαντα χίλι’, ἄλλης ὠμῆς μετρητὰς χιλίους, ἀργυρίου πρὸς τούτοις ἑκατὸν ἐπηγγείλατο τάλαντα, Χρυσηὶς δ’ ἡ γυνὴ δέκα μὲν σίτου μυριάδας, τρισχίλια δὲ μολίβδου τάλαντα. Σέλευκος δ’ ὁ πατὴρ Ἀντιόχου χωρὶς μὲν ἀτέλειαν τοῖς εἰς τὴν αὑτοῦ βασιλείαν πλοϊζομένοις, χωρὶς δὲ πεντήρεις μὲν δέκα κατηρτισμένας, σίτου δ’ εἴκοσι μυριάδας, καὶ μὴν ξύλων καὶ ῥητίνης καὶ τριχὸς μυριάδας πηχῶν καὶ ταλάντων χιλιάδας.", "st": "5.89"}, {"sp": "N", "t": "παραπλήσια δὲ τούτοις Προυσίας καὶ Μιθριδάτης, ἔτι δ’ οἱ κατὰ τὴν Ἀσίαν ὄντες δυνάσται τότε, λέγω δὲ Λυσανίαν, Ὀλύμπιχον, Λιμναῖον. τάς γε μὴν πόλεις τὰς συνεπιλαμβανομένας αὐτοῖς κατὰ δύναμιν οὐδ’ ἂν ἐξαριθμήσαιτο ῥᾳδίως οὐδείς· ὥσθ’ ὅταν μέν τις εἰς τὸν χρόνον ἐμβλέψῃ καὶ τὴν ἀρχήν, ἀφ’ οὗ συμβαίνει τὴν πόλιν αὐτῶν συνῳκίσθαι, καὶ λίαν θαυμάζειν ὡς βραχεῖ χρόνῳ μεγάλην ἐπίδοσιν εἴληφε περί τε τοὺς κατ’ ἰδίαν βίους καὶ τὰ κοινὰ τῆς πόλεως· ὅταν δ’ εἰς τὴν εὐκαιρίαν τοῦ τόπου καὶ τὴν ἔξωθεν ἐπιφορὰν καὶ συμπλήρωσιν τῆς εὐδαιμονίας, μηκέτι θαυμάζειν, μικροῦ δ’ ἐλλείπειν δοκεῖν τοῦ καθήκοντος. ταῦτα μὲν οὖν εἰρήσθω μοι χάριν πρῶτον μὲν τῆς Ῥοδίων περὶ τὰ κοινὰ προστασίας — ἐπαίνου γάρ εἰσιν ἄξιοι καὶ ζήλου — δεύτερον δὲ τῆς τῶν νῦν βασιλέων μικροδοσίας καὶ τῆς τῶν ἐθνῶν καὶ πόλεων μικροληψίας, ἵνα μηθ’ οἱ βασιλεῖς τέτταρα καὶ πέντε προϊέμενοι τάλαντα δοκῶσί τι ποιεῖν μέγα καὶ ζητῶσι τὴν αὐτὴν ὑπάρχειν αὐτοῖς εὔνοιαν καὶ τιμὴν παρὰ τῶν Ἑλλήνων, ἣν οἱ πρὸ τοῦ βασιλεῖς εἶχον, αἵ τε πόλεις λαμβάνουσαι πρὸ ὀφθαλμῶν τὸ μέγεθος τῶν πρότερον δωρεῶν μὴ λανθάνωσιν ἐπὶ μικροῖς καὶ τοῖς τυχοῦσι νῦν τὰς μεγίστας καὶ καλλίστας προϊέμεναι τιμάς, ἀλλὰ πειρῶνται τὸ κατ’ ἀξίαν ἑκάστοις τηρεῖν, ᾧ πλεῖστον διαφέρουσιν Ἕλληνες τῶν ἄλλων ἀνθρώπων.", "st": "5.90"}, {"sp": "N", "t": "ἄρτι δὲ τῆς θερινῆς ὥρας ἐνισταμένης, καὶ στρατηγοῦντος Ἀγήτα μὲν τῶν Αἰτωλῶν, Ἀράτου δὲ παρειληφότος τὴν τῶν Ἀχαιῶν στρατηγίαν — ἀπὸ γὰρ τούτων ἐποιησάμεθα τοῦ συμμαχικοῦ πολέμου τὴν ἐκτροπήν — Λυκοῦργος μὲν ὁ Σπαρτιάτης ἐπανῆκε πάλιν ἐξ Αἰτωλίας· οἱ γὰρ ἔφοροι, ψευδῆ τὴν διαβολὴν εὑρόντες, δι’ ἣν ἔφευγε, μετεπέμποντο καὶ μετεκάλουν αὖθις τὸν Λυκοῦργον. οὗτος μὲν οὖν ἐτάττετο πρὸς Πυρρίαν τὸν Αἰτωλόν, ὃς ἐτύγχανε τότε παρὰ τοῖς Ἠλείοις στρατηγὸς ὤν, περὶ τῆς εἰς τὴν Μεσσηνίαν εἰσβολῆς. Ἄρατος δὲ παρειλήφει τό τε ξενικὸν τὸ τῶν Ἀχαιῶν κατεφθαρμένον τάς τε πόλεις ὀλιγώρως διακειμένας πρὸς τὰς εἰς τοῦτο τὸ μέρος εἰσφορὰς διὰ τὸ τὸν πρὸ αὐτοῦ στρατηγὸν Ἐπήρατον, ὡς ἐπάνω προεῖπα, κακῶς καὶ ῥᾳθύμως κεχρῆσθαι τοῖς κοινοῖς πράγμασιν. οὐ μὴν ἀλλὰ παρακαλέσας τοὺς Ἀχαιούς, καὶ λαβὼν δόγμα περὶ τούτων, ἐνεργὸς ἐγίνετο περὶ τὴν τοῦ πολέμου παρασκευήν. ἦν δὲ τὰ δόξαντα τοῖς Ἀχαιοῖς ταῦτα· πεζοὺς μὲν τρέφειν μισθοφόρους ὀκτακισχιλίους, ἱππεῖς δὲ πεντακοσίους, τῶν δ’ Ἀχαϊκῶν ἐπιλέκτους, πεζοὺς μὲν τρισχιλίους, ἱππεῖς δὲ τριακοσίους· εἶναι δὲ τούτων Μεγαλοπολίτας μὲν χαλκάσπιδας, πεζοὺς μὲν πεντακοσίους, ἱππεῖς δὲ πεντήκοντα, καὶ τοὺς ἴσους Ἀργείων. ἔδοξε δὲ καὶ ναῦς πλεῖν τρεῖς μὲν περὶ τὴν Ἀκτὴν καὶ τὸν Ἀργολικὸν κόλπον, τρεῖς δὲ κατὰ Πάτρας καὶ Δύμην καὶ τὴν ταύτῃ θάλατταν.", "st": "5.91"}, {"sp": "N", "t": "Ἄρατος μὲν οὖν ταῦτ’ ἔπραττε καὶ ταύτας ἐξήρτυε τὰς παρασκευάς· ὁ δὲ Λυκοῦργος καὶ Πυρρίας διαπεμψάμενοι πρὸς ἀλλήλους, ἵνα ταῖς αὐταῖς ἡμέραις ποιήσωνται τὴν ἔξοδον, προῆγον εἰς τὴν Μεσσηνίαν. ὁ δὲ στρατηγὸς τῶν Ἀχαιῶν, συνεὶς τὴν ἐπιβολὴν αὐτῶν, ἧκεν ἔχων τοὺς μισθοφόρους καί τινας τῶν ἐπιλέκτων εἰς τὴν Μεγάλην πόλιν παραβοηθήσων τοῖς Μεσσηνίοις. Λυκοῦργος δ’ ἐξορμήσας τὰς μὲν Καλάμας, χωρίον τι τῶν Μεσσηνίων, προδοσίᾳ κατέσχε, μετὰ δὲ ταῦτα προῆγε, σπεύδων συμμῖξαι τοῖς Αἰτωλοῖς. ὁ δὲ Πυρρίας παντελῶς ἐλαφρὸς ἐξελθὼν ἐκ τῆς Ἤλιδος, καὶ κατὰ τὴν εἰσβολὴν τὴν εἰς Μεσσηνίαν εὐθέως κωλυθεὶς ὑπὸ τῶν Κυπαρισσέων, ἀνέστρεψε. διόπερ ὁ Λυκοῦργος, οὔτε συμμῖξαι δυνάμενος τοῖς περὶ τὸν Πυρρίαν οὔτ’ αὐτὸς ἀξιόχρεως ὑπάρχων, ἐπὶ βραχὺ προσβολὰς ποιησάμενος πρὸς τὴν Ἀνδανίαν ἄπρακτος αὖθις εἰς τὴν Σπάρτην ἀπηλλάγη. Ἄρατος δέ, διαπεσούσης τοῖς πολεμίοις τῆς ἐπιβολῆς, τὸ κατὰ λόγον ποιῶν καὶ προνοούμενος τοῦ μέλλοντος, συνετάξατο πρός τε Ταυρίωνα παρασκευάζειν ἱππεῖς πεντήκοντα καὶ πεζοὺς πεντακοσίους καὶ πρὸς Μεσσηνίους, ἵνα τοὺς ἴσους τούτοις ἱππεῖς καὶ πεζοὺς ἐξαποστείλωσι, βουλόμενος τούτοις μὲν τοῖς ἀνδράσι παραφυλάττεσθαι τήν τε τῶν Μεσσηνίων χώραν καὶ Μεγαλοπολιτῶν καὶ Τεγεατῶν, ἔτι δὲ τῶν Ἀργείων — αὗται γὰρ αἱ χῶραι, συντερμονοῦσαι τῇ Λακωνικῇ πρόκεινται τῶν ἄλλων Πελοποννησίων πρὸς τὸν ἀπὸ Λακεδαιμονίων πόλεμον — τοῖς δ’ Ἀχαϊκοῖς ἐπιλέκτοις καὶ μισθοφόροις τὰ πρὸς τὴν Ἠλείαν καὶ τὴν Αἰτωλίαν ἐστραμμένα μέρη τῆς Ἀχαΐας τηρεῖν.", "st": "5.92"}, {"sp": "N", "t": "ταῦτα δ’ ἁρμοσάμενος διέλυε τοὺς Μεγαλοπολίτας πρὸς αὑτοὺς κατὰ τὸ τῶν Ἀχαιῶν δόγμα. συνέβαινε γὰρ τούτους προσφάτως ὑπὸ Κλεομένους ἐπταικότας τῇ πατρίδι καὶ τὸ δὴ λεγόμενον ἐκ θεμελίων ἐσφαλμένους πολλῶν μὲν ἐπιδεῖσθαι, πάντων δὲ σπανίζειν· τοῖς μὲν γὰρ φρονήμασιν ἔμενον, ταῖς δὲ χορηγίαις καὶ κοινῇ καὶ κατ’ ἰδίαν πρὸς πᾶν ἀδυνάτως εἶχον. διόπερ ἦν ἀμφισβητήσεως, φιλοτιμίας, ὀργῆς τῆς ἐν ἀλλήλοις πάντα πλήρη· τοῦτο γὰρ δὴ φιλεῖ γίνεσθαι καὶ περὶ τὰ κοινὰ πράγματα καὶ περὶ τοὺς κατ’ ἰδίαν βίους, ὅταν ἐλλίπωσιν αἱ χορηγίαι τὰς ἑκάστων ἐπιβολάς. πρῶτον μὲν οὖν ἠμφισβήτουν ὑπὲρ τοῦ τειχισμοῦ τῆς πόλεως, φάσκοντες οἱ μὲν συνάγειν αὐτὴν δεῖν καὶ ποιεῖν τηλικαύτην ἡλίκην καὶ τειχίζειν ἐπιβαλλόμενοι καθίξονται καὶ φυλάττειν καιροῦ περιστάντος δυνήσονται· καὶ γὰρ νῦν παρὰ τὸ μέγεθος αὐτῆς καὶ τὴν ἐρημίαν ἐσφάλθαι. πρὸς δὲ τούτοις εἰσφέρειν ᾤοντο δεῖν τοὺς κτηματικοὺς τὸ τρίτον μέρος τῆς γῆς εἰς τὴν τῶν προσλαμβανομένων οἰκητόρων ἀναπλήρωσιν. οἱ δ’ οὔτε τὴν πόλιν ἐλάττω ποιεῖν ὑπέμενον οὔτε τὸ τρίτον τῶν κτήσεων εὐδόκουν εἰσφέρειν μέρος. μάλιστά τε τῶν νόμων ὑπὸ Πρυτάνιδος γεγραμμένων πρὸς ἀλλήλους ἐφιλονείκουν, ὃν ἔδωκε μὲν αὐτοῖς νομοθέτην Ἀντίγονος, ἦν δὲ τῶν ἐπιφανῶν ἀνδρῶν ἐκ τοῦ Περιπάτου καὶ ταύτης τῆς αἱρέσεως. τοιαύτης δ’ οὔσης τῆς ἀμφισβητήσεως ποιησάμενος Ἄρατος τὴν ἐνδεχομένην ἐπιστροφὴν κατέπαυσε τὴν φιλοτιμίαν αὐτῶν. ἐφ’ οἷς δ’ ἔληξαν τῆς πρὸς ἀλλήλους διαφορᾶς, γράψαντες εἰς στήλην παρὰ τὸν τῆς Ἑστίας ἀνέθεσαν βωμὸν ἐν Ὁμαρίῳ.", "st": "5.93"}, {"sp": "N", "t": "μετὰ δὲ τὰς διαλύσεις ταύτας ἀναζεύξας αὐτὸς μὲν ἧκε πρὸς τὴν τῶν Ἀχαιῶν σύνοδον, τοὺς δὲ μισθοφόρους συνέστησε Λύκῳ τῷ Φαραιεῖ, διὰ τὸ τοῦτον ὑποστράτηγον εἶναι τότε τῆς συντελείας τῆς πατρικῆς. οἱ δ’ Ἠλεῖοι, δυσαρεστούμενοι τῷ Πυρρίᾳ, πάλιν ἐπεσπάσαντο στρατηγὸν παρὰ τῶν Αἰτωλῶν Εὐριπίδαν. ὃς τηρήσας τὴν τῶν Ἀχαιῶν σύνοδον, καὶ παραλαβὼν ἱππεῖς μὲν ἑξήκοντα, πεζοὺς δὲ δισχιλίους, ἐξώδευσε, καὶ διελθὼν διὰ τῆς Φαραϊκῆς κατέδραμε τὴν χώραν ἕως τῆς Αἰγιάδος. περιελασάμενος δὲ λείαν ἱκανὴν ἐποιεῖτο τὴν ἀποχώρησιν ὡς ἐπὶ Λεόντιον. οἱ δὲ περὶ τὸν Λύκον συνέντες τὸ γεγονὸς ἐβοήθουν κατὰ σπουδήν, συνάψαντες δὲ τοῖς πολεμίοις καὶ συμμίξαντες ἐξ ἐφόδου κατέβαλον μὲν αὐτῶν εἰς τετρακοσίους, ζωγρίᾳ δ’ ἔλαβον εἰς διακοσίους, ἐν οἷς ἦσαν ἐπιφανεῖς ἄνδρες Φυσσίας, Ἀντάνωρ, Κλέαρχος, Ἀνδρόλοχος, Εὐανορίδας, Ἀριστογείτων, Νικάσιππος, Ἀσπάσιος· τῶν δ’ ὅπλων καὶ τῆς ἀποσκευῆς ἐκυρίευσαν πάσης. κατὰ δὲ τοὺς αὐτοὺς καιροὺς ὁ τῶν Ἀχαιῶν ναύαρχος ἐξοδεύσας εἰς Μολυκρίαν, ἧκεν ἔχων οὐ πολὺ λείποντα τῶν ἑκατὸν σωμάτων. αὖτις δ’ ὑποστρέψας ἔπλευσε πρὸς Χάλκειαν, τῶν δ’ ἐκβοηθησάντων ἐκυρίευσε δύο μακρῶν πλοίων αὐτάνδρων· ἔλαβε δὲ καὶ κέλητα περὶ τὸ Ῥίον Αἰτωλικὸν ὁμοῦ τῷ πληρώματι. συνδραμόντων δὲ τῶν τε κατὰ γῆν καὶ τῶν κατὰ θάλατταν λαφύρων περὶ τοὺς αὐτοὺς καιρούς, καὶ συναχθείσης ἀπὸ τούτων προσόδου καὶ χορηγίας ἱκανῆς, ἐγένετο τοῖς τε στρατιώταις θάρσος ὑπὲρ τῆς τῶν ὀψωνίων κομιδῆς ταῖς τε πόλεσιν ἐλπὶς ὑπὲρ τοῦ μὴ βαρυνθήσεσθαι ταῖς εἰσφοραῖς.", "st": "5.94"}, {"sp": "N", "t": "ἅμα δὲ τοῖς προειρημένοις Σκερδιλαΐδας, νομίζων ὑπὸ τοῦ βασιλέως ἀδικεῖσθαι διὰ τό τινα τῶν χρημάτων ἐλλείπειν αὐτῷ τῶν κατὰ τὰς συντάξεις ὁμολογηθέντων, ἃς ἐποιήσατο πρὸς Φίλιππον, ἐξαπέστειλε λέμβους πεντεκαίδεκα, μετὰ δόλου ποιούμενος τὴν ἐπιβολὴν τῆς κομιδῆς τῶν χρημάτων· οἳ καὶ κατέπλευσαν εἰς Λευκάδα, πάντων αὐτοὺς ὡς φιλίους προσδεχομένων διὰ τὴν γεγενημένην κοινοπραγίαν. ἄλλο μὲν οὖν οὐκ ἔφθασαν οὐδὲν ἐργάσασθαι κακὸν οὐδ’ ἐδυνήθησαν, Ἀγαθίνῳ δὲ καὶ Κασσάνδρῳ τοῖς Κορινθίοις ἐπιπλέουσι ταῖς Ταυρίωνος ναυσὶ καὶ συγκαθορμισθεῖσιν ὡς φίλοις μετὰ τεττάρων πλοίων, παρασπονδήσαντες ἐπέθεντο, καὶ συλλαβόντες αὐτούς τε καὶ τὰ πλοῖα πρὸς Σκερδιλαΐδαν ἀπέπεμψαν. μετὰ δὲ ταῦτα ποιησάμενοι τὴν ἀναγωγὴν ἐκ τῆς Λευκάδος καὶ πλεύσαντες ὡς ἐπὶ Μαλέας ἐλῄζοντο καὶ κατῆγον τοὺς ἐμπόρους. ἤδη δὲ τοῦ θερισμοῦ συνάπτοντος, καὶ τῶν περὶ τὸν Ταυρίωνα κατολιγωρούντων τῆς τῶν ἄρτι ῥηθεισῶν πόλεων προφυλακῆς, Ἄρατος μὲν ἔχων τοὺς ἐπιλέκτους ἐφήδρευε τῇ τοῦ σίτου κομιδῇ περὶ τὴν Ἀργείαν, Εὐριπίδας δὲ τοὺς Αἰτωλοὺς ἔχων ἐξώδευσε, βουλόμενος κατασῦραι τὴν τῶν Τριταιέων χώραν. οἱ δὲ περὶ Λύκον καὶ Δημόδοκον τὸν τῶν Ἀχαιῶν ἱππάρχην συνέντες τὴν ἐκ τῆς Ἤλιδος τῶν Αἰτωλῶν ἔξοδον, ἐπισυναγαγόντες τοὺς Δυμαίους καὶ τοὺς Πατρεῖς καὶ Φαραιεῖς, σὺν δὲ τούτοις ἔχοντες τοὺς μισθοφόρους, ἐνέβαλον εἰς τὴν Ἠλείαν. παραγενόμενοι δ’ ἐπὶ τὸ Φύξιον καλούμενον τοὺς μὲν εὐζώνους καὶ τοὺς ἱππεῖς ἐφῆκαν εἰς τὴν καταδρομήν, τὰ δὲ βαρέα τῶν ὅπλων ἔκρυψαν περὶ τὸν προειρημένον τόπον. ἐκβοηθησάντων δὲ πανδημεὶ τῶν Ἠλείων ἐπὶ τοὺς κατατρέχοντας καὶ προσκειμένων τοῖς ἀποχωροῦσιν, ἐξαναστάντες οἱ περὶ τὸν Λύκον ἐπέθεντο τοῖς προπεπτωκόσι. τῶν δ’ Ἠλείων οὐ δεξαμένων τὴν ὁρμήν, ἀλλ’ ἐξ ἐπιφανείας τραπέντων, ἀπέκτειναν μὲν αὐτῶν εἰς διακοσίους, ζωγρίᾳ δ’ ἔλαβον ὀγδοήκοντα, συνεκόμισαν δὲ καὶ τὴν περιελαθεῖσαν λείαν ἀσφαλῶς. ἅμα δὲ τούτοις ὁ ναύαρχος τῶν Ἀχαιῶν ποιησάμενος ἀποβάσεις πλεονάκις εἴς τε τὴν Καλυδωνίαν καὶ Ναυπακτίαν τήν τε χώραν κατέσυρε καὶ τὴν βοήθειαν αὐτῶν συνέτριψε δίς. ἔλαβε δὲ καὶ Κλεόνικον τὸν Ναυπάκτιον, ὃς διὰ τὸ πρόξενος ὑπάρχειν τῶν Ἀχαιῶν παραυτὰ μὲν οὐκ ἐπράθη, μετὰ δέ τινα χρόνον ἀφείθη χωρὶς λύτρων.", "st": "5.95"}, {"sp": "N", "t": "κατὰ δὲ τοὺς αὐτοὺς χρόνους Ἀγήτας ὁ τῶν Αἰτωλῶν στρατηγὸς συναγαγὼν πανδημεὶ τοὺς Αἰτωλοὺς ἐλεηλάτησε μὲν τὴν τῶν Ἀκαρνάνων χώραν, ἐπεπορεύθη δὲ πορθῶν πᾶσαν ἀδεῶς τὴν Ἤπειρον. οὗτος μὲν οὖν ταῦτα πράξας ἐπανελθὼν διαφῆκε τοὺς Αἰτωλοὺς ἐπὶ τὰς πόλεις. οἱ δ’ Ἀκαρνᾶνες ἀντεμβαλόντες εἰς τὴν Στρατικὴν καὶ πανικῷ περιπεσόντες αἰσχρῶς μέν, ἀβλαβῶς γε μὴν ἐπανῆλθον, οὐ τολμησάντων αὐτοὺς ἐπιδιῶξαι τῶν ἐκ τοῦ Στράτου διὰ τὸ νομίζειν ἐνέδρας ἕνεκα ποιεῖσθαι τὴν ἀποχώρησιν. ἐγένετο δὲ καὶ περὶ Φανοτεῖς παλιμπροδοσία τοιόνδε τινὰ τρόπον. Ἀλέξανδρος ὁ τεταγμένος ἐπὶ τῆς Φωκίδος ὑπὸ Φιλίππου συνεστήσατο πρᾶξιν ἐπὶ τοὺς Αἰτωλοὺς διά τινος Ἰάσονος, ὃς ἐτύγχανεν ὑπ’ αὐτοῦ τεταγμένος ἐπὶ τῆς τῶν Φανοτέων πόλεως· ὃς διαπεμψάμενος πρὸς Ἀγήταν τὸν τῶν Αἰτωλῶν στρατηγὸν ὡμολόγησε τὴν ἄκραν αὐτοῖς παραδώσειν τὴν ἐν τοῖς Φανοτεῦσι, καὶ περὶ τούτων ὅρκους ἐποιήσατο καὶ συνθήκας. παραγενομένης δὲ τῆς ταχθείσης ἡμέρας ὁ μὲν Ἀγήτας ἧκεν ἔχων τοὺς Αἰτωλοὺς νυκτὸς πρὸς τοὺς Φανοτεῖς, καὶ τοὺς μὲν λοιποὺς ἐν ἀποστήματι κρύψας ἔμεινε, τοὺς δ’ ἐπιτηδειοτάτους ἑκατὸν ἐπιλέξας ἀπέστειλε πρὸς τὴν ἄκραν, ὁ δ’ Ἰάσων τὸν μὲν Ἀλέξανδρον ἕτοιμον εἶχε μετὰ στρατιωτῶν ἐν τῇ πόλει, τοὺς δὲ νεανίσκους παραλαβὼν κατὰ τοὺς ὅρκους εἰσήγαγε πάντας εἰς τὴν ἀκρόπολιν. τῶν δὲ περὶ τὸν Ἀλέξανδρον εὐθέως ἐπεισπεσόντων, οἱ μὲν ἐπίλεκτοι τῶν Αἰτωλῶν ἑάλωσαν, ὁ δ’ Ἀγήτας ἐπιγενομένης τῆς ἡμέρας συνεὶς τὸ γεγονὸς αὖτις ἐπανῆγε τὴν δύναμιν, οὐκ ἀνοικείῳ πράγματι περιπεπτωκὼς τοῖς πολλάκις ὑφ’ αὑτοῦ πραττομένοις.", "st": "5.96"}, {"sp": "N", "t": "κατὰ δὲ τοὺς αὐτοὺς καιροὺς Φίλιππος ὁ βασιλεὺς κατελάβετο Βυλάζωρα, μεγίστην οὖσαν πόλιν τῆς Παιονίας καὶ λίαν εὐκαίρως κειμένην πρὸς τὰς εἰσβολὰς τὰς ἀπὸ τῆς Δαρδανικῆς εἰς Μακεδονίαν, ὥστε διὰ τῆς πράξεως ταύτης σχεδὸν ἀπολελύσθαι τοῦ φόβου τοῦ κατὰ Δαρδανίους· οὐ γὰρ ἔτι ῥᾴδιον ἦν αὐτοῖς ἐμβαλεῖν εἰς Μακεδονίαν κρατοῦντος Φιλίππου τῶν εἰσόδων διὰ τῆς προειρημένης πόλεως. ἀσφαλισάμενος δὲ ταύτην Χρυσόγονον μὲν ἐξαπέστειλε κατὰ σπουδὴν ἐπισυνάξοντα τοὺς ἄνω Μακεδόνας, αὐτὸς δὲ παραλαβὼν τοὺς ἐκ τῆς Βοττίας καὶ τῆς Ἀμφαξίτιδος ἧκεν ἔχων εἰς Ἔδεσσαν. προσδεξάμενος δ’ ἐνταῦθα τοὺς μετὰ Χρυσογόνου Μακεδόνας ἐξώρμησε μετὰ πάσης τῆς δυνάμεως, καὶ παρῆν ἑκταῖος εἰς Λάρισαν. κατὰ δὲ τὸ συνεχὲς ἐνεργῷ νυκτοπορίᾳ χρησάμενος ὑπὸ τὴν ἑωθινὴν ἧκε πρὸς Μελίτειαν, καὶ προσθεὶς τὰς κλιμακίδας τοῖς τείχεσι κατεπείραζε τῆς πόλεως. τῷ μὲν οὖν αἰφνιδίῳ καὶ παραδόξῳ κατεπλήξατο τοὺς Μελιταιεῖς, ὥστε ῥᾳδίως ἂν κρατῆσαι τῆς πόλεως· τῷ δὲ παρὰ πολὺ γενέσθαι τὰς κλίμακας ἐλάττους τῆς χρείας διεψεύσθη τῆς πράξεως.", "st": "5.97"}, {"sp": "N", "t": "ἐν ᾧ δὴ γένει μάλιστ’ ἄν τις ἐπιτιμήσειε τοῖς ἡγουμένοις. εἴτε γάρ τινες μηδεμίαν πρόνοιαν ποιησάμενοι μηδ’ ἐκμετρησάμενοι τείχη, κρημνούς, ἕτερα τῶν τοιούτων, δι’ ὧν ἐπιβάλλονται ποιεῖσθαι τὴν εἴσοδον, αὐτόθεν ἀσκέπτως παραγίνονται πόλιν καταληψόμενοι, τίς οὐκ ἂν τοῖς τοιούτοις ἐπιτιμήσειεν; εἴτ’ ἐκμετρησάμενοι τὸ καθ’ αὑτούς, κἄπειτα τὴν κατασκευὴν τῶν κλιμάκων καὶ καθόλου τῶν τοιούτων ὀργάνων, ἃ μικρὰν ἔχοντα τὴν ἀσχολίαν ἐν μεγάλῳ δίδωσι τὴν αὑτῶν πεῖραν, εἰκῇ καὶ τοῖς τυχοῦσιν ἀνθρώποις ἐγχειρίζουσι, πῶς οὐκ ἄξιον ἐγκαλεῖν; οὐ γὰρ ἔστιν ἐπὶ τῶν τοιούτων πράξεων ἢ ποιῆσαί τι τῶν δεόντων ἢ μηδὲν παθεῖν δεινόν, ἀλλ’ ἅμα ταῖς ἀποτυχίαις ἕπεται βλάβη κατὰ πολλοὺς τρόπους, κατ’ αὐτὸν μὲν τὸν τοῦ πράττειν καιρὸν κίνδυνος περὶ τοὺς ἀρίστους τῶν ἀνδρῶν, ἔτι δὲ μᾶλλον κατὰ τὰς ἀπολύσεις, ὅταν ἅπαξ καταφρονηθῶσι. πολλὰ δὲ καὶ λίαν τῶν τοιούτων ἐστὶ παραδείγματα· πλείους γὰρ ἂν εὕροι τις τῶν ἀποτυγχανόντων ἐν ταῖς τοιαύταις ἐπιβολαῖς τοὺς μὲν ἀπολωλότας, τοὺς δ’ εἰς τὸν ἔσχατον παραγεγονότας κίνδυνον, τῶν ἀβλαβῶς ἀπολελυμένων. πρός γε μὴν τὸ μέλλον ὁμολογουμένως ἀπιστίας καὶ μῖσος ἐξεργάζονται καθ’ αὑτῶν, ἔτι δὲ φυλακὴν παραγγέλλουσι πᾶσιν· οὐ γὰρ μόνον τοῖς παθοῦσιν, ἀλλὰ καὶ τοῖς συνεῖσι τὸ γεγονὸς τρόπον τινὰ παράγγελμα δίδοται προσέχειν αὑτοῖς καὶ φυλάττεσθαι. διόπερ οὐδέποτε ταῖς τοιαύταις ἐπινοίαις εἰκῇ χρηστέον τοὺς ἐπὶ πραγμάτων ταττομένους. ὁ δὲ τρόπος τῆς ἐκμετρήσεως καὶ κατασκευῆς τῶν τοιούτων εὐχερὴς καὶ ἀδιάπτωτος, ἐὰν λαμβάνηται μεθοδικῶς. νῦν μὲν οὖν τὸ συνεχὲς τῆς διηγήσεως ἀποδοτέον· περὶ δὲ τοῦ τοιούτου γένους πάλιν μεταλαβόντες ἁρμόζοντα καιρὸν καὶ τόπον κατὰ τὴν πραγματείαν πειρασόμεθα συνυποδεικνύειν πῶς ἄν τις ἥκιστα περὶ τὰς τοιαύτας ἐπιβολὰς ἁμαρτάνοι.", "st": "5.98"}, {"sp": "N", "t": "ὁ δὲ Φίλιππος διαψευσθεὶς τῆς πράξεως, καὶ καταστρατοπεδεύσας περὶ τὸν Ἐνιπέα ποταμόν, συνῆγε τὰς παρασκευὰς ἔκ τε τῆς Λαρίσης καὶ τῶν ἄλλων πόλεων, ἃς ἐπεποίητο κατὰ χειμῶνα πρὸς τὴν πολιορκίαν· ἡ γὰρ ὅλη πρόθεσις ἦν αὐτῷ τῆς στρατείας ἐξελεῖν τὰς Φθιώτιδας καλουμένας Θήβας. ἡ δὲ πόλις αὕτη κεῖται μὲν οὐ μακρὰν ἀπὸ τῆς θαλάττης, ἀπέχουσα Λαρίσης ὡς τριακοσίους σταδίους, ἐπίκειται δ’ εὐκαίρως τῇ τε Μαγνησίᾳ καὶ τῇ Θετταλίᾳ, καὶ μάλιστα τῆς μὲν Μαγνησίας τῇ τῶν Δημητριέων χώρᾳ, τῆς δὲ Θετταλίας τῇ τῶν Φαρσαλίων καὶ Φεραίων. ἐξ ἧς καὶ τότε, κατεχόντων αὐτὴν τῶν Αἰτωλῶν καὶ συνεχεῖς ποιουμένων τὰς ἐπιδρομάς, μεγάλα συνέβαινε βλάπτεσθαι τούς τε Δημητριεῖς καὶ τοὺς Φαρσαλίους, ἔτι δὲ Λαρισαίους· πολλάκις γὰρ ἐποιοῦντο τὰς καταδρομὰς ἕως ἐπὶ τὸ καλούμενον Ἀμυρικὸν πεδίον. διόπερ ὁ Φίλιππος οὐκ ἐν μικρῷ τιθέμενος μεγάλην ἐποιεῖτο σπουδὴν ὑπὲρ τοῦ κατὰ κράτος ἐξελεῖν αὐτήν. συναχθέντων δὲ καταπελτῶν μὲν ἑκατὸν πεντήκοντα, πετροβολικῶν δ’ ὀργάνων πέντε καὶ εἴκοσι, προσῆλθε ταῖς Θήβαις, καὶ διελὼν τὸ στρατόπεδον εἰς τρία μέρη διέλαβε τοὺς πέριξ τόπους τῆς πόλεως, καὶ τῷ μὲν ἑνὶ περὶ τὸ Σκόπιον ἐστρατοπέδευσε, τῷ δ’ ἄλλῳ περὶ τὸ καλούμενον Ἡλιοτρόπιον, τὸ δὲ τρίτον εἶχε κατὰ τὸ τῆς πόλεως ὑπερκείμενον ὄρος, τὰ δὲ μεταξὺ τῶν στρατοπέδων τάφρῳ καὶ διπλῷ χάρακι διαλαβὼν ὠχυρώσατο, πρὸς δὲ καὶ πύργοις ξυλίνοις ἠσφαλίσατο, κατὰ πλέθρον στήσας αὐτοὺς μετὰ φυλακῆς τῆς ἀρκούσης. ἑξῆς δὲ τούτοις τὰς παρασκευὰς ἁθροίσας ὁμοῦ πάσας ἤρξατο προσάγειν τὰ μηχανήματα πρὸς τὴν ἄκραν.", "st": "5.99"}, {"sp": "N", "t": "ἐπὶ μὲν οὖν ἡμέρας τρεῖς τὰς πρώτας οὐδὲν ἠδύνατο προβιβάζειν τῶν ἔργων διὰ τὸ γενναίως καὶ παραβόλως ἀμύνεσθαι τοὺς ἐκ τῆς πόλεως. ἐπειδὴ δὲ διὰ τὴν συνέχειαν τῶν ἀκροβολισμῶν καὶ τὸ πλῆθος τῶν βελῶν οἱ προκινδυνεύοντες τῶν ἐκ τῆς πόλεως οἱ μὲν ἔπεσον, οἱ δὲ κατετραυματίσθησαν, τότε βραχείας ἐνδόσεως γενομένης ἤρξαντο τῶν ὀρυγμάτων οἱ Μακεδόνες. τῇ δὲ συνεχείᾳ, καίπερ ἀντιβαίνοντος τοῦ χωρίου, μόλις ἐναταῖοι πρὸς τὸ τεῖχος ἐξίκοντο. μετὰ δὲ ταῦτα ποιούμενοι τὴν ἐργασίαν ἐκ διαδοχῆς, ὥστε μήθ’ ἡμέρας μήτε νυκτὸς διαλείπειν, ἐν τρισὶν ἡμέραις δύο πλέθρα τοῦ τείχους ὑπώρυξαν καὶ διεστύλωσαν. τῶν δ’ ἐρεισμάτων οὐ δυναμένων ὑποφέρειν τὸ βάρος, ἀλλ’ ἐνδόντων, πεσεῖν συνέβη τὸ τεῖχος πρὸ τοῦ πῦρ ἐμβαλεῖν τοὺς Μακεδόνας. ἐνεργὸν δὲ ποιησαμένων τὴν ἀνακάθαρσιν τοῦ πτώματος, καὶ παρασκευασαμένων πρὸς τὴν εἴσοδον καὶ μελλόντων ἤδη βιάζεσθαι, καταπλαγέντες παρέδοσαν οἱ Θηβαῖοι τὴν πόλιν. ὁ δὲ Φίλιππος διὰ τῆς πράξεως ταύτης ἀσφαλισάμενος τὰ κατὰ τὴν Μαγνησίαν καὶ Θετταλίαν ἀφείλετο τὰς μεγάλας ὠφελείας τῶν Αἰτωλῶν, ἀπεδείξατο δὲ καὶ ταῖς αὑτοῦ δυνάμεσιν ὅτι δικαίως ἐπανείλετο τοὺς περὶ τὸν Λεόντιον, ἐθελοκακήσαντας πρότερον ἐν τῇ περὶ τοὺς Παλαιεῖς πολιορκίᾳ. γενόμενος δὲ κύριος τῶν Θηβῶν τοὺς μὲν ὑπάρχοντας οἰκήτορας ἐξηνδραποδίσατο, Μακεδόνας δ’ εἰσοικίσας Φιλίππου τὴν πόλιν ἀντὶ Θηβῶν κατωνόμασεν. ἤδη δ’ αὐτοῦ συντετελεσμένου τὰ κατὰ τὰς Θήβας, πάλιν ἧκον ὑπὲρ τῶν διαλύσεων παρά τε Χίων καὶ Ῥοδίων καὶ Βυζαντίων πρέσβεις καὶ παρὰ Πτολεμαίου τοῦ βασιλέως· οἷς παραπλησίους ἀποκρίσεις δοὺς ταῖς πρότερον, καὶ φήσας οὐκ ἀλλότριος εἶναι διαλύσεως, ἔπεμψε κελεύσας αὐτοὺς πεῖραν λαμβάνειν καὶ τῶν Αἰτωλῶν. αὐτὸς δὲ τῆς μὲν διαλύσεως ὠλιγώρει, τοῦ δὲ πράττειν τι τῶν ἑξῆς ἀντείχετο.", "st": "5.100"}, {"sp": "N", "t": "διόπερ ἀκούων τοὺς Σκερδιλαΐδου λέμβους περὶ Μαλέαν λῄζεσθαι καὶ πᾶσι τοῖς ἐμπόροις ὡς πολεμίοις χρῆσθαι, παρεσπονδηκέναι δὲ καὶ τῶν ἰδίων τινὰ πλοίων ἐν Λευκάδι συνορμήσαντα, καταρτίσας δώδεκα μὲν καταφράκτους ναῦς, ὀκτὼ δ’ ἀφράκτους, τριάκοντα δ’ ἡμιολίους, ἔπλει δι’ Εὐρίπου, σπεύδων μὲν καταλαβεῖν καὶ τοὺς Ἰλλυριούς, καθόλου δὲ μετέωρος ὢν ταῖς ἐπιβολαῖς ἐπὶ τὸν κατὰ τῶν Αἰτωλῶν πόλεμον διὰ τὸ μηδέν πω συνεικέναι τῶν ἐν Ἰταλίᾳ γεγονότων. συνέβαινε δέ, καθ’ οὓς καιροὺς ἐπολιόρκει τὰς Θήβας Φίλιππος, ἡττῆσθαι Ῥωμαίους ὑπ’ Ἀννίβου τῇ περὶ Τυρρηνίαν μάχῃ, τὴν δὲ φήμην ὑπὲρ τῶν γεγονότων μηδέπω προσπεπτωκέναι τοῖς Ἕλλησιν. ὁ δὲ Φίλιππος, τῶν λέμβων ὑστερήσας καὶ καθορμισθεὶς πρὸς Κεγχρεαῖς τὰς μὲν καταφράκτους ναῦς ἐξαπέστειλε, συντάξας περὶ Μαλέαν ποιεῖσθαι τὸν πλοῦν ὡς ἐπ’ Αἰγίου καὶ Πατρῶν, τὰ δὲ λοιπὰ τῶν πλοίων ὑπερισθμίσας ἐν Λεχαίῳ παρήγγελλε πᾶσιν ὁρμεῖν. αὐτὸς δὲ κατὰ σπουδὴν ἧκε μετὰ φίλων ἐπὶ τὴν τῶν Νεμέων πανήγυριν εἰς Ἄργος. ἄρτι δ’ αὐτοῦ θεωμένου τὸν ἀγῶνα τὸν γυμνικόν, παρῆν ἐκ Μακεδονίας γραμματοφόρος διασαφῶν ὅτι λείπονται Ῥωμαῖοι μάχῃ μεγάλῃ καὶ κρατεῖ τῶν ὑπαίθρων Ἀννίβας. παραυτίκα μὲν οὖν Δημητρίῳ τῷ Φαρίῳ μόνῳ τὴν ἐπιστολὴν ἐπέδειξε, σιωπᾶν παρακελευσάμενος· ὃς καὶ λαβόμενος τῆς ἀφορμῆς ταύτης τὸν μὲν πρὸς τοὺς Αἰτωλοὺς ᾤετο δεῖν τὴν ταχίστην ἀπορρῖψαι πόλεμον, ἀντέχεσθαι δὲ τῶν κατὰ τὴν Ἰλλυρίδα πραγμάτων ἠξίου καὶ τῆς εἰς Ἰταλίαν διαβάσεως. τὰ μὲν γὰρ κατὰ τὴν Ἑλλάδα πάντα καὶ νῦν ἤδη ποιεῖν αὐτῷ τὸ προσταττόμενον ἔφη καὶ μετὰ ταῦτα ποιήσειν, Ἀχαιῶν μὲν ἐθελοντὴν εὐνοούντων, Αἰτωλῶν δὲ καταπεπληγμένων ἐκ τῶν συμβεβηκότων αὐτοῖς κατὰ τὸν ἐνεστῶτα πόλεμον· τὴν δ’ Ἰταλίαν ἔφη καὶ τὴν ἐκεῖ διάβασιν ἀρχὴν εἶναι τῆς ὑπὲρ τῶν ὅλων ἐπιβολῆς, ἣν οὐδενὶ καθήκειν μᾶλλον ἢ ’κείνῳ τὸν δὲ καιρὸν εἶναι νῦν, ἐπταικότων Ῥωμαίων.", "st": "5.101"}, {"sp": "N", "t": "τοιούτοις δὲ χρησάμενος λόγοις ταχέως παρώρμησε τὸν Φίλιππον, ὡς ἄν, οἶμαι, καὶ νέον βασιλέα καὶ κατὰ τὰς πράξεις ἐπιτυχῆ καὶ καθόλου τολμηρὸν εἶναι δοκοῦντα, πρὸς δὲ τούτοις ἐξ οἰκίας ὁρμώμενον τοιαύτης, ἣ μάλιστά πως ἀεὶ τῆς τῶν ὅλων ἐλπίδος ἐφίεται. πλὴν ὅ γε Φίλιππος, ὡς εἶπον, τότε μὲν αὐτῷ τῷ Δημητρίῳ τὰ προσπεπτωκότα διὰ τῆς ἐπιστολῆς ἐδήλωσε, μετὰ δὲ ταῦτα συνῆγε τοὺς φίλους καὶ διαβούλιον ἀνεδίδου περὶ τῆς πρὸς Αἰτωλοὺς διαλύσεως. ὄντων δὲ καὶ τῶν περὶ τὸν Ἄρατον οὐκ ἀλλοτρίων διεξαγωγῆς τῷ δοκεῖν ὑπερδεξίους ὄντας τῷ πολέμῳ ποιεῖσθαι τὴν διάλυσιν, οὕτως ὁ βασιλεύς, οὐδὲ τοὺς πρεσβευτὰς ἔτι προσδεξάμενος τοὺς κοινῇ πράττοντας τὰ περὶ τὰς διαλύσεις, παραχρῆμα Κλεόνικον μὲν τὸν Ναυπάκτιον πρὸς τοὺς Αἰτωλοὺς διεπέμψατο — κατέλαβε γὰρ ἔτι τοῦτον ἐκ τῆς αἰχμαλωσίας ἐπιμένοντα τὴν τῶν Ἀχαιῶν σύνοδον — αὐτὸς δὲ παραλαβὼν ἐκ Κορίνθου τὰς ναῦς καὶ τὴν πεζὴν δύναμιν ἧκεν ἔχων εἰς Αἴγιον. καὶ προελθὼν ἐπὶ Λασιῶνα καὶ τὸν ἐν τοῖς Περιππίοις πύργον παραλαβών, καὶ συνυποκριθεὶς ὡς ἐμβαλῶν εἰς τὴν Ἠλείαν, τοῦ μὴ δοκεῖν λίαν ἕτοιμος εἶναι πρὸς τὴν τοῦ πολέμου κατάλυσιν, μετὰ ταῦτα δὶς ἢ τρὶς ἀνακάμψαντος τοῦ Κλεονίκου, δεομένων τῶν Αἰτωλῶν εἰς λόγους σφίσι συνελθεῖν ἐπήκουσε, καὶ πάντ’ ἀφεὶς τὰ τοῦ πολέμου πρὸς μὲν τὰς συμμαχίδας πόλεις γραμματοφόρους ἐξαπέστειλε, παρακαλῶν πέμπειν τοὺς συνεδρεύσοντας καὶ μεθέξοντας τῆς ὑπὲρ τῶν διαλύσεων κοινολογίας, αὐτὸς δὲ διαβὰς μετὰ τῆς δυνάμεως καὶ καταστρατοπεδεύσας περὶ Πάνορμον, ὃς ἔστι μὲν τῆς Πελοποννήσου λιμήν, κεῖται δὲ καταντικρὺ τῆς τῶν Ναυπακτίων πόλεως, ἀνέμενε τοὺς τῶν συμμάχων συνέδρους. κατὰ δὲ τὸν καιρὸν τοῦτον, καθ’ ὃν ἔδει συναθροίζεσθαι τοὺς προειρημένους, πλεύσας εἰς Ζάκυνθον δι’ αὑτοῦ κατεστήσατο τὰ κατὰ τὴν νῆσον, καὶ παρῆν αὖθις ἀναπλέων.", "st": "5.102"}, {"sp": "N", "t": "ἤδη δὲ καὶ τῶν συνέδρων ἡθροισμένων, ἐξέπεμψε πρὸς τοὺς Αἰτωλοὺς Ἄρατον καὶ Ταυρίωνα καί τινας τῶν ἡκόντων ἅμα τούτοις. οἳ καὶ συμμίξαντες τοῖς Αἰτωλοῖς πανδημεὶ συνηθροισμένοις ἐν Ναυπάκτῳ, βραχέα διαλεχθέντες καὶ θεωροῦντες αὐτῶν τὴν ὁρμὴν τὴν πρὸς τὰς διαλύσεις, ἔπλεον ἐξ ὑποστροφῆς πρὸς τὸν Φίλιππον χάριν τοῦ διασαφῆσαι περὶ τούτων. οἱ δ’ Αἰτωλοί, σπεύδοντες διαλύσασθαι τὸν πόλεμον, ἐξαπέστελλον ἅμα τούτοις πρέσβεις πρὸς τὸν Φίλιππον, ἀξιοῦντες παραγενέσθαι μετὰ τῆς δυνάμεως πρὸς σφᾶς, ἵνα τῆς κοινολογίας ἐκ χειρὸς γινομένης τύχῃ τὰ πράγματα τῆς ἁρμοζούσης διεξαγωγῆς. ὁ δὲ βασιλεὺς παρορμηθεὶς τοῖς παρακαλουμένοις διέπλευσε μετὰ τῆς δυνάμεως πρὸς τὰ λεγόμενα Κοῖλα τῆς Ναυπακτίας, ἃ τῆς πόλεως εἴκοσι μάλιστα σταδίους ἀφέστηκε· στρατοπεδεύσας δὲ καὶ περιλαβὼν χάρακι τὰς νῆας καὶ τὴν παρεμβολήν, ἔμενε προσανέχων τὸν καιρὸν τῆς ἐντεύξεως. οἱ δ’ Αἰτωλοὶ χωρὶς τῶν ὅπλων ἧκον πανδημεί, καὶ διασχόντες ὡς δύο στάδια τῆς Φιλίππου παρεμβολῆς διεπέμποντο καὶ διελέγοντο περὶ τῶν ἐνεστώτων. τὸ μὲν οὖν πρῶτον ὁ βασιλεὺς πάντας ἐξέπεμπε τοὺς ἥκοντας παρὰ τῶν συμμάχων, κελεύσας ἐπὶ τούτοις προτείνειν τὴν εἰρήνην τοῖς Αἰτωλοῖς, ὥστ’ ἔχειν ἀμφοτέρους ἃ νῦν ἔχουσι· δεξαμένων δὲ τῶν Αἰτωλῶν ἑτοίμως, τὸ λοιπὸν ἤδη περὶ τῶν κατὰ μέρος συνεχεῖς ἐγίνοντο διαποστολαὶ πρὸς ἀλλήλους, ὧν τὰς μὲν πλείους παρήσομεν διὰ τὸ μηδὲν ἔχειν ἄξιον μνήμης, τῆς δ’ Ἀγελάου τοῦ Ναυπακτίου παραινέσεως ποιησόμεθα μνήμην, ᾗ κατὰ τὴν πρώτην ἔντευξιν ἐχρήσατο πρός τε τὸν βασιλέα καὶ τοὺς παρόντας συμμάχους.", "st": "5.103"}, {"sp": "N", "t": "ὃς ἔφη δεῖν μάλιστα μὲν μηδέποτε πολεμεῖν τοὺς Ἕλληνας ἀλλήλοις, ἀλλὰ μεγάλην χάριν ἔχειν τοῖς θεοῖς, εἰ λέγοντες ἓν καὶ ταὐτὸ πάντες καὶ συμπλέκοντες τὰς χεῖρας, καθάπερ οἱ τοὺς ποταμοὺς διαβαίνοντες, δύναιντο τὰς τῶν βαρβάρων ἐφόδους ἀποτριβόμενοι συσσῴζειν σφᾶς αὐτοὺς καὶ τὰς πόλεις. οὐ μὴν ἀλλ’ εἰ τὸ παράπαν τοῦτο μὴ δυνατόν, κατά γε τὸ παρὸν ἠξίου συμφρονεῖν καὶ φυλάττεσθαι, προϊδομένους τὸ βάρος τῶν στρατοπέδων καὶ τὸ μέγεθος τοῦ συνεστῶτος πρὸς ταῖς δύσεσι πολέμου· δῆλον γὰρ εἶναι παντὶ τῷ καὶ μετρίως περὶ τὰ κοινὰ σπουδάζοντι καὶ νῦν, ὡς ἐάν τε Καρχηδόνιοι Ῥωμαίων ἐάν τε Ῥωμαῖοι Καρχηδονίων περιγένωνται τῷ πολέμῳ, διότι κατ’ οὐδένα τρόπον εἰκός ἐστι τοὺς κρατήσαντας ἐπὶ ταῖς Ἰταλιωτῶν καὶ Σικελιωτῶν μεῖναι δυναστείαις, ἥξειν δὲ καὶ διατείνειν τὰς ἐπιβολὰς καὶ δυνάμεις αὑτῶν πέρα τοῦ δέοντος. διόπερ ἠξίου πάντας μὲν φυλάξασθαι τὸν καιρόν, μάλιστα δὲ Φίλιππον. εἶναι δὲ φυλακήν, ἐὰν ἀφέμενος τοῦ καταφθείρειν τοὺς Ἕλληνας καὶ ποιεῖν εὐχειρώτους τοῖς ἐπιβαλλομένοις κατὰ τοὐναντίον ὡς ὑπὲρ ἰδίου σώματος βουλεύηται, καὶ καθόλου πάντων. τῶν τῆς Ἑλλάδος μερῶν ὡς οἰκείων καὶ προσηκόντων αὑτῷ ποιῆται πρόνοιαν· τοῦτον γὰρ τὸν τρόπον χρωμένου τοῖς πράγμασι τοὺς μὲν Ἕλληνας εὔνους ὑπάρχειν αὐτῷ καὶ βεβαίους συναγωνιστὰς πρὸς τὰς ἐπιβολάς, τοὺς δ’ ἔξωθεν ἧττον ἐπιβουλεύσειν αὐτοῦ τῇ δυναστείᾳ, καταπεπληγμένους τὴν τῶν Ἑλλήνων πρὸς αὐτὸν πίστιν. εἰ δὲ πραγμάτων ὀρέγεται, πρὸς τὰς δύσεις βλέπειν αὐτὸν ἠξίου καὶ τοῖς ἐν Ἰταλίᾳ συνεστῶσι πολέμοις προσέχειν τὸν νοῦν, ἵνα γενόμενος ἔφεδρος ἔμφρων πειραθῇ σὺν καιρῷ τῆς τῶν ὅλων ἀντιποιήσασθαι δυναστείας. εἶναι δὲ τὸν ἐνεστῶτα καιρὸν οὐκ ἀλλότριον τῆς ἐλπίδος ταύτης. τὰς δὲ πρὸς τοὺς Ἕλληνας διαφορὰς καὶ τοὺς πολέμους εἰς τὰς ἀναπαύσεις αὐτὸν ὑπερτίθεσθαι παρεκάλει, καὶ μάλιστα σπουδάζειν περὶ τούτου τοῦ μέρους, ἵν’ ἔχῃ τὴν ἐξουσίαν, ὅταν βούληται, καὶ διαλύεσθαι καὶ πολεμεῖν πρὸς αὐτούς· ὡς ἐὰν ἅπαξ τὰ προφαινόμενα νῦν ἀπὸ τῆς ἑσπέρας νέφη προσδέξηται τοῖς κατὰ τὴν Ἑλλάδα τόποις ἐπιστῆναι, καὶ λίαν ἀγωνιᾶν ἔφη μὴ τὰς ἀνοχὰς καὶ τοὺς πολέμους καὶ καθόλου τὰς παιδιάς, ἃς νῦν παίζομεν πρὸς ἀλλήλους, ἐκκοπῆναι συμβῇ πάντων ἡμῶν ἐπὶ τοσοῦτον ὥστε κἂν εὔξασθαι τοῖς θεοῖς ὑπάρχειν ἡμῖν τὴν ἐξουσίαν ταύτην, καὶ πολεμεῖν ὅταν βουλώμεθα καὶ διαλύεσθαι πρὸς ἀλλήλους, καὶ καθόλου κυρίους εἶναι τῶν ἐν αὑτοῖς ἀμφισβητουμένων.", "st": "5.104"}, {"sp": "N", "t": "ὁ μὲν οὖν Ἀγέλαος τοιαῦτα διαλεχθεὶς πάντας μὲν παρώρμησε τοὺς συμμάχους πρὸς τὰς διαλύσεις, μάλιστα δὲ τὸν Φίλιππον, οἰκείοις χρησάμενος λόγοις πρὸς τὴν ὁρμὴν αὐτοῦ τὴν ἤδη προκατεσκευασμένην ὑπὸ τῶν τοῦ Δημητρίου παραινέσεων. διόπερ ἀνθομολογησάμενοι πρὸς σφᾶς ὑπὲρ τῶν κατὰ μέρος, καὶ κυρώσαντες τὰς διαλύσεις, ἐχωρίσθησαν, κατάγοντες εἰς τὰς οἰκείας ἕκαστοι πατρίδας εἰρήνην ἀντὶ πολέμου. ταῦτα δὲ πάντα συνέβη γενέσθαι κατὰ τὸν τρίτον ἐνιαυτὸν τῆς ἑκατοστῆς καὶ τετταρακοστῆς ὀλυμπιάδος, λέγω δὲ τὴν τῶν Ῥωμαίων περὶ Τυρρηνίαν μάχην καὶ τὴν Ἀντιόχου περὶ Κοίλην Συρίαν, ἔτι δὲ τὰς Ἀχαιῶν καὶ Φιλίππου πρὸς Αἰτωλοὺς διαλύσεις. τὰς μὲν οὖν Ἑλληνικὰς καὶ τὰς Ἰταλικάς, ἔτι δὲ τὰς Λιβυκὰς πράξεις, οὗτος ὁ καιρὸς καὶ τοῦτο τὸ διαβούλιον συνέπλεξε πρῶτον· οὐ γὰρ ἔτι Φίλιππος οὐδ’ οἱ τῶν Ἑλλήνων προεστῶτες ἄρχοντες πρὸς τὰς κατὰ τὴν Ἑλλάδα πράξεις ποιούμενοι τὰς ἀναφορὰς οὔτε τοὺς πολέμους οὔτε τὰς διαλύσεις ἐποιοῦντο πρὸς ἀλλήλους, ἀλλ’ ἤδη πάντες πρὸς τοὺς ἐν Ἰταλίᾳ σκοποὺς ἀπέβλεπον. ταχέως δὲ καὶ πρὸς τοὺς νησιώτας καὶ τοὺς τὴν Ἀσίαν κατοικοῦντας τὸ παραπλήσιον συνέβη γενέσθαι· καὶ γὰρ οἱ Φιλίππῳ δυσαρεστούμενοι καί τινες τῶν Ἀττάλῳ διαφερομένων οὐκέτι πρὸς Ἀντίοχον καὶ Πτολεμαῖον οὐδὲ πρὸς μεσημβρίαν καὶ τὰς ἀνατολὰς ἔνευον, ἀλλ’ ἐπὶ τὴν ἑσπέραν ἀπὸ τούτων τῶν καιρῶν ἔβλεπον, καὶ τινὲς μὲν πρὸς Καρχηδονίους, οἱ δὲ πρὸς Ῥωμαίους ἐπρέσβευον, ὁμοίως δὲ καὶ Ῥωμαῖοι πρὸς τοὺς Ἕλληνας, δεδιότες τὴν τοῦ Φιλίππου τόλμαν καὶ προορώμενοι μὴ συνεπίθηται τοῖς τότε περιεστῶσιν αὐτοὺς καιροῖς. ἡμεῖς δ’ ἐπειδὴ κατὰ τὴν ἐξ ἀρχῆς ὑπόσχεσιν σαφῶς, οἶμαι, δεδείχαμεν πότε καὶ πῶς καὶ δι’ ἃς αἰτίας αἱ κατὰ τὴν Ἑλλάδα πράξεις συνεπλάκησαν ταῖς Ἰταλικαῖς καὶ Λιβυκαῖς, λοιπὸν κατὰ τὸ συνεχὲς ποιησάμενοι τὴν διήγησιν ὑπὲρ τῶν Ἑλληνικῶν ἕως εἰς τοὺς καιρούς, ἐν οἷς Ῥωμαῖοι τὴν περὶ Κάνναν μάχην ἡττήθησαν, ἐφ’ ἣν τῶν Ἰταλικῶν πράξεων τὴν καταστροφὴν ἐποιησάμεθα, καὶ ταύτην τὴν βύβλον ἀφοριοῦμεν, ἐξισώσαντες τοῖς προειρημένοις καιροῖς.", "st": "5.105"}, {"sp": "N", "t": "Ἀχαιοὶ μὲν οὖν ὡς θᾶττον ἀπέθεντο τὸν πόλεμον, στρατηγὸν αὑτῶν ἑλόμενοι Τιμόξενον, ἀναχωρήσαντες εἰς τὰ σφέτερα νόμιμα καὶ τὰς διαγωγάς, ἅμ’ Ἀχαιοῖς δ’ [καὶ] αἱ λοιπαὶ πόλεις αἱ κατὰ Πελοπόννησον, ἀνεκτῶντο μὲν τοὺς ἰδίους βίους, ἐθεράπευον δὲ τὴν χώραν, ἀνενεοῦντο δὲ τὰς πατρίους θυσίας καὶ πανηγύρεις καὶ τἄλλα τὰ πρὸς τοὺς θεοὺς παρ’ ἑκάστοις ὑπάρχοντα νόμιμα. σχεδὸν γὰρ ὡς ἂν εἰ λήθην συνέβαινε γεγονέναι παρὰ τοῖς πλείστοις περὶ τὰ τοιαῦτα διὰ τὴν συνέχειαν τῶν προγεγονότων πολέμων. οὐ γὰρ οἶδ’ ὅπως ἀεί ποτε Πελοποννήσιοι, τῶν ἄλλων ἀνθρώπων οἰκειότατα πρὸς τὸν ἥμερον καὶ τὸν ἀνθρώπινον βίον ἔχοντες, ἥκιστα πάντων ἀπολελαύκασιν αὐτοῦ κατά γε τοὺς ἀνώτερον χρόνους, μᾶλλον δέ πως κατὰ τὸν Εὐριπίδην ἦσαν ἀεὶ πρασίμοχθοί τινες καὶ οὔποτε ἥσυχοι δορί. τοῦτο δέ μοι δοκοῦσι πάσχειν εἰκότως· ἅπαντες γὰρ ἡγεμονικοὶ καὶ φιλελεύθεροι ταῖς φύσεσι μάχονται συνεχῶς πρὸς ἀλλήλους, ἀπαραχωρήτως διακείμενοι περὶ τῶν πρωτείων. Ἀθηναῖοι δὲ τῶν ἐκ Μακεδονίας φόβων ἀπελέλυντο καὶ τὴν ἐλευθερίαν ἔχειν ἐδόκουν ἤδη βεβαίως, χρώμενοι δὲ προστάταις Εὐρυκλείδᾳ καὶ Μικίωνι τῶν μὲν ἄλλων Ἑλληνικῶν πράξεων οὐδ’ ὁποίας μετεῖχον, ἀκολουθοῦντες δὲ τῇ τῶν προεστώτων αἱρέσει καὶ ταῖς τούτων ὁρμαῖς εἰς πάντας τοὺς βασιλεῖς ἐξεκέχυντο, καὶ μάλιστα τούτων εἰς Πτολεμαῖον, καὶ πᾶν γένος ὑπέμενον ψηφισμάτων καὶ κηρυγμάτων, βραχύν τινα λόγον ποιούμενοι τοῦ καθήκοντος διὰ τὴν τῶν προεστώτων ἀκρισίαν.", "st": "5.106"}, {"sp": "N", "t": "Πτολεμαίῳ γε μὴν εὐθέως ἀπὸ τούτων τῶν καιρῶν συνέβαινε γίνεσθαι τὸν πρὸς τοὺς Αἰγυπτίους πόλεμον. ὁ γὰρ προειρημένος βασιλεὺς καθοπλίσας τοὺς Αἰγυπτίους ἐπὶ τὸν πρὸς Ἀντίοχον πόλεμον πρὸς μὲν τὸ παρὸν ἐνδεχομένως ἐβουλεύσατο, τοῦ δὲ μέλλοντος ἠστόχησε· φρονηματισθέντες γὰρ ἐκ τοῦ περὶ Ῥαφίαν προτερήματος, οὐκέτι τὸ προσταττόμενον οἷοί τ’ ἦσαν ὑπομένειν, ἀλλ’ ἐζήτουν ἡγεμόνα καὶ πρόσωπον, ὡς ἱκανοὶ βοηθεῖν ὄντες αὑτοῖς. ὃ καὶ τέλος ἐποίησαν οὐ μετὰ πολὺν χρόνον. Ἀντίοχος δὲ μεγάλῃ παρασκευῇ χρησάμενος ἐν τῷ χειμῶνι, μετὰ ταῦτα τῆς θερείας ἐπιγενομένης ὑπερέβαλε τὸν Ταῦρον, καὶ συνθέμενος πρὸς Ἄτταλον τὸν βασιλέα κοινοπραγίαν ἐνίστατο τὸν πρὸς Ἀχαιὸν πόλεμον. Αἰτωλοὶ δὲ παραυτὰ μὲν εὐδοκοῦντες τῇ γενομένῃ διαλύσει πρὸς τοὺς Ἀχαιούς, ὡς ἂν μὴ κατὰ γνώμην αὐτοῖς τοῦ πολέμου προκεχωρηκότος — διὸ καὶ στρατηγὸν Ἀγέλαον εἵλοντο τὸν Ναυπάκτιον, δοκοῦντα πλεῖστα συμβεβλῆσθαι πρὸς τὰς διαλύσεις — οὐδένα χρόνον διαλιπόντες δυσηρέστουν καὶ κατεμέμφοντο τὸν Ἀγέλαον ὡς ὑποτετμημένον πάσας αὐτῶν τὰς ἔξωθεν ὠφελείας καὶ τὰς εἰς τὸ μέλλον ἐλπίδας, διὰ τὸ μὴ πρὸς τινάς, πρὸς πάντας δὲ τοὺς Ἕλληνας πεποιῆσθαι τὴν εἰρήνην. ὁ δὲ προειρημένος ἀνὴρ ὑποφέρων τὴν προειρημένην τοιαύτην ἀλογίαν καὶ μέμψιν παρακατεῖχε τὰς ὁρμὰς αὐτῶν· διὸ καὶ καρτερεῖν οὗτοι μὲν ἠναγκάζοντο παρὰ φύσιν.", "st": "5.107"}, {"sp": "N", "t": "ὁ δὲ βασιλεὺς Φίλιππος, ἀνακομισθεὶς κατὰ θάλατταν ἀπὸ τῶν διαλύσεων εἰς Μακεδονίαν, καὶ καταλαβὼν τὸν Σκερδιλαΐδαν ἐπὶ τῇ προφάσει τῶν προσοφειλομένων χρημάτων, πρὸς ἃ καὶ τὰ περὶ τὴν Λευκάδα πλοῖα παρεσπόνδησε, καὶ τότε τῆς μὲν Πελαγονίας πόλισμα διηρπακότα τὸ προσαγορευόμενον Πισσαῖον, τῆς δὲ Δασσαρήτιδος προσηγμένον πόλεις, τὰς μὲν φόβῳ, τὰς δ’ ἐπαγγελίαις, Ἀντιπάτρειαν, Χρυσονδύωνα, Γερτοῦντα, πολλὴν δὲ καὶ τῆς συνορούσης τούτοις Μακεδονίας ἐπιδεδραμηκότα, παραυτίκα μὲν ὥρμησε μετὰ τῆς δυνάμεως, ὡς ἀνακτήσασθαι σπουδάζων τὰς ἀφεστηκυίας πόλεις, καθόλου δ’ ἔκρινε πολεμεῖν πρὸς τὸν Σκερδιλαΐδαν, νομίζων ἀναγκαιότατον εἶναι παρευτρεπίσασθαι τὰ κατὰ τὴν Ἰλλυρίδα πρός τε τὰς ἄλλας ἐπιβολὰς καὶ μάλιστα πρὸς τὴν εἰς Ἰταλίαν διάβασιν. ὁ γὰρ Δημήτριος οὕτως ἐξέκαιε τὴν ἐλπίδα καὶ τὴν ἐπιβολὴν τῷ βασιλεῖ ταύτην συνεχῶς, ὥστε κατὰ τοὺς ὕπνους τὸν Φίλιππον ταῦτ’ ὀνειρώττειν καὶ περὶ ταύτας εἶναι τὰς πράξεις. ἐποίει δὲ ταῦτα Δημήτριος οὐ Φιλίππου χάριν — τούτῳ μὲν γὰρ τρίτην ἴσως ἐν τούτοις ἔνεμε μερίδα — μᾶλλον δὲ τῆς πρὸς Ῥωμαίους δυσμενείας, τὸ δὲ πλεῖστον ἕνεκεν αὑτοῦ καὶ τῶν ἰδίων ἐλπίδων· μόνως γὰρ οὕτως ἐπέπειστο τὴν ἐν τῷ Φάρῳ δυναστείαν κατακτήσασθαι πάλιν. πλὴν ὅ γε Φίλιππος στρατεύσας ἀνεκτήσατο μὲν τὰς προειρημένας πόλεις, κατελάβετο δὲ τῆς μὲν Δασσαρήτιδος Κρεώνιον καὶ Γεροῦντα, τῶν δὲ περὶ τὴν Λυχνιδίαν λίμνην Ἐγχελᾶνας, Κέρακα, Σατίωνα, Βοιούς, τῆς δὲ Καλοικίνων χώρας Βαντίαν, ἔτι δὲ τῶν καλουμένων Πισαντίνων Ὀργησσόν. ἐπιτελεσάμενος δὲ ταῦτα διαφῆκε τὰς δυνάμεις εἰς παραχειμασίαν. ἦν δ’ ὁ χειμὼν οὗτος, καθ’ ὃν Ἀννίβας, πεπορθηκὼς τοὺς ἐπιφανεστάτους τόπους τῆς Ἰταλίας ἔμελλε περὶ τὸ Γερούνιον τῆς Δαυνίας ποιεῖσθαι τὴν παραχειμασίαν. Ῥωμαῖοι δὲ τότε κατέστησαν στρατηγοὺς αὑτῶν Γάιον Τερέντιον καὶ Λεύκιον Αἰμίλιον.", "st": "5.108"}, {"sp": "N", "t": "Φίλιππος δὲ κατὰ τὴν παραχειμασίαν ἀναλογιζόμενος ὅτι πρὸς τὰς ἐπιβολὰς αὐτοῦ χρεία πλοίων ἐστὶ καὶ τῆς κατὰ θάλατταν ὑπηρεσίας, καὶ ταύτης οὐχ ὡς πρὸς ναυμαχίαν — τοῦτο μὲν γὰρ οὐδ’ ἂν ἤλπισε δυνατὸς εἶναι, Ῥωμαίοις διαναυμαχεῖν — ἀλλὰ μᾶλλον ἕως τοῦ παρακομίζειν στρατιώτας καὶ θᾶττον διαίρειν οὗ πρόθοιτο καὶ παραδόξως ἐπιφαίνεσθαι τοῖς πολεμίοις· διόπερ ὑπολαβὼν ἀρίστην εἶναι πρὸς ταῦτα τὴν τῶν Ἰλλυριῶν ναυπηγίαν ἑκατὸν ἐπεβάλετο λέμβους κατασκευάζειν, σχεδὸν πρῶτος τῶν ἐν Μακεδονίᾳ βασιλέων. καταρτίσας δὲ τούτους συνῆγε τὰς δυνάμεις ἀρχομένης θερείας, καὶ βραχέα προσασκήσας τοὺς Μακεδόνας ἐν ταῖς εἰρεσίαις ἀνήχθη. κατὰ δὲ τὸν αὐτὸν καιρὸν Ἀντίοχος μὲν ὑπερέβαλε τὸν Ταῦρον, Φίλιππος δὲ ποιησάμενος τὸν πλοῦν δι’ Εὐρίπου καὶ [τοῦ] περὶ Μαλέαν ἧκε πρὸς τοὺς περὶ Κεφαλληνίαν καὶ Λευκάδα τόπους, ἐν οἷς καθορμισθεὶς ἐκαραδόκει πολυπραγμονῶν τὸν τῶν Ῥωμαίων στόλον. πυνθανόμενος δὲ περὶ τὸ Λιλύβαιον αὐτοὺς ὁρμεῖν, θαρρήσας ἀνήχθη, καὶ προῆγε ποιούμενος τὸν πλοῦν ὡς ἐπ’ Ἀπολλωνίας.", "st": "5.109"}, {"sp": "N", "t": "ἤδη δὲ συνεγγίζοντος αὐτοῦ τοῖς περὶ τὸν Ἀῷον ποταμὸν τόποις, ὃς ῥεῖ παρὰ τὴν τῶν Ἀπολλωνιατῶν πόλιν, ἐμπίπτει πανικὸν παραπλήσιον τοῖς γινομένοις ἐπὶ τῶν πεζικῶν στρατοπέδων. τῶν γὰρ ἐπὶ τῆς οὐραγίας πλεόντων τινὲς λέμβοι, καθορμισθέντες εἰς τὴν νῆσον, ἣ καλεῖται μὲν Σάσων, κεῖται δὲ κατὰ τὴν εἰσβολὴν τὴν εἰς τὸν Ἰόνιον πόρον, ἧκον ὑπὸ νύκτα πρὸς τὸν Φίλιππον, φάσκοντες συνωρμηκέναι τινὰς αὐτοῖς πλέοντας ἀπὸ πορθμοῦ, τούτους δ’ ἀπαγγέλλειν, ὅτι καταλείποιεν ἐν Ῥηγίῳ πεντήρεις Ῥωμαϊκὰς πλεούσας ἐπ’ Ἀπολλωνίας καὶ πρὸς Σκερδιλαΐδαν. ὁ δὲ Φίλιππος, ὑπολαβὼν ὅσον οὔπω τὸν στόλον ἐπ’ αὐτὸν παρεῖναι, περίφοβος γενόμενος καὶ ταχέως ἀνασπάσας τὰς ἀγκύρας αὖτις εἰς τοὐπίσω παρήγγειλε πλεῖν. οὐδενὶ δὲ κόσμῳ ποιησάμενος τὴν ἀναζυγὴν καὶ τὸν ἀνάπλουν δευτεραῖος εἰς Κεφαλληνίαν κατῆρε, συνεχῶς ἡμέραν καὶ νύκτα τὸν πλοῦν ποιούμενος. βραχὺ δέ τι θαρρήσας ἐνταῦθα κατέμεινε, ποιῶν ἔμφασιν ὡς ἐπί τινας τῶν ἐν Πελοποννήσῳ πράξεων ἐπεστροφώς. συνέβη δὲ ψευδῶς γενέσθαι τὸν ὅλον φόβον περὶ αὐτόν. ὁ γὰρ Σκερδιλαΐδας, ἀκούων κατὰ χειμῶνα λέμβους ναυπηγεῖσθαι τὸν Φίλιππον πλείους, καὶ προσδοκῶν αὐτοῦ τὴν κατὰ θάλατταν παρουσίαν, διεπέμπετο πρὸς τοὺς Ῥωμαίους διασαφῶν ταῦτα καὶ παρακαλῶν βοηθεῖν, οἱ δὲ Ῥωμαῖοι δεκαναΐαν ἀπὸ τοῦ περὶ τὸ Λιλύβαιον ἐξαπέστειλαν στόλου, ταύτην τὴν περὶ τὸ Ῥήγιον ὀφθεῖσαν· ἣν Φίλιππος εἰ μὴ πτοηθεὶς ἀλόγως ἔφυγε, τῶν περὶ τὴν Ἰλλυρίδα πράξεων μάλιστ’ ἂν τότε καθίκετο διὰ τὸ τοὺς Ῥωμαίους πάσαις ταῖς ἐπινοίαις καὶ παρασκευαῖς περὶ τὸν Ἀννίβαν καὶ τὴν περὶ Κάνναν μάχην γίνεσθαι, τῶν τε πλοίων ἐκ τοῦ κατὰ λόγον ἐγκρατὴς ἂν ἐγεγόνει. νῦν δὲ διαταραχθεὶς ὑπὸ τῆς προσαγγελίας ἀβλαβῆ μέν, οὐκ εὐσχήμονα δ’ ἐποιήσατο τὴν ἀναχώρησιν εἰς Μακεδονίαν.", "st": "5.110"}, {"sp": "N", "t": "ἐπράχθη δέ τι κατὰ τούτους τοὺς χρόνους καὶ Προυσίᾳ μνήμης ἄξιον. τῶν γὰρ Γαλατῶν, οὓς διεβίβασεν ἐκ τῆς Εὐρώπης ὁ βασιλεὺς Ἄτταλος εἰς τὸν πρὸς Ἀχαιὸν πόλεμον διὰ τὴν ἐπ’ ἀνδρείᾳ δόξαν, τούτων χωρισθέντων τοῦ προειρημένου βασιλέως διὰ τὰς ἄρτι ῥηθείσας ὑποψίας καὶ πορθούντων μετὰ πολλῆς ἀσελγείας καὶ βίας τὰς ἐφ’ Ἑλλησπόντῳ πόλεις, τὸ δὲ τελευταῖον καὶ πολιορκεῖν τοὺς Ἰλιεῖς ἐπιβαλομένων, ἐγένετο μέν τις οὐκ ἀγεννὴς περὶ ταῦτα πρᾶξις καὶ ὑπὸ τῶν τὴν Τρῳάδα κατοικούντων Ἀλεξάνδρειαν· Θεμίστην γὰρ ἐξαποστείλαντες μετ’ ἀνδρῶν τετρακισχιλίων ἔλυσαν μὲν τὴν Ἰλιέων πολιορκίαν, ἐξέβαλον δ’ ἐκ πάσης τῆς Τρῳάδος τοὺς Γαλάτας, ἐμποδίζοντες ταῖς χορηγίαις καὶ διαλυμαινόμενοι τὰς ἐπιβολὰς αὐτῶν. οἱ δὲ Γαλάται κατασχόντες τὴν Ἀρίσβαν καλουμένην ἐν τῇ τῶν Ἀβυδηνῶν χώρᾳ, λοιπὸν ἐπεβούλευον καὶ προσεπολέμουν ταῖς περὶ τούτους τοὺς τόπους ἐκτισμέναις πόλεσιν. ἐφ’ οὓς στρατεύσας μετὰ δυνάμεως Προυσίας καὶ παραταξάμενος τοὺς μὲν ἄνδρας κατ’ αὐτὸν τὸν κίνδυνον ἐν χερῶν νόμῳ διέφθειρε, τὰ δὲ τέκνα σχεδὸν ἅπαντα καὶ τὰς γυναῖκας αὐτῶν ἐν τῇ παρεμβολῇ κατέσφαξε, τὴν δ’ ἀποσκευὴν ἐφῆκε διαρπάσαι τοῖς ἠγωνισμένοις. πράξας δὲ ταῦτα μεγάλου μὲν ἀπέλυσε φόβου καὶ κινδύνου τὰς ἐφ’ Ἑλλησπόντου πόλεις, καλὸν δὲ παράδειγμα τοῖς ἐπιγινομένοις ἀπέλιπε τοῦ μὴ ῥᾳδίαν ποιεῖσθαι τοὺς ἐκ τῆς Εὐρώπης βαρβάρους τὴν εἰς τὴν Ἀσίαν διάβασιν. τὰ μὲν οὖν περὶ τὴν Ἑλλάδα καὶ τὴν Ἀσίαν ἐν τούτοις ἦν. τὰ δὲ κατὰ τὴν Ἰταλίαν τῆς περὶ Κάνναν μάχης ἐπιτελεσθείσης τὰ πλεῖστα μετετίθετο πρὸς τοὺς Καρχηδονίους, καθάπερ ἐν τοῖς πρὸ τούτων ἡμῖν δεδήλωται. ἡμεῖς δὲ νῦν μὲν ἐπὶ τούτων τῶν καιρῶν τῆς διηγήσεως λήξομεν, ἐπεὶ διεληλύθαμεν ἃς περιέσχε τῶν τε κατὰ τὴν Ἀσίαν καὶ τῶν Ἑλληνικῶν πράξεων ἡ τετταρακοστὴ τῶν ὀλυμπιάδων πρὸς ταῖς ἑκατόν· ἐν δὲ τῇ μετὰ ταῦτα βύβλῳ, βραχέα προσαναμνήσαντες τῆς [ἐν ταύτῃ τῇ βύβλῳ] προκατασκευῆς, ἐπὶ τὸν περὶ τῆς Ῥωμαίων πολιτείας λόγον ἐπάνιμεν κατὰ τὴν ἐν ἀρχαῖς ὑπόσχεσιν.", "st": "5.111"}, {"sp": "HDR", "t": "Βιβλίον Ϛʹ", "st": "6"}, {"sp": "N", "t": "οὐκ ἀγνοῶ μὲν οὖν διότι τινὲς διαπορήσουσι πῶς ἀφέμενοι τοῦ συνάπτειν καὶ προστιθέναι τὸ συνεχὲς τῆς διηγήσεως, εἰς τοῦτον ἀπεθέμεθα τὸν καιρὸν τὸν ὑπὲρ τῆς προειρημένης πολιτείας ἀπολογισμόν· ἐμοὶ δ’ ὅτι μὲν ἦν ἐξ ἀρχῆς ἕν τι τῶν ἀναγκαίων καὶ τοῦτο τὸ μέρος τῆς ὅλης προθέσεως, ἐν πολλοῖς οἶμαι δῆλον αὐτὸ πεποιηκέναι, μάλιστα δ’ ἐν τῇ καταβολῇ καὶ προεκθέσει τῆς ἱστορίας, ἐν ᾗ τοῦτο κάλλιστον ἔφαμεν, ἅμα δ’ ὠφελιμώτατον εἶναι τῆς ἡμετέρας ἐπιβολῆς τοῖς ἐντυγχάνουσι τῇ πραγματείᾳ τὸ γνῶναι καὶ μαθεῖν πῶς καὶ τίνι γένει πολιτείας ἐπικρατηθέντα σχεδὸν πάντα τὰ κατὰ τὴν οἰκουμένην ἐν οὐδ’ ὅλοις πεντήκοντα καὶ τρισὶν ἔτεσιν ὑπὸ μίαν ἀρχὴν τὴν Ῥωμαίων ἔπεσεν, ὃ πρότερον οὐχ εὑρίσκεται γεγονός. κεκριμένου δὲ τούτου καιρὸν οὐχ ἑώρων ἐπιτηδειότερον εἰς ἐπίστασιν καὶ δοκιμασίαν τῶν λέγεσθαι μελλόντων ὑπὲρ τῆς πολιτείας τοῦ νῦν ἐνεστῶτος. καθάπερ γὰρ οἱ κατ’ ἰδίαν ὑπὲρ τῶν φαύλων ἢ τῶν σπουδαίων ἀνδρῶν ποιούμενοι τὰς διαλήψεις, ἐπειδὰν ἀληθῶς πρόθωνται δοκιμάζειν, οὐκ ἐκ τῆς ἀπεριστάτου ῥᾳστώνης κατὰ τὸν βίον ποιοῦνται τὰς ἐπισκέψεις, ἀλλ’ ἐκ τῶν ἐν ταῖς ἀτυχίαις περιπετειῶν καὶ τῶν ἐν ταῖς ἐπιτυχίαις κατορθωμάτων, μόνον νομίζοντες εἶναι ταύτην ἀνδρὸς τελείου βάσανον τὸ τὰς ὁλοσχερεῖς μεταβολὰς τῆς τύχης μεγαλοψύχως δύνασθαι καὶ γενναίως ὑποφέρειν, τὸν αὐτὸν τρόπον χρὴ θεωρεῖν καὶ πολιτείαν. διόπερ οὐχ ὁρῶν ποίαν ἄν τις ὀξυτέραν ἢ μείζονα λάβοι μεταβολὴν τῶν καθ’ ἡμᾶς τῆς γε Ῥωμαίοις συμβάσης, εἰς τοῦτον ἀπεθέμην τὸν καιρὸν τὸν ὑπὲρ τῶν προειρημένων ἀπολογισμόν· γνοίη δ’ ἄν τις τὸ μέγεθος τῆς μεταβολῆς ἐκ τούτων. ζήτει ἐν τῷ περὶ στρατηγίας. ὅτι τὸ ψυχαγωγοῦν ἅμα καὶ τὴν ὠφέλειαν ἐπιφέρον τοῖς φιλομαθοῦσι τοῦτ’ ἔστιν ἡ τῶν αἰτιῶν θεωρία καὶ τοῦ βελτίονος ἐν ἑκάστοις αἵρεσις. μεγίστην δ’ αἰτίαν ἡγητέον ἐν ἅπαντι πράγματι καὶ πρὸς ἐπιτυχίαν καὶ τοὐναντίον τὴν τῆς πολιτείας σύστασιν· ἐκ γὰρ ταύτης ᾗπερ ἐκ πηγῆς οὐ μόνον ἀναφέρεσθαι συμβαίνει πάσας τὰς ἐπινοίας καὶ τὰς ἐπιβολὰς τῶν ἔργων, ἀλλὰ καὶ συντέλειαν λαμβάνειν.", "st": "6.1"}, {"sp": "N", "t": "τῶν μὲν γὰρ Ἑλληνικῶν πολιτευμάτων ὅσα πολλάκις μὲν ηὔξηται, πολλάκις δὲ τῆς εἰς τἀναντία μεταβολῆς ὁλοσχερῶς πεῖραν εἴληφε, ῥᾳδίαν εἶναι συμβαίνει καὶ τὴν ὑπὲρ τῶν προγεγονότων ἐξήγησιν καὶ τὴν ὑπὲρ τοῦ μέλλοντος ἀπόφασιν· τό τε γὰρ ἐξαγγεῖλαι τὰ γινωσκόμενα ῥᾴδιον, τό τε προειπεῖν ὑπὲρ τοῦ μέλλοντος στοχαζόμενον ἐκ τῶν ἤδη γεγονότων εὐμαρές. περὶ δὲ τῆς Ῥωμαίων οὐδ’ ὅλως εὐχερὲς οὔτε περὶ τῶν παρόντων ἐξηγήσασθαι διὰ τὴν ποικιλίαν τῆς πολιτείας, οὔτε περὶ τοῦ μέλλοντος προειπεῖν διὰ τὴν ἄγνοιαν τῶν προγεγονότων περὶ αὐτοὺς ἰδιωμάτων καὶ κοινῇ καὶ κατ’ ἰδίαν. διόπερ οὐ τῆς τυχούσης ἐπιστάσεως προσδεῖται καὶ θεωρίας, εἰ μέλλοι τις τὰ διαφέροντα καθαρίως ἐν αὐτῇ συνόψεσθαι. συμβαίνει δὴ τοὺς πλείστους τῶν βουλομένων διδασκαλικῶς ἡμῖν ὑποδεικνύειν περὶ τῶν τοιούτων τρία γένη λέγειν πολιτειῶν, ὧν τὸ μὲν καλοῦσι βασιλείαν, τὸ δ’ ἀριστοκρατίαν, τὸ δὲ τρίτον δημοκρατίαν. δοκεῖ δέ μοι πάνυ τις εἰκότως ἂν ἐπαπορῆσαι πρὸς αὐτούς, πότερον ὡς μόνας ταύτας ἢ καὶ νὴ Δί’ ὡς ἀρίστας ἡμῖν εἰσηγοῦνται τῶν πολιτειῶν. κατ’ ἀμφότερα γὰρ ἀγνοεῖν μοι δοκοῦσι. δῆλον γὰρ ὡς ἀρίστην μὲν ἡγητέον πολιτείαν τὴν ἐκ πάντων τῶν προειρημένων ἰδιωμάτων συνεστῶσαν· τούτου γὰρ τοῦ μέρους οὐ λόγῳ μόνον, ἀλλ’ ἔργῳ πεῖραν εἰλήφαμεν, Λυκούργου συστήσαντος πρώτου κατὰ τοῦτον τὸν τρόπον τὸ Λακεδαιμονίων πολίτευμα. καὶ μὴν οὐδ’ ὡς μόνας ταύτας προσδεκτέον· καὶ γὰρ μοναρχικὰς καὶ τυραννικὰς ἤδη τινὰς τεθεάμεθα πολιτείας, αἳ πλεῖστον διαφέρουσαι βασιλείας παραπλήσιον ἔχειν τι ταύτῃ δοκοῦσιν· ᾗ καὶ συμψεύδονται καὶ συγχρῶνται πάντες οἱ μόναρχοι καθ’ ὅσον οἷοί τ’ εἰσὶ τῷ τῆς βασιλείας ὀνόματι. καὶ μὴν ὀλιγαρχικὰ πολιτεύματα καὶ πλείω γέγονε, δοκοῦντα παρόμοιον ἔχειν τι τοῖς ἀριστοκρατικοῖς, ἃ πλεῖστον ὡς ἔπος εἰπεῖν διεστᾶσιν. ὁ δ’ αὐτὸς λόγος καὶ περὶ δημοκρατίας.", "st": "6.3"}, {"sp": "N", "t": "ὅτι δ’ ἀληθές ἐστι τὸ λεγόμενον ἐκ τούτων συμφανές. οὔτε γὰρ πᾶσαν δήπου μοναρχίαν εὐθέως βασιλείαν ῥητέον, ἀλλὰ μόνην τὴν ἐξ ἑκόντων συγχωρουμένην καὶ τῇ γνώμῃ τὸ πλεῖον ἢ φόβῳ καὶ βίᾳ κυβερνωμένην· οὐδὲ μὴν πᾶσαν ὀλιγαρχίαν ἀριστοκρατίαν νομιστέον, ἀλλὰ ταύτην, ἥτις ἂν κατ’ ἐκλογὴν ὑπὸ τῶν δικαιοτάτων καὶ φρονιμωτάτων ἀνδρῶν βραβεύηται. παραπλησίως οὐδὲ δημοκρατίαν, ἐν ᾗ πᾶν πλῆθος κύριόν ἐστι ποιεῖν ὅ, τι ποτ’ ἂν αὐτὸ βουληθῇ καὶ πρόθηται παρὰ δ’ ᾧ πάτριόν ἐστι καὶ σύνηθες θεοὺς σέβεσθαι, γονεῖς θεραπεύειν, πρεσβυτέρους αἰδεῖσθαι, νόμοις πείθεσθαι, παρὰ τοῖς τοιούτοις συστήμασιν ὅταν τὸ τοῖς πλείοσι δόξαν νικᾷ, τοῦτο καλεῖν δεῖ δημοκρατίαν. διὸ καὶ γένη μὲν ἓξ εἶναι ῥητέον πολιτειῶν, τρία μὲν ἃ πάντες θρυλοῦσι καὶ νῦν προείρηται, τρία δὲ τὰ τούτοις συμφυῆ, λέγω δὲ μοναρχίαν, ὀλιγαρχίαν, ὀχλοκρατίαν. πρώτη μὲν οὖν ἀκατασκεύως καὶ φυσικῶς συνίσταται μοναρχία, ταύτῃ δ’ ἕπεται καὶ ἐκ ταύτης γεννᾶται μετὰ κατασκευῆς καὶ διορθώσεως βασιλεία. μεταβαλλούσης δὲ ταύτης εἰς τὰ συμφυῆ κακά, λέγω δ’ εἰς τυραννίδ’, αὖθις ἐκ τῆς τούτων καταλύσεως ἀριστοκρατία φύεται. καὶ μὴν ταύτης εἰς ὀλιγαρχίαν ἐκτραπείσης κατὰ φύσιν, τοῦ δὲ πλήθους ὀργῇ μετελθόντος τὰς τῶν προεστώτων ἀδικίας, γεννᾶται δῆμος. ἐκ δὲ τῆς τούτου πάλιν ὕβρεως καὶ παρανομίας ἀποπληροῦται σὺν χρόνοις ὀχλοκρατία. γνοίη δ’ ἄν τις σαφέστατα περὶ τούτων ὡς ἀληθῶς ἐστιν οἷα δὴ νῦν εἶπον, ἐπὶ τὰς ἑκάστων κατὰ φύσιν ἀρχὰς καὶ γενέσεις καὶ μεταβολὰς ἐπιστήσας. ὁ γὰρ συνιδὼν ἕκαστον αὐτῶν ὡς φύεται, μόνος ἂν οὗτος δύναιτο συνιδεῖν καὶ τὴν αὔξησιν καὶ τὴν ἀκμὴν καὶ τὴν μεταβολὴν ἑκάστων καὶ τὸ τέλος, πότε καὶ πῶς καὶ ποῦ καταντήσει πάλιν· μάλιστα δ’ ἐπὶ τῆς Ῥωμαίων πολιτείας τοῦτον ἁρμόσειν τὸν τρόπον ὑπείληφα τῆς ἐξηγήσεως διὰ τὸ κατὰ φύσιν αὐτὴν ἀπ’ ἀρχῆς εἰληφέναι τήν τε σύστασιν καὶ τὴν αὔξησιν.", "st": "6.4"}, {"sp": "N", "t": "ἀκριβέστερον μὲν οὖν ἴσως ὁ περὶ τῆς κατὰ φύσιν μεταβολῆς τῶν πολιτειῶν εἰς ἀλλήλας διευκρινεῖται λόγος παρὰ Πλάτωνι καί τισιν ἑτέροις τῶν φιλοσόφων· ποικίλος δ’ ὢν καὶ διὰ πλειόνων λεγόμενος ὀλίγοις ἐφικτός ἐστιν. διόπερ ὅσον ἀνήκειν ὑπολαμβάνομεν αὐτοῦ πρὸς τὴν πραγματικὴν ἱστορίαν καὶ τὴν κοινὴν ἐπίνοιαν, τοῦτο πειρασόμεθα κεφαλαιωδῶς διελθεῖν· καὶ γὰρ ἂν ἐλλείπειν τι δόξῃ διὰ τῆς καθολικῆς ἐμφάσεως, ὁ κατὰ μέρος λόγος τῶν ἑξῆς ῥηθησομένων ἱκανὴν ἀνταπόδοσιν ποιήσει τῶν νῦν ἐπαπορηθέντων. ποίας οὖν ἀρχὰς λέγω καὶ πόθεν φημὶ φύεσθαι τὰς πολιτείας πρῶτον; ὅταν ἢ διὰ κατακλυσμοὺς ἢ διὰ λοιμικὰς περιστάσεις ἢ δι’ ἀφορίας καρπῶν ἢ δι’ ἄλλας τοιαύτας αἰτίας φθορὰ γένηται τοῦ τῶν ἀνθρώπων γένους, οἵας ἤδη γεγονέναι παρειλήφαμεν καὶ πάλιν πολλάκις ἔσεσθ’ ὁ λόγος αἱρεῖ, τότε δὴ συμφθειρομένων πάντων τῶν ἐπιτηδευμάτων καὶ τεχνῶν, ὅταν ἐκ τῶν περιλειφθέντων οἷον εἰ σπερμάτων αὖθις αὐξηθῇ σὺν χρόνῳ πλῆθος ἀνθρώπων, τότε δήπου, καθάπερ ἐπὶ τῶν ἄλλων ζῴων, καὶ ἐπὶ τούτων συναθροιζομένων — ὅπερ εἰκός, καὶ τούτους εἰς τὸ ὁμόφυλον συναγελάζεσθαι διὰ τὴν τῆς φύσεως ἀσθένειαν — ἀνάγκη τὸν τῇ σωματικῇ ῥώμῃ καὶ τῇ ψυχικῇ τόλμῃ διαφέροντα, τοῦτον ἡγεῖσθαι καὶ κρατεῖν, καθάπερ καὶ ἐπὶ τῶν ἄλλων γενῶν ἀδοξοποιήτων ζῴων θεωρούμενον τοῦτο χρὴ φύσεως ἔργον ἀληθινώτατον νομίζειν, παρ’ οἷς ὁμολογουμένως τοὺς ἰσχυροτάτους ὁρῶμεν ἡγουμένους, λέγω δὲ ταύρους, κάπρους, ἀλεκτρυόνας, τὰ τούτοις παραπλήσια. τὰς μὲν οὖν ἀρχὰς εἰκὸς τοιούτους εἶναι καὶ τοὺς τῶν ἀνθρώπων βίους, ζῳηδὸν συναθροιζομένων καὶ τοῖς ἀλκιμωτάτοις καὶ δυναμικωτάτοις ἑπομένων· οἷς ὅρος μέν ἐστι τῆς ἀρχῆς ἰσχύς, ὄνομα δ’ ἂν εἴποι τις μοναρχίαν. ἐπειδὰν δὲ τοῖς συστήμασι διὰ τὸν χρόνον ὑπογένηται συντροφία καὶ συνήθεια, τοῦτ’ ἀρχὴ βασιλείας φύεται, καὶ τότε πρώτως ἔννοια γίνεται τοῦ καλοῦ καὶ δικαίου τοῖς ἀνθρώποις, ὁμοίως δὲ καὶ τῶν ἐναντίων τούτοις.", "st": "6.5"}, {"sp": "N", "t": "ὁ δὲ τρόπος τῆς ἀρχῆς καὶ τῆς γενέσεως τῶν εἰρημένων τοιόσδε. πάντων γὰρ πρὸς τὰς συνουσίας ὁρμώντων κατὰ φύσιν, ἐκ δὲ τούτων παιδοποιίας ἀποτελουμένης, ὁπότε τις τῶν ἐκτραφέντων εἰς ἡλικίαν ἱκόμενος μὴ νέμοι χάριν μηδ’ ἀμύναι τούτοις οἷς ἐκτρέφοιτ’, ἀλλά που τἀναντία κακῶς λέγειν ἢ δρᾶν τούτους ἐγχειροίη, δῆλον ὡς δυσαρεστεῖν καὶ προσκόπτειν εἰκὸς τοὺς συνόντας καὶ συνιδόντας τὴν γεγενημένην ἐκ τῶν γεννησάντων ἐπιμέλειαν καὶ κακοπάθειαν περὶ τὰ τέκνα καὶ τὴν τούτων θεραπείαν καὶ τροφήν. τοῦ γὰρ γένους τῶν ἀνθρώπων ταύτῃ διαφέροντος τῶν ἄλλων ζῴων, ᾗ μόνοις αὐτοῖς μέτεστι νοῦ καὶ λογισμοῦ, φανερὸν ὡς οὐκ εἰκὸς παρατρέχειν αὐτοὺς τὴν προειρημένην διαφοράν, καθάπερ ἐπὶ τῶν ἄλλων ζῴων, ἀλλ’ ἐπισημαίνεσθαι τὸ γινόμενον καὶ δυσαρεστεῖσθαι τοῖς παροῦσι, προορωμένους τὸ μέλλον καὶ συλλογιζομένους ὅτι τὸ παραπλήσιον ἑκάστοις αὐτῶν συγκυρήσει. καὶ μὴν ὅταν που πάλιν ἅτερος ὑπὸ θατέρου τυχὼν ἐπικουρίας ἢ βοηθείας ἐν τοῖς δεινοῖς μὴ νέμῃ τῷ σώσαντι χάριν, ἀλλά ποτε καὶ βλάπτειν ἐγχειρῇ τοῦτον, φανερὸν ὡς εἰκὸς τῷ τοιούτῳ δυσαρεστεῖσθαι καὶ προσκόπτειν τοὺς εἰδότας, συναγανακτοῦντας μὲν τῷ πέλας, ἀναφέροντας δ’ ἐφ’ αὑτοὺς τὸ παραπλήσιον. ἐξ ὧν ὑπογίνεταί τις ἔννοια παρ’ ἑκάστῳ τῆς τοῦ καθήκοντος δυνάμεως καὶ θεωρίας· ὅπερ ἐστὶν ἀρχὴ καὶ τέλος δικαιοσύνης. ὁμοίως πάλιν ὅταν ἀμύνῃ μέν τις πρὸ πάντων ἐν τοῖς δεινοῖς, ὑφίστηται δὲ καὶ μένῃ τὰς ἐπιφορὰς τῶν ἀλκιμωτάτων ζῴων, εἰκὸς μὲν τὸν τοιοῦτον ὑπὸ τοῦ πλήθους ἐπισημασίας τυγχάνειν εὐνοϊκῆς καὶ προστατικῆς, τὸν δὲ τἀναντία τούτῳ πράττοντα καταγνώσεως καὶ προσκοπῆς. ἐξ οὗ πάλιν εὔλογον ὑπογίνεσθαί τινα θεωρίαν παρὰ τοῖς πολλοῖς αἰσχροῦ καὶ καλοῦ καὶ τῆς τούτων πρὸς ἄλληλα διαφορᾶς, καὶ τὸ μὲν ζήλου καὶ μιμήσεως τυγχάνειν διὰ τὸ συμφέρον, τὸ δὲ φυγῆς. ἐν οἷς ὅταν ὁ προεστὼς καὶ τὴν μεγίστην δύναμιν ἔχων ἀεὶ συνεπισχύῃ τοῖς προειρημένοις κατὰ τὰς τῶν πολλῶν διαλήψεις, καὶ δόξῃ τοῖς ὑποταττομένοις διανεμητικὸς εἶναι τοῦ κατ’ ἀξίαν ἑκάστοις, οὐκέτι τὴν βίαν δεδιότες, τῇ δὲ γνώμῃ τὸ πλεῖον εὐδοκοῦντες, ὑποτάττονται καὶ συσσῴζουσι τὴν ἀρχὴν αὐτοῦ, κἂν ὅλως ᾖ γηραιός, ὁμοθυμαδὸν ἐπαμύνοντες καὶ διαγωνιζόμενοι πρὸς τοὺς ἐπιβουλεύοντας αὐτοῦ τῇ δυναστείᾳ. καὶ δὴ τῷ τοιούτῳ τρόπῳ βασιλεὺς ἐκ μονάρχου λανθάνει γενόμενος, ὅταν παρὰ τοῦ θυμοῦ καὶ τῆς ἰσχύος μεταλάβῃ τὴν ἡγεμονίαν ὁ λογισμός.", "st": "6.6"}, {"sp": "N", "t": "αὕτη καλοῦ καὶ δικαίου πρώτη παρ’ ἀνθρώποις κατὰ φύσιν ἔννοια καὶ τῶν ἐναντίων τούτοις, αὕτη βασιλείας ἀληθινῆς ἀρχὴ καὶ γένεσις. οὐ γὰρ μόνον αὐτοῖς, ἀλλὰ καὶ τοῖς ἐκ τούτων οἱ πολλοὶ διαφυλάττουσι τὰς ἀρχάς, πεπεισμένοι τοὺς ἐκ τοιούτων γεγονότας καὶ τραφέντας ὑπὸ τοιούτοις παραπλησίους ἕξειν καὶ τὰς προαιρέσεις. ἐὰν δέ ποτε τοῖς ἐγγόνοις δυσαρεστήσωσι, ποιοῦνται μετὰ ταῦτα τὴν αἵρεσιν τῶν ἀρχόντων καὶ βασιλέων οὐκέτι κατὰ τὰς σωματικὰς καὶ θυμικὰς δυνάμεις, ἀλλὰ κατὰ τὰς τῆς γνώμης καὶ τοῦ λογισμοῦ διαφοράς, πεῖραν εἰληφότες ἐπ’ αὐτῶν τῶν ἔργων τῆς ἐξ ἀμφοῖν παραλλαγῆς. τὸ μὲν οὖν παλαιὸν ἐνεγήρασκον ταῖς βασιλείαις οἱ κριθέντες ἅπαξ καὶ τυχόντες τῆς ἐξουσίας ταύτης, τόπους τε διαφέροντας ὀχυρούμενοι καὶ τειχίζοντες καὶ χώραν κατακτώμενοι, τὸ μὲν τῆς ἀσφαλείας χάριν, τὸ δὲ τῆς δαψιλείας τῶν ἐπιτηδείων τοῖς ὑποτεταγμένοις· ἅμα δὲ περὶ ταῦτα σπουδάζοντες ἐκτὸς ἦσαν πάσης διαβολῆς καὶ φθόνου διὰ τὸ μήτε περὶ τὴν ἐσθῆτα μεγάλας ποιεῖσθαι τὰς παραλλαγὰς μήτε περὶ τὴν βρῶσιν καὶ πόσιν, ἀλλὰ παραπλήσιον ἔχειν τὴν βιοτείαν τοῖς ἄλλοις, ὁμόσε ποιούμενοι τοῖς πολλοῖς ἀεὶ τὴν δίαιταν. ἐπεὶ δ’ ἐκ διαδοχῆς καὶ κατὰ γένος τὰς ἀρχὰς παραλαμβάνοντες ἕτοιμα μὲν εἶχον ἤδη τὰ πρὸς τὴν ἀσφάλειαν, ἕτοιμα δὲ καὶ πλείω τῶν ἱκανῶν τὰ πρὸς τὴν τροφήν, τότε δὴ ταῖς ἐπιθυμίαις ἑπόμενοι διὰ τὴν περιουσίαν ἐξάλλους μὲν ἐσθῆτας ὑπέλαβον δεῖν ἔχειν τοὺς ἡγουμένους τῶν ὑποταττομένων, ἐξάλλους δὲ καὶ ποικίλας τὰς περὶ τὴν τροφὴν ἀπολαύσεις καὶ παρασκευάς, ἀναντιρρήτους δὲ καὶ παρὰ τῶν μὴ προσηκόντων τὰς τῶν ἀφροδισίων χρείας καὶ συνουσίας. ἐφ’ οἷς μὲν φθόνου γενομένου καὶ προσκοπῆς, ἐφ’ οἷς δὲ μίσους ἐκκαιομένου καὶ δυσμενικῆς ὀργῆς, ἐγένετο μὲν ἐκ τῆς βασιλείας τυραννίς, ἀρχὴ δὲ καταλύσεως ἐγεννᾶτο καὶ σύστασις ἐπιβουλῆς τοῖς ἡγουμένοις· ἣν οὐκ ἐκ τῶν χειρίστων, ἀλλ’ ἐκ τῶν γενναιοτάτων καὶ μεγαλοψυχοτάτων, ἔτι δὲ θαρραλεωτάτων ἀνδρῶν συνέβαινε γίνεσθαι διὰ τὸ τοὺς τοιούτους ἥκιστα δύνασθαι φέρειν τὰς τῶν ἐφεστώτων ὕβρεις.", "st": "6.7"}, {"sp": "N", "t": "τοῦ δὲ πλήθους, ὅτε λάβοι προστάτας, συνεπισχύοντος κατὰ τῶν ἡγουμένων διὰ τὰς προειρημένας αἰτίας, τὸ μὲν τῆς βασιλείας καὶ μοναρχίας εἶδος ἄρδην ἀνῃρεῖτο, τὸ δὲ τῆς ἀριστοκρατίας αὖθις ἀρχὴν ἐλάμβανε καὶ γένεσιν. τοῖς γὰρ καταλύσασι τοὺς μονάρχους οἷον εἰ χάριν ἐκ χειρὸς ἀποδιδόντες οἱ πολλοὶ τούτοις ἐχρῶντο προστάταις καὶ τούτοις ἐπέτρεπον περὶ σφῶν. οἱ δὲ τὸ μὲν πρῶτον ἀσμενίζοντες τὴν ἐπιτροπὴν οὐδὲν προυργιαίτερον ἐποιοῦντο τοῦ κοινῇ συμφέροντος, καὶ κηδεμονικῶς καὶ φυλακτικῶς ἕκαστα χειρίζοντες καὶ τὰ κατ’ ἰδίαν καὶ τὰ κοινὰ τοῦ πλήθους. ὅτε δὲ διαδέξαιντο πάλιν παῖδες παρὰ πατέρων τὴν τοιαύτην ἐξουσίαν, ἄπειροι μὲν ὄντες κακῶν, ἄπειροι δὲ καθόλου πολιτικῆς ἰσότητος καὶ παρρησίας, τεθραμμένοι δ’ ἐξ ἀρχῆς ἐν ταῖς τῶν πατέρων ἐξουσίαις καὶ προαγωγαῖς, ὁρμήσαντες οἱ μὲν ἐπὶ πλεονεξίαν καὶ φιλαργυρίαν ἄδικον, οἱ δ’ ἐπὶ μέθας καὶ τὰς ἅμα ταύταις ἀπλήστους εὐωχίας, οἱ δ’ ἐπὶ τὰς τῶν γυναικῶν ὕβρεις καὶ παίδων ἁρπαγάς, μετέστησαν μὲν τὴν ἀριστοκρατίαν εἰς ὀλιγαρχίαν, ταχὺ δὲ κατεσκεύασαν ἐν τοῖς πλήθεσι πάλιν τὰ παραπλήσια τοῖς ἄρτι ῥηθεῖσι· διὸ καὶ παραπλήσιον συνέβαινε τὸ τέλος αὐτῶν γίνεσθαι τῆς καταστροφῆς τοῖς περὶ τοὺς τυράννους ἀτυχήμασιν.", "st": "6.8"}, {"sp": "N", "t": "ἐπειδὰν γάρ τις συνθεασάμενος τὸν φθόνον καὶ τὸ μῖσος κατ’ αὐτῶν τὸ παρὰ τοῖς πολίταις ὑπάρχον, κἄπειτα θαρρήσῃ λέγειν ἢ πράττειν τι κατὰ τῶν προεστώτων, πᾶν ἕτοιμον καὶ συνεργὸν λαμβάνει τὸ πλῆθος. λοιπὸν οὓς μὲν φονεύσαντες, οὓς δὲ φυγαδεύσαντες, οὔτε βασιλέα προΐστασθαι τολμῶσιν, ἔτι δεδιότες τὴν τῶν πρότερον ἀδικίαν, οὔτε πλείοσιν ἐπιτρέπειν τὰ κοινὰ θαρροῦσι, παρὰ πόδας αὐτοῖς οὔσης τῆς πρότερον ἀγνοίας, μόνης δὲ σφίσι καταλειπομένης ἐλπίδος ἀκεραίου τῆς ἐν αὑτοῖς ἐπὶ ταύτην καταφέρονται, καὶ τὴν μὲν πολιτείαν ἐξ ὀλιγαρχικῆς δημοκρατίαν ἐποίησαν, τὴν δὲ τῶν κοινῶν πρόνοιαν καὶ πίστιν εἰς σφᾶς αὐτοὺς ἀνέλαβον. καὶ μέχρι μὲν ἂν ἔτι σῴζωνταί τινες τῶν ὑπεροχῆς καὶ δυναστείας πεῖραν εἰληφότων, ἀσμενίζοντες τῇ παρούσῃ καταστάσει περὶ πλείστου ποιοῦνται τὴν ἰσηγορίαν καὶ τὴν παρρησίαν· ὅταν δ’ ἐπιγένωνται νέοι καὶ παισὶ παίδων πάλιν ἡ δημοκρατία παραδοθῇ, τότ’ οὐκέτι διὰ τὸ σύνηθες ἐν μεγάλῳ τιθέμενοι τὸ τῆς ἰσηγορίας καὶ παρρησίας ζητοῦσι πλέον ἔχειν τῶν πολλῶν· μάλιστα δ’ εἰς τοῦτ’ ἐμπίπτουσιν οἱ ταῖς οὐσίαις ὑπερέχοντες. λοιπὸν ὅταν ὁρμήσωσιν ἐπὶ τὸ φιλαρχεῖν καὶ μὴ δύνωνται δι’ αὑτῶν καὶ διὰ τῆς ἰδίας ἀρετῆς τυγχάνειν τούτων, διαφθείρουσι τὰς οὐσίας, δελεάζοντες καὶ λυμαινόμενοι τὰ πλήθη κατὰ πάντα τρόπον. ἐξ ὧν ὅταν ἅπαξ δωροδόκους καὶ δωροφάγους κατασκευάσωσι τοὺς πολλοὺς διὰ τὴν ἄφρονα δοξοφαγίαν, τότ’ ἤδη πάλιν τὸ μὲν τῆς δημοκρατίας καταλύεται, μεθίσταται δ’ εἰς βίαν καὶ χειροκρατίαν ἡ δημοκρατία. συνειθισμένον γὰρ τὸ πλῆθος ἐσθίειν τὰ ἀλλότρια καὶ τὰς ἐλπίδας ἔχειν τοῦ ζῆν ἐπὶ τοῖς τῶν πέλας, ὅταν λάβῃ προστάτην μεγαλόφρονα καὶ τολμηρόν, ἐκκλειόμενον δὲ διὰ πενίαν τῶν ἐν τῇ πολιτείᾳ τιμίων, τότε δὴ χειροκρατίαν ἀποτελεῖ, καὶ τότε συναθροιζόμενον ποιεῖ σφαγάς, φυγάς, γῆς ἀναδασμούς, ἕως ἂν ἀποτεθηριωμένον πάλιν εὕρῃ δεσπότην καὶ μόναρχον. αὕτη πολιτειῶν ἀνακύκλωσις, αὕτη φύσεως οἰκονομία, καθ’ ἣν μεταβάλλει καὶ μεθίσταται καὶ πάλιν εἰς αὑτὰ καταντᾷ τὰ κατὰ τὰς πολιτείας. ταῦτά τις σαφῶς ἐπεγνωκὼς χρόνοις μὲν ἴσως διαμαρτήσεται λέγων ὑπὲρ τοῦ μέλλοντος περὶ πολιτείας, τὸ δὲ ποῦ τῆς αὐξήσεως ἕκαστόν ἐστιν ἢ τῆς φθορᾶς ἢ ποῦ μεταστήσεται σπανίως ἂν διασφάλλοιτο, χωρὶς ὀργῆς ἢ φθόνου ποιούμενος τὴν ἀπόφασιν. καὶ μὴν περί γε τῆς Ῥωμαίων πολιτείας κατὰ ταύτην τὴν ἐπίστασιν μάλιστ’ ἂν ἔλθοιμεν εἰς γνῶσιν καὶ τῆς συστάσεως καὶ τῆς αὐξήσεως καὶ τῆς ἀκμῆς, ὁμοίως δὲ καὶ τῆς εἰς τοὔμπαλιν ἐσομένης ἐκ τούτων μεταβολῆς· εἰ γάρ τινα καὶ ἑτέραν πολιτείαν, ὡς ἀρτίως εἶπα, καὶ ταύτην συμβαίνει, κατὰ φύσιν ἀπ’ ἀρχῆς ἔχουσαν τὴν σύστασιν καὶ τὴν αὔξησιν, κατὰ φύσιν ἕξειν καὶ τὴν εἰς τἀναντία μεταβολήν. σκοπεῖν δ’ ἐξέσται διὰ τῶν μετὰ ταῦτα ῥηθησομένων.", "st": "6.9"}, {"sp": "N", "t": "νῦν δ’ ἐπὶ βραχὺ ποιησόμεθα μνήμην ὑπὲρ τῆς Λυκούργου νομοθεσίας· ἔστι γὰρ οὐκ ἀνοίκειος ὁ λόγος τῆς προθέσεως. ἐκεῖνος γὰρ ἕκαστα τῶν προειρημένων συννοήσας ἀναγκαίως καὶ φυσικῶς ἐπιτελούμενα καὶ συλλογισάμενος ὅτι πᾶν εἶδος πολιτείας ἁπλοῦν καὶ κατὰ μίαν συνεστηκὸς δύναμιν ἐπισφαλὲς γίνεται διὰ τὸ ταχέως εἰς τὴν οἰκείαν καὶ φύσει παρεπομένην ἐκτρέπεσθαι κακίαν· καθάπερ γὰρ σιδήρῳ μὲν ἰός, ξύλοις δὲ θρῖπες καὶ τερηδόνες συμφυεῖς εἰσι λῦμαι, δι’ ὧν, κἂν πάσας τὰς ἔξωθεν διαφύγωσι βλάβας, ὑπ’ αὐτῶν φθείρονται τῶν συγγενομένων, τὸν αὐτὸν τρόπον καὶ τῶν πολιτειῶν συγγεννᾶται κατὰ φύσιν ἑκάστῃ καὶ παρέπεταί τις κακία, βασιλείᾳ μὲν ὁ μοναρχικὸς λεγόμενος τρόπος, ἀριστοκρατίᾳ δ’ ὁ τῆς ὀλιγαρχίας, δημοκρατίᾳ δ’ ὁ θηριώδης καὶ χειροκρατικός, εἰς οὓς οὐχ οἷόν τε μὴ οὐ πάντα τὰ προειρημένα σὺν χρόνῳ ποιεῖσθαι τὰς μεταστάσεις κατὰ τὸν ἄρτι λόγον. ἃ προϊδόμενος Λυκοῦργος οὐχ ἁπλῆν οὐδὲ μονοειδῆ συνεστήσατο τὴν πολιτείαν, ἀλλὰ πάσας ὁμοῦ συνήθροιζε τὰς ἀρετὰς καὶ τὰς ἰδιότητας τῶν ἀρίστων πολιτευμάτων, ἵνα μηδὲν αὐξανόμενον ὑπὲρ τὸ δέον εἰς τὰς συμφυεῖς ἐκτρέπηται κακίας, ἀντισπωμένης δὲ τῆς ἑκάστου δυνάμεως ὑπ’ ἀλλήλων μηδαμοῦ νεύῃ μηδ’ ἐπὶ πολὺ καταρρέπῃ μηδὲν αὐτῶν, ἀλλ’ ἰσορροποῦν καὶ ζυγοστατούμενον ἐπὶ πολὺ διαμένῃ κατὰ τὸν τῆς ἀντιπλοίας λόγον ἀεὶ τὸ πολίτευμα, τῆς μὲν βασιλείας κωλυομένης ὑπερηφανεῖν διὰ τὸν ἀπὸ τοῦ δήμου φόβον, δεδομένης καὶ τούτῳ μερίδος ἱκανῆς ἐν τῇ πολιτείᾳ, τοῦ δὲ δήμου πάλιν μὴ θαρροῦντος καταφρονεῖν τῶν βασιλέων διὰ τὸν ἀπὸ τῶν γερόντων φόβον, οἳ κατ’ ἐκλογὴν ἀριστίνδην κεκριμένοι πάντες ἔμελλον ἀεὶ τῷ δικαίῳ προσνέμειν ἑαυτούς, ὥστε τὴν τῶν ἐλαττουμένων μερίδα διὰ τὸ τοῖς ἔθεσιν ἐμμένειν, ταύτην ἀεὶ γίνεσθαι μείζω καὶ βαρυτέραν τῇ τῶν γερόντων προσκλίσει καὶ ῥοπῇ. τοιγαροῦν οὕτως συστησάμενος πλεῖστον ὧν ἡμεῖς ἴσμεν χρόνον διεφύλαξε τοῖς Λακεδαιμονίοις τὴν ἐλευθερίαν. ἐκεῖνος μὲν οὖν λόγῳ τινὶ προϊδόμενος πόθεν ἕκαστα καὶ πῶς πέφυκε συμβαίνειν, ἀβλαβῶς συνεστήσατο τὴν προειρημένην πολιτείαν· Ῥωμαῖοι δὲ τὸ μὲν τέλος ταὐτὸ πεποίηνται τῆς ἐν τῇ πατρίδι καταστάσεως, οὐ μὴν διὰ λόγου, διὰ δὲ πολλῶν ἀγώνων καὶ πραγμάτων, ἐξ αὐτῆς ἀεὶ τῆς ἐν ταῖς περιπετείαις ἐπιγνώσεως αἱρούμενοι τὸ βέλτιον, οὕτως ἦλθον ἐπὶ ταὐτὸ μὲν Λυκούργῳ τέλος, κάλλιστον δὲ σύστημα τῶν καθ’ ἡμᾶς πολιτειῶν.", "st": "6.10"}, {"sp": "N", "t": "Ὄλκιον, πόλις Τυρρηνίας· Πολύβιος ἕκτῳ.", "st": "6.11b"}, {"sp": "N", "t": "ὅτι ἀπὸ τῆς Ξέρξου διαβάσεως εἰς τὴν Ἑλλάδα καὶ τριάκοντα ἔτεσιν ὕστερον ἀπὸ τούτων τῶν καιρῶν ἀεὶ τῶν κατὰ μέρος προδιευκρινουμένων ἦν καὶ κάλλιστον καὶ τέλειον ἐν τοῖς Ἀννιβιακοῖς καιροῖς, ἀφ’ ὧν ἡμεῖς εἰς ταῦτα τὴν ἐκτροπὴν ἐποιησάμεθα. διὸ καὶ τὸν ὑπὲρ τῆς συστάσεως αὐτοῦ λόγον ἀποδεδωκότες πειρασόμεθα νῦν ἤδη διασαφεῖν ὁποῖόν τι κατ’ ἐκείνους ὑπῆρχε τοὺς καιρούς, ἐν οἷς λειφθέντες τῇ περὶ Κάνναν μάχῃ τοῖς ὅλοις ἔπταισαν πράγμασιν. οὐκ ἀγνοῶ δὲ διότι τοῖς ἐξ αὐτῆς τῆς πολιτείας ὁρμωμένοις ἐλλιπεστέραν φανησόμεθα ποιεῖσθαι τὴν ἐξήγησιν, ἔνια παραλιπόντες τῶν κατὰ μέρος· πᾶν γὰρ ἐπιγινώσκοντες καὶ παντὸς πεῖραν εἰληφότες διὰ τὴν ἐκ παίδων τοῖς ἔθεσι καὶ νομίμοις συντροφίαν οὐ τὸ λεγόμενον θαυμάσουσιν ἀλλὰ τὸ παραλειπόμενον ἐπιζητήσουσιν, οὐδὲ κατὰ πρόθεσιν ὑπολήψονται τὸν γράφοντα παραλιπεῖν τὰς μικρὰς διαφοράς, ἀλλὰ κατ’ ἄγνοιαν παρασιωπᾶν τὰς ἀρχὰς καὶ τὰ συνέχοντα τῶν πραγμάτων. καὶ ῥηθέντα μὲν οὐκ ἂν ἐθαύμαζον ὡς ὄντα μικρὰ καὶ πάρεργα, παραλειπόμενα δ’ ἐπιζητοῦσιν ὡς ἀναγκαῖα, βουλόμενοι δοκεῖν αὐτοὶ πλέον εἰδέναι τῶν συγγραφέων. δεῖ δὲ τὸν ἀγαθὸν κριτὴν οὐκ ἐκ τῶν παραλειπομένων δοκιμάζειν τοὺς γράφοντας, ἀλλ’ ἐκ τῶν λεγομένων, κἂν μὲν ἐν τούτοις τι λαμβάνῃ ψεῦδος, εἰδέναι διότι κἀκεῖνα παραλείπεται δι’ ἄγνοιαν, ἐὰν δὲ πᾶν τὸ λεγόμενον ἀληθὲς ᾖ, συγχωρεῖν διότι κἀκεῖνα παρασιωπᾶται κατὰ κρίσιν, οὐ κατ’ ἄγνοιαν. ταῦτα μὲν οὖν εἰρήσθω μοι πρὸς τοὺς φιλοτιμότερον ἢ δικαιότερον ἐπιτιμῶντας τοῖς συγγραφεῦσιν. ὅτι πᾶν πρᾶγμα σὺν καιρῷ θεωρούμενον ὑγιεῖς λαμβάνει καὶ τὰς συγκαταθέσεις καὶ τὰς ἐπιτιμήσεις· μεταπεσόντος δὲ τούτου καὶ πρὸς τὰς ἄλλας περιστάσεις συγκρινόμενον οὐχ οἷον αἱρετόν, ἀλλ’ οὐδ’ ἀνεκτὸν ἂν φανείη τὸ κράτιστα καὶ ἀληθινώτατα πολλάκις ὑπὸ τῶν συγγραφέων εἰρημένον. ἦν μὲν δὴ τρία μέρη τὰ κρατοῦντα τῆς πολιτείας, ἅπερ εἶπα πρότερον ἅπαντα· οὕτως δὲ πάντα κατὰ μέρος ἴσως καὶ πρεπόντως συνετέτακτο καὶ διῳκεῖτο διὰ τούτων ὥστε μηδένα ποτ’ ἂν εἰπεῖν δύνασθαι βεβαίως μηδὲ τῶν ἐγχωρίων πότερ’ ἀριστοκρατικὸν τὸ πολίτευμα σύμπαν ἢ δημοκρατικὸν ἢ μοναρχικόν. καὶ τοῦτ’ εἰκὸς ἦν πάσχειν. ὅτε μὲν γὰρ εἰς τὴν τῶν ὑπάτων ἀτενίσαιμεν ἐξουσίαν, τελείως μοναρχικὸν ἐφαίνετ’ εἶναι καὶ βασιλικόν, ὅτε δ’ εἰς τὴν τῆς συγκλήτου, πάλιν ἀριστοκρατικόν· καὶ μὴν εἰ τὴν τῶν πολλῶν ἐξουσίαν θεωροίη τις, ἐδόκει σαφῶς εἶναι δημοκρατικόν. ὧν δ’ ἕκαστον εἶδος μερῶν τῆς πολιτείας ἐπεκράτει, καὶ τότε καὶ νῦν ἔτι πλὴν ὀλίγων τινῶν ταῦτ’ ἐστίν.", "st": "6.11"}, {"sp": "N", "t": "οἱ μὲν γὰρ ὕπατοι πρὸ τοῦ μὲν ἐξάγειν τὰ στρατόπεδα παρόντες ἐν Ῥώμῃ πασῶν εἰσι κύριοι τῶν δημοσίων πράξεων. οἵ τε γὰρ ἄρχοντες οἱ λοιποὶ πάντες ὑποτάττονται καὶ πειθαρχοῦσι τούτοις πλὴν τῶν δημάρχων, εἴς τε τὴν σύγκλητον οὗτοι τὰς πρεσβείας ἄγουσι. πρὸς δὲ τοῖς προειρημένοις οὗτοι τὰ κατεπείγοντα τῶν διαβουλίων ἀναδιδόασιν, οὗτοι τὸν ὅλον χειρισμὸν τῶν δογμάτων ἐπιτελοῦσι. καὶ μὴν ὅσα δεῖ διὰ τοῦ δήμου συντελεῖσθαι τῶν πρὸς τὰς κοινὰς πράξεις ἀνηκόντων, τούτοις καθήκει φροντίζειν καὶ συνάγειν τὰς ἐκκλησίας, τούτοις εἰσφέρειν τὰ δόγματα, τούτοις βραβεύειν τὰ δοκοῦντα τοῖς πλείοσι. καὶ μὴν περὶ πολέμου κατασκευῆς καὶ καθόλου τῆς ἐν ὑπαίθροις οἰκονομίας σχεδὸν αὐτοκράτορα τὴν ἐξουσίαν ἔχουσι. καὶ γὰρ ἐπιτάττειν τοῖς συμμαχικοῖς τὸ δοκοῦν, καὶ τοὺς χιλιάρχους καθιστάναι, καὶ διαγράφειν τοὺς στρατιώτας, καὶ διαλέγειν τοὺς ἐπιτηδείους τούτοις ἔξεστι. πρὸς δὲ τοῖς εἰρημένοις ζημιῶσαι τῶν ὑποταττομένων ἐν τοῖς ὑπαίθροις ὃν ἂν βουληθῶσι κύριοι καθεστᾶσιν. ἐξουσίαν δ’ ἔχουσι καὶ δαπανᾶν τῶν δημοσίων ὅσα προθεῖντο, παρεπομένου ταμίου καὶ πᾶν τὸ προσταχθὲν ἑτοίμως ποιοῦντος. ὥστ’ εἰκότως εἰπεῖν ἄν, ὅτε τις εἰς ταύτην ἀποβλέψειε τὴν μερίδα, διότι μοναρχικὸν ἁπλῶς καὶ βασιλικόν ἐστι τὸ πολίτευμα. εἰ δέ τινα τούτων ἢ τῶν λέγεσθαι μελλόντων λήψεται μετάθεσιν ἢ κατὰ τὸ παρὸν ἢ μετά τινα χρόνον, οὐδὲν ἂν εἴη πρὸς τὴν νῦν ὑφ’ ἡμῶν λεγομένην ἀπόφασιν.", "st": "6.12"}, {"sp": "N", "t": "καὶ μὴν ἡ σύγκλητος πρῶτον μὲν ἔχει τὴν τοῦ ταμιείου κυρίαν. καὶ γὰρ τῆς εἰσόδου πάσης αὕτη κρατεῖ καὶ τῆς ἐξόδου παραπλησίως. οὔτε γὰρ εἰς τὰς κατὰ μέρος χρείας οὐδεμίαν ποιεῖν ἔξοδον οἱ ταμίαι δύνανται χωρὶς τῶν τῆς συγκλήτου δογμάτων πλὴν τὴν εἰς τοὺς ὑπάτους· τῆς τε παρὰ πολὺ τῶν ἄλλων ὁλοσχερεστάτης καὶ μεγίστης δαπάνης, ἣν οἱ τιμηταὶ ποιοῦσιν εἰς τὰς ἐπισκευὰς καὶ κατασκευὰς τῶν δημοσίων κατὰ πενταετηρίδα, ταύτης ἡ σύγκλητός ἐστι κυρία, καὶ διὰ ταύτης γίνεται τὸ συγχώρημα τοῖς τιμηταῖς. ὁμοίως ὅσα τῶν ἀδικημάτων τῶν κατ’ Ἰταλίαν προσδεῖται δημοσίας ἐπισκέψεως, λέγω δ’ οἷον προδοσίας, συνωμοσίας, φαρμακείας, δολοφονίας, τῇ συγκλήτῳ μέλει περὶ τούτων. πρὸς δὲ τούτοις, εἴ τις ἰδιώτης ἢ πόλις τῶν κατὰ τὴν Ἰταλίαν διαλύσεως ἢ καὶ νὴ Δί’ ἐπιτιμήσεως ἢ βοηθείας ἢ φυλακῆς προσδεῖται, τούτων πάντων ἐπιμελές ἐστι τῇ συγκλήτῳ. καὶ μὴν εἰ τῶν ἐκτὸς Ἰταλίας πρός τινας ἐξαποστέλλειν δέοι πρεσβείαν τιν’ ἢ διαλύσουσάν τινας ἢ παρακαλέσουσαν ἢ καὶ νὴ Δί’ ἐπιτάξουσαν ἢ παραληψομένην ἢ πόλεμον ἐπαγγέλλουσαν. αὕτη ποιεῖται τὴν πρόνοιαν. ὁμοίως δὲ καὶ τῶν παραγενομένων εἰς Ῥώμην πρεσβειῶν ὡς δέον ἐστὶν ἑκάστοις χρῆσθαι καὶ ὡς δέον ἀποκριθῆναι, πάντα ταῦτα χειρίζεται διὰ τῆς συγκλήτου. πρὸς δὲ τὸν δῆμον καθάπαξ οὐδέν ἐστι τῶν προειρημένων. ἐξ ὧν πάλιν ὁπότε τις ἐπιδημήσαι μὴ παρόντος ὑπάτου, τελείως ἀριστοκρατικὴ φαίνεθ’ ἡ πολιτεία. ὃ δὴ καὶ πολλοὶ τῶν Ἑλλήνων, ὁμοίως δὲ καὶ τῶν βασιλέων, πεπεισμένοι τυγχάνουσι, διὰ τὸ τὰ σφῶν πράγματα σχεδὸν πάντα τὴν σύγκλητον κυροῦν.", "st": "6.13"}, {"sp": "N", "t": "ἐκ δὲ τούτων τίς οὐκ ἂν εἰκότως ἐπιζητήσειε ποία καὶ τίς ποτ’ ἐστὶν ἡ τῷ δήμῳ καταλειπομένη μερὶς ἐν τῷ πολιτεύματι, τῆς μὲν συγκλήτου τῶν κατὰ μέρος ὧν εἰρήκαμεν κυρίας ὑπαρχούσης, τὸ δὲ μέγιστον, ὑπ’ αὐτῆς καὶ τῆς εἰσόδου καὶ τῆς ἐξόδου χειριζομένης ἁπάσης, τῶν δὲ στρατηγῶν ὑπάτων πάλιν αὐτοκράτορα μὲν ἐχόντων δύναμιν περὶ τὰς τοῦ πολέμου παρασκευάς, αὐτοκράτορα δὲ τὴν ἐν τοῖς ὑπαίθροις ἐξουσίαν; οὐ μὴν ἀλλὰ καταλείπεται μερὶς καὶ τῷ δήμῳ, καὶ καταλείπεταί γε βαρυτάτη. τιμῆς γάρ ἐστι καὶ τιμωρίας ἐν τῇ πολιτείᾳ μόνος ὁ δῆμος κύριος, οἷς συνέχονται μόνοις καὶ δυναστεῖαι καὶ πολιτεῖαι καὶ συλλήβδην πᾶς ὁ τῶν ἀνθρώπων βίος. παρ’ οἷς γὰρ ἢ μὴ γινώσκεσθαι συμβαίνει τὴν τοιαύτην διαφορὰν ἢ γινωσκομένην χειρίζεσθαι κακῶς, παρὰ τούτοις οὐδὲν οἷόν τε κατὰ λόγον διοικεῖσθαι τῶν ὑφεστώτων· πῶς γὰρ εἰκὸς ἐν ἴσῃ τιμῇ [ὄντων] τῶν ἀγαθῶν τοῖς κακοῖς; κρίνει μὲν οὖν ὁ δῆμος καὶ διαφόρου πολλάκις, ὅταν ἀξιόχρεων ᾖ τὸ τίμημα τῆς ἀδικίας, καὶ μάλιστα τοὺς τὰς ἐπιφανεῖς ἐσχηκότας ἀρχάς. θανάτου δὲ κρίνει μόνος. καὶ γίνεταί τι περὶ ταύτην τὴν χρείαν παρ’ αὐτοῖς ἄξιον ἐπαίνου καὶ μνήμης. τοῖς γὰρ θανάτου κρινομένοις, ἐπὰν καταδικάζωνται, δίδωσι τὴν ἐξουσίαν τὸ παρ’ αὐτοῖς ἔθος ἀπαλλάττεσθαι φανερῶς, κἂν ἔτι μία λείπηται φυλὴ τῶν ἐπικυρουσῶν τὴν κρίσιν ἀψηφοφόρητος, ἑκούσιον ἑαυτοῦ καταγνόντα φυγαδείαν. ἔστι δ’ ἀσφάλεια τοῖς φεύγουσιν ἔν τε τῇ Νεαπολιτῶν καὶ Πραινεστίνων, ἔτι δὲ Τιβουρίνων πόλει, καὶ ταῖς ἄλλαις, πρὸς ἃς ἔχουσιν ὅρκια. καὶ μὴν τὰς ἀρχὰς ὁ δῆμος δίδωσι τοῖς ἀξίοις· ὅπερ ἐστὶ κάλλιστον ἆθλον ἐν πολιτείᾳ καλοκἀγαθίας. ἔχει δὲ τὴν κυρίαν καὶ περὶ τῆς τῶν νόμων δοκιμασίας, καὶ τὸ μέγιστον, ὑπὲρ εἰρήνης οὗτος βουλεύεται καὶ πολέμου. καὶ μὴν περὶ συμμαχίας καὶ διαλύσεως καὶ συνθηκῶν οὗτός ἐστιν ὁ βεβαιῶν ἕκαστα τούτων καὶ κύρια ποιῶν ἢ τοὐναντίον. ὥστε πάλιν ἐκ τούτων εἰκότως ἄν τιν’ εἰπεῖν ὅτι μεγίστην ὁ δῆμος ἔχει μερίδα καὶ δημοκρατικόν ἐστι τὸ πολίτευμα.", "st": "6.14"}, {"sp": "N", "t": "τίνα μὲν οὖν τρόπον διῄρηται τὰ τῆς πολιτείας εἰς ἕκαστον εἶδος εἴρηται· τίνα δὲ τρόπον ἀντιπράττειν βουληθέντα καὶ συνεργεῖν ἀλλήλοις πάλιν ἕκαστα τῶν μερῶν δύναται νῦν ῥηθήσεται. ὁ μὲν γὰρ ὕπατος, ἐπειδὰν τυχὼν τῆς προειρημένης ἐξουσίας ὁρμήσῃ μετὰ τῆς δυνάμεως, δοκεῖ μὲν αὐτοκράτωρ εἶναι πρὸς τὴν τῶν προκειμένων συντέλειαν, προσδεῖται δὲ τοῦ δήμου καὶ τῆς συγκλήτου, καὶ χωρὶς τούτων ἐπὶ τέλος ἄγειν τὰς πράξεις οὐχ ἱκανός ἐστι. δῆλον γὰρ ὡς δεῖ μὲν ἐπιπέμπεσθαι τοῖς στρατοπέδοις ἀεὶ τὰς χορηγίας· ἄνευ δὲ τοῦ τῆς συγκλήτου βουλήματος οὔτε σῖτος οὔθ’ ἱματισμὸς οὔτ’ ὀψώνια δύναται χορηγεῖσθαι τοῖς στρατοπέδοις, ὥστ’ ἀπράκτους γίνεσθαι τὰς ἐπιβολὰς τῶν ἡγουμένων, ἐθελοκακεῖν καὶ κωλυσιεργεῖν προθεμένης τῆς συγκλήτου. καὶ μὴν τό γ’ ἐπιτελεῖς ἢ μὴ γίνεσθαι τὰς ἐπινοίας καὶ προθέσεις τῶν στρατηγῶν ἐν τῇ συγκλήτῳ κεῖται· τοῦ γὰρ ἐπαποστεῖλαι στρατηγὸν ἕτερον, ἐπειδὰν ἐνιαύσιος διέλθῃ χρόνος, ἢ τὸν ὑπάρχοντα ποιεῖν ἐπίμονον, ἔχει τὴν κυρίαν αὕτη. καὶ μὴν τὰς ἐπιτυχίας τῶν ἡγουμένων ἐκτραγῳδῆσαι καὶ συναυξῆσαι καὶ πάλιν ἀμαυρῶσαι καὶ ταπεινῶσαι τὸ συνέδριον ἔχει τὴν δύναμιν· τοὺς γὰρ προσαγορευομένους παρ’ αὐτοῖς θριάμβους, δι’ ὧν ὑπὸ τὴν ὄψιν ἄγεται τοῖς πολίταις ὑπὸ τῶν στρατηγῶν ἡ τῶν κατειργασμένων πραγμάτων ἐνάργεια, τούτους οὐ δύνανται χειρίζειν, ὡς πρέπει, ποτὲ δὲ τὸ παράπαν οὐδὲ συντελεῖν, ἐὰν μὴ τὸ συνέδριον συγκατάθηται καὶ δῷ τὴν εἰς ταῦτα δαπάνην. τοῦ γε μὴν δήμου στοχάζεσθαι καὶ λίαν αὐτοῖς ἀναγκαῖόν ἐστι, κἂν ὅλως ἀπὸ τῆς οἰκείας τύχωσι πολὺν τόπον ἀφεστῶτες· ὁ γὰρ τὰς διαλύσεις καὶ συνθήκας ἀκύρους καὶ κυρίας ποιῶν, ὡς ἐπάνω προεῖπον, οὗτός ἐστιν. τὸ δὲ μέγιστον ἀποτιθεμένους τὴν ἀρχὴν ἐν τούτῳ δεῖ τὰς εὐθύνας ὑπέχειν τῶν πεπραγμένων. ὥστε κατὰ μηδένα τρόπον ἀσφαλὲς εἶναι τοῖς στρατηγοῖς ὀλιγωρεῖν μήτε τῆς συγκλήτου μήτε τῆς τοῦ πλήθους εὐνοίας.", "st": "6.15"}, {"sp": "N", "t": "ἥ γε μὴν σύγκλητος πάλιν, ἡ τηλικαύτην ἔχουσα δύναμιν, πρῶτον μὲν ἐν τοῖς κοινοῖς πράγμασιν ἀναγκάζεται προσέχειν τοῖς πολλοῖς καὶ στοχάζεσθαι τοῦ δήμου, τὰς δ’ ὁλοσχερεστάτας καὶ μεγίστας ζητήσεις καὶ διορθώσεις τῶν ἁμαρτανομένων κατὰ τῆς πολιτείας, οἷς θάνατος ἀκολουθεῖ τὸ πρόστιμον, οὐ δύναται συντελεῖν, ἂν μὴ συνεπικυρώσῃ τὸ προβεβουλευμένον ὁ δῆμος. ὁμοίως δὲ καὶ περὶ τῶν εἰς ταύτην ἀνηκόντων· ἐὰν γάρ τις εἰσφέρῃ νόμον, ἢ τῆς ἐξουσίας ἀφαιρούμενός τι τῆς ὑπαρχούσης τῇ συγκλήτῳ κατὰ τοὺς ἐθισμοὺς ἢ τὰς προεδρίας καὶ τιμὰς καταλύων αὐτῶν ἢ καὶ νὴ Δία ποιῶν ἐλαττώματα περὶ τοὺς βίους. πάντων ὁ δῆμος γίνεται τῶν τοιούτων καὶ θεῖναι καὶ μὴ κύριος. τὸ δὲ συνέχον, ἐὰν εἷς ἐνίστηται τῶν δημάρχων, οὐχ οἷον ἐπὶ τέλος ἄγειν τι δύναται τῶν διαβουλίων ἡ σύγκλητος, ἀλλ’ οὐδὲ συνεδρεύειν ἢ συμπορεύεσθαι τὸ παράπαν — ὀφείλουσι δ’ ἀεὶ ποιεῖν οἱ δήμαρχοι τὸ δοκοῦν τῷ δήμῳ καὶ μάλιστα στοχάζεσθαι τῆς τούτου βουλήσεως — διὸ πάντων τῶν προειρημένων χάριν δέδιε τοὺς πολλοὺς καὶ προσέχει τῷ δήμῳ τὸν νοῦν ἡ σύγκλητος.", "st": "6.16"}, {"sp": "N", "t": "ὁμοίως γε μὴν πάλιν ὁ δῆμος ὑπόχρεώς ἐστι τῇ συγκλήτῳ, καὶ στοχάζεσθαι ταύτης ὀφείλει καὶ κοινῇ καὶ κατ’ ἰδίαν. πολλῶν γὰρ ἔργων ὄντων τῶν ἐκδιδομένων ὑπὸ τῶν τιμητῶν διὰ πάσης Ἰταλίας εἰς τὰς ἐπισκευὰς καὶ κατασκευὰς τῶν δημοσίων, ἅ τις οὐκ ἂν ἐξαριθμήσαιτο ῥᾳδίως, πολλῶν δὲ ποταμῶν, λιμένων, κηπίων, μετάλλων, χώρας, συλλήβδην ὅσα πέπτωκεν ὑπὸ τὴν Ῥωμαίων δυναστείαν, πάντα χειρίζεσθαι συμβαίνει τὰ προειρημένα διὰ τοῦ πλήθους, καὶ σχεδὸν ὡς ἔπος εἰπεῖν πάντας ἐνδεδέσθαι ταῖς ὠναῖς καὶ ταῖς ἐργασίαις ταῖς ἐκ τούτων· οἱ μὲν γὰρ ἀγοράζουσι παρὰ τῶν τιμητῶν αὐτοὶ τὰς ἐκδόσεις, οἱ δὲ κοινωνοῦσι τούτοις, οἱ δ’ ἐγγυῶνται τοὺς ἠγορακότας, οἱ δὲ τὰς οὐσίας διδόασι περὶ τούτων εἰς τὸ δημόσιον. ἔχει δὲ περὶ πάντων τῶν προειρημένων τὴν κυρίαν τὸ συνέδριον· καὶ γὰρ χρόνον δύναται δοῦναι καὶ συμπτώματος γενομένου κουφίσαι καὶ τὸ παράπαν ἀδυνάτου τινὸς συμβάντος ἀπολῦσαι τῆς ἐργωνίας. καὶ πολλὰ δή τιν’ ἐστίν, ἐν οἷς καὶ βλάπτει μεγάλα καὶ πάλιν ὠφελεῖ τοὺς τὰ δημόσια χειρίζοντας ἡ σύγκλητος· ἡ γὰρ ἀναφορὰ τῶν προειρημένων γίνεται πρὸς ταύτην. τὸ δὲ μέγιστον, ἐκ ταύτης ἀποδίδονται κριταὶ τῶν πλείστων καὶ τῶν δημοσίων καὶ τῶν ἰδιωτικῶν συναλλαγμάτων, ὅσα μέγεθος ἔχει τῶν ἐγκλημάτων. διὸ πάντες εἰς τὴν ταύτης πίστιν ἐνδεδεμένοι, καὶ δεδιότες τὸ τῆς χρείας ἄδηλον, εὐλαβῶς ἔχουσι πρὸς τὰς ἐνστάσεις καὶ τὰς ἀντιπράξεις τῶν τῆς συγκλήτου βουλημάτων. ὁμοίως δὲ καὶ πρὸς τὰς τῶν ὑπάτων ἐπιβολὰς δυσχερῶς ἀντιπράττουσι διὰ τὸ κατ’ ἰδίαν καὶ κοινῇ πάντας ἐν τοῖς ὑπαίθροις ὑπὸ τὴν ἐκείνων πίπτειν ἐξουσίαν.", "st": "6.17"}, {"sp": "N", "t": "τοιαύτης δ’ οὔσης τῆς ἑκάστου τῶν μερῶν δυνάμεως εἰς τὸ καὶ βλάπτειν καὶ συνεργεῖν ἀλλήλοις, πρὸς πάσας συμβαίνει τὰς περιστάσεις δεόντως ἔχειν τὴν ἁρμογὴν αὐτῶν, ὥστε μὴ οἷόν τ’ εἶναι ταύτης εὑρεῖν ἀμείνω πολιτείας σύστασιν. ὅταν μὲν γάρ τις ἔξωθεν κοινὸς φόβος ἐπιστὰς ἀναγκάσῃ σφᾶς συμφρονεῖν καὶ συνεργεῖν ἀλλήλοις, τηλικαύτην καὶ τοιαύτην συμβαίνει γίνεσθαι τὴν δύναμιν τοῦ πολιτεύματος ὥστε μήτε παραλείπεσθαι τῶν δεόντων μηδέν, ἅτε περὶ τὸ προσπεσὸν ἀεὶ πάντων ὁμοῦ ταῖς ἐπινοίαις ἁμιλλωμένων, μήτε τὸ κριθὲν ὑστερεῖν τοῦ καιροῦ, κοινῇ καὶ κατ’ ἰδίαν ἑκάστου συνεργοῦντος πρὸς τὴν τοῦ προκειμένου συντέλειαν. διόπερ ἀνυπόστατον συμβαίνει γίνεσθαι καὶ παντὸς ἐφικνεῖσθαι τοῦ κριθέντος τὴν ἰδιότητα τοῦ πολιτεύματος. ὅταν γε μὴν πάλιν ἀπολυθέντες τῶν ἐκτὸς φόβων ἐνδιατρίβωσι ταῖς εὐτυχίαις καὶ περιουσίαις ταῖς ἐκ τῶν κατορθωμάτων, ἀπολαύοντες τῆς εὐδαιμονίας, καὶ ὑποκολακευόμενοι καὶ ῥᾳθυμοῦντες τρέπωνται πρὸς ὕβριν καὶ πρὸς ὑπερηφανίαν, ὃ δὴ φιλεῖ γίνεσθαι, τότε καὶ μάλιστα συνιδεῖν ἔστιν αὐτὸ παρ’ αὑτοῦ ποριζόμενον τὸ πολίτευμα τὴν βοήθειαν. ἐπειδὰν γὰρ ἐξοιδοῦν τι τῶν μερῶν φιλονεικῇ καὶ πλέον τοῦ δέοντος ἐπικρατῇ, δῆλον ὡς οὐδενὸς αὐτοτελοῦς ὄντος κατὰ τὸν ἄρτι λόγον, ἀντισπᾶσθαι δὲ καὶ παραποδίζεσθαι δυναμένης τῆς ἑκάστου προθέσεως ὑπ’ ἀλλήλων, οὐδὲν ἐξοιδεῖ τῶν μερῶν οὐδ’ ὑπερφρονεῖ. πάντα γὰρ ἐμμένει τοῖς ὑποκειμένοις τὰ μὲν κωλυόμενα τῆς ὁρμῆς, τὰ δ’ ἐξ ἀρχῆς δεδιότα τὴν ἐκ τοῦ πέλας ἐπίστασιν. ὁ δὲ δικτάτωρ ταύτην ἔχει τὴν διαφορὰν τῶν ὑπάτων· τῶν μὲν γὰρ ὑπάτων ἑκατέρῳ δώδεκα πελέκεις ἀκολουθοῦσι, τούτῳ δ’ εἴκοσι καὶ τέτταρες, κἀκεῖνοι μὲν ἐν πολλοῖς προσδέονται τῆς συγκλήτου πρὸς τὸ συντελεῖν τὰς ἐπιβολάς, οὗτος δ’ ἔστιν αὐτοκράτωρ στρατηγός, οὗ κατασταθέντος παραχρῆμα διαλύεσθαι συμβαίνει πάσας τὰς ἀρχὰς ἐν τῇ Ῥώμῃ πλὴν τῶν δημάρχων. οὐ μὴν ἀλλὰ περὶ μὲν τούτων ἐν ἄλλοις ἀκριβεστέραν ποιησόμεθα τὴν διαστολήν.", "st": "6.18"}, {"sp": "N", "t": "ἐπειδὰν ἀποδείξωσι τοὺς ὑπάτους, μετὰ ταῦτα χιλιάρχους καθιστᾶσι, τετταρασκαίδεκα μὲν ἐκ τῶν πέντ’ ἐνιαυσίους ἐχόντων ἤδη στρατείας, δέκα δ’ ἄλλους σὺν τούτοις ἐκ τῶν δέκα. τῶν λοιπῶν τοὺς μὲν ἱππεῖς δέκα, τοὺς δὲ πεζοὺς ἓξ καὶ δέκα δεῖ στρατείας τελεῖν κατ’ ἀνάγκην ἐν τοῖς τετταράκοντα καὶ ἓξ ἔτεσιν ἀπὸ γενεᾶς πλὴν τῶν ὑπὸ τὰς τετρακοσίας δραχμὰς τετιμημένων· τούτους δὲ παριᾶσι πάντας εἰς τὴν ναυτικὴν χρείαν. ἐὰν δέ ποτε κατεπείγῃ τὰ τῆς περιστάσεως, ὀφείλουσιν οἱ πεζοὶ στρατεύειν εἴκοσι στρατείας ἐνιαυσίους. πολιτικὴν δὲ λαβεῖν ἀρχὴν οὐκ ἔξεστιν οὐδενὶ πρότερον, ἐὰν μὴ δέκα στρατείας ἐνιαυσίους ᾖ τετελεκώς. ἐὰν δὲ μέλλωσι ποιεῖσθαι τὴν καταγραφὴν τῶν στρατιωτῶν οἱ τὰς ὑπάτους ἔχοντες ἀρχάς, προλέγουσιν ἐν τῷ δήμῳ τὴν ἡμέραν, ἐν ᾗ δεήσει παραγενέσθαι τοὺς ἐν ταῖς ἡλικίαις Ῥωμαίους ἅπαντας. ποιοῦσι δὲ τοῦτο καθ’ ἕκαστον ἐνιαυτόν. τῆς δ’ ἡμέρας ἐπελθούσης καὶ τῶν στρατευσίμων παραγενομένων εἰς τὴν Ῥώμην, καὶ μετὰ ταῦθ’ ἁθροισθέντων εἰς τὸ Καπετώλιον, διεῖλον σφᾶς αὐτοὺς οἱ νεώτεροι τῶν χιλιάρχων, καθάπερ ἂν ὑπὸ τοῦ δήμου κατασταθῶσιν ἢ τῶν στρατηγῶν, εἰς τέτταρα μέρη διὰ τὸ τέτταρα παρ’ αὐτοῖς στρατόπεδα τὴν ὁλοσχερῆ καὶ πρώτην διαίρεσιν τῶν δυνάμεων ποιεῖσθαι. καὶ τοὺς μὲν πρώτους κατασταθέντας τέτταρας εἰς τὸ πρῶτον καλούμενον στρατόπεδον ἔνειμαν, τοὺς δ’ ἑξῆς τρεῖς εἰς τὸ δεύτερον, τοὺς δ’ ἑπομένους τούτοις τέτταρας εἰς τὸ τρίτον, τρεῖς δὲ τοὺς τελευταίους εἰς τὸ τέταρτον. τῶν δὲ πρεσβυτέρων δύο μὲν τοὺς πρώτους εἰς τὸ πρῶτον, τρεῖς δὲ τοὺς δευτέρους εἰς τὸ δεύτερον τιθέασι στρατόπεδον, δύο δὲ τοὺς ἑξῆς εἰς τὸ τρίτον, τρεῖς δὲ τοὺς τελευταίους εἰς τὸ τέταρτον [τῶν πρεσβυτέρων].", "st": "6.19"}, {"sp": "N", "t": "γενομένης δὲ τῆς διαιρέσεως καὶ καταστάσεως τῶν χιλιάρχων τοιαύτης ὥστε πάντα τὰ στρατόπεδα τοὺς ἴσους ἔχειν ἄρχοντας, μετὰ ταῦτα καθίσαντες χωρὶς ἀλλήλων κατὰ στρατόπεδον κληροῦσι τὰς φυλὰς κατὰ μίαν καὶ προσκαλοῦνται τὴν ἀεὶ λαχοῦσαν. ἐκ δὲ ταύτης ἐκλέγουσι τῶν νεανίσκων τέτταρας ἐπιεικῶς τοὺς παραπλησίους ταῖς ἡλικίαις καὶ ταῖς ἕξεσι. προσαχθέντων δὲ τούτων λαμβάνουσι πρῶτοι τὴν ἐκλογὴν οἱ τοῦ πρώτου στρατοπέδου, δεύτεροι δ’ οἱ τοῦ δευτέρου, τρίτοι δ’ οἱ τοῦ τρίτου, τελευταῖοι δ’ οἱ τοῦ τετάρτου. πάλιν δ’ ἄλλων τεττάρων προσαχθέντων λαμβάνουσι πρῶτοι τὴν αἵρεσιν οἱ τοῦ δευτέρου στρατοπέδου καὶ ἑξῆς οὕτως, τελευταῖοι δ’ οἱ τοῦ πρώτου. μετὰ δὲ ταῦτα πάλιν ἄλλων τεττάρων προσαχθέντων πρῶτοι λαμβάνουσιν οἱ τοῦ τρίτου στρατοπέδου, τελευταῖοι δ’ οἱ τοῦ δευτέρου. [καὶ] αἰεὶ κατὰ λόγον οὕτως ἐκ περιόδου τῆς ἐκλογῆς γινομένης παραπλησίους συμβαίνει λαμβάνεσθαι τοὺς ἄνδρας εἰς ἕκαστον τῶν στρατοπέδων. ὅταν δ’ ἐκλέξωσι τὸ προκείμενον πλῆθος — τοῦτο δ’ ἔστιν ὁτὲ μὲν εἰς ἕκαστον στρατόπεδον πεζοὶ τετρακισχίλιοι καὶ διακόσιοι, ποτὲ δὲ πεντακισχίλιοι, ἐπειδὰν μείζων τις αὐτοῖς προφαίνηται κίνδυνος — μετὰ ταῦτα τοὺς ἱππεῖς τὸ μὲν παλαιὸν ὑστέρους εἰώθεσαν δοκιμάζειν ἐπὶ τοῖς τετρακισχιλίοις διακοσίοις, νῦν δὲ προτέρους, πλουτίνδην αὐτῶν γεγενημένης ὑπὸ τοῦ τιμητοῦ τῆς ἐκλογῆς· καὶ ποιοῦσι τριακοσίους εἰς ἕκαστον στρατόπεδον.", "st": "6.20"}, {"sp": "N", "t": "Ἐπιτελεσθείσης δὲ τῆς καταγραφῆς τὸν προειρημένον τρόπον, ἁθροίσαντες τοὺς ἐπειλεγμένους οἱ προσήκοντες τῶν χιλιάρχων καθ’ ἕκαστον στρατόπεδον, καὶ λαβόντες ἐκ πάντων ἕνα τὸν ἐπιτηδειότατον, ἐξορκίζουσιν ἦ μὴν πειθαρχήσειν καὶ ποιήσειν τὸ προσταττόμενον ὑπὸ τῶν ἀρχόντων κατὰ δύναμιν. οἱ δὲ λοιποὶ πάντες ὀμνύουσι καθ’ ἕνα προπορευόμενοι, τοῦτ’ αὐτὸ δηλοῦντες ὅτι ποιήσουσι πάντα καθάπερ ὁ πρῶτος. κατὰ δὲ τοὺς αὐτοὺς καιροὺς οἱ τὰς ὑπάτους ἀρχὰς ἔχοντες παραγγέλλουσι τοῖς ἄρχουσι τοῖς ἀπὸ τῶν συμμαχίδων πόλεων τῶν ἐκ τῆς Ἰταλίας, ἐξ ὧν ἂν βούλωνται συστρατεύειν τοὺς συμμάχους, διασαφοῦντες τὸ πλῆθος καὶ τὴν ἡμέραν καὶ τὸν τόπον, εἰς ὃν δεήσει παρεῖναι τοὺς κεκριμένους. αἱ δὲ πόλεις παραπλησίαν ποιησάμεναι τῇ προειρημένῃ τὴν ἐκλογὴν καὶ τὸν ὅρκον ἐκπέμπουσιν, ἄρχοντα συστήσασαι καὶ μισθοδότην. οἱ δ’ ἐν τῇ Ῥώμῃ χιλίαρχοι μετὰ τὸν ἐξορκισμὸν παραγγείλαντες ἡμέραν ἑκάστῳ στρατοπέδῳ καὶ τόπον, εἰς ὃν δεήσει παρεῖναι χωρὶς τῶν ὅπλων, τότε μὲν ἀφῆκαν. παραγενομένων δ’ εἰς τὴν ταχθεῖσαν ἡμέραν διαλέγουσι τῶν ἀνδρῶν τοὺς μὲν νεωτάτους καὶ πενιχροτάτους εἰς τοὺς γροσφομάχους, τοὺς δ’ ἑξῆς τούτοις εἰς τοὺς ἁστάτους καλουμένους, τοὺς δ’ ἀκμαιοτάτους ταῖς ἡλικίαις εἰς τοὺς πρίγκιπας, τοὺς δὲ πρεσβυτάτους εἰς τοὺς τριαρίους. αὗται γάρ εἰσι καὶ τοσαῦται διαφοραὶ παρὰ Ῥωμαίοις καὶ τῶν ὀνομασιῶν καὶ τῶν ἡλικιῶν, ἔτι δὲ τῶν καθοπλισμῶν ἐν ἑκάστῳ στρατοπέδῳ. διαιροῦσι δ’ αὐτοὺς τὸν τρόπον τοῦτον ὥστ’ εἶναι τοὺς μὲν πρεσβυτάτους καὶ τριαρίους προσαγορευομένους ἑξακοσίους, τοὺς δὲ πρίγκιπας χιλίους καὶ διακοσίους, ἴσους δὲ τούτοις τοὺς ἁστάτους, τοὺς δὲ λοιποὺς καὶ νεωτάτους γροσφοφόρους. ἐὰν δὲ πλείους τῶν τετρακισχιλίων ὦσι, κατὰ λόγον ποιοῦνται τὴν διαίρεσιν πλὴν τῶν τριαρίων. τούτους αἰεὶ τοὺς ἴσους.", "st": "6.21"}, {"sp": "N", "t": "καὶ τοῖς μὲν νεωτάτοις παρήγγειλαν μάχαιραν φορεῖν καὶ γρόσφους καὶ πάρμην. ἡ δὲ πάρμη καὶ δύναμιν ἔχει τῇ κατασκευῇ καὶ μέγεθος ἀρκοῦν πρὸς ἀσφάλειαν· περιφερὴς γὰρ οὖσα τῷ σχήματι τρίπεδον ἔχει τὴν διάμετρον. προσεπικοσμεῖται δὲ καὶ λιτῷ περικεφαλαίῳ· ποτὲ δὲ λυκείαν ἤ τι τῶν τοιούτων ἐπιτίθεται, σκέπης ἅμα καὶ σημείου χάριν, ἵνα τοῖς κατὰ μέρος ἡγεμόσι προκινδυνεύοντες ἐρρωμένως καὶ μὴ διάδηλοι γίνωνται. τὸ δὲ τῶν γρόσφων βέλος ἔχει τῷ μὲν μήκει τὸ ξύλον ὡς ἐπίπαν δίπηχυ, τῷ δὲ πάχει δακτυλιαῖον, τὸ δὲ κέντρον σπιθαμιαῖον, κατὰ τοσοῦτον ἐπὶ λεπτὸν ἐξεληλασμένον καὶ συνωξυσμένον ὥστε κατ’ ἀνάγκην εὐθέως ἀπὸ τῆς πρώτης ἐμβολῆς κάμπτεσθαι καὶ μὴ δύνασθαι τοὺς πολεμίους ἀντιβάλλειν· εἰ δὲ μή, κοινὸν γίνεται τὸ βέλος.", "st": "6.22"}, {"sp": "N", "t": "τοῖς γε μὴν δευτέροις μὲν κατὰ τὴν ἡλικίαν, ἁστάτοις δὲ προσαγορευομένοις, παρήγγειλαν φέρειν πανοπλίαν. ἔστι δ’ ἡ Ῥωμαϊκὴ πανοπλία πρῶτον μὲν θυρεός — οὗ τὸ μὲν πλάτος ἐστὶ τῆς κυρτῆς ἐπιφανείας πένθ’ ἡμιποδίων, τὸ δὲ μῆκος ποδῶν τεττάρων, τὸ δ’ ἐπ’ ἴτυος πάχος ἔτι καὶ παλαιστιαῖον — ἐκ διπλοῦ σανιδώματος ταυροκόλλῃ πεπηγώς, ὀθονίῳ, μετὰ δὲ ταῦτα μοσχείῳ δέρματι περιείληται τὴν ἐκτὸς ἐπιφάνειαν. ἔχει δὲ περὶ τὴν ἴτυν ἐκ τῶν ἄνωθεν καὶ κάτωθεν μερῶν σιδηροῦν σιάλωμα, δι’ οὗ τάς τε καταφορὰς τῶν μαχαιρῶν ἀσφαλίζεται καὶ τὰς πρὸς τὴν γῆν ἐξερείσεις. προσήρμοσται δ’ αὐτῷ καὶ σιδηρᾶ κόγχος, ἣ τὰς ὁλοσχερεῖς ἀποστέγει πληγὰς λίθων καὶ σαρισῶν καὶ καθόλου βιαίων βελῶν. ἅμα δὲ τῷ θυρεῷ μάχαιρα· ταύτην δὲ περὶ τὸν δεξιὸν φέρει μηρόν, καλοῦσι δ’ αὐτὴν Ἰβηρικήν. ἔχει δ’ αὕτη κέντημα διάφορον καὶ καταφορὰν ἐξ ἀμφοῖν τοῖν μεροῖν βίαιον διὰ τὸ τὸν ὀβελίσκον αὐτῆς ἰσχυρὸν καὶ μόνιμον εἶναι. πρὸς δὲ τούτοις ὑσσοὶ δύο καὶ περικεφαλαία χαλκῆ καὶ προκνημίς. τῶν δ’ ὑσσῶν εἰσιν οἱ μὲν παχεῖς, οἱ δὲ λεπτοί. τῶν δὲ στερεωτέρων οἱ μὲν στρογγύλοι παλαιστιαίαν ἔχουσι τὴν διάμετρον, οἱ δὲ τετράγωνοι τὴν πλευράν. οἵ γε μὴν λεπτοὶ σιβυνίοις ἐοίκασι συμμέτροις, οὓς φοροῦσι μετὰ τῶν προειρημένων. ἁπάντων δὲ τούτων τοῦ ξύλου τὸ μῆκός ἐστιν ὡς τρεῖς πήχεις. προσήρμοσται δ’ ἑκάστοις βέλος σιδηροῦν ἀγκιστρωτόν, ἴσον ἔχον τὸ μῆκος τοῖς ξύλοις· οὗ τὴν ἔνδεσιν καὶ τὴν χρείαν οὕτως ἀσφαλίζονται βεβαίως, ἕως μέσων τῶν ξύλων ἐνδιδέντες καὶ πυκναῖς ταῖς λαβίσι καταπερονῶντες, ὥστε πρότερον ἢ τὸν δεσμὸν ἐν ταῖς χρείαις ἀναχαλασθῆναι τὸν σίδηρον θραύεσθαι, καίπερ ὄντα τὸ πάχος ἐν τῷ πυθμένι καὶ τῇ πρὸς τὸ ξύλον συναφῇ τριῶν ἡμιδακτυλίων· ἐπὶ τοσοῦτον καὶ τοιαύτην πρόνοιαν ποιοῦνται τῆς ἐνδέσεως. ἐπὶ δὲ πᾶσι τούτοις προσεπικοσμοῦνται πτερίνῳ στεφάνῳ καὶ πτεροῖς φοινικοῖς ἢ μέλασιν ὀρθοῖς τρισίν, ὡς πηχυαίοις τὸ μέγεθος, ὧν προστεθέντων κατὰ κορυφὴν ἅμα τοῖς ἄλλοις ὅπλοις ὁ μὲν ἀνὴρ φαίνεται διπλάσιος ἑαυτοῦ κατὰ τὸ μέγεθος, ἡ δ’ ὄψις καλὴ καὶ καταπληκτικὴ τοῖς ἐναντίοις. οἱ μὲν οὖν πολλοὶ προσλαβόντες χάλκωμα σπιθαμιαῖον πάντῃ πάντως, ὃ προστίθενται μὲν πρὸ τῶν στέρνων, καλοῦσι δὲ καρδιοφύλακα, τελείαν ἔχουσι τὴν καθόπλισιν· οἱ δ’ ὑπὲρ τὰς μυρίας τιμώμενοι δραχμὰς ἀντὶ τοῦ καρδιοφύλακος σὺν τοῖς ἄλλοις ἁλυσιδωτοὺς περιτίθενται θώρακας. ὁ δ’ αὐτὸς τρόπος τῆς καθοπλίσεώς ἐστι καὶ περὶ τοὺς πρίγκιπας καὶ τριαρίους, πλὴν ἀντὶ τῶν ὑσσῶν οἱ τριάριοι δόρατα φοροῦσιν.", "st": "6.23"}, {"sp": "N", "t": "ἐξ ἑκάστου δὲ τῶν προειρημένων γενῶν πλὴν τῶν νεωτάτων ἐξέλεξαν ταξιάρχους ἀριστίνδην δέκα. μετὰ δὲ τούτους ἑτέραν ἐκλογὴν ἄλλων δέκα ποιοῦνται. καὶ τούτους μὲν ἅπαντας προσηγόρευσαν ταξιάρχους, ὧν ὁ πρῶτος αἱρεθεὶς καὶ συνεδρίου κοινωνεῖ· προσεκλέγονται δ’ οὗτοι πάλιν αὐτοὶ τοὺς ἴσους οὐραγούς. ἑξῆς δὲ τούτοις μετὰ τῶν ταξιάρχων διεῖλον τὰς ἡλικίας, ἑκάστην εἰς δέκα μέρη, πλὴν τῶν γροσφομάχων· καὶ προσένειμαν ἑκάστῳ μέρει τῶν ἐκλεχθέντων ἀνδρῶν δύ’ ἡγεμόνας καὶ δύ’ οὐραγούς. τῶν δὲ γροσφομάχων τοὺς ἐπιβάλλοντας κατὰ τὸ πλῆθος ἴσους ἐπὶ πάντα τὰ μέρη διένειμαν. καὶ τὸ μὲν μέρος ἕκαστον ἐκάλεσαν καὶ τάγμα καὶ σπεῖραν καὶ σημαίαν, τοὺς δ’ ἡγεμόνας κεντυρίωνας καὶ ταξιάρχους. οὗτοι δὲ καθ’ ἑκάστην σπεῖραν ἐκ τῶν καταλειπομένων ἐξέλεξαν αὐτοὶ δύο τοὺς ἀκμαιοτάτους καὶ γενναιοτάτους ἄνδρας σημαιαφόρους. δύο δὲ καθ’ ἕκαστον τάγμα ποιοῦσιν ἡγεμόνας εἰκότως· ἀδήλου γὰρ ὄντος καὶ τοῦ ποιῆσαι καὶ τοῦ παθεῖν τι τὸν ἡγεμόνα, τῆς πολεμικῆς χρείας οὐκ ἐπιδεχομένης πρόφασιν, οὐδέποτε βούλονται τὴν σπεῖραν χωρὶς ἡγεμόνος εἶναι καὶ προστάτου. παρόντων μὲν οὖν ἀμφοτέρων ὁ μὲν πρῶτος αἱρεθεὶς ἡγεῖται τοῦ δεξιοῦ μέρους τῆς σπείρας, ὁ δὲ δεύτερος τῶν εὐωνύμων ἀνδρῶν τῆς σημαίας ἔχει τὴν ἡγεμονίαν· μὴ παρόντων δ’ ὁ καταλειπόμενος ἡγεῖται πάντων. βούλονται δ’ εἶναι τοὺς ταξιάρχους οὐχ οὕτως θρασεῖς καὶ φιλοκινδύνους ὡς ἡγεμονικοὺς καὶ στασίμους καὶ βαθεῖς μᾶλλον ταῖς ψυχαῖς, οὐδ’ ἐξ ἀκεραίου προσπίπτειν ἢ κατάρχεσθαι τῆς μάχης, ἐπικρατουμένους δὲ καὶ πιεζομένους ὑπομένειν καὶ ἀποθνήσκειν ὑπὲρ τῆς χώρας.", "st": "6.24"}, {"sp": "N", "t": "παραπλησίως δὲ καὶ τοὺς ἱππεῖς εἰς ἴλας δέκα διεῖλον, ἐξ ἑκάστης δὲ τρεῖς προκρίνουσιν ἰλάρχας, οὗτοι δ’ αὐτοὶ τρεῖς προσέλαβον οὐραγούς. ὁ μὲν οὖν πρῶτος αἱρεθεὶς ἰλάρχης ἡγεῖται τῆς ἴλης, οἱ δὲ δύο δεκαδάρχων ἔχουσι τάξιν, καλοῦνται δὲ πάντες δεκουρίωνες. μὴ παρόντος δὲ τοῦ πρώτου πάλιν ὁ δεύτερος ἰλάρχου λαμβάνει τάξιν. ὁ δὲ καθοπλισμὸς τῶν ἱππέων νῦν μέν ἐστι παραπλήσιος τῷ τῶν Ἑλλήνων· τὸ δὲ παλαιὸν πρῶτον θώρακας οὐκ εἶχον, ἀλλ’ ἐν περιζώμασιν ἐκινδύνευον, ἐξ οὗ πρὸς μὲν τὸ καταβαίνειν καὶ ταχέως ἀναπηδᾶν ἐπὶ τοὺς ἵππους ἑτοίμως διέκειντο καὶ πρακτικῶς, πρὸς δὲ τὰς συμπλοκὰς ἐπισφαλῶς εἶχον διὰ τὸ γυμνοὶ κινδυνεύειν. τὰ δὲ δόρατα κατὰ δύο τρόπους ἄπρακτ’ ἦν αὐτοῖς, καθ’ ἃ μὲν ᾗ λεπτὰ καὶ κλαδαρὰ ποιοῦντες οὔτε τοῦ προτεθέντος ἠδύναντο σκοποῦ στοχάζεσθαι, πρὸ τοῦ τε τὴν ἐπιδορατίδα πρός τι προσερεῖσαι, κραδαινόμενα δι’ αὐτῆς τῆς τῶν ἵππων κινήσεως τὰ πλεῖστα συνετρίβετο· πρὸς δὲ τούτοις ἄνευ σαυρωτήρων κατασκευάζοντες μιᾷ τῇ πρώτῃ διὰ τῆς ἐπιδορατίδος ἐχρῶντο πληγῇ, μετὰ δὲ ταῦτα κλασθέντων λοιπὸν ἦν ἄπρακτ’ αὐτοῖς καὶ μάταια. τόν γε μὴν θυρεὸν εἶχον ἐκ βοείου δέρματος, τοῖς ὀμφαλωτοῖς ποπάνοις παραπλήσιον τοῖς ἐπὶ τὰς θυσίας ἐπιτιθεμένοις· οἷς οὔτε πρὸς τὰς ἐπιβολὰς ἦν χρῆσθαι διὰ τὸ μὴ στάσιν ἔχειν, ὑπό τε τῶν ὄμβρων ἀποδερματούμενοι καὶ μυδῶντες δύσχρηστοι καὶ πρότερον ἦσαν καὶ νῦν ἔτι γίνονται παντελῶς. διόπερ ἀδοκίμου τῆς χρείας οὔσης, ταχέως μετέλαβον τὴν Ἑλληνικὴν κατασκευὴν τῶν ὅπλων, ἐν ᾗ τῶν μὲν δοράτων τὴν πρώτην εὐθέως τῆς ἐπιδορατίδος πληγὴν εὔστοχον ἅμα καὶ πρακτικὴν γίνεσθαι συμβαίνει, διὰ τὴν κατασκευὴν ἀτρεμοῦς καὶ στασίμου τοῦ δόρατος ὑπάρχοντος, ὁμοίως δὲ καὶ τὴν ἐκ μεταλήψεως τοῦ σαυρωτῆρος χρείαν μόνιμον καὶ βίαιον. ὁ δ’ αὐτὸς λόγος καὶ περὶ τῶν θυρεῶν· καὶ γὰρ πρὸς τὰς ἐπιβολὰς καὶ πρὸς τὰς ἐπιθέσεις ἑστηκυῖαν καὶ τεταγμένην ἔχουσι τὴν χρείαν. ἃ συνιδόντες ἐμιμήσαντο ταχέως· ἀγαθοὶ γάρ, εἰ καί τινες ἕτεροι, μεταλαβεῖν ἔθη καὶ ζηλῶσαι τὸ βέλτιον καὶ Ῥωμαῖοι.", "st": "6.25"}, {"sp": "N", "t": "τοιαύτην δὲ ποιησάμενοι τὴν διαίρεσιν οἱ χιλίαρχοι, καὶ ταῦτα παραγγείλαντες περὶ τῶν ὅπλων, τότε μὲν ἀπέλυσαν τοὺς ἄνδρας εἰς τὴν οἰκείαν· παραγενομένης δὲ τῆς ἡμέρας, εἰς ἣν ὤμοσαν ἁθροισθῆναι πάντες ὁμοίως εἰς τὸν ἀποδειχθέντα τόπον ὑπὸ τῶν ὑπάτων — τάττει δ’ ὡς ἐπίπαν ἑκάτερος χωρὶς τὸν τόπον τοῖς αὑτοῦ στρατοπέδοις· ἑκατέρῳ γὰρ δίδοται τὸ μέρος τῶν συμμάχων καὶ δύο τῶν Ῥωμαϊκῶν στρατοπέδων — παραγίνονται δὲ πάντες ἀδιαπτώτως οἱ καταγραφέντες, ὡς ἂν μηδεμιᾶς ἄλλης συγχωρουμένης προφάσεως τοῖς ἐξορκισθεῖσι πλὴν ὀρνιθείας καὶ τῶν ἀδυνάτων. ἁθροισθέντων δὲ καὶ τῶν συμμάχων ὁμοῦ τοῖς Ῥωμαίοις, τὴν μὲν οἰκονομίαν καὶ τὸν χειρισμὸν ποιοῦνται τούτων αὐτῶν οἱ καθεσταμένοι μὲν ὑπὸ τῶν ὑπάτων ἄρχοντες, προσαγορευόμενοι δὲ πραίφεκτοι, δώδεκα τὸν ἀριθμὸν ὄντες. οἳ πρῶτον μὲν τοῖς ὑπάτοις τοὺς ἐπιτηδειοτάτους πρὸς τὴν ἀληθινὴν χρείαν ἐκ πάντων τῶν παραγεγονότων συμμάχων ἱππεῖς καὶ πεζοὺς ἐκλέγουσι, τοὺς καλουμένους ἐκτραορδιναρίους, ὃ μεθερμηνευόμενον ἐπιλέκτους δηλοῖ. τὸ δὲ πλῆθος γίνεται τὸ πᾶν τῶν συμμάχων, τὸ μὲν τῶν πεζῶν πάρισον τοῖς Ῥωμαϊκοῖς στρατοπέδοις ὡς τὸ πολύ, τὸ δὲ τῶν ἱππέων τριπλάσιον· ἐκ δὲ τούτων λαμβάνουσι τῶν μὲν ἱππέων εἰς τοὺς ἐπιλέκτους ἐπιεικῶς τὸ τρίτον μέρος, τῶν δὲ πεζῶν τὸ πέμπτον. τοὺς δὲ λοιποὺς διεῖλον εἰς δύο μέρη, καὶ καλοῦσι τὸ μὲν δεξιόν, τὸ δ’ εὐώνυμον κέρας. τούτων δ’ εὐτρεπῶν γενομένων παραλαβόντες οἱ χιλίαρχοι τοὺς Ῥωμαίους ὁμοῦ καὶ τοὺς συμμάχους κατεστρατοπέδευσαν, ἑνὸς ὑπάρχοντος παρ’ αὐτοῖς θεωρήματος ἁπλοῦ περὶ τὰς παρεμβολάς, ᾧ χρῶνται πρὸς πάντα καιρὸν καὶ τόπον. διὸ καὶ δοκεῖ μοι πρέπειν τῷ καιρῷ τὸ πειραθῆναι, καθ’ ὅσον οἷόν τε τῷ λόγῳ, τοὺς ἀκούοντας εἰς ἔννοιαν ἀγαγεῖν τοῦ κατὰ τὰς πορείας καὶ στρατοπεδείας καὶ παρατάξεις χειρισμοῦ τῶν δυνάμεων. τίς γὰρ οὕτως ἐστὶν ἀπεοικὼς πρὸς τὰ καλὰ καὶ σπουδαῖα τῶν ἔργων, ὃς οὐκ ἂν βουληθείη μικρὸν ἐπιμελέστερον ἐπιστῆσαι περὶ τῶν τοιούτων, ὑπὲρ ὧν ἅπαξ ἀκούσας ἐπιστήμων ἔσται πράγματος ἑνὸς τῶν ἀξίων λόγου καὶ γνώσεως;", "st": "6.26"}, {"sp": "N", "t": "ἔστι δὴ τὸ γένος αὐτῶν τῆς στρατοπεδείας τοιόνδε. τοῦ κριθέντος αἰεὶ τόπου πρὸς στρατοπεδείαν, τούτου τὸν ἐπιτηδειότατον εἰς σύνοψιν ἅμα καὶ παραγγελίαν ἡ τοῦ στρατηγοῦ σκηνὴ καταλαμβάνει. τεθείσης δὲ τῆς σημαίας, οὗ μέλλουσι πηγνύναι ταύτην, ἀπομετρεῖται πέριξ τῆς σημαίας τετράγωνος τόπος, ὥστε πάσας τὰς πλευρὰς ἑκατὸν ἀπέχειν πόδας τῆς σημαίας, τὸ δ’ ἐμβαδὸν γίνεσθαι τετράπλεθρον. τούτου δὲ τοῦ σχήματος αἰεὶ παρὰ μίαν ἐπιφάνειαν καὶ πλευράν, ἥτις ἂν ἐπιτηδειοτάτη φανῇ πρός τε τὰς ὑδρείας καὶ προνομάς, παραβάλλεται τὰ Ῥωμαϊκὰ στρατόπεδα τὸν τρόπον τοῦτον. ἓξ ὑπαρχόντων χιλιάρχων ἐν ἑκάστῳ στρατοπέδῳ κατὰ τὸν ἄρτι λόγον, δυεῖν δὲ στρατοπέδων ὄντων τῶν Ῥωμαϊκῶν ἀεὶ μεθ’ ἑκατέρου τῶν ὑπάτων, φανερὸν ὅτι δώδεκα χιλιάρχους ἀνάγκη συστρατεύειν ἑκατέρῳ τῶν ὑπάτων. τιθέασι δὴ τὰς τούτων σκηνὰς ἐπὶ μίαν εὐθεῖαν ἁπάσας, ἥτις ἐστὶ παράλληλος τῇ τοῦ τετραγώνου προκριθείσῃ πλευρᾷ, πεντήκοντα δ’ ἀπέχει πόδας ἀπ’ αὐτῆς, ἵν’ ᾗ τοῖς ἵπποις, ἅμα δ’ ὑποζυγίοις καὶ τῇ λοιπῇ τῶν χιλιάρχων ἀποσκευῇ τόπος. αἱ δὲ σκηναὶ τοῦ προειρημένου σχήματος εἰς τοὔμπαλιν ἀπεστραμμέναι πήγνυνται πρὸς τὴν ἐκτὸς ἐπιφάνειαν, ἣ νοείσθω καὶ καλείσθω δὲ καθάπαξ ἡμῖν ἀεὶ τοῦ παντὸς σχήματος κατὰ πρόσωπον. ἀφεστᾶσι δ’ ἀλλήλων μὲν ἴσον αἱ τῶν χιλιάρχων σκηναί, τοσοῦτον δὲ τόπον ὥστε παρ’ ὅλον τὸ πλάτος ἀεὶ τῶν Ῥωμαϊκῶν στρατοπέδων παρήκειν.", "st": "6.27"}, {"sp": "N", "t": "Ἀπομετρηθέντων δὲ πάλιν ἑκατὸν ποδῶν εἰς τὸ πρόσθεν κατὰ πάσας τὰς σκηνάς, λοιπὸν ἀπὸ τῆς τοῦτο τὸ πλάτος ὁριζούσης εὐθείας, ἥτις γίνεται παράλληλος ταῖς τῶν χιλιάρχων σκηναῖς, ἀπὸ ταύτης ἄρχονται ποιεῖσθαι τὰς τῶν στρατοπέδων παρεμβολάς, χειρίζοντες τὸν τρόπον τοῦτον. διχοτομήσαντες τὴν προειρημένην εὐθεῖαν, ἀπὸ τούτου τοῦ σημείου πρὸς ὀρθὰς τῇ γραμμῇ τοὺς ἱππεῖς ἀντίους αὑτοῖς ἑκατέρου τοῦ στρατοπέδου παρεμβάλλουσι, πεντήκοντα διέχοντας πόδας ἀλλήλων, μέσην ποιοῦντες τὴν τομὴν τοῦ διαστήματος. ἔστι δ’ ἥ τε τῶν ἱππέων καὶ τῶν πεζῶν σκηνοποιία παραπλήσιος· γίνεται γὰρ τὸ ὅλον σχῆμα καὶ τῆς σημαίας καὶ τῶν οὐλαμῶν τετράγωνον. τοῦτο δὲ βλέπει μὲν εἰς τὰς διόδους, ἔχει δὲ τὸ μὲν μῆκος ὡρισμένον τὸ παρὰ τὴν δίοδον — ἔστι γὰρ ἑκατὸν ποδῶν — ὡς δ’ ἐπὶ τὸ πολὺ καὶ τὸ βάθος ἴσον πειρῶνται ποιεῖν πλὴν τῶν συμμάχων. ὅταν δὲ τοῖς μείζοσι στρατοπέδοις χρῶνται, τὸ κατὰ λόγον καὶ τῷ μήκει καὶ τῷ βάθει προστιθέασι.", "st": "6.28"}, {"sp": "N", "t": "γενομένης δὲ τῆς τῶν ἱππέων παρεμβολῆς κατὰ μέσας τὰς τῶν χιλιάρχων σκηνὰς οἷον εἰ ῥύμης τινὸς ἐπικαρσίου πρὸς τὴν ἄρτι ῥηθεῖσαν εὐθεῖαν καὶ τὸν πρὸ τῶν χιλιάρχων τόπον — τῷ γὰρ ὄντι ῥύμαις παραπλήσιον ἀποτελεῖται τὸ τῶν διόδων σχῆμα πασῶν, ὡς ἂν ἐξ ἑκατέρου τοῦ μέρους αἷς μὲν ταγμάτων, αἷς δ’ οὐλαμῶν ἐπὶ τὸ μῆκος παρεμβεβληκότων — πλὴν τοῖς προειρημένοις ἱππεῦσι κατόπιν τοὺς ἐξ ἀμφοτέρων τῶν στρατοπέδων τριαρίους, κατ’ οὐλαμὸν ἑκάστην σημαίαν, ἐν ὁμοίῳ σχήματι τιθέασι, συμψαυόντων μὲν τῶν σχημάτων ἀλλήλοις, βλεπόντων δ’ ἔμπαλιν πρὸς τὰς ἐναντίας τοῖς ἱππεῦσιν ἐπιφανείας, ἥμισυ ποιοῦντες τὸ βάθος τοῦ μήκους ἑκάστης σημαίας τῷ καὶ κατὰ τὸ πλῆθος ἡμίσεις ὡς ἐπίπαν εἶναι τούτους τῶν ἄλλων μερῶν. διότιπερ ἀνίσων ὄντων πολλάκις τῶν ἀνδρῶν ἰσάζειν ἀεὶ συμβαίνει πάντα τὰ μέρη κατὰ τὸ μῆκος διὰ τὴν τοῦ βάθους διαφοράν. αὖθις δὲ πεντήκοντα πόδας ἀφ’ ἑκατέρων τούτων ἀποστήσαντες, ἀντίους παρεμβάλλουσι τοῖς τριαρίοις τοὺς πρίγκιπας. νευόντων δὲ καὶ τούτων εἰς τὰ προειρημένα διαστήματα δύ’ αὗται πάλιν ἀποτελοῦνται ῥῦμαι, τὰς μὲν ἀρχὰς ἀπὸ τῆς αὐτῆς εὐθείας λαμβάνουσαι καὶ τὰς εἰσβολάς, ὁμοίως τοῖς ἱππεῦσιν, ἐκ τοῦ πρὸ τῶν χιλιάρχων ἑκατομπέδου διαστήματος, λήγουσαι δὲ πρὸς τὴν καταντικρὺ τῶν χιλιάρχων πλευρὰν τοῦ χάρακος, ἣν ἐξ ἀρχῆς ὑπεθέμεθα κατὰ πρόσωπον εἶναι τοῦ παντὸς σχήματος. μετὰ δὲ τοὺς πρίγκιπας, ὄπισθεν τούτων ὁμοίως ἔμπαλιν βλέποντα, συμψαύοντα δὲ τὰ σχήματα τιθέντες, τοὺς ἁστάτους παρεμβάλλουσι. δέκα δὲ σημαίας ἐχόντων ἁπάντων τῶν μερῶν κατὰ τὴν ἐξ ἀρχῆς διαίρεσιν, πάσας ἴσας συμβαίνει γίνεσθαι τὰς ῥύμας καὶ κατὰ τὸ μῆκος καὶ τὰς ἀποτομὰς ἰσάζειν αὐτῶν τὰς πρὸς τῇ κατὰ τὸ πρόσωπον πλευρᾷ τοῦ χάρακος· πρὸς ἣν καὶ τὰς τελευταίας σημαίας ἐπιστρέφοντες στρατοπεδεύουσιν.", "st": "6.29"}, {"sp": "N", "t": "ἀπὸ τῶν ἁστάτων πεντήκοντα πάλιν διαλείποντες πόδας τοὺς τῶν συμμάχων ἱππεῖς ἀντίους παρεμβάλλουσι τούτοις, ποιούμενοι τὴν ἀρχὴν ἀπὸ τῆς αὐτῆς εὐθείας καὶ λήγοντες ἐπὶ τὴν αὐτήν. ἔστι δὲ τὸ πλῆθος τῶν συμμάχων, ὡς ἐπάνω προεῖπα, τὸ μὲν τῶν πεζῶν πάρισον τοῖς Ῥωμαϊκοῖς στρατοπέδοις, λεῖπον τοῖς ἐπιλέκτοις, τὸ δὲ τῶν ἱππέων διπλάσιον, ἀφῃρημένου καὶ τούτων τοῦ τρίτου μέρους εἰς τοὺς ἐπιλέκτους. διὸ καὶ τὸ βάθος αὔξοντες τούτοις πρὸς λόγον ἐν τοῖς στρατοπεδευτικοῖς σχήμασι, πειρῶνται κατὰ τὸ μῆκος ἐξισοῦν τοῖς τῶν Ῥωμαίων στρατοπέδοις. ἀποτελεσθεισῶν δὲ τῶν ἁπασῶν πέντε διόδων, αὖθις εἰς τοὔμπαλιν ἀπεστραμμένας ὁμοίως τοῖς ἱππεῦσι τιθέασι τὰς τῶν συμμαχικῶν πεζῶν σημαίας, αὔξοντες τὸ βάθος πρὸς λόγον, βλεπούσας δὲ πρὸς τὸν χάρακα καὶ πρὸς τὰς ἐκ τῶν πλαγίων ἐπιφανείας ἑκατέρας. καθ’ ἑκάστην δὲ σημαίαν τὰς πρώτας ἀφ’ ἑκατέρου τοῦ μέρους σκηνὰς οἱ ταξίαρχοι λαμβάνουσιν. ἅμα δὲ τὸν προειρημένον τρόπον παρεμβάλλοντες καθ’ ἕκαστον μέρος τὸν ἕκτον οὐλαμὸν ἀπὸ τοῦ πέμπτου πεντήκοντα πόδας ἀφιστᾶσι, παραπλησίως δὲ καὶ τὰς τῶν πεζῶν τάξεις, ὥστε γίνεσθαι καὶ ταύτην ἄλλην διὰ μέσων τῶν στρατοπέδων δίοδον, ἐπικάρσιον μὲν πρὸς τὰς ῥύμας, παράλληλον δὲ ταῖς τῶν χιλιάρχων σκηναῖς, ἣν καλοῦσι πέμπτην διὰ τὸ παρὰ τὰ πέμπτα τάγματα παρήκειν.", "st": "6.30"}, {"sp": "N", "t": "ὁ δ’ ὑπὸ τὰς τῶν χιλιάρχων σκηνὰς ὄπισθεν τόπος ὑποπεπτωκώς, ἐξ ἑκατέρου δὲ τοῦ μέρους τῆς τοῦ στρατηγίου περιστάσεως παρακείμενος, ὁ μὲν εἰς ἀγορὰν γίνεται τόπος, ὁ δ’ ἕτερος τῷ τε ταμιείῳ καὶ ταῖς ἅμα τούτῳ χορηγίαις. ἀπὸ δὲ τῆς ἐφ’ ἑκάτερα τελευταίας τῶν χιλιάρχων σκηνῆς κατόπιν οἷον ἐπικάμπιον ἔχοντες τάξιν πρὸς τὰς σκηνάς, οἱ τῶν ἐπιλέκτων ἱππέων ἀπόλεκτοι καί τινες τῶν ἐθελοντὴν στρατευομένων τῇ τῶν ὑπάτων χάριτι, πάντες οὗτοι στρατοπεδεύουσι παρὰ τὰς ἐκ τῶν πλαγίων τοῦ χάρακος ἐπιφανείας, βλέποντες οἱ μὲν ἐπὶ τὰς τοῦ ταμιείου παρασκευάς, οἱ δ’ ἐκ θατέρου μέρους εἰς τὴν ἀγοράν. ὡς δ’ ἐπὶ τὸ πολὺ συμβαίνει τούτοις μὴ μόνον στρατοπεδεύειν σύνεγγυς τῶν ὑπάτων, ἀλλὰ καὶ κατὰ τὰς πορείας καὶ κατὰ τὰς ἄλλας χρείας περὶ τὸν ὕπατον καὶ τὸν ταμίαν ποιεῖσθαι τὴν ἐπιμέλειαν καὶ τὴν ὅλην διατριβήν. ἀντίκεινται δὲ τούτοις ἐπὶ τὸν χάρακα βλέποντες οἱ τὴν παραπλήσιον χρείαν παρεχόμενοι πεζοὶ τοῖς προειρημένοις ἱππεῦσιν. ἑξῆς δὲ τούτοις δίοδος ἀπολείπεται πλάτος ποδῶν ἑκατόν, παράλληλος μὲν ταῖς τῶν χιλιάρχων σκηναῖς, ἐπὶ θάτερα δὲ τῆς ἀγορᾶς καὶ στρατηγίου καὶ ταμιείου παρατείνουσα παρὰ πάντα τὰ προειρημένα μέρη τοῦ χάρακος. παρὰ δὲ τὴν ἀνωτέρω πλευρὰν ταύτης οἱ τῶν συμμάχων ἱππεῖς ἐπίλεκτοι στρατοπεδεύουσι, βλέποντες ἐπί τε τὴν ἀγορὰν ἅμα καὶ τὸ στρατήγιον καὶ τὸ ταμιεῖον. κατὰ μέσην δὲ τὴν τούτων τῶν ἱππέων παρεμβολὴν καὶ κατ’ αὐτὴν τὴν τοῦ στρατηγίου περίστασιν δίοδος ἀπολείπεται πεντήκοντα ποδῶν, φέρουσα μὲν ἐπὶ τὴν ὄπισθε πλευρὰν τῆς στρατοπεδείας, τῇ δὲ τάξει πρὸς ὀρθὰς κειμένη τῇ προειρημένῃ πλατείᾳ. τοῖς δ’ ἱππεῦσι τούτοις ἀντίτυποι τίθενται πάλιν οἱ τῶν συμμάχων ἐπίλεκτοι πεζοί, βλέποντες πρὸς τὸν χάρακα καὶ τὴν ὄπισθεν ἐπιφάνειαν τῆς ὅλης στρατοπεδείας. τὸ δ’ ἀπολειπόμενον ἐξ ἑκατέρου τοῦ μέρους τούτων κένωμα παρὰ τὰς ἐκ τῶν πλαγίων πλευρὰς δίδοται τοῖς ἀλλοφύλοις καὶ τοῖς ἐκ τοῦ καιροῦ προσγινομένοις συμμάχοις. τούτων δ’ οὕτως ἐχόντων τὸ μὲν σύμπαν σχῆμα γίνεται τῆς στρατοπεδείας τετράγωνον ἰσόπλευρον, τὰ δὲ κατὰ μέρος ἤδη τῆς τε ῥυμοτομίας ἐν αὐτῇ καὶ τῆς ἄλλης οἰκονομίας πόλει παραπλησίαν ἔχει τὴν διάθεσιν. τὸν δὲ χάρακα τῶν σκηνῶν ἀφιστᾶσι κατὰ πάσας τὰς ἐπιφανείας διακοσίους πόδας. τοῦτο δὲ τὸ κένωμα πολλὰς καὶ δοκίμους αὐτοῖς παρέχεται χρείας. πρός τε γὰρ τὰς εἰσαγωγὰς καὶ τὰς ἐξαγωγὰς τῶν στρατοπέδων εὐφυῶς ἔχει καὶ δεόντως ἕκαστοι γὰρ κατὰ τὰς ἑαυτῶν ῥύμας εἰς τοῦτο τὸ κένωμα ποιοῦνται τὴν ἔξοδον, ἀλλ’ οὐκ εἰς μίαν συμπίπτοντες ἀνατρέπουσι καὶ συμπατοῦσιν ἀλλήλους· τάς τε τῶν παρεισαγομένων θρεμμάτων καὶ τὰς ἐκ τῶν πολεμίων λείας εἰς τοῦτο παράγοντες ἀσφαλῶς τηροῦσι τὰς νύκτας. τὸ δὲ μέγιστον, ἐν ταῖς ἐπιθέσεσι ταῖς νυκτεριναῖς οὔτε πῦρ οὔτε βέλος ἐξικνεῖται πρὸς αὐτοὺς πλὴν τελείως ὀλίγων· γίνεται δὲ καὶ ταῦτα σχεδὸν ἀβλαβῆ διά τε τὸ μέγεθος τῆς ἀποστάσεως καὶ διὰ τὴν τῶν σκηνῶν περίστασιν.", "st": "6.31"}, {"sp": "N", "t": "δεδομένου δὲ τοῦ πλήθους καὶ τῶν πεζῶν καὶ τῶν ἱππέων καθ’ ἑκατέραν τὴν πρόθεσιν, ἄν τε τετρακισχιλίους ἄν τε πεντακισχιλίους εἰς ἕκαστον στρατόπεδον ποιῶσι, παραπλησίως δὲ καὶ τῶν σημαιῶν τοῦ τε βάθους καὶ τοῦ μήκους καὶ τοῦ πλήθους δεδομένου, πρὸς δὲ τούτοις τῶν κατὰ τὰς διόδους καὶ πλατείας διαστημάτων, ὁμοίως δὲ καὶ τῶν ἄλλων ἁπάντων δεδομένων, συμβαίνει τοῖς βουλομένοις συνεφιστάνειν νοεῖν καὶ τοῦ χωρίου τὸ μέγεθος καὶ τὴν ὅλην περίμετρον τῆς παρεμβολῆς. ἐὰν δέ ποτε πλεονάζῃ τὸ τῶν συμμάχων πλῆθος, ἢ τῶν ἐξ ἀρχῆς συστρατευομένων ἢ τῶν ἐκ τοῦ καιροῦ προσγινομένων, τοῖς μὲν ἐκ τοῦ καιροῦ πρὸς τοῖς προειρημένοις καὶ τοὺς παρὰ τὸ στρατήγιον ἀναπληροῦσι τόπους, τὴν ἀγορὰν καὶ τὸ ταμιεῖον συναγαγόντες εἰς αὐτὸν τὸν κατεπείγοντα πρὸς τὴν χρείαν τόπον· τοῖς δ’ ἐξ ἀρχῆς συνεκπορευομένοις, ἐὰν ᾖ πλῆθος ἱκανώτερον, ῥύμην μίαν ἐξ ἑκατέρου τοῦ μέρους τῶν Ῥωμαϊκῶν στρατοπέδων πρὸς ταῖς ὑπαρχούσαις παρὰ τὰς ἐκ τῶν πλαγίων ἐπιφανείας παρατιθέασι. πάντων δὲ τῶν τεττάρων στρατοπέδων καὶ τῶν ὑπάτων ἀμφοτέρων εἰς ἕνα χάρακα συναθροισθέντων, οὐδὲν ἕτερον δεῖ νοεῖν πλὴν δύο στρατιὰς κατὰ τὸν ἄρτι λόγον παρεμβεβληκυίας ἀντεστραμμένας αὑταῖς συνηρμόσθαι, συναπτούσας κατὰ τὰς τῶν ἐπιλέκτων ἑκατέρου τοῦ στρατοπέδου παρεμβολάς, οὓς ἐποιοῦμεν εἰς τὴν ὀπίσω βλέποντας ἐπιφάνειαν τῆς ὅλης παρεμβολῆς, ὅτε δὴ συμβαίνει γίνεσθαι τὸ μὲν σχῆμα παράμηκες, τὸ δὲ χωρίον διπλάσιον τοῦ πρόσθεν, τὴν δὲ περίμετρον ἡμιόλιον. ὅταν μὲν οὖν συμβαίνῃ τοὺς ὑπάτους ἀμφοτέρους ὁμοῦ στρατοπεδεύειν, οὕτως ἀεὶ χρῶνται ταῖς στρατοπεδείαις· ὅταν δὲ χωρίς, τἄλλα μὲν ὡσαύτως, τὴν δ’ ἀγορὰν καὶ τὸ ταμιεῖον καὶ τὸ στρατήγιον μέσον τιθέασι τῶν δυεῖν στρατοπέδων.", "st": "6.32"}, {"sp": "N", "t": "μετὰ δὲ τὴν στρατοπεδείαν συναθροισθέντες οἱ χιλίαρχοι τοὺς ἐκ τοῦ στρατοπέδου πάντας ἐλευθέρους ὁμοῦ καὶ δούλους ὁρκίζουσι, καθ’ ἕνα ποιούμενοι τὸν ὁρκισμόν. ὁ δ’ ὅρκος ἐστὶ μηδὲν ἐκ τῆς παρεμβολῆς κλέψειν, ἀλλὰ κἂν εὕρῃ τι, τοῦτ’ ἀνοίσειν ἐπὶ τοὺς χιλιάρχους. ἑξῆς δὲ τούτοις διέταξαν τὰς σημαίας ἐξ ἑκάστου στρατοπέδου τῶν πριγκίπων καὶ τῶν ἁστάτων, δύο μὲν εἰς τὴν ἐπιμέλειαν τοῦ τόπου τοῦ πρὸ τῶν χιλιάρχων· τὴν γὰρ διατριβὴν ἐν ταῖς καθημερείαις οἱ πλεῖστοι τῶν Ῥωμαίων ἐν ταύτῃ ποιοῦνται τῇ πλατείᾳ· διόπερ ἀεὶ σπουδάζουσι περὶ ταύτης, ὡς ῥαίνηται καὶ καλλύνηται σφίσιν ἐπιμελῶς. τῶν δὲ λοιπῶν ὀκτωκαίδεκα τρεῖς ἕκαστος τῶν χιλιάρχων διαλαγχάνει· τοσαῦται γάρ εἰσι τῶν ἁστάτων καὶ πριγκίπων ἐν ἑκάστῳ στρατοπέδῳ σημαῖαι κατὰ τὴν ἄρτι ῥηθεῖσαν διαίρεσιν, χιλίαρχοι δ’ ἕξ. τῶν δὲ τριῶν σημαιῶν ἀνὰ μέρος ἑκάστη τῷ χιλιάρχῳ λειτουργεῖ λειτουργίαν τοιαύτην. ἐπειδὰν καταστρατοπεδεύσωσι, τὴν σκηνὴν ἱστᾶσιν οὗτοι καὶ τὸν περὶ τὴν σκηνὴν τόπον ἠδάφισαν. κἄν τι περιφράξαι δέῃ τῶν σκευῶν ἀσφαλείας χάριν, οὗτοι φροντίζουσι. διδόασι δὲ καὶ φυλακεῖα δύο — τὸ δὲ φυλακεῖόν ἐστιν ἐκ τεττάρων ἀνδρῶν — ὧν οἱ μὲν πρὸ τῆς σκηνῆς, οἱ δὲ κατόπιν παρὰ τοὺς ἵππους ποιοῦνται τὴν φυλακήν. οὐσῶν δὲ σημαιῶν ἑκάστῳ χιλιάρχῳ τριῶν, ἐν ἑκάστῃ δὲ τούτων ἀνδρῶν ὑπαρχόντων ὑπὲρ τοὺς ἑκατὸν χωρὶς τῶν τριαρίων καὶ γροσφομάχων — οὗτοι γὰρ οὐ λειτουργοῦσι — τὸ μὲν ἔργον γίνεται κοῦφον διὰ τὸ παρὰ τετάρτην ἡμέραν ἑκάστῃ σημαίᾳ καθήκειν τὴν λειτουργίαν, τοῖς δὲ χιλιάρχοις ἅμα μὲν τὸ τῆς εὐχρηστίας ἀναγκαῖον, ἅμα δὲ τὸ τῆς τιμῆς διὰ τῶν προειρημένων ἀποτελεῖται σεμνὸν καὶ προστατικόν. αἱ δὲ τῶν τριαρίων σημαῖαι τῆς μὲν τῶν χιλιάρχων παραλύονται λειτουργίας, εἰς δὲ τοὺς τῶν ἱππέων οὐλαμοὺς ἑκάστη σημαία καθ’ ἡμέραν δίδωσι φυλακεῖον ἀεὶ τῷ γειτνιῶντι κατόπιν τῶν οὐλαμῶν· οἵτινες τηροῦσι μὲν καὶ τἄλλα, μάλιστα δὲ τοὺς ἵππους, ἵνα μήτ’ ἐμπλεκόμενοι τοῖς δέμασι βλάπτωνται πρὸς χρείαν μήτε λυόμενοι καὶ προσπίπτοντες ἄλλοις ἵπποις ταραχὰς καὶ θορύβους ἐμποιῶσι τῷ στρατοπέδῳ. μία δ’ ἐξ ἁπασῶν καθ’ ἡμέραν σημαία ἀνὰ μέρος τῷ στρατηγῷ παρακοιτεῖ· ἥτις ἅμα μὲν ἀσφάλειαν παρασκευάζει τῷ στρατηγῷ πρὸς τὰς ἐπιβουλάς, ἅμα δὲ κοσμεῖ τὸ πρόσχημα τῆς ἀρχῆς.", "st": "6.33"}, {"sp": "N", "t": "τῆς δὲ ταφρείας καὶ χαρακοποιίας δύο μὲν ἐπιβάλλουσι πλευραὶ τοῖς συμμάχοις, παρ’ ἃς καὶ στρατοπεδεύει τὸ κέρας αὐτῶν ἑκάτερον, δύο δὲ τοῖς Ῥωμαίοις, ἑκατέρῳ τῷ στρατοπέδῳ μία. διαιρεθείσης δὲ τῆς πλευρᾶς ἑκάστης κατὰ σημαίαν, τὴν μὲν κατὰ μέρος ἐπιμέλειαν οἱ ταξίαρχοι ποιοῦνται παρεστῶτες, τὴν δὲ καθόλου δοκιμασίαν τῆς πλευρᾶς δύο τῶν χιλιάρχων. ὁμοίως δὲ καὶ τὴν λοιπὴν τὴν κατὰ τὸ στρατόπεδον ἐπιμέλειαν οὗτοι ποιοῦνται· κατὰ δύο γὰρ σφᾶς αὐτοὺς διελόντες ἀνὰ μέρος τῆς ἑκμήνου τὴν δίμηνον ἄρχουσι, καὶ πάσης οἱ λαχόντες τῆς ἐν τοῖς ὑπαίθροις προΐστανται χρείας. ὁ δ’ αὐτὸς τρόπος τῆς ἀρχῆς ἐστι καὶ τῶν πραιφέκτων περὶ τοὺς συμμάχους. οἱ δ’ ἱππεῖς καὶ ταξίαρχοι πάντες ἅμα τῷ φωτὶ παραγίνονται πρὸς τὰς τῶν χιλιάρχων σκηνάς, οἱ δὲ χιλίαρχοι πρὸς τὸν ὕπατον. κἀκεῖνος μὲν τὸ κατεπεῖγον ἀεὶ παραγγέλλει τοῖς χιλιάρχοις, οἱ δὲ χιλίαρχοι τοῖς ἱππεῦσι καὶ ταξιάρχοις, οὗτοι δὲ τοῖς πολλοῖς, ὅταν ἑκάστων ὁ καιρὸς ᾖ. τὴν δὲ τοῦ νυκτερινοῦ συνθήματος παράδοσιν ἀσφαλίζονται τὸν τρόπον τοῦτον. καθ’ ἕκαστον γένος καὶ τῶν ἱππέων καὶ τῶν πεζῶν ἐκ τῆς δεκάτης σημαίας καὶ τελευταίας στρατοπεδευούσης κατὰ τὰς ῥύμας, ἐκ τούτων εἷς ἑκάστης ἀνὴρ λαμβάνεται κατ’ ἐκλογήν, ὃς τῶν μὲν κατὰ τὰς φυλακὰς λειτουργιῶν ἀπολύεται, παραγίνεται δὲ καθ’ ἡμέραν δύνοντος ἡλίου πρὸς τὴν τοῦ χιλιάρχου σκηνήν, καὶ λαβὼν τὸ σύνθημα — τοῦτο δ’ ἐστὶ πλατεῖον ἐπιγεγραμμένον — ἀπαλλάττεται πάλιν. ἀναχωρήσας δ’ ἐπὶ τὴν αὑτοῦ σημαίαν τό τε ξυλήφιον παρέδωκε καὶ τὸ σύνθημα μετὰ μαρτύρων τῷ τῆς ἐχομένης σημαίας ἡγεμόνι, παραπλησίως δὲ πάλιν οὗτος τῷ τῆς ἐχομένης. τὸ δ’ ὅμοιον ἑξῆς ποιοῦσι πάντες, ἕως ἂν ἐπὶ τὰς πρώτας καὶ σύνεγγυς τοῖς χιλιάρχοις στρατοπεδευούσας σημαίας ἐξικνῆται. τούτους δὲ δεῖ τὸ πλατεῖον ἔτι φωτὸς ὄντος ἀναφέρειν πρὸς τοὺς χιλιάρχους. κἂν μὲν ἀνενεχθῇ πάντα τὰ δοθέντα, γινώσκει διότι δέδοται τὸ σύνθημα πᾶσι καὶ διὰ πάντων εἰς αὐτὸν ἥκει· ἐὰν δ’ ἐλλείπῃ τι, παρὰ πόδας ζητεῖ τὸ γεγονός, εἰδὼς ἐκ τῆς ἐπιγραφῆς ἐκ ποίου μέρους οὐχ ἥκει τὸ πλατεῖον. οὗ δ’ ἂν εὑρεθῇ τὸ κώλυμα, τυγχάνει τῆς καθηκούσης ζημίας.", "st": "6.34"}, {"sp": "N", "t": "τὰ δὲ περὶ τὰς νυκτερινὰς φυλακὰς οὕτως οἰκονομεῖται παρ’ αὐτοῖς. τὸν μὲν στρατηγὸν καὶ τὴν τούτου σκηνὴν ἡ παρακοιτοῦσα σημαία φυλάττει, τὰς δὲ τῶν χιλιάρχων καὶ τοὺς τῶν ἱππέων οὐλαμοὺς οἱ διατεταγμένοι κατὰ τὸν ἄρτι λόγον ἐξ ἑκάστης σημαίας. ὁμοίως δὲ καὶ παρ’ ἕκαστον τάγμα πάντες ἐξ ἑαυτῶν τιθέασι φυλακήν· τὰς δὲ λοιπὰς ὁ στρατηγὸς ἀποτάττει. γίνονται δ’ ὡς ἐπίπαν τρεῖς φυλακαὶ παρὰ τὸν ταμίαν, καὶ παρ’ ἕκαστον τῶν πρεσβευτῶν καὶ συμβούλων δύο. τὴν δ’ ἐκτὸς ἐπιφάνειαν οἱ γροσφομάχοι πληροῦσι, παρ’ ὅλον καθ’ ἡμέραν τὸν χάρακα παρακοιτοῦντες — αὕτη γὰρ ἐπιτέτακται τούτοις ἡ λειτουργία — ἐπί τε τῶν εἰσόδων ἀνὰ δέκα ποιοῦνται τούτων αὐτῶν τὰς προκοιτίας. τῶν δ’ εἰς τὰς φυλακὰς ἀποταχθέντων ἀφ’ ἑκάστου φυλακείου τὸν τὴν πρώτην μέλλοντα τηρεῖν εἷς ἐξ ἑκάστης σημαίας οὐραγὸς ἄγει πρὸς τὸν χιλίαρχον ἑσπέρας· ὁ δὲ δίδωσι τούτοις πᾶσι ξυλήφια κατὰ φυλακήν, βραχέα τελέως, ἔχοντα χαρακτῆρα. λαβόντες δ’ οὗτοι μὲν ἐπὶ τοὺς ἀποδεδειγμένους ἀπαλλάττονται τόπους. ἡ δὲ τῆς ἐφοδείας πίστις εἰς τοὺς ἱππεῖς ἀνατίθεται. δεῖ γὰρ τὸν πρῶτον ἰλάρχην καθ’ ἕκαστον στρατόπεδον ἑνὶ τῶν οὐραγῶν τῶν αὑτοῦ παραγγεῖλαι πρῲ παράγγελμα τοιοῦτον, ἵνα τέτταρσιν οὗτος ἐμφανίσῃ νεανίσκοις τῶν ἐκ τῆς ἰδίας ἴλης πρὸ ἀρίστου τοῖς μέλλουσιν ἐφοδεύειν. μετὰ δὲ ταῦτα τῷ τῆς ἐχομένης ἴλης ἡγεμόνι δεῖ τὸν αὐτὸν ἀφ’ ἑσπέρας παραγγεῖλαι διότι τούτῳ καθήκει τὰ περὶ τῆς ἐφοδείας φροντίζειν εἰς τὴν αὔριον. τοῦτον δ’ ἀκούσαντα παραπλησίως ταὐτὰ δεῖ ποιεῖν τοῖς προειρημένοις εἰς τὴν ἐπιοῦσαν ἡμέραν· ὁμοίως δὲ καὶ τοὺς ἑξῆς. οἱ δὲ προκριθέντες ὑπὸ τῶν οὐραγῶν ἐκ τῆς πρώτης ἴλης τέτταρες, ἐπειδὰν διαλάχωσι τὰς φυλακάς, πορεύονται πρὸς τὸν χιλίαρχον, καὶ γραφὴν λαμβάνουσι πόσου καὶ πόσας ἐφοδεῦσαι δεῖ φυλακάς. μετὰ δὲ ταῦτα παρακοιτοῦσιν οἱ τέτταρες παρὰ τὴν πρώτην σημαίαν τῶν τριαρίων· ὁ γὰρ ταύτης ταξίαρχος τὴν ἐπιμέλειαν ποιεῖται τοῦ κατὰ φυλακὴν βουκανᾶν.", "st": "6.35"}, {"sp": "N", "t": "συνάψαντος δὲ τοῦ καιροῦ τὴν πρώτην ἐφοδεύει φυλακὴν ὁ ταύτην λαχών, ἔχων μεθ’ αὑτοῦ μάρτυρας τῶν φίλων. ἐπιπορεύεται δὲ τοὺς ῥηθέντας τόπους, οὐ μόνον τοὺς περὶ τὸν χάρακα καὶ τὰς εἰσόδους, ἀλλὰ καὶ τοὺς κατὰ σημαίαν ἅπαντας καὶ τοὺς κατ’ οὐλαμόν· κἂν μὲν εὕρῃ τοὺς φυλάττοντας τὴν πρώτην ἐγρηγορότας, λαμβάνει παρὰ τούτων τὸ κάρφος· ἐὰν δ’ εὕρῃ κοιμώμενον ἢ λελοιπότα τινὰ τὸν τόπον, ἐπιμαρτυράμενος τοὺς σύνεγγυς ἀπαλλάττεται. τὸ δὲ παραπλήσιον γίνεται καὶ ὑπὸ τῶν τὰς ἑξῆς φυλακὰς ἐφοδευόντων. τὴν δ’ ἐπιμέλειαν τοῦ κατὰ φυλακὴν βουκανᾶν, ὡς ἀρτίως εἶπον, ἵνα σύμφωνον ᾖ τοῖς ἐφοδεύουσι πρὸς τοὺς φυλάττοντας, οἱ τῆς πρώτης σημαίας τῶν τριαρίων ἐξ ἑκατέρου τοῦ στρατοπέδου ταξίαρχοι καθ’ ἡμέραν ποιοῦνται. τῶν δ’ ἐφόδων ἕκαστος ἅμα τῷ φωτὶ πρὸς τὸν χιλίαρχον ἀναφέρει τὸ σύνθημα. κἂν μὲν ᾖ πάντα δεδομένα, χωρὶς ἐγκλήματος ἀπαλλάττονται πάλιν· ἂν δέ τις ἐλάττω φέρῃ τοῦ πλήθους τῶν φυλακείων, ζητοῦσιν ἐκ τοῦ χαρακτῆρος ποῖον ἐκ τῶν φυλακείων λέλοιπε. τούτου δὲ γνωσθέντος καλεῖ τὸν ταξίαρχον· οὗτος δ’ ἄγει τοὺς ἀποταχθέντας εἰς τὴν φυλακήν· οὗτοι δὲ συγκρίνονται πρὸς τὸν ἔφοδον. ἐὰν μὲν οὖν ἐν τοῖς φύλαξιν ᾖ τὸ κακόν, εὐθέως δῆλός ἐστιν ὁ τὴν ἐφοδείαν ἔχων ἐπιμαρτυράμενος τοὺς σύνεγγυς· ὀφείλει γὰρ τοῦτο ποιεῖν· ἐὰν δὲ μηδὲν ᾖ τοιοῦτο γεγονός, εἰς τὸν ἔφοδον ἀναχωρεῖ τοὔγκλημα.", "st": "6.35"}, {"sp": "N", "t": "καθίσαντος δὲ παραχρῆμα συνεδρίου τῶν χιλιάρχων κρίνεται, κἂν καταδικασθῇ, ξυλοκοπεῖται. τὸ δὲ τῆς ξυλοκοπίας ἐστὶ τοιοῦτον. λαβὼν ξύλον ὁ χιλίαρχος τούτῳ τοῦ κατακριθέντος οἷον ἥψατο μόνον, οὗ γενομένου πάντες οἱ τοῦ στρατοπέδου τύπτοντες τοῖς ξύλοις καὶ τοῖς λίθοις τοὺς μὲν πλείστους ἐν αὐτῇ τῇ στρατοπεδείᾳ καταβάλλουσι, τοῖς δ’ ἐκπεσεῖν δυναμένοις οὐδ’ ὣς ὑπάρχει σωτηρία· πῶς γάρ; οἷς οὔτ’ εἰς τὴν πατρίδα τὴν ἑαυτῶν ἐπανελθεῖν ἔξεστιν οὔτε τῶν ἀναγκαίων οὐδεὶς ἂν οἰκίᾳ τολμήσειε δέξασθαι τὸν τοιοῦτον. διὸ τελείως οἱ περιπεσόντες ἅπαξ τοιαύτῃ συμφορᾷ καταφθείρονται. τὸ δ’ αὐτὸ πάσχειν ὀφείλει τοῖς προειρημένοις ὅ τ’ οὐραγὸς καὶ [ὁ] τῆς ἴλης ἡγεμών, ἐὰν μὴ παραγγείλωσιν, ὁ μὲν τοῖς ἐφόδοις, ὁ δὲ τῷ τῆς ἐχομένης ἴλης ἡγεμόνι, τὸ δέον ἐν τῷ καθήκοντι καιρῷ. διόπερ οὕτως ἰσχυρᾶς οὔσης καὶ ἀπαραιτήτου τῆς τιμωρίας ἀδιάπτωτα γίνεται παρ’ αὐτοῖς τὰ κατὰ τὰς νυκτερινὰς φυλακάς. δεῖ δὲ προσέχειν τοὺς μὲν στρατιώτας τοῖς χιλιάρχοις, τούτους δ’ ἔτι τοῖς ὑπάτοις. κύριος δ’ ἐστὶ καὶ ζημιῶν ὁ χιλίαρχος καὶ ἐνεχυράζων καὶ μαστιγῶν, τοὺς δὲ συμμάχους οἱ πραίφεκτοι. ξυλοκοπεῖται δὲ καὶ πᾶς ὁ κλέψας τι τῶν ἐκ τοῦ στρατοπέδου, καὶ μὴν ὁ μαρτυρήσας ψευδῆ παραπλησίως, κἄν τις τῶν ἐν ἀκμῇ παραχρησάμενος εὑρεθῇ τῷ σώματι, πρὸς δὲ τούτοις ὁ τρὶς περὶ τῆς αὐτῆς αἰτίας ζημιωθείς. ταῦτα μὲν οὖν ὡς ἀδικήματα κολάζουσιν· εἰς δ’ ἀνανδρίαν τιθέασι καὶ στρατιωτικὴν αἰσχύνην τὰ τοιαῦτα τῶν ἐγκλημάτων, ἐάν τινες ψευδῆ περὶ αὑτῶν ἀνδραγαθίαν ἀπαγγείλωσι τοῖς χιλιάρχοις ἕνεκεν τοῦ τιμὰς λαβεῖν, ὁμοίως ἄν τινες εἰς ἐφεδρείαν ταχθέντες φόβου χάριν λίπωσι τὸν δοθέντα τόπον, παραπλησίως ἐάν τις ἀπορρίψῃ τι τῶν ὅπλων κατ’ αὐτὸν τὸν κίνδυνον διὰ φόβον. διὸ καί τινες μὲν ἐν ταῖς ἐφεδρείαις προδήλως ἀπόλλυνται, πολλαπλασίων αὐτοῖς ἐπιγινομένων οὐ θέλοντες λιπεῖν τὴν τάξιν, δεδιότες τὴν οἰκείαν τιμωρίαν· ἔνιοι δὲ κατ’ αὐτὸν τὸν κίνδυνον ἐκβαλόντες θυρεὸν ἢ μάχαιραν ἤ τι τῶν ἄλλων ὅπλων παραλόγως ῥίπτουσιν ἑαυτοὺς εἰς τοὺς πολεμίους, ἢ κυριεύειν ἐλπίζοντες ὧν ἀπέβαλον ἢ παθόντες τι τὴν πρόδηλον αἰσχύνην διαφεύξεσθαι καὶ τὴν τῶν οἰκείων ὕβριν.", "st": "6.37"}, {"sp": "N", "t": "ἐὰν δέ ποτε ταὐτὰ ταῦτα περὶ πλείους συμβῇ γενέσθαι καὶ σημαίας τινὰς ὁλοσχερῶς πιεσθείσας λιπεῖν τοὺς τόπους, τὸ μὲν ἅπαντας ξυλοκοπεῖν ἢ φονεύειν ἀποδοκιμάζουσι, λύσιν δὲ τοῦ πράγματος εὑρίσκονται συμφέρουσαν ἅμα καὶ καταπληκτικήν. συναθροίσας γὰρ τὸ στρατόπεδον ὁ χιλίαρχος καὶ προαγαγὼν εἰς μέσον τοὺς λελοιπότας, κατηγορεῖ πικρῶς, καὶ τὸ τέλος ποτὲ μὲν πέντε, ποτὲ δ’ ὀκτώ, ποτὲ δ’ εἴκοσι, τὸ δ’ ὅλον πρὸς τὸ πλῆθος αἰεὶ στοχαζόμενος, ὥστε δέκατον μάλιστα γίνεσθαι τῶν ἡμαρτηκότων, τοσούτους ἐκ πάντων κληροῦται τῶν ἀποδεδειλιακότων, καὶ τοὺς μὲν λαχόντας ξυλοκοπεῖ κατὰ τὸν ἄρτι ῥηθέντα λόγον ἀπαραιτήτως, τοῖς δὲ λοιποῖς τὸ μέτρημα κριθὰς δοὺς ἀντὶ πυρῶν ἔξω κελεύει τοῦ χάρακος καὶ τῆς ἀσφαλείας ποιεῖσθαι τὴν παρεμβολήν. λοιπὸν τοῦ μὲν κινδύνου καὶ φόβου τοῦ κατὰ τὸν κλῆρον ἐπ’ ἴσον ἐπικρεμαμένου πᾶσιν, ὡς ἂν ἀδήλου τοῦ συμπτώματος ὑπάρχοντος, τοῦ δὲ παραδειγματισμοῦ τοῦ κατὰ τὴν κριθοφαγίαν ὁμοίως συμβαίνοντος περὶ πάντας, τὸ δυνατὸν ἐκ τῶν ἐθισμῶν εἴληπται καὶ πρὸς κατάπληξιν καὶ διόρθωσιν τῶν συμπτωμάτων.", "st": "6.38"}, {"sp": "N", "t": "καλῶς δὲ καὶ τοὺς νέους ἐκκαλοῦνται πρὸς τὸ κινδυνεύειν. ἐπειδὰν γὰρ γένηταί τις χρεία καί τινες αὐτῶν ἀνδραγαθήσωσι, συναγαγὼν ὁ στρατηγὸς ἐκκλησίαν τοῦ στρατοπέδου, καὶ παραστησάμενος τοὺς δόξαντάς τι πεπραχέναι διαφέρον, πρῶτον μὲν ἐγκώμιον ὑπὲρ ἑκάστου λέγει περί τε τῆς ἀνδραγαθίας, κἄν τι κατὰ τὸν βίον αὐτοῖς ἄλλο συνυπάρχῃ τῆς ἐπ’ ἀγαθῷ μνήμης ἄξιον, μετὰ δὲ ταῦτα τῷ μὲν τρώσαντι πολέμιον γαῖσον δωρεῖται, τῷ δὲ καταβαλόντι καὶ σκυλεύσαντι, τῷ μὲν πεζῷ φιάλην, τῷ δ’ ἱππεῖ φάλαρ’, ἐξ ἀρχῆς δὲ γαῖσον μόνον. τυγχάνει δὲ τούτων οὐκ ἐὰν ἐν παρατάξει τις ἢ πόλεως καταλήψει τρώσῃ τινὰς ἢ σκυλεύσῃ τῶν πολεμίων, ἀλλ’ ἐὰν ἐν ἀκροβολισμοῖς ἤ τισιν ἄλλοις τοιούτοις καιροῖς, ἐν οἷς μηδεμιᾶς ἀνάγκης οὔσης κατ’ ἄνδρα κινδυνεύειν αὐτοί τινες ἑκουσίως καὶ κατὰ προαίρεσιν αὑτοὺς εἰς τοῦτο διδόασι. τοῖς δὲ πόλεως καταλαμβανομένης πρώτοις ἐπὶ τὸ τεῖχος ἀναβᾶσι χρυσοῦν δίδωσι στέφανον. ὁμοίως δὲ καὶ τοὺς ὑπερασπίσαντας καὶ σώσαντάς τινας τῶν πολιτῶν ἢ συμμάχων ὅ τε στρατηγὸς ἐπισημαίνεται δώροις, οἵ τε χιλίαρχοι τοὺς σωθέντας, ἐὰν μὲν ἑκόντες ποιήσωσιν, εἰ δὲ μή, κρίναντες συναναγκάζουσι τὸν σώσαντα στεφανοῦν. σέβεται δὲ τοῦτον καὶ παρ’ ὅλον τὸν βίον ὁ σωθεὶς ὡς πατέρα, καὶ πάντα δεῖ τούτῳ ποιεῖν αὐτὸν ὡς τῷ γονεῖ. ἐκ δὲ τῆς τοιαύτης παρορμήσεως οὐ μόνον τοὺς ἀκούοντας καὶ παρόντας ἐκκαλοῦνται πρὸς τὴν ἐν τοῖς κινδύνοις ἅμιλλαν καὶ ζῆλον, ἀλλὰ καὶ τοὺς ἐν οἴκῳ μένοντας· οἱ γὰρ τυχόντες τῶν τοιούτων δωρεῶν χωρὶς τῆς ἐν τοῖς στρατοπέδοις εὐκλείας καὶ τῆς ἐν οἴκῳ παραχρῆμα φήμης καὶ μετὰ τὴν ἐπάνοδον τὴν εἰς τὴν πατρίδα τάς τε πομπὰς ἐπισήμως πομπεύουσι διὰ τὸ μόνοις ἐξεῖναι περιτίθεσθαι κόσμον τοῖς ὑπὸ τῶν στρατηγῶν ἐπ’ ἀνδραγαθίᾳ τετιμημένοις, ἔν τε ταῖς οἰκίαις κατὰ τοὺς ἐπιφανεστάτους τόπους τιθέασι τὰ σκῦλα, σημεῖα ποιούμενοι καὶ μαρτύρια τῆς ἑαυτῶν ἀρετῆς. τοιαύτης δ’ ἐπιμελείας οὔσης καὶ σπουδῆς περί τε τὰς τιμὰς καὶ τιμωρίας τὰς ἐν τοῖς στρατοπέδοις, εἰκότως καὶ τὰ τέλη τῶν πολεμικῶν πράξεων ἐπιτυχῆ καὶ λαμπρὰ γίνεται δι’ αὐτῶν. ὀψώνιον δ’ οἱ μὲν πεζοὶ λαμβάνουσι τῆς ἡμέρας δύ’ ὀβολούς, οἱ δὲ ταξίαρχοι διπλοῦν, οἱ δ’ ἱππεῖς δραχμήν. σιτομετροῦνται δ’ οἱ μὲν πεζοὶ πυρῶν Ἀττικοῦ μεδίμνου δύο μέρη μάλιστά πως, οἱ δ’ ἱππεῖς κριθῶν μὲν ἑπτὰ μεδίμνους εἰς τὸν μῆνα, πυρῶν δὲ δύο, τῶν δὲ συμμάχων οἱ μὲν πεζοὶ τὸ ἴσον, οἱ δ’ ἱππεῖς πυρῶν μὲν μέδιμνον ἕνα καὶ τρίτον μέρος, κριθῶν δὲ πέντε. δίδοται δὲ τοῖς μὲν συμμάχοις τοῦτ’ ἐν δωρεᾷ· τοῖς δὲ Ῥωμαίοις τοῦ τε σίτου καὶ τῆς ἐσθῆτος, κἄν τινος ὅπλου προσδεηθῶσι, πάντων τούτων ὁ ταμίας τὴν τεταγμένην τιμὴν ἐκ τῶν ὀψωνίων ὑπολογίζεται.", "st": "6.39"}, {"sp": "N", "t": "τὰς δ’ ἐκ τῆς παρεμβολῆς ἀναστρατοπεδείας ποιοῦνται τὸν τρόπον τοῦτον. ὅταν τὸ πρῶτον σημήνῃ, καταλύουσι τὰς σκηνὰς καὶ συντιθέασι τὰ φορτία πάντες· οὔτε δὲ καθελεῖν ἔξεστιν οὔτ’ ἀναστῆσαι πρότερον οὐδένα τῆς τῶν χιλιάρχων καὶ τοῦ στρατηγοῦ σκηνῆς. ὅταν δὲ τὸ δεύτερον, ἀνατιθέασι τὰ σκευοφόρα τοῖς ὑποζυγίοις. ἐπὰν δὲ τὸ τρίτον σημήνῃ, προάγειν δεῖ τοὺς πρώτους καὶ κινεῖν τὴν ὅλην παρεμβολήν. εἰς μὲν οὖν τὴν πρωτοπορείαν ὡς ἐπίπαν τάττουσι τοὺς ἐπιλέκτους· τούτοις δὲ τὸ τῶν συμμάχων δεξιὸν ἐπιβάλλει κέρας· ἑξῆς δὲ τούτοις ἕπεται τὰ τῶν προειρημένων ὑποζύγια. τῇ δὲ τούτων πορείᾳ τὸ πρῶτον τῶν Ῥωμαϊκῶν ἀκολουθεῖ στρατόπεδον, ἔχον ὄπισθεν τὴν ἰδίαν ἀποσκευήν. κἄπειτα κατακολουθεῖ τὸ δεύτερον στρατόπεδον, ἑπομένων αὐτῷ τῶν ἰδίων ὑποζυγίων καὶ τῆς τῶν συμμάχων ἀποσκευῆς τῶν ἐπὶ τῆς οὐραγίας τεταγμένων τελευταῖον γὰρ ἐν τῇ πορείᾳ τάττεται τὸ τῶν συμμάχων εὐώνυμον κέρας. οἱ δ’ ἱππεῖς ποτὲ μὲν ἀπουραγοῦσι τοῖς αὑτῶν ἕκαστοι μέρεσι, ποτὲ δὲ παρὰ τὰ ὑποζύγια πλάγιοι παραπορεύονται, συνέχοντες ταῦτα καὶ τὴν ἀσφάλειαν τούτοις παρασκευάζοντες. προσδοκίας δ’ οὔσης κατὰ τὴν οὐραγίαν τὰ μὲν ἄλλα παρ’ αὐτοῖς τὸν αὐτὸν ἔχει τρόπον, αὐτοὶ δ’ οἱ τῶν συμμάχων ἐπίλεκτοι τὴν οὐραγίαν ἀντὶ τῆς πρωτοπορείας μεταλαμβάνουσι. παρὰ δὲ μίαν ἡμέραν τὰ μὲν ἡγεῖται τῶν στρατοπέδων καὶ κεράτων, τὰ δ’ αὐτὰ πάλιν ἕπεται ταῦτα κατόπιν, ἵνα τῆς περὶ τὰς ὑδρείας καὶ σιτολογίας ἀκεραιότητος πάντες ἐπ’ ἴσον κοινωνῶσι, μεταλαμβάνοντες ἀεὶ τὴν ἐπὶ τῆς πρωτοπορείας ἐναλλὰξ τάξιν. χρῶνται δὲ καὶ ἑτέρῳ γένει πορείας ἐν τοῖς ἐπισφαλέσι τῶν καιρῶν, ἐὰν ἀναπεπταμένους ἔχωσι τόπους ἄγουσι γὰρ τριφαλαγγίαν παράλληλον τῶν ἁστάτων καὶ πριγκίπων καὶ τριαρίων, τάττοντες τὰ τῶν ἡγουμένων σημαιῶν ὑποζύγια πρὸ πάντων, ἐπὶ δὲ ταῖς πρώταις σημαίαις τὰ τῶν δευτέρων, ἐπὶ δὲ ταῖς δευτέραις τὰ τῶν τρίτων, καὶ κατὰ λόγον οὕτως ἐναλλὰξ ἀεὶ τιθέντες τὰ ὑποζύγια ταῖς σημαίαις οὕτω δὲ συντάξαντες τὴν πορείαν, ἐπειδὰν προσπίπτῃ τι τῶν δεινῶν, ποτὲ μὲν παρ’ ἀσπίδα κλίναντες, ποτὲ δ’ ἐπὶ δόρυ, προάγουσι τὰς σημαίας ἐκ τῶν ὑποζυγίων πρὸς τὴν τῶν πολεμίων ἐπιφάνειαν. λοιπὸν ἐν βραχεῖ χρόνῳ καὶ μιᾷ κινήσει τὸ μὲν τῶν ὁπλιτῶν σύστημα λαμβάνει παρατάξεως διάθεσιν, ἐὰν μή ποτε προσεξελίξαι δέῃ τοὺς ἁστάτους, τὸ δὲ τῶν ὑποζυγίων καὶ τῶν παρεπομένων τούτοις πλῆθος, ὑπὸ τοὺς παρατεταγμένους ὑπεσταλκός, ἔχει τὴν καθήκουσαν χώραν πρὸς τὸν κίνδυνον.", "st": "6.40"}, {"sp": "N", "t": "ὅταν δὲ κατὰ τὰς πορείας ἐγγίζωσι στρατοπεδεύειν, προπορεύονται χιλίαρχος καὶ τῶν ταξιάρχων οἱ πρὸς τοῦτο τὸ μέρος ἀεὶ προχειρισθέντες, οἵτινες ἐπειδὰν συνθεάσωνται τὸν ὅλον τόπον, οὗ δεῖ στρατοπεδεύειν, ἐν αὐτῷ τούτῳ πρῶτον μὲν διέλαβον τὴν τοῦ στρατηγοῦ σκηνὴν οὗ δεήσει θεῖναι κατὰ τὸν ἄρτι λόγον, καὶ παρὰ ποίαν ἐπιφάνειαν καὶ πλευρὰν τῆς περὶ τὴν σκηνὴν περιστάσεως παρεμβαλεῖν τὰ στρατόπεδα· τούτων δὲ προκριθέντων διαμετροῦνται τὴν περίστασιν τῆς σκηνῆς, μετὰ δὲ ταῦτα τὴν εὐθεῖαν, ἐφ’ ἧς αἱ σκηναὶ τίθενται τῶν χιλιάρχων, ἑξῆς δὲ τὴν ταύτης παράλληλον, ἀφ’ ἧς ἄρχεται τὰ στρατόπεδα παρεμβάλλειν. ὁμοίως δὲ καὶ τὰ ἐπὶ θάτερα μέρη τῆς σκηνῆς κατεμετρήσαντο γραμμαῖς, περὶ ὧν ὑπεδείξαμεν ἄρτι διὰ πλειόνων κατὰ μέρος. γενομένων δὲ τούτων ἐν βραχεῖ χρόνῳ διὰ τὸ ῥᾳδίαν εἶναι τὴν καταμέτρησιν, ὡς ἁπάντων ὡρισμένων καὶ συνήθων ὄντων διαστημάτων, μετὰ δὲ ταῦτα σημαίαν ἔπηξαν μίαν μὲν καὶ πρώτην, ἐν ᾧ δεῖ τόπῳ τίθεσθαι τὴν τοῦ στρατηγοῦ σκηνήν, δευτέραν δὲ τὴν ἐπὶ τῆς προκριθείσης πλευρᾶς, τρίτην ἐπὶ μέσης τῆς γραμμῆς ἐφ’ ἧς οἱ χιλίαρχοι σκηνοῦσι, τετάρτην, παρ’ ἣν τίθενται τὰ στρατόπεδα. καὶ ταύτας μὲν ποιοῦσι φοινικιᾶς, τὴν δὲ τοῦ στρατηγοῦ λευκήν. τὰ δ’ ἐπὶ θάτερα ποτὲ μὲν ψιλὰ δόρατα πηγνύουσι, ποτὲ δὲ σημαίας ἐκ τῶν ἄλλων χρωμάτων. γενομένων δὲ τούτων ἑξῆς τὰς ῥύμας διεμέτρησαν καὶ δόρατα κατέπηξαν ἐφ’ ἑκάστης ῥύμης. ἐξ ὧν εἰκότως, ὅταν ἐγγίσῃ τὰ στρατόπεδα κατὰ τὰς πορείας καὶ γένητ’ εὐσύνοπτος ὁ τόπος τῆς παρεμβολῆς, εὐθέως ἅπαντα γίνεται πᾶσι γνώριμα, τεκμαιρομένοις καὶ συλλογιζομένοις ἀπὸ τῆς τοῦ στρατηγοῦ σημαίας. λοιπὸν ἑκάστου σαφῶς γινώσκοντος ἐν ποίᾳ ῥύμῃ καὶ ποίῳ τόπῳ τῆς ῥύμης σκηνοῖ διὰ τὸ πάντας ἀεὶ τὸν αὐτὸν ἐπέχειν τῆς στρατοπεδείας, γίνεταί τι παραπλήσιον, οἷον ὅταν εἰς πόλιν εἰσίῃ στρατόπεδον ἐγχώριον. καὶ γὰρ ἐκεῖ διακλίναντες ἀπὸ τῶν πυλῶν εὐθέως ἕκαστοι προάγουσι καὶ παραγίνονται πρὸς τὰς ἰδίας οἰκήσεις ἀδιαπτώτως, διὰ τὸ καθόλου καὶ κατὰ μέρος γινώσκειν ποῦ τῆς πόλεώς ἐστιν αὐτοῖς ἡ κατάλυσις. τὸ δὲ παραπλήσιον τούτοις καὶ περὶ τὰς Ῥωμαϊκὰς συμβαίνει στρατοπεδείας.", "st": "6.41"}, {"sp": "N", "t": "ἧι δοκοῦσι Ῥωμαῖοι καταδιώκοντες τὴν ἐν τούτοις εὐχέρειαν τὴν ἐναντίαν ὁδὸν πορεύεσθαι τοῖς Ἕλλησι κατὰ τοῦτο τὸ μέρος. οἱ μὲν γὰρ Ἕλληνες ἐν τῷ στρατοπεδεύειν ἡγοῦνται κυριώτατον τὸ κατακολουθεῖν ταῖς ἐξ αὐτῶν τῶν τόπων ὀχυρότησιν, ἅμα μὲν ἐκκλίνοντες τὴν περὶ τὰς ταφρείας ταλαιπωρίαν, ἅμα δὲ νομίζοντες οὐχ ὁμοίας εἶναι τὰς χειροποιήτους ἀσφαλείας ταῖς ἐξ αὐτῆς τῆς φύσεως ἐπὶ τῶν τόπων ὑπαρχούσαις ὀχυρότησι. διὸ καὶ κατά τε τὴν τῆς ὅλης παρεμβολῆς θέσιν πᾶν ἀναγκάζονται σχῆμα μεταλαμβάνειν, ἑπόμενοι τοῖς τόποις, τά τε μέρη μεταλλάττειν ἄλλοτε πρὸς ἄλλους καὶ ἀκαταλλήλους τόπους· ἐξ ὧν ἄστατον ὑπάρχειν συμβαίνει καὶ τὸν κατ’ ἰδίαν καὶ τὸν κατὰ μέρος ἑκάστῳ τόπον τῆς στρατοπεδείας. Ῥωμαῖοι δὲ τὴν περὶ τὰς τάφρους ταλαιπωρίαν καὶ τἄλλα τὰ παρεπόμενα τούτοις ὑπομένειν αἱροῦνται χάριν τῆς εὐχερείας καὶ τοῦ γνώριμον καὶ μίαν ἔχειν καὶ τὴν αὐτὴν αἰεὶ παρεμβολήν. τὰ μὲν οὖν ὁλοσχερέστερα μέρη τῆς περὶ τὰ στρατόπεδα θεωρίας, καὶ μάλιστα περὶ τὰς παρεμβολάς, ταῦτ’ ἔστιν.", "st": "6.42"}, {"sp": "N", "t": "σχεδὸν δὴ πάντες οἱ συγγραφεῖς περὶ τούτων ἡμῖν τῶν πολιτευμάτων παραδεδώκασι τὴν ἐπ’ ἀρετῇ φήμην, περί τε τοῦ Λακεδαιμονίων καὶ Κρητῶν καὶ Μαντινέων, ἔτι δὲ Καρχηδονίων· ἔνιοι δὲ καὶ περὶ τῆς Ἀθηναίων καὶ Θηβαίων πολιτείας πεποίηνται μνήμην. ἐγὼ δὲ ταύτας μὲν ἐῶ, τὴν γὰρ Ἀθηναίων καὶ Θηβαίων οὐ πάνυ τι πολλοῦ προσδεῖσθαι πέπεισμαι λόγου διὰ τὸ μήτε τὰς αὐξήσεις ἐσχηκέναι κατὰ λόγον μήτε τὰς ἀκμὰς ἐπιμόνους, μήτε τὰς μεταβολὰς ἐνηλλαχέναι μετρίως, ἀλλ’ ὥσπερ ἐκ προσπαίου τινὸς τύχης σὺν καιρῷ λάμψαντας, τὸ δὴ λεγόμενον, ἔτι δοκοῦντας ἀκμὴν καὶ μέλλοντας εὐτυχεῖν, τῆς ἐναντίας πεῖραν εἰληφέναι μεταβολῆς. Θηβαῖοι μὲν γὰρ τῇ Λακεδαιμονίων ἀγνοίᾳ καὶ τῷ τῶν συμμάχων πρὸς αὐτοὺς μίσει συνεπιθέμενοι, διὰ τὴν ἑνὸς ἀνδρὸς ἀρετὴν ἢ καὶ δευτέρου, τῶν τὰ προειρημένα συνιδόντων, περιεποιήσαντο παρὰ τοῖς Ἕλλησι τὴν ἐπ’ ἀρετῇ φήμην. ὅτι γὰρ οὐχ ἡ τῆς πολιτείας σύστασις αἰτία τότ’ ἐγένετο Θηβαίοις τῶν εὐτυχημάτων, ἀλλ’ ἡ τῶν προεστώτων ἀνδρῶν ἀρετή, παρὰ πόδας ἡ τύχη τοῦτο πᾶσιν ἐποίησε δῆλον· καὶ γὰρ συνηυξήθη καὶ συνήκμασε καὶ συγκατελύθη τὰ Θηβαίων ἔργα τῷ τ’ Ἐπαμινώνδου καὶ τῷ Πελοπίδου βίῳ προφανῶς. ἐξ ὧν οὐ τὴν πολιτείαν αἰτίαν, ἀλλὰ τοὺς ἄνδρας ἡγητέον τῆς τότε γενομένης περὶ τὴν Θηβαίων πόλιν ἐπιφανείας.", "st": "6.43"}, {"sp": "N", "t": "τὸ δὲ παραπλήσιον καὶ περὶ τῆς Ἀθηναίων πολιτείας διαληπτέον. καὶ γὰρ αὕτη πλεονάκις μὲν ἴσως, ἐκφανέστατα δὲ τῇ Θεμιστοκλέους ἀρετῇ συνανθήσασα ταχέως τῆς ἐναντίας μεταβολῆς ἔλαβε πεῖραν διὰ τὴν ἀνωμαλίαν τῆς φύσεως. ἀεὶ γάρ ποτε τὸν τῶν Ἀθηναίων δῆμον παραπλήσιον εἶναι συμβαίνει τοῖς ἀδεσπότοις σκάφεσι. καὶ γὰρ ἐπ’ ἐκείνων, ὅταν μὲν ἢ διὰ πελαγῶν φόβον ἢ διὰ περίστασιν χειμῶνος ὁρμὴ παραστῇ τοῖς ἐπιβάταις συμφρονεῖν καὶ προσέχειν τὸν νοῦν τῷ κυβερνήτῃ, γίνεται τὸ δέον ἐξ αὐτῶν διαφερόντως· ὅταν δὲ θαρρήσαντες ἄρξωνται καταφρονεῖν τῶν προεστώτων καὶ στασιάζειν πρὸς ἀλλήλους διὰ τὸ μηκέτι δοκεῖν πᾶσι ταὐτά, τότε δὴ τῶν μὲν ἔτι πλεῖν προαιρουμένων, τῶν δὲ κατεπειγόντων ὁρμίζειν τὸν κυβερνήτην, καὶ τῶν μὲν ἐκσειόντων τοὺς κάλους, τῶν δ’ ἐπιλαμβανομένων καὶ στέλλεσθαι παρακελευομένων, αἰσχρὰ μὲν πρόσοψις γίνεται τοῖς ἔξωθεν θεωμένοις διὰ τὴν ἐν ἀλλήλοις διαφορὰν καὶ στάσιν, ἐπισφαλὴς δ’ ἡ διάθεσις τοῖς μετασχοῦσι καὶ κοινωνήσασι τοῦ πλοῦ· διὸ καὶ πολλάκις διαφυγόντες τὰ μέγιστα πελάγη καὶ τοὺς ἐπιφανεστάτους χειμῶνας ἐν τοῖς λιμέσι καὶ πρὸς τῇ γῇ ναυαγοῦσιν. ὃ δὴ καὶ τῇ τῶν Ἀθηναίων πολιτείᾳ πλεονάκις ἤδη συμβέβηκε· διωσαμένη γὰρ ἐνίοτε τὰς μεγίστας καὶ δεινοτάτας περιστάσεις διά τε τὴν τοῦ δήμου καὶ τὴν τῶν προεστώτων ἀρετὴν ἐν ταῖς ἀπεριστάτοις ῥᾳστώναις εἰκῇ πως καὶ ἀλόγως ἐνίοτε σφάλλεται. διὸ καὶ περὶ μὲν ταύτης τε καὶ τῆς τῶν Θηβαίων οὐδὲν δεῖ πλείω λέγειν, ἐν αἷς ὄχλος χειρίζει τὰ ὅλα κατὰ τὴν ἰδίαν ὁρμήν, ὁ μὲν ὀξύτητι καὶ πικρίᾳ διαφέρων, ὁ δὲ βίᾳ καὶ θυμῷ συμπεπαιδευμένος.", "st": "6.44"}, {"sp": "N", "t": "ἐπὶ δὲ τὴν Κρηταιῶν μεταβάντας ἄξιον ἐπιστῆσαι κατὰ δύο τρόπους πῶς οἱ λογιώτατοι τῶν ἀρχαίων συγγραφέων, Ἔφορος, Ξενοφῶν, Καλλισθένης, Πλάτων, πρῶτον μὲν ὁμοίαν εἶναί φασι καὶ τὴν αὐτὴν τῇ Λακεδαιμονίων, δεύτερον δ’ ἐπαινετὴν ὑπάρχουσαν ἀποφαίνουσιν· ὧν οὐδέτερον ἀληθὲς εἶναί μοι δοκεῖ. σκοπεῖν δ’ ἐκ τούτων πάρεστι. καὶ πρῶτον ὑπὲρ τῆς ἀνομοιότητος διέξιμεν. τῆς μὲν δὴ Λακεδαιμονίων πολιτείας ἴδιον εἶναί φασι πρῶτον μὲν τὰ περὶ τὰς ἐγγαίους κτήσεις, ὧν οὐδενὶ μέτεστι πλεῖον, ἀλλὰ πάντας τοὺς πολίτας ἴσον ἔχειν δεῖ τῆς πολιτικῆς χώρας, δεύτερον τὰ περὶ τὴν τοῦ διαφόρου κτῆσιν, ἧς εἰς τέλος ἀδοκίμου παρ’ αὐτοῖς ὑπαρχούσης ἄρδην ἐκ τῆς πολιτείας ἀνῃρῆσθαι συμβαίνει τὴν περὶ τὸ πλεῖον καὶ τοὔλαττον φιλοτιμίαν. τρίτον παρὰ Λακεδαιμονίοις οἱ μὲν βασιλεῖς ἀΐδιον ἔχουσι τὴν ἀρχήν, οἱ δὲ προσαγορευόμενοι γέροντες διὰ βίου, δι’ ὧν καὶ μεθ’ ὧν πάντα χειρίζεται τὰ κατὰ τὴν πολιτείαν.", "st": "6.45"}, {"sp": "N", "t": "παρὰ δὲ Κρηταιεῦσι πάντα τούτοις ὑπάρχει τἀναντία· τήν τε γὰρ χώραν κατὰ δύναμιν αὐτοῖς ἐφιᾶσιν οἱ νόμοι, τὸ δὴ λεγόμενον, εἰς ἄπειρον κτᾶσθαι, τό τε διάφορον ἐκτετίμηται παρ’ αὐτοῖς ἐπὶ τοσοῦτον ὥστε μὴ μόνον ἀναγκαίαν, ἀλλὰ καὶ καλλίστην εἶναι δοκεῖν τὴν τούτου κτῆσιν. καθόλου θ’ ὁ περὶ τὴν αἰσχροκέρδειαν καὶ πλεονεξίαν τρόπος οὕτως ἐπιχωριάζει παρ’ αὐτοῖς ὥστε παρὰ μόνοις Κρηταιεῦσι τῶν ἁπάντων ἀνθρώπων μηδὲν αἰσχρὸν νομίζεσθαι κέρδος. καὶ μὴν τὰ κατὰ τὰς ἀρχὰς ἐπέτεια παρ’ αὐτοῖς ἐστι καὶ δημοκρατικὴν ἔχει διάθεσιν. ὥστε πολλάκις διαπορεῖν πῶς ἡμῖν περὶ τῶν τὴν ἐναντίαν φύσιν ἐχόντων ὡς οἰκείων καὶ συγγενῶν ὄντων ἀλλήλοις ἐξηγγέλκασι. καὶ χωρὶς τοῦ παραβλέπειν τὰς τηλικαύτας διαφορὰς καὶ πολὺν δή τινα λόγον ἐν ἐπιμέτρῳ διατίθενται, φάσκοντες τὸν Λυκοῦργον μόνον τῶν γεγονότων τὰ συνέχοντα τεθεωρηκέναι· δυεῖν γὰρ ὄντων, δι’ ὧν σῴζεται πολίτευμα πᾶν, τῆς πρὸς τοὺς πολεμίους ἀνδρείας καὶ τῆς πρὸς σφᾶς αὐτοὺς ὁμονοίας, ἀνῃρηκότα τὴν πλεονεξίαν ἅμα ταύτῃ συνανῃρηκέναι πᾶσαν ἐμφύλιον διαφορὰν καὶ στάσιν· ᾗ καὶ Λακεδαιμονίους, ἐκτὸς ὄντας τῶν κακῶν τούτων, κάλλιστα τῶν Ἑλλήνων τὰ πρὸς σφᾶς αὐτοὺς πολιτεύεσθαι καὶ συμφρονεῖν ταὐτά. ταῦτα δ’ ἀποφηνάμενοι, καὶ θεωροῦντες ἐκ παραθέσεως Κρηταιεῖς διὰ τὴν ἔμφυτον σφίσι πλεονεξίαν ἐν πλείσταις ἰδίᾳ καὶ κατὰ κοινὸν στάσεσι καὶ φόνοις καὶ πολέμοις ἐμφυλίοις ἀναστρεφομένους, οὐδὲν οἴονται πρὸς σφᾶς εἶναι, θαρροῦσι δὲ λέγειν ὡς ὁμοίων ὄντων τῶν πολιτευμάτων. ὁ δ’ Ἔφορος χωρὶς τῶν ὀνομάτων καὶ ταῖς λέξεσι κέχρηται ταῖς αὐταῖς, ὑπὲρ ἑκατέρας ποιούμενος τῆς πολιτείας ἐξήγησιν, ὥστ’, εἴ τις μὴ τοῖς κυρίοις ὀνόμασι προσέχοι, κατὰ μηδένα τρόπον ἂν δύνασθαι διαγνῶναι περὶ ὁποτέρας ποιεῖται τὴν διήγησιν. ἧι μὲν οὖν μοι δοκοῦσι διαφέρειν ἀλλήλων, ταῦτ’ ἔστιν ᾗ δὲ πάλιν οὔτ’ ἐπαινετὴν οὔτε ζηλωτὴν ἡγούμεθ’ εἶναι τὴν Κρητικὴν πολιτείαν, νῦν ἤδη διέξιμεν.", "st": "6.46"}, {"sp": "N", "t": "ἐγὼ γὰρ οἶμαι δύ’ ἀρχὰς εἶναι πάσης πολιτείας, δι’ ὧν αἱρετὰς ἢ φευκτὰς συμβαίνει γίνεσθαι τάς τε δυνάμεις αὐτῶν καὶ τὰς συστάσεις· αὗται δ’ εἰσὶν ἔθη καὶ νόμοι· ὧν τὰ μὲν αἱρετὰ τούς τε κατ’ ἰδίαν βίους τῶν ἀνθρώπων ὁσίους ἀποτελεῖ καὶ σώφρονας τό τε κοινὸν ἦθος τῆς πόλεως ἥμερον ἀπεργάζεται καὶ δίκαιον, τὰ δὲ φευκτὰ τοὐναντίον. ὥσπερ οὖν, ὅταν τοὺς ἐθισμοὺς καὶ νόμους κατίδωμεν παρά τισι σπουδαίους ὑπάρχοντας, θαρροῦντες ἀποφαινόμεθα καὶ τοὺς ἄνδρας ἐκ τούτων ἔσεσθαι καὶ τὴν τούτων πολιτείαν σπουδαίαν, οὕτως, ὅταν τούς τε κατ’ ἰδίαν βίους τινῶν πλεονεκτικοὺς τάς τε κοινὰς πράξεις ἀδίκους θεωρήσωμεν, δῆλον ὡς εἰκὸς λέγειν καὶ τοὺς νόμους καὶ τὰ κατὰ μέρος ἤθη καὶ τὴν ὅλην πολιτείαν αὐτῶν εἶναι φαύλην. καὶ μὴν οὔτε κατ’ ἰδίαν ἤθη δολιώτερα Κρηταιέων εὕροι τις ἂν πλὴν τελείως ὀλίγων οὔτε κατὰ κοινὸν ἐπιβολὰς ἀδικωτέρας. διόπερ οὔθ’ ὁμοίαν αὐτὴν ἡγούμενοι τῇ Λακεδαιμονίων οὔτε μὴν ἄλλως αἱρετὴν οὔτε ζηλωτὴν ἀποδοκιμάζομεν ἐκ τῆς προειρημένης συγκρίσεως. καὶ μὴν οὐδὲ τὴν Πλάτωνος πολιτείαν δίκαιον παρεισαγαγεῖν, ἐπειδὴ καὶ ταύτην τινὲς τῶν φιλοσόφων ἐξυμνοῦσιν. ὥσπερ γὰρ οὐδὲ τῶν τεχνιτῶν ἢ τῶν ἀθλητῶν τούς γε μὴ νενεμημένους ἢ σεσωμασκηκότας παρίεμεν εἰς τοὺς ἀθλητικοὺς ἀγῶνας, οὕτως οὐδὲ ταύτην χρὴ παρεισαγαγεῖν εἰς τὴν τῶν πρωτείων ἅμιλλαν, ἐὰν μὴ πρότερον ἐπιδείξηταί τι τῶν ἑαυτῆς ἔργων ἀληθινῶς. μέχρι δὲ τοῦ νῦν παραπλήσιος ἂν ὁ περὶ αὐτῆς φανείη λόγος, ἀγομένης εἰς σύγκρισιν πρὸς τὴν Σπαρτιατῶν καὶ Ῥωμαίων καὶ Καρχηδονίων πολιτείαν, ὡς ἂν εἰ τῶν ἀγαλμάτων τις ἓν προθέμενος τοῦτο συγκρίνοι τοῖς ζῶσι καὶ πεπνυμένοις ἀνδράσι. καὶ γὰρ ἂν ὅλως ἐπαινετὸν ὑπάρχῃ κατὰ τὴν τέχνην, τήν γε σύγκρισιν τῶν ἀψύχων τοῖς ἐμψύχοις ἐνδεῆ καὶ τελείως ἀπεμφαίνουσαν εἰκὸς προσπίπτειν τοῖς θεωμένοις.", "st": "6.47"}, {"sp": "N", "t": "διόπερ ἀφέμενοι τούτων ἐπὶ τὴν Λακωνικὴν ἐπάνιμεν πολιτείαν. δοκεῖ δή μοι Λυκοῦργος πρὸς μὲν τὸ σφίσιν ὁμονοεῖν τοὺς πολίτας καὶ πρὸς τὸ τὴν Λακωνικὴν τηρεῖν ἀσφαλῶς, ἔτι δὲ τὴν ἐλευθερίαν διαφυλάττειν τῇ Σπάρτῃ βεβαίως, οὕτως νενομοθετηκέναι καὶ προνενοῆσθαι καλῶς ὥστε θειοτέραν τὴν ἐπίνοιαν ἢ κατ’ ἄνθρωπον αὐτοῦ νομίζειν. ἡ μὲν γὰρ περὶ τὰς κτήσεις ἰσότης καὶ περὶ τὴν δίαιταν ἀφέλεια καὶ κοινότης σώφρονας μὲν ἔμελλε τοὺς κατ’ ἰδίαν βίους παρασκευάζειν, ἀστασίαστον δὲ τὴν κοινὴν παρέξεσθαι πολιτείαν, ἡ δὲ πρὸς τοὺς πόνους καὶ πρὸς τὰ δεινὰ τῶν ἔργων ἄσκησις ἀλκίμους καὶ γενναίους ἀποτελέσειν ἄνδρας. ἑκατέρων δὲ τούτων ὁμοῦ συνδραμόντων εἰς μίαν ψυχὴν ἢ πόλιν, ἀνδρείας καὶ σωφροσύνης, οὐτ’ ἐξ αὐτῶν φῦναι κακίαν εὐμαρὲς οὔθ’ ὑπὸ τῶν πέλας χειρωθῆναι ῥᾴδιον. διόπερ οὕτως καὶ διὰ τούτων συστησάμενος τὴν πολιτείαν, βεβαίαν μὲν τῇ συμπάσῃ Λακωνικῇ παρεσκεύασε τὴν ἀσφάλειαν, πολυχρόνιον δὲ τοῖς Σπαρτιάταις αὐτοῖς ἀπέλιπε τὴν ἐλευθερίαν. πρὸς μέντοι γε τὴν τῶν πέλας κατάκτησιν καὶ πρὸς ἡγεμονίαν καὶ καθόλου πρὸς πραγμάτων ἀμφισβήτησιν οὔτ’ ἐν τοῖς κατὰ μέρος οὔτ’ ἐν τοῖς ὅλοις δοκεῖ μοι προνοηθῆναι καθάπαξ οὐδέν. λοιπὸν ἦν τοιαύτην τινὰ παρεισαγαγεῖν [δεῖ] τοῖς πολίταις ἀνάγκην ἢ πρόθεσιν, δι’ ἧς ὥσπερ καὶ περὶ τοὺς κατ’ ἰδίαν βίους αὐτάρκεις αὐτοὺς παρεσκεύασε καὶ λιτούς, οὕτως καὶ τὸ κοινὸν ἔθος τῆς πόλεως αὔταρκες ἔμελλε γίνεσθαι καὶ σῶφρον. νῦν δ’ ἀφιλοτιμοτάτους καὶ νουνεχεστάτους ποιήσας περί τε τοὺς ἰδίους βίου, καὶ τὰ τῆς σφετέρας πόλεως νόμιμα, πρὸς τοὺς ἄλλους Ἕλληνας φιλοτιμοτάτους καὶ φιλαρχοτάτους καὶ πλεονεκτικωτάτους ἀπέλιπε.", "st": "6.48"}, {"sp": "N", "t": "τοῦτο μὲν γὰρ τίς οὐκ οἶδε διότι πρῶτοι σχεδὸν τῶν Ἑλλήνων ἐπιθυμήσαντες τῆς τῶν ἀστυγειτόνων χώρας διὰ πλεονεξίαν ἐπ’ ἐξανδραποδισμῷ Μεσσηνίοις πόλεμον ἐξήνεγκαν; τοῦτο δὲ τίς οὐχ ἱστόρηκεν ὡς διὰ φιλονεικίαν ἐνόρκους σφᾶς ἐποίησαν μὴ πρόσθεν λύσειν τὴν πολιορκίαν πρὶν ἢ κατὰ κράτος ἑλεῖν τὴν Μεσσήνην; καὶ μὴν τοῦτο γνώριμον ὑπάρχει πᾶσιν, ὡς διὰ τὴν ἐν τοῖς Ἕλλησι φιλαρχίαν, οὓς ἐνίκησαν μαχόμενοι, τούτοις αὖτις ὑπέμειναν ποιεῖν τὸ προσταττόμενον. ἐπιπορευομένους μὲν γὰρ τοὺς Πέρσας ἐνίκων διαγωνιζόμενοι περὶ τῆς τῶν Ἑλλήνων ἐλευθερίας· ἐπανελθοῦσι δὲ καὶ φυγοῦσι προύδωκαν ἐκδότους τὰς Ἑλληνίδας πόλεις κατὰ τὴν ἐπ’ Ἀνταλκίδου γενομένην εἰρήνην χάριν τοῦ χρημάτων εὐπορῆσαι πρὸς τὴν κατὰ τῶν Ἑλλήνων δυναστείαν, ὅτε δὴ καὶ τὸ τῆς νομοθεσίας ἐλλιπὲς συνώφθη παρ’ αὐτοῖς. ἕως μὲν γὰρ τῆς τῶν ἀστυγειτόνων, ἔτι δὲ τῆς Πελοποννησίων αὐτῶν ἀρχῆς ἐφίεντο, συνεξεποιοῦντο ταῖς ἐκ τῆς Λακωνικῆς αὐτῆς ἐπαρκείαις καὶ χορηγίαις, προχείρους μὲν ἔχοντες τὰς τῶν ἐπιτηδείων παρασκευάς, ταχείας δὲ ποιούμενοι τὰς εἰς τὴν οἰκείαν ἐπανόδους καὶ παρακομιδάς. ἐπεὶ δὲ στόλους μὲν ἐπεβάλλοντο κατὰ θάλατταν ἐκπέμπειν, στρατεύειν δὲ πεζικοῖς στρατοπέδοις ἔξω Πελοποννήσου, δῆλον ὡς οὔτε τὸ νόμισμα τὸ σιδηροῦν οὔθ’ ἡ τῶν ἐπετείων καρπῶν ἀλλαγὴ πρὸς τὰ λείποντα τῆς χρείας ἔμελλεν αὐτοῖς ἐξαρκεῖν κατὰ τὴν Λυκούργου νομοθεσίαν· προσεδεῖτο γὰρ τὰ πράγματα κοινοῦ νομίσματος καὶ ξενικῆς παρασκευῆς. ὅθεν ἠναγκάσθησαν ἐπὶ θύρας μὲν πορεύεσθαι τὰς Περσῶν, φόρους δὲ τοῖς νησιώταις ἐπιτάττειν, ἀργυρολογεῖν δὲ πάντας τοὺς Ἕλληνας, γνόντες ὡς οὐχ οἷόν τε κατὰ τὴν Λυκούργου νομοθεσίαν οὐχ ὅτι τῆς τῶν Ἑλλήνων ἡγεμονίας, ἀλλ’ οὐδὲ πραγμάτων ἀντιποιεῖσθαι τὸ παράπαν.", "st": "6.49"}, {"sp": "N", "t": "τίνος οὖν χάριν εἰς ταῦτα παρεξέβην; ἵνα γένηται δι’ αὐτῶν τῶν πραγμάτων συμφανὲς ὅτι πρὸς μὲν τὸ τὰ σφέτερα βεβαίως διαφυλάττειν καὶ πρὸς τὸ τὴν ἐλευθερίαν τηρεῖν αὐτάρκης ἐστὶν ἡ Λυκούργου νομοθεσία, καὶ τοῖς γε τοῦτο τὸ τέλος ἀποδεχομένοις τῆς πολιτείας συγχωρητέον ὡς οὔτ’ ἔστιν οὔτε γέγονεν οὐδὲν αἱρετώτερον τοῦ Λακωνικοῦ καταστήματος καὶ συντάγματος. εἰ δέ τις μειζόνων ἐφίεται, κἀκείνου κάλλιον καὶ σεμνότερον εἶναι νομίζει τὸ πολλῶν μὲν ἡγεῖσθαι, πολλῶν δ’ ἐπικρατεῖν καὶ δεσπόζειν, πάντας δ’ εἰς αὐτὸν ἀποβλέπειν καὶ νεύειν πρὸς αὐτόν, τῇδέ πῃ συγχωρητέον τὸ μὲν Λακωνικὸν ἐνδεὲς εἶναι πολίτευμα, τὸ δὲ Ῥωμαίων διαφέρειν καὶ δυναμικωτέραν ἔχειν τὴν σύστασιν. δῆλον δὲ τοῦτ’ ἐξ αὐτῶν γέγονε τῶν πραγμάτων. Λακεδαιμόνιοι μὲν γὰρ ὁρμήσαντες ἐπὶ τὸ κατακτᾶσθαι τὴν τῶν Ἑλλήνων ἡγεμονίαν, ταχέως ἐκινδύνευσαν καὶ περὶ τῆς σφετέρας ἐλευθερίας· Ῥωμαῖοι δὲ τῆς Ἰταλιωτῶν αὐτῶν ἐπιλαβόμενοι δυναστείας, ἐν ὀλίγῳ χρόνῳ πᾶσαν ὑφ’ ἑαυτοὺς ἐποιήσαντο τὴν οἰκουμένην, οὐ μικρὰ πρὸς τὸ καθικέσθαι τῆς πράξεως ταύτης συμβαλλομένης αὐτοῖς τῆς εὐπορίας καὶ τῆς ἑτοιμότητος τῆς κατὰ τὰς χορηγίας.", "st": "6.50"}, {"sp": "N", "t": "τὸ δὲ Καρχηδονίων πολίτευμα τὸ μὲν ἀνέκαθέν μοι δοκεῖ καλῶς κατά γε τὰς ὁλοσχερεῖς διαφορὰς συνεστάσθαι. καὶ γὰρ βασιλεῖς ἦσαν παρ’ αὐτοῖς, καὶ τὸ γερόντιον εἶχε τὴν ἀριστοκρατικὴν ἐξουσίαν, καὶ τὸ πλῆθος ἦν κύριον τῶν καθηκόντων αὐτῷ· καθόλου δὲ τὴν τῶν ὅλων ἁρμογὴν εἶχε παραπλησίαν τῇ Ῥωμαίων καὶ Λακεδαιμονίων. κατά γε μὴν τοὺς καιροὺς τούτους, καθ’ οὓς εἰς τὸν Ἀννιβιακὸν ἐνέβαινε πόλεμον, χεῖρον ἦν τὸ Καρχηδονίων, ἄμεινον δὲ τὸ Ῥωμαίων. ἐπειδὴ γὰρ παντὸς καὶ σώματος καὶ πολιτείας καὶ πράξεώς ἐστί τις αὔξησις κατὰ φύσιν, μετὰ δὲ ταύτην ἀκμή, κἄπειτα φθίσις, κράτιστα δ’ αὑτῶν ἐστι πάντα τὰ κατὰ τὴν ἀκμήν, παρὰ τοῦτο καὶ τότε διέφερεν ἀλλήλων τὰ πολιτεύματα. καθ’ ὅσον γὰρ ἡ Καρχηδονίων πρότερον ἴσχυε καὶ πρότερον εὐτύχει τῆς Ῥωμαίων, κατὰ τοσοῦτον ἡ μὲν Καρχηδὼν ἤδη τότε παρήκμαζεν, ἡ δὲ Ῥώμη μάλιστα τότ’ εἶχε τὴν ἀκμὴν κατά γε τὴν τῆς πολιτείας σύστασιν. διὸ καὶ τὴν πλείστην δύναμιν ἐν τοῖς διαβουλίοις παρὰ μὲν Καρχηδονίοις ὁ δῆμος ἤδη μετειλήφει, παρὰ δὲ Ῥωμαίοις ἀκμὴν εἶχεν ἡ σύγκλητος. ὅθεν παρ’ οἷς μὲν τῶν πολλῶν βουλευομένων, παρ’ οἷς δὲ τῶν ἀρίστων, κατίσχυε τὰ Ῥωμαίων διαβούλια περὶ τὰς κοινὰς πράξεις. ᾗ καὶ πταίσαντες τοῖς ὅλοις τῷ βουλεύεσθαι καλῶς τέλος ἐπεκράτησαν τῷ πολέμῳ τῶν Καρχηδονίων.", "st": "6.51"}, {"sp": "N", "t": "τά γε μὴν κατὰ μέρος, οἷον εὐθέως τὰ πρὸς τὰς πολεμικὰς χρείας, τὸ μὲν πρὸς τὰς κατὰ θάλατταν, ὅπερ εἰκός, ἄμεινον ἀσκοῦσι καὶ παρασκευάζονται Καρχηδόνιοι διὰ τὸ καὶ πάτριον αὐτοῖς ὑπάρχειν ἐκ παλαιοῦ τὴν ἐμπειρίαν ταύτην καὶ θαλαττουργεῖν μάλιστα πάντων ἀνθρώπων, τὸ δὲ περὶ τὰς πεζικὰς χρείας πολὺ δή τι Ῥωμαῖοι πρὸς τὸ βέλτιον ἀσκοῦσι Καρχηδονίων. οἱ μὲν γὰρ τὴν ὅλην περὶ τοῦτο ποιοῦνται σπουδήν, Καρχηδόνιοι δὲ τῶν μὲν πεζικῶν εἰς τέλος ὀλιγωροῦσι, τῶν δ’ ἱππικῶν βραχεῖάν τινα ποιοῦνται πρόνοιαν. αἴτιον δὲ τούτων ἐστὶν ὅτι ξενικαῖς καὶ μισθοφόροις χρῶνται δυνάμεσι, Ῥωμαῖοι δ’ ἐγχωρίοις καὶ πολιτικαῖς. ᾗ καὶ περὶ τοῦτο τὸ μέρος ταύτην τὴν πολιτείαν ἀποδεκτέον ἐκείνης μᾶλλον· ἡ μὲν γὰρ ἐν ταῖς τῶν μισθοφόρων εὐψυχίαις ἔχει τὰς ἐλπίδας ἀεὶ τῆς ἐλευθερίας, ἡ δὲ Ῥωμαίων ἐν ταῖς σφετέραις ἀρεταῖς καὶ ταῖς τῶν συμμάχων ἐπαρκείαις. διὸ κἄν ποτε πταίσωσι κατὰ τὰς ἀρχάς, Ῥωμαῖοι μὲν ἀναμάχονται τοῖς ὅλοις, Καρχηδόνιοι δὲ τοὐναντίον. ἐκεῖνοι γὰρ ὑπὲρ πατρίδος ἀγωνιζόμενοι καὶ τέκνων οὐδέποτε δύνανται λῆξαι τῆς ὀργῆς, ἀλλὰ μένουσι ψυχομαχοῦντες, ἕως ἂν περιγένωνται τῶν ἐχθρῶν. διὸ καὶ περὶ τὰς ναυτικὰς δυνάμεις πολύ τι λειπόμενοι Ῥωμαῖοι κατὰ τὴν ἐμπειρίαν, ὡς προεῖπον ἐπάνω, τοῖς ὅλοις ἐπικρατοῦσι διὰ τὰς τῶν ἀνδρῶν ἀρετάς· καίπερ γὰρ οὐ μικρὰ συμβαλλομένης εἰς τοὺς κατὰ θάλατταν κινδύνους τῆς ναυτικῆς χρείας, ὅμως ἡ τῶν ἐπιβατῶν εὐψυχία πλείστην παρέχεται ῥοπὴν εἰς τὸ νικᾶν. διαφέρουσι μὲν οὖν καὶ φύσει πάντες Ἰταλιῶται Φοινίκων καὶ Λιβύων τῇ τε σωματικῇ ῥώμῃ καὶ ταῖς ψυχικαῖς τόλμαις· μεγάλην δὲ καὶ διὰ τῶν ἐθισμῶν πρὸς τοῦτο τὸ μέρος ποιοῦνται τῶν νέων παρόρμησιν. ἓν δὲ ῥηθὲν ἱκανὸν ἔσται σημεῖον τῆς τοῦ πολιτεύματος σπουδῆς, ἣν ποιεῖται περὶ τὸ τοιούτους ἀποτελεῖν ἄνδρας ὥστε πᾶν ὑπομένειν χάριν τοῦ τυχεῖν ἐν τῇ πατρίδι τῆς ἐπ’ ἀρετῇ φήμης.", "st": "6.52"}, {"sp": "N", "t": "ὅταν γὰρ μεταλλάξῃ τις παρ’ αὐτοῖς τῶν ἐπιφανῶν ἀνδρῶν, συντελουμένης τῆς ἐκφορᾶς κομίζεται μετὰ τοῦ λοιποῦ κόσμου πρὸς τοὺς καλουμένους ἐμβόλους εἰς τὴν ἀγορὰν ποτὲ μὲν ἑστὼς ἐναργής, σπανίως δὲ κατακεκλιμένος. πέριξ δὲ παντὸς τοῦ δήμου στάντος, ἀναβὰς ἐπὶ τοὺς ἐμβόλους, ἂν μὲν υἱὸς ἐν ἡλικίᾳ καταλείπηται καὶ τύχῃ παρών, οὗτος, εἰ δὲ μή, τῶν ἄλλων εἴ τις ἀπὸ γένους ὑπάρχει, λέγει περὶ τοῦ τετελευτηκότος τὰς ἀρετὰς καὶ τὰς ἐπιτετευγμένας ἐν τῷ ζῆν πράξεις. δι’ ὧν συμβαίνει τοὺς πολλοὺς ἀναμιμνησκομένους καὶ λαμβάνοντας ὑπὸ τὴν ὄψιν τὰ γεγονότα, μὴ μόνον τοὺς κεκοινωνηκότας τῶν ἔργων, ἀλλὰ καὶ τοὺς ἐκτός, ἐπὶ τοσοῦτον γίνεσθαι συμπαθεῖς ὥστε μὴ τῶν κηδευόντων ἴδιον, ἀλλὰ κοινὸν τοῦ δήμου φαίνεσθαι τὸ σύμπτωμα. μετὰ δὲ ταῦτα θάψαντες καὶ ποιήσαντες τὰ νομιζόμενα τιθέασι τὴν εἰκόνα τοῦ μεταλλάξαντος εἰς τὸν ἐπιφανέστατον τόπον τῆς οἰκίας, ξύλινα ναΐδια περιτιθέντες. ἡ δ’ εἰκών ἐστι πρόσωπον εἰς ὁμοιότητα διαφερόντως ἐξειργασμένον καὶ κατὰ τὴν πλάσιν καὶ κατὰ τὴν ὑπογραφήν. ταύτας δὴ τὰς εἰκόνας ἔν τε ταῖς δημοτελέσι θυσίαις ἀνοίγοντες κοσμοῦσι φιλοτίμως, ἐπάν τε τῶν οἰκείων μεταλλάξῃ τις ἐπιφανής, ἄγουσιν εἰς τὴν ἐκφοράν, περιτιθέντες ὡς ὁμοιοτάτοις εἶναι δοκοῦσι κατά τε τὸ μέγεθος καὶ τὴν ἄλλην περικοπήν. οὗτοι δὲ προσαναλαμβάνουσιν ἐσθῆτας, ἐὰν μὲν ὕπατος ἢ στρατηγὸς ᾖ γεγονώς, περιπορφύρους, ἐὰν δὲ τιμητής, πορφυρᾶς, ἐὰν δὲ καὶ τεθριαμβευκὼς ἤ τι τοιοῦτον κατειργασμένος, διαχρύσους. αὐτοὶ μὲν οὖν ἐφ’ ἁρμάτων οὗτοι πορεύονται, ῥάβδοι δὲ καὶ πελέκεις καὶ τἄλλα τὰ ταῖς ἀρχαῖς εἰωθότα συμπαρακεῖσθαι προηγεῖται κατὰ τὴν ἀξίαν ἑκάστῳ τῆς γεγενημένης κατὰ τὸν βίον ἐν τῇ πολιτείᾳ προαγωγῆς ὅταν δ’ ἐπὶ τοὺς ἐμβόλους ἔλθωσι, καθέζονται πάντες ἑξῆς ἐπὶ δίφρων ἐλεφαντίνων. οὗ κάλλιον οὐκ εὐμαρὲς ἰδεῖν θέαμα νέῳ φιλοδόξῳ καὶ φιλαγάθῳ· τὸ γὰρ τὰς τῶν ἐπ’ ἀρετῇ δεδοξασμένων ἀνδρῶν εἰκόνας ἰδεῖν ὁμοῦ πάσας οἷον εἰ ζώσας καὶ πεπνυμένας τίν’ οὐκ ἂν παραστήσαι; τί δ’ ἂν κάλλιον θέαμα τούτου φανείη;", "st": "6.53"}, {"sp": "N", "t": "πλὴν ὅ γε λέγων ὑπὲρ τοῦ θάπτεσθαι μέλλοντος, ἐπὰν διέλθῃ τὸν περὶ τούτου λόγον, ἄρχεται τῶν ἄλλων ἀπὸ τοῦ προγενεστάτου τῶν παρόντων, καὶ λέγει τὰς ἐπιτυχίας ἑκάστου καὶ τὰς πράξεις. ἐξ ὧν καινοποιουμένης ἀεὶ τῶν ἀγαθῶν ἀνδρῶν τῆς ἐπ’ ἀρετῇ φήμης ἀθανατίζεται μὲν ἡ τῶν καλόν τι διαπραξαμένων εὔκλεια, γνώριμος δὲ τοῖς πολλοῖς καὶ παραδόσιμος τοῖς ἐπιγινομένοις ἡ τῶν εὐεργετησάντων τὴν πατρίδα γίνεται δόξα. τὸ δὲ μέγιστον, οἱ νέοι παρορμῶνται πρὸς τὸ πᾶν ὑπομένειν ὑπὲρ τῶν κοινῶν πραγμάτων χάριν τοῦ τυχεῖν τῆς συνακολουθούσης τοῖς ἀγαθοῖς τῶν ἀνδρῶν εὐκλείας. πίστιν δ’ ἔχει τὸ λεγόμενον ἐκ τούτων. πολλοὶ μὲν γὰρ ἐμονομάχησαν ἑκουσίως Ῥωμαίων ὑπὲρ τῆς τῶν ὅλων κρίσεως, οὐκ ὀλίγοι δὲ προδήλους εἵλοντο θανάτους, τινὲς μὲν ἐν πολέμῳ τῆς τῶν ἄλλων ἕνεκεν σωτηρίας, τινὲς δ’ ἐν εἰρήνῃ χάριν τῆς τῶν κοινῶν πραγμάτων ἀσφαλείας. καὶ μὴν ἀρχὰς ἔχοντες ἔνιοι τοὺς ἰδίους υἱοὺς παρὰ πᾶν ἔθος ἢ νόμον ἀπέκτειναν, περὶ πλείονος ποιούμενοι τὸ τῆς πατρίδος συμφέρον τῆς κατὰ φύσιν οἰκειότητος πρὸς τοὺς ἀναγκαιοτάτους. πολλὰ μὲν οὖν τοιαῦτα καὶ περὶ πολλῶν ἱστορεῖται παρὰ Ῥωμαίοις ἓν δ’ ἀρκοῦν ἔσται πρὸς τὸ παρὸν ἐπ’ ὀνόματος ῥηθὲν ὑποδείγματος καὶ πίστεως ἕνεκεν.", "st": "6.54"}, {"sp": "N", "t": "Κόκλην γὰρ λέγεται τὸν Ὡράτιον ἐπικληθέντα, διαγωνιζόμενον πρὸς δύο τῶν ὑπεναντίων ἐπὶ τῷ καταντικρὺ τῆς γεφύρας πέρατι τῆς ἐπὶ τοῦ Τιβέριδος, ἣ κεῖται πρὸ τῆς πόλεως, ἐπεὶ πλῆθος ἐπιφερόμενον εἶδε τῶν βοηθούντων τοῖς πολεμίοις, δείσαντα μὴ βιασάμενοι παραπέσωσιν εἰς τὴν πόλιν, βοᾶν ἐπιστραφέντα τοῖς κατόπιν ὡς τάχος ἀναχωρήσαντας διασπᾶν τὴν γέφυραν. τῶν δὲ πειθαρχησάντων, ἕως μὲν οὗτοι διέσπων, ὑπέμενε τραυμάτων πλῆθος ἀναδεχόμενος καὶ διακατέσχε τὴν ἐπιφορὰν τῶν ἐχθρῶν, οὐχ οὕτως τὴν δύναμιν ὡς τὴν ὑπόστασιν αὐτοῦ καὶ τόλμαν καταπεπληγμένων τῶν ὑπεναντίων· διασπασθείσης δὲ τῆς γεφύρας, οἱ μὲν πολέμιοι τῆς ὁρμῆς ἐκωλύθησαν, ὁ δὲ Κόκλης ῥίψας ἑαυτὸν εἰς τὸν ποταμὸν ἐν τοῖς ὅπλοις κατὰ προαίρεσιν μετήλλαξε τὸν βίον, περὶ πλείονος ποιησάμενος τὴν τῆς πατρίδος ἀσφάλειαν καὶ τὴν ἐσομένην μετὰ ταῦτα περὶ αὐτὸν εὔκλειαν τῆς παρούσης ζωῆς καὶ τοῦ καταλειπομένου βίου. τοιαύτη τις, ὡς ἔοικε, διὰ τῶν παρ’ αὐτοῖς ἐθισμῶν ἐγγεννᾶται τοῖς νέοις ὁρμὴ καὶ φιλοτιμία πρὸς τὰ καλὰ τῶν ἔργων.", "st": "6.55"}, {"sp": "N", "t": "καὶ μὴν τὰ περὶ τοὺς χρηματισμοὺς ἔθη καὶ νόμιμα βελτίω παρὰ Ῥωμαίοις ἐστὶν ἢ παρὰ Καρχηδονίοις παρ’ οἷς μὲν γὰρ οὐδὲν αἰσχρὸν τῶν ἀνηκόντων πρὸς κέρδος, παρ’ οἷς δ’ οὐδὲν αἴσχιον τοῦ δωροδοκεῖσθαι καὶ τοῦ πλεονεκτεῖν ἀπὸ τῶν μὴ καθηκόντων καθ’ ὅσον γὰρ ἐν καλῷ τίθενται τὸν ἀπὸ τοῦ κρατίστου χρηματισμόν, κατὰ τοσοῦτο πάλιν ἐν ὀνείδει ποιοῦνται τὴν ἐκ τῶν ἀπειρημένων πλεονεξίαν. σημεῖον δὲ τοῦτο· παρὰ μὲν Καρχηδονίοις δῶρα φανερῶς διδόντες λαμβάνουσι τὰς ἀρχάς, παρὰ δὲ Ῥωμαίοις θάνατός ἐστι περὶ τοῦτο πρόστιμον. ὅθεν τῶν ἄθλων τῆς ἀρετῆς ἐναντίων τιθεμένων παρ’ ἀμφοῖν, εἰκὸς ἀνόμοιον εἶναι καὶ τὴν παρασκευὴν ἑκατέρων πρὸς ταῦτα. μεγίστην δέ μοι δοκεῖ διαφορὰν ἔχειν τὸ Ῥωμαίων πολίτευμα πρὸς βέλτιον ἐν τῇ περὶ θεῶν διαλήψει. καί μοι δοκεῖ τὸ παρὰ τοῖς ἄλλοις ἀνθρώποις ὀνειδιζόμενον, τοῦτο συνέχειν τὰ Ῥωμαίων πράγματα, λέγω δὲ τὴν δεισιδαιμονίαν· ἐπὶ τοσοῦτον γὰρ ἐκτετραγῴδηται καὶ παρεισῆκται τοῦτο τὸ μέρος παρ’ αὐτοῖς εἴς τε τοὺς κατ’ ἰδίαν βίους καὶ τὰ κοινὰ τῆς πόλεως ὥστε μὴ καταλιπεῖν ὑπερβολήν. ὃ καὶ δόξειεν ἂν πολλοῖς εἶναι θαυμάσιον. ἐμοί γε μὴν δοκοῦσι τοῦ πλήθους χάριν τοῦτο πεποιηκέναι. εἰ μὲν γὰρ ἦν σοφῶν ἀνδρῶν πολίτευμα συναγαγεῖν, ἴσως οὐδὲν ἦν ἀναγκαῖος ὁ τοιοῦτος τρόπος· ἐπεὶ δὲ πᾶν πλῆθός ἐστιν ἐλαφρὸν καὶ πλῆρες ἐπιθυμιῶν παρανόμων, ὀργῆς ἀλόγου, θυμοῦ βιαίου, λείπεται τοῖς ἀδήλοις φόβοις καὶ τῇ τοιαύτῃ τραγῳδίᾳ τὰ πλήθη συνέχειν. διόπερ οἱ παλαιοὶ δοκοῦσί μοι τὰς περὶ θεῶν ἐννοίας καὶ τὰς ὑπὲρ τῶν ἐν ᾅδου διαλήψεις οὐκ εἰκῇ καὶ ὡς ἔτυχεν εἰς τὰ πλήθη παρεισαγαγεῖν, πολὺ δὲ μᾶλλον οἱ νῦν εἰκῇ καὶ ἀλόγως ἐκβάλλειν αὐτά. τοιγαροῦν χωρὶς τῶν ἄλλων οἱ τὰ κοινὰ χειρίζοντες παρὰ μὲν τοῖς Ἕλλησιν, ἐὰν ταλάντου μόνον πιστευθῶσιν, ἀντιγραφεῖς ἔχοντες δέκα καὶ σφραγῖδας τοσαύτας καὶ μάρτυρας διπλασίους οὐ δύνανται τηρεῖν τὴν πίστιν· παρὰ δὲ Ῥωμαίοις κατά τε τὰς ἀρχὰς καὶ πρεσβείας πολύ τι πλῆθος χρημάτων χειρίζοντες δι’ αὐτῆς τῆς κατὰ τὸν ὅρκον πίστεως τηροῦσι τὸ καθῆκον. καὶ παρὰ μὲν τοῖς ἄλλοις σπάνιόν ἐστιν εὑρεῖν ἀπεχόμενον ἄνδρα τῶν δημοσίων καὶ καθαρεύοντα περὶ ταῦτα· παρὰ δὲ τοῖς Ῥωμαίοις σπάνιόν ἐστι τὸ λαβεῖν τινα πεφωραμένον ἐπὶ τοιαύτῃ πράξει.", "st": "6.56"}, {"sp": "N", "t": "ὅτι μὲν οὖν πᾶσι τοῖς οὖσιν ὑπόκειται φθορὰ καὶ μεταβολὴ σχεδὸν οὐ προσδεῖ λόγων· ἱκανὴ γὰρ ἡ τῆς φύσεως ἀνάγκη παραστῆσαι τὴν τοιαύτην πίστιν. δυεῖν δὲ τρόπων ὄντων, καθ’ οὓς φθείρεσθαι πέφυκε πᾶν γένος πολιτείας, τοῦ μὲν ἔξωθεν, τοῦ δ’ ἐν αὐτοῖς φυομένου, τὸν μὲν ἐκτὸς ἄστατον ἔχειν συμβαίνει τὴν θεωρίαν, τὸν δ’ ἐξ αὐτῶν τεταγμένην. τί μὲν δὴ πρῶτον φύεται γένος πολιτείας καὶ τί δεύτερον, καὶ πῶς εἰς ἄλληλα μεταπίπτουσιν, εἴρηται πρόσθεν ἡμῖν, ὥστε τοὺς δυναμένους τὰς ἀρχὰς τῷ τέλει συνάπτειν τῆς ἐνεστώσης ὑποθέσεως κἂν αὐτοὺς ἤδη προειπεῖν ὑπὲρ τοῦ μέλλοντος. ἔστι δ’, ὡς ἐγᾦμαι, δῆλον. ὅταν γὰρ πολλοὺς καὶ μεγάλους κινδύνους διωσαμένη πολιτεία μετὰ ταῦτα εἰς ὑπεροχὴν καὶ δυναστείαν ἀδήριτον ἀφίκηται, φανερὸν ὡς εἰσοικιζομένης εἰς αὐτὴν ἐπὶ πολὺ τῆς εὐδαιμονίας συμβαίνει τοὺς μὲν βίους γίνεσθαι πολυτελεστέρους, τοὺς δ’ ἄνδρας φιλονεικοτέρους τοῦ δέοντος περί τε τὰς ἀρχὰς καὶ τὰς ἄλλας ἐπιβολάς. ὧν προβαινόντων ἐπὶ πλέον ἄρξει μὲν τῆς ἐπὶ τὸ χεῖρον μεταβολῆς ἡ φιλαρχία καὶ τὸ τῆς ἀδοξίας ὄνειδος, πρὸς δὲ τούτοις ἡ περὶ τοὺς βίους ἀλαζονεία καὶ πολυτέλεια, λήψεται δὲ τὴν ἐπιγραφὴν τῆς μεταβολῆς ὁ δῆμος, ὅταν ὑφ’ ὧν μὲν ἀδικεῖσθαι δόξῃ διὰ τὴν πλεονεξίαν, ὑφ’ ὧν δὲ χαυνωθῇ κολακευόμενος διὰ τὴν φιλαρχίαν. τότε γὰρ ἐξοργισθεὶς καὶ θυμῷ πάντα βουλευόμενος οὐκέτι θελήσει πειθαρχεῖν οὐδ’ ἴσον ἔχειν τοῖς προεστῶσιν, ἀλλὰ πᾶν καὶ τὸ πλεῖστον αὐτός. οὗ γενομένου τῶν μὲν ὀνομάτων τὸ κάλλιστον ἡ πολιτεία μεταλήψεται, τὴν ἐλευθερίαν καὶ δημοκρατίαν, τῶν δὲ πραγμάτων τὸ χείριστον, τὴν ὀχλοκρατίαν. ἡμεῖς δ’ ἐπειδὴ τήν τε σύστασιν καὶ τὴν αὔξησιν τῆς πολιτείας, ἔτι δὲ τὴν ἀκμὴν καὶ τὴν διάθεσιν, πρὸς δὲ τούτοις τὴν διαφορὰν πρὸς τὰς ἄλλας τοῦ τε χείρονος ἐν αὐτῇ καὶ βελτίονος διεληλύθαμεν, τὸν μὲν περὶ τῆς πολιτείας λόγον ὧδέ πῃ καταστρέφομεν.", "st": "6.57"}, {"sp": "N", "t": "τῶν δὲ συναπτόντων μερῶν τῆς ἱστορίας τοῖς καιροῖς, ἀφ’ ὧν παρεξέβημεν, παραλαβόντες ἐπὶ βραχὺ μιᾶς πράξεως ποιησόμεθα κεφαλαιώδη μνήμην, ἵνα μὴ τῷ λόγῳ μόνον ἀλλὰ καὶ τοῖς πράγμασιν, ὥσπερ ἀγαθοῦ τεχνίτου δεῖγμα τῶν ἔργων ἕν τι προενεγκάμενοι, φανερὰν ποιήσωμεν τῆς πολιτείας τὴν ἀκμὴν καὶ δύναμιν, οἵα τις ἦν κατ’ ἐκείνους τοὺς χρόνους. Ἀννίβας γὰρ ἐπειδὴ τῇ περὶ Κάνναν μάχῃ περιγενόμενος Ῥωμαίων ἐγκρατὴς ἐγένετο τῶν τὸν χάρακα φυλαττόντων ὀκτακισχιλίων, ζωγρήσας ἅπαντας συνεχώρησε διαπέμπεσθαι σφίσι πρὸς τοὺς ἐν οἴκῳ περὶ λύτρων καὶ σωτηρίας. τῶν δὲ προχειρισαμένων δέκα τοὺς ἐπιφανεστάτους, ὁρκίσας ἦ μὴν ἐπανήξειν πρὸς αὐτόν, ἐξέπεμψε τούτους. εἷς δὲ τῶν προχειρισθέντων ἐκπορευόμενος ἐκ τοῦ χάρακος ἤδη, καί τι φήσας ἐπιλελῆσθαι, πάλιν ἀνέκαμψε, καὶ λαβὼν τὸ καταλειφθὲν αὖθις ἀπελύετο, νομίζων διὰ τῆς ἀναχωρήσεως τετηρηκέναι τὴν πίστιν καὶ λελυκέναι τὸν ὅρκον. ὧν παραγενομένων εἰς τὴν Ῥώμην, καὶ δεομένων καὶ παρακαλούντων τὴν σύγκλητον μὴ φθονῆσαι τοῖς ἑαλωκόσι τῆς σωτηρίας, ἀλλ’ ἐᾶσαι τρεῖς μνᾶς ἕκαστον καταβαλόντα σωθῆναι πρὸς τοὺς ἀναγκαίους· τοῦτο γὰρ συγχωρεῖν ἔφασαν τὸν Ἀννίβαν· εἶναι δ’ ἀξίους σωτηρίας αὑτούς· οὔτε γὰρ ἀποδεδειλιακέναι κατὰ τὴν μάχην οὔτ’ ἀνάξιον οὐδὲν πεποιηκέναι τῆς Ῥώμης, ἀλλ’ ἀπολειφθέντας τὸν χάρακα τηρεῖν, πάντων ἀπολομένων τῶν ἄλλων ἐν τῇ μάχῃ τῷ καιρῷ περιληφθέντας ὑποχειρίους γενέσθαι τοῖς πολεμίοις. Ῥωμαῖοι δὲ μεγάλοις κατὰ τὰς μάχας περιπεπτωκότες ἐλαττώμασι, πάντων δ’ ὡς ἔπος εἰπεῖν ἐστερημένοι τότε τῶν συμμάχων, ὅσον οὔπω δὲ προσδοκῶντες τὸν περὶ τῆς πατρίδος αὐτοῖς ἐκφέρεσθαι κίνδυνον, διακούσαντες τῶν λεγομένων οὔτε τοῦ πρέποντος αὑτοῖς εἴξαντες ταῖς συμφοραῖς ὠλιγώρησαν οὔτε τῶν δεόντων οὐδὲν τοῖς λογισμοῖς παρεῖδον, ἀλλὰ συνιδόντες τὴν Ἀννίβου πρόθεσιν, ὅτι βούλεται διὰ τῆς πράξεως ταύτης ἅμα μὲν εὐπορῆσαι χρημάτων, ἅμα δὲ τὸ φιλότιμον ἐν ταῖς μάχαις ἐξελέσθαι τῶν ἀντιταττομένων, ὑποδείξας ὅτι τοῖς ἡττημένοις ὅμως ἐλπὶς ἀπολείπεται σωτηρίας, τοσοῦτ’ ἀπέσχον τοῦ ποιῆσαί τι τῶν ἀξιουμένων ὥστ’ οὔτε τὸν τῶν οἰκείων ἔλεον οὔτε τὰς ἐκ τῶν ἀνδρῶν ἐσομένας χρείας ἐποιήσαντο περὶ πλείονος, ἀλλὰ τοὺς μὲν Ἀννίβου λογισμοὺς καὶ τὰς ἐν τούτοις ἐλπίδας ἀπέδειξαν κενάς, ἀπειπάμενοι τὴν διαλύτρωσιν τῶν ἀνδρῶν, τοῖς δὲ παρ’ αὑτῶν ἐνομοθέτησαν ἢ νικᾶν μαχομένους ἢ θνήσκειν, ὡς ἄλλης οὐδεμιᾶς ἐλπίδος ὑπαρχούσης εἰς σωτηρίαν αὐτοῖς ἡττωμένοις. διὸ καὶ ταῦτα προθέμενοι τοὺς μὲν ἐννέα τῶν πρεσβευτῶν ἐθελοντὴν κατὰ τὸν ὅρκον ἀναχωροῦντας ἐξέπεμψαν, τὸν δὲ σοφισάμενον πρὸς τὸ λῦσαι τὸν ὅρκον δήσαντες ἀποκατέστησαν πρὸς τοὺς πολεμίους, ὥστε τὸν Ἀννίβαν μὴ τοσοῦτον χαρῆναι νικήσαντα τῇ μάχῃ Ῥωμαίους ὡς συντριβῆναι καταπλαγέντα τὸ στάσιμον καὶ τὸ μεγαλόψυχον τῶν ἀνδρῶν ἐν τοῖς διαβουλίοις.", "st": "6.58"}, {"sp": "N", "t": "καὶ τόπος δέ τις οὕτω καλεῖται Ῥύγχος περὶ Στράτον τῆς Αἰτωλίας, ὥς φησι Πολύβιος ἐν ϛʹ ἱστοριῶν.", "st": "6.59"}, {"sp": "HDR", "t": "Βιβλίον Ζʹ", "st": "7"}, {"sp": "N", "t": "Πολύβιος δ’ ἐν τῇ ἑβδόμῃ \"Καπυησίους τοὺς ἐν Καμπανίᾳ διὰ τὴν ἀρετὴν τῆς γῆς πλοῦτον περιβαλομένους ἐξοκεῖλαι εἰς τρυφὴν καὶ πολυτέλειαν, ὑπερβαλλομένους τὴν περὶ Κρότωνα καὶ Σύβαριν παραδεδομένην φήμην. οὐ δυνάμενοι οὖν, φησί, φέρειν τὴν παροῦσαν εὐδαιμονίαν ἐκάλουν τὸν Ἀννίβαν. διόπερ ὑπὸ Ῥωμαίων ἀνήκεστα δεινὰ ἔπαθον. Πετηλῖνοι δὲ τηρήσαντες τὴν πρὸς Ῥωμαίους πίστιν εἰς τοσοῦτον καρτερίας ἦλθον πολιορκούμενοι ὑπ’ Ἀννίβα ὥστε μετὰ τὸ πάντα μὲν τὰ κατὰ τὴν πόλιν δέρματα καταφαγεῖν, ἁπάντων δὲ τῶν κατὰ τὴν πόλιν δένδρων τοὺς φλοιοὺς καὶ τοὺς ἁπαλοὺς πτόρθους ἀναλῶσαι, καὶ ἕνδεκα μῆνας ὑπομείναντες τὴν πολιορκίαν, οὐδενὸς βοηθοῦντος, συνευδοκούντων Ῥωμαίων παρέδοσαν ἑαυτούς.\" ἡ δὲ Καπύη μεταθεμένη πρὸς τοὺς Καρχηδονίους τῷ βάρει συνεπεσπάσατο καὶ τὰς ἄλλας πόλεις.", "st": "7.1"}, {"sp": "N", "t": "ὅτι μετὰ τὴν ἐπιβουλὴν τὴν κατὰ Ἱερωνύμου τοῦ βασιλέως Συρακοσίων, ἐκχωρήσαντος τοῦ Θράσωνος, οἱ περὶ τὸν Ζώιππον καὶ Ἀδρανόδωρον πείθουσι τὸν Ἱερώνυμον εὐθέως πρεσβευτὰς πρὸς τὸν Ἀννίβαν πέμψαι. προχειρισάμενος δὲ Πολύκλειτον τὸν Κυρηναῖον καὶ Φιλόδημον τὸν Ἀργεῖον, τούτους μὲν εἰς Ἰταλίαν ἀπέστειλε, δοὺς ἐντολὰς λαλεῖν ὑπὲρ κοινοπραγίας τοῖς Καρχηδονίοις, ἅμα δὲ καὶ τοὺς ἀδελφοὺς εἰς Ἀλεξάνδρειαν ἀπέπεμψεν. Ἀννίβας δὲ τοὺς περὶ Πολύκλειτον καὶ Φιλόδημον ἀποδεξάμενος φιλανθρώπως, καὶ πολλὰς ἐλπίδας ὑπογράψας τῷ μειρακίῳ [Ἱερωνύμῳ], σπουδῇ πάλιν ἀπέπεμψε τοὺς πρέσβεις, σὺν δὲ τούτοις Ἀννίβαν τὸν Καρχηδόνιον, ὄντα τότε τριήραρχον, καὶ τοὺς Συρακοσίους Ἱπποκράτην καὶ τὸν ἀδελφὸν αὐτοῦ τὸν νεώτερον Ἐπικύδην. συνέβαινε δὲ τούτους τοὺς ἄνδρας καὶ πλείω χρόνον ἤδη στρατεύεσθαι μετ’ Ἀννίβου, πολιτευομένους παρὰ Καρχηδονίοις διὰ τὸ φεύγειν αὐτῶν τὸν πάππον ἐκ Συρακουσῶν δόξαντα προσενηνοχέναι τὰς χεῖρας ἑνὶ τῶν Ἀγαθοκλέους υἱῶν Ἀγαθάρχῳ. παραγενομένων δὲ τούτων εἰς τὰς Συρακούσας, καὶ τῶν μὲν περὶ Πολύκλειτον ἀποπρεσβευσάντων, τοῦ δὲ Καρχηδονίου διαλεχθέντος κατὰ τὰς ὑπ’ Ἀννίβου δεδομένας ἐντολάς, εὐθέως ἕτοιμος ἦν κοινωνεῖν Καρχηδονίοις τῶν πραγμάτων· καὶ τόν τε παραγεγονότα πρὸς αὑτὸν Ἀννίβαν ἔφη δεῖν πορεύεσθαι κατὰ τάχος εἰς τὴν Καρχηδόνα, καὶ παρ’ αὑτοῦ συμπέμπειν ἐπηγγείλατο τοὺς διαλεχθησομένους τοῖς Καρχηδονίοις.", "st": "7.2"}, {"sp": "N", "t": "κατὰ δὲ τὸν καιρὸν τοῦτον ὁ τεταγμένος ἐπὶ Λιλυβαίου στρατηγὸς τῶν Ῥωμαίων ταῦτα πυνθανόμενος ἔπεμψε πρὸς Ἱερώνυμον πρέσβεις τοὺς ἀνανεωσομένους τὰς πρὸς τοὺς προγόνους αὐτοῦ συντεθειμένας συνθήκας. ὁ δ’ Ἱερώνυμος ἔτ’ ἐγγὺς ἐπόντων τῶν πρεσβευτῶν [εἴτ’ ἐν μισειόντων] τῶν Καρχηδονίων, ἔφη συλλυπεῖσθαι τοῖς Ῥωμαίοις ὅτι κακοὶ κακῶς ἐν ταῖς κατὰ τὴν Ἰταλίαν μάχαις ἀπολώλασιν ὑπὸ Καρχηδονίων. τῶν δὲ καταπλαγέντων τὴν ἀστοχίαν, ὅμως δὲ προσπυθομένων τίς λέγει ταῦτα περὶ αὐτῶν, ἔδειξε τοὺς Καρχηδονίους παρόντας, καὶ τούτους ἐκέλευσε διελέγχειν, εἴ τι τυγχάνουσι ψευδόμενοι. τῶν δὲ φησάντων οὐ πάτριον εἶναι σφίσι πιστεύειν τοῖς πολεμίοις, παρακαλούντων δὲ μηδὲν ποιεῖν παρὰ τὰς συνθήκας, ὅτι τοῦτο καὶ δίκαιόν ἐστι καὶ συμφέρον αὐτῷ μάλιστ’ ἐκείνῳ, περὶ μὲν τούτων. ἔφη βουλευσάμενος αὐτοῖς πάλιν διασαφήσειν, ἤρετο δὲ πῶς πρὸ τῆς τελευτῆς τοῦ πάππου πλεύσαντες ἕως τοῦ Παχύνου πεντήκοντα ναυσὶ πάλιν ἀνακάμψαιεν. συμβεβήκει δὲ Ῥωμαίους βραχεῖ χρόνῳ πρότερον ἀκούσαντας Ἱέρωνα μετηλλαχέναι, καὶ διαγωνιάσαντας μή τι νεωτερίσωσιν ἐν ταῖς Συρακούσαις καταφρονήσαντες τῆς τοῦ καταλελειμμένου παιδὸς ἡλικίας, πεποιῆσθαι τὸν ἐπίπλουν, πυθομένους δὲ τὸν Ἱέρωνα ζῆν αὖθις εἰς τὸ Λιλύβαιον ἀναδραμεῖν. διὸ καὶ τότε παρομολογούντων πεποιῆσθαι μὲν τὸν ἐπίπλουν, θέλοντας ἐφεδρεῦσαι τῇ νεότητι τῇ ’κείνου καὶ συνδιαφυλάξαι τὴν ἀρχὴν αὐτῷ, προσπεσόντος δὲ ζῆν τὸν πάππον, ἀποπλεῦσαι πάλιν, ῥηθέντων δὲ τούτων, πάλιν ὑπολαβὸν τὸ μειράκιον \"ἐάσατε τοίνυν\" ἔφη \"κἀμὲ νῦν, ἄνδρες Ῥωμαῖοι, διαφυλάξαι τὴν ἀρχήν, παλινδρομήσαντα πρὸς τὰς Καρχηδονίων ἐλπίδας\". οἱ δὲ Ῥωμαῖοι συνέντες τὴν ὁρμὴν αὐτοῦ, τότε μὲν κατασιωπήσαντες ἐπανῆλθον, καὶ διεσάφουν τὰ λεγόμενα τῷ πέμψαντι, τὸ δὲ λοιπὸν ἤδη προσεῖχον καὶ παρεφύλαττον ὡς πολέμιον.", "st": "7.3"}, {"sp": "N", "t": "Ἱερώνυμος δὲ προχειρισάμενος Ἀγάθαρχον καὶ Ὀνησιγένη καὶ Ἱπποσθένη πέμπει μετ’ Ἀννίβου πρὸς Καρχηδονίους, δοὺς ἐντολὰς ἐπὶ τοῖσδε ποιεῖσθαι τὰς συνθήκας, ἐφ’ ᾧ Καρχηδονίους βοηθεῖν καὶ πεζικαῖς καὶ ναυτικαῖς δυνάμεσι, καὶ συνεκβαλόντας Ῥωμαίους ἐκ Σικελίας οὕτως διελέσθαι τὰ κατὰ τὴν νῆσον ὥστε τῆς ἑκατέρων ἐπαρχίας ὅρον εἶναι τὸν Ἱμέραν ποταμόν, ὃς μάλιστά πως δίχα διαιρεῖ τὴν ὅλην Σικελίαν. οὗτοι μὲν οὖν ἀφικόμενοι πρὸς Καρχηδονίους διελέγοντο περὶ τούτων καὶ ταῦτ’ ἔπραττον, εἰς πᾶν ἑτοίμως συγκαταβαινόντων τῶν Καρχηδονίων· οἱ δὲ περὶ τὸν Ἱπποκράτην, λαμβάνοντες εἰς τὰς χεῖρας τὸ μειράκιον τὰς μὲν ἀρχὰς ἐψυχαγώγουν, ἐξηγούμενοι τὰς ἐν Ἰταλίᾳ πορείας Ἀννίβου καὶ παρατάξεις καὶ μάχας, μετὰ δὲ ταῦτα φάσκοντες μηδενὶ καθήκειν μᾶλλον τὴν ἁπάντων Σικελιωτῶν ἀρχὴν ὡς ἐκείνῳ, πρῶτον μὲν διὰ τὸ τῆς Πύρρου θυγατρὸς υἱὸν εἶναι Νηρηίδος, ὃν μόνον κατὰ προαίρεσιν καὶ κατ’ εὔνοιαν Σικελιῶται πάντες εὐδόκησαν σφῶν αὐτῶν ἡγεμόν’ εἶναι καὶ βασιλέα, δεύτερον δὲ κατὰ τὴν Ἱέρωνος τοῦ πάππου δυναστείαν. καὶ τέλος ἐπὶ τοσοῦτον ἐξωμίλησαν τὸ μειράκιον ὥστε καθόλου μηδενὶ προσέχειν τῶν ἄλλων διὰ τὸ καὶ φύσει μὲν ἀκατάστατον ὑπάρχειν, ἔτι δὲ μᾶλλον ὑπ’ ἐκείνων τότε μετεωρισθέν· ἀκμὴν τῶν περὶ Ἀγάθαρχον ἐν τῇ Καρχηδόνι τὰ προειρημένα διαπραττομένων, ἐπιπέμπει πρεσβευτάς, τὴν μὲν τῆς Σικελίας ἀρχὴν φάσκων αὑτῷ καθήκειν ἅπασαν, ἀξιῶν δὲ Καρχηδονίους μὲν βοηθεῖν περὶ Σικελίας, αὐτὸς δὲ Καρχηδονίοις ὑπισχνούμενος ἐπαρκεῖν εἰς τὰς κατὰ τὴν Ἰταλίαν πράξεις. τὴν μὲν οὖν ὅλην ἀκαταστασίαν καὶ μανίαν καλῶς συνθεώμενοι Καρχηδόνιοι τοῦ μειρακίου, νομίζοντες δὲ κατὰ πολλοὺς τρόπους συμφέρειν σφίσι τὸ μὴ προέσθαι τὰ κατὰ τὴν Σικελίαν, ἐκείνῳ μὲν ἅπαντα συγκατένευον, αὐτοὶ δὲ καὶ πρότερον ἤδη παρασκευασάμενοι ναῦς καὶ στρατιώτας, ἐγίνοντο πρὸς τὸ διαβιβάζειν τὰς δυνάμεις εἰς τὴν Σικελίαν.", "st": "7.4"}, {"sp": "N", "t": "οἱ δὲ Ῥωμαῖοι ταῦτα πυνθανόμενοι πάλιν ἔπεμψαν πρὸς αὐτὸν πρέσβεις, διαμαρτυρόμενοι μὴ παραβαίνειν τὰς πρὸς τοὺς προγόνους αὐτοῦ τεθειμένας συνθήκας. ὑπὲρ ὧν Ἱερώνυμος ἁθροίσας τὸ συνέδριον ἀνέδωκε διαβούλιον τί δεῖ ποιεῖν. οἱ μὲν οὖν ἐγχώριοι τὴν ἡσυχίαν ἦγον, δεδιότες τὴν τοῦ προεστῶτος ἀκρισίαν· Ἀριστόμαχος δ’ ὁ Κορίνθιος καὶ Δάμιππος ὁ Λακεδαιμόνιος καὶ Αὐτόνους ὁ Θετταλὸς ἠξίουν ἐμμένειν ταῖς πρὸς Ῥωμαίους συνθήκαις. Ἀδρανόδωρος δὲ μόνος οὐκ ἔφη δεῖν παριέναι τὸν καιρόν· εἶναι δὲ τὸν ἐνεστῶτα μόνον ἐν ᾧ κατακτήσασθαι δυνατόν ἐστι τὴν τῆς Σικελίας ἀρχήν. τοῦ δὲ ταῦτ’ εἰπόντος, ἤρετο τοὺς περὶ τὸν Ἱπποκράτην ποίας μετέχουσι γνώμης. τῶν δὲ φησάντων τῆς Ἀδρανοδώρου, πέρας εἶχε τὸ διαβούλιον. καὶ τὰ μὲν τοῦ πολέμου τοῦ πρὸς Ῥωμαίους ἐκεκύρωτο τὸν τρόπον τοῦτον· βουλόμενος δὲ μὴ σκαιῶς δοκεῖν ἀποκρίνεσθαι τοῖς πρεσβευταῖς, εἰς τηλικαύτην ἀστοχίαν ἐνέπεσε δι’ ἧς τοῖς Ῥωμαίοις οὐ μόνον δυσαρεστήσειν, ἀλλὰ καὶ προσκόπτειν ἔμελλε προφανῶς. ἔφη γὰρ ἐμμενεῖν ἐν ταῖς συνθήκαις, ἐὰν αὐτῷ πρῶτον μὲν τὸ χρυσίον ἀποδῶσι πᾶν, ὃ παρ’ Ἱέρωνος ἔλαβον τοῦ πάππου, δεύτερον δὲ τὸν σῖτον ἐκ παντὸς ἀποκαταστήσωσι τοῦ χρόνου καὶ τὰς ἄλλας δωρεάς, ἃς εἶχον παρ’ ἐκείνου, τὸ δὲ τρίτον ὁμολογήσωσι τὴν ἐντὸς Ἱμέρα ποταμοῦ χώραν καὶ πόλεις εἶναι Συρακοσίων. οἱ μὲν οὖν πρεσβευταὶ καὶ τὸ συνέδριον ἐπὶ τούτοις ἐχωρίσθησαν· οἱ δὲ περὶ τὸν Ἱερώνυμον ἀπὸ τούτων τῶν καιρῶν ἐνήργουν τὰ τοῦ πολέμου, καὶ τάς τε δυνάμεις ἥθροιζον καὶ καθώπλιζον τάς τε λοιπὰς χορηγίας ἡτοίμαζον.", "st": "7.5"}, {"sp": "N", "t": "ἡ γὰρ τῶν Λεοντίνων πόλις τῷ μὲν ὅλῳ κλίματι τέτραπται πρὸς τὰς ἄρκτους, ἔστι δὲ διὰ μέσης αὐτῆς αὐλὼν ἐπίπεδος, ἐν ᾧ συμβαίνει τάς τε τῶν ἀρχείων καὶ δικαστηρίων κατασκευὰς καὶ καθόλου τὴν ἀγορὰν ὑπάρχειν. τοῦ δ’ αὐλῶνος παρ’ ἑκατέραν τὴν πλευρὰν παρήκει λόφος, ἔχων ἀπορρῶγα συνεχῆ· τὰ δ’ ἐπίπεδα τῶν λόφων τούτων ὑπὲρ τὰς ὀφρῦς οἰκιῶν ἐστι πλήρη καὶ ναῶν. δύο δ’ ἔχει πυλῶνας ἡ πόλις, ὧν ὁ μὲν ἐπὶ τοῦ πρὸς μεσημβρίαν πέρατός ἐστιν οὗ προεῖπον αὐλῶνος, φέρων ἐπὶ Συρακούσας, ὁ δ’ ἕτερος ἐπὶ τοῦ πρὸς ἄρκτους, ἄγων ἐπὶ τὰ Λεοντῖνα καλούμενα πεδία καὶ τὴν γεωργήσιμον χώραν. ὑπὸ δὲ τὴν μίαν ἀπορρῶγα, τὴν πρὸς τὰς δύσεις, παραρρεῖ ποταμός, ὃν καλοῦσι Λίσσον. τούτῳ δὲ κεῖνται παράλληλοι καὶ πλείους ὑπ’ αὐτὸν τὸν κρημνὸν οἰκίαι συνεχεῖς, ὧν μεταξὺ καὶ τοῦ ποταμοῦ συμβαίνει τὴν προειρημένην ὁδὸν ὑπάρχειν.", "st": "7.6"}, {"sp": "N", "t": "ὅτι τινὲς τῶν λογογράφων τῶν ὑπὲρ τῆς καταστροφῆς τοῦ Ἱερωνύμου γεγραφότων πολύν τινα πεποίηνται λόγον καὶ πολλήν τινα διατέθεινται τερατείαν, ἐξηγούμενοι μὲν τὰ πρὸ τῆς ἀρχῆς αὐτοῖς γενόμενα σημεῖα καὶ τὰς ἀτυχίας τὰς Συρακοσίων, τραγῳδοῦντες δὲ τὴν ὠμότητα τῶν τρόπων καὶ τὴν ἀσέβειαν τῶν πράξεων, ἐπὶ δὲ πᾶσι τὸ παράλογον καὶ τὸ δεινὸν τῶν περὶ τὴν καταστροφὴν αὐτοῦ συμβάντων, ὥστε μήτε Φάλαριν μήτ’ Ἀπολλόδωρον μήτ’ ἄλλον μηδένα γεγονέναι τύραννον ἐκείνου πικρότερον. καίτοι παῖς παραλαβὼν τὴν ἀρχήν, εἶτα μῆνας οὐ πλείους τριῶν καὶ δέκα βιώσας μετήλλαξε τὸν βίον. κατὰ δὲ τὸν χρόνον τοῦτον ἕνα μέν τινα καὶ δεύτερον ἐστρεβλῶσθαι καί τινας τῶν φίλων καὶ τῶν ἄλλων Συρακοσίων ἀπεκτάνθαι δυνατόν, ὑπερβολὴν δὲ γεγονέναι παρανομίας καὶ παρηλλαγμένην ἀσέβειαν οὐκ εἰκός. καὶ τῷ μὲν τρόπῳ διαφερόντως εἰκαῖον αὐτὸν γεγονέναι καὶ παράνομον φατέον, οὐ μὴν εἴς γε σύγκρισιν ἀκτέον οὐδενὶ τῶν προειρημένων τυράννων. ἀλλά μοι δοκοῦσιν οἱ τὰς ἐπὶ μέρους γράφοντες πράξεις, ἐπειδὰν ὑποθέσεις εὐπεριλήπτους ὑποστήσωνται καὶ στενάς, πτωχεύοντες πραγμάτων ἀναγκάζεσθαι τὰ μικρὰ μεγάλα ποιεῖν καὶ περὶ τῶν μηδὲ μνήμης ἀξίων πολλούς τινας διατίθεσθαι λόγους. ἔνιοι δὲ καὶ δι’ ἀκρισίαν εἰς τὸ παραπλήσιον τούτοις ἐμπίπτουσιν. ὅσῳ γὰρ ἄν τις εὐλογώτερον καὶ περὶ ταῦτα τὸν ἀναπληροῦντα τὰς βύβλους καὶ τὸν ἐπιμετροῦντα λόγον τῆς διηγήσεως εἰς Ἱέρωνα καὶ Γέλωνα διάθοιτο, παρεὶς Ἱερώνυμον. καὶ γὰρ τοῖς φιληκόοις ἡδίων οὗτος καὶ τοῖς φιλομαθοῦσι τῷ παντὶ χρησιμώτερος.", "st": "7.7"}, {"sp": "N", "t": "Ἱέρων μὲν γὰρ πρῶτον μὲν δι’ αὑτοῦ κατεκτήσατο τὴν Συρακοσίων καὶ τῶν συμμάχων ἀρχήν, οὐ πλοῦτον, οὐ δόξαν, οὐχ ἕτερον οὐδὲν ἐκ τῆς τύχης ἕτοιμον παραλαβών. καὶ μὴν οὐκ ἀποκτείνας, οὐ φυγαδεύσας, οὐ λυπήσας οὐδένα τῶν πολιτῶν, δι’ αὑτοῦ βασιλεὺς κατέστη τῶν Συρακοσίων, ὃ πάντων ἐστὶ παραδοξότατον, ἔτι δὲ τὸ μὴ μόνον κτήσασθαι τὴν ἀρχὴν οὕτως, ἀλλὰ καὶ διαφυλάξαι τὸν αὐτὸν τρόπον. ἔτη γὰρ πεντήκοντα καὶ τέτταρα βασιλεύσας διετήρησε μὲν τῇ πατρίδι τὴν εἰρήνην, διεφύλαξε δ’ αὑτῷ τὴν ἀρχὴν ἀνεπιβούλευτον, διέφυγε δὲ τὸν ταῖς ὑπεροχαῖς παρεπόμενον φθόνον· ὅς γε πολλάκις ἐπιβαλόμενος ἀποθέσθαι τὴν δυναστείαν ἐκωλύθη κατὰ κοινὸν ὑπὸ τῶν πολιτῶν. εὐεργετικώτατος δὲ καὶ φιλοδοξότατος γενόμενος εἰς τοὺς Ἕλληνας μεγάλην μὲν αὑτῷ δόξαν, οὐ μικρὰν δὲ Συρακοσίοις εὔνοιαν παρὰ πᾶσιν ἀπέλιπε. καὶ μὴν ἐν περιουσίᾳ καὶ τρυφῇ καὶ δαψιλείᾳ πλείστῃ διαγενόμενος ἔτη μὲν ἐβίωσε πλείω τῶν ἐνενήκοντα, διεφύλαξε δὲ τὰς αἰσθήσεις ἁπάσας, διετήρησε δὲ πάντα καὶ τὰ μέρη τοῦ σώματος ἀβλαβῆ. τοῦτο δέ μοι δοκεῖ σημεῖον οὐ μικρόν, ἀλλὰ παμμέγεθες εἶναι βίου σώφρονος. ὅτι Γέλων πλείω τῶν πεντήκοντα βιώσας ἐτῶν σκοπὸν προέθηκε κάλλιστον ἐν τῷ ζῆν, τὸ πειθαρχεῖν τῷ γεννήσαντι, καὶ μήτε πλοῦτον μήτε βασιλείας μέγεθος μήτ’ ἄλλο περὶ πλείονος ποιήσασθαι μηδὲν τῆς πρὸς τοὺς γονεῖς εὐνοίας καὶ πίστεως.", "st": "7.8"}, {"sp": "N", "t": "ὅρκος, ὃν ἔθετο Ἀννίβας ὁ στρατηγός, Μάγωνος, Μύρκανος, Βαρμόκαρος, καὶ πάντες γερουσιασταὶ Καρχηδονίων οἱ μετ’ αὐτοῦ καὶ πάντες Καρχηδόνιοι στρατευόμενοι μετ’ αὐτοῦ πρὸς Ξενοφάνη Κλεομάχου Ἀθηναῖον πρεσβευτήν, ὃν ἀπέστειλε πρὸς ἡμᾶς Φίλιππος ὁ βασιλεὺς Δημητρίου ὑπὲρ αὑτοῦ καὶ Μακεδόνων καὶ τῶν συμμάχων, ἐναντίον Διὸς καὶ Ἥρας καὶ Ἀπόλλωνος, ἐναντίον δαίμονος Καρχηδονίων καὶ Ἡρακλέους καὶ Ἰολάου, ἐναντίον Ἄρεως, Τρίτωνος, Ποσειδῶνος, ἐναντίον θεῶν τῶν συστρατευομένων καὶ Ἡλίου καὶ Σελήνης καὶ Γῆς, ἐναντίον ποταμῶν καὶ λιμένων καὶ ὑδάτων, ἐναντίον πάντων θεῶν ὅσοι κατέχουσι Καρχηδόνα, ἐναντίον θεῶν πάντων ὅσοι Μακεδονίαν καὶ τὴν ἄλλην Ἑλλάδα κατέχουσιν, ἐναντίον θεῶν πάντων τῶν κατὰ στρατείαν, ὅσοι τινὲς ἐφεστήκασιν ἐπὶ τοῦδε τοῦ ὅρκου. Ἀννίβας ὁ στρατηγὸς εἶπε καὶ πάντες Καρχηδονίων γερουσιασταὶ οἱ μετ’ αὐτοῦ καὶ πάντες Καρχηδόνιοι οἱ στρατευόμενοι μετ’ αὐτοῦ, ὃ ἂν δοκῇ ὑμῖν καὶ ἡμῖν, τὸν ὅρκον τοῦτον θέσθαι περὶ φιλίας καὶ εὐνοίας καλῆς, φίλους καὶ οἰκείους καὶ ἀδελφούς, ἐφ’ ᾧτ’ εἶναι σῳζομένους ὑπὸ βασιλέως Φιλίππου καὶ Μακεδόνων καὶ ὑπὸ τῶν ἄλλων Ἑλλήνων, ὅσοι εἰσὶν αὐτῶν σύμμαχοι, κυρίους Καρχηδονίους καὶ Ἀννίβαν τὸν στρατηγὸν καὶ τοὺς μετ’ αὐτοῦ καὶ τοὺς Καρχηδονίων ὑπάρχους, ὅσοι τοῖς αὐτοῖς νόμοις χρῶνται, καὶ Ἰτυκαίους, καὶ ὅσαι πόλεις καὶ ἔθνη Καρχηδονίων ὑπήκοα, καὶ τοὺς στρατιώτας καὶ τοὺς συμμάχους, καὶ πάσας πόλεις καὶ ἔθνη, πρὸς ἅ ἐστιν ἡμῖν ἥ τε φιλία τῶν ἐν Ἰταλίᾳ καὶ Κελτίᾳ καὶ ἐν τῇ Λιγυστίνῃ, καὶ πρὸς οὕστινας ἡμῖν ἂν γένηται φιλία καὶ συμμαχία ἐν ταύτῃ τῇ χώρᾳ. ἔσται δὲ καὶ Φίλιππος ὁ βασιλεὺς καὶ Μακεδόνες καὶ τῶν ἄλλων Ἑλλήνων οἱ σύμμαχοι, σῳζόμενοι καὶ φυλαττόμενοι ὑπὸ Καρχηδονίων τῶν συστρατευομένων καὶ ὑπὸ Ἰτυκαίων καὶ ὑπὸ πασῶν πόλεων καὶ ἐθνῶν ὅσα ἐστὶ Καρχηδονίοις ὑπήκοα, καὶ συμμάχων καὶ στρατιωτῶν, καὶ ὑπὸ πάντων ἐθνῶν καὶ πόλεων ὅσα ἐστὶν ἐν Ἰταλίᾳ καὶ Κελτίᾳ καὶ Λιγυστίνῃ, καὶ ὑπὸ τῶν ἄλλων, ὅσοι ἂν γένωνται σύμμαχοι ἐν τοῖς κατ’ Ἰταλίαν τόποις τούτοις. οὐκ ἐπιβουλεύσομεν ἀλλήλοις οὐδὲ λόχῳ χρησόμεθα ἐπ’ ἀλλήλοις, μετὰ πάσης δὲ προθυμίας καὶ εὐνοίας ἄνευ δόλου καὶ ἐπιβουλῆς ἐσόμεθα πολέμιοι τοῖς πρὸς Καρχηδονίους πολεμοῦσι χωρὶς βασιλέων καὶ πόλεων καὶ λιμένων, πρὸς οὓς ἡμῖν εἰσιν ὅρκοι καὶ φιλίαι. ἐσόμεθα δὲ καὶ ἡμεῖς πολέμιοι τοῖς πολεμοῦσι πρὸς βασιλέα Φίλιππον χωρὶς βασιλέων καὶ πόλεων καὶ ἐθνῶν, πρὸς οὓς ἡμῖν εἰσιν ὅρκοι καὶ φιλίαι. ἔσεσθε δὲ καὶ ἡμῖν σύμμαχοι πρὸς τὸν πόλεμον, ὅς ἐστιν ἡμῖν πρὸς Ῥωμαίους, ἕως ἂν ἡμῖν καὶ ὑμῖν οἱ θεοὶ διδῶσι τὴν εὐημερίαν. βοηθήσετε δὲ ἡμῖν, ὡς ἂν χρεία ᾖ καὶ ὡς ἂν συμφωνήσωμεν. ποιησάντων δὲ τῶν θεῶν εὐημερίαν ἡμῖν κατὰ τὸν πόλεμον τὴν πρὸς Ῥωμαίους καὶ τοὺς συμμάχους αὐτῶν, ἂν ἀξιῶσι Ῥωμαῖοι συντίθεσθαι περὶ φιλίας, συνθησόμεθα, ὥστ’ εἶναι πρὸς ὑμᾶς τὴν αὐτὴν φιλίαν, ἐφ’ ᾧτε μὴ ἐξεῖναι αὐτοῖς ἄρασθαι πρὸς ὑμᾶς μηδέποτε πόλεμον, μηδ’ εἶναι Ῥωμαίους κυρίους Κερκυραίων μηδ’ Ἀπολλωνιατῶν καὶ Ἐπιδαμνίων μηδὲ Φάρου μηδὲ Διμάλης καὶ Παρθίνων μηδ’ Ἀτιντανίας. ἀποδώσουσι δὲ καὶ Δημητρίῳ τῷ Φαρίῳ τοὺς οἰκείους πάντας, οἵ εἰσιν ἐν τῷ κοινῷ τῶν Ῥωμαίων. ἐὰν δὲ αἴρωνται Ῥωμαῖοι πρὸς ὑμᾶς πόλεμον ἢ πρὸς ἡμᾶς, βοηθήσομεν ἀλλήλοις εἰς τὸν πόλεμον, καθὼς ἂν ἑκατέροις ᾖ χρεία. ὁμοίως δὲ καὶ ἐάν τινες ἄλλοι χωρὶς βασιλέων καὶ πόλεων καὶ ἐθνῶν, πρὸς ἃ ἡμῖν εἰσιν ὅρκοι καὶ φιλίαι. ἐὰν δὲ δοκῇ ἡμῖν ἀφελεῖν ἢ προσθεῖναι πρὸς τόνδε τὸν ὅρκον, ἀφελοῦμεν ἢ προσθήσομεν ὡς ἂν ἡμῖν δοκῇ ἀμφοτέροις.", "st": "7.9"}, {"sp": "N", "t": "οὔσης δημοκρατίας παρὰ τοῖς Μεσσηνίοις, καὶ τῶν μὲν ἀξιολόγων ἀνδρῶν πεφυγαδευμένων, τῶν δὲ κατακεκληρουχημένων τὰς τούτων οὐσίας ἐπικρατούντων τῆς πολιτείας, δυσχερῶς ὑπέφερον τὴν τούτων ἰσηγορίαν οἱ μένοντες τῶν ἀρχαίων πολιτῶν. ὅτι Γόργος ὁ Μεσσήνιος οὐδενὸς ἦν δεύτερος Μεσσηνίων πλούτῳ καὶ γένει, διὰ δὲ τὴν ἄθλησιν κατὰ τὴν ἀκμὴν πάντων ἐνδοξότατος ἐγεγόνει τῶν περὶ τοὺς γυμνικοὺς ἀγῶνας φιλοστεφανούντων. καὶ γὰρ κατὰ τὴν ἐπιφάνειαν καὶ κατὰ τὴν τοῦ λοιποῦ βίου προστασίαν, ἔτι δὲ κατὰ τὸ πλῆθος τῶν στεφάνων, οὐδενὸς ἐλείπετο τῶν καθ’ αὑτόν. καὶ μὴν ὅτε καταλύσας τὴν ἄθλησιν ἐπὶ τὸ πολιτεύεσθαι καὶ τὸ πράττειν τὰ τῆς πατρίδος ὥρμησε, καὶ περὶ τοῦτο τὸ μέρος οὐκ ἐλάττω δόξαν ἐξεφέρετο τῆς πρότερον ὑπαρχούσης αὐτῷ, πλεῖστον μὲν ἀπέχειν δοκῶν τῆς τοῖς ἀθληταῖς παρεπομένης ἀναγωγίας, πρακτικώτατος δὲ καὶ νουνεχέστατος εἶναι νομιζόμενος περὶ τὴν πολιτείαν.", "st": "7.10"}, {"sp": "N", "t": "ὅτι Φιλίππου τοῦ βασιλέως Μακεδόνων τὴν τῶν Μεσσηνίων ἀκρόπολιν κατασχεῖν βουλομένου, καὶ φήσαντος βούλεσθαι πρὸς τοὺς προεστῶτας τῆς πόλεως θεάσασθαι τὴν ἀκρόπολιν καὶ θῦσαι τῷ Διί, ἀναβάντος μετὰ τῆς θεραπείας καὶ θύοντος, μετὰ ταῦτα κατὰ τὸν ἐθισμὸν ἐκ τῶν τυθέντων ἱερείων προσενεχθέντων αὐτῷ τῶν σπλάγχνων, δεξάμενος εἰς τὰς χεῖρας καὶ βραχὺ διακλίνας, ἤρετο προτείνων τοῖς περὶ τὸν Ἄρατον \"τί δοκεῖ τὰ ἱερὰ σημαίνειν, πότερον ἐκχωρεῖν τῆς ἄκρας ἢ κρατεῖν αὐτῆς. \" ὁ μὲν οὖν Δημήτριος αὐτόθεν ἐκ τοῦ προβεβηκότος \"εἰ μὲν μάντεως φρένας ἔχεις\" ἔφη \"ἐκχωρεῖν τὴν ταχίστην· εἰ δὲ βασιλέως πραγματικοῦ, τηρεῖν αὐτήν, ἵνα μὴ νῦν ἀφεὶς ζητῇς ἕτερον ἐπιτηδειότερον καιρόν· οὕτως γὰρ ἑκατέρων τῶν κεράτων κρατῶν μόνως ἂν ὑποχείριον ἔχοις τὸν βοῦν\", αἰνιττόμενος τὰ μὲν κέρατα τὸν Ἰθωμάταν καὶ τὸν Ἀκροκόρινθον, τὴν δὲ Πελοπόννησον τὸν βοῦν. ὁ δὲ Φίλιππος ἐπιστρέψας πρὸς τὸν Ἄρατον \"σὺ δὲ ταὐτὰ συμβουλεύεις;\" ἔφη. τοῦ δ’ ἐπισχόντος, αὐτὸ λέγειν ἠξίου τὸ φαινόμενον. ὁ δὲ διαπορήσας \"εἰ μὲν χωρίς\" ἔφη \"τοῦ παρασπονδῆσαι Μεσσηνίους δύνῃ κρατεῖν τοῦ τόπου τούτου, συμβουλεύω κρατεῖν· εἰ δὲ τοῦτον καταλαβὼν φρουρᾷ, πάσας ἀπολλύναι μέλλεις τὰς ἀκροπόλεις καὶ τὴν φρουράν, ᾗ παρέλαβες παρ’ Ἀντιγόνου φρουρουμένους τοὺς συμμάχους\", λέγων τὴν πίστιν, \"σκόπει μὴ καὶ νῦν κρεῖττον ᾖ τοὺς ἄνδρας ἐξαγαγόντα τὴν πίστιν αὐτοῦ καταλιπεῖν, καὶ ταύτῃ φρουρεῖν τοὺς Μεσσηνίους, ὁμοίως δὲ καὶ τοὺς λοιποὺς συμμάχους.\" ὁ Φίλιππος κατὰ μὲν τὴν ἰδίαν ὁρμὴν ἕτοιμος ἦν παρασπονδεῖν, ὡς ἐκ τῶν ὕστερον πραχθέντων ἐγένετο καταφανής, ἐπιτετιμημένος δὲ μικρῷ μὲν πρότερον ὑπὸ τοῦ νεωτέρου πικρῶς ἐπὶ τῇ τῶν ἀνδρῶν ἀπωλείᾳ, τότε δὲ μετὰ παρρησίας ἅμα καὶ μετ’ ἀξιώσεως λέγοντος τοῦ πρεσβυτέρου καὶ δεομένου μὴ παρακοῦσαι τῶν λεγομένων, ἐνετράπη. καὶ λαβόμενος αὐτοῦ τῆς δεξιᾶς \"ἄγωμεν τοίνυν\" ἔφη \"πάλιν τὴν αὐτὴν ὁδόν.\"", "st": "7.11"}, {"sp": "N", "t": "ἐγὼ δὲ κατὰ τὸ παρὸν ἐπιστήσας τὴν διήγησιν βραχέα βούλομαι διαλεχθῆναι περὶ Φιλίππου, διὰ τὸ ταύτην τὴν ἀρχὴν γενέσθαι τῆς εἰς τοὔμπαλιν μεταβολῆς αὐτοῦ καὶ τῆς ἐπὶ χεῖρον ὁρμῆς καὶ μεταθέσεως. δοκεῖ γάρ μοι τοῖς καὶ κατὰ βραχὺ βουλομένοις τῶν πραγματικῶν ἀνδρῶν περιποιεῖσθαι τὴν ἐκ τῆς ἱστορίας διόρθωσιν ἐναργέστατον εἶναι τοῦτο παράδειγμα. καὶ γὰρ διὰ τὸ τῆς ἀρχῆς ἐπιφανὲς καὶ διὰ τὸ τῆς φύσεως λαμπρὸν ἐκφανεστάτας συμβαίνει καὶ γνωριμωτάτας γεγονέναι πᾶσι τοῖς Ἕλλησι τὰς εἰς ἑκάτερον τὸ μέρος ὁρμὰς τοῦ βασιλέως τούτου, παραπλησίως δὲ καὶ τὰ συνεξακολουθήσαντα ταῖς ὁρμαῖς ἑκατέραις ἐκ παραθέσεως. ὅτι μὲν οὖν αὐτῷ μετὰ τὸ παραλαβεῖν τὴν βασιλείαν τά τε κατὰ Θετταλίαν καὶ Μακεδονίαν καὶ συλλήβδην τὰ κατὰ τὴν ἰδίαν ἀρχὴν οὕτως ὑπετέτακτο καὶ συνέκλινε ταῖς εὐνοίαις ὡς οὐδενὶ τῶν πρότερον βασιλέων, καίτοι νέῳ ὄντι παραλαβόντι τὴν Μακεδόνων δυναστείαν, εὐχερὲς καταμαθεῖν ἐκ τούτων. συνεχέστατα γὰρ αὐτοῦ περισπασθέντος ἐκ Μακεδονίας διὰ τὸν πρὸς Αἰτωλοὺς καὶ Λακεδαιμονίους πόλεμον, οὐχ οἷον ἐστασίασέ τι τῶν προειρημένων ἐθνῶν, ἀλλ’ οὐδὲ τῶν περιοικούντων ἐτόλμησε βαρβάρων οὐδεὶς ἅψασθαι τῆς Μακεδονίας. καὶ μὴν περὶ τῆς Ἀλεξάνδρου καὶ Χρυσογόνου καὶ τῶν ἄλλων φίλων εὐνοίας καὶ προθυμίας εἰς αὐτὸν οὐδ’ ἂν εἰπεῖν τις δύναιτ’ ἀξίως. τὴν δὲ Πελοποννησίων καὶ Βοιωτῶν, ἅμα δὲ τούτοις Ἠπειρωτῶν, Ἀκαρνάνων, … ὅσων ἑκάστοις ἀγαθῶν ἐν βραχεῖ χρόνῳ παραίτιος ἐγένετο. καθόλου γε μήν, εἰ δεῖ μικρὸν ὑπερβολικώτερον εἰπεῖν, οἰκειότατ’ ἂν οἶμαι περὶ Φιλίππου τοῦτο ῥηθῆναι, διότι κοινός τις οἷον ἐρώμενος ἐγένετο τῶν Ἑλλήνων διὰ τὸ τῆς αἱρέσεως εὐεργετικόν. ἐκφανέστατον δὲ καὶ μέγιστον δεῖγμα περὶ τοῦ τί δύναται προαίρεσις καλοκἀγαθικὴ καὶ πίστις, τὸ πάντας Κρηταιεῖς συμφρονήσαντας καὶ τῆς αὐτῆς μετασχόντας συμμαχίας ἕνα προστάτην ἑλέσθαι τῆς νήσου Φίλιππον, καὶ ταῦτα συντελεσθῆναι χωρὶς ὅπλων καὶ κινδύνων, ὃ πρότερον οὐ ῥᾳδίως ἂν εὕροι τις γεγονός. ἀπὸ τοίνυν τῶν κατὰ Μεσσηνίους ἐπιτελεσθέντων ἅπαντα τὴν ἐναντίαν ἐλάμβανε διάθεσιν αὐτῷ· καὶ τοῦτο συνέβαινε κατὰ λόγον· τραπεὶς γὰρ ἐπὶ τὴν ἀντικειμένην προαίρεσιν τῇ πρόσθεν, καὶ ταύτῃ προστιθεὶς ἀεὶ τἀκόλουθον, ἔμελλε καὶ τὰς τῶν ἄλλων διαλήψεις περὶ αὑτοῦ τρέψειν εἰς τἀναντία καὶ ταῖς τῶν πραγμάτων συντελείαις ἐγκυρήσειν ἐναντίαις ἢ πρότερον. ὃ καὶ συνέβη γενέσθαι. δῆλον δὲ τοῦτ’ ἔσται τοῖς προσέχουσιν ἐπιμελῶς διὰ τῶν ἑξῆς ῥηθησομένων πράξεων.", "st": "7.12"}, {"sp": "N", "t": "ὅτι ὁ Ἄρατος, θεωρῶν τὸν Φίλιππον ὁμολογουμένως τόν τε πρὸς Ῥωμαίους ἀναλαμβάνοντα πόλεμον καὶ κατὰ τὴν πρὸς τοὺς συμμάχους αἵρεσιν ὁλοσχερῶς ἠλλοιωμένον, πολλὰς εἰσενεγκάμενος ἀπορίας καὶ σκήψεις μόλις ἀπετρέψατο τὸν Φίλιππον. ἡμεῖς δέ, τοῦ κατὰ τὴν πέμπτην βύβλον ἡμῖν ἐν ἐπαγγελίᾳ καὶ φάσει μόνον εἰρημένου νῦν δι’ αὐτῶν τῶν πραγμάτων τὴν πίστιν εἰληφότος, βουλόμεθα προσαναμνῆσαι τοὺς συνεφιστάνοντας τῇ πραγματείᾳ, πρὸς τὸ μηδεμίαν τῶν ἀποφάσεων ἀναπόδεικτον μηδ’ ἀμφισβητουμένην καταλιπεῖν. καθ’ ὃν γὰρ καιρὸν ἐξηγούμενοι τὸν Αἰτωλικὸν πόλεμον ἐπὶ τοῦτο τὸ μέρος τῆς διηγήσεως ἐπέστημεν, ἐν ᾧ Φίλιππον ἔφαμεν τὰς ἐν Θέρμῳ στοὰς καὶ τὰ λοιπὰ τῶν ἀναθημάτων θυμικώτερον καταφθεῖραι, καὶ δεῖν τούτων τὴν αἰτίαν οὐχ οὕτως ἐπὶ τὸν βασιλέα διὰ τὴν ἡλικίαν ὡς ἐπὶ τοὺς συνόντας αὐτῷ φίλους ἀναφέρειν, τότε περὶ μὲν Ἀράτου τὸν βίον ἐφήσαμεν ἀπολογεῖσθαι τὸ μηδὲν ἂν ποιῆσαι μοχθηρόν, Δημητρίου δὲ τοῦ Φαρίου τὴν τοιαύτην εἶναι προαίρεσιν. δῆλον δὲ τοῦτο ποιήσειν ἐπηγγειλάμεθα διὰ τῶν ἑξῆς ῥηθησομένων, εἰς τοῦτον ὑπερθέμενοι τὸν καιρὸν τὴν πίστιν τῆς προρρηθείσης ἀποφάσεως, ἐν ᾧ παρὰ μίαν ἡμέραν Δημητρίου μὲν παρόντος, ὡς ἀρτίως ὑπὲρ τῶν κατὰ Μεσσηνίους ὑπεδείξαμεν, Ἀράτου δὲ καθυστερήσαντος, ἤρξατο Φίλιππος ἅπτεσθαι τῶν μεγίστων ἀσεβημάτων. καὶ καθάπερ ἂν ἐγγευσάμενος αἵματος ἀνθρωπείου καὶ τοῦ φονεύειν καὶ παρασπονδεῖν τοὺς συμμάχους, οὐ λύκος ἐξ ἀνθρώπου κατὰ τὸν Ἀρκαδικὸν μῦθον, ὥς φησιν ὁ Πλάτων, ἀλλὰ τύραννος ἐκ βασιλέως ἀπέβη πικρός. τούτου δ’ ἐναργέστερον ἔτι δεῖγμα τῆς ἑκατέρου γνώμης τὸ περὶ τῆς ἄκρας συμβούλευμα πρὸς τὸ μηδὲ περὶ τῶν κατ’ Αἰτωλοὺς διαπορεῖν.", "st": "7.13"}, {"sp": "N", "t": "ὧν ὁμολογουμένων εὐμαρὲς ἤδη συλλογίσασθαι τὴν διαφορὰν τῆς ἑκατέρου προαιρέσεως. καθάπερ γὰρ νῦν Φίλιππος πεισθεὶς Ἀράτῳ διεφύλαξε τὴν πρὸς Μεσσηνίους πίστιν ἐν τοῖς κατὰ τὴν ἄκραν, καὶ μεγάλῳ, τὸ δὴ λεγόμενον, ἕλκει τῷ προγεγονότι περὶ τὰς σφαγὰς μικρὸν ἴαμα προσέθηκεν, οὕτως ἐν τοῖς κατ’ Αἰτωλοὺς Δημητρίῳ κατακολουθήσας ἠσέβει μὲν εἰς τοὺς θεούς, τὰ καθιερωμένα τῶν ἀναθημάτων διαφθείρων, ἡμάρτανε δὲ περὶ τοὺς ἀνθρώπους, ὑπερβαίνων τοὺς τοῦ πολέμου νόμους, ἠστόχει δὲ τῆς σφετέρας προαιρέσεως, ἀπαραίτητον καὶ πικρὸν ἑαυτὸν ἀποδεικνύων ἐχθρὸν τοῖς διαφερομένοις. ὁ δ’ αὐτὸς λόγος καὶ περὶ τῶν κατὰ Κρήτην· καὶ γὰρ ἐπ’ ἐκείνων Ἀράτῳ μὲν καθηγεμόνι χρησάμενος περὶ τῶν ὅλων, οὐχ οἷον ἀδικήσας, ἀλλ’ οὐδὲ λυπήσας οὐδένα τῶν κατὰ τὴν νῆσον, ἅπαντας μὲν εἶχε τοὺς Κρηταιεῖς ὑποχειρίους, ἅπαντας δὲ τοὺς Ἕλληνας εἰς τὴν πρὸς αὑτὸν εὔνοιαν ἐπήγετο διὰ τὴν σεμνότητα τῆς προαιρέσεως. οὕτω πάλιν ἐπακολουθήσας Δημητρίῳ καὶ παραίτιος γενόμενος Μεσσηνίοις τῶν ἄρτι ῥηθέντων ἀτυχημάτων, ἅμα τὴν παρὰ τοῖς συμμάχοις εὔνοιαν καὶ τὴν παρὰ τοῖς ἄλλοις Ἕλλησιν ἀπέβαλε πίστιν. τηλικαύτην τοῖς νέοις βασιλεῦσι ῥοπὴν ἔχει καὶ πρὸς ἀτυχίαν καὶ πρὸς ἐπανόρθωσιν τῆς ἀρχῆς ἡ τῶν παρεπομένων φίλων ἐκλογὴ καὶ κρίσις, ὑπὲρ ἧς οἱ πλείους οὐκ οἶδ’ ὅπως ῥᾳθυμοῦντες οὐδὲ τὴν ἐλαχίστην ποιοῦνται πρόνοιαν.", "st": "7.14"}, {"sp": "N", "t": "Μασύλιοι, Λιβυκὸν ἔθνος· Πολύβιος ἐν τῷ ἑβδόμῳ Μασυλεῖς αὐτούς φησι", "st": "7.14c"}, {"sp": "N", "t": "λέγεται ἀρσενικῶς, ὡς Πολύβιος ἑβδόμῳ· οἱ δὲ τὸν Ὠρικὸν κατοικοῦντες, οἳ καὶ πρῶτοι κεῖνται περὶ τὴν εἰσβολὴν πρὸς τὸν Ἀδρίαν ἐκ δεξιῶν εἰσπλέοντι", "st": "7.14d"}, {"sp": "N", "t": "περὶ δὲ τὰς Σάρδεις ἄπαυστοι καὶ συνεχεῖς ἀκροβολισμοὶ συνίσταντο καὶ κίνδυνοι καὶ νύκτωρ καὶ μεθ’ ἡμέραν, πᾶν γένος ἐνέδρας, ἀντενέδρας, ἐπιθέσεως ἐξευρισκόντων τῶν στρατιωτῶν κατ’ ἀλλήλων· περὶ ὧν γράφειν τὰ κατὰ μέρος οὐ μόνον ἀνωφελὲς ἀλλὰ καὶ μακρὸν ἂν εἴη τελέως. τὸ δὲ πέρας, ἤδη τῆς πολιορκίας δεύτερον ἔτος ἐνεστώσης, Λαγόρας ὁ Κρής, τριβὴν ἔχων ἐν τοῖς πολεμικοῖς ἱκανήν, καὶ συνεωρακὼς ὅτι συμβαίνει τὰς ὀχυρωτάτας πόλεις ὡς ἐπὶ τὸ πολὺ ῥᾷστα γίνεσθαι τοῖς πολεμίοις ὑποχειρίους διὰ τὴν ὀλιγωρίαν τῶν ἐνοικούντων, ὅταν πιστεύσαντες ταῖς ὀχυρότησι ταῖς φυσικαῖς ἢ χειροποιήτοις ἀφυλακτῶσι καὶ ῥᾳθυμῶσι τὸ παράπαν, καὶ τούτων αὐτῶν ἐπεγνωκὼς διότι συμβαίνει τὰς ἁλώσεις γίνεσθαι κατὰ τοὺς ὀχυρωτάτους τόπους καὶ δοκοῦντας ὑπὸ τῶν ἐναντίων ἀπηλπίσθαι, καὶ τότε θεωρῶν κατὰ τὴν προϋπάρχουσαν δόξαν περὶ τῆς τῶν Σάρδεων ὀχυρότητος ἅπαντας ἀπεγνωκότας ὡς διὰ τοιαύτης πράξεως κυριεύσειν αὐτῆς, μίαν δὲ ταύτην ἔχοντας ἐλπίδα τοῦ διὰ τῆς ἐνδείας κρατήσειν τῆς πόλεως, τοσούτῳ μᾶλλον προσεῖχε καὶ πάντα τρόπον ἠρεύνα, σπεύδων ἀφορμῆς τινος ἐπιλαβέσθαι τοιαύτης. συνθεωρήσας δὲ τὸ κατὰ τὸν καλούμενον Πρίονα τεῖχος ἀφυλακτούμενον — οὗτος δ’ ἔστι τόπος ὁ συνάπτων τὴν ἄκραν καὶ τὴν πόλιν — ἐγίνετο περὶ τὴν ἐλπίδα καὶ τὴν ἐπίνοιαν ταύτην. τὴν μὲν οὖν τῶν φυλαττόντων ῥᾳθυμίαν ἐκ τοιούτου τινὸς σημείου συνέβη θεωρῆσαι. τοῦ τόπου κρημνώδους ὑπάρχοντος διαφερόντως, καὶ φάραγγος ὑποκειμένης, εἰς ἣν ῥιπτεῖσθαι συνέβαινε τοὺς ἐκ τῆς πόλεως νεκροὺς καὶ τὰς τῶν ἵππων καὶ τὰς τῶν ὑποζυγίων τῶν ἀποθνησκόντων κοιλίας, εἰς τοῦτον αἰεὶ τὸ τῶν γυπῶν καὶ τῶν ἄλλων ὀρνέων πλῆθος ἡθροίζετο. συνθεωρήσας οὖν ὁ προειρημένος ἀνήρ, ὅτε πληρωθείη τὰ ζῷα, τὰς ἀναπαύσεις ἐπὶ τῶν κρημνῶν καὶ τοῦ τείχους ποιούμενα συνεχῶς, ἔγνω διότι κατ’ ἀνάγκην ἀφυλακτεῖται τὸ τεῖχος καὶ γίνεται τὸν πλεῖστον χρόνον ἔρημον. λοιπὸν ἐπιμελῶς τὴν νύκτα προσπορευόμενος ἐξήταζε τὰς προσβάσεις καὶ θέσεις τῶν κλιμάκων. εὑρίσκων δὲ κατά τινα τόπον καὶ καθ’ ἕνα τῶν κρημνῶν δυνατὴν οὖσαν, προσφέρει τῷ βασιλεῖ τὸν περὶ τούτων λόγον.", "st": "7.15"}, {"sp": "N", "t": "τοῦ δὲ δεξαμένου τὴν ἐλπίδα καὶ παρακαλέσαντος τὸν Λαγόραν ἐπιτελεῖν τὴν πρᾶξιν, αὐτὸς μὲν ὑπισχνεῖτο τὰ δυνατὰ ποιήσειν, ἠξίου δὲ τὸν βασιλέα Θεόδοτον αὐτῷ τὸν Αἰτωλὸν καὶ Διονύσιον τὸν ἡγεμόνα τῶν ὑπασπιστῶν παρακελεύσαντα συστῆσαι συνεπιδοῦναι σφᾶς καὶ κοινωνῆσαι τῆς ἐπιβολῆς, διὰ τὸ δοκεῖν ἑκάτερον ἱκανὴν δύναμιν ἔχειν καὶ τόλμαν πρὸς τὴν ἐπινοουμένην πρᾶξιν. τοῦ δὲ βασιλέως παραχρῆμα ποιήσαντος τὸ παρακαλούμενον, συμφρονήσαντες οἱ προειρημένοι καὶ κοινωσάμενοι περὶ πάντων ἑαυτοῖς ἐτήρουν νύκτα τὸ περὶ τὴν ἑωθινὴν μέρος ἔχουσαν ἀσέληνον. λαβόντες δὲ τοιαύτην, ἐν ᾗ πράττειν ἔμελλον ἡμέρᾳ, τῇ πρότερον ὀψίας δείλης ἐπέλεξαν ἐκ παντὸς τοῦ στρατοπέδου πεντεκαίδεκα τοὺς εὐρωστοτάτους ἄνδρας καὶ τοῖς σώμασι καὶ ταῖς ψυχαῖς, οἵτινες ἔμελλον ἅμα μὲν προσοίσειν τὰς κλίμακας, ἅμα δὲ συναναβήσεσθαι καὶ μεθέξειν αὐτοῖς τῆς τόλμης. μετὰ δὲ τούτους ἄλλους ἐπελέξαντο τριάκοντα τοὺς ἐν ἀποστήματι συνεφεδρεύσοντας, ἵν’ ἐπειδὰν ὑπερβάντες αὐτοὶ πρὸς τὴν παρακειμένην παραγένωνται πύλην, οὗτοι μὲν ἔξωθεν προσπεσόντες πειρῶνται διακόπτειν τοὺς στροφεῖς καὶ τὸ ζύγωμα τῶν πυλῶν, αὐτοὶ δὲ τὸν μοχλὸν ἔνδοθεν καὶ τὰς βαλανάγρας, δισχιλίους δὲ τοὺς κατόπιν ἀκολουθήσοντας τούτοις, οὓς συνεισπεσόντας ἔδει καταλαβέσθαι τὴν τοῦ θεάτρου στεφάνην, εὐφυῶς κειμένην πρός τε τοὺς ἐκ τῆς ἄκρας καὶ πρὸς τοὺς ἐκ τῆς πόλεως. τοῦ δὲ μὴ γενέσθαι μηδεμίαν ὑποψίαν τῆς ἀληθείας διὰ τὴν ἐπιλογὴν τῶν ἀνδρῶν, διέδωκε λόγον ὡς τοὺς Αἰτωλοὺς μέλλοντας εἰσπίπτειν διά τινος φάραγγος εἰς τὴν πόλιν, καὶ δέον ἐνεργῶς τούτους παραφυλάξαι πρὸς τὸ μηνυθέν.", "st": "7.16"}, {"sp": "N", "t": "ἑτοίμων δὲ πάντων αὐτοῖς γενομένων, ἅμα τῷ κρυφθῆναι τὴν σελήνην λάθρᾳ πρὸς τοὺς κρημνοὺς οἱ περὶ τὸν Λαγόραν ἀφικόμενοι μετὰ τῶν κλιμάκων ὑπέστειλαν ἑαυτοὺς ὑπό τινα προπεπτωκυῖαν ὀφρύν. ἐπιγενομένης δὲ τῆς ἡμέρας, καὶ τῶν μὲν φυλάκων ἀπολυομένων ἀπὸ τοῦ τόπου τούτου, τοῦ δὲ βασιλέως κατὰ τὸν ἐθισμὸν τοὺς μὲν εἰς τὰς ἐφεδρείας ἐκπέμποντος, τοὺς δὲ πολλοὺς εἰς τὸν ἱππόδρομον ἐξαγαγόντος καὶ παρατάττοντος, τὸ μὲν πρῶτον ἀνύποπτον ἦν πᾶσι τὸ γενόμενον. προστεθεισῶν δὲ δυεῖν κλιμάκων, καὶ δι’ ἧς μὲν Διονυσίου, δι’ ἧς δὲ Λαγόρα πρῶτον πορευομένων, ἐγίνετο ταραχὴ καὶ κίνημα περὶ τὸ στρατόπεδον. συνέβαινε γὰρ τοῖς μὲν ἐκ τῆς πόλεως καὶ τοῖς περὶ τὸν Ἀχαιὸν ἐκ τῆς ἄκρας ἀδήλους εἶναι τοὺς προσβαίνοντας διὰ τῆς προπεπτωκυίας ἐπὶ τὸν κρημνὸν ὀφρύος· τοῖς δ’ ἐκ τοῦ στρατοπέδου σύνοπτος ἦν ἡ τόλμα τῶν ἀναβαινόντων καὶ παραβαλλομένων. διόπερ οἱ μὲν ἐκπεπληγμένοι τὸ παράδοξον, οἱ δὲ προορώμενοι καὶ δεδιότες τὸ συμβησόμενον, ἀχανεῖς ἅμα δὲ περιχαρεῖς ὄντες, ἕστασαν. ὅθεν ὁ βασιλεύς, θεωρῶν τὸ περὶ τὴν ὅλην παρεμβολὴν κίνημα, καὶ βουλόμενος ἀποσπᾶν ἀπὸ τοῦ προκειμένου τούς τε παρ’ αὑτοῦ καὶ τοὺς ἐκ τῆς πόλεως, προῆγε τὴν δύναμιν καὶ προσέβαλε πρὸς τὰς ἐπὶ θάτερα πύλας κειμένας, Περσίδας δὲ προσαγορευομένας. Ἀχαιὸς δέ, συνθεωρῶν ἐκ τῆς ἄκρας τὸ περὶ τοὺς ὑπεναντίους κίνημα παρηλλαγμένον τῆς συνηθείας, ἐπὶ πολὺ διηπορεῖτο δυσχρηστούμενος καὶ συννοῆσαι τὸ γινόμενον οὐδαμῶς δυνάμενος. πλὴν ὅμως ἐξαπέστειλε τοὺς ἀπαντήσοντας εἰς τὴν πύλην· ὧν διὰ στενῆς καὶ κρημνώδους ποιουμένων τὴν κατάβασιν βραδεῖαν συνέβαινε γίνεσθαι τὴν ἐπικουρίαν. ὁ δ’ ἐπὶ τῆς πόλεως τεταγμένος Ἀρίβαζος ἀκάκως ὥρμησε πρὸς τὰς πύλας, αἷς ἑώρα προσβάλλοντα τὸν Ἀντίοχον, καὶ τοὺς μὲν ἐπὶ τὸ τεῖχος ἀνεβίβαζε, τοὺς δὲ διὰ τῆς πύλης ἀφιεὶς εἴργειν τοὺς συνεγγίζοντας καὶ συμπλέκεσθαι παρεκελεύετο τοῖς πολεμίοις.", "st": "7.17"}, {"sp": "N", "t": "κατὰ δὲ τὸν καιρὸν τοῦτον οἱ περὶ τὸν Λαγόραν καὶ Θεόδοτον καὶ Διονύσιον ὑπερβάντες τοὺς κρημνοὺς ἧκον ἐπὶ τὴν ὑποκειμένην πύλην. καὶ τινὲς μὲν αὐτῶν διεμάχοντο πρὸς τοὺς ἀπαντῶντας, οἱ δὲ διέκοπτον τοὺς μοχλούς. ἅμα δὲ τούτοις προσπεσόντες ἔξωθεν οἱ τεταγμένοι πρὸς τοῦτο τὸ μέρος τὸ παραπλήσιον ἐποίουν. ταχὺ δὲ τῶν πυλῶν ἀνοιχθεισῶν, εἰσελθόντες οἱ δισχίλιοι κατελάβοντο τὴν τοῦ θεάτρου στεφάνην. οὗ γινομένου πάντες ὥρμησαν ἀπὸ τῶν τειχῶν καὶ τῆς Περσίδος προσαγορευομένης πύλης, ἐφ’ ἣν πρότερον ἐβοήθησαν οἱ περὶ τὸν Ἀρίβαζον, σπεύδοντες παρεγγυᾶν ἐπὶ τοὺς εἰσπεπτωκότας. τούτου δὲ συμβαίνοντος, κατὰ τὴν ἀποχώρησιν ἀνεῳγμένης τῆς πύλης, συνεισέπεσόν τινες τῶν παρὰ τοῦ βασιλέως, ἑπόμενοι τοῖς ὑποχωροῦσιν. ὧν κρατησάντων τῆς πύλης, ἤδη τούτοις κατὰ τὸ συνεχὲς οἱ μὲν εἰσέπιπτον, οἱ δὲ τὰς παρακειμένας διέκοπτον πύλας. οἱ δὲ περὶ τὸν Ἀρίβαζον καὶ πάντες οἱ κατὰ τὴν πόλιν ἐπὶ βραχὺ διαγωνισάμενοι πρὸς τοὺς εἰσεληλυθότας ὥρμησαν φεύγειν πρὸς τὴν ἄκραν. οὗ συμβάντος οἱ μὲν περὶ τὸν Θεόδοτον καὶ Λαγόραν ἔμενον ἐπὶ τῶν κατὰ τὸ θέατρον τόπων, νουνεχῶς καὶ πραγματικῶς ἐφεδρεύοντες τοῖς ὅλοις, ἡ δὲ λοιπὴ δύναμις εἰσπεσοῦσα πανταχόθεν ἅμα κατειλήφει τὴν πόλιν. καὶ τὸ λοιπὸν ἤδη, τῶν μὲν φονευόντων τοὺς ἐντυγχάνοντας, τῶν δὲ τὰς οἰκήσεις ἐμπιπρώντων, ἄλλων δὲ πρὸς τὰς ἁρπαγὰς καὶ τὰς ὠφελείας ὡρμηκότων, ἐγίνετο παντελὴς ἡ τῆς πόλεως καταφθορὰ καὶ διαρπαγή. καὶ Σάρδεων μὲν τοῦτον τὸν τρόπον ἐγένετο κύριος Ἀντίοχος.", "st": "7.18"}, {"sp": "HDR", "t": "Βιβλίον Ηʹ", "st": "8"}, {"sp": "N", "t": "ὅτι Τιβέριος ὁ Ῥωμαίων στρατηγὸς λόχῳ ἐνεδρευθεὶς καὶ γενναίως ὑποστὰς σὺν τοῖς περὶ αὑτὸν τὸν βίον κατέστρεψεν. περὶ δὲ τῶν τοιούτων περιπετειῶν, πότερα χρὴ τοῖς πάσχουσιν ἐπιτιμᾶν ἢ συγγνώμην ἔχειν, καθόλου μὲν οὐκ ἀσφαλὲς ἀποφήνασθαι διὰ τὸ καὶ πλείους τὰ κατὰ λόγον πάντα πράξαντας, ὅμως ὑποχειρίους γεγονέναι τοῖς ἑτοίμως τὰ παρ’ ἀνθρώποις ὡρισμένα δίκαια παραβαίνουσιν· οὐ μὴν οὐδ’ αὐτόθεν ἀποστατέον τῆς ἀποφάσεως ἀργῶς, ἀλλὰ βλέποντα πρὸς τοὺς καιροὺς καὶ τὰς περιστάσεις οἷς μὲν ἐπιτιμητέον τῶν ἡγεμόνων, οἷς δὲ συγγνώμην δοτέον. ἔσται δὲ τὸ λεγόμενον δῆλον ἐκ τούτων. Ἀρχίδαμος ὁ τῶν Λακεδαιμονίων βασιλεὺς ὑπιδόμενος τὴν Κλεομένους φιλαρχίαν ἔφυγεν ἐκ τῆς Σπάρτης, μετ’ οὐ πολὺ δὲ πάλιν πεισθεὶς ἐνεχείρισεν αὑτὸν τῷ προειρημένῳ. τοιγαροῦν ἅμα τῆς ἀρχῆς καὶ τοῦ βίου στερηθεὶς οὐδ’ ἀπολογίαν αὑτῷ κατέλιπε πρὸς τοὺς ἐπιγινομένους· τῆς γὰρ ὑποθέσεως τῆς αὐτῆς μενούσης, τῆς δὲ Κλεομένους φιλαρχίας καὶ δυναστείας ἐπηυξημένης, ὁ τούτοις ἐγχειρίσας αὑτὸν οὓς φυγὼν πρότερον ἔτυχε παραδόξως τῆς σωτηρίας, πῶς οὐκ εὐλόγως ἔμελλε τοῖς προειρημένοις ἐγκυρήσειν; καὶ μὴν Πελοπίδας ὁ Θηβαῖος, εἰδὼς τὴν Ἀλεξάνδρου τοῦ τυράννου παρανομίαν καὶ σαφῶς γινώσκων ὅτι πᾶς τύραννος πολεμιωτάτους αὑτῷ νομίζει τοὺς τῆς ἐλευθερίας προεστῶτας, αὐτὸς οὐ μόνον τῆς Θηβαίων ἀλλὰ καὶ τῆς τῶν Ἑλλήνων δημοκρατίας ἔπειθεν Ἐπαμινώνδαν προεστάναι, καὶ παρὼν εἰς Θετταλίαν πολέμιος ἐπὶ καταλύσει τῆς Ἀλεξάνδρου μοναρχίας πρεσβεύειν πρὸς τοῦτον ὑπέμεινε δεύτερον. τοιγαροῦν γενόμενος ὑποχείριος τοῖς ἐχθροῖς ἔβλαψε μὲν Θηβαίους μεγάλα, κατέλυσε δὲ τὴν αὑτῷ προγεγενημένην δόξαν, εἰκῇ καὶ ἀκρίτως πιστεύσας οἷς ἥκιστ’ ἐχρῆν. παραπλήσια δὲ τούτοις καὶ Γνάϊος ὁ Ῥωμαίων στρατηγὸς ἔπαθε κατὰ τὸν Σικελικὸν πόλεμον, ἀλόγως αὑτὸν ἐγχειρίσας τοῖς πολεμίοις· ὁμοίως δὲ καὶ πλείους ἕτεροι.", "st": "8.1"}, {"sp": "N", "t": "διὸ καὶ τοῖς μὲν ἀσκέπτως ἑαυτοὺς ἐγχειρίζουσι τοῖς ὑπεναντίοις ἐπιτιμητέον, τοῖς δὲ τὴν ἐνδεχομένην πρόνοιαν ποιουμένοις οὐκ ἐγκλητέον· τὸ μὲν γὰρ μηδενὶ πιστεύειν εἰς τέλος ἄπρακτον, τὸ δὲ λαβόντα τὰς ἐνδεχομένας πίστεις πράττειν τὸ κατὰ λόγον ἀνεπιτίμητον. εἰσὶ δ’ ἐνδεχόμεναι πίστεις ὅρκοι, τέκνα, γυναῖκες, τὸ μέγιστον ὁ προγεγονὼς βίος. ᾗ καὶ τὸ διὰ τῶν τοιούτων ἀλογηθῆναι καὶ περιπεσεῖν οὐ τῶν πασχόντων, ἀλλὰ τῶν πραξάντων ἐστὶν ἔγκλημα. διὸ καὶ μάλιστα μὲν τοιαύτας ζητεῖν πίστεις δεῖ, δι’ ὧν ὁ πιστευθεὶς οὐ δυνήσεται τὴν πίστιν ἀθετεῖν. ἐπεὶ δὲ σπάνιον εὑρεῖν ἐστι τὸ τοιοῦτο, δεύτερος ἂν εἴη πλοῦς τὸ τῶν κατὰ λόγον φροντίζειν, ἵν’ ἄν του καὶ σφαλλώμεθα, τῆς παρὰ τοῖς ἐκτὸς συγγνώμης μὴ διαμαρτάνωμεν. ὃ καὶ περὶ πλείους μὲν δὴ γεγένηται τῶν πρότερον· ἐναργέστατον δ’ ἔσται καὶ τοῖς καιροῖς ἔγγιστον τοῖς ὑπὲρ ὧν ὁ νῦν δὴ λόγος ἐνέστηκε τὸ κατ’ Ἀχαιὸν συμβάν. ὃς οὐδὲν τῶν ἐνδεχομένων πρὸς εὐλάβειαν καὶ πρὸς ἀσφάλειαν παραλιπών, ἀλλ’ ὑπὲρ ἁπάντων προνοηθείς, ἐφ’ ὅσον ἀνθρωπίνῃ γνώμῃ δυνατὸν ἦν, ὅμως ἐγένετο τοῖς ἐχθροῖς ὑποχείριος. τό γε μὴν συμβὰν ἔλεον μὲν τῷ παθόντι καὶ συγγνώμην ἀπειργάσατο παρὰ τοῖς ἐκτός, διαβολὴν δὲ καὶ μῖσος τοῖς πράξασιν.", "st": "8.2"}, {"sp": "N", "t": "οὐκ ἀλλότριον εἶναί μοι δοκεῖ τῆς ὅλης ἡμῶν ἐπιβολῆς καὶ τῆς ἐν ἀρχαῖς προθέσεως συνεπιστῆσαι τοὺς ἀκούοντας ἐπὶ τὸ μεγαλεῖον τῶν πράξεων καὶ τὸ φιλότιμον τῆς ἑκατέρου τοῦ πολιτεύματος προαιρέσεως, λέγω δὲ τοῦ Ῥωμαίων καὶ Καρχηδονίων. τίς γὰρ οὐκ ἂν ἐπισημήναιτο πῶς τηλικοῦτον μὲν πόλεμον συνεσταμένοι περὶ τῶν κατὰ τὴν Ἰταλίαν πραγμάτων, οὐκ ἐλάττω δὲ τούτου περὶ τῶν κατὰ τὴν Ἰβηρίαν, ἀκμὴν δὲ περὶ τούτων ἀδήλους μὲν ἔχοντες ἐπ’ ἴσον ἀμφότεροι τὰς ὑπὲρ τοῦ μέλλοντος ἐλπίδας, ἐφαμίλλους δὲ τοὺς κατὰ τὸ παρὸν ἐνεστῶτας κινδύνους, ὅμως οὐκ ἠρκοῦντο ταῖς προκειμέναις ἐπιβολαῖς, ἀλλὰ καὶ περὶ Σαρδόνος καὶ Σικελίας ἠμφισβήτουν· … καὶ πάντα περιελάμβανον, οὐ μόνον ταῖς ἐλπίσιν, ἀλλὰ καὶ ταῖς χορηγίαις καὶ ταῖς παρασκευαῖς; ὃ καὶ μάλιστ’ ἄν τις εἰς τὸ κατὰ μέρος ἐμβλέψας θαυμάσειε. δύο μὲν γὰρ Ῥωμαίοις κατὰ τὴν Ἰταλίαν μετὰ τῶν ὑπάτων ἐντελῆ προεκάθητο στρατόπεδα, δύο δὲ κατὰ τὴν Ἰβηρίαν, ὧν τὸ μὲν πεζὸν Γνάϊος εἶχε, τὸ δὲ ναυτικὸν Πόπλιος. οἰκείως δὲ ταῦτα συνέβαινε γίνεσθαι καὶ παρὰ Καρχηδονίοις. καὶ μὴν τοῖς κατὰ τὴν Ἑλλάδα τόποις ἐφώρμει καὶ ταῖς ἐπιβολαῖς τοῦ Φιλίππου στόλος, ἐφ’ οὗ τὸ μὲν πρῶτον Μάρκος Οὐαλέριος, μετὰ δὲ ταῦτα Πόπλιος ἐπέπλει Σουλπίκιος. ἅμα δὲ τούτοις Ἄππιος μὲν ἑκατὸν πεντηρικοῖς σκάφεσι, Μάρκος δὲ Κλαύδιος πεζικὰς ἔχων δυνάμεις, ἐφήδρευε τοῖς κατὰ τὴν Σικελίαν. τὸ δ’ αὐτὸ τοῦτ’ Ἀμίλκας ἐποίει παρὰ Καρχηδονίοις.", "st": "8.3"}, {"sp": "N", "t": "δι’ ὧν ὑπολαμβάνω τὸ πολλάκις ἐν ἀρχαῖς ἡμῖν τῆς πραγματείας εἰρημένον νῦν δι’ αὐτῶν τῶν ἔργων ἀληθινὴν λαμβάνειν πίστιν. τοῦτο δ’ ἦν ὡς οὐχ οἷόν τε διὰ τῶν τὰς κατὰ μέρος ἱστορίας γραφόντων συνθεάσασθαι τὴν τῶν ὅλων οἰκονομίαν. πῶς γὰρ ἐνδέχεται ψιλῶς αὐτὰς καθ’ αὑτὰς ἀναγνόντα τὰς Σικελικὰς ἢ τὰς Ἰβηρικὰς πράξεις, γνῶναι καὶ μαθεῖν ἢ τὸ μέγεθος τῶν γεγονότων ἢ τὸ συνέχον, τίνι τρόπῳ καὶ τίνι γένει πολιτείας τὸ παραδοξότατον καθ’ ἡμᾶς ἔργον ἡ τύχη συνετέλεσε; τοῦτο δ’ ἔστι τὸ πάντα τὰ γνωριζόμενα μέρη τῆς οἰκουμένης ὑπὸ μίαν ἀρχὴν καὶ δυναστείαν ἀγαγεῖν, ὃ πρότερον οὐχ εὑρίσκεται γεγονός. πῶς μὲν γὰρ εἷλον Συρακούσας Ῥωμαῖοι καὶ πῶς Ἰβηρίαν κατέσχον, οὐκ ἀδύνατον καὶ διὰ τῶν κατὰ μέρος ἐπὶ ποσὸν γνῶναι συντάξεων· πῶς δὲ τῆς ἁπάντων ἡγεμονίας καθίκοντο, καὶ τί πρὸς τὰς ὁλοσχερεῖς αὐτοῖς ἐπιβολὰς τῶν κατὰ μέρος ἀντέπραξε, καὶ τί πάλιν καὶ κατὰ τίνας καιροὺς συνήργησε, δυσχερὲς καταλαβεῖν ἄνευ τῆς καθόλου τῶν πράξεων ἱστορίας. οὐ μὴν τὸ μέγεθος τῶν ἔργων οὐδὲ τὴν τοῦ πολιτεύματος δύναμιν εὐμαρὲς κατανοῆσαι διὰ τὰς αὐτὰς αἰτίας. τὸ γὰρ ἀντιποιήσασθαι Ῥωμαίους Ἰβηρίας ἢ πάλιν Σικελίας, καὶ στρατεῦσαι πεζικαῖς καὶ ναυτικαῖς δυνάμεσιν, αὐτὸ καθ’ αὑτὸ λεγόμενον οὐκ ἂν εἴη θαυμαστόν. ἅμα δὲ τούτων συμβαινόντων καὶ πολλαπλασίων ἄλλων κατὰ τὸν αὐτὸν καιρὸν ἐπιτελουμένων ἐκ τῆς αὐτῆς ἀρχῆς καὶ πολιτείας, καὶ θεωρουμένων ὁμοῦ τούτοις τῶν κατὰ τὴν ἰδίαν χώραν ὑπαρχουσῶν περιστάσεων καὶ πολέμων περὶ τοὺς ἅπαντα τὰ προειρημένα χειρίζοντας, οὕτως ἂν εἴη μόνως σαφῆ τὰ γεγονότα καὶ θαυμαστὰ καὶ μάλιστ’ ἂν οὕτως τυγχάνοι τῆς ἁρμοζούσης ἐπιστάσεως. ταῦτα μὲν οὖν ἡμῖν εἰρήσθω πρὸς τοὺς ὑπολαμβάνοντας διὰ τῆς τῶν κατὰ μέρος συντάξεως ἐμπειρίαν ποιήσασθαι τῆς καθολικῆς καὶ κοινῆς ἱστορίας.", "st": "8.4"}, {"sp": "N", "t": "ἐκπέμπουσι τῶν Κρητῶν τινας ὡς ἐπὶ λῃστείαν, δόντες ἐπιστολὴν διεσκευασμένην.", "st": "8.4b"}, {"sp": "N", "t": "ὅτε δὴ τὰς Συρακούσας Ἐπικύδης τε καὶ Ἱπποκράτης κατέλαβον, ἑαυτούς τε καὶ τοὺς ἄλλους τῶν πολιτῶν τῆς Ῥωμαίων φιλίας ἀλλοτριώσαντες, οἱ Ῥωμαῖοι προσπεπτωκυίας αὐτοῖς ἤδη καὶ τῆς Ἱερωνύμου τοῦ Συρακοσίων τυράννου καταστροφῆς Ἄππιον Κλαύδιον ἀντιστράτηγον καταστήσαντες αὐτῷ μὲν τὴν πεζὴν συνέστησαν δύναμιν, τὸν δὲ νηΐτην αὐτοῖς στόλον ἐπετρόπευσε Μάρκος Κλαύδιος. οὗτοι μὲν δὴ τὴν στρατοπεδείαν ἐβάλοντο μικρὸν ἀποσχόντες τῆς πόλεως, τὰς δὲ προσβολὰς ἔκριναν ποιεῖσθαι τῇ μὲν πεζῇ δυνάμει κατὰ τοὺς ἀπὸ τῶν Ἑξαπύλων τόπους, τῇ δὲ ναυτικῇ τῆς Ἀχραδίνης κατὰ τὴν Σκυτικὴν προσαγορευομένην στοάν, καθ’ ἣν ἐπ’ αὐτῆς κεῖται τῆς κρηπῖδος τὸ τεῖχος παρὰ θάλατταν. ἑτοιμασάμενοι δὲ γέρρα καὶ βέλη καὶ τἄλλα τὰ πρὸς τὴν πολιορκίαν, ἐν ἡμέραις πέντε διὰ τὴν πολυχειρίαν ἤλπισαν καταταχήσειν τῇ παρασκευῇ τοὺς ὑπεναντίους, οὐ λογισάμενοι τὴν Ἀρχιμήδους δύναμιν, οὐδὲ προϊδόμενοι διότι μία ψυχὴ τῆς ἁπάσης ἐστὶ πολυχειρίας ἐν ἐνίοις καιροῖς ἀνυστικωτέρα. πλὴν τότε δι’ αὐτῶν ἔγνωσαν τῶν ἔργων τὸ λεγόμενον. οὔσης γὰρ ὀχυρᾶς τῆς πόλεως διὰ τὸ κεῖσθαι κύκλῳ τὸ τεῖχος ἐπὶ τόπων ὑπερδεξίων καὶ προκειμένης ὀφρύος, πρὸς ἣν καὶ μηδενὸς κωλύοντος οὐκ ἂν εὐμαρῶς τις δύναιτο πελάσαι πλὴν κατά τινας τόπους ὡρισμένους, τοιαύτην ἡτοίμασε παρασκευὴν ὁ προειρημένος ἀνὴρ ἐντὸς τῆς πόλεως, ὁμοίως δὲ καὶ πρὸς τοὺς κατὰ θάλατταν ἐπιπορευομένους, ὥστε μηδὲν ἐκ τοῦ καιροῦ δεῖν ἀσχολεῖσθαι τοὺς ἀμυνομένους, πρὸς πᾶν δὲ τὸ γινόμενον ὑπὸ τῶν ἐναντίων ἐξ ἑτοίμου ποιεῖσθαι τὴν ἀπάντησιν. πλὴν ὁ μὲν Ἄππιος ἔχων γέρρα καὶ κλίμακας ἐνεχείρει προσφέρειν ταῦτα τῷ συνάπτοντι τείχει τοῖς Ἑξαπύλοις ἀπὸ τῶν ἀνατολῶν.", "st": "8.5"}, {"sp": "N", "t": "ὁ δὲ Μάρκος ἑξήκοντα σκάφεσι πεντηρικοῖς ἐποιεῖτο τὸν ἐπίπλουν ἐπὶ τὴν Ἀχραδίνην, ὧν ἕκαστον πλῆρες ἦν ἀνδρῶν ἐχόντων τόξα καὶ σφενδόνας καὶ γρόσφους, δι’ ὧν ἔμελλον τοὺς ἀπὸ τῶν ἐπάλξεων μαχομένους ἀναστέλλειν. ἅμα δὲ τούτοις ὀκτὼ πεντήρεσι, παραλελυμέναις τοὺς ταρσούς, ταῖς μὲν τοὺς δεξιούς, ταῖς δὲ τοὺς εὐωνύμους, καὶ συνεζευγμέναις πρὸς ἀλλήλας σύνδυο κατὰ τοὺς ἐψιλωμένους τοίχους, προσῆγον πρὸς τὸ τεῖχος διὰ τῆς τῶν ἐκτὸς τοίχων εἰρεσίας τὰς λεγομένας σαμβύκας. τὸ δὲ γένος τῆς κατασκευῆς τῶν εἰρημένων ὀργάνων ἐστὶ τοιοῦτο. κλίμακα τῷ πλάτει τετράπεδον ἑτοιμάσαντες, ὥστ’ ἐξ ἀποβάσεως ἰσοϋψῆ γενέσθαι τῷ τείχει, ταύτης ἑκατέραν τὴν πλευρὰν δρυφακτώσαντες καὶ σκεπάσαντες ὑπερπετέσι θωρακίοις, ἔθηκαν πλαγίαν ἐπὶ τοὺς συμψαύοντας τοίχους τῶν συνεζευγμένων νεῶν, πολὺ προπίπτουσαν τῶν ἐμβόλων. πρὸς δὲ τοῖς ἱστοῖς ἐκ τῶν ἄνω μερῶν τροχιλίαι προσήρτηντο σὺν κάλοις. λοιπὸν ὅταν ἐγγίσωσι τῆς χρείας, ἐνδεδεμένων τῶν κάλων εἰς τὴν κορυφὴν τῆς κλίμακος, ἕλκουσι διὰ τῶν τροχιλιῶν τούτους ἑστῶτες ἐν ταῖς πρύμναις· ἕτεροι δὲ παραπλησίως ἐν ταῖς πρώρραις ἐξερείδοντες ταῖς ἀντηρίσιν ἀσφαλίζονται τὴν ἄρσιν τοῦ μηχανήματος. κἄπειτα διὰ τῆς εἰρεσίας τῆς ἀφ’ ἑκατέρου τῶν ἐκτὸς ταρσῶν ἐγγίσαντες τῇ γῇ τὰς ναῦς, πειράζουσι προσερείδειν τῷ τείχει τὸ προειρημένον ὄργανον. ἐπὶ δὲ τῆς κλίμακος ἄκρας ὑπάρχει πέτευρον ἠσφαλισμένον γέρροις τὰς τρεῖς ἐπιφανείας, ἐφ’ οὗ τέτταρες ἄνδρες ἐπιβεβηκότες ἀγωνίζονται, διαμαχόμενοι πρὸς τοὺς εἴργοντας ἀπὸ τῶν ἐπάλξεων τὴν πρόσθεσιν τῆς σαμβύκης. ἐπὰν δὲ προσερείσαντες ὑπερδέξιοι γένωνται τοῦ τείχους, οὗτοι μὲν τὰ πλάγια τῶν γέρρων παραλύσαντες ἐξ ἑκατέρου τοῦ μέρους ἐπιβαίνουσιν ἐπὶ τὰς ἐπάλξεις ἢ τοὺς πύργους. οἱ δὲ λοιποὶ διὰ τῆς σαμβύκης ἕπονται τούτοις, ἀσφαλῶς τοῖς κάλοις βεβηκυίας τῆς κλίμακος εἰς ἀμφοτέρας τὰς ναῦς. εἰκότως δὲ τὸ κατασκεύασμα τῆς προσηγορίας τέτευχε ταύτης· ἐπειδὰν γὰρ ἐξαρθῇ, γίνεται τὸ σχῆμα τῆς νεὼς ταύτης καὶ τῆς κλίμακος ἑνοποιηθὲν παραπλήσιον σαμβύκῃ.", "st": "8.6"}, {"sp": "N", "t": "πλὴν οὗτοι μὲν τὸν τρόπον τοῦτον διηρμοσμένοι προσάγειν διενοοῦντο τοῖς πύργοις· ὁ δὲ προειρημένος ἀνήρ, παρεσκευασμένος ὄργανα πρὸς ἅπαν ἐμβελὲς διάστημα, πόρρωθεν μὲν ἐπιπλέοντας τοῖς εὐτονωτέροις καὶ μείζοσι λιθοβόλοις καὶ βέλεσι τιτρώσκων εἰς ἀπορίαν ἐνέβαλε καὶ δυσχρηστίαν, ὅτε δὲ ταῦθ’ ὑπερπετῆ γίνοιτο, τοῖς ἐλάττοσι κατὰ λόγον ἀεὶ πρὸς τὸ παρὸν ἀπόστημα χρώμενος εἰς τοιαύτην ἤγαγε διατροπὴν ὥστε καθόλου κωλύειν αὐτῶν τὴν ὁρμὴν καὶ τὸν ἐπίπλουν, ἕως ὁ Μάρκος δυσθετούμενος ἠναγκάσθη λάθρᾳ νυκτὸς ἔτι ποιήσασθαι τὴν παραγωγήν. γενομένων δ’ αὐτῶν ἐντὸς βέλους πρὸς τῇ γῇ, πάλιν ἑτέραν ἡτοιμάκει παρασκευὴν πρὸς τοὺς ἀπομαχομένους ἐκ τῶν πλοίων. ἕως ἀνδρομήκους ὕψους κατεπύκνωσε τρήμασι τὸ τεῖχος ὡς παλαιστιαίοις τὸ μέγεθος κατὰ τὴν ἐκτὸς ἐπιφάνειαν· οἷς τοξότας καὶ σκορπίδια παραστήσας ἐντὸς τοῦ τείχους, καὶ βάλλων διὰ τούτων, ἀχρήστους ἐποίει τοὺς ἐπιβάτας. ἐξ οὗ καὶ μακρὰν ἀφεστῶτας καὶ σύνεγγυς ὄντας τοὺς πολεμίους οὐ μόνον ἀπράκτους παρεσκεύαζε πρὸς τὰς ἰδίας ἐπιβολάς, ἀλλὰ καὶ διέφθειρε τοὺς πλείστους αὐτῶν. ὅτε δὲ τὰς σαμβύκας ἐγχειρήσαιεν ἐξαίρειν, ὄργανα παρ’ ὅλον τὸ τεῖχος ἡτοιμάκει, τὸν μὲν λοιπὸν χρόνον ἀφανῆ, κατὰ δὲ τὸν τῆς χρείας καιρὸν ἐκ τῶν ἔσω μερῶν ὑπὲρ τοῦ τείχους ἀνιστάμενα καὶ προπίπτοντα πολὺ τῆς ἐπάλξεως ταῖς κεραίαις· ὧν τινὰ μὲν ἐβάσταζε λίθους οὐκ ἐλάττους δέκα ταλάντων, τινὰ δὲ σηκώματα μολίβδινα. λοιπὸν ὅτε συνεγγίζοιεν αἱ σαμβῦκαι, τότε περιαγόμεναι καρχησίῳ πρὸς τὸ δέον αἱ κεραῖαι διά τινος σχαστηρίας ἠφίεσαν εἰς τὸ κατασκεύασμα τὸν λίθον· ἐξ οὗ συνέβαινε μὴ μόνον αὐτὸ συνθραύεσθαι τοὔργανον, ἀλλὰ καὶ τὴν ναῦν καὶ τοὺς ἐν αὐτῇ κινδυνεύειν ὁλοσχερῶς.", "st": "8.7"}, {"sp": "N", "t": "τινά τε τῶν μηχανημάτων πάλιν ἐπὶ τοὺς ἐφορμῶντας καὶ προβεβλημένους γέρρα καὶ διὰ τούτων ἠσφαλισμένους πρὸς τὸ μηδὲν πάσχειν ὑπὸ τῶν διὰ τοῦ τείχους φερομένων βελῶν, ἠφίει μὲν καὶ λίθους συμμέτρους πρὸς τὸ φεύγειν ἐκ τῆς πρώρρας τοὺς ἀγωνιζομένους, ἅμα δὲ καὶ καθίει χεῖρα σιδηρᾶν ἐξ ἁλύσεως δεδεμένην, ᾗ δραξάμενος ὁ τὴν κεραίαν οἰακίζων ὅθεν ἐπιλάβοιτο τῆς πρώρρας, κατῆγε τὴν πτέρναν τῆς μηχανῆς ἐντὸς τοῦ τείχους. ὅτε δὲ κουφίζων τὴν πρῶρραν ὀρθὸν ποιήσειε τὸ σκάφος ἐπὶ πρύμναν, τὰς μὲν πτέρνας τῶν ὀργάνων εἰς ἀκίνητον καθῆπτε, τὴν δὲ χεῖρα καὶ τὴν ἅλυσιν ἐκ τῆς μηχανῆς ἐξέρραινε διά τινος σχαστηρίας. οὗ γινομένου τινὰ μὲν τῶν πλοίων πλάγια κατέπιπτε, τινὰ δὲ καὶ κατεστρέφετο, τὰ δὲ πλεῖστα τῆς πρώρρας ἀφ’ ὕψους ῥιφθείσης βαπτιζόμενα πλήρη θαλάττης ἐγίνετο καὶ ταραχῆς. Μάρκος δὲ δυσχρηστούμενος ἐπὶ τοῖς ἀπαντωμένοις ὑπ’ Ἀρχιμήδους, καὶ θεωρῶν μετὰ βλάβης καὶ χλευασμοῦ τοὺς ἔνδον ἀποτριβομένους αὑτοῦ τὰς ἐπιβολάς, δυσχερῶς μὲν ἔφερε τὸ συμβαῖνον, ὅμως δ’ ἐπισκώπτων τὰς αὑτοῦ πράξεις ἔφη ταῖς μὲν ναυσὶν αὐτοῦ κυαθίζειν ἐκ θαλάττης Ἀρχιμήδη, τὰς δὲ σαμβύκας ῥαπιζομένας ὥσπερ ἐκσπόνδους μετ’ αἰσχύνης ἐκπεπτωκέναι. καὶ τῆς μὲν κατὰ θάλατταν πολιορκίας τοιοῦτον ἀπέβη τὸ τέλος.", "st": "8.8"}, {"sp": "N", "t": "οἱ δὲ περὶ τὸν Ἄππιον εἰς παραπλησίους ἐμπεσόντες δυσχερείας ἀπέστησαν τῆς ἐπιβολῆς. ἔτι μὲν γὰρ ὄντες ἐν ἀποστήματι τοῖς τε πετροβόλοις καὶ καταπέλταις τυπτόμενοι διεφθείροντο, διὰ τὸ θαυμάσιον εἶναι τὴν τῶν βελῶν κατασκευὴν καὶ κατὰ τὸ πλῆθος καὶ κατὰ τὴν ἐνέργειαν, ὡς ἂν Ἱέρωνος μὲν χορηγοῦ γεγονότος, ἀρχιτέκτονος δὲ καὶ δημιουργοῦ τῶν ἐπινοημάτων Ἀρχιμήδους. συνεγγίζοντές γε μὴν πρὸς τὴν πόλιν οἱ μὲν ταῖς διὰ τοῦ τείχους τοξότισιν, ὡς ἐπάνω προεῖπον, κακούμενοι συνεχῶς εἴργοντο τῆς προσόδου· οἱ δὲ μετὰ τῶν γέρρων βιαζόμενοι ταῖς τῶν κατὰ κορυφὴν λίθων καὶ δοκῶν ἐμβολαῖς διεφθείροντο. οὐκ ὀλίγα δὲ καὶ ταῖς χερσὶ ταῖς ἐκ τῶν μηχανῶν ἐκακοποίουν, ὡς καὶ πρότερον εἶπα· σὺν αὐτοῖς γὰρ τοῖς ὅπλοις τοὺς ἄνδρας ἐξαιροῦντες ἐρρίπτουν. τὸ δὲ πέρας, ἀναχωρήσαντες εἰς τὴν παρεμβολὴν καὶ συνεδρεύσαντες μετὰ τῶν χιλιάρχων οἱ περὶ τὸν Ἄππιον, ὁμοθυμαδὸν ἐβουλεύσαντο πάσης ἐλπίδος πεῖραν λαμβάνειν πλὴν τοῦ διὰ πολιορκίας ἑλεῖν τὰς Συρακούσας, ὡς καὶ τέλος ἐποίησαν· ὀκτὼ γὰρ μῆνας τῇ πόλει προσκαθεζόμενοι τῶν μὲν ἄλλων στρατηγημάτων ἢ τολμημάτων οὐδενὸς ἀπέστησαν, τοῦ δὲ πολιορκεῖν οὐδέποτε πεῖραν ἔτι λαβεῖν ἐθάρρησαν. οὕτως εἷς ἀνὴρ καὶ μία ψυχὴ δεόντως ἡρμοσμένη πρὸς ἔνια τῶν πραγμάτων μέγα τι χρῆμα φαίνεται γίνεσθαι καὶ θαυμάσιον. ἐκεῖνοι γοῦν τηλικαύτας δυνάμεις ἔχοντες καὶ κατὰ γῆν καὶ κατὰ θάλατταν, εἰ μὲν ἀφέλοι τις πρεσβύτην ἕνα Συρακοσίων, παραχρῆμα τῆς πόλεως κυριεύσειν ἤλπιζον, τούτου δὲ συμπαρόντος οὐκ ἐθάρρουν οὐδ’ ἐπιβαλέσθαι κατά γε τοῦτον τὸν τρόπον, καθ’ ὃν ἀμύνασθαι δυνατὸς ἦν Ἀρχιμήδης. οὐ μὴν ἀλλὰ νομίσαντες μάλιστ’ ἂν ὑπὸ τῆς τῶν ἀναγκαίων ἐνδείας διὰ τὸ πλῆθος τοὺς ἔνδον ὑποχειρίους σφίσι γενέσθαι, ταύτης ἀντείχοντο τῆς ἐλπίδος· καὶ ταῖς μὲν ναυσὶ τὰς κατὰ θάλατταν ἐπικουρίας αὐτῶν ἐκώλυον, τῷ δὲ πεζῷ στρατεύματι τὰς κατὰ γῆν. βουλόμενοι δὲ μὴ ποιεῖν ἄπρακτον τὸν χρόνον, ἐν ᾧ προσεδρεύουσι ταῖς Συρακούσαις, ἀλλ’ ἅμα τι καὶ τῶν ἐκτὸς χρησίμων κατασκευάζεσθαι, διεῖλον οἱ στρατηγοὶ σφᾶς αὐτοὺς καὶ τὴν δύναμιν, ὥστε τὸν μὲν Ἄππιον ἔχοντα δύο μέρη προσκαθῆσθαι τοῖς ἐν τῇ πόλει, τὸ δὲ τρίτον ἀναλαβόντα Μάρκον ἐπιπορεύεσθαι τοὺς τὰ Καρχηδονίων αἱρουμένους κατὰ τὴν Σικελίαν.", "st": "8.9"}, {"sp": "N", "t": "ὅτι Φίλιππος παραγενόμενος εἰς τὴν Μεσσήνην ἔφθειρε τὴν χώραν δυσμενικῶς, θυμῷ τὸ πλεῖον ἢ λογισμῷ χρώμενος· ἤλπιζε γάρ, ὡς ἐμοὶ δοκεῖ, βλάπτων συνεχῶς οὐδέποτ’ ἀγανακτήσειν οὐδὲ μισήσειν αὐτὸν τοὺς κακῶς πάσχοντας. προήχθην δὲ καὶ νῦν καὶ διὰ τῆς προτέρας βύβλου σαφέστερον ἐξηγήσασθαι περὶ τούτων οὐ μόνον διὰ τὰς πρότερον ἡμῖν εἰρημένας αἰτίας, ἀλλὰ καὶ διὰ τὸ τῶν συγγραφέων τοὺς μὲν ὅλως παραλελοιπέναι τὰ κατὰ τοὺς Μεσσηνίους, τοὺς δὲ καθόλου διὰ τὴν πρὸς τοὺς μονάρχους εὔνοιαν ἢ τἀναντία φόβον οὐχ οἷον ἐν ἁμαρτίᾳ γεγονέναι τὴν εἰς τοὺς Μεσσηνίους ἀσέβειαν Φιλίππου καὶ παρανομίαν, ἀλλὰ τοὐναντίον ἐν ἐπαίνῳ καὶ κατορθώματι τὰ πεπραγμένα διασαφεῖν ἡμῖν. οὐ μόνον δὲ περὶ Μεσσηνίους τοῦτο πεποιηκότας ἰδεῖν ἔστι τοὺς γράφοντας τοῦ Φιλίππου τὰς πράξεις, ἀλλὰ καὶ περὶ τῶν ἄλλων παραπλησίως. ἐξ ὧν ἱστορίας μὲν οὐδαμῶς ἔχειν αὐτοῖς συμβαίνει διάθεσιν τὰς συντάξεις, ἐγκωμίου δὲ μᾶλλον. ἐγὼ δ’ οὔτε λοιδορεῖν ψευδῶς φημι δεῖν τοὺς μονάρχους οὔτ’ ἐγκωμιάζειν, ὃ πολλοῖς ἤδη συμβέβηκε, τὸν ἀκόλουθον δὲ τοῖς προγεγραμμένοις ἀεὶ καὶ τὸν πρέποντα ταῖς ἑκάστων προαιρέσεσι λόγον ἐφαρμόζειν. ἀλλ’ ἴσως τοῦτ’ εἰπεῖν μὲν εὐμαρές, πρᾶξαι δὲ καὶ λίαν δυσχερὲς διὰ τὸ πολλὰς καὶ ποικίλας εἶναι διαθέσεις καὶ περιστάσεις, αἷς εἴκοντες ἄνθρωποι κατὰ τὸν βίον οὔτε λέγειν οὔτε γράφειν δύνανται τὸ φαινόμενον. ὧν χάριν τισὶ μὲν αὐτῶν συγγνώμην δοτέον, ἐνίοις γε μὴν οὐ δοτέον.", "st": "8.10"}, {"sp": "N", "t": "καταλαβέσθαι … ἐγχειρήσας μετὰ τῆς Φιλίππου γνώμης τὴν τῶν Μεσσηνίων πόλιν εἰκῇ καὶ παραβόλως, ἐν αὐτῷ τῷ τῆς πράξεως καιρῷ διεφθάρη· περὶ ὧν ἡμεῖς τὰ κατὰ μέρος, ὅταν ἐπὶ τοὺς καιροὺς ἔλθωμεν, διασαφήσομεν.", "st": "8.8a"}, {"sp": "N", "t": "μάλιστα δ’ ἄν τις ἐπιτιμήσειε περὶ τοῦτο τὸ μέρος Θεοπόμπῳ, ὅς γ’ ἐν ἀρχῇ τῆς Φιλίππου συντάξεως δι’ αὐτὸ μάλιστα παρορμηθῆναι φήσας πρὸς τὴν ἐπιβολὴν τῆς πραγματείας διὰ τὸ μηδέποτε τὴν Εὐρώπην ἐνηνοχέναι τοιοῦτον ἄνδρα παράπαν οἷον τὸν Ἀμύντου Φίλιππον, μετὰ ταῦτα παρὰ πόδας, ἔν τε τῷ προοιμίῳ καὶ παρ’ ὅλην δὲ τὴν ἱστορίαν, ἀκρατέστατον μὲν αὐτὸν ἀποδείκνυσι πρὸς γυναῖκας, ὥστε καὶ τὸν ἴδιον οἶκον ἐσφαλκέναι τὸ καθ’ αὑτὸν διὰ τὴν πρὸς τοῦτο τὸ μέρος ὁρμὴν καὶ προστασίαν, ἀδικώτατον δὲ καὶ κακοπραγμονέστατον περὶ τὰς τῶν φίλων καὶ συμμάχων κατασκευάς, πλείστας δὲ πόλεις ἐξηνδραποδισμένον καὶ πεπραξικοπηκότα μετὰ δόλου καὶ βίας, ἐκπαθῆ δὲ γεγονότα καὶ πρὸς τὰς ἀκρατοποσίας, ὥστε καὶ μεθ’ ἡμέραν πλεονάκις μεθύοντα καταφανῆ γενέσθαι τοῖς φίλοις. εἰ δέ τις ἀναγνῶναι βουληθείη τὴν ἀρχὴν τῆς ἐνάτης καὶ τετταρακοστῆς αὐτῷ βύβλου, παντάπασιν ἂν θαυμάσαι τὴν ἀτοπίαν τοῦ συγγραφέως, ὅς γε χωρὶς τῶν ἄλλων τετόλμηκε καὶ ταῦτα λέγειν· αὐταῖς γὰρ λέξεσιν, αἷς ἐκεῖνος κέχρηται, κατατετάχαμεν· \" εἰ γάρ τις ἦν ἐν τοῖς Ἕλλησιν ἢ τοῖς βαρβάροις\" φησί \"λάσταυρος ἢ θρασὺς τὸν τρόπον, οὗτοι πάντες εἰς Μακεδονίαν ἁθροιζόμενοι πρὸς Φίλιππον ἑταῖροι τοῦ βασιλέως προσηγορεύοντο. καθόλου γὰρ ὁ Φίλιππος τοὺς μὲν κοσμίους τοῖς ἤθεσι καὶ τῶν ἰδίων βίων ἐπιμελουμένους ἀπεδοκίμαζε, τοὺς δὲ πολυτελεῖς καὶ ζῶντας ἐν μέθαις καὶ κύβοις ἐτίμα καὶ προῆγε. τοιγαροῦν οὐ μόνον ταῦτ’ ἔχειν αὐτοὺς παρεσκεύαζεν, ἀλλὰ καὶ τῆς ἄλλης ἀδικίας καὶ βδελυρίας ἀθλητὰς ἐποίησε. τί γὰρ τῶν αἰσχρῶν ἢ δεινῶν αὐτοῖς οὐ προσῆν; ἢ τί τῶν καλῶν καὶ σπουδαίων οὐκ ἀπῆν; ὧν οἱ μὲν ξυρόμενοι καὶ λεαινόμενοι διετέλουν ἄνδρες ὄντες, οἱ δ’ ἀλλήλοις ἐτόλμων ἐπανίστασθαι πώγωνας ἔχουσι. καὶ περιήγοντο μὲν δύο καὶ τρεῖς τοὺς ἑταιρευομένους, αὐτοὶ δὲ τὰς αὐτὰς ἐκείνοις χρήσεις ἑτέροις παρείχοντο. ὅθεν καὶ δικαίως ἄν τις αὐτοὺς οὐχ ἑταίρους, ἀλλ’ ἑταίρας ὑπελάμβανεν [εἶναι] οὐδὲ στρατιώτας, ἀλλὰ χαμαιτύπους προσηγόρευσεν· ἀνδροφόνοι γὰρ τὴν φύσιν ὄντες ἀνδρόπορνοι τὸν τρόπον ἦσαν. ἁπλῶς δ’ εἰπεῖν, ἵνα παύσωμαι\" φησί \"μακρολογῶν, ἄλλως τε καὶ τοσούτων μοι πραγμάτων ἐπικεχυμένων, ἡγοῦμαι τοιαῦτα θηρία γεγονέναι καὶ τοιούτους τὸν τρόπον τοὺς φίλους καὶ τοὺς ἑταίρους Φιλίππου προσαγορευθέντας οἵους οὔτε τοὺς Κενταύρους τοὺς τὸ Πήλιον κατασχόντας οὔτε τοὺς Λαιστρυγόνας τοὺς τὸ Λεοντίνων πεδίον οἰκήσαντας οὔτ’ ἄλλους οὐδ’ ὁποίους.\"", "st": "8.11"}, {"sp": "N", "t": "ταύτην δὲ τήν τε πικρίαν καὶ τὴν ἀθυρογλωττίαν τοῦ συγγραφέως τίς οὐκ ἂν ἀποδοκιμάσειεν; οὐ γὰρ μόνον ὅτι μαχόμενα λέγει πρὸς τὴν αὑτοῦ πρόθεσιν ἄξιός ἐστιν ἐπιτιμήσεως, ἀλλὰ καὶ διότι κατέψευσται τοῦ τε βασιλέως καὶ τῶν φίλων, καὶ μάλιστα διότι τὸ ψεῦδος αἰσχρῶς καὶ ἀπρεπῶς διατέθειται. εἰ γὰρ περὶ Σαρδαναπάλλου τις ἢ τῶν ἐκείνου συμβιωτῶν ἐποιεῖτο τοὺς λόγους, μόλις ἂν ἐθάρρησε τῇ κακορρημοσύνῃ ταύτῃ χρήσασθαι· οὗ τὴν ἐν τῷ βίῳ προαίρεσιν καὶ τὴν ἀσέλγειαν διὰ τῆς ἐπιγραφῆς τῆς ἐπὶ τοῦ τάφου τεκμαιρόμεθα. λέγει γὰρ ἡ [ἐπι]γραφή, ταῦτ’ ἔχω ὅσσ’ ἔφαγον καὶ ἐφύβρισα καὶ μετ’ ἔρωτος τέρπν’ ἔπαθον. περὶ δὲ Φιλίππου καὶ τῶν ἐκείνου φίλων εὐλαβηθείη τις ἂν οὐχ οἷον εἰς μαλακίαν καὶ ἀνανδρίαν, ἔτι δ’ ἀναισχυντίαν λέγειν, ἀλλὰ τοὐναντίον μήποτ’ ἐγκωμιάζειν ἐπιβαλλόμενος οὐ δυνηθῇ καταξίως εἰπεῖν τῆς ἀνδρείας καὶ φιλοπονίας καὶ συλλήβδην τῆς ἀρετῆς τῶν προειρημένων ἀνδρῶν· οἵ γε προφανῶς ταῖς σφετέραις φιλοπονίαις καὶ τόλμαις ἐξ ἐλαχίστης μὲν βασιλείας ἐνδοξοτάτην καὶ μεγίστην τὴν Μακεδόνων ἀρχὴν κατεσκεύασαν· χωρὶς δὲ τῶν ἐπὶ Φιλίππου πράξεων αἱ μετὰ τὸν ἐκείνου θάνατον ἐπιτελεσθεῖσαι μετ’ Ἀλεξάνδρου πᾶσιν ὁμολογουμένην τὴν ἐπ’ ἀρετῇ φήμην παραδεδώκασι περὶ αὐτῶν. μεγάλην γὰρ ἴσως μερίδα θετέον τῷ προεστῶτι τῶν ὅλων Ἀλεξάνδρῳ, καίπερ ὄντι νέῳ παντελῶς, οὐκ ἐλάττω μέντοι γε τοῖς συνεργοῖς καὶ φίλοις, οἳ πολλαῖς μὲν καὶ παραδόξοις μάχαις ἐνίκησαν τοὺς ὑπεναντίους, πολλοὺς δὲ καὶ παραβόλους ὑπέμειναν πόνους καὶ κινδύνους καὶ ταλαιπωρίας, πλείστης δὲ περιουσίας κυριεύσαντες καὶ πρὸς ἁπάσας τὰς ἐπιθυμίας πλείστης εὐπορήσαντες ἀπολαύσεως, οὔτε κατὰ τὴν σωματικὴν δύναμιν οὐδέποτε διὰ ταῦτ’ ἠλαττώθησαν, οὔτε κατὰ τὰς ψυχικὰς ὁρμὰς οὐδὲν ἄδικον οὐδ’ ἀσελγὲς ἐπετήδευσαν, ἅπαντες δ’, ὡς ἔπος εἰπεῖν, βασιλικοὶ καὶ ταῖς μεγαλοψυχίαις καὶ ταῖς σωφροσύναις καὶ ταῖς τόλμαις ἀπέβησαν, Φιλίππῳ καὶ μετ’ Ἀλεξάνδρῳ συμβιώσαντες. ὧν οὐδὲν ἂν δέοι μνημονεύειν ἐπ’ ὀνόματος. μετὰ δὲ τὸν Ἀλεξάνδρου θάνατον οὕτω περὶ τῶν πλείστων μερῶν τῆς οἰκουμένης ἀμφισβητήσαντες παραδόσιμον ἐποίησαν τὴν ἑαυτῶν δόξαν ἐν πλείστοις ὑπομνήμασιν ὥστε τὴν μὲν Τιμαίου τοῦ συγγραφέως πικρίαν, ᾗ κέχρηται κατ’ Ἀγαθοκλέους τοῦ Σικελίας δυνάστου, καίπερ ἀνυπέρβλητον εἶναι δοκοῦσαν, ὅμως λόγον ἔχειν — ὡς γὰρ κατ’ ἐχθροῦ καὶ πονηροῦ καὶ τυράννου διατίθεται τὴν κατηγορίαν — τὴν δὲ Θεοπόμπου μηδ’ ὑπὸ λόγον πίπτειν.", "st": "8.12"}, {"sp": "N", "t": "προθέμενος γὰρ ὡς περὶ βασιλέως εὐφυεστάτου πρὸς ἀρετὴν γεγονότος οὐκ ἔστι τῶν αἰσχρῶν καὶ δεινῶν ὃ παραλέλοιπε. λοιπὸν ἢ περὶ τὴν ἀρχὴν καὶ προέκθεσιν τῆς πραγματείας ἀνάγκη ψεύστην καὶ κόλακα φαίνεσθαι τὸν ἱστοριογράφον, ἢ περὶ τὰς κατὰ μέρος ἀποφάσεις ἀνόητον καὶ μειρακιώδη τελείως, εἰ διὰ τῆς ἀλόγου καὶ ἐπικλήτου λοιδορίας ὑπέλαβε πιστότερος μὲν αὐτὸς φανήσεσθαι, παραδοχῆς δὲ μᾶλλον ἀξιωθήσεσθαι τὰς ἐγκωμιαστικὰς ἀποφάσεις αὐτοῦ περὶ Φιλίππου. καὶ μὴν οὐδὲ περὶ τὰς ὁλοσχερεῖς διαλήψεις οὐδεὶς ἂν εὐδοκήσειε τῷ προειρημένῳ συγγραφεῖ· ὅς γ’ ἐπιβαλόμενος γράφειν τὰς Ἑλληνικὰς πράξεις ἀφ’ ὧν Θουκυδίδης ἀπέλιπε, καὶ συνεγγίσας τοῖς Λευκτρικοῖς καιροῖς καὶ τοῖς ἐπιφανεστάτοις τῶν Ἑλληνικῶν ἔργων, τὴν μὲν Ἑλλάδα μεταξὺ καὶ τὰς ταύτης ἐπιβολὰς ἀπέρριψε, μεταλαβὼν δὲ τὴν ὑπόθεσιν τὰς Φιλίππου πράξεις προύθετο γράφειν. καίτοι γε πολλῷ σεμνότερον ἦν καὶ δικαιότερον ἐν τῇ περὶ τῆς Ἑλλάδος ὑποθέσει τὰ πεπραγμένα Φιλίππῳ συμπεριλαβεῖν ἤπερ ἐν τῇ Φιλίππου τὰ τῆς Ἑλλάδος. οὐδὲ γὰρ προκαταληφθεὶς ὑπὸ βασιλικῆς δυναστείας, καὶ τυχὼν ἐξουσίας, οὐδεὶς ἂν ἐπέσχε σὺν καιρῷ ποιήσασθαι μετάβασιν ἐπὶ τὸ τῆς Ἑλλάδος ὄνομα καὶ πρόσωπον· ἀπὸ δὲ ταύτης ἀρξάμενος καὶ προβὰς ἐπὶ ποσὸν οὐδ’ ὅλως οὐδεὶς ἂν ἠλλάξατο μονάρχου πρόσχημα καὶ βίον, ἀκεραίῳ χρώμενος γνώμῃ. καὶ τί δήποτ’ ἦν τὸ τὰς τηλικαύτας ἐναντιώσεις βιασάμενον παριδεῖν Θεόπομπον; εἰ μὴ νὴ Δί’ ὅτι ἐκείνης μὲν τῆς ὑποθέσεως τέλος ἦν τὸ καλόν, τῆς δὲ κατὰ Φίλιππον τὸ συμφέρον. οὐ μὴν ἀλλὰ πρὸς μὲν ταύτην τὴν ἁμαρτίαν, καθὸ μετέβαλε τὴν ὑπόθεσιν, ἴσως ἂν εἶχέ τι λέγειν, εἴ τις αὐτὸν ἤρετο περὶ τούτων· πρὸς δὲ τὴν κατὰ τῶν φίλων αἰσχρολογίαν οὐκ ἂν οἶμαι δυνηθῆναι λόγον αὐτὸν ἀποδοῦναι, συγχωρῆσαι δὲ διότι πολύ τι παρέπεσε τοῦ καθήκοντος.", "st": "8.13"}, {"sp": "N", "t": "Φίλιππος δὲ τοὺς μὲν Μεσσηνίους πολεμίους γεγονότας οὐδὲν ἄξιον ἠδυνήθη λόγου βλάψαι, καίπερ ἐπιβαλόμενος κακοποιεῖν αὐτῶν τὴν χώραν, εἰς δὲ τοὺς ἀναγκαιοτάτους τῶν φίλων τὴν μεγίστην ἀσέλγειαν ἐναπεδείξατο. τὸν γὰρ πρεσβύτερον Ἄρατον, δυσαρεστηθέντα τοῖς ὑπ’ αὐτοῦ πεπραγμένοις ἐν τῇ Μεσσήνῃ, μετ’ οὐ πολὺ μετὰ Ταυρίωνος τοῦ χειρίζοντος αὐτῷ τὰ κατὰ Πελοπόννησον ἐπανείλατο φαρμάκῳ. παραυτίκα μὲν οὖν ἠγνοεῖτο παρὰ τοῖς ἐκτὸς τὸ γεγονός· καὶ γὰρ ἦν ἡ δύναμις οὐ τῶν παρ’ αὐτὸν τὸν καιρὸν ἀπολλυουσῶν, ἀλλὰ χρόνον ἔχουσα καὶ διάθεσιν ἐργαζομένη· τόν γε μὴν Ἄρατον αὐτὸν οὐκ ἐλάνθανε τὸ κακόν. ἐγένετο δὲ δῆλον ἐκ τούτων· ἅπαντας γὰρ ἐπικρυπτόμενος τοὺς ἄλλους, πρὸς ἕνα τῶν ὑπηρετῶν Κεφάλωνα διὰ τὴν συνήθειαν οὐκ ἔστεξε τὸν λόγον, ἀλλ’ ἐπιμελῶς αὐτῷ κατὰ τὴν ἀρρωστίαν τοῦ προειρημένου συμπαρόντος καί τι τῶν πρὸς τῷ τοίχῳ πτυσμάτων ἐπισημηναμένου δίαιμον ὑπάρχον, εἶπε \"ταῦτα τἀπίχειρα τῆς φιλίας, ὦ Κεφάλων, κεκομίσμεθα τῆς πρὸς Φίλιππον\". οὕτως ἐστὶ μέγα τι καὶ καλὸν χρῆμα μετριότης, ὥστε μᾶλλον ὁ παθὼν τοῦ πράξαντος ᾐσχύνετο τὸ γεγονός, εἰ τοσούτων καὶ τηλικούτων κεκοινωνηκὼς ἔργων ἐπὶ τῷ τοῦ Φιλίππου συμφέροντι τοιαῦτα τἀπίχειρα κεκόμισται τῆς εὐνοίας. οὗτος μὲν οὖν καὶ διὰ τὸ πολλάκις τῆς ἀρχῆς τετευχέναι παρὰ τοῖς Ἀχαιοῖς, καὶ διὰ τὸ πλῆθος καὶ διὰ τὸ μέγεθος τῶν εἰς τὸ ἔθνος εὐεργεσιῶν, μεταλλάξας τὸν βίον ἔτυχε πρεπούσης τιμῆς καὶ παρὰ τῇ πατρίδι καὶ παρὰ τῷ κοινῷ τῶν Ἀχαιῶν· καὶ γὰρ θυσίας αὐτῷ καὶ τιμὰς ἡρωικὰς ἐψηφίσαντο, καὶ συλλήβδην ὅσα πρὸς αἰώνιον ἀνήκει μνήμην, ὥστ’ εἴπερ καὶ περὶ τοὺς ἀποιχομένους ἔστι τις αἴσθησις, εἰκὸς εὐδοκεῖν αὐτὸν καὶ τῇ τῶν Ἀχαιῶν εὐχαριστίᾳ καὶ ταῖς ἐν τῷ ζῆν κακοπραγίαις καὶ κινδύνοις.", "st": "8.14"}, {"sp": "N", "t": "πάλαι δὲ τῇ διανοίᾳ περὶ τὸν Λίσσον καὶ τὸν Ἀκρόλισσον ὤν, καὶ σπουδάζων ἐγκρατὴς γενέσθαι τῶν τόπων τούτων, ὥρμησε μετὰ τῆς δυνάμεως· ποιησάμενος δὲ τὴν πορείαν ἐπὶ δύ’ ἡμέρας, καὶ διελθὼν τὰ στενά, κατέζευξε παρὰ τὸν Ἀρδάξανον ποταμόν, οὐ μακρὰν τῆς πόλεως. θεωρῶν δὲ τόν τε τοῦ Λίσσου περίβολον καὶ τὰ πρὸς τῇ θαλάττῃ καὶ τὰ πρὸς τὴν μεσόγαιον ἠσφαλισμένον διαφερόντως καὶ φύσει καὶ κατασκευῇ, τόν τε παρακείμενον Ἀκρόλισσον αὐτῷ καὶ διὰ τὴν εἰς ὕψος ἀνάτασιν καὶ διὰ τὴν ἄλλην ἐρυμνότητα τοιαύτην ἔχοντα φαντασίαν ὥστε μηδ’ ἂν ἐλπίσαι μηδένα κατὰ κράτος ἑλεῖν, τῆς μὲν περὶ τοῦτον ἐλπίδος ἀπέστη τελέως, τῆς δὲ πόλεως οὐ λίαν ἀπήλπισε. συνθεωρήσας δὲ τὸ μεταξὺ διάστημα τοῦ Λίσσου καὶ τοῦ κατὰ τὸν Ἀκρόλισσον πρόποδος σύμμετρον ὑπάρχον πρὸς τὴν ἐπιβολὴν τὴν κατὰ τῆς πόλεως, κατὰ τοῦτο διενοήθη συστησάμενος ἀκροβολισμὸν χρήσασθαι στρατηγήματι πρὸς τὸ παρὸν οἰκείῳ. δοὺς δὲ μίαν ἡμέραν πρὸς ἀνάπαυσιν τοῖς Μακεδόσι, καὶ παρακαλέσας ἐν αὐτῇ τὰ πρέποντα τῷ καιρῷ, τὸ μὲν πολὺ μέρος καὶ χρησιμώτατον τῶν εὐζώνων ἔτι νυκτὸς εἴς τινας φάραγγας ὑλώδεις ἔκρυψε κατὰ τὸν ἐπὶ τῆς μεσογαίου τόπον ὑπὲρ τὸ προειρημένον διάστημα, τοὺς δὲ πελταστὰς εἰς τὴν ἐπαύριον ἔχων καὶ τὸ λοιπὸν μέρος τῶν εὐζώνων ἐπὶ θάτερα τῆς πόλεως κατὰ θάλατταν ἐχρῆτο τῇ πορείᾳ. περιελθὼν δὲ τὴν πόλιν, καὶ γενόμενος κατὰ τὸν προειρημένον τόπον, δῆλος ἦν ὡς ταύτῃ ποιησόμενος τὴν πρὸς τὴν πόλιν ἀνάβασιν. οὐκ ἀγνοουμένης δὲ τῆς τοῦ Φιλίππου παρουσίας ἦν πλῆθος ἱκανὸν ἐξ ἁπάσης τῆς πέριξ Ἰλλυρίδος εἰς τὸν Λίσσον ἡθροισμένον· τῷ μὲν γὰρ Ἀκρολίσσῳ διὰ τὴν ὀχυρότητα πιστεύοντες μετρίαν τινὰ τελέως εἰς αὐτὸν ἀπένειμαν φυλακήν.", "st": "8.15"}, {"sp": "N", "t": "διόπερ ἅμα τῷ συνεγγίζειν τοὺς Μακεδόνας εὐθέως ἐκ τῆς πόλεως ἐξεχέοντο, θαρροῦντες ἐπί τε τῷ πλήθει καὶ ταῖς τῶν τόπων ὀχυρότησι. τοὺς μὲν οὖν πελταστὰς ὁ βασιλεὺς ἐν τοῖς ἐπιπέδοις ἐπέστησε, τοῖς δὲ κούφοις παρήγγειλε προβαίνειν πρὸς τοὺς λόφους καὶ συμπλέκεσθαι πρὸς τοὺς πολεμίους ἐρρωμένως. ποιούντων δὲ τὸ παραγγελθέν, ἐπὶ ποσὸν μὲν ὁ κίνδυνος πάρισος ἦν μετὰ δὲ ταῦτα καὶ ταῖς δυσχωρίαις εἴξαντες οἱ παρὰ τοῦ Φιλίππου καὶ τῷ πλήθει τῶν πολεμίων ἐτράπησαν. καταφυγόντων δὲ τούτων εἰς τοὺς πελταστὰς οἱ μὲν ἐκ τῆς πόλεως καταφρονήσαντες προῄεσαν καὶ συγκαταβάντες ἐν τοῖς ἐπιπέδοις προσεμάχοντο τοῖς πελτασταῖς· οἱ δὲ τὸν Ἀκρόλισσον φυλάττοντες, θεωροῦντες τὸν Φίλιππον ἐκ διαδοχῆς ταῖς σπείραις ἐπὶ πόδα ποιούμενον τὴν ἀναχώρησιν, καὶ δόξαντες τοῖς ὅλοις αὐτὸν εἴκειν, ἔλαθον ἐκκληθέντες διὰ τὸ πιστεύειν τῇ φύσει τοῦ τόπου, κἄπειτα κατ’ ὀλίγους ἐκλιπόντες τὸν Ἀκρόλισσον κατέρρεον ταῖς ἀνοδίαις εἰς τοὺς ὁμαλοὺς καὶ πεδινοὺς τόπους, ὡς ἤδη τινὸς ὠφελείας καὶ τροπῆς τῶν πολεμίων ἐσομένης. κατὰ δὲ τὸν καιρὸν τοῦτον οἱ τὰς ἐνέδρας ἐκ τῆς μεσογαίας διειληφότες ἀφανῶς ἐξαναστάντες ἐνεργὸν ἐποιήσαντο τὴν ἔφοδον· ἅμα δὲ τούτοις ἐκ μεταβολῆς οἱ πελτασταὶ συνεπέθεντο τοῖς ὑπεναντίοις. οὗ συμβάντος διαταραχθέντες οἱ μὲν ἐκ τοῦ Λίσσου σποράδην ποιούμενοι τὴν ἀναχώρησιν διεσῴζοντο πρὸς τὴν πόλιν, οἱ δὲ τὸν Ἀκρόλισσον ἐκλιπόντες ἀπετμήθησαν ὑπὸ τῶν ἐκ τῆς ἐνέδρας ἐξαναστάντων. διὸ καὶ συνέβη τὸ μὲν ἀνέλπιστον, τὸν Ἀκρόλισσον παραχρῆμα ληφθῆναι χωρὶς κινδύνων, τὸν δὲ Λίσσον τῇ κατὰ πόδας ἡμέρᾳ μετὰ μεγάλων ἀγώνων, ποιησαμένων τῶν Μακεδόνων ἐνεργοὺς καὶ καταπληκτικὰς προσβολάς. Φίλιππος μὲν οὖν, παραδόξως ἐγκρατὴς γενόμενος τῶν προειρημένων τόπων, ἅπαντας τοὺς πέριξ ὑποχειρίους ἐποιήσατο διὰ ταύτης τῆς πράξεως, ὥστε τοὺς πλείστους τῶν Ἰλλυριῶν ἐθελοντὴν ἐπιτρέπειν αὐτῷ τὰς πόλεις· οὐδεμία γὰρ ὀχυρότης ἔτι πρὸς τὴν Φιλίππου βίαν οὐδ’ ἀσφάλεια τοῖς ἀντιταττομένοις προυφαίνετο, κεκρατημένων μετὰ βίας τῶν προειρημένων ὀχυρωμάτων.", "st": "8.16"}, {"sp": "N", "t": "Δασσαρῆται ἔθνος Ἰλλυρίας· Πολύβιος ὀγδόῳ. Ὕσκανα πόλις Ἰλλυρίδος οὐδετέρως· Πολύβιος ηʹ.", "st": "8.14b"}, {"sp": "N", "t": "Βῶλις ἦν ἀνὴρ γένει μὲν Κρής, χρόνον δὲ πολὺν ἐν τῇ βασιλείᾳ διατετριφὼς ἐν ἡγεμονικῇ προστασίᾳ, δοκῶν δὲ καὶ σύνεσιν ἔχειν καὶ τόλμαν παράβολον καὶ τριβὴν ἐν τοῖς πολεμικοῖς οὐδενὸς ἐλάττω. τοῦτον ὁ Σωσίβιος διὰ πλειόνων λόγων πιστωσάμενος, καὶ παρασκευάσας εὔνουν ἑαυτῷ καὶ πρόθυμον, ἀναδίδωσι τὴν πρᾶξιν, λέγων ὡς οὐδὲν ἂν τῷ βασιλεῖ μεῖζον χαρίσαιτο κατὰ τοὺς ἐνεστῶτας καιροὺς ἢ συνεπινοήσας πῶς καὶ τίνι τρόπῳ δύναται σῶσαι τὸν Ἀχαιόν. τότε μὲν οὖν διακούσας ὁ Βῶλις, καὶ φήσας ἐπισκέψασθαι περὶ τῶν εἰρημένων, ἐχωρίσθη· δοὺς δὲ λόγον ἑαυτῷ, καὶ μετὰ δύ’ ἢ τρεῖς ἡμέρας προσελθὼν πρὸς τὸν Σωσίβιον, ἀνεδέξατο τὴν πρᾶξιν εἰς αὑτόν, φήσας καὶ γεγονέναι πλείω χρόνον ἐν ταῖς Σάρδεσι καὶ τῶν τόπων ἐμπειρεῖν, καὶ τὸν Καμβύλον τὸν ἡγεμόνα τῶν παρ’ Ἀντιόχῳ στρατευομένων Κρητῶν οὐ μόνον πολίτην, ἀλλὰ καὶ συγγενῆ καὶ φίλον ὑπάρχειν αὑτῷ. συνέβαινε δὲ καὶ τὸν Καμβύλον καὶ τοὺς ὑπὸ τοῦτον ταττομένους Κρῆτας πεπιστεῦσθαί τι τῶν φυλακτηρίων τῶν κατὰ τοὺς ὄπισθε τόπους τῆς ἄκρας, οἵτινες κατασκευὴν μὲν οὐκ ἐπεδέχοντο, τῇ δὲ συνεχείᾳ τῶν ὑπὸ τὸν Καμβύλον τεταγμένων ἀνδρῶν ἐτηροῦντο. τοῦ δὲ Σωσιβίου δεξαμένου τὴν ἐπίνοιαν, καὶ διειληφότος ἢ μὴ δυνατὸν εἶναι σωθῆναι τὸν Ἀχαιὸν ἐκ τῶν περιεστώτων, ἢ δυνατοῦ καθάπαξ ὑπάρχοντος διὰ μηδενὸς ἂν ἑτέρου γενέσθαι τοῦτο βέλτιον ἢ διὰ Βώλιδος, τοιαύτης δὲ συνδραμούσης καὶ περὶ τὸν Βῶλιν προθυμίας, ταχέως ἐλάμβανε τὸ πρᾶγμα προκοπήν. ὅ τε γὰρ Σωσίβιος ἅμα μὲν προεδίδου τῶν χρημάτων εἰς τὸ μηδὲν ἐλλείπειν εἰς τὰς ἐπιβολάς, πολλὰ δ’ εὖ γενομένων ὑπισχνεῖτο δώσειν, τὰς δὲ παρ’ αὐτοῦ τοῦ βασιλέως καὶ παρ’ Ἀχαιοῦ τοῦ σῳζομένου χάριτας ἐξ ὑπερβολῆς αὔξων εἰς μεγάλας ἐλπίδας ἦγε τὸν Βῶλιν· ὅ τε προειρημένος ἀνήρ, ἕτοιμος ὢν πρὸς τὴν πρᾶξιν, οὐδένα χρόνον ἐπιμείνας ἐξέπλευσε, συνθήματα λαβὼν καὶ πίστεις πρός τε Νικόμαχον εἰς Ῥόδον, ὃς ἐδόκει πατρὸς ἔχειν διάθεσιν κατὰ τὴν εὔνοιαν καὶ πίστιν πρὸς τὸν Ἀχαιόν, ὁμοίως δὲ καὶ πρὸς Μελαγκόμαν εἰς Ἔφεσον. οὗτοι γὰρ ἦσαν, δι’ ὧν καὶ τὸν πρὸ τοῦ χρόνον Ἀχαιὸς τά τε πρὸς τὸν Πτολεμαῖον καὶ τὰς ἄλλας ἁπάσας τὰς ἔξωθεν ἐπιβολὰς ἐχείριζε.", "st": "8.17"}, {"sp": "N", "t": "παραγενόμενος δ’ εἰς τὴν Ῥόδον καὶ μετὰ ταῦτα πάλιν εἰς τὴν Ἔφεσον, καὶ κοινωσάμενος τοῖς προειρημένοις ἀνδράσι, καὶ λαβὼν αὐτοὺς ἑτοίμους εἰς τὰ παρακαλούμενα, μετὰ ταῦτ’ Ἀριανόν τινα τῶν ὑφ’ αὑτὸν ταττομένων διαπέμπεται πρὸς τὸν Καμβύλον, φήσας ἐξαπεστάλθαι μὲν ἐκ τῆς Ἀλεξανδρείας ξενολογήσων, βούλεσθαι δὲ τῷ Καμβύλῳ συμμῖξαι περί τινων ἀναγκαίων· διόπερ ᾤετο δεῖν τάξασθαι καιρὸν καὶ τόπον, ἐν ᾧ μηδενὸς συνειδότος αὑτοῖς συναντήσουσι. ταχὺ δὲ τοῦ Ἀριανοῦ συμμίξαντος τῷ Καμβύλῳ καὶ δηλώσαντος τὰς ἐντολάς, ἑτοίμως ὁ προειρημένος ἀνὴρ ὑπήκουσε τοῖς παρακαλουμένοις, καὶ συνθέμενος ἡμέραν καὶ τόπον ἑκατέρῳ γνωστόν, εἰς ὃν παρέσται νυκτός, ἀπέπεμψε τὸν Ἀριανόν. ὁ δὲ Βῶλις, ἅτε Κρὴς ὑπάρχων καὶ φύσει ποικίλος, πᾶν ἐβάσταζε πρᾶγμα καὶ πᾶσαν ἐπίνοιαν ἐψηλάφα. τέλος δὲ συμμίξας τῷ Καμβύλῳ κατὰ τὴν τοῦ Ἀριανοῦ σύνταξιν ἔδωκε τὴν ἐπιστολήν. ἧς τεθείσης εἰς τὸ μέσον ἐποιοῦντο τὴν σκέψιν Κρητικήν· οὐ γὰρ ἐσκόπουν ὑπὲρ τῆς τοῦ κινδυνεύοντος σωτηρίας οὐδ’ ὑπὲρ τῆς τῶν ἐγχειρισάντων τὴν πρᾶξιν πίστεως, ἀλλ’ ὑπὲρ τῆς αὑτῶν ἀσφαλείας καὶ τοῦ σφίσιν αὐτοῖς συμφέροντος. διόπερ ἀμφότεροι Κρῆτες ὄντες συντόμως κατηνέχθησαν ἐπὶ τὴν αὐτὴν γνώμην· αὕτη δ’ ἦν τὰ μὲν παρὰ τοῦ Σωσιβίου προδεδομένα δέκα τάλαντα διελέσθαι κοινῇ, τὴν δὲ πρᾶξιν Ἀντιόχῳ δηλώσαντας καὶ συνεργῷ χρησαμένους ἐπαγγείλασθαι τὸν Ἀχαιὸν ἐγχειριεῖν αὐτῷ, λαβόντας χρήματα καὶ τὰς εἰς τὸ μέλλον ἐλπίδας ἀξίας τῆς προειρημένης ἐπιβολῆς. τούτων δὲ κυρωθέντων ὁ μὲν Καμβύλος ἀνεδέξατο χειριεῖν τὰ κατὰ τὸν Ἀντίοχον, ὁ δὲ Βῶλις ἐτάξατο μετά τινας ἡμέρας πέμψειν τὸν Ἀριανὸν πρὸς τὸν Ἀχαιόν, ἔχοντα παρά τε τοῦ Νικομάχου καὶ Μελαγκόμα συνθηματικὰ γράμματα. περὶ δὲ τοῦ παρεισελθεῖν τὸν Ἀριανὸν εἰς τὴν ἄκραν ἀσφαλῶς καὶ πάλιν ἀπελθεῖν, ἐκεῖνον ἐκέλευε φροντίζειν. ἐὰν δὲ προσδεξάμενος τὴν ἐπιβολὴν Ἀχαιὸς ἀντιφωνήσῃ τοῖς περὶ τὸν Νικόμαχον καὶ Μελαγκόμαν, οὕτως ἔφη δώσειν ὁ Βῶλις αὑτὸν εἰς τὴν χρείαν καὶ συμμίξειν τῷ Καμβύλῳ. τῆς δὲ διατάξεως γενομένης τοιαύτης χωρισθέντες ἔπραττον ἑκάτεροι τὰ συντεταγμένα.", "st": "8.18"}, {"sp": "N", "t": "καὶ λαβὼν καιρὸν πρῶτον ὁ Καμβύλος προσφέρει τῷ βασιλεῖ τὸν λόγον. ὁ δ’ Ἀντίοχος, πρὸς τρόπον αὐτῷ καὶ παραδόξου γενομένης τῆς ἐπαγγελίας, τὰ μὲν ὑπερχαρὴς ὢν πάνθ’ ὑπισχνεῖτο, τὰ δὲ διαπιστῶν ἐξήταζε τὰς κατὰ μέρος ἐπινοίας καὶ παρασκευὰς αὐτῶν. μετὰ δὲ ταῦτα πιστεύσας, καὶ νομίζων ὡς ἂν εἰ σὺν θεῷ γίνεσθαι τὴν ἐπιβολήν, ἠξίου καὶ πολλάκις ἐδεῖτο τοῦ Καμβύλου συντελεῖν τὴν πρᾶξιν. τὸ δὲ παραπλήσιον ὁ Βῶλις ἐποίει πρὸς τὸν Νικόμαχον καὶ Μελαγκόμαν. οἱ δὲ πιστεύοντες ἀπὸ τοῦ κρατίστου γίνεσθαι τὴν ἐπιβολήν, καὶ παραυτίκα τῷ Ἀριανῷ συνθέντες τὰς πρὸς τὸν Ἀχαιὸν ἐπιστολὰς γεγραμμένας συνθηματικῶς, καθάπερ ἔθος ἦν αὐτοῖς, οὕτως ὥστε τὸν κυριεύσαντα τῆς ἐπιστολῆς μὴ δύνασθαι γνῶναι μηδὲν τῶν ἐν αὐτῇ γεγραμμένων, ἐξαπέστειλαν παρακαλοῦντες πιστεύειν τοῖς περὶ τὸν Βῶλιν καὶ τὸν Καμβύλον. ὁ δ’ Ἀριανὸς διὰ τοῦ Καμβύλου παρελθὼν εἰς τὴν ἄκραν τὰ γεγραμμένα τοῖς περὶ τὸν Ἀχαιὸν ἀπέδωκε, καὶ συμπαρὼν ἀπὸ τῆς ἀρχῆς τοῖς γινομένοις ἀκριβῶς τὸν κατὰ μέρος ὑπὲρ ἑκάστων ἀπεδίδου λόγον, πολλάκις μὲν καὶ ποικίλως ὑπὲρ τῶν κατὰ τὸν Σωσίβιον καὶ Βῶλιν ἀνακρινόμενος, πολλάκις δὲ περὶ Νικομάχου καὶ Μελαγκόμα, μάλιστα δὲ περὶ τῶν κατὰ τὸν Καμβύλον. οὐ μὴν ἀλλ’ αὐτοπαθῶς καὶ γενναίως ὑπέμενε τοὺς ἐλέγχους, καὶ μάλιστα διὰ τὸ μὴ γινώσκειν τὸ συνέχον τῶν τῷ Καμβύλῳ καὶ Βώλιδι δεδογμένων. Ἀχαιὸς δὲ καὶ διὰ τῶν ἀνακρίσεων τῶν τοῦ Ἀριανοῦ καὶ μάλιστα διὰ τῶν παρὰ τοῦ Νικομάχου καὶ Μελαγκόμα συνθημάτων πιστεύσας ἀντεφώνησε, καὶ παραχρῆμα πάλιν ἐξέπεμψε τὸν Ἀριανόν. πλεονάκις δὲ τούτου γινομένου παρ’ ἑκατέρων, τέλος οἱ περὶ τὸν Ἀχαιὸν ἐπέτρεψαν περὶ σφῶν τοῖς περὶ τὸν Νικόμαχον, ἅτε μηδεμιᾶς ἄλλης ἐλπίδος ἔτι καταλειπομένης πρὸς σωτηρίαν, καὶ πέμπειν ἐκέλευον ἅμα τῷ Ἀριανῷ τὸν Βῶλιν ἀσελήνου νυκτός, ὡς ἐγχειριοῦντες αὑτούς. ἦν γάρ τις ἐπίνοια περὶ τὸν Ἀχαιὸν τοιαύτη, πρῶτον μὲν διαφυγεῖν τοὺς ἐνεστῶτας κινδύνους, μετὰ δὲ ταῦτα ποιήσασθαι δίχα προόδου τὴν ὁρμὴν ἐπὶ τοὺς κατὰ Συρίαν τόπους· πάνυ γὰρ εἶχε μεγάλας ἐλπίδας ἐπιφανεὶς ἄφνω καὶ παραδόξως τοῖς κατὰ Συρίαν ἀνθρώποις, καὶ ἔτι διατρίβοντος Ἀντιόχου περὶ τὰς Σάρδεις, μέγα ποιήσειν κίνημα καὶ μεγάλης ἀποδοχῆς τεύξεσθαι παρά τε τοῖς Ἀντιοχεῦσι καὶ τοῖς κατὰ Κοίλην Συρίαν καὶ Φοινίκην.", "st": "8.19"}, {"sp": "N", "t": "ὁ μὲν οὖν Ἀχαιὸς ἐπί τινος τοιαύτης προσδοκίας καὶ διαλογισμῶν ὑπάρχων ἐκαραδόκει τὴν παρουσίαν τοῦ Βώλιδος· οἱ δὲ περὶ τὸν Μελαγκόμαν ἀποδεξάμενοι τὸν Ἀριανὸν καὶ τὰς ἐπιστολὰς ἀναγνόντες, ἐξέπεμπον τὸν Βῶλιν, παρακαλέσαντες διὰ πλειόνων καὶ μεγάλας ἐλπίδας ὑποδείξαντες, ἐὰν καθίκηται τῆς ἐπιβολῆς. ὁ δὲ προδιαπεμψάμενος τὸν Ἀριανόν, καὶ δηλώσας τῷ Καμβύλῳ τὴν αὑτοῦ παρουσίαν, ἧκε νυκτὸς ἐπὶ τὸν συντεθέντα τόπον. γενόμενοι δὲ μίαν ἡμέραν ἐπὶ ταὐτό, καὶ συνταξάμενοι περὶ τοῦ πῶς χειρισθήσεται τὰ κατὰ μέρος, μετὰ ταῦτα νυκτὸς εἰσῆλθον εἰς τὴν παρεμβολήν. ἡ δὲ διάταξις αὐτῶν ἐγεγόνει τοιαύτη τις· εἰ μὲν συμβαίη τὸν Ἀχαιὸν ἐκ τῆς ἄκρας ἐλθεῖν μόνον ἢ καὶ δεύτερον μετὰ τοῦ Βώλιδος καὶ Ἀριανοῦ, τελέως εὐκαταφρόνητος, ἔτι δ’ εὐχείρωτος ἔμελλε γίνεσθαι τοῖς ἐνεδρεύουσιν· εἰ δὲ μετὰ πλειόνων, δύσχρηστος ἡ πρόθεσις ἀπέβαινε τοῖς πεπιστευμένοις, ἄλλως τε καὶ ζωγρίᾳ σπεύδουσι κυριεῦσαι διὰ τὸ τῆς πρὸς τὸν Ἀντίοχον χάριτος τὸ πλεῖστον ἐν τούτῳ κεῖσθαι τῷ μέρει. διόπερ ἔδει τὸν μὲν Ἀριανόν, ὅταν ἐξάγῃ τὸν Ἀχαιόν, ἡγεῖσθαι διὰ τὸ γινώσκειν τὴν ἀτραπόν, ᾗ πολλάκις ἐπεποίητο καὶ τὴν εἴσοδον καὶ τὴν ἔξοδον, τὸν δὲ Βῶλιν ἀκολουθεῖν τῶν ἄλλων κατόπιν, ἵν’ ἐπειδὰν παραγένηται πρὸς τὸν τόπον, ἐν ᾧ τοὺς ἐνεδρεύοντας ἑτοίμους ὑπάρχειν ἔδει διὰ τοῦ Καμβύλου, τότ’ ἐπιλαβόμενος κρατοίη τὸν Ἀχαιόν, καὶ μήτε διαδραίη κατὰ τὸν θόρυβον νυκτὸς οὔσης διὰ τόπων ὑλωδῶν, μήθ’ αὑτὸν ῥίψαι κατά τινος κρημνοῦ περιπαθὴς γενόμενος, πέσοι δὲ κατὰ τὴν πρόθεσιν ὑπὸ τὰς τῶν ἐχθρῶν χεῖρας ζωγρίᾳ. τούτων δὲ συγκειμένων, καὶ παραγενομένου τοῦ Βώλιδος ὡς τὸν Καμβύλον, ᾗ μὲν ἦλθε νυκτί, ταύτῃ παράγει πρὸς τὸν Ἀντίοχον τὸν Βῶλιν ὁ Καμβύλος μόνος πρὸς μόνον. ἀποδεξαμένου δὲ τοῦ βασιλέως φιλοφρόνως, καὶ δόντος πίστεις ὑπὲρ τῶν ἐπαγγελιῶν, καὶ παρακαλέσαντος ἀμφοτέρους διὰ πλειόνων μηκέτι μέλλειν ὑπὲρ τῶν προκειμένων, τότε μὲν ἀνεχώρησαν εἰς τὴν αὑτῶν παρεμβολήν, ὑπὸ δὲ τὴν ἑωθινὴν Βῶλις ἀνέβη μετὰ τοῦ Ἀριανοῦ, καὶ παρεισῆλθεν ἔτι νυκτὸς εἰς τὴν ἄκραν.", "st": "8.20"}, {"sp": "N", "t": "Ἀχαιὸς δὲ προσδεξάμενος ἐκτενῶς καὶ φιλοφρόνως τὸν Βῶλιν ἀνέκρινε διὰ πλειόνων ὑπὲρ ἑκάστου τῶν κατὰ μέρος. θεωρῶν δὲ καὶ κατὰ τὴν ἐπιφάνειαν τὸν ἄνδρα καὶ κατὰ τὴν ὁμιλίαν ἕλκοντα τὸ τῆς πράξεως στάσιμον, τὰ μὲν περιχαρὴς ἦν διὰ τὴν ἐλπίδα τῆς σωτηρίας, τὰ δὲ πάλιν ἐπτοημένος καὶ πλήρης ἀγωνίας διὰ τὸ μέγεθος τῶν ἀποβησομένων. ὑπάρχων δὲ καὶ κατὰ τὴν διάνοιαν οὐδενὸς ἥττων καὶ κατὰ τὴν ἐν πράγμασι τριβὴν ἱκανός, ὅμως ἀκμὴν ἔκρινε μὴ πᾶσαν εἰς τὸν Βῶλιν ἀνακρεμάσαι τὴν πίστιν. διὸ ποιεῖται τοιούτους λόγους πρὸς αὐτόν, ὅτι κατὰ μὲν τὸ παρὸν οὐκ ἔστι δυνατὸν ἐξελθεῖν αὐτῷ, πέμψει δέ τινας τῶν φίλων μετ’ ἐκείνου τρεῖς ἢ τέτταρας, ὧν συμμιξάντων τοῖς περὶ τὸν Μελαγκόμαν ἕτοιμον αὑτὸν ἔφη παρασκευάσειν πρὸς τὴν ἔξοδον. ὁ μὲν οὖν Ἀχαιὸς ἐποίει τὰ δυνατά· τοῦτο δ’ ἠγνόει, τὸ δὴ λεγόμενον, πρὸς Κρῆτα κρητίζων· ὁ γὰρ Βῶλις οὐθὲν ἀψηλάφητον εἶχε τῶν ἐπινοηθέντων ἂν εἰς τοῦτο τὸ μέρος. πλὴν παραγενομένης τῆς νυκτός, ἐν ᾗ συνεξαποστέλλειν ἔφη τοὺς φίλους, προπέμψας τὸν Ἀριανὸν καὶ τὸν Βῶλιν ἐπὶ τὴν τῆς ἄκρας ἔξοδον μένειν προσέταξε, μέχρις ἂν οἱ μέλλοντες αὐτοῖς συνεξορμᾶν παραγένωνται. τῶν δὲ πειθαρχησάντων, κοινωσάμενος παρ’ αὐτὸν τὸν καιρὸν τῇ γυναικὶ καὶ ποιήσας διὰ τὸ παράδοξον τὴν Λαοδίκην ἔκφρονα, χρόνον μέν τινα λιπαρῶν ταύτην καὶ καταπραΰνων ταῖς προσδοκωμέναις ἐλπίσι προσεκαρτέρει, μετὰ δὲ ταῦτα πέμπτος αὐτὸς γενόμενος, καὶ τοῖς μὲν ἄλλοις μετρίας ἐσθῆτας ἀναδούς, αὐτὸς δὲ λιτὴν καὶ τὴν τυχοῦσαν ἀναλαβὼν καὶ ταπεινὸν αὑτὸν ποιήσας προῆγε, συντάξας ἑνὶ τῶν φίλων αὐτὸν αἰὲν ἀποκρίνασθαι πρὸς τὸ λεγόμενον ὑπὸ τῶν περὶ τὸν Ἀριανὸν καὶ πυνθάνεσθαι παρ’ ἐκείνων ἀεὶ τὸ κατεπεῖγον, περὶ δὲ τῶν ἄλλων φάναι βαρβάρους αὐτοὺς ὑπάρχειν.", "st": "8.21"}, {"sp": "N", "t": "ἐπεὶ δὲ συνέμιξαν τοῖς περὶ τὸν Ἀριανόν, ἡγεῖτο μὲν αὐτὸς αὐτῶν διὰ τὴν ἐμπειρίαν, ὁ δὲ Βῶλις κατόπιν ἐπέστη κατὰ τὴν ἐξ ἀρχῆς πρόθεσιν, ἀπορῶν καὶ δυσχρηστούμενος ὑπὲρ τοῦ συμβαίνοντος· καίπερ γὰρ ὢν Κρὴς καὶ πᾶν ἄν τι κατὰ τοῦ πέλας ὑποπτεύσας, ὅμως οὐκ ἠδύνατο διὰ τὸ σκότος συννοῆσαι τὸν Ἀχαιόν, οὐχ οἷον τίς ἐστιν, ἀλλ’ οὐδὲ καθάπαξ εἰ πάρεστι. τῆς δὲ καταβάσεως κρημνώδους μὲν καὶ δυσβάτου κατὰ τὸ πλεῖστον ὑπαρχούσης, ἔν τισι δὲ τόποις καὶ λίαν ἐπισφαλεῖς ἐχούσης καὶ κινδυνώδεις καταφοράς, ὁπότε παραγένοιτο πρός τινα τοιοῦτον τόπον, τῶν μὲν ἐπιλαμβανομένων, τῶν δὲ πάλιν ἐκδεχομένων τὸν Ἀχαιόν, οὐ δυναμένων γὰρ καθόλου τὴν ἐκ τῆς συνηθείας καταξίωσιν στέλλεσθαι πρὸς τὸν παρόντα καιρόν, ταχέως ὁ Βῶλις συνῆκε τίς ἐστι καὶ ποῖος αὐτῶν ὁ Ἀχαιός. ἐπεὶ δὲ παρεγένοντο πρὸς τὸν τῷ Καμβύλῳ διατεταγμένον τόπον, καὶ τὸ σύνθημα προσσυρίξας ὁ Βῶλις ἀπέδωκε, τῶν μὲν ἄλλων οἱ διαναστάντες ἐκ τῆς ἐνέδρας ἐπελάβοντο, τὸν δ’ Ἀχαιὸν αὐτὸς ὁ Βῶλις ὁμοῦ τοῖς ἱματίοις, ἔνδον τὰς χεῖρας ἔχοντα, συνήρπασε, φοβηθεὶς μὴ συννοήσας τὸ γινόμενον ἐπιβάλοιτο διαφθείρειν αὑτόν· καὶ γὰρ εἶχε μάχαιραν ἐφ’ αὑτῷ παρεσκευασμένος. ταχὺ δὲ καὶ πανταχόθεν κυκλωθεὶς ὑποχείριος ἐγένετο τοῖς ἐχθροῖς, καὶ παραχρῆμα μετὰ τῶν φίλων ἀνήγετο πρὸς τὸν Ἀντίοχον. ὁ δὲ βασιλεύς, πάλαι μετέωρος ὢν τῇ διανοίᾳ καὶ καραδοκῶν τὸ συμβησόμενον, ἀπολύσας τοὺς ἐκ τῆς συνουσίας ἔμενε μόνος ἐγρηγορὼς ἐν τῇ σκηνῇ μετὰ δυεῖν ἢ τριῶν σωματοφυλάκων. παρεισελθόντων δὲ τῶν περὶ τὸν Καμβύλον καὶ καθισάντων τὸν Ἀχαιὸν ἐπὶ τὴν γῆν δεδεμένον, εἰς τοιαύτην ἀφασίαν ἦλθε διὰ τὸ παράδοξον ὥστε πολὺν μὲν χρόνον ἀποσιωπῆσαι, τὸ δὲ τελευταῖον συμπαθὴς γενέσθαι καὶ δακρῦσαι. τοῦτο δ’ ἔπαθεν ὁρῶν, ὡς ἔμοιγε δοκεῖ, τὸ δυσφύλακτον καὶ παράλογον τῶν ἐκ τῆς τύχης συμβαινόντων. Ἀχαιὸς γὰρ ἦν Ἀνδρομάχου μὲν υἱὸς τοῦ Λαοδίκης ἀδελφοῦ τῆς Σελεύκου γυναικός, ἔγημε δὲ Λαοδίκην τὴν Μιθριδάτου τοῦ βασιλέως θυγατέρα, κύριος δ’ ἐγεγόνει τῆς ἐπὶ τάδε τοῦ Ταύρου πάσης. δοκῶν δὲ τότε καὶ ταῖς αὑτοῦ δυνάμεσι καὶ ταῖς τῶν ὑπεναντίων ἐν ὀχυρωτάτῳ τόπῳ τῆς οἰκουμένης διατρίβειν, ἐκάθητο δεδεμένος ἐπὶ τῆς γῆς, ὑποχείριος γενόμενος τοῖς ἐχθροῖς, οὐδέπω γινώσκοντος οὐθενὸς ἁπλῶς τὸ γεγονὸς πλὴν τῶν πραξάντων.", "st": "8.22"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ ἅμα τῷ φωτὶ συναθροιζομένων τῶν φίλων εἰς τὴν σκηνὴν κατὰ τὸν ἐθισμόν, καὶ τοῦ πράγματος ὑπὸ τὴν ὄψιν θεωρουμένου, τὸ παραπλήσιον τῷ βασιλεῖ συνέβαινε πάσχειν καὶ τοὺς ἄλλους· θαυμάζοντες γὰρ τὸ γεγονὸς ἠπίστουν τοῖς ὁρωμένοις. καθίσαντος δὲ τοῦ συνεδρίου, πολλοὶ μὲν ἐγίνοντο λόγοι περὶ τοῦ τίσι δεῖ κατ’ αὐτοῦ χρήσασθαι τιμωρίαις· ἔδοξε δ’ οὖν πρῶτον μὲν ἀκρωτηριάσαι τὸν ταλαίπωρον, μετὰ δὲ ταῦτα τὴν κεφαλὴν ἀποτεμόντας αὐτοῦ καὶ καταρράψαντας εἰς ὄνειον ἀσκὸν ἀνασταυρῶσαι τὸ σῶμα. γενομένων δὲ τούτων, καὶ τῆς δυνάμεως ἐπιγνούσης τὸ συμβεβηκός, τοιοῦτος ἐνθουσιασμὸς ἐγένετο καὶ παράστασις τοῦ στρατοπέδου παντὸς ὥστε τὴν Λαοδίκην ἐκ τῆς ἄκρας μόνον συνειδυῖαν τὴν ἔξοδον τἀνδρός, τεκμήρασθαι τὸ γεγονὸς ἐκ τῆς περὶ τὸ στρατόπεδον ταραχῆς καὶ κινήσεως. ταχὺ δὲ καὶ τοῦ κήρυκος παραγενομένου πρὸς τὴν Λαοδίκην καὶ διασαφοῦντος τὰ περὶ τὸν Ἀχαιόν, καὶ κελεύοντος τίθεσθαι τὰ πράγματα καὶ παραχωρεῖν τῆς ἄκρας, τὸ μὲν πρῶτον ἀναπόκριτος οἰμωγὴ καὶ θρῆνοι παράλογοι κατεῖχον τοὺς περὶ τὴν ἀκρόπολιν, οὐχ οὕτως διὰ τὴν πρὸς τὸν Ἀχαιὸν εὔνοιαν ὡς διὰ τὸ παράδοξον καὶ τελέως ἀνέλπιστον ἑκάστῳ φαίνεσθαι τὸ συμβεβηκός, μετὰ δὲ ταῦτα πολλή τις ἦν ἀπορία καὶ δυσχρηστία περὶ τοὺς ἔνδον. Ἀντίοχος δὲ διακεχειρισμένος τὸν Ἀχαιὸν ἐπεῖχε τοῖς κατὰ τὴν ἄκραν ἀεί, πεπεισμένος ἀφορμὴν ἐκ τῶν ἔνδον αὑτῷ παραδοθήσεσθαι, καὶ μάλιστα διὰ τῶν στρατιωτῶν. ὃ καὶ τέλος ἐγένετο· στασιάσαντες γὰρ πρὸς σφᾶς ἐμερίσθησαν, οἱ μὲν πρὸς Ἀρίβαζον, οἱ δὲ πρὸς τὴν Λαοδίκην. οὗ γενομένου διαπιστήσαντες ἀλλήλοις ταχέως ἀμφότεροι παρέδοσαν αὑτοὺς καὶ τὰς ἀκροπόλεις. Ἀχαιὸς μὲν οὖν πάντα τὰ κατὰ λόγον πράξας, ὑπὸ δὲ τῆς τῶν πιστευθέντων ἡττηθεὶς ἀθεσίας, κατεστρέψατο τὸν βίον, κατὰ δύο τρόπους οὐκ ἀνωφελὲς ὑπόδειγμα γενόμενος τοῖς ἐπεσομένοις, καθ’ ἕνα μὲν πρὸς τὸ μηδενὶ πιστεύειν ῥᾳδίως, καθ’ ἕτερον δὲ πρὸς τὸ μὴ μεγαλαυχεῖν ἐν ταῖς εὐπραγίαις, πᾶν δὲ προσδοκᾶν ἀνθρώπους ὄντας.", "st": "8.23"}, {"sp": "N", "t": "ὅτι Καύαρος ὁ βασιλεὺς τῶν ἐν τῇ Θρᾴκῃ Γαλατῶν βασιλικὸς ὑπάρχων τῇ φύσει καὶ μεγαλόφρων, πολλὴν μὲν ἀσφάλειαν παρεσκεύαζε τοῖς προσπλέουσι τῶν ἐμπόρων εἰς τὸν Πόντον, μεγάλας δὲ παρείχετο χρείας τοῖς Βυζαντίοις ἐν τοῖς πρὸς τοὺς Θρᾷκας καὶ Βιθυνοὺς πολέμοις. Πολύβιος … ἐν ὀγδόῃ ἱστοριῶν, Καύαρος, φησίν, ὁ Γαλάτης, ὢν τἄλλα ἀνὴρ ἀγαθός, ὑπὸ Σωστράτου τοῦ κόλακος διεστρέφετο, ὃς ἦν Χαλκηδόνιος γένος.", "st": "8.24"}, {"sp": "N", "t": "ὅτι Ξέρξου βασιλεύοντος πόλεως Ἀρμόσατα, ἣ κεῖται πρὸς τῷ Καλῷ πεδίῳ καλουμένῳ, μέσον Εὐφράτου καὶ Τίγριδος, ταύτῃ τῇ πόλει παραστρατοπεδεύσας Ἀντίοχος ὁ βασιλεὺς ἐπεβάλετο πολιορκεῖν αὐτήν. θεωρῶν δὲ τὴν παρασκευὴν τοῦ βασιλέως ὁ Ξέρξης, τὸ μὲν πρῶτον αὑτὸν ἐκποδὼν ἐποίησε, μετὰ δέ τινα χρόνον δείσας μὴ τοῦ βασιλείου κρατηθέντος ὑπὸ τῶν ἐχθρῶν καὶ τἄλλα τὰ κατὰ τὴν ἀρχὴν αὐτῷ διατραπῇ, μετεμελήθη καὶ διεπέμψατο πρὸς τὸν Ἀντίοχον, φάσκων βούλεσθαι συνελθεῖν εἰς λόγους. οἱ μὲν οὖν πιστοὶ τῶν φίλων οὐκ ἔφασκον δεῖν προΐεσθαι τὸν νεανίσκον λαβόντες εἰς χεῖρας, ἀλλὰ συνεβούλευον κυριεύσαντα τῆς πόλεως Μιθριδάτῃ παραδοῦναι τὴν δυναστείαν, ὃς ἦν υἱὸς τῆς ἀδελφῆς αὐτοῦ κατὰ φύσιν. ὁ δὲ βασιλεὺς τούτων μὲν οὐδενὶ προσέσχε, μεταπεμψάμενος δὲ τὸν νεανίσκον διελύσατο τὴν ἔχθραν, ἀφῆκε δὲ τὰ πλεῖστα τῶν χρημάτων, ἃ συνέβαινε τὸν πατέρα προσοφείλειν αὐτῷ τῶν φόρων. λαβὼν δὲ παραχρῆμα τριακόσια τάλαντα παρ’ αὐτοῦ καὶ χιλίους ἵππους καὶ χιλίους ἡμιόνους μετὰ τῆς ἐπισκευῆς τά τε κατὰ τὴν ἀρχὴν ἅπαντ’ ἀποκατέστησε, καὶ συνοικίσας αὐτῷ τὴν ἀδελφὴν Ἀντιοχίδα πάντας τοὺς ἐκείνων τῶν τόπων ἐψυχαγώγησε καὶ προσεκαλέσατο, δόξας μεγαλοψύχως καὶ βασιλικῶς τοῖς πράγμασι κεχρῆσθαι.", "st": "8.25"}, {"sp": "N", "t": "ὅτι οἱ Ταραντῖνοι διὰ τὸ τῆς εὐδαιμονίας ὑπερήφανον ἐπεκαλέσαντο Πύρρον τὸν Ἠπειρώτην· πᾶσα γὰρ ἐλευθερία μετ’ ἐξουσίας πολυχρονίου φύσιν ἔχει κόρον λαμβάνειν τῶν ὑποκειμένων, κἄπειτα ζητεῖ δεσπότην· τυχοῦσά γε μὴν τούτου ταχὺ πάλιν μισεῖ διὰ τὸ μεγάλην φαίνεσθαι τὴν πρὸς τὸ χεῖρον μεταβολήν· ὃ καὶ τότε συνέβαινε τοῖς Ταραντίνοις. ὅτι πᾶν τὸ μέλλον κρεῖττον φαίνεται τοῦ παρόντος ὑπάρχειν. προσπεσόντων δὲ τούτων εἰς Τάραντα καὶ τοὺς Θουρίους, ἠγανάκτει τὰ πλήθη. τὸ μὲν οὖν πρῶτον ὡς ἐπ’ ἐξοδείαν ὁρμήσαντες ἐκ τῆς πόλεως καὶ συνεγγίσαντες τῇ παρεμβολῇ τῶν Καρχηδονίων νυκτός, ἄλλοι μὲν συγκαθέντες εἴς τινα τόπον ὑλώδη παρὰ τὴν ὁδὸν ἔμειναν, ὁ δὲ Φιλήμενος καὶ Νίκων προσῆλθον πρὸς τὴν παρεμβολήν. τῶν δὲ φυλάκων ἐπιλαβομένων αὐτῶν, ἀνήγοντο πρὸς τὸν Ἀννίβαν, οὐδὲν εἰπόντες οὔτε πόθεν οὔτε τίνες ἦσαν, αὐτὸ δὲ μόνον τοῦτο δηλοῦντες ὅτι θέλουσι τῷ στρατηγῷ συμμῖξαι. ταχὺ δὲ πρὸς τὸν Ἀννίβαν ἐπαναχθέντες ἔφασαν αὐτῷ κατ’ ἰδίαν βούλεσθαι διαλεχθῆναι. τοῦ δὲ καὶ λίαν ἑτοίμως προσδεξαμένου τὴν ἔντευξιν, ἀπελογίζοντο περί τε τῶν καθ’ αὑτοὺς καὶ περὶ τῶν κατὰ τὴν πατρίδα, πολλὰς καὶ ποικίλας ποιούμενοι κατηγορίας Ῥωμαίων, χάριν τοῦ μὴ δοκεῖν ἀλόγως ἐμβαίνειν εἰς τὴν ὑποκειμένην πρᾶξιν. τότε μὲν οὖν Ἀννίβας ἐπαινέσας καὶ τὴν ὁρμὴν αὐτῶν φιλανθρώπως ἀποδεξάμενος ἐξέπεμψε, συνταξάμενος παραγίνεσθαι καὶ συμμιγνύναι κατὰ τάχος αὑτῷ πάλιν. κατὰ δὲ τὸ παρὸν ἐκέλευσε τὰ πρῶτα τῶν ἐξελασθέντων πρωῒ θρεμμάτων καὶ τοὺς ἅμα τούτοις ἄνδρας, ἐπειδὰν ἱκανὸν ἀπόσχωσι τῆς παρεμβολῆς, περιελασαμένους εὐθαρσῶς ἀπαλλάττεσθαι· περὶ γὰρ τῆς ἀσφαλείας αὑτῷ μελήσειν. ἐποίει δὲ τοῦτο βουλόμενος αὑτῷ μὲν ἀναστροφὴν δοῦναι πρὸς τὸ πολυπραγμονῆσαι τὰ κατὰ τοὺς νεανίσκους, ἐκείνοις δὲ πίστιν παρασκευάζειν πρὸς τοὺς πολίτας ὡς ἀπὸ τοῦ κρατίστου ποιουμένοις τὰς ἐπὶ τὰς λῃστείας ἐξόδους. πραξάντων δὲ τῶν περὶ τὸν Νίκωνα τὸ παραγγελθέν, ὁ μὲν Ἀννίβας περιχαρὴς ἦν διὰ τὸ μόλις ἀφορμῆς ἐπειλῆφθαι πρὸς τὴν προκειμένην ἐπιβολήν, οἱ δὲ περὶ τὸν Φιλήμενον ἔτι μᾶλλον παρώρμηντο πρὸς τὴν πρᾶξιν διὰ τὸ καὶ τὴν ἔντευξιν ἀσφαλῶς γεγονέναι καὶ τὸν Ἀννίβαν ηὑρηκέναι πρόθυμον, ἔτι δὲ τὴν τῆς λείας δαψίλειαν ἱκανὴν αὐτοῖς πίστιν παρεσκευακέναι πρὸς τοὺς ἰδίους. διότι τὰ μὲν ἀποδόμενοι, τὰ δ’ εὐωχούμενοι τῆς λείας, οὐ μόνον ἐπιστεύοντο παρὰ τοῖς Ταραντίνοις, ἀλλὰ καὶ ζηλωτὰς ἔσχον οὐκ ὀλίγους.", "st": "8.26"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα ποιησάμενοι δευτέραν ἔξοδον, καὶ παραπλησίως χειρίσαντες τὰ κατὰ μέρος, αὐτοί τε τοῖς περὶ τὸν Ἀννίβαν ἔδοσαν πίστεις καὶ παρ’ ἐκείνων ἔλαβον ἐπὶ τούτοις, ἐφ’ ᾧ Ταραντίνους ἐλευθερώσειν καὶ μήτε φόρους πράξεσθαι κατὰ μηδένα τρόπον μήτ’ ἄλλο μηδὲν ἐπιτάξειν Ταραντίνοις Καρχηδονίους, τὰς δὲ τῶν Ῥωμαίων οἰκίας καὶ καταλύσεις, ἐπειδὰν κρατήσωσι τῆς πόλεως, ἐξεῖναι Καρχηδονίοις διαρπάζειν. ἐποιήσαντο δὲ καὶ σύνθημα τοῦ παραδέχεσθαι σφᾶς τοὺς φύλακας ἑτοίμως εἰς τὴν παρεμβολήν, ὅτ’ ἔλθοιεν. ὧν γενομένων ἔλαβον ἐξουσίαν εἰς τὸ καὶ πλεονάκις συμμιγνύναι τοῖς περὶ τὸν Ἀννίβαν, ποτὲ μὲν ὡς ἐπ’ ἐξοδείαν, ποτὲ δὲ πάλιν ὡς ἐπὶ κυνηγίαν ποιούμενοι τὰς ἐκ τῆς πόλεως ἐξόδους. ταῦτα δὲ διαρμοσάμενοι πρὸς τὸ μέλλον, οἱ μὲν πλείους ἐπετήρουν τοὺς καιρούς, τὸν δὲ Φιλήμενον ἀπέταξαν ἐπὶ τὰς κυνηγίας· διὰ γὰρ τὴν ὑπερβάλλουσαν ἐπὶ τοῦτο τὸ μέρος ἐπιθυμίαν ἦν ὑπὲρ αὐτοῦ διάληψις ὡς οὐδὲν προυργιαίτερον ποιουμένου κατὰ τὸν βίον τοῦ κυνηγετεῖν. διὸ τούτῳ μὲν ἐπέτρεψαν ἐξιδιάσασθαι διὰ τῶν ἁλισκομένων θηρίων πρῶτον μὲν τὸν ἐπὶ τῆς πόλεως τεταγμένον Γάιον Λίβιον, δεύτερον δὲ τοὺς φυλάττοντας τὸν πυλῶνα τὸν ὑπὸ τὰς Τημενίδας προσαγορευομένας πύλας. ὃς παραλαβὼν τὴν πίστιν ταύτην, καὶ τὰ μὲν αὐτὸς κυνηγετῶν, τῶν δ’ ἑτοιμαζομένων αὐτῷ δι’ Ἀννίβου, συνεχῶς εἰσέφερε τῶν θηρίων, ὧν τὰ μὲν ἐδίδου τῷ Γαΐῳ, τὰ δὲ τοῖς ἐπὶ τοῦ πυλῶνος χάριν τοῦ τὴν ῥινοπύλην ἑτοίμως ἀνοίγειν αὐτῷ· τὸ γὰρ πλεῖον ἐποιεῖτο τὰς εἰσόδους καὶ τὰς ἐξόδους νυκτός, προφάσει μὲν χρώμενος τῷ φόβῳ τῶν πολεμίων, ἁρμοζόμενος δὲ πρὸς τὴν ὑποκειμένην πρόθεσιν. ἤδη δὲ κατεσκευασμένου τοιαύτην συνήθειαν τοῦ Φιλημένου πρὸς τοὺς ἐπὶ τῆς πύλης ὥστε μὴ διαπορεῖν τοὺς φυλάττοντας, ἀλλ’ ὁπότε προσεγγίσας τῷ τείχει προσσυρίξαι νυκτός, εὐθέως ἀνοίγεσθαι τὴν ῥινοπύλην αὐτῷ, τότε παρατηρήσαντες τὸν ἐπὶ τῆς πόλεως ἄρχοντα τῶν Ῥωμαίων, ἀφ’ ἡμέρας μέλλοντα γίνεσθαι μετὰ πλειόνων ἐν τῷ προσαγορευομένῳ Μουσείῳ σύνεγγυς τῆς ἀγορᾶς, ταύτην ἐτάξαντο τὴν ἡμέραν πρὸς τὸν Ἀννίβαν.", "st": "8.27"}, {"sp": "N", "t": "ὁ δὲ πάλαι μὲν ἐπεπόριστο σκῆψιν ὡς ἀρρωστῶν, χάριν τοῦ μὴ θαυμάζειν ἀκούοντας τοὺς Ῥωμαίους, ὡς καὶ πλείω χρόνον ἐπὶ τῶν αὐτῶν τόπων ποιεῖται τὴν διατριβήν· τότε δὲ καὶ μᾶλλον προσεποιεῖτο τὴν ἀρρωστίαν. ἀπεῖχε δὲ τῷ στρατοπέδῳ τριῶν ἡμερῶν ὁδὸν τοῦ Τάραντος. ἥκοντος δὲ τοῦ καιροῦ, παρεσκευακὼς ἔκ τε τῶν ἱππέων καὶ τῶν πεζῶν τοὺς διαφέροντας εὐκινησίᾳ καὶ τόλμῃ, περὶ μυρίους ὄντας τὸν ἀριθμόν, παρήγγειλε τεττάρων ἡμερῶν ἔχειν ἐφόδια. ποιησάμενος δὲ τὴν ἀναζυγὴν ὑπὸ τὴν ἑωθινὴν ἐχρῆτο τῇ πορείᾳ συντόνως. τῶν δὲ Νομαδικῶν ἱππέων εἰς ὀγδοήκοντα προχειρισάμενος ἐκέλευε προπορεύεσθαι τῆς δυνάμεως εἰς τριάκοντα σταδίους καὶ τοὺς παρὰ τὴν ὁδὸν τόπους ἐξ ἑκατέρου τοῦ μέρους ἐπιτρέχειν, ἵνα μηδεὶς κατοπτεύσῃ τὴν ὅλην δύναμιν, ἀλλ’ οἱ μὲν ὑποχείριοι γίνοιντο τῶν διεμπιπτόντων, οἱ δὲ διαφυγόντες ἀναγγέλλοιεν εἰς τὴν πόλιν, ὡς ἐπιδρομῆς οὔσης ἐκ τῶν Νομάδων. ἀποσχόντων δὲ τῶν Νομάδων ὡς ἑκατὸν εἴκοσι σταδίους, ἐδειπνοποιήσατο παρά τινα δυσσύνοπτον καὶ φαραγγώδη ποταμόν. καὶ συναθροίσας τοὺς ἡγεμόνας κυρίως μὲν οὐ διεσάφει τὴν ἐπιβολήν, ἁπλῶς δὲ παρεκάλει πρῶτον μὲν ἄνδρας ἀγαθοὺς γίνεσθαι πάντας, ὡς οὐδέποτε μειζόνων αὐτοῖς ἄθλων ὑποκειμένων, δεύτερον δὲ συνέχειν ἕκαστον τῇ πορείᾳ τοὺς ὑφ’ αὑτὸν ταττομένους καὶ πικρῶς ἐπιτιμᾶν τοῖς καθόλου παρεκβαίνουσιν ἐκ τῆς ἰδίας τάξεως, τελευταῖον δὲ προσέχειν τὸν νοῦν τοῖς παραγγελλομένοις καὶ μηδὲν ἰδιοπραγεῖν πάρεξ τῶν προσταττομένων. ταῦτ’ εἰπὼν καὶ διαφεὶς τοὺς ἡγεμόνας ἐκίνει τὴν πρωτοπορείαν, κνέφατος ἄρτι γενομένου, σπουδάζων συνάψαι τῷ τείχει περὶ μέσας νύκτας, καθηγεμόνα τὸν Φιλήμενον ἔχων καὶ παρεσκευακὼς ὗν ἄγριον αὐτῷ πρὸς τὴν διατεταγμένην χρείαν.", "st": "8.28"}, {"sp": "N", "t": "τῷ δὲ Γαΐῳ τῷ Λιβίῳ, γενομένῳ μετὰ τῶν συνήθων ἀφ’ ἡμέρας ἐν τῷ Μουσείῳ κατὰ τὴν τῶν νεανίσκων πρόληψιν, καὶ σχεδὸν ἤδη τοῦ πότου τὴν ἀκμαιοτάτην ἔχοντος διάθεσιν, προσαγγέλλεται περὶ δυσμὰς ἡλίου τοὺς Νομάδας ἐπιτρέχειν τὴν χώραν. ὁ δὲ πρὸς μὲν αὐτὸ τοῦτο διενοήθη, καὶ καλέσας τινὰς τῶν ἡγεμόνων συνέταξε τοὺς μὲν ἡμίσεις τῶν ἱππέων ἐξελθόντας ὑπὸ τὴν ἑωθινὴν κωλῦσαι τοὺς κακοποιοῦντας τὴν χώραν τῶν πολεμίων, τῆς γε μὴν ὅλης πράξεως διὰ ταῦτα καὶ μᾶλλον ἀνύποπτος ἦν. οἱ δὲ περὶ τὸν Νίκωνα καὶ Τραγίσκον, ἅμα τῷ σκότος γενέσθαι συναθροισθέντες ἐν τῇ πόλει πάντες, ἐτήρουν τὴν ἐπάνοδον τῶν περὶ τὸν Λίβιον. τῶν δὲ ταχέως ἐξαναστάντων διὰ τὸ γεγονέναι τὸν πότον ἀφ’ ἡμέρας, οἱ μὲν ἄλλοι πρός τινα τόπον ἀποστάντες ἔμενον, τινὲς δὲ τῶν νεανίσκων ἀπήντων τοῖς περὶ τὸν Γάιον, διακεχυμένοι καί τι καὶ προσπαίζοντες ἀλλήλοις, ὡς ἂν ὑποκρινόμενοι τοὺς ἐκ συνουσίας ἐπανάγοντας. ἔτι δὲ μᾶλλον ἠλλοιωμένων ὑπὸ τῆς μέθης τῶν περὶ τὸν Λίβιον, ἅμα τῷ συμμῖξαι γέλως ἐξ ἀμφοῖν ἦν καὶ παιδιὰ πρόχειρος. ἐπεὶ δὲ συνανακάμψαντες ἀποκατέστησαν αὐτὸν εἰς οἶκον, ὁ μὲν Γάιος ἀνεπαύετο μεθύων, ὡς εἰκός ἐστι τοὺς ἀφ’ ἡμέρας πίνοντας, οὐδὲν ἄτοπον οὐδὲ δυσχερὲς ἔχων ἐν τῇ διανοίᾳ, χαρᾶς δὲ πλήρης καὶ ῥᾳθυμίας. οἱ δὲ περὶ τὸν Νίκωνα καὶ Τραγίσκον ἐπεὶ συνέμιξαν τοῖς ἀπολελειμμένοις νεανίσκοις, διελόντες σφᾶς εἰς τρία μέρη παρεφύλαττον, διαλαβόντες τῆς ἀγορᾶς τὰς εὐκαιροτάτας εἰσβολάς, ἵνα μήτε τῶν ἔξωθεν προσπιπτόντων μηδὲν αὐτοὺς λανθάνῃ μήτε τῶν ἐν αὐτῇ τῇ πόλει γινομένων. ἐπέστησαν δὲ καὶ παρὰ τὴν οἰκίαν τοῦ Γαΐου, σαφῶς εἰδότες ὡς ἐὰν γίνηταί τις ὑπόνοια τοῦ μέλλοντος, ἐπὶ τὸν Λίβιον ἀνοισθήσεται πρῶτον, καὶ πᾶν τὸ πραττόμενον ἀπ’ ἐκείνου λήψεται τὴν ἀρχήν. ὡς δ’ αἱ μὲν ἀπὸ τῶν δείπνων ἐπάνοδοι καὶ συλλήβδην ὁ τοιοῦτος θόρυβος ἤδη παρῳχήκει, τῶν δὲ δημοτῶν ἡ πληθὺς κατακεκοίμητο, προύβαινε δὲ τὰ τῆς νυκτὸς καὶ τὰ τῆς ἐλπίδος ἀκέραια διέμενε, τότε συναθροισθέντες προῆγον ἐπὶ τὴν προκειμένην χρείαν.", "st": "8.29"}, {"sp": "N", "t": "τὰ δὲ συγκείμενα τοῖς νεανίσκοις ἦν πρὸς τοὺς Καρχηδονίους· τὸν μὲν Ἀννίβαν ἔδει συνάψαντα τῇ πόλει κατὰ τὴν ἀπὸ τῆς μεσογαίου, πρὸς ἕω δὲ κειμένην πλευράν, ὡς ἐπὶ τὰς Τημενίδας προσαγορευομένας πύλας, ἀνάψαι πῦρ ἐπὶ τοῦ τάφου, τοῦ παρὰ μέν τισιν Ὑακίνθου προσαγορευομένου, παρὰ δέ τισιν Ἀπόλλωνος Ὑακίνθου, τοὺς δὲ περὶ τὸν Τραγίσκον, ὅταν ἴδωσι τοῦτο γινόμενον, ἔνδοθεν ἀντιπυρσεῦσαι. τούτου δὲ συντελεσθέντος, σβέσαι τὸ πῦρ ἔδει τοὺς περὶ τὸν Ἀννίβαν καὶ βάδην ποιεῖσθαι τὴν πορείαν ὡς ἐπὶ τὴν πύλην. ὧν διατεταγμένων, οἱ μὲν νεανίσκοι διαπορευθέντες τὸν οἰκούμενον τόπον τῆς πόλεως ἧκον ἐπὶ τοὺς τάφους. τὸ γὰρ πρὸς ἕω μέρος τῆς τῶν Ταραντίνων πόλεως μνημάτων ἐστὶ πλῆρες, διὰ τὸ τοὺς τελευτήσαντας ἔτι καὶ νῦν θάπτεσθαι παρ’ αὐτοῖς πάντας ἐντὸς τῶν τειχῶν κατά τι λόγιον ἀρχαῖον. φασὶ γὰρ χρῆσαι τὸν θεὸν τοῖς Ταραντίνοις ἄμεινον καὶ λῷον ἔσεσθαί σφισι ποιουμένοις τὴν οἴκησιν μετὰ τῶν πλειόνων. τοὺς δὲ νομίσαντας ἂν οἰκῆσ’ οὕτως ἄριστα κατὰ τὸν χρησμόν, εἰ καὶ τοὺς μετηλλαχότας ἐντὸς τοῦ τείχους ἔχοιεν, διὰ ταῦτα θάπτειν ἔτι καὶ νῦν τοὺς μεταλλάξαντας ἐντὸς τῶν πυλῶν. οὐ μὴν ἀλλ’ οἵ γε προειρημένοι παραγενόμενοι πρὸς τὸν τοῦ Πυθιονίκου τάφον ἐκαραδόκουν τὸ μέλλον. συνεγγισάντων δὲ τῶν περὶ τὸν Ἀννίβαν καὶ πραξάντων τὸ συνταχθέν, ἅμα τῷ τὸ πῦρ ἰδεῖν οἱ περὶ τὸν Νίκωνα καὶ Τραγίσκον ἀναθαρρήσαντες ταῖς ψυχαῖς καὶ τὸν παρ’ αὑτῶν πυρσὸν ἀναδείξαντες, ἐπεὶ τὸ παρ’ ἐκείνων πῦρ πάλιν ἑώρων ἀποσβεννύμενον, ὥρμησαν ἐπὶ τὴν πύλην μετὰ δρόμου καὶ σπουδῆς, βουλόμενοι φθάσαι φονεύσαντες τοὺς ἐπὶ τοῦ πυλῶνος τεταγμένους, διὰ τὸ συγκεῖσθαι [καὶ] σχολῇ καὶ βάδην ποιεῖσθαι τὴν πορείαν τοὺς Καρχηδονίους. εὐροήσαντος δὲ τοῦ πράγματος, καὶ προκαταληφθέντων τῶν φυλαττόντων, οἱ μὲν ἐφόνευον τούτους, οἱ δὲ διέκοπτον τοὺς μοχλούς. ταχὺ δὲ τῶν πυλῶν ἀνοιχθεισῶν, πρὸς τὸν δέοντα καιρὸν ἧκον οἱ περὶ τὸν Ἀννίβαν, κεχρημένοι τῇ πορείᾳ συμμέτρως, ὥστε μηδεμίαν ἐπίστασιν γενέσθαι παρ’ ὁδὸν ἐπὶ τὴν πόλιν.", "st": "8.30"}, {"sp": "N", "t": "γενομένης δὲ τῆς εἰσόδου κατὰ τὴν πρόθεσιν ἀσφαλοῦς καὶ τελέως ἀθορύβου, δόξαντες ἠνύσθαι σφίσι τὸ πλεῖστον τῆς ἐπιβολῆς, λοιπὸν αὐτοὶ μὲν εὐθαρσῶς ἤδη προῆγον ἐπὶ τὴν ἀγορὰν κατὰ τὴν πλατεῖαν τὴν ἀπὸ τῆς Βαθείας ἀναφέρουσαν· τούς γε μὴν ἱππεῖς ἀπέλειπον ἐκτὸς τοῦ τείχους, ὄντας οὐκ ἐλάττους δισχιλίων, θέλοντες ἐφεδρείαν αὑτοῖς ὑπάρχειν ταύτην πρός τε τὰς ἔξωθεν ἐπιφανείας καὶ πρὸς τὰ παράλογα τῶν ἐν ταῖς τοιαύταις ἐπιβολαῖς συμβαινόντων. ἐγγίσαντες δὲ τοῖς περὶ τὴν ἀγορὰν τόποις τὴν μὲν δύναμιν ἐπέστησαν κατὰ πορείαν, αὐτοὶ δὲ καὶ τὸν Φιλήμενον ἐκαραδόκουν, δεδιότες πῶς σφίσι προχωρήσει καὶ τοῦτο τὸ μέρος τῆς ἐπιβολῆς. ὅτε γὰρ ἀνάψαντες τὸ πῦρ ἔμελλον πρὸς τὰς πύλας ὁρμᾶν, τότε καὶ τὸν Φιλήμενον, ἔχοντα τὸν ὗν ἐν φερέτρῳ καὶ Λίβυας ὡς εἰ χιλίους ἐξαπέστειλαν ἐπὶ τὴν παρακειμένην πύλην, βουλόμενοι κατὰ τὴν ἐξ ἀρχῆς πρόθεσιν μὴ ψιλῶς ἐκ μιᾶς ἐλπίδος ἐξηρτῆσθαι τὴν ἐπιβολὴν αὐτῶν, ἀλλ’ ἐκ πλειόνων. ὁ δὲ προειρημένος ἐγγίσας τῷ τείχει κατὰ τὸν ἐθισμὸν ἐπεὶ προσεσύριξε, παρῆν ὁ φύλαξ εὐθέως καταβαίνων πρὸς τὴν ῥινοπύλην. τοῦ δ’ εἰπόντος ἔξωθεν ἀνοίγειν ταχέως, ὅτι βαρύνονται· φέρουσι γὰρ ὗν ἄγριον· ἀσμένως ἀκούσας ὁ φύλαξ ἀνέῳξε μετὰ σπουδῆς, ἐλπίζων καὶ πρὸς αὑτόν τι διατείνειν τὴν εὐαγρίαν τῶν περὶ τὸν Φιλήμενον διὰ τὸ μερίτην ἀεὶ γίνεσθαι τῶν εἰσφερομένων. αὐτὸς μὲν οὖν ὁ προειρημένος τὴν πρώτην ἔχων χώραν τοῦ φορήματος εἰσῆλθε, καὶ σὺν αὐτῷ νομαδικὴν ἔχων διασκευὴν ἕτερος, ὡς εἷς τις ὢν τῶν ἀπὸ τῆς χώρας, μετὰ δὲ τοῦτον ἄλλοι δύο πάλιν οἱ φέροντες ἐκ τῶν ὄπισθεν τὸ θηρίον. ἐπεὶ δὲ τέτταρες ὄντες ἐντὸς ἐγένοντο τῆς ῥινοπύλης, τὸν μὲν ἀνοίξαντα θεώμενον ἀκάκως καὶ ψηλαφῶντα τὸν ὗν αὐτοῦ πατάξαντες ἀπέκτειναν, τοὺς δ’ ἑπομένους μὲν αὑτοῖς, προηγουμένους δὲ τῶν ἄλλων, Λίβυας, ὄντας εἰς τριάκοντα, σχολῇ καὶ μεθ’ ἡσυχίας παρῆκαν διὰ τῆς πυλίδος. γενομένου δὲ τούτου κατὰ τὸ συνεχὲς οἱ μὲν τοὺς μοχλοὺς διέκοπτον, οἱ δὲ τοὺς ἐπὶ τοῦ πυλῶνος ἐφόνευον, οἱ δὲ τοὺς ἔξω Λίβυας ἐκάλουν διὰ συνθημάτων. εἰσελθόντων δὲ καὶ τούτων ἀσφαλῶς, προῆγον ὡς ἐπὶ τὴν ἀγορὰν κατὰ τὸ συντεταγμένον. ἅμα δὲ τῷ συμμῖξαι καὶ τούτους, περιχαρὴς γενόμενος Ἀννίβας ἐπὶ τῷ κατὰ νοῦν αὐτῷ προχωρεῖν τὴν πρᾶξιν εἴχετο τῶν προκειμένων.", "st": "8.31"}, {"sp": "N", "t": "ἀπομερίσας δὲ τῶν Κελτῶν εἰς δισχιλίους, καὶ διελὼν εἰς τρία μέρη τούτους, συνέστησε τῶν νεανίσκων δύο πρὸς ἕκαστον μέρος τῶν χειριζόντων τὴν πρᾶξιν. ἀκολούθως δὲ καὶ τῶν παρ’ αὑτοῦ τινας ἡγεμόνων συνεξαπέστειλε, προστάξας διαλαβεῖν τῶν εἰς τὴν ἀγορὰν φερουσῶν ὁδῶν τὰς εὐκαιροτάτας. ὅταν δὲ τοῦτο πράξωσι, τοῖς μὲν ἐγχωρίοις νεανίσκοις ἐξαιρεῖσθαι παρήγγειλε καὶ σῴζειν τοὺς ἐντυγχάνοντας τῶν πολιτῶν, ἀναβοῶντας ἐκ πολλοῦ μένειν κατὰ χώραν Ταραντίνους, ὡς ὑπαρχούσης αὐτοῖς τῆς ἀσφαλείας, τοῖς δὲ παρὰ τῶν Καρχηδονίων καὶ τῶν Κελτῶν ἡγεμόσι κτείνειν διεκελεύσατο τοὺς ἐντυγχάνοντας τῶν Ῥωμαίων. οὗτοι μὲν οὖν χωρισθέντες ἀλλήλων ἔπραττον μετὰ ταῦτα τὸ προσταχθέν. τῆς δὲ τῶν πολεμίων εἰσόδου καταφανοῦς ἤδη γενομένης τοῖς Ταραντίνοις, πλήρης ἡ πόλις κραυγῆς ἐγίνετο καὶ ταραχῆς παρηλλαγμένης. ὁ μὲν οὖν Γάϊος, προσπεσούσης αὐτῷ τῆς εἰσόδου τῶν πολεμίων, συννοήσας ἀδύνατον αὑτὸν ὄντα διὰ τὴν μέθην, εὐθέως ἐξελθὼν ἐκ τῆς οἰκίας μετὰ τῶν οἰκετῶν καὶ παραγενόμενος ἐπὶ τὴν πύλην τὴν φέρουσαν ἐπὶ τὸν λιμένα, καὶ μετὰ ταῦτα τοῦ φύλακος ἀνοίξαντος αὐτῷ τὴν ῥινοπύλην, διαδὺς ταύτῃ καὶ λαβόμενος ἀκατίου τῶν ὁρμούντων, ἐμβὰς μετὰ τῶν οἰκετῶν εἰς τὴν ἄκραν παρεκομίσθη. κατὰ δὲ τὸν καιρὸν τοῦτον οἱ περὶ τὸν Φιλήμενον, ἡτοιμασμένοι σάλπιγγας Ῥωμαϊκὰς καί τινας τῶν αὐταῖς χρῆσθαι δυναμένων διὰ τὴν συνήθειαν, στάντες ἐπὶ τὸ θέατρον ἐσήμαινον. τῶν δὲ Ῥωμαίων βοηθούντων ἐν τοῖς ὅπλοις κατὰ τὸν ἐθισμὸν εἰς τὴν ἄκραν, ἐχώρει τὸ πρᾶγμα κατὰ τὴν πρόθεσιν τοῖς Καρχηδονίοις· παραγενόμενοι γὰρ ταῖς πλατείαις ἀτάκτως καὶ σποράδην οἱ μὲν εἰς τοὺς Καρχηδονίους ἐνέπιπτον, οἱ δ’ εἰς τοὺς Κελτούς· καὶ δὴ τῷ τοιούτῳ τρόπῳ φονευομένων αὐτῶν πολύ τι πλῆθος διεφθάρη. τῆς δ’ ἡμέρας ἐπιφαινομένης οἱ μὲν Ταραντῖνοι τὴν ἡσυχίαν εἶχον κατὰ τὰς οἰκήσεις, οὐδέπω δυνάμενοι τάξασθαι τὸ συμβαῖνον. διὰ μὲν γὰρ τὴν σάλπιγγα καὶ τὸ μηδὲν ἀδίκημα γίνεσθαι μηδ’ ἁρπαγὴν κατὰ τὴν πόλιν, ἔδοξαν ἐξ αὐτῶν τῶν Ῥωμαίων εἶναι τὸ κίνημα. τὸ δὲ πολλοὺς αὐτῶν ὁρᾶν πεφονευμένους ἐν ταῖς πλατείαις, καί τινας τῶν Γαλατῶν θεωρεῖσθαι σκυλεύοντας τοὺς τῶν Ῥωμαίων νεκρούς, ὑπέτρεχέ τις ἔννοια τῆς τῶν Καρχηδονίων παρουσίας.", "st": "8.32"}, {"sp": "N", "t": "ἤδη δὲ τοῦ μὲν Ἀννίβου παρεμβεβληκότος τὴν δύναμιν εἰς τὴν ἀγοράν, τῶν δὲ Ῥωμαίων ἀποκεχωρηκότων εἰς τὴν ἄκραν διὰ τὸ προκατεσχῆσθαι φρουρᾷ ταύτην ὑπ’ αὐτῶν, ὄντος δὲ φωτὸς εἰλικρινοῦς, ὁ μὲν Ἀννίβας ἐκήρυττε τοὺς Ταραντίνους ἄνευ τῶν ὅπλων ἁθροίζεσθαι πάντας εἰς τὴν ἀγοράν, οἱ δὲ νεανίσκοι περιπορευόμενοι τὴν πόλιν ἐβόων ἐπὶ τὴν ἐλευθερίαν, καὶ παρεκάλουν θαρρεῖν, ὡς ὑπὲρ ἐκείνων παρόντας τοὺς Καρχηδονίους. ὅσοι μὲν οὖν τῶν Ταραντίνων προκατείχοντο τῇ πρὸς τοὺς Ῥωμαίους εὐνοίᾳ, γνόντες ἀπεχώρουν εἰς τὴν ἄκραν· οἱ δὲ λοιποὶ κατὰ τὸ κήρυγμα συνηθροίζοντο χωρὶς τῶν ὅπλων, πρὸς οὓς Ἀννίβας φιλανθρώπους διελέχθη λόγους. τῶν δὲ Ταραντίνων ὁμοθυμαδὸν ἐπισημηναμένων ἕκαστα τῶν λεγομένων διὰ τὸ παράδοξον τῆς ἐλπίδος, τότε μὲν διαφῆκε τοὺς πολλούς, συντάξας ἕκαστον εἰς τὴν ἰδίαν οἰκίαν ἐπανελθόντας μετὰ σπουδῆς ἐπὶ τὴν θύραν ἐπιγράψαι ΤΑΡΑΝΤΙΝΟΥ. τῷ δ’ ἐπὶ τὴν Ῥωμαϊκὴν κατάλυσιν ἐπιγράψαντι ταὐτὸ τοῦτο θάνατον ὥρισε τὴν ζημίαν. αὐτὸς δὲ διελὼν τοὺς ἐπιτηδειοτάτους τῶν ἐπὶ τῶν πραγμάτων ἐφῆκε διαρπάζειν τὰς τῶν Ῥωμαίων οἰκίας, σύνθημα δοὺς πολεμίας νομίζειν τὰς ἀνεπιγράφους, τοὺς δὲ λοιποὺς συνέχων ἐν τάξει τούτοις ἐφέδρους.", "st": "8.33"}, {"sp": "N", "t": "πολλῶν δὲ καὶ παντοδαπῶν κατασκευασμάτων ἁθροισθέντων ἐκ τῆς διαρπαγῆς, καὶ γενομένης ὠφελείας τοῖς Καρχηδονίοις ἀξίας τῶν προσδοκωμένων ἐλπίδων, τότε μὲν ἐπὶ τῶν ὅπλων ηὐλίσθησαν, εἰς δὲ τὴν ἐπιοῦσαν ἡμέραν Ἀννίβας συνεδρεύσας μετὰ τῶν Ταραντίνων ἔκρινε διατειχίσαι τὴν πόλιν ἀπὸ τῆς ἄκρας, ἵνα μηδεὶς ἔτι φόβος ἐπικάθηται τοῖς Ταραντίνοις ἀπὸ τῶν κατεχόντων τὴν ἀκρόπολιν Ῥωμαίων. πρῶτον μὲν οὖν ἐπεβάλετο προθέσθαι χάρακα παράλληλον τῷ τείχει τῆς ἀκροπόλεως καὶ τῇ πρὸ τούτου τάφρῳ. σαφῶς δὲ γινώσκων οὐκ ἐάσοντας τοὺς ὑπεναντίους, ἀλλ’ ἐναποδειξομένους τῇδέ πῃ τὴν αὑτῶν δύναμιν, ἡτοίμασε χεῖρας ἐπιτηδειοτάτας, νομίζων πρὸς τὸ μέλλον οὐδὲν ἀναγκαιότερον εἶναι τοῦ καταπλήξασθαι μὲν τοὺς Ῥωμαίους, εὐθαρσεῖς δὲ ποιῆσαι τοὺς Ταραντίνους. ἅμα δὲ τῷ τίθεσθαι τὸν πρῶτον χάρακα θρασέως τῶν Ῥωμαίων καὶ τετολμηκότως ἐπιχειρούντων τοῖς ὑπεναντίοις, βραχὺ συμμίξας Ἀννίβας καὶ τὰς ὁρμὰς τῶν προειρημένων ἐκκαλεσάμενος, ἐπεὶ προέπεσον οἱ πλείους ἐκτὸς τῆς τάφρου, δοὺς παράγγελμα τοῖς αὑτοῦ προσέβαλε τοῖς πολεμίοις. γενομένης δὲ τῆς μάχης ἰσχυρᾶς, ὡς ἂν ἐν βραχεῖ χώρῳ καὶ περιτετειχισμένῳ τῆς συμπλοκῆς ἐπιτελουμένης, τὸ πέρας ἐκβιασθέντες ἐτράπησαν οἱ Ῥωμαῖοι. καὶ πολλοὶ μὲν ἔπεσον ἐν χειρῶν νόμῳ, τὸ δὲ πλεῖον αὐτῶν μέρος ἀπωθούμενον καὶ συγκρημνιζόμενον ἐν τῇ τάφρῳ διεφθάρη.", "st": "8.34"}, {"sp": "N", "t": "τότε μὲν οὖν Ἀννίβας προβαλόμενος ἀσφαλῶς τὸν χάρακα τὴν ἡσυχίαν ἔσχε, τῆς ἐπιβολῆς αὐτῷ κατὰ νοῦν κεχωρηκυίας. τοὺς μὲν γὰρ ὑπεναντίους συγκλείσας ἠνάγκασε μένειν ἐντὸς τοῦ τείχους, δεδιότας οὐ μόνον περὶ σφῶν, ἀλλὰ καὶ περὶ τῆς ἄκρας, τοῖς δὲ πολιτικοῖς τοιοῦτο παρέστησε θάρσος ὥστε καὶ χωρὶς τῶν Καρχηδονίων ἱκανοὺς αὑτοὺς ὑπολαμβάνειν ἔσεσθαι τοῖς Ῥωμαίοις. μετὰ δὲ ταῦτα μικρὸν ἀπὸ τοῦ χάρακος ἀποστήσας ὡς πρὸς τὴν πόλιν, τάφρον ἐποίει παράλληλον τῷ χάρακι καὶ τῷ τῆς ἄκρας τείχει· παρ’ ἣν ἐκ μεταβολῆς ἐπὶ τὸ πρὸς τῇ πόλει χεῖλος τοῦ χοὸς ἀνασωρευομένου, προσέτι δὲ καὶ χάρακος ἐπ’ αὐτῆς τεθέντος, οὐ πολὺ καταδεεστέραν τείχους συνέβαινε τὴν ἀσφάλειαν ἐξ αὐτῆς ἀποτελεῖσθαι. παρὰ δὲ ταύτην ἐντὸς ἔτι πρὸς τὴν πόλιν ἀπολιπὼν σύμμετρον διάστημα τεῖχος ἐπεβάλετο κατασκευάζειν, ἀρξάμενος ἀπὸ τῆς Σωτείρας ἕως εἰς τὴν Βαθεῖαν προσαγορευομένην, ὥστε καὶ χωρὶς ἀνδρῶν τὰς δι’ αὐτῶν τῶν κατασκευασμάτων ὀχυρότητας ἱκανὰς εἶναι τοῖς Ταραντίνοις τὴν ἀσφάλειαν παρασκευάζειν. ἀπολιπὼν δὲ τοὺς ἱκανοὺς καὶ τοὺς ἐπιτηδείους πρὸς τὴν τῆς πόλεως φυλακὴν καὶ τὴν τοῦ τείχους παρεφεδρεύοντας ἱππεῖς κατεστρατοπέδευσε, περὶ τετταράκοντα σταδίους ἀποσχὼν τῆς πόλεως, παρὰ τὸν ποταμὸν τὸν παρὰ μέν τισι Γαλαῖσον, παρὰ δὲ τοῖς πλείστοις προσαγορευόμενον Εὐρώταν, ὃς ἔχει τὴν ἐπωνυμίαν ταύτην ἀπὸ τῆς τοῦ παρὰ Λακεδαίμονα ῥέοντος Εὐρώτα. πολλὰ δὲ τοιαῦτα κατὰ τὴν χώραν καὶ κατὰ τὴν πόλιν ὑπάρχει τοῖς Ταραντίνοις διὰ τὸ καὶ τὴν ἀποικίαν καὶ τὴν συγγένειαν ὁμολογουμένην αὐτοῖς εἶναι πρὸς Λακεδαιμονίους. ταχὺ δὲ τοῦ τείχους λαμβάνοντας τὴν συντέλειαν διά τε τὴν τῶν Ταραντίνων σπουδὴν καὶ προθυμίαν καὶ τὴν τῶν Καρχηδονίων συνεργίαν, μετὰ ταῦτα διενοήθη καὶ τὴν ἄκραν ἐξελεῖν Ἀννίβας.", "st": "8.35"}, {"sp": "N", "t": "ἤδη δ’ ἐντελεῖς αὐτοῦ συνεσταμένου τὰς πρὸς τὴν πολιορκίαν παρασκευάς, παραπεσούσης ἐκ Μεταποντίου βοηθείας εἰς τὴν ἄκραν κατὰ θάλατταν, βραχύ τι ταῖς ψυχαῖς ἀναθαρρήσαντες οἱ Ῥωμαῖοι νυκτὸς ἐπέθεντο τοῖς ἔργοις, καὶ πάσας διέφθειραν τὰς τῶν ἔργων καὶ μηχανημάτων κατασκευάς. οὗ γενομένου τὸ μὲν πολιορκεῖν τὴν ἄκραν Ἀννίβας ἀπέγνω, τῆς δὲ τοῦ τείχους κατασκευῆς ἤδη τετελειωμένης, ἁθροίσας τοὺς Ταραντίνους ἀπεδείκνυε διότι κυριώτατόν ἐστι πρὸς τοὺς ἐνεστῶτας καιροὺς τὸ τῆς θαλάττης ἀντιλαμβάνεσθαι. κρατούσης γὰρ τῆς ἄκρας τῶν κατὰ τὸν εἴσπλουν τόπων, ὡς ἐπάνω προεῖπον, οἱ μὲν Ταραντῖνοι τὸ παράπαν οὐκ ἠδύναντο χρῆσθαι ταῖς ναυσὶν οὐδ’ ἐκπλεῖν ἐκ τοῦ λιμένος, τοῖς δὲ Ῥωμαίοις κατὰ θάλατταν ἀσφαλῶς παρεκομίζετο τὰ πρὸς τὴν χρείαν· οὗ συμβαίνοντος οὐδέποτε δυνατὸν ἦν βεβαίως ἐλευθερωθῆναι τὴν πόλιν. ἃ συνορῶν ὁ Ἀννίβας ἐδίδασκε τοὺς Ταραντίνους ὡς, ἐὰν ἀποκλεισθῶσι τῆς κατὰ θάλατταν ἐλπίδος οἱ τὴν ἄκραν τηροῦντες, παρὰ πόδας αὐτοὶ δι’ αὑτῶν εἴξαντες λείψουσι ταύτην καὶ παραδώσουσι τὸν τόπον. ὧν ἀκούοντες οἱ Ταραντῖνοι τοῖς μὲν λεγομένοις συγκατετίθεντο· ὅπως δ’ ἂν γένοιτο τοῦτο κατὰ τὸ παρόν, οὐδαμῶς ἐδύναντο συννοῆσαι, πλὴν εἰ παρὰ Καρχηδονίων ἐπιφανείη στόλος· τοῦτο δ’ ἦν κατὰ τοὺς τότε καιροὺς ἀδύνατον. διόπερ ἠδυνάτουν συμβαλεῖν ἐπὶ τί φερόμενος Ἀννίβας τοὺς περὶ τούτων πρὸς σφᾶς ποιεῖται λόγους. φήσαντος δ’ αὐτοῦ φανερὸν εἶναι χωρὶς Καρχηδονίων αὐτοὺς δι’ αὑτῶν ὅσον ἤδη κρατῆσαι τῆς θαλάττης, μᾶλλοι ἐκπλαγεῖς ἦσαν, οὐ δυνάμενοι τὴν ἐπίνοιαν αὐτοῦ συμβαλεῖν. ὁ δὲ συνεωρακὼς τὴν πλατεῖαν εὐδιακόσμητον οὖσαν τὴν ὑπάρχουσαν μὲν ἐντὸς τοῦ διατειχίσματος, φέρουσαν δὲ παρὰ τὸ διατείχισμ’ ἐκ τοῦ λιμένος εἰς τὴν ἔξω θάλατταν, ταύτῃ διενοεῖτο τὰς ναῦς ἐκ τοῦ λιμένος εἰς τὴν νότιον ὑπερβιβάζειν πλευράν. διόπερ ἅμα τῷ τὴν ἐπίνοιαν ἐπιδεῖξαι τοῖς Ταραντίνοις οὐ μόνον συγκατέθεντο τοῖς λεγομένοις, ἀλλὰ καὶ διαφερόντως ἐθαύμασαν τὸν ἄνδρα, καὶ διέλαβον ὡς οὐδὲν ἂν περιγένοιτο τῆς ἀγχινοίας τῆς ἐκείνου καὶ τόλμης. ταχὺ δὲ πορείων ὑποτρόχων κατασκευασθέντων, ἅμα τῷ λόγῳ τοὔργον εἰλήφει συντέλειαν, ἅτε προθυμίας καὶ πολυχειρίας ὁμοῦ τῇ προθέσει συνεργούσης. οἱ μὲν οὖν Ταραντῖνοι τοῦτον τὸν τρόπον ὑπερνεωλκήσαντες τὰς νῆας εἰς τὴν ἔξω θάλατταν, ἐπολιόρκουν ἀσφαλῶς τοὺς ἐκ τῆς ἄκρας, ἀφῃρημένοι τὰς ἔξωθεν αὐτῶν ἐπικουρίας. Ἀννίβας δὲ φυλακὴν ἀπολιπὼν τῆς πόλεως ἀνέζευξε μετὰ τῆς δυνάμεως, καὶ παρεγένετο τριταῖος ἐπὶ τὸν ἐξ ἀρχῆς χάρακα, καὶ τὸ λοιπὸν τοῦ χειμῶνος ἐνταῦθα διατρίβων ἔμενε κατὰ χώραν.", "st": "8.36"}, {"sp": "N", "t": "ἐξηριθμήσατο τοὺς δόμους· ἦν γὰρ ὁ πύργος ἐκ συννόμων λίθων ᾠκοδομημένος, ὥστε καὶ λίαν εὐσυλλόγιστον εἶναι τὴν ἀπὸ γῆς τῶν ἐπάλξεων ἀπόστασιν. μετὰ δέ τινας ἡμέρας αὐτομόλου διασαφήσαντος ὅτι θυσίαν ἄγουσι πάνδημον οἱ κατὰ τὴν πόλιν ἐφ’ ἡμέρας ἤδη τρεῖς Ἀρτέμιδι καὶ τοῖς μὲν σιτίοις λιτοῖς χρῶνται διὰ τὴν σπάνιν, τῷ δ’ οἴνῳ δαψιλεῖ, πολὺν μὲν Ἐπικύδους δεδωκότος πολὺν δὲ Συρακοσίων, τότε προσαναλαβὼν ὁ Μάρκος τὸ τεῖχος καθ’ ὃ μέρος ἦν ταπεινότερον καὶ νομίσας εἰκὸς εἶναι τοὺς ἀνθρώπους μεθύειν διὰ τὴν ἄνεσιν καὶ τὴν ἔνδειαν τῆς ξηρᾶς τροφῆς ἐπεβάλετο καταπειράζειν τῆς ἐλπίδος. ταχὺ δὲ κλιμάκων δυεῖν συντεθεισῶν εὐαρμόστων πρὸς τὸ τεῖχος, ἐγένετο περὶ τὰ συνεχῆ τῆς πράξεως καὶ τοῖς μὲν ἐπιτηδείοις πρὸς τὴν ἀνάβασιν καὶ τὸν ἐπιφανέστατον καὶ πρῶτον κίνδυνον ἐκοινολογεῖτο, περὶ τοῦ μέλλοντος μεγάλας ἐλπίδας αὐτοῖς ἐνδιδούς. τοὺς δὲ τούτοις ὑπουργήσοντας καὶ προσοίσοντας κλίμακας ἐξέλεξε διασαφῶν οὐδὲν πλὴν ἑτοίμους εἶναι πρὸς τὸ παραγγελλόμενον. πειθαρχησάντων δὲ κατὰ τὸ συνταχθὲν λαβὼν τὸν ἁρμόζοντα καιρὸν νυκτὸς ἤγειρε τοὺς πρώτους· προπέμψας δὲ τοὺς ἅμα ταῖς κλίμαξι μετὰ σημαίας καὶ χιλιάρχου καὶ προσαναμνήσας τῶν ἐσομένων δωρεῶν τοῖς ἀνδραγαθήσασι, μετὰ δὲ ταῦτα πᾶσαν τὴν δύναμιν ἐξεγείρας τοὺς μὲν πρώτους ἐν διαστήματι κατὰ σημαίαν ἐξαποστέλλει· γενομένων δὲ τούτων εἰς χιλίους βραχὺ διαλιπὼν αὐτὸς εἵπετο μετὰ τῆς ἄλλης στρατιᾶς. ἐπεὶ δ’ οἱ φέροντες τὰς κλίμακας ἔλαθον ἀσφαλῶς τῷ τείχει προσερείσαντες, ἐξ αὐτῆς ὥρμησαν ἀπροφασίστως οἱ πρὸς τὴν ἀνάβασιν ἀποτεταγμένοι. λαθόντων δὲ καὶ τούτων καὶ στάντων ἐπὶ τοῦ τείχους βεβαίως, οὐκέτι κατὰ τὴν ἐξ ἀρχῆς τάξιν, ἀλλὰ κατὰ δύναμιν ἅπαντες ἀνέθεον διὰ τῶν κλιμάκων. κατὰ μὲν οὖν τὰς ἀρχὰς ἐπιπορευόμενοι τὴν ἐφοδείαν ἔρημον εὕρισκον· οἱ γὰρ εἰς τοὺς πύργους ἡθροισμένοι διὰ τὴν θυσίαν οἱ μὲν ἀκμὴν ἔπινον, οἱ δ’ ἐκοιμῶντο πάλαι μεθυσκόμενοι. διὸ καὶ τοῖς μὲν πρώτοις καὶ τοῖς ἑξῆς ἐπιστάντες ἄφνω καὶ μεθ’ ἡσυχίας ἔλαθον τοὺς πλείστους αὐτῶν ἀποκτείναντες. ἐπειδὴ δὲ τοῖς Ἑξαπύλοις ἤγγιζον καταβαίνοντες, ἐνῳκοδομημένην τὴν πρώτην πυλίδα διεῖλον, δι’ ἧς τόν τε στρατηγὸν καὶ τὸ λοιπὸν ἐδέξαντο στράτευμα. οὕτω δὴ τὰς Συρακούσας εἷλον Ῥωμαῖοι. οὐδενὸς ἐπεγνωκότος τῶν πολιτῶν τὸ συμβαῖνον διὰ τὴν ἀπόστασιν, ἅτε μεγάλης οὔσης τῆς πόλεως. τοὺς δὲ Ῥωμαίους θαρρεῖν συνέβαινε, κρατοῦντας τοῦ περὶ τὰς Ἐπιπολὰς τόπου.", "st": "8.37"}, {"sp": "N", "t": "σὺν γὰρ τοῖς ἐπιδεδεμένοις φορτίοις τὰ κανθήλια λαβόντας ἐκ τῶν ὄπισθεν προθέσθαι πρὸ αὑτῶν ἐκέλευσε τοὺς πεζούς. οὗ γενομένου συνέβη παρὰ πάντας χάρακας ἀσφαλέστατον γενέσθαι τὸ πρόβλημα.", "st": "8.38"}, {"sp": "N", "t": "οὕτως οἱ πλείους τῶν ἀνθρώπων τὸ κουφότατον ἥκιστα φέρειν δύνανται, λέγω δὲ τὴν σιωπήν.", "st": "8.38"}, {"sp": "N", "t": "Ἄγκαρα, πόλις Ἰταλίας. τὸ ἐθνικὸν Ἀγκαράτης, ὡς Πολύβιος ὀγδόῃ. λοιπὸν τοῖς ἀδήλοις ἐλπίσι προσανέχων διὰ τὸ πρόδηλον τῆς τιμωρίας πᾶν ἔκρινεν ὑπομένειν.", "st": "8.38"}], []);})();
